        },
        [6100702] = {
          ContentEN = "A cheerful young man with a backpack walks up to the campfire and greets you loudly.",
          DialogueId = 6100702,
          GUID = "0F45C06C",
          NextDialogue = 6100703,
          RougeTalkActorType = 3,
          Subtitle = "A cheerful young man with a backpack walks up to the campfire and greets you loudly."
        },
        [6100703] = {
          ContentEN = "\"Don't mean to be blunt — but you're alive, right?\"",
          DialogueId = 6100703,
          GUID = "0F45C096",
          NextOptions = {
            [1] = 6100704,
            [2] = 6100711
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room307_Char01",
          Subtitle = "\"Don't mean to be blunt — but you're alive, right?\""
        },
        [6100704] = {
          ContentEN = "Nod to greet him",
          DialogueId = 6100704,
          GUID = "0F45C0C0",
          IsKeyOption = true,
          NextDialogue = 6100705,
          RougeTalkActorType = 2,
          Subtitle = "Nod to greet him"
        },
        [6100705] = {
          ContentEN = "\"Never thought I'd meet another living soul out here! Guess we're both the lucky ones, huh?\"",
          DialogueId = 6100705,
          GUID = "0F45C0EA",
          NextDialogue = 6100706,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room307_Char01",
          Subtitle = "\"Never thought I'd meet another living soul out here! Guess we're both the lucky ones, huh?\""
        },
        [6100706] = {
          ContentEN = "\"Dad and I wrote a little folk song when I was 16. Apparently, the Hall of Divine Judgment didn't appreciate our lyrics.\"\n\"I should've been executed like my poor dad — until lightning struck the executioner on the very day.\"",
          DialogueId = 6100706,
          GUID = "0F45C114",
          NextDialogue = 6100707,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room307_Char01",
          Subtitle = "\"Dad and I wrote a little folk song when I was 16. Apparently, the Hall of Divine Judgment didn't appreciate our lyrics.\"\n\"I should've been executed like my poor dad — until lightning struck the executioner on the very day.\""
        },
        [6100707] = {
          ContentEN = "\"At 20, I joined a band of traveling merchants. We were ambushed in a forest up in the North — tied up and abandoned in a cavern.\"\n\"I watched my companions starve to death one by one until dawn on the seventh day when a snuffling boar rooted me awake. A girl gave me some food. Pretty sure I was looking at an angel.\"",
          DialogueId = 6100707,
          GUID = "0F45C13E",
          NextDialogue = 6100708,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room307_Char01",
          Subtitle = "\"At 20, I joined a band of traveling merchants. We were ambushed in a forest up in the North — tied up and abandoned in a cavern.\"\n\"I watched my companions starve to death one by one until dawn on the seventh day when a snuffling boar rooted me awake. A girl gave me some food. Pretty sure I was looking at an angel.\""
        },
        [6100708] = {
          ContentEN = [[
"Later I traveled with a group of Knights into the abyss as a merchant. Their lights died one after another. An elder Knight tripped and found his sword buried in his own neck. I was the only one who survived."
"That was when I knew the Goddess of Fate had my back. That she would bless me with boundless luck and happiness."]],
          DialogueId = 6100708,
          GUID = "0F45C168",
          NextDialogue = 6100709,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room307_Char01",
          Subtitle = [[
"Later I traveled with a group of Knights into the abyss as a merchant. Their lights died one after another. An elder Knight tripped and found his sword buried in his own neck. I was the only one who survived."
"That was when I knew the Goddess of Fate had my back. That she would bless me with boundless luck and happiness."]]
        },
        [6100709] = {
          ContentEN = [[
"If she led me here, there must be something truly one-of-a-kind waiting in the depths. I won't keep it waiting."
He puts on his heavy backpack.]],
          DialogueId = 6100709,
          GUID = "0F45C192",
          NextDialogue = 6100710,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room307_Char01",
          Subtitle = [[
"If she led me here, there must be something truly one-of-a-kind waiting in the depths. I won't keep it waiting."
He puts on his heavy backpack.]]
        },
        [6100710] = {
          ContentEN = [[
"Listen, my friend! If she spared you as well, then destiny has something wonderful in store just for you!"
He laughs, pumping his fists.
"To our good fortune!"]],
          DialogueId = 6100710,
          GUID = "0F45C1BC",
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
