        },
        [6100808] = {
          ContentEN = "\"You are a grotesque creature.\"",
          DialogueId = 6100808,
          GUID = "0F45D1D0",
          IsKeyOption = true,
          NextDialogue = 6100809,
          RougeTalkActorType = 2,
          Subtitle = "\"You are a grotesque creature.\""
        },
        [6100809] = {
