        [6100901] = {
          ContentEN = "\"Greetings, wandering stranger.\"",
          DialogueId = 6100901,
          GUID = "0F45E112",
          NextDialogue = 6100902,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room309_Char01",
          Subtitle = "\"Greetings, wandering stranger.\""
        },
        [6100902] = {
          ContentEN = "A finely-dressed young man pauses in the flickering firelight, offering you a graceful bow.",
          DialogueId = 6100902,
          GUID = "0F45E13C",
          NextDialogue = 6100903,
          RougeTalkActorType = 3,
          Subtitle = "A finely-dressed young man pauses in the flickering firelight, offering you a graceful bow."
        },
        [6100903] = {
          ContentEN = "\"I'm seeking a lady with crimson eyes. Have you glimpsed her passing?\"",
          DialogueId = 6100903,
          GUID = "0F45E166",
          NextDialogue = 6100904,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room309_Char01",
          Subtitle = "\"I'm seeking a lady with crimson eyes. Have you glimpsed her passing?\""
        },
        [6100904] = {
          ContentEN = "\"She sings with such grace, even the nightingale falls silent in envy.\"\n\"Her golden hair flows like liquid sunlight, brighter than spring marigolds in bloom.\"\n\"She wears a gown of regal elegance, embroidered with jewels that shimmer like the night sky.\"\n\"And around her neck rests my gift — a crimson pendant, deep and mysterious as her gaze.\"",
          DialogueId = 6100904,
          GUID = "0F45E190",
          NextDialogue = 6100905,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room309_Char01",
          Subtitle = "\"She sings with such grace, even the nightingale falls silent in envy.\"\n\"Her golden hair flows like liquid sunlight, brighter than spring marigolds in bloom.\"\n\"She wears a gown of regal elegance, embroidered with jewels that shimmer like the night sky.\"\n\"And around her neck rests my gift — a crimson pendant, deep and mysterious as her gaze.\""
        },
        [6100905] = {
          ContentEN = "You haven't seen a lady like that.",
          DialogueId = 6100905,
          GUID = "0F45E1BA",
          NextDialogue = 6100906,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004,
          Subtitle = "You haven't seen a lady like that."
        },
        [6100906] = {
          ContentEN = "\"I see…\"\nHis gaze falters briefly—just a moment — before composure returns.\n\"That's fine. My search continues.\"",
          DialogueId = 6100906,
          GUID = "0F45E1E4",
          NextDialogue = 6100907,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room309_Char01",
          Subtitle = "\"I see…\"\nHis gaze falters briefly—just a moment — before composure returns.\n\"That's fine. My search continues.\""
        },
        [6100907] = {
          ContentEN = "The young man settles by the campfire, flames dancing in his untainted eyes.",
          DialogueId = 6100907,
          GUID = "0F45E20E",
          NextDialogue = 6100908,
          RougeTalkActorType = 3,
          Subtitle = "The young man settles by the campfire, flames dancing in his untainted eyes."
        },
        [6100908] = {
          ContentEN = "\"We were betrothed — she to be my bride upon her coming of age. Yet the gods marked her: a sacred sigil bloomed upon her brow. On the eve of her fourteenth birthday, their envoys spirited her away.\"\n\"Her parting words begged me to move on. But my vow stands eternal — this life belongs to her alone.\"\n\"When I find her, I'll bring her back to the world. The God of Full Moon, the patron of lovers, will surely bless our reunion.\"",
          DialogueId = 6100908,
          GUID = "0F45E238",
          NextOptions = {
            [1] = 6100909,
            [2] = 6100911
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room309_Char01",
          Subtitle = "\"We were betrothed — she to be my bride upon her coming of age. Yet the gods marked her: a sacred sigil bloomed upon her brow. On the eve of her fourteenth birthday, their envoys spirited her away.\"\n\"Her parting words begged me to move on. But my vow stands eternal — this life belongs to her alone.\"\n\"When I find her, I'll bring her back to the world. The God of Full Moon, the patron of lovers, will surely bless our reunion.\""
        },
        [6100909] = {
          ContentEN = "Wish him luck in finding his lover.",
          DialogueId = 6100909,
          GUID = "0F45E262",
          IsKeyOption = true,
          NextDialogue = 6100910,
          RougeTalkActorType = 2,
          Subtitle = "Wish him luck in finding his lover."
        },
        [6100910] = {
          ContentEN = "\"My gratitude, kind traveler.\"\n\"Please accept this humble gift — may fortune smile upon your own desires.\"",
          DialogueId = 6100910,
          GUID = "0F45E28C",
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room309_Char01",
          Subtitle = "\"My gratitude, kind traveler.\"\n\"Please accept this humble gift — may fortune smile upon your own desires.\""
        },
        [6100911] = {
          ContentEN = "\"What if the gods disapprove?\"",
          DialogueId = 6100911,
          GUID = "0F45E2B6",
          IsKeyOption = true,
          NextDialogue = 6100912,
          RougeTalkActorType = 2,
          Subtitle = "\"What if the gods disapprove?\""
        },
        [6100912] = {
          ContentEN = "A faint smile touches his lips.\n\"Then I shall surrender this flesh to the Sacred Lake — that my soul may dwell eternally where hers resides.\"",
          DialogueId = 6100912,
          GUID = "0F45E2E0",
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room309_Char01",
          Subtitle = "A faint smile touches his lips.\n\"Then I shall surrender this flesh to the Sacred Lake — that my soul may dwell eternally where hers resides.\""
        },
