        },
        [6101201] = {
          ContentEN = "A middle-aged woman settles by the campfire, her grim expression untouched by the flickering light.",
          DialogueId = 6101201,
          GUID = "0F46124A",
          NextDialogue = 6101202,
          RougeTalkActorType = 3,
          Subtitle = "A middle-aged woman settles by the campfire, her grim expression untouched by the flickering light."
        },
        [6101202] = {
          ContentEN = "\"Greetings, stranger. Pardon my asking, what is this place?\"",
          DialogueId = 6101202,
          GUID = "0F461274",
          NextDialogue = 6101203,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room312_Char01",
          Subtitle = "\"Greetings, stranger. Pardon my asking, what is this place?\""
        },
        [6101203] = {
          ContentEN = "Tell her",
          DialogueId = 6101203,
          GUID = "0F46129E",
          NextDialogue = 6101204,
          RougeTalkActorType = 3,
          Subtitle = "Tell her"
        },
        [6101204] = {
          ContentEN = "\"Sacred lake…? Abyss…?\" Her voice wavers with confusion. \"These words mean nothing to me…\"\nShe stares at her weathered hands. \"I can't remember why I'm here.\"",
          DialogueId = 6101204,
          GUID = "0F4612C8",
          NextOptions = {
            [1] = 6101205,
            [2] = 6101207
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room312_Char01",
          Subtitle = "\"Sacred lake…? Abyss…?\" Her voice wavers with confusion. \"These words mean nothing to me…\"\nShe stares at her weathered hands. \"I can't remember why I'm here.\""
        },
        [6101205] = {
          ContentEN = "Tell her about the history of the Sacred Lake",
          DialogueId = 6101205,
          GUID = "0F4612F2",
          IsKeyOption = true,
          NextDialogue = 6101206,
          RougeTalkActorType = 2,
          Subtitle = "Tell her about the history of the Sacred Lake"
        },
        [6101206] = {
          ContentEN = "\"People bearing sacred sigils… will be brought here…?\"\n\"Ah… I remember now. My child is here. The sacred sigil appeared at the corner of her eye — like a butterfly about to take flight.\"",
          DialogueId = 6101206,
          GUID = "0F46131C",
          NextDialogue = 6101210,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room312_Char01",
          Subtitle = "\"People bearing sacred sigils… will be brought here…?\"\n\"Ah… I remember now. My child is here. The sacred sigil appeared at the corner of her eye — like a butterfly about to take flight.\""
        },
        [6101207] = {
          ContentEN = "Suggest she check her belongings",
          DialogueId = 6101207,
          GUID = "0F461346",
          IsKeyOption = true,
          NextDialogue = 6101208,
          RougeTalkActorType = 2,
          Subtitle = "Suggest she check her belongings"
        },
        [6101208] = {
          ContentEN = [[
"Good idea."
She reaches into her pocket, pulling out a silver brooch.]],
          DialogueId = 6101208,
          GUID = "0F461370",
          NextDialogue = 6101209,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room312_Char01",
          Subtitle = [[
"Good idea."
She reaches into her pocket, pulling out a silver brooch.]]
        },
        [6101209] = {
          ContentEN = "\"Ah… I remember now.\" She gently buffs the brooch with her sleeve. \"This… this is meant for my child.\"",
          DialogueId = 6101209,
          GUID = "0F46139A",
          NextDialogue = 6101210,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room312_Char01",
          Subtitle = "\"Ah… I remember now.\" She gently buffs the brooch with her sleeve. \"This… this is meant for my child.\""
        },
        [6101210] = {
          ContentEN = "She looks up. The firelight now burns clearly in her eyes.",
          DialogueId = 6101210,
          GUID = "0F4613C4",
          NextDialogue = 6101211,
          RougeTalkActorType = 3,
          Subtitle = "She looks up. The firelight now burns clearly in her eyes."
        },
        [6101211] = {
          ContentEN = "\"I came for my child.\"\n\"They took her while she slept when I was not home. My girl's always feared strangers… If she wakes to unfamiliar faces—\"\n\"I need to be with her… Yes. That's why I'm here.\"",
          DialogueId = 6101211,
          GUID = "0F4613EE",
          NextDialogue = 6101212,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room312_Char01",
          Subtitle = "\"I came for my child.\"\n\"They took her while she slept when I was not home. My girl's always feared strangers… If she wakes to unfamiliar faces—\"\n\"I need to be with her… Yes. That's why I'm here.\""
        },
        [6101212] = {
          ContentEN = "\"When did they take her?\"",
          DialogueId = 6101212,
          GUID = "0F461418",
          NextDialogue = 6101213,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004,
          Subtitle = "\"When did they take her?\""
        },
        [6101213] = {
          ContentEN = "\"Ten days ago… no, ten months… or is it ten years… Ah… I can't recall.\"",
          DialogueId = 6101213,
          GUID = "0F461442",
          NextDialogue = 6101214,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room312_Char01",
          Subtitle = "\"Ten days ago… no, ten months… or is it ten years… Ah… I can't recall.\""
        },
        [6101214] = {
          ContentEN = [[
Her voice trails off. Now she sits transfixed, a statue with unblinking eyes and a seemingly unmoving chest.
Her mind has gone to a place where your voice can't reach.]],
          DialogueId = 6101214,
          GUID = "0F46146C",
          RougeTalkActorType = 3,
          Subtitle = [[
