        },
        [6101301] = {
          ContentEN = "\"Crackle—\"\nThe flames leap higher in an instant.\nYou see a golden-haired girl standing before the fire, her skirt lifted to cradle a handful of golden rocks. She drops them one by one into the flames.",
          DialogueId = 6101301,
          GUID = "0F4622B2",
          NextDialogue = 6101302,
          RougeTalkActorType = 3,
          Subtitle = "\"Crackle—\"\nThe flames leap higher in an instant.\nYou see a golden-haired girl standing before the fire, her skirt lifted to cradle a handful of golden rocks. She drops them one by one into the flames."
        },
        [6101302] = {
          ContentEN = "The flames leap higher and higher, surging with the wild abandon of a forest greeting its first spring.",
          DialogueId = 6101302,
          GUID = "0F4622DC",
          NextOptions = {
            [1] = 6101303,
            [2] = 6101305
          },
          RougeTalkActorType = 3,
          Subtitle = "The flames leap higher and higher, surging with the wild abandon of a forest greeting its first spring."
        },
        [6101303] = {
          ContentEN = "Admire the dancing flames",
          DialogueId = 6101303,
          GUID = "0F462306",
          IsKeyOption = true,
          NextDialogue = 6101304,
          RougeTalkActorType = 2,
          Subtitle = "Admire the dancing flames"
        },
        [6101304] = {
          ContentEN = "\"I know!\" Her voice burns with passion, \"How wonderful that we share the same view!\"",
          DialogueId = 6101304,
          GUID = "0F462330",
          NextDialogue = 6101307,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room313_Char01",
          Subtitle = "\"I know!\" Her voice burns with passion, \"How wonderful that we share the same view!\""
        },
        [6101305] = {
          ContentEN = "Ask the girl where she got the rocks",
          DialogueId = 6101305,
          GUID = "0F46235A",
          IsKeyOption = true,
          NextDialogue = 6101306,
          RougeTalkActorType = 2,
          Subtitle = "Ask the girl where she got the rocks"
        },
        [6101306] = {
          ContentEN = "\"I picked these up around here,\" she says. \"I think they're some kind of fire-magic crystal.\"",
          DialogueId = 6101306,
          GUID = "0F462384",
          NextDialogue = 6101307,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room313_Char01",
          Subtitle = "\"I picked these up around here,\" she says. \"I think they're some kind of fire-magic crystal.\""
        },
        [6101307] = {
          ContentEN = "The girl keeps tossing the rocks. Maybe it's your imagination, but the flames seem to drift closer, gently caressing her golden hair.",
          DialogueId = 6101307,
          GUID = "0F4623AE",
          NextDialogue = 6101308,
          RougeTalkActorType = 3,
          Subtitle = "The girl keeps tossing the rocks. Maybe it's your imagination, but the flames seem to drift closer, gently caressing her golden hair."
        },
        [6101308] = {
          ContentEN = [[
"Come morning, the flames will be as they were, and these rocks will scatter around here once more."
"So every day, I gather and toss them into the flames again. Exactly one hundred forty-six of them."]],
          DialogueId = 6101308,
          GUID = "0F4623D8",
          NextDialogue = 6101309,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room313_Char01",
          Subtitle = [[
"Come morning, the flames will be as they were, and these rocks will scatter around here once more."
"So every day, I gather and toss them into the flames again. Exactly one hundred forty-six of them."]]
        },
        [6101309] = {
          ContentEN = "\"What's the point of this then?\"",
          DialogueId = 6101309,
          GUID = "0F462402",
          NextDialogue = 6101310,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004,
          Subtitle = "\"What's the point of this then?\""
        },
        [6101310] = {
          ContentEN = "The girl tilts her head, blinking with an innocent smile.",
          DialogueId = 6101310,
          GUID = "0F46242C",
          NextDialogue = 6101311,
          RougeTalkActorType = 3,
          Subtitle = "The girl tilts her head, blinking with an innocent smile."
        },
        [6101311] = {
          ContentEN = "\"No, I love fire,\" she says. \"I love its crackling sound, its dancing light.\"\n\"You see, space twists here. You close your eyes by the campfire and wake up at the bottom of the lake.\"\n\"But these little rocks are different — no matter how the world shifts, they always return. Just knowing I'll find them tomorrow lets me sleep in peace.\"",
          DialogueId = 6101311,
          GUID = "0F462456",
          NextDialogue = 6101312,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room313_Char01",
          Subtitle = "\"No, I love fire,\" she says. \"I love its crackling sound, its dancing light.\"\n\"You see, space twists here. You close your eyes by the campfire and wake up at the bottom of the lake.\"\n\"But these little rocks are different — no matter how the world shifts, they always return. Just knowing I'll find them tomorrow lets me sleep in peace.\""
        },
        [6101312] = {
          ContentEN = "\"Certainty comforts me.\"",
          DialogueId = 6101312,
          GUID = "0F462480",
          NextDialogue = 6101313,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room313_Char01",
          Subtitle = "\"Certainty comforts me.\""
        },
        [6101313] = {
