        [6101404] = {
          ContentEN = "\"…Thank you for the kindness, kid. But my body's past eating.\"\n\"The black tide dragged me under. All the bread in the world couldn't save me now.\"\n\"You remind me of a little girl in Elysium… A child as kind-hearted as you.\"",
          DialogueId = 6101404,
          GUID = "0F463398",
          NextDialogue = 6101405,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room314_Char01",
          Subtitle = "\"…Thank you for the kindness, kid. But my body's past eating.\"\n\"The black tide dragged me under. All the bread in the world couldn't save me now.\"\n\"You remind me of a little girl in Elysium… A child as kind-hearted as you.\""
        },
        [6101405] = {
          ContentEN = "\"She had golden locks, riding a giant pink boar. When I was starving on the streets, she offered me a piece of bread…\"\n\"But my pride ran too deep. I refused the Elysian Church's charity and spat venom at her kindness.\"",
          DialogueId = 6101405,
          GUID = "0F4633C2",
          NextDialogue = 6101406,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room314_Char01",
          Subtitle = "\"She had golden locks, riding a giant pink boar. When I was starving on the streets, she offered me a piece of bread…\"\n\"But my pride ran too deep. I refused the Elysian Church's charity and spat venom at her kindness.\""
        },
        [6101406] = {
          ContentEN = "\"Now, looking back… I realise she might have been the only one who truly cared.\"\n\"Faith, race, birth… People use these things to embellish themselves… But no title can outshine the radiance of genuine kindness…\"",
          DialogueId = 6101406,
          GUID = "0F4633EC",
          NextDialogue = 6101407,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room314_Char01",
          Subtitle = "\"Now, looking back… I realise she might have been the only one who truly cared.\"\n\"Faith, race, birth… People use these things to embellish themselves… But no title can outshine the radiance of genuine kindness…\""
        },
