        },
        [6200412] = {
          ContentEN = "\"A traveler…?\" The young Knight's expression flickers with familiar confusion, just like last time. \"But this is Elysium's sacred ground… How did you get in?\"",
          DialogueId = 6200412,
          GUID = "0F85A718",
          NextOptions = {
            [1] = 6200413
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char02",
          Subtitle = "\"A traveler…?\" The young Knight's expression flickers with familiar confusion, just like last time. \"But this is Elysium's sacred ground… How did you get in?\""
        },
        [6200413] = {
          ContentEN = "I have my reasons — and a purpose to fulfil. Just like you.",
          DialogueId = 6200413,
          GUID = "0F85A742",
          NextDialogue = 6200414,
          RougeTalkActorType = 2,
          Subtitle = "I have my reasons — and a purpose to fulfil. Just like you."
        },
        [6200414] = {
          ContentEN = "\"Hmm…?\"",
          DialogueId = 6200414,
          GUID = "0F85A76C",
          NextDialogue = 6200415,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char03",
          Subtitle = "\"Hmm…?\""
        },
        [6200415] = {
          ContentEN = "This time, the cloaked Sorceress finally shows a flicker of interest in you.\nShe lifts her head. You finally see her eyes — dark, doubtful, searching, like bubbles surfacing in shadowed waters.",
          DialogueId = 6200415,
          GUID = "0F85A796",
          NextDialogue = 6200416,
          RougeTalkActorType = 3,
          Subtitle = "This time, the cloaked Sorceress finally shows a flicker of interest in you.\nShe lifts her head. You finally see her eyes — dark, doubtful, searching, like bubbles surfacing in shadowed waters."
        },
        [6200416] = {
          ContentEN = "\"It sounds like you know truths about this abyss — truths we've yet to uncover.\"",
          DialogueId = 6200416,
          GUID = "0F85A7C0",
          NextDialogue = 6200417,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char03",
          Subtitle = "\"It sounds like you know truths about this abyss — truths we've yet to uncover.\""
        },
        [6200417] = {
          ContentEN = "\"Calista…! Only heretics speak such blasphemy! This is sacred ground, our Sacred Lake!\"",
          DialogueId = 6200417,
          GUID = "0F85A7EA",
          NextDialogue = 6200418,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char04",
          Subtitle = "\"Calista…! Only heretics speak such blasphemy! This is sacred ground, our Sacred Lake!\""
        },
        [6200418] = {
          ContentEN = "Calista ignores his rebuke, her gaze steady on you, waiting for an answer.",
          DialogueId = 6200418,
          GUID = "0F85A814",
          NextDialogue = 6200419,
          RougeTalkActorType = 3,
          Subtitle = "Calista ignores his rebuke, her gaze steady on you, waiting for an answer."
        },
        [6200419] = {
          ContentEN = "What will you say? What can you say?",
          DialogueId = 6200419,
          GUID = "0F85A83E",
          NextDialogue = 6200420,
          RougeTalkActorType = 3,
          Subtitle = "What will you say? What can you say?"
        },
        [6200420] = {
          ContentEN = "Tell them to turn back now? You know their faith forbids it.\nFaith — such a heavy word. It holds more weight than a stranger's warning or the plea of a face grown unfamiliar.",
          DialogueId = 6200420,
          GUID = "0F85A868",
          NextDialogue = 6200421,
          RougeTalkActorType = 3,
          Subtitle = "Tell them to turn back now? You know their faith forbids it.\nFaith — such a heavy word. It holds more weight than a stranger's warning or the plea of a face grown unfamiliar."
        },
        [6200421] = {
          ContentEN = "For those raised in faith's radiance, unwanted truths burn like staring at the sun — leaving only daylight's cruel tattoo upon the soul.",
          DialogueId = 6200421,
          GUID = "0F85A892",
          NextDialogue = 6200422,
          RougeTalkActorType = 3,
          Subtitle = "For those raised in faith's radiance, unwanted truths burn like staring at the sun — leaving only daylight's cruel tattoo upon the soul."
        },
        [6200422] = {
          ContentEN = "You shake your head, avoiding her gaze.",
          DialogueId = 6200422,
          GUID = "0F85A8BC",
          NextOptions = {
            [1] = 6200423
          },
          RougeTalkActorType = 3,
          Subtitle = "You shake your head, avoiding her gaze."
        },
        [6200423] = {
          ContentEN = "It's easy to get lost in the abyss. Stay close to your friends, Cathy.",
          DialogueId = 6200423,
          GUID = "0F85A8E6",
          NextDialogue = 6200424,
          RougeTalkActorType = 2,
          Subtitle = "It's easy to get lost in the abyss. Stay close to your friends, Cathy."
        },
        [6200424] = {
          ContentEN = "\"Huh? Why single me out?\"",
          DialogueId = 6200424,
          GUID = "0F85A910",
          NextDialogue = 6200425,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char01",
          Subtitle = "\"Huh? Why single me out?\""
        },
        [6200425] = {
          ContentEN = "\"Means you should reflect. Even strangers can see you're the most restless one.\"",
          DialogueId = 6200425,
          GUID = "0F85A93A",
          NextDialogue = 6200426,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char02",
          Subtitle = "\"Means you should reflect. Even strangers can see you're the most restless one.\""
        },
        [6200426] = {
          ContentEN = "\"As if! I'd find you all in no time if we got separated.\" The girl pouts.",
          DialogueId = 6200426,
          GUID = "0F85A964",
          NextOptions = {
            [1] = 6200427
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char01",
          Subtitle = "\"As if! I'd find you all in no time if we got separated.\" The girl pouts."
        },
        [6200427] = {
          ContentEN = "Next time might be too late.",
          DialogueId = 6200427,
          GUID = "0F85A98E",
          IsKeyOption = true,
          NextDialogue = 6200428,
          RougeTalkActorType = 2,
          Subtitle = "Next time might be too late."
        },
        [6200428] = {
          ContentEN = "Cathy freezes, caught off guard by your grave tone.",
          DialogueId = 6200428,
          GUID = "0F85A9B8",
          NextDialogue = 6200429,
          RougeTalkActorType = 3,
          Subtitle = "Cathy freezes, caught off guard by your grave tone."
        },
        [6200429] = {
          ContentEN = "Flynn steps forward — a true Knight of Elysium indeed. For a noble knight, piety alone is not enough; prudence too must be his virtue. He understands the delicate balance of curiosity — enough to gather information, yet not so much as to invite calamity. Like when you find a locked door in the sacred hall left slightly ajar, the wisest choice is to pause, turn away, and pretend you never saw it.",
          DialogueId = 6200429,
          GUID = "0F85A9E2",
          NextDialogue = 6200430,
          RougeTalkActorType = 3,
          Subtitle = "Flynn steps forward — a true Knight of Elysium indeed. For a noble knight, piety alone is not enough; prudence too must be his virtue. He understands the delicate balance of curiosity — enough to gather information, yet not so much as to invite calamity. Like when you find a locked door in the sacred hall left slightly ajar, the wisest choice is to pause, turn away, and pretend you never saw it."
        },
        [6200430] = {
          ContentEN = "\"Though we don't know your true identity, you're clearly here for a reason. Forgive us — duty calls us elsewhere.\" He bows solemnly. \"May the God of Full Moon bless your journey.\"",
          DialogueId = 6200430,
          GUID = "0F85AA0C",
          NextDialogue = 6200431,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char02",
          Subtitle = "\"Though we don't know your true identity, you're clearly here for a reason. Forgive us — duty calls us elsewhere.\" He bows solemnly. \"May the God of Full Moon bless your journey.\""
        },
        [6200431] = {
          ContentEN = "The Knights depart together, leaving only endless mist before you.",
          DialogueId = 6200431,
          GUID = "0F85AA36",
          RougeTalkActorType = 3,
          Subtitle = "The Knights depart together, leaving only endless mist before you."
        },
        [6200501] = {
          ContentEN = "Endless battles drain your strength.\nThe last ember slips through your fingers — direction lost in the void.",
          DialogueId = 6200501,
          GUID = "0F85B5B2",
          NextDialogue = 6200502,
          RougeTalkActorType = 3,
          Subtitle = "Endless battles drain your strength.\nThe last ember slips through your fingers — direction lost in the void."
        },
        [6200502] = {
          ContentEN = [[
The lantern falls to the ground, its crystal shattering with a sound like blades cutting through the silent darkness.
Splintered shadows rush toward you from every direction, corroding your flesh and biting at your nerves.]],
          DialogueId = 6200502,
          GUID = "0F85B5DC",
          NextDialogue = 6200503,
          RougeTalkActorType = 3,
          Subtitle = [[
