        },
        [6200902] = {
          ContentEN = "You're still here.",
          DialogueId = 6200902,
          GUID = "0F85F77C",
          NextDialogue = 6200903,
          RougeTalkActorType = 2,
          Subtitle = "You're still here."
        },
        [6200903] = {
          ContentEN = [[
"I am."
The Merchant's voice is calm, ever gentle.
"Until I can aid you in ending this darkness, I shall remain."]],
          DialogueId = 6200903,
          GUID = "0F85F7A6",
          NextOptions = {
            [1] = 6200904
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = [[
"I am."
The Merchant's voice is calm, ever gentle.
"Until I can aid you in ending this darkness, I shall remain."]]
        },
        [6200904] = {
          ContentEN = "But no one else remembers me.",
          DialogueId = 6200904,
          GUID = "0F85F7D0",
          NextDialogue = 6200905,
          RougeTalkActorType = 2,
          Subtitle = "But no one else remembers me."
        },
        [6200905] = {
          ContentEN = "\"Those... ghosts of the Abyss, and the few humans who remain — when I turn the dial and return to the past, they forget me, as though we had never met, never spoken.\"\n\"Even if I manage to save someone, most still perish the next time.\"\n\"Though I meet many along the way... in the end, I remain alone.\"",
          DialogueId = 6200905,
          GUID = "0F85F7FA",
          NextDialogue = 6200906,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004,
          Subtitle = "\"Those... ghosts of the Abyss, and the few humans who remain — when I turn the dial and return to the past, they forget me, as though we had never met, never spoken.\"\n\"Even if I manage to save someone, most still perish the next time.\"\n\"Though I meet many along the way... in the end, I remain alone.\""
        },
        [6200906] = {
          ContentEN = [[
"Yes. The Abyss moves like the tide, ever returning all things to yesterday."
"But you are different. As the owner of the dial, you now stand beyond the current of time."
He lets out a quiet sigh.]],
          DialogueId = 6200906,
          GUID = "0F85F824",
          NextDialogue = 6200907,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = [[
"Yes. The Abyss moves like the tide, ever returning all things to yesterday."
"But you are different. As the owner of the dial, you now stand beyond the current of time."
He lets out a quiet sigh.]]
        },
        [6200907] = {
          ContentEN = "\"Here in the Abyss, time bends to your will. You alone are <H>eternal</> — wielding a sceptre once meant only for the gods.\"\n\"Yet that sceptre leads not to a throne, but to a prison. It binds you to witness, again and again, as all things are torn from you — never to be held.\"\nThere's the faintest quiver in his otherwise calm voice.\n\"And still... it is the only way to defy the Abyss.\"",
          DialogueId = 6200907,
          GUID = "0F85F84E",
          NextOptions = {
            [1] = 6200908
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = "\"Here in the Abyss, time bends to your will. You alone are eternal — wielding a sceptre once meant only for the gods.\"\n\"Yet that sceptre leads not to a throne, but to a prison. It binds you to witness, again and again, as all things are torn from you — never to be held.\"\nThere's the faintest quiver in his otherwise calm voice.\n\"And still... it is the only way to defy the Abyss.\""
        },
        [6200908] = {
          ContentEN = "I must be on my way.",
          DialogueId = 6200908,
          GUID = "0F85F878",
          IsKeyOption = true,
          NextDialogue = 6200909,
          RougeTalkActorType = 2,
          Subtitle = "I must be on my way."
        },
        [6200909] = {
          ContentEN = "\"Farewell, lonely traveller,\" he says. \"May the flame of your Lantern shine ever unceasing upon your path.\"",
          DialogueId = 6200909,
          GUID = "0F85F8A2",
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = "\"Farewell, lonely traveller,\" he says. \"May the flame of your Lantern shine ever unceasing upon your path.\""
        },
        [6201001] = {
          ContentEN = "Once again, you find a fleeting moment of respite.\nNo Abyssoids give chase. No wailing souls. At last — a place of safety.\nYou sink slowly to the ground, resting against a broken wall.",
          DialogueId = 6201001,
          GUID = "0F8607BA",
          NextOptions = {
            [1] = 6201002
          },
          RougeTalkActorType = 3,
          Subtitle = "Once again, you find a fleeting moment of respite.\nNo Abyssoids give chase. No wailing souls. At last — a place of safety.\nYou sink slowly to the ground, resting against a broken wall."
        },
        [6201002] = {
          ContentEN = "I'm tired.",
          DialogueId = 6201002,
          GUID = "0F8607E4",
          NextDialogue = 6201003,
          RougeTalkActorType = 2,
          Subtitle = "I'm tired."
        },
        [6201003] = {
          ContentEN = [[
"Again and again I push forward. Again and again I start over."
"I know this battle is mine... but I don't know how much longer it will last."]],
          DialogueId = 6201003,
          GUID = "0F86080E",
          NextDialogue = 6201004,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004,
          Subtitle = [[
"Again and again I push forward. Again and again I start over."
"I know this battle is mine... but I don't know how much longer it will last."]]
        },
        [6201004] = {
          ContentEN = "\"When the divine blessing — <H>Pure Glazeystal</> — is gathered once more, and the Lantern restored, a miracle shall be revealed.\"\n\"Then shall you bear a light strong enough to cleave this darkness.\"",
          DialogueId = 6201004,
          GUID = "0F860838",
          NextOptions = {
            [1] = 6201005
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = "\"When the divine blessing — Pure Glazeystal — is gathered once more, and the Lantern restored, a miracle shall be revealed.\"\n\"Then shall you bear a light strong enough to cleave this darkness.\""
        },
        [6201005] = {
          ContentEN = "That's not what I meant.",
          DialogueId = 6201005,
          GUID = "0F860862",
          NextDialogue = 6201006,
          RougeTalkActorType = 2,
          Subtitle = "That's not what I meant."
        },
        [6201006] = {
          ContentEN = "\"I don't even know how long I've wandered here — ten years? Twenty? Or longer still? All I can count is how many times I've turned the dial.\"\n\"And still the Lantern's glow remains so faint... as if all I've done were in vain.\"\n\"What if it's never made whole — not until I'm already gone? Then everything I've done... what would it all be for?\"\n\"Would it all just be some pathetic joke?\"",
          DialogueId = 6201006,
          GUID = "0F86088C",
          NextDialogue = 6201007,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004,
          Subtitle = "\"I don't even know how long I've wandered here — ten years? Twenty? Or longer still? All I can count is how many times I've turned the dial.\"\n\"And still the Lantern's glow remains so faint... as if all I've done were in vain.\"\n\"What if it's never made whole — not until I'm already gone? Then everything I've done... what would it all be for?\"\n\"Would it all just be some pathetic joke?\""
        },
        [6201007] = {
          ContentEN = [[
"Yes."
He does not deny it. The starkness of the answer catches you off guard.]],
          DialogueId = 6201007,
          GUID = "0F8608B6",
          NextDialogue = 6201008,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = [[
"Yes."
He does not deny it. The starkness of the answer catches you off guard.]]
        },
        [6201008] = {
          ContentEN = "\"I have seen you raise your blade, again and again,\ndriving back the Abyssoids — just as I have seen thousands of masons hewing stone, laying the foundations of a temple.\"\n\"I have seen a girl toss pebbles into the flame, again and again — just as I have seen thousands of farmers scatter seed, year after year.\"\n\"All effort, all struggle... only for the cycle to begin anew.\nNot just you and I — but the souls of the Abyss, and the living above — all are bound within this endless tragedy.\"\n\"And if that burden proves too great for you to carry... you may always lay it down. And then — it would end.\"",
          DialogueId = 6201008,
          GUID = "0F8608E0",
          NextOptions = {
            [1] = 6201009
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = "\"I have seen you raise your blade, again and again,\ndriving back the Abyssoids — just as I have seen thousands of masons hewing stone, laying the foundations of a temple.\"\n\"I have seen a girl toss pebbles into the flame, again and again — just as I have seen thousands of farmers scatter seed, year after year.\"\n\"All effort, all struggle... only for the cycle to begin anew.\nNot just you and I — but the souls of the Abyss, and the living above — all are bound within this endless tragedy.\"\n\"And if that burden proves too great for you to carry... you may always lay it down. And then — it would end.\""
        },
        [6201009] = {
          ContentEN = "Refuse.",
          DialogueId = 6201009,
          GUID = "0F86090A",
          NextDialogue = 6201010,
          RougeTalkActorType = 2,
          Subtitle = "Refuse."
        },
        [6201010] = {
          ContentEN = [[
To end it all would be to become one of those drifting souls.
Your gentle heart would fade. You'd no longer fear solitude, no longer feel the torment of this endless cycle. But... would that truly be happiness?]],
          DialogueId = 6201010,
          GUID = "0F860934",
          NextDialogue = 6201011,
          RougeTalkActorType = 3,
          Subtitle = [[
To end it all would be to become one of those drifting souls.
Your gentle heart would fade. You'd no longer fear solitude, no longer feel the torment of this endless cycle. But... would that truly be happiness?]]
        },
        [6201011] = {
          ContentEN = [[
"No." You take up your blade once more. 
"I'll keep fighting. I'll keep chasing those damned Glazeystal shards."]],
          DialogueId = 6201011,
          GUID = "0F86095E",
          NextOptions = {
            [1] = 6201012
          },
          RougeTalkActorType = 2,
          SpeakNpcId = 910004,
          Subtitle = [[
"No." You take up your blade once more. 
"I'll keep fighting. I'll keep chasing those damned Glazeystal shards."]]
        },
        [6201012] = {
          ContentEN = "I must be on my way.",
          DialogueId = 6201012,
          GUID = "0F860988",
          IsKeyOption = true,
          NextDialogue = 6201013,
          RougeTalkActorType = 2,
          Subtitle = "I must be on my way."
        },
        [6201013] = {
          ContentEN = "\"Farewell, steadfast traveller,\" he says. \"May the flame of your Lantern shine ever unceasing upon your path.\"",
          DialogueId = 6201013,
          GUID = "0F8609B2",
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = "\"Farewell, steadfast traveller,\" he says. \"May the flame of your Lantern shine ever unceasing upon your path.\""
        },
        [6201101] = {
          ContentEN = [[
The Abyssal Merchant takes the Lantern from your hands. Without a word, you trade Embers for a Lampwick with him.
This time, you have no intention of lingering.]],
          DialogueId = 6201101,
          GUID = "0F861822",
          NextOptions = {
            [1] = 6201102
          },
          RougeTalkActorType = 3,
          Subtitle = [[
The Abyssal Merchant takes the Lantern from your hands. Without a word, you trade Embers for a Lampwick with him.
This time, you have no intention of lingering.]]
        },
        [6201102] = {
          ContentEN = "I must be on my way.",
          DialogueId = 6201102,
          GUID = "0F86184C",
          IsKeyOption = true,
          NextDialogue = 6201103,
          RougeTalkActorType = 2,
          Subtitle = "I must be on my way."
        },
        [6201103] = {
          ContentEN = "\"Take this.\"\nA young voice speaks softly from behind you. He presses something into your hand.\n\"It gives no light, so no Ember is needed.\"\nA piece of candy — clear, translucent — rests in your blood-stained palm.",
          DialogueId = 6201103,
          GUID = "0F861876",
          NextDialogue = 6201104,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = "\"Take this.\"\nA young voice speaks softly from behind you. He presses something into your hand.\n\"It gives no light, so no Ember is needed.\"\nA piece of candy — clear, translucent — rests in your blood-stained palm."
        },
        [6201104] = {
          ContentEN = "You place it on your tongue and let it melt. The taste is wild mint — sharp, cool, piercing. For the first time in ages, your mind clears... and you remember what it is to be human.\nNo longer do Abyssoids haunt your thoughts. Instead, memories return: a tower that pierced the clouds; the oak you could never resist climbing; the chill of cream on a silver plate; the swing swaying in the backyard.\nThese memories — proof that you have lived.",
          DialogueId = 6201104,
          GUID = "0F8618A0",
          NextDialogue = 6201105,
          RougeTalkActorType = 3,
          Subtitle = "You place it on your tongue and let it melt. The taste is wild mint — sharp, cool, piercing. For the first time in ages, your mind clears... and you remember what it is to be human.\nNo longer do Abyssoids haunt your thoughts. Instead, memories return: a tower that pierced the clouds; the oak you could never resist climbing; the chill of cream on a silver plate; the swing swaying in the backyard.\nThese memories — proof that you have lived."
        },
        [6201105] = {
          ContentEN = "And what of the mysterious Abyssal Merchant? Was he human, or phantom? Does he like the taste of candy? Does it wound him, being bound to this Abyss? Did he once walk in sunlight, in the world above — and live, as you did?\nBut there is no time to linger.\nYou must fight on. Without end.",
          DialogueId = 6201105,
          GUID = "0F8618CA",
          NextDialogue = 6201106,
          RougeTalkActorType = 3,
          Subtitle = "And what of the mysterious Abyssal Merchant? Was he human, or phantom? Does he like the taste of candy? Does it wound him, being bound to this Abyss? Did he once walk in sunlight, in the world above — and live, as you did?\nBut there is no time to linger.\nYou must fight on. Without end."
        },
        [6201106] = {
          ContentEN = "Farewell, level-headed traveller,\" he says. \"May the flame of your Lantern shine ever unceasing upon your path.\"",
          DialogueId = 6201106,
          GUID = "0F8618F4",
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = "Farewell, level-headed traveller,\" he says. \"May the flame of your Lantern shine ever unceasing upon your path.\""
        },
        [6201201] = {
          ContentEN = "Lately, the weariness weighs on you less. You even chat with some of the Abyssoids now.\nYou cannot tell if your heart is hardening, growing numb — or if this is the fracture before collapse.\nFor now, at least, you do not feel so bad.",
          DialogueId = 6201201,
          GUID = "0F86288A",
          NextDialogue = 6201202,
          RougeTalkActorType = 3,
          Subtitle = "Lately, the weariness weighs on you less. You even chat with some of the Abyssoids now.\nYou cannot tell if your heart is hardening, growing numb — or if this is the fracture before collapse.\nFor now, at least, you do not feel so bad."
        },
        [6201202] = {
          ContentEN = "\"I met two zealots today — one sworn to Selenism, the other to Noclunism.\"\n\"One claimed to serve the light, the other the dark. The irony was this: when you told them you cared nothing for their gods, both spat the same profanities.\"\n\"And you? Do you follow a god?\"",
          DialogueId = 6201202,
          GUID = "0F8628B4",
          NextDialogue = 6201203,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004,
          Subtitle = "\"I met two zealots today — one sworn to Selenism, the other to Noclunism.\"\n\"One claimed to serve the light, the other the dark. The irony was this: when you told them you cared nothing for their gods, both spat the same profanities.\"\n\"And you? Do you follow a god?\""
        },
        [6201203] = {
          ContentEN = [[
"I serve Fusa." 
For the first time, the Merchant answers a question about himself.
"I speak Her name, hail Her grace, and honour the light of the Full Moon."]],
          DialogueId = 6201203,
          GUID = "0F8628DE",
          NextDialogue = 6201204,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = [[
"I serve Fusa." 
For the first time, the Merchant answers a question about himself.
"I speak Her name, hail Her grace, and honour the light of the Full Moon."]]
        },
        [6201204] = {
          ContentEN = "His words surprise you — you had expected something more arcane, more intriguing.",
          DialogueId = 6201204,
          GUID = "0F862908",
          NextDialogue = 6201205,
          RougeTalkActorType = 3,
          Subtitle = "His words surprise you — you had expected something more arcane, more intriguing."
        },
        [6201205] = {
          ContentEN = [[
"So... you believe in all that Elysian Orthodox teaching?
That if you pray devoutly to the Goddess of the Full Moon, She will weave threads of blessing, and draw us from the dark?"]],
          DialogueId = 6201205,
          GUID = "0F862932",
          NextDialogue = 6201206,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004,
          Subtitle = [[
"So... you believe in all that Elysian Orthodox teaching?
That if you pray devoutly to the Goddess of the Full Moon, She will weave threads of blessing, and draw us from the dark?"]]
        },
        [6201206] = {
          ContentEN = "\"No. I <H>follow</> Fusa, but I do not <H>believe in</> Her.\" \n\"I only needed something — something certain — to justify the path I chose to walk.\"",
          DialogueId = 6201206,
          GUID = "0F86295C",
          NextOptions = {
            [1] = 6201207
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = "\"No. I follow Fusa, but I do not believe in Her.\" \n\"I only needed something — something certain — to justify the path I chose to walk.\""
        },
        [6201207] = {
          ContentEN = "I don't understand.",
          DialogueId = 6201207,
          GUID = "0F862986",
          NextDialogue = 6201208,
          RougeTalkActorType = 2,
          Subtitle = "I don't understand."
        },
        [6201208] = {
          ContentEN = [[
"We should give, not take."
"We should love, not hate."
"We should embrace, not wound."
"This is what I hold to be right. Yet if I believe in freedom of the human mind, I cannot prove what I believe to be true."]],
          DialogueId = 6201208,
          GUID = "0F8629B0",
          NextDialogue = 6201209,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = [[
"We should give, not take."
"We should love, not hate."
"We should embrace, not wound."
"This is what I hold to be right. Yet if I believe in freedom of the human mind, I cannot prove what I believe to be true."]]
        },
        [6201209] = {
          ContentEN = "\"So I cast aside 'freedom' and chose Fusa, who achieves utmost transcendence. In that way, what I held as right became truth — flawless, unquestioned, beyond the need of proof.\"\nHe lets out a sigh.\n\"In a sense... perhaps I am Her ultimate transgressor.\"",
          DialogueId = 6201209,
          GUID = "0F8629DA",
          NextDialogue = 6201210,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = "\"So I cast aside 'freedom' and chose Fusa, who achieves utmost transcendence. In that way, what I held as right became truth — flawless, unquestioned, beyond the need of proof.\"\nHe lets out a sigh.\n\"In a sense... perhaps I am Her ultimate transgressor.\""
        },
        [6201210] = {
          ContentEN = "\"So what you're saying is...\" \nYou search for words. \n\"If I wanted to keep pressing on in this Abyss, I might as well invent a... god of walking — just to convince myself I must go on?\"",
          DialogueId = 6201210,
          GUID = "0F862A04",
          NextDialogue = 6201211,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004,
          Subtitle = "\"So what you're saying is...\" \nYou search for words. \n\"If I wanted to keep pressing on in this Abyss, I might as well invent a... god of walking — just to convince myself I must go on?\""
        },
        [6201211] = {
          ContentEN = [[
"Mmm... You could say that." 
He chuckles softly.]],
          DialogueId = 6201211,
          GUID = "0F862A2E",
          NextOptions = {
            [1] = 6201212
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = [[
"Mmm... You could say that." 
He chuckles softly.]]
        },
        [6201212] = {
          ContentEN = "What a kook. But I've lingered too long. I should be on my way.",
          DialogueId = 6201212,
          GUID = "0F862A58",
          IsKeyOption = true,
          NextDialogue = 6201213,
          RougeTalkActorType = 2,
          Subtitle = "What a kook. But I've lingered too long. I should be on my way."
        },
        [6201213] = {
          ContentEN = "\"Farewell, wise traveller,\" he says. \"May the flame of your Lantern shine ever unceasing upon your path.\"",
          DialogueId = 6201213,
          GUID = "0F862A82",
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = "\"Farewell, wise traveller,\" he says. \"May the flame of your Lantern shine ever unceasing upon your path.\""
        },
        [6201301] = {
          ContentEN = "\"It has been long since last I rested.\"\nYou've already planned the trade before you come here.\n\"Could I buy something from you — a dream?\"\n\"If such a thing is possible.\"",
          DialogueId = 6201301,
          GUID = "0F8638F2",
          NextDialogue = 6201302,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004,
          Subtitle = "\"It has been long since last I rested.\"\nYou've already planned the trade before you come here.\n\"Could I buy something from you — a dream?\"\n\"If such a thing is possible.\""
        },
        [6201302] = {
          ContentEN = [[
"I am no dream-weaver. I cannot promise it will be what you seek."
He shakes his head slowly.
"But perhaps I may try."
"Long ago, when I told stories to my little sister, she would always sleep well."]],
          DialogueId = 6201302,
          GUID = "0F86391C",
          NextDialogue = 6201303,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = [[
"I am no dream-weaver. I cannot promise it will be what you seek."
He shakes his head slowly.
"But perhaps I may try."
"Long ago, when I told stories to my little sister, she would always sleep well."]]
        },
        [6201303] = {
          ContentEN = "You gather a heap of straw, softening it as best you can.\nWeariness settles over you once more. You yearn for a dream — for just a brief rest.",
          DialogueId = 6201303,
          GUID = "0F863946",
          NextDialogue = 6201304,
          RougeTalkActorType = 3,
          Subtitle = "You gather a heap of straw, softening it as best you can.\nWeariness settles over you once more. You yearn for a dream — for just a brief rest."
        },
        [6201304] = {
          ContentEN = "\"Once upon a time,\" he said, \"there was a boy — a young goldsmith — who fell in love with the Moon.\"\n\"In secret he measured her shape and size, planning to forge a necklace from the finest gems the world could offer — a gift for the crescent Moon he adored.\"\n\"But when the work was done, the Moon had grown rounder, and the necklace no longer fit.\"\n\"So he began again, setting every jewel he had ever gathered. Yet when he returned, the Moon was rounder still — full as a silver dish upon the sky.\"",
          DialogueId = 6201304,
          GUID = "0F863970",
          NextDialogue = 6201305,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = "\"Once upon a time,\" he said, \"there was a boy — a young goldsmith — who fell in love with the Moon.\"\n\"In secret he measured her shape and size, planning to forge a necklace from the finest gems the world could offer — a gift for the crescent Moon he adored.\"\n\"But when the work was done, the Moon had grown rounder, and the necklace no longer fit.\"\n\"So he began again, setting every jewel he had ever gathered. Yet when he returned, the Moon was rounder still — full as a silver dish upon the sky.\""
        },
        [6201305] = {
          ContentEN = [[
It is an old fairytale. You dimly recall your mother once telling it to you.
Sleep begins to drift over you.]],
          DialogueId = 6201305,
          GUID = "0F86399A",
          NextDialogue = 6201306,
          RougeTalkActorType = 3,
          Subtitle = [[
It is an old fairytale. You dimly recall your mother once telling it to you.
Sleep begins to drift over you.]]
        },
        [6201306] = {
          ContentEN = "\"'Then I shall make three necklaces in different sizes,' thought the goldsmith. 'Surely one will fit her.'\"\n\"But when he brought his offerings to the Moon he loved,\nshe was gone.\"\n\"The sky lay black, with only stars upon it — as if the Moon had never been there at all.\"",
          DialogueId = 6201306,
          GUID = "0F8639C4",
          NextDialogue = 6201307,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = "\"'Then I shall make three necklaces in different sizes,' thought the goldsmith. 'Surely one will fit her.'\"\n\"But when he brought his offerings to the Moon he loved,\nshe was gone.\"\n\"The sky lay black, with only stars upon it — as if the Moon had never been there at all.\""
        },
        [6201307] = {
          ContentEN = "You sink into a moonlit dream.",
          DialogueId = 6201307,
          GUID = "0F8639EE",
          NextDialogue = 6201308,
          RougeTalkActorType = 3,
          Subtitle = "You sink into a moonlit dream."
        },
        [6201308] = {
          ContentEN = [[
"...And so the goldsmith who had lost the Moon struck his hammer day after day, forging necklaces that would never be worn."
"His tears fell upon the earth, and from them grew glittering trees, heavy with fruit, each one shining like the Moon he loved."
"In time, people named the trees Heaventree, and the fruit Phoxene..."
"Weary traveller... have you drifted off? Sweat dreams, then."]],
          DialogueId = 6201308,
          GUID = "0F863A18",
          NextDialogue = 6201309,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = [[
"...And so the goldsmith who had lost the Moon struck his hammer day after day, forging necklaces that would never be worn."
"His tears fell upon the earth, and from them grew glittering trees, heavy with fruit, each one shining like the Moon he loved."
"In time, people named the trees Heaventree, and the fruit Phoxene..."
"Weary traveller... have you drifted off? Sweat dreams, then."]]
        },
        [6201309] = {
          ContentEN = "In your first dream, a swing drifts in a garden courtyard. \nYou are small again. The old butler stands beside it, arms open, waiting for you to run into them. \n\"Welcome back, my ▇▇.\" \n...",
          DialogueId = 6201309,
          GUID = "0F863A42",
          NextDialogue = 6201310,
          RougeTalkActorType = 3,
          Subtitle = "In your first dream, a swing drifts in a garden courtyard. \nYou are small again. The old butler stands beside it, arms open, waiting for you to run into them. \n\"Welcome back, my ▇▇.\" \n..."
        },
        [6201310] = {
          ContentEN = "In the second dream, young knights stand upon a hillside of blooming thyme.\nThey raise a banner of golden iris; their hair streams in the wind as they call your name, smiling.\n\"Let us set out, Lord ▇▇.\" \n...",
          DialogueId = 6201310,
          GUID = "0F863A6C",
          NextDialogue = 6201311,
          RougeTalkActorType = 3,
          Subtitle = "In the second dream, young knights stand upon a hillside of blooming thyme.\nThey raise a banner of golden iris; their hair streams in the wind as they call your name, smiling.\n\"Let us set out, Lord ▇▇.\" \n..."
        },
        [6201311] = {
          ContentEN = "In the third dream, you see another traveller — carrying a lantern like yours. You have seen {性别：him|her} three times now.\n{性别：His|Her} figure drifts farther and farther, fading into the dark.\nYou run, heart pounding, chasing with all your strength.",
          DialogueId = 6201311,
          GUID = "0F863A96",
          NextDialogue = 6201312,
          RougeTalkActorType = 3,
          Subtitle = "In the third dream, you see another traveller — carrying a lantern like yours. You have seen {性别：him|her} three times now.\n{性别：His|Her} figure drifts farther and farther, fading into the dark.\nYou run, heart pounding, chasing with all your strength."
        },
        [6201312] = {
          ContentEN = [[
"Could you stay?"
Your hoarse cry is more desperate than in any battle.]],
          DialogueId = 6201312,
          GUID = "0F863AC0",
          NextDialogue = 6201313,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004,
          Subtitle = [[
"Could you stay?"
Your hoarse cry is more desperate than in any battle.]]
        },
        [6201313] = {
          ContentEN = "\"I'm sorry, ▇▇.\"\n{性别：He|She} turns, the lantern's flame wavering across {性别：his|her} face — yet you cannot see it clearly.\n\"Our paths run in <H>opposite directions</>. That's why... I have to go.\"",
          DialogueId = 6201313,
          GUID = "0F863AEA",
          NextDialogue = 6201314,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char02",
          Subtitle = "\"I'm sorry, ▇▇.\"\n{性别：He|She} turns, the lantern's flame wavering across {性别：his|her} face — yet you cannot see it clearly.\n\"Our paths run in opposite directions. That's why... I have to go.\""
        },
        [6201314] = {
          ContentEN = "\"But — I don't want to be alone anymore!\" \nYou reach for the hem of {性别：his|her} coat — like a petulant child begging for the last piece of candy — but catch only air.\nTears spill down your cheeks. How long has it been since you last cried?",
          DialogueId = 6201314,
          GUID = "0F863B14",
          NextDialogue = 6201315,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004,
          Subtitle = "\"But — I don't want to be alone anymore!\" \nYou reach for the hem of {性别：his|her} coat — like a petulant child begging for the last piece of candy — but catch only air.\nTears spill down your cheeks. How long has it been since you last cried?"
        },
        [6201315] = {
          ContentEN = "\"Don't cry, ▇▇.\"\n{性别：He|She} brushes your cheek, tender and merciful, wiping your tears away. You feel {性别：his|her} breath — the unmistakable warmth of another human.\n\"Our journey is <H>a circle</>. Even walking in opposite directions, we are bound to meet again.\"",
          DialogueId = 6201315,
          GUID = "0F863B3E",
          NextDialogue = 6201316,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char02",
          Subtitle = "\"Don't cry, ▇▇.\"\n{性别：He|She} brushes your cheek, tender and merciful, wiping your tears away. You feel {性别：his|her} breath — the unmistakable warmth of another human.\n\"Our journey is a circle. Even walking in opposite directions, we are bound to meet again.\""
        },
        [6201316] = {
          ContentEN = "You see the lantern in {性别：his|her} hand begin to glow with silver-white radiance — brighter, ever brighter, like a full moon casting its silver threads of light...\nAnd {性别：he|she} steps into the blinding silver glow.\n...\n...\nYou wake to the scent of wild mint.",
          DialogueId = 6201316,
          GUID = "0F863B68",
          NextDialogue = 6201317,
          RougeTalkActorType = 3,
          Subtitle = "You see the lantern in {性别：his|her} hand begin to glow with silver-white radiance — brighter, ever brighter, like a full moon casting its silver threads of light...\nAnd {性别：he|she} steps into the blinding silver glow.\n...\n...\nYou wake to the scent of wild mint."
        },
        [6201317] = {
          ContentEN = "\"Was it a sweet dream?\"",
          DialogueId = 6201317,
          GUID = "0F863B92",
          NextDialogue = 6201318,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = "\"Was it a sweet dream?\""
        },
        [6201318] = {
          ContentEN = "\"Yes... it felt long. As though many years had passed.\"",
          DialogueId = 6201318,
          GUID = "0F863BBC",
          NextDialogue = 6201319,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004,
          Subtitle = "\"Yes... it felt long. As though many years had passed.\""
        },
        [6201319] = {
          ContentEN = "\"That's good. You are fortunate still, to be able to dream.\"",
          DialogueId = 6201319,
          GUID = "0F863BE6",
          NextDialogue = 6201320,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = "\"That's good. You are fortunate still, to be able to dream.\""
        },
        [6201320] = {
          ContentEN = "You rise, Lantern in hand. Your battle continues — an endless, solitary road.",
          DialogueId = 6201320,
          GUID = "0F863C10",
          NextOptions = {
            [1] = 6201321
          },
          RougeTalkActorType = 3,
          Subtitle = "You rise, Lantern in hand. Your battle continues — an endless, solitary road."
        },
        [6201321] = {
          ContentEN = "Thank you. I should be going.",
          DialogueId = 6201321,
          GUID = "0F863C3A",
          IsKeyOption = true,
          NextDialogue = 6201322,
          RougeTalkActorType = 2,
          Subtitle = "Thank you. I should be going."
        },
        [6201322] = {
          ContentEN = [[
"Farewell, steadfast traveller," he says.
"May there come a day when you no longer walk this road alone."]],
          DialogueId = 6201322,
          GUID = "0F863C64",
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = [[
"Farewell, steadfast traveller," he says.
"May there come a day when you no longer walk this road alone."]]
        },
        [6201401] = {
          ContentEN = "Darkness... darkness... and darkness yet deeper—\nYou drift in silence, submerged beneath still waters,\ncarried ever downward along a river without end.",
          DialogueId = 6201401,
          GUID = "0F86495A",
          NextDialogue = 6201402,
          RougeTalkActorType = 3,
          Subtitle = "Darkness... darkness... and darkness yet deeper—\nYou drift in silence, submerged beneath still waters,\ncarried ever downward along a river without end."
        },
        [6201402] = {
          ContentEN = [[
And then, from afar, a light begins to draw near.
It is a <H>Lantern</>.]],
          DialogueId = 6201402,
          GUID = "0F864984",
          NextDialogue = 6201403,
          RougeTalkActorType = 3,
          Subtitle = [[
And then, from afar, a light begins to draw near.
It is a Lantern.]]
        },
        [6201403] = {
          ContentEN = "\"You have returned. I always knew you would.\"\nThe flickering flame reveals the face of its bearer — an aged woman.",
          DialogueId = 6201403,
          GUID = "0F8649AE",
          NextOptions = {
            [1] = 6201404
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent_SeasonFirst01_Char01",
          Subtitle = "\"You have returned. I always knew you would.\"\nThe flickering flame reveals the face of its bearer — an aged woman."
        },
        [6201404] = {
          ContentEN = "Do you know me?",
          DialogueId = 6201404,
          GUID = "0F8649D8",
          NextDialogue = 6201405,
          RougeTalkActorType = 2,
          Subtitle = "Do you know me?"
        },
        [6201405] = {
          ContentEN = [[
"Yes."
Her clouded eyes kindle with light, like dead wood bursting into bloom.
"I have waited for you... for a very, very long time."]],
          DialogueId = 6201405,
          GUID = "0F864A02",
          NextOptions = {
            [1] = 6201406
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent_SeasonFirst01_Char01",
          Subtitle = [[
"Yes."
Her clouded eyes kindle with light, like dead wood bursting into bloom.
"I have waited for you... for a very, very long time."]]
        },
        [6201406] = {
          ContentEN = "I can't remember who I am.",
          DialogueId = 6201406,
          GUID = "0F864A2C",
          NextDialogue = 6201407,
          RougeTalkActorType = 2,
          Subtitle = "I can't remember who I am."
        },
        [6201407] = {
          ContentEN = "\"The path we walk is <H>a circle</>.\"\nShe smiles.\n\"And now that you've come full circle — all you have forgotten shall soon return.\"",
          DialogueId = 6201407,
          GUID = "0F864A56",
          NextOptions = {
            [1] = 6201408
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent_SeasonFirst01_Char01",
          Subtitle = "\"The path we walk is a circle.\"\nShe smiles.\n\"And now that you've come full circle — all you have forgotten shall soon return.\""
        },
        [6201408] = {
          ContentEN = "What should I do next?",
          DialogueId = 6201408,
          GUID = "0F864A80",
          NextDialogue = 6201409,
          RougeTalkActorType = 2,
          Subtitle = "What should I do next?"
        },
        [6201409] = {
          ContentEN = "\"Leave this place. Leave the <H>Abyss</>. That has ever been the wish of <H>every you</> that has ever walked this path.\"\nShe places the Lantern in your hands. Her fingers are cold as a ghost's — yet the Lantern burns golden, bright, and warm.\nSet into its frame is a dial, etched with fine <H>gradations</>.",
          DialogueId = 6201409,
          GUID = "0F864AAA",
          NextOptions = {
            [1] = 6201410
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent_SeasonFirst01_Char01",
          Subtitle = "\"Leave this place. Leave the Abyss. That has ever been the wish of every you that has ever walked this path.\"\nShe places the Lantern in your hands. Her fingers are cold as a ghost's — yet the Lantern burns golden, bright, and warm.\nSet into its frame is a dial, etched with fine gradations."
        },
        [6201410] = {
          ContentEN = "How can I leave this place?",
          DialogueId = 6201410,
          GUID = "0F864AD4",
          IsKeyOption = true,
          NextDialogue = 6201411,
          RougeTalkActorType = 2,
          Subtitle = "How can I leave this place?"
        },
        [6201411] = {
          ContentEN = [[
"This Lantern carries a divine blessing."
"Restore it with enough <H>Pure Glazeystal</>, and it shall part the depths of the Abyss, opening a path before you."
"Should you face mortal peril... turn the dial in <H>reverse</>."]],
          DialogueId = 6201411,
          GUID = "0F864AFE",
          NextDialogue = 6201412,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent_SeasonFirst01_Char01",
          Subtitle = [[
"This Lantern carries a divine blessing."
"Restore it with enough Pure Glazeystal, and it shall part the depths of the Abyss, opening a path before you."
"Should you face mortal peril... turn the dial in reverse."]]
        },
        [6201412] = {
          ContentEN = "\"Before you set out, perhaps you would like to hear a tale or two of this Abyss.\"\nShe smiles again, serene and still.\n\"These are but fragments — driftwood upon the river of time. As I have told you, the path we tread is a circle. To you, these stories may be of your 'past'... or of your 'future'.\"\n\"Yet this much is certain: <H>they are your stories</>.\"",
          DialogueId = 6201412,
          GUID = "0F864B28",
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent_SeasonFirst01_Char01",
          Subtitle = "\"Before you set out, perhaps you would like to hear a tale or two of this Abyss.\"\nShe smiles again, serene and still.\n\"These are but fragments — driftwood upon the river of time. As I have told you, the path we tread is a circle. To you, these stories may be of your 'past'... or of your 'future'.\"\n\"Yet this much is certain: they are your stories.\""
        },
        [6201501] = {
          ContentEN = "Footsteps echo in the dark — dull, dragging, tapering into a gritty scrape.\nYou follow the sound. Four figures emerge at last: the Knights of Hushed Dusk. Your paths cross again. They stand unscathed, yet their faces bear none of the light they wore when last you met.",
          DialogueId = 6201501,
          GUID = "0F8659C2",
          NextDialogue = 6201502,
          RougeTalkActorType = 3,
          Subtitle = "Footsteps echo in the dark — dull, dragging, tapering into a gritty scrape.\nYou follow the sound. Four figures emerge at last: the Knights of Hushed Dusk. Your paths cross again. They stand unscathed, yet their faces bear none of the light they wore when last you met."
        },
        [6201502] = {
          ContentEN = [[
"Are we truly still walking...? How long has it been?"
The Sorceress's voice hangs heavy with fatigue, as if the cloak on her shoulders were a slab of stone.]],
          DialogueId = 6201502,
          GUID = "0F8659EC",
          NextDialogue = 6201503,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista",
          Subtitle = [[
