      return {
        [6201602] = {
          ContentEN = "Then — a slim shadow sweeps past. By instinct he raises his shield, catching the strike. An arrow juts from the cracked wood. When he sees it clearly, he freezes.\nIts fletching bears the golden Iris of Elysium — but the base is stained black. There is only one archer who would do that...",
          DialogueId = 6201602,
          GUID = "0F866A54",
          NextDialogue = 6201603,
          RougeTalkActorType = 3,
          Subtitle = "Then — a slim shadow sweeps past. By instinct he raises his shield, catching the strike. An arrow juts from the cracked wood. When he sees it clearly, he freezes.\nIts fletching bears the golden Iris of Elysium — but the base is stained black. There is only one archer who would do that..."
        },
        [6201603] = {
          ContentEN = "\"Calista...?\"",
          DialogueId = 6201603,
          GUID = "0F866A7E",
          NextDialogue = 6201604,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn",
          Subtitle = "\"Calista...?\""
        },
        [6201604] = {
          ContentEN = "The Abyssoid presses closer, its limbs gnawed by the darkness, until they seem to blur into the cloak that shrouds it. \"She\" gives no answer to Flynn's call — only draws the bowstring taut once more.",
          DialogueId = 6201604,
          GUID = "0F866AA8",
          NextDialogue = 6201605,
          RougeTalkActorType = 3,
          Subtitle = "The Abyssoid presses closer, its limbs gnawed by the darkness, until they seem to blur into the cloak that shrouds it. \"She\" gives no answer to Flynn's call — only draws the bowstring taut once more."
        },
        [6201605] = {
          ContentEN = "From their very first steps into the Abyss, they are horrified to see familiar figures among the hostile, human-like Abyssoids. Many were once Knights of Elysium, who had marched here to bring down the Abyss — only to be claimed by it in death, reborn as part of its darkness, and set against their former comrades.",
          DialogueId = 6201605,
          GUID = "0F866AD2",
          NextDialogue = 6201606,
          RougeTalkActorType = 3,
          Subtitle = "From their very first steps into the Abyss, they are horrified to see familiar figures among the hostile, human-like Abyssoids. Many were once Knights of Elysium, who had marched here to bring down the Abyss — only to be claimed by it in death, reborn as part of its darkness, and set against their former comrades."
        },
        [6201606] = {
          ContentEN = "This is the Abyss's cruellest curse: to live is itself a curse. Those who fall swiftly may still become mere phantoms, resembling what they were in life.",
          DialogueId = 6201606,
          GUID = "0F866AFC",
          NextDialogue = 6201607,
          RougeTalkActorType = 3,
          Subtitle = "This is the Abyss's cruellest curse: to live is itself a curse. Those who fall swiftly may still become mere phantoms, resembling what they were in life."
        },
        [6201607] = {
          ContentEN = "But if one refuses to die and struggles on, then every passing moment the darkness gnaws at their will. In the end, each battle becomes a gamble: should their resolve falter even for an instant, the Abyss devours their mind, leaving only a mindless beast driven to slaughter.",
          DialogueId = 6201607,
          GUID = "0F866B26",
          NextDialogue = 6201608,
          RougeTalkActorType = 3,
          Subtitle = "But if one refuses to die and struggles on, then every passing moment the darkness gnaws at their will. In the end, each battle becomes a gamble: should their resolve falter even for an instant, the Abyss devours their mind, leaving only a mindless beast driven to slaughter."
        },
        [6201608] = {
          ContentEN = "Just like the one who stands before Flynn now.",
          DialogueId = 6201608,
          GUID = "0F866B50",
          NextDialogue = 6201609,
          RougeTalkActorType = 3,
          Subtitle = "Just like the one who stands before Flynn now."
        },
        [6201609] = {
          ContentEN = "\"No... don't do this... I don't want to hurt you... please...\" His hands shake upon the hilt of his sword. \"Milton's already gone. If I lose you too...\"",
          DialogueId = 6201609,
          GUID = "0F866B7A",
          NextDialogue = 6201610,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn",
          Subtitle = "\"No... don't do this... I don't want to hurt you... please...\" His hands shake upon the hilt of his sword. \"Milton's already gone. If I lose you too...\""
        },
        [6201610] = {
          ContentEN = "But the arrow comes anyway, swift for his heart. He wrenches up his shield. Another hisses past — slashing his cheek, spilling blood.",
          DialogueId = 6201610,
          GUID = "0F866BA4",
          NextDialogue = 6201611,
          RougeTalkActorType = 3,
          Subtitle = "But the arrow comes anyway, swift for his heart. He wrenches up his shield. Another hisses past — slashing his cheek, spilling blood."
        },
        [6201611] = {
          ContentEN = "\"Aaaah—!\"",
          DialogueId = 6201611,
          GUID = "0F866BCE",
          NextDialogue = 6201612,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn",
          Subtitle = "\"Aaaah—!\""
        },
        [6201612] = {
          ContentEN = "With a cry, he swings his blade — once, twice, again — until the Abyssoid at last dissolves into ash.\nHis body trembles, held up only by the sword. Before the dust that was once his comrade, he breaks, his voice torn by grief, and weeps aloud.",
          DialogueId = 6201612,
          GUID = "0F866BF8",
          NextDialogue = 6201613,
          RougeTalkActorType = 3,
          Subtitle = "With a cry, he swings his blade — once, twice, again — until the Abyssoid at last dissolves into ash.\nHis body trembles, held up only by the sword. Before the dust that was once his comrade, he breaks, his voice torn by grief, and weeps aloud."
        },
        [6201613] = {
          ContentEN = "When the weeping finally ebbs, an eerie silence fills the hollow air. The battle is over — yet the girl who once fought beside him, always bounding, always loud and full of life, does not return with her usual grin. Not this time.",
          DialogueId = 6201613,
          GUID = "0F866C22",
          NextDialogue = 6201614,
          RougeTalkActorType = 3,
          Subtitle = "When the weeping finally ebbs, an eerie silence fills the hollow air. The battle is over — yet the girl who once fought beside him, always bounding, always loud and full of life, does not return with her usual grin. Not this time."
        },
        [6201614] = {
