        [10031301] = {
          ContentEN = "Hey, look! There's a <H>broken weather vane</> in this rubbish bin. Wow, it looks practically brand new! Someone just tossed it out like that? What a waste... Let's take it with us!",
          DetectiveQuestionId = 1002,
          DialogueId = 10031301,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter_Vane.T_Guide_Chapter_Vane'}",
          GUID = "191CC052",
          NextDialogue = 10031302,
          SpeakNpcId = 200002,
          Subtitle = "Hey, look! There's a broken weather vane in this rubbish bin. Wow, it looks practically brand new! Someone just tossed it out like that? What a waste... Let's take it with us!",
          VoiceName = "voice/$Locale$/story/1003/100313/191CC052"
        },
        [10031302] = {
          ContentEN = "Do you collect weather vanes? That's quite an unusual hobby. I could have one of my subordinates get you a new one, but this is a piece of evidence — you can't have it now.",
          DetectiveQuestionId = 1002,
          DialogueId = 10031302,
          GUID = "191CC07C",
          NextDialogue = 10031303,
          SpeakNpcId = 100304,
          Subtitle = "Do you collect weather vanes? That's quite an unusual hobby. I could have one of my subordinates get you a new one, but this is a piece of evidence — you can't have it now.",
          VoiceName = "voice/$Locale$/story/1003/100313/191CC07C"
        },
        [10031303] = {
          ContentEN = "Uh... I was just saying it offhand. I-It's not like I actually have a thing for weather vanes or anything...",
          DetectiveQuestionId = 1002,
          DialogueId = 10031303,
          GUID = "191CC0A6",
          NextDialogue = 10031304,
          SpeakNpcId = 200002,
          Subtitle = "Uh... I was just saying it offhand. I-It's not like I actually have a thing for weather vanes or anything...",
          VoiceName = "voice/$Locale$/story/1003/100313/191CC0A6"
        },
        [10031304] = {
          ContentEN = "Waaah, someone actually took my words seriously for once... I'm so touched, waaah...",
          DetectiveQuestionId = 1002,
          DialogueId = 10031304,
          GUID = "191CC0D0",
          NextDialogue = 10031305,
          SpeakNpcId = 200002,
          Subtitle = "Waaah, someone actually took my words seriously for once... I'm so touched, waaah...",
          VoiceName = "voice/$Locale$/story/1003/100313/191CC0D0"
        },
        [10031305] = {
          ContentEN = "Officer Fischer, when was this street sealed off?",
          DetectiveQuestionId = 1002,
          DialogueId = 10031305,
          GUID = "191CC0FA",
          NextDialogue = 10031306,
          SpeakNpcId = 100001,
          Subtitle = "Officer Fischer, when was this street sealed off?",
          VoiceName = "voice/$Locale$/story/1003/100313/191CC0FA"
        },
        [10031306] = {
          ContentEN = "The morning after the first \"Charon Hunt\" incident.",
          DetectiveQuestionId = 1002,
          DialogueId = 10031306,
          GUID = "191CC124",
          NextDialogue = 10031307,
          SpeakNpcId = 100304,
          Subtitle = "The morning after the first \"Charon Hunt\" incident.",
          VoiceName = "voice/$Locale$/story/1003/100313/191CC124"
        },
        [10031307] = {
          ContentEN = "That's fairly prompt... Since this weather vane is practically new, it shouldn't have been discarded on purpose...",
          DetectiveQuestionId = 1002,
          DialogueId = 10031307,
          GUID = "191CC14E",
          NextDialogue = 10031308,
          SpeakNpcId = 100001,
          Subtitle = "That's fairly prompt... Since this weather vane is practically new, it shouldn't have been discarded on purpose...",
          VoiceName = "voice/$Locale$/story/1003/100313/191CC14E"
        },
        [10031308] = {
          ContentEN = "Could it have been the strong winds that night?",
          DetectiveQuestionId = 1002,
          DialogueId = 10031308,
          GUID = "191CC178",
          NextDialogue = 10031309,
          SpeakNpcId = 200021,
          Subtitle = "Could it have been the strong winds that night?",
          VoiceName = "voice/$Locale$/story/1003/100313/191CC178"
        },
        [10031309] = {
          ContentEN = "No. After the storm five days ago, the Security Bureau did receive numerous reports of property damage, but this weather vane wasn't blown off — it's much more likely <H>knocked down</> by the perpetrator.",
          DetectiveQuestionId = 1002,
          DialogueId = 10031309,
          GUID = "191CC1A2",
          NextDialogue = 10031310,
          SpeakNpcId = 100304,
          Subtitle = "No. After the storm five days ago, the Security Bureau did receive numerous reports of property damage, but this weather vane wasn't blown off — it's much more likely knocked down by the perpetrator.",
          VoiceName = "voice/$Locale$/story/1003/100313/191CC1A2"
        },
        [10031310] = {
          ContentEN = "According to Ms Camilla's account, the perpetrator jumped onto the <H>rooftop</> after engaging with her. This weather vane must have fallen from up there.",
          DetectiveQuestionId = 1002,
          DialogueId = 10031310,
          GUID = "191CC1CC",
          NextDialogue = 10031311,
          SpeakNpcId = 100304,
          Subtitle = "According to Ms Camilla's account, the perpetrator jumped onto the rooftop after engaging with her. This weather vane must have fallen from up there.",
          VoiceName = "voice/$Locale$/story/1003/100313/191CC1CC"
        },
        [10031311] = {
          ContentEN = "(The rooftop... might as well check it out.)",
          DetectiveQuestionId = 1002,
          DialogueId = 10031311,
          DisableMouth = 1,
          GUID = "191CC1F6",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(The rooftop... might as well check it out.)",
          VoiceName = "voice/$Locale$/story/1003/100313/191CC1F6"
        },
        [10031401] = {
          ContentEN = "This is it. The break aligns perfectly. Judging by the bending on the base, apparently it was not blown off by the wind — it was struck with force.",
          DetectiveQuestionId = 1002,
          DialogueId = 10031401,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter_VaneBottom.T_Guide_Chapter_VaneBottom'}",
