          NextDialogue = 10032906,
          SpeakNpcId = 100001,
          Subtitle = "Cleaning sewers every day... Does being a Charon mean you get pushed around no matter where you are, even in the Legion?",
          VoiceName = "voice/$Locale$/story/1003/100329/191DC77A"
        },
        [10032906] = {
          ContentEN = "Prejudice runs deep. But in the Legion, we at least have a chance to prove ourselves through merits and exploits.",
