          GUID = "191EBE3D",
          Subtitle = "We'll be done before the Silvercandle Carnival. Just leave the gaudy decorations where they are.",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE3D"
        },
        [10034416] = {
          ContentEN = "Comms check — one, two... one, two. Can you hear me? Good — loud and clear on my end too.",
