        },
        [10034603] = {
          ContentEN = "I was just remembering the last time I fished here. It was three years ago, with Blues.",
          DialogueId = 10034603,
          GUID = "191EDE0E",
          NextDialogue = 10034604,
          SpeakNpcId = 100304,
          Subtitle = "I was just remembering the last time I fished here. It was three years ago, with Blues.",
          VoiceName = "voice/$Locale$/story/1003/100346/191EDE0E"
        },
        [10034604] = {
          ContentEN = "That kid's smart, but he's always been boisterous. He fished all day and ended up with an empty basket.",
