        [10035319] = {
          ContentEN = "It's a new clue, but unfortunately, it doesn't narrow things down much. Children From the Snowfield had been performed at Galea Theatre for decades. It was incredibly popular, so a lot of the locals know it.",
          DialogueId = 10035319,
          FacialId = {
            [1] = "100304:None"
          },
          GUID = "191F5386",
          LookAt = {
            [1] = "100304:n(100001)"
