          NextDialogue = 10035320,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt03/0071_lise_secret\"},RelatedRegionId{101103}}",
          SpeakNpcId = 100304,
          Subtitle = "It's a new clue, but unfortunately, it doesn't narrow things down much. Children From the Snowfield had been performed at Galea Theatre for decades. It was incredibly popular, so a lot of the locals know it.",
          VoiceName = "voice/$Locale$/story/1003/100353/191F5386"
        },
        [10035320] = {
          Camera = "-47.433594,-302.833496,184.461426,0.000141,-15.616298,71.198349,25.000002,100000.0,false,Manual,22.0",
          ContentEN = "Once, Blues and I saved up for half a year to buy two tickets to see the play. We were so excited, but on that day... someone in the theatre accused us of stealing their tickets. We were kicked out before the play even started.",
          DialogueId = 10035320,
          FacialId = {
            [1] = "100304:Sad01"
          },
          FinalCamera = "-43.898438,-292.427002,181.38916,0.000141,-15.616298,71.198349,25.000002,100000.0,false,Manual,22.0",
          GUID = "191F53B0",
          NextDialogue = 10035321,
          SpeakNpcId = 100304,
          Subtitle = "Once, Blues and I saved up for half a year to buy two tickets to see the play. We were so excited, but on that day... someone in the theatre accused us of stealing their tickets. We were kicked out before the play even started.",
          TalkActionId = {
            [1] = "100304:Talk02_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100353/191F53B0"
        },
        [10035321] = {
          ContentEN = "That night, I sat against the theatre wall for hours, feeling absolutely miserable. But Blues... he pulled out his harmonica like a magician and started playing that song. Turns out, he'd already learned it on his own.",
          DialogueId = 10035321,
          GUID = "191F53DA",
          NextDialogue = 10035322,
          SpeakNpcId = 100304,
          Subtitle = "That night, I sat against the theatre wall for hours, feeling absolutely miserable. But Blues... he pulled out his harmonica like a magician and started playing that song. Turns out, he'd already learned it on his own.",
          VoiceName = "voice/$Locale$/story/1003/100353/191F53DA"
        },
        [10035322] = {
          Camera = "69.078125,-79.48877,262.419922,0.000194,-37.617821,73.187332,35.000008,100000.0,false,Manual,22.0",
          ContentEN = "As he played, a voice rose from the other side of the wall — a boy, singing along. His voice was so beautiful... just like a lark.",
          DialogueId = 10035322,
          FinalCamera = "75.945312,-56.791992,244.148438,0.000194,-37.617821,73.187332,35.000008,100000.0,false,Manual,22.0",
          GUID = "191F5404",
          NextDialogue = 10035323,
          SpeakNpcId = 100304,
          Subtitle = "As he played, a voice rose from the other side of the wall — a boy, singing along. His voice was so beautiful... just like a lark.",
          TalkActionId = {
            [1] = "100304:Talk02_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100353/191F5404"
        },
        [10035323] = {
          Camera = "292.566406,182.274902,118.647949,0.000237,-2.417996,-149.207611,35.000008,100000.0,false,Manual,22.0",
          ContentEN = "With Blues's harmonica and that stranger's singing, I felt so happy I almost forgot we'd been thrown out that night.",
          DialogueId = 10035323,
          GUID = "191F542E",
          NextDialogue = 10035324,
          SpeakNpcId = 100304,
          Subtitle = "With Blues's harmonica and that stranger's singing, I felt so happy I almost forgot we'd been thrown out that night.",
          VoiceName = "voice/$Locale$/story/1003/100353/191F542E"
        },
        [10035324] = {
          Camera = "72.292969,-58.250488,84.757324,0.000228,9.781732,71.391068,35.000008,100000.0,false,Manual,22.0",
          ContentEN = "Sorry... I didn't mean to get carried away and bore you with these old stories. My point is, this song is too common. It's not specific enough to serve as evidence.",
