        [10035328] = {
          Camera = "-151.640625,-339.61792,161.115723,0.000086,-9.217005,58.195625,35.000008,100000.0,false,Manual,22.0",
          ContentEN = "Yeah. I came across a note about it while sorting through case files some time ago. It wasn't anything major — just a brawl at the theatre during a performance two years ago.",
          DialogueId = 10035328,
          GUID = "191F5500",
          LookAt = {
