        [10035418] = {
          Camera = "119.15625,42.66748,164.325195,0.00001,-11.431517,-163.217941,35.000008,100000.0,false,Manual,22.0",
          ContentEN = "Rhythm, don't jump to conclusions. You've seen how cunning this monster is. He could just be disguising himself as your brother to manipulate you.",
