          GUID = "191F8272",
          NextDialogue = 10035606,
          SpeakNpcName = "Cp2CharacterName32",
          Subtitle = "Are you sure we can do that? This feels excessively cruel, doesn't it?",
          VoiceName = "voice/$Locale$/story/1003/100356/191F8272"
        },
        [10035606] = {
          ContentEN = "Cruel? You've got it all wrong. It is by His Majesty's benevolence and the magnificence of alchemical technology that this trash has been given the honour of serving the academy's great cause.",
          DialogueId = 10035606,
          GUID = "191F829C",
          NextDialogue = 10035607,
          SpeakNpcName = "Cp2CharacterName32",
          Subtitle = "Cruel? You've got it all wrong. It is by His Majesty's benevolence and the magnificence of alchemical technology that this trash has been given the honour of serving the academy's great cause.",
          VoiceName = "voice/$Locale$/story/1003/100356/191F829C"
        },
        [10035607] = {
          ContentEN = "Don't even think about running. The electrified grids and gun turrets are far less forgiving than we are. And forget self-destruction — we have plenty of drugs to prolong your worthless existence.",
