          SnapShot = "MEMORY",
          Subtitle = "We chased so hard to catch the light, the dazzling light... only to find it's so... unreachable in the end.",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE782"
        },
        [10036222] = {
          ContentEN = "If something is unreachable, why not pull it down to the ground?",
          DialogueId = 10036222,
          GUID = "191FE7AC",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
