        },
        [10104501] = {
          ContentEN = "Whoo... It's been a while since I've stepped out of the city.",
          DialogueId = 10104501,
          Duration = 3,
          GUID = "194BA9B2",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104502,
          SpeakNpcId = 200006,
          Subtitle = "Whoo... It's been a while since I've stepped out of the city.",
          VoiceName = "voice/$Locale$/story/1002/101045/194BA9B2"
        },
        [10104502] = {
          ContentEN = "The snow-draped conifers, the boundless lake... mountains with their peaks in the clouds... I love all this.",
          DialogueId = 10104502,
          Duration = 3,
          GUID = "194BA9DC",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10104503,
          SpeakNpcId = 200006,
          Subtitle = "The snow-draped conifers, the boundless lake... mountains with their peaks in the clouds... I love all this.",
          VoiceName = "voice/$Locale$/story/1002/101045/194BA9DC"
        },
        [10104503] = {
          ContentEN = "Snow's more a city soul! If only the outskirts were free of those roaming Filthoids.",
          DialogueId = 10104503,
          Duration = 3,
          GUID = "194BAA06",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10104504,
          SpeakNpcId = 200002,
          Subtitle = "Snow's more a city soul! If only the outskirts were free of those roaming Filthoids.",
          VoiceName = "voice/$Locale$/story/1002/101045/194BAA06"
        },
        [10104504] = {
          ContentEN = "It's safer inside, indeed. But there's something about the... air out here.",
          DialogueId = 10104504,
          Duration = 3,
          GUID = "194BAA30",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10104505,
          SpeakNpcId = 200006,
          Subtitle = "It's safer inside, indeed. But there's something about the... air out here.",
          VoiceName = "voice/$Locale$/story/1002/101045/194BAA30"
        },
        [10104505] = {
          ContentEN = "Is there a difference? All smells the same to me...",
          DialogueId = 10104505,
          Duration = 3,
          GUID = "194BAA5A",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10104506,
          SpeakNpcId = 200002,
          Subtitle = "Is there a difference? All smells the same to me...",
          VoiceName = "voice/$Locale$/story/1002/101045/194BAA5A"
        },
        [10104506] = {
          ContentEN = "Mmm... The air in Icelake is always tinged with a scent of blood and echoes of weeping.",
          DialogueId = 10104506,
          Duration = 3,
          GUID = "194BAA84",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104507,
          SpeakNpcId = 200006,
          Subtitle = "Mmm... The air in Icelake is always tinged with a scent of blood and echoes of weeping.",
          VoiceName = "voice/$Locale$/story/1002/101045/194BAA84"
        },
        [10104507] = {
          ContentEN = "Out here, it's the scent of the forest and drifting ice, and the distant sound of steam whistles. Occasionally, you might catch a glimpse of snow-white deer darting through the trees—",
          DialogueId = 10104507,
          Duration = 3,
          GUID = "194BAAAE",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10104508,
          SpeakNpcId = 200006,
          Subtitle = "Out here, it's the scent of the forest and drifting ice, and the distant sound of steam whistles. Occasionally, you might catch a glimpse of snow-white deer darting through the trees—",
          VoiceName = "voice/$Locale$/story/1002/101045/194BAAAE"
        },
        [10104508] = {
          ContentEN = "While around Icelake's alleys, what darts out are thieves or bandits... and sometimes just whimpering beggars.",
          DialogueId = 10104508,
          Duration = 3,
          GUID = "194BAAD8",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10104509,
          SpeakNpcId = 200006,
          Subtitle = "While around Icelake's alleys, what darts out are thieves or bandits... and sometimes just whimpering beggars.",
          VoiceName = "voice/$Locale$/story/1002/101045/194BAAD8"
        },
        [10104509] = {
          ContentEN = "What about your hometown, {nickname}? Tell us about it! What's that island like?",
          DialogueId = 10104509,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194BAB02",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10104510,
          SpeakNpcId = 200006,
          Subtitle = "What about your hometown, ? Tell us about it! What's that island like?",
          VoiceName = "voice/$Locale$/story/1002/101045/194BAB02"
        },
        [10104510] = {
          ContentEN = "The \"air\" is golden gravel and beachside rosemary...",
          DialogueId = 10104510,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194BAB2C",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104511,
          SpeakNpcId = 100001,
          Subtitle = "The \"air\" is golden gravel and beachside rosemary...",
          VoiceName = "voice/$Locale$/story/1002/101045/194BAB2C"
        },
        [10104511] = {
          ContentEN = "It's misty sea fogs at midnight, and the massive Heaventree that Berr... my family and I used to gaze upon every day.",
          DialogueId = 10104511,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194BAB56",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104512,
          SpeakNpcId = 100001,
          Subtitle = "It's misty sea fogs at midnight, and the massive Heaventree that Berr... my family and I used to gaze upon every day.",
          VoiceName = "voice/$Locale$/story/1002/101045/194BAB56"
        },
        [10104512] = {
          ContentEN = "Mmm... if you ever make it back to your homeland, please send them my regards.",
          DialogueId = 10104512,
          Duration = 3,
          GUID = "194BAB80",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10104513,
          SpeakNpcId = 200006,
          Subtitle = "Mmm... if you ever make it back to your homeland, please send them my regards.",
          VoiceName = "voice/$Locale$/story/1002/101045/194BAB80"
        },
        [10104513] = {
          ContentEN = "...Umm, you two are talking over my head...",
          DialogueId = 10104513,
          Duration = 3,
          GUID = "194BABAA",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10104514,
          SpeakNpcId = 200002,
          Subtitle = "...Umm, you two are talking over my head...",
          VoiceName = "voice/$Locale$/story/1002/101045/194BABAA"
        },
        [10104514] = {
          ContentEN = "You'll get it when you're older.",
          DialogueId = 10104514,
          Duration = 3,
          GUID = "194BABD4",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10104515,
          SpeakNpcId = 200006,
          Subtitle = "You'll get it when you're older.",
          VoiceName = "voice/$Locale$/story/1002/101045/194BABD4"
        },
        [10104515] = {
          ContentEN = "...But then again, Lunos never really grow older, do you?",
          DialogueId = 10104515,
          Duration = 3,
          GUID = "194BABFE",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
