        [10128101] = {
          ContentEN = "Please, sir... just let us through. We're only here to sell firewood and maybe buy a little bread...",
          DialogueId = 10128101,
          GUID = "195AC992",
          NextDialogue = 10128102,
          SpeakNpcId = 200089,
          Subtitle = "Please, sir... just let us through. We're only here to sell firewood and maybe buy a little bread...",
          VoiceName = "voice/$Locale$/story/1002/101281/195AC992"
        },
        [10128102] = {
          ContentEN = "No one told us we needed a travel permit. Please, sir... we're running out of food back home...",
          DialogueId = 10128102,
          GUID = "195AC9BC",
          NextDialogue = 10128103,
          SpeakNpcId = 200089,
          Subtitle = "No one told us we needed a travel permit. Please, sir... we're running out of food back home...",
          VoiceName = "voice/$Locale$/story/1002/101281/195AC9BC"
        },
        [10128103] = {
          ContentEN = "You think I want to stand here all day checking that thing? If you lot didn't keep gathering in groups and stirring up trouble, we wouldn't even need them.",
          DialogueId = 10128103,
          GUID = "195AC9E6",
          NextDialogue = 10128104,
          SpeakNpcId = 200071,
          Subtitle = "You think I want to stand here all day checking that thing? If you lot didn't keep gathering in groups and stirring up trouble, we wouldn't even need them.",
          VoiceName = "voice/$Locale$/story/1002/101281/195AC9E6"
        },
        [10128104] = {
          ContentEN = "Heard of The Forsakens, the ones stirring up chaos all over? These permits are meant to catch their kind. So if you're looking for someone to blame, start with your own people.",
          DialogueId = 10128104,
          GUID = "195ACA10",
          NextDialogue = 10128105,
          SpeakNpcId = 200071,
          Subtitle = "Heard of The Forsakens, the ones stirring up chaos all over? These permits are meant to catch their kind. So if you're looking for someone to blame, start with your own people.",
          VoiceName = "voice/$Locale$/story/1002/101281/195ACA10"
        },
        [10128105] = {
          ContentEN = "But I don't know anything about The Forsakens... Alright, sir, could you tell me where to get one of these... travel permits?",
          DialogueId = 10128105,
          GUID = "195ACA3A",
          NextDialogue = 10128106,
          SpeakNpcId = 200089,
          Subtitle = "But I don't know anything about The Forsakens... Alright, sir, could you tell me where to get one of these... travel permits?",
          VoiceName = "voice/$Locale$/story/1002/101281/195ACA3A"
        },
        [10128106] = {
          ContentEN = "Go queue at the Security Bureau.",
          DialogueId = 10128106,
          GUID = "195ACA64",
          NextDialogue = 10128107,
          SpeakNpcId = 200071,
          Subtitle = "Go queue at the Security Bureau.",
          VoiceName = "voice/$Locale$/story/1002/101281/195ACA64"
        },
        [10128107] = {
          ContentEN = "The Security Bureau...? But that's inside the city...",
          DialogueId = 10128107,
          GUID = "195ACA8E",
          NextDialogue = 10128108,
          SpeakNpcId = 200089,
          Subtitle = "The Security Bureau...? But that's inside the city...",
          VoiceName = "voice/$Locale$/story/1002/101281/195ACA8E"
        },
        [10128108] = {
          ContentEN = "Not my problem. Sort it out yourself, and don't come bothering me again. Count yourself lucky I'm not one of the trigger-happy types — they'd shoot first and let the worms handle the rest.",
          DialogueId = 10128108,
          GUID = "195ACAB8",
          NextDialogue = 10128109,
          SpeakNpcId = 200071,
          Subtitle = "Not my problem. Sort it out yourself, and don't come bothering me again. Count yourself lucky I'm not one of the trigger-happy types — they'd shoot first and let the worms handle the rest.",
          VoiceName = "voice/$Locale$/story/1002/101281/195ACAB8"
        },
        [10128109] = {
          ContentEN = "As far as the higher-ups are concerned, every Charon's a potential Forsaken sympathiser. So yeah — good luck.",
          DialogueId = 10128109,
          GUID = "195ACAE2",
          SpeakNpcId = 200071,
          Subtitle = "As far as the higher-ups are concerned, every Charon's a potential Forsaken sympathiser. So yeah — good luck.",
          VoiceName = "voice/$Locale$/story/1002/101281/195ACAE2"
        },
        [10128110] = {
          ContentEN = "But we didn't need a travel permit last time, sir...",
          DialogueId = 10128110,
          GUID = "195ACAE3",
          NextDialogue = 10128111,
          SpeakNpcId = 200089,
          Subtitle = "But we didn't need a travel permit last time, sir...",
          VoiceName = "voice/$Locale$/story/1002/101281/195ACAE3"
        },
        [10128111] = {
          ContentEN = "Don't start whining. Orders are orders — you think I like doing this!?",
          DialogueId = 10128111,
          GUID = "195ACAE4",
          Subtitle = "Don't start whining. Orders are orders — you think I like doing this!?",
          VoiceName = "voice/$Locale$/story/1002/101281/195ACAE4"
        },
        [10128201] = {
          ContentEN = "Forgot my travel permit today too...",
          DialogueId = 10128201,
          GUID = "195AD9FA",
          SpeakNpcId = 200090,
          Subtitle = "Forgot my travel permit today too...",
          VoiceName = "voice/$Locale$/story/1002/101282/195AD9FA"
        },
        [10128202] = {
          ContentEN = "I forgot my permit today too. Lucky they didn't drag me off to a cell...",
          DialogueId = 10128202,
          GUID = "195ADA24",
          NextOptions = {
            [1] = 101282021,
            [2] = 101282022,
            [3] = 101282023
          },
          SpeakNpcId = 200090,
          Subtitle = "I forgot my permit today too. Lucky they didn't drag me off to a cell...",
          VoiceName = "voice/$Locale$/story/1002/101282/195ADA24"
        },
        [10128204] = {
          ContentEN = "Important? Hah... I mean, they say it's to keep The Forsakens out. But if someone's really up to no good, do you think they're strolling through the front gate like it's nothing?",
          DialogueId = 10128204,
          GUID = "195ADA78",
          NextDialogue = 10128205,
          SpeakNpcId = 200090,
          Subtitle = "Important? Hah... I mean, they say it's to keep The Forsakens out. But if someone's really up to no good, do you think they're strolling through the front gate like it's nothing?",
          VoiceName = "voice/$Locale$/story/1002/101282/195ADA78"
        },
        [10128205] = {
          ContentEN = "End of the day, it's just another excuse for the soldiers to push folk like us around. No permit? That makes you \"suspicious.\" Simple as that.",
          DialogueId = 10128205,
          GUID = "195ADAA2",
          NextDialogue = 10128206,
          SpeakNpcId = 200090,
          Subtitle = "End of the day, it's just another excuse for the soldiers to push folk like us around. No permit? That makes you \"suspicious.\" Simple as that.",
          VoiceName = "voice/$Locale$/story/1002/101282/195ADAA2"
        },
        [10128206] = {
          ContentEN = "Most days, you just slip them all the coins in your pocket and they look the other way. But if your luck runs out... well, you saw what happened. That was... brutal.",
          DialogueId = 10128206,
          GUID = "195ADACC",
          NextOptions = {
            [1] = 101282061
          },
          SpeakNpcId = 200090,
          Subtitle = "Most days, you just slip them all the coins in your pocket and they look the other way. But if your luck runs out... well, you saw what happened. That was... brutal.",
          VoiceName = "voice/$Locale$/story/1002/101282/195ADACC"
        },
        [10128208] = {
          ContentEN = "Some, yeah. If the officer in charge is a Laurelled Charon, the soldiers under 'em usually act a bit better.",
          DialogueId = 10128208,
          GUID = "195ADB20",
          NextDialogue = 10128209,
          SpeakNpcId = 200090,
          Subtitle = "Some, yeah. If the officer in charge is a Laurelled Charon, the soldiers under 'em usually act a bit better.",
          VoiceName = "voice/$Locale$/story/1002/101282/195ADB20"
        },
        [10128209] = {
          ContentEN = "Take Chief Sibylle and that new one, Officer Fischer for example — they keep their unit on a tight leash.",
          DialogueId = 10128209,
          GUID = "195ADB4A",
          NextDialogue = 10128210,
          SpeakNpcId = 200090,
          Subtitle = "Take Chief Sibylle and that new one, Officer Fischer for example — they keep their unit on a tight leash.",
          VoiceName = "voice/$Locale$/story/1002/101282/195ADB4A"
        },
        [10128210] = {
          ContentEN = "Anyway... I should go grab my permit before someone else decides I look \"suspicious.\"",
          DialogueId = 10128210,
          GUID = "195ADB74",
          SpeakNpcId = 200090,
          Subtitle = "Anyway... I should go grab my permit before someone else decides I look \"suspicious.\"",
          VoiceName = "voice/$Locale$/story/1002/101282/195ADB74"
        },
        [10128212] = {
          ContentEN = "Punished? Sure. Maybe a couple nights in the brig, a slap-on-the-wrist fine. That's about it.",
          DialogueId = 10128212,
          GUID = "195ADBC8",
          NextDialogue = 10128213,
          SpeakNpcId = 200090,
          Subtitle = "Punished? Sure. Maybe a couple nights in the brig, a slap-on-the-wrist fine. That's about it.",
          VoiceName = "voice/$Locale$/story/1002/101282/195ADBC8"
        },
        [10128213] = {
          ContentEN = "But what can we do? This is Hyperborea. Charons were born a rung below the Solas — all because we lost the war.",
          DialogueId = 10128213,
          GUID = "195ADBF2",
          NextDialogue = 10128214,
          SpeakNpcId = 200090,
          Subtitle = "But what can we do? This is Hyperborea. Charons were born a rung below the Solas — all because we lost the war.",
          VoiceName = "voice/$Locale$/story/1002/101282/195ADBF2"
        },
        [10128214] = {
          ContentEN = "I heard there's a place far out east, a nation called Huaxu. Word is, things are different there — Charons live proper lives.",
          DialogueId = 10128214,
          GUID = "195ADC1C",
          NextOptions = {
            [1] = 101282141
          },
          SpeakNpcId = 200090,
          Subtitle = "I heard there's a place far out east, a nation called Huaxu. Word is, things are different there — Charons live proper lives.",
          VoiceName = "voice/$Locale$/story/1002/101282/195ADC1C"
        },
        [10128216] = {
          ContentEN = "*sigh* Because they slap Charons with all sorts of \"supervision levies.\" Just being who we are costs extra. And the trip to Huaxu? That'd bleed me dry.",
          DialogueId = 10128216,
          GUID = "195ADC70",
          NextDialogue = 10128217,
          SpeakNpcId = 200090,
          Subtitle = "*sigh* Because they slap Charons with all sorts of \"supervision levies.\" Just being who we are costs extra. And the trip to Huaxu? That'd bleed me dry.",
          VoiceName = "voice/$Locale$/story/1002/101282/195ADC70"
        },
        [10128217] = {
          ContentEN = "Even if I managed to scrape together enough for myself, I've got my wife and kids to think about... But you — you're still young. Maybe you've got a shot. Save what you can.",
          DialogueId = 10128217,
          GUID = "195ADC9A",
          SpeakNpcId = 200090,
          Subtitle = "Even if I managed to scrape together enough for myself, I've got my wife and kids to think about... But you — you're still young. Maybe you've got a shot. Save what you can.",
          VoiceName = "voice/$Locale$/story/1002/101282/195ADC9A"
        },
        [10128301] = {
          ContentEN = "That's the third one this month...",
          DialogueId = 10128301,
          GUID = "195AEA62",
          SpeakNpcId = 200091,
          Subtitle = "That's the third one this month...",
          VoiceName = "voice/$Locale$/story/1002/101283/195AEA62"
        },
        [10128302] = {
          ContentEN = "Third one this month... I reckon. What's the point of keeping my stall open anymore? Might as well join The Forsakens myself.",
          DialogueId = 10128302,
          GUID = "195AEA8C",
          NextOptions = {
            [1] = 101283021,
            [2] = 101283022,
            [3] = 101283023
          },
          SpeakNpcId = 200091,
          Subtitle = "Third one this month... I reckon. What's the point of keeping my stall open anymore? Might as well join The Forsakens myself.",
          VoiceName = "voice/$Locale$/story/1002/101283/195AEA8C"
        },
        [10128304] = {
          ContentEN = "Third Charon this month caught without a travel permit. They all argued with the guards and then got branded a member of The Forsakens...",
          DialogueId = 10128304,
          GUID = "195AEAE0",
          NextDialogue = 10128305,
          SpeakNpcId = 200091,
          Subtitle = "Third Charon this month caught without a travel permit. They all argued with the guards and then got branded a member of The Forsakens...",
          VoiceName = "voice/$Locale$/story/1002/101283/195AEAE0"
        },
        [10128305] = {
          ContentEN = "Can you believe it? Treated like dirt — just because we're Charons and they're Solas.",
          DialogueId = 10128305,
          GUID = "195AEB0A",
          NextDialogue = 10128306,
          SpeakNpcId = 200091,
          Subtitle = "Can you believe it? Treated like dirt — just because we're Charons and they're Solas.",
          VoiceName = "voice/$Locale$/story/1002/101283/195AEB0A"
        },
        [10128306] = {
          ContentEN = "Hmph. If we'd won the uprising, they wouldn't be walking around like they own the place. But we didn't — and here we are...",
          DialogueId = 10128306,
          GUID = "195AEB34",
          NextOptions = {
            [1] = 101283061
          },
          SpeakNpcId = 200091,
          Subtitle = "Hmph. If we'd won the uprising, they wouldn't be walking around like they own the place. But we didn't — and here we are...",
          VoiceName = "voice/$Locale$/story/1002/101283/195AEB34"
        },
        [10128308] = {
          ContentEN = "You don't know? Ah, figures. You look young. Probably weren't even born yet. Go ask your folks — back then, nearly every Charon in the Empire got swept up in it.",
          DialogueId = 10128308,
          GUID = "195AEB88",
          NextDialogue = 10128309,
          SpeakNpcId = 200091,
          Subtitle = "You don't know? Ah, figures. You look young. Probably weren't even born yet. Go ask your folks — back then, nearly every Charon in the Empire got swept up in it.",
          VoiceName = "voice/$Locale$/story/1002/101283/195AEB88"
        },
        [10128309] = {
          ContentEN = "We got as far as the capital. Frontlines broke through — nearly took the place. But we lost it, right at the end. That's why they keep their boot on our necks now.",
          DialogueId = 10128309,
          GUID = "195AEBB2",
          NextDialogue = 10128310,
          SpeakNpcId = 200091,
          Subtitle = "We got as far as the capital. Frontlines broke through — nearly took the place. But we lost it, right at the end. That's why they keep their boot on our necks now.",
          VoiceName = "voice/$Locale$/story/1002/101283/195AEBB2"
        },
        [10128310] = {
          ContentEN = "Still... the way His Majesty runs things these days, I wouldn't be surprised if another war breaks out soon enough.",
          DialogueId = 10128310,
          GUID = "195AEBDC",
          SpeakNpcId = 200091,
          Subtitle = "Still... the way His Majesty runs things these days, I wouldn't be surprised if another war breaks out soon enough.",
          VoiceName = "voice/$Locale$/story/1002/101283/195AEBDC"
        },
        [10128312] = {
          ContentEN = "What, you interested? Or are you planning to rat me out?",
          DialogueId = 10128312,
          GUID = "195AEC30",
          NextDialogue = 10128313,
          SpeakNpcId = 200091,
          Subtitle = "What, you interested? Or are you planning to rat me out?",
          VoiceName = "voice/$Locale$/story/1002/101283/195AEC30"
        },
        [10128313] = {
          ContentEN = "...*sigh* I'm just blowing off steam. The Forsakens might be the Charon resistance, but even if you're Charon, it's nearly impossible to find them.",
          DialogueId = 10128313,
          GUID = "195AEC5A",
          NextDialogue = 10128314,
          SpeakNpcId = 200091,
          Subtitle = "...*sigh* I'm just blowing off steam. The Forsakens might be the Charon resistance, but even if you're Charon, it's nearly impossible to find them.",
          VoiceName = "voice/$Locale$/story/1002/101283/195AEC5A"
        },
        [10128314] = {
          ContentEN = "After the uprising failed, they vanished underground. No one knows how many are left — or if they even meet at all anymore.",
          DialogueId = 10128314,
          GUID = "195AEC84",
          NextDialogue = 10128315,
          SpeakNpcId = 200091,
          Subtitle = "After the uprising failed, they vanished underground. No one knows how many are left — or if they even meet at all anymore.",
          VoiceName = "voice/$Locale$/story/1002/101283/195AEC84"
        },
        [10128315] = {
          ContentEN = "Some say they're long gone. That it's just the Security Bureau making things up — whenever they can't solve a case, they blame it on The Forsakens to save face.",
          DialogueId = 10128315,
          GUID = "195AECAE",
          NextDialogue = 10128316,
          SpeakNpcId = 200091,
          Subtitle = "Some say they're long gone. That it's just the Security Bureau making things up — whenever they can't solve a case, they blame it on The Forsakens to save face.",
          VoiceName = "voice/$Locale$/story/1002/101283/195AECAE"
        },
        [10128316] = {
          ContentEN = "Still... I believe they're out there. Lying low, waiting. And when the time comes — the Solas will pay for every drop of blood they spilt.",
          DialogueId = 10128316,
          GUID = "195AECD8",
          SpeakNpcId = 200091,
          Subtitle = "Still... I believe they're out there. Lying low, waiting. And when the time comes — the Solas will pay for every drop of blood they spilt.",
          VoiceName = "voice/$Locale$/story/1002/101283/195AECD8"
        },
        [10128401] = {
          ContentEN = "Big house, isn't it? Bit spooky, though...",
          DialogueId = 10128401,
          GUID = "195AFACA",
          SpeakNpcId = 200092,
          Subtitle = "Big house, isn't it? Bit spooky, though...",
          VoiceName = "voice/$Locale$/story/1002/101284/195AFACA"
        },
        [10128402] = {
          ContentEN = "Big house, sure... but definitely cursed. Folks who can afford it won't touch the place. And the ones who'd dare live here? Can't afford to own it.",
          DialogueId = 10128402,
          GUID = "195AFAF4",
          NextOptions = {
            [1] = 101284021,
            [2] = 101284022,
            [3] = 101284023,
            [4] = 101284024
          },
          SpeakNpcId = 200092,
          Subtitle = "Big house, sure... but definitely cursed. Folks who can afford it won't touch the place. And the ones who'd dare live here? Can't afford to own it.",
          VoiceName = "voice/$Locale$/story/1002/101284/195AFAF4"
        },
        [10128404] = {
          ContentEN = "Of course! You haven't heard? This is one of the two most infamous cursed houses in Icelake! Everyone who's ever moved in either ran afoul of the Empire... or mysteriously vanished, separated from their loved ones.",
          DialogueId = 10128404,
          GUID = "195AFB48",
          NextDialogue = 10128405,
          SpeakNpcId = 200092,
          Subtitle = "Of course! You haven't heard? This is one of the two most infamous cursed houses in Icelake! Everyone who's ever moved in either ran afoul of the Empire... or mysteriously vanished, separated from their loved ones.",
          VoiceName = "voice/$Locale$/story/1002/101284/195AFB48"
        },
        [10128405] = {
          ContentEN = "As for the other one — you just came from it — the Hypnos' House. They say if you stand near it at night, you can hear weeping through the walls.",
          DialogueId = 10128405,
          GUID = "195AFB72",
          NextDialogue = 10128406,
          SpeakNpcId = 200092,
          Subtitle = "As for the other one — you just came from it — the Hypnos' House. They say if you stand near it at night, you can hear weeping through the walls.",
          VoiceName = "voice/$Locale$/story/1002/101284/195AFB72"
        },
        [10128406] = {
          ContentEN = "Funny thing is... both houses happen to be owned by the same person — Henrik.",
          DialogueId = 10128406,
          GUID = "195AFB9C",
          SpeakNpcId = 200092,
          Subtitle = "Funny thing is... both houses happen to be owned by the same person — Henrik.",
          VoiceName = "voice/$Locale$/story/1002/101284/195AFB9C"
        },
        [10128408] = {
          ContentEN = "Snooping? Come now — a mansion like this gets new tenants, and I'm not even allowed a little curiosity?",
          DialogueId = 10128408,
          GUID = "195AFBF0",
          NextDialogue = 10128409,
          SpeakNpcId = 200092,
          Subtitle = "Snooping? Come now — a mansion like this gets new tenants, and I'm not even allowed a little curiosity?",
          VoiceName = "voice/$Locale$/story/1002/101284/195AFBF0"
        },
        [10128409] = {
          ContentEN = "I know every household in Icelake — top to bottom, side to side. All from good old-fashioned asking around, mind you. Never once been accused of \"snooping.\"",
          DialogueId = 10128409,
          GUID = "195AFC1A",
          NextDialogue = 10128410,
          SpeakNpcId = 200092,
          Subtitle = "I know every household in Icelake — top to bottom, side to side. All from good old-fashioned asking around, mind you. Never once been accused of \"snooping.\"",
          VoiceName = "voice/$Locale$/story/1002/101284/195AFC1A"
        },
        [10128410] = {
          ContentEN = "But if I'm making you uncomfortable... I'll be on my way. I have a feeling we'll cross paths again.",
          DialogueId = 10128410,
          GUID = "195AFC44",
          SpeakNpcId = 200092,
          Subtitle = "But if I'm making you uncomfortable... I'll be on my way. I have a feeling we'll cross paths again.",
          VoiceName = "voice/$Locale$/story/1002/101284/195AFC44"
        },
        [10128412] = {
          ContentEN = "Me? Just someone who lives off ink and paper. You can call me Ansuz — intrepid journalist extraordinaire!",
          DialogueId = 10128412,
          GUID = "195AFC98",
          NextDialogue = 10128413,
          SpeakNpcId = 200092,
          Subtitle = "Me? Just someone who lives off ink and paper. You can call me Ansuz — intrepid journalist extraordinaire!",
          VoiceName = "voice/$Locale$/story/1002/101284/195AFC98"
        },
        [10128413] = {
          ContentEN = "I go where the whispers lead, unearth the truth, and weave it into tales to bring a bit of cheer to the fine folks of Icelake.",
          DialogueId = 10128413,
          GUID = "195AFCC2",
          NextDialogue = 10128414,
          SpeakNpcId = 200092,
          Subtitle = "I go where the whispers lead, unearth the truth, and weave it into tales to bring a bit of cheer to the fine folks of Icelake.",
          VoiceName = "voice/$Locale$/story/1002/101284/195AFCC2"
        },
        [10128414] = {
          ContentEN = "What's with that look? Go on, take one — today's issue of the Icelake Daily. On the house. If you like what you read, come find me for the next one.",
          DialogueId = 10128414,
          GUID = "195AFCEC",
          NextDialogue = 10128415,
          SpeakNpcId = 200092,
          Subtitle = "What's with that look? Go on, take one — today's issue of the Icelake Daily. On the house. If you like what you read, come find me for the next one.",
          VoiceName = "voice/$Locale$/story/1002/101284/195AFCEC"
        },
        [10128415] = {
          ContentEN = "And if you've got a juicy lead, come find me — I'll trade you a fresh copy for it.",
          DialogueId = 10128415,
          GUID = "195AFD16",
          SpeakNpcId = 200092,
          Subtitle = "And if you've got a juicy lead, come find me — I'll trade you a fresh copy for it.",
          VoiceName = "voice/$Locale$/story/1002/101284/195AFD16"
        },
        [10128501] = {
          ContentEN = "Miss Margie brought the money again!",
          DialogueId = 10128501,
          GUID = "195B0B32",
          NextDialogue = 10128502,
          SpeakNpcId = 200093,
          Subtitle = "Miss Margie brought the money again!",
          VoiceName = "voice/$Locale$/story/1002/101285/195B0B32"
        },
        [10128502] = {
          ContentEN = "But we can't rely on her forever.",
          DialogueId = 10128502,
          GUID = "195B0B5C",
          SpeakNpcId = 200094,
          Subtitle = "But we can't rely on her forever.",
          VoiceName = "voice/$Locale$/story/1002/101285/195B0B5C"
        },
        [10128503] = {
          ContentEN = "Miss Margie brought us the money again — we won't have to worry about going hungry this month! She's the best!",
          DialogueId = 10128503,
          GUID = "195B0B86",
          NextDialogue = 10128504,
          SpeakNpcId = 200093,
          Subtitle = "Miss Margie brought us the money again — we won't have to worry about going hungry this month! She's the best!",
          VoiceName = "voice/$Locale$/story/1002/101285/195B0B86"
        },
        [10128504] = {
          ContentEN = "I heard someone tried to steal it. Miss Margie and a kind Phoxhunter went through a lot just to get it back.",
          DialogueId = 10128504,
          GUID = "195B0BB0",
          NextDialogue = 10128505,
          SpeakNpcId = 200094,
          Subtitle = "I heard someone tried to steal it. Miss Margie and a kind Phoxhunter went through a lot just to get it back.",
          VoiceName = "voice/$Locale$/story/1002/101285/195B0BB0"
        },
        [10128505] = {
          ContentEN = "We can't keep going like this. It's not right. We're depending on her too much... If — stars forbid — something ever happened to Miss Margie, what would we do? Just sit here and starve?",
          DialogueId = 10128505,
          GUID = "195B0BDA",
          NextDialogue = 10128506,
          SpeakNpcId = 200094,
          Subtitle = "We can't keep going like this. It's not right. We're depending on her too much... If — stars forbid — something ever happened to Miss Margie, what would we do? Just sit here and starve?",
          VoiceName = "voice/$Locale$/story/1002/101285/195B0BDA"
        },
        [10128506] = {
          ContentEN = "If I eat enough and grow strong, maybe I can become a Phoxhunter too! Then I'll help Miss Margie!",
          DialogueId = 10128506,
          GUID = "195B0C04",
          NextDialogue = 10128507,
          SpeakNpcId = 200093,
          Subtitle = "If I eat enough and grow strong, maybe I can become a Phoxhunter too! Then I'll help Miss Margie!",
          VoiceName = "voice/$Locale$/story/1002/101285/195B0C04"
        },
        [10128507] = {
          ContentEN = "Then eat up. Here — I can't finish this biscuit, so take half. When you're taller than Miss Margie's shovel, you can take her place... and start looking after everyone here in the slums.",
          DialogueId = 10128507,
          GUID = "195B0C2E",
          NextDialogue = 10128508,
          SpeakNpcId = 200094,
          Subtitle = "Then eat up. Here — I can't finish this biscuit, so take half. When you're taller than Miss Margie's shovel, you can take her place... and start looking after everyone here in the slums.",
          VoiceName = "voice/$Locale$/story/1002/101285/195B0C2E"
        },
        [10128508] = {
          ContentEN = "Okay! But I bet by then, no one here will have to starve anymore. We won't need anyone's charity ever again!",
          DialogueId = 10128508,
          GUID = "195B0C58",
          NextDialogue = 10128509,
          SpeakNpcId = 200093,
          Subtitle = "Okay! But I bet by then, no one here will have to starve anymore. We won't need anyone's charity ever again!",
          VoiceName = "voice/$Locale$/story/1002/101285/195B0C58"
        },
        [10128509] = {
          ContentEN = "If only that day would come... Then Miss Margie — and the rest of us — wouldn't have to struggle so hard anymore. Ugh, slow down — no one's taking your food, you know...",
          DialogueId = 10128509,
          GUID = "195B0C82",
          NextDialogue = 10128510,
          SpeakNpcId = 200094,
          Subtitle = "If only that day would come... Then Miss Margie — and the rest of us — wouldn't have to struggle so hard anymore. Ugh, slow down — no one's taking your food, you know...",
          VoiceName = "voice/$Locale$/story/1002/101285/195B0C82"
        },
        [10128510] = {
          ContentEN = "Nom nom... mmph...!",
          DialogueId = 10128510,
          GUID = "195B0CAC",
          SpeakNpcId = 200093,
          Subtitle = "Nom nom... mmph...!",
          VoiceName = "voice/$Locale$/story/1002/101285/195B0CAC"
        },
        [10128601] = {
          ContentEN = "Nearly eight o'clock, isn't it...?",
          DialogueId = 10128601,
          GUID = "195B1B9A",
          SpeakNpcId = 200092,
          Subtitle = "Nearly eight o'clock, isn't it...?",
          VoiceName = "voice/$Locale$/story/1002/101286/195B1B9A"
        },
        [10128602] = {
          ContentEN = "I'm supposed to meet a friend at The Asphodel at eight, but I forgot my pocket watch. So I came here instead. Once I spot Henrik, I'll know it's exactly eight on the dot.",
          DialogueId = 10128602,
          GUID = "195B1BC4",
          NextOptions = {
            [1] = 101286021,
            [2] = 101286022,
            [3] = 101286023
          },
          SpeakNpcId = 200092,
          Subtitle = "I'm supposed to meet a friend at The Asphodel at eight, but I forgot my pocket watch. So I came here instead. Once I spot Henrik, I'll know it's exactly eight on the dot.",
          VoiceName = "voice/$Locale$/story/1002/101286/195B1BC4"
        },
        [10128604] = {
          ContentEN = "Oh, I just know. Henrik's like clockwork — always steps out the door at the exact same time, eats at the exact same time...",
          DialogueId = 10128604,
          GUID = "195B1C18",
          NextDialogue = 10128605,
          SpeakNpcId = 200092,
          Subtitle = "Oh, I just know. Henrik's like clockwork — always steps out the door at the exact same time, eats at the exact same time...",
          VoiceName = "voice/$Locale$/story/1002/101286/195B1C18"
        },
        [10128605] = {
          ContentEN = "Honestly, I wouldn't be surprised if he breathes on a schedule. Actually, that might make a good headline — \"Live By the Clock: Take Back Control.\" Catchy, right?",
          DialogueId = 10128605,
          GUID = "195B1C42",
          SpeakNpcId = 200092,
          Subtitle = "Honestly, I wouldn't be surprised if he breathes on a schedule. Actually, that might make a good headline — \"Live By the Clock: Take Back Control.\" Catchy, right?",
          VoiceName = "voice/$Locale$/story/1002/101286/195B1C42"
        },
