        },
        [10128702] = {
          ContentEN = "*sigh* Maybe I shouldn't write about it at all... Bad news is all there is these days. No sense dragging folks down even further.",
          DialogueId = 10128702,
          GUID = "195B2C2C",
          NextOptions = {
            [1] = 101287021,
            [2] = 101287022,
            [3] = 101287023,
