          GUID = "195BD065",
          NextDialogue = 10131308,
          SpeakNpcId = 200002,
          Subtitle = "Then bring it back to Lunosmith, Little Minion. As for now, let this Demon King continue to lead you deeper into the pit!",
          VoiceName = "voice/$Locale$/story/1002/101313/195BD065"
        },
        [10131308] = {
