        },
        [11010404] = {
          ContentEN = "I failed to protect you. I'm sorry.",
          DialogueId = 11010404,
          GUID = "1B903A68",
          ImprPlusId = 1007,
          NextDialogue = 11010405,
          Subtitle = "I failed to protect you. I'm sorry."
        },
        [11010405] = {
          ContentEN = "Please don't say that, Captain! You did your best!",
          DialogueId = 11010405,
          Duration = 3,
          GUID = "1B903A92",
          NextDialogue = 11010408,
          SpeakNpcId = 110044,
          Subtitle = "Please don't say that, Captain! You did your best!",
          VoiceName = "voice/$Locale$/story/1002/110104/1B903A92"
        },
        [11010406] = {
          ContentEN = "Who are you cursing at?",
          DialogueId = 11010406,
          GUID = "1B903ABC",
          ImprPlusId = 1010,
          NextDialogue = 11010407,
          Subtitle = "Who are you cursing at?"
        },
        [11010407] = {
          ContentEN = "Who else could it be? The bastards who call themselves The Forsakens.",
          DialogueId = 11010407,
          Duration = 3,
          GUID = "1B903AE6",
          NextDialogue = 11010408,
          SpeakNpcId = 110044,
          Subtitle = "Who else could it be? The bastards who call themselves The Forsakens.",
          VoiceName = "voice/$Locale$/story/1002/110104/1B903AE6"
        },
        [11010408] = {
          ContentEN = "Those despicable cowards are using Filthoids as their weapon... <W>The Forsakens</> are monsters, just like their Filthoid pets!",
          DialogueId = 11010408,
          Duration = 3,
          GUID = "1B903B10",
          NextDialogue = 11010409,
          RelatedWikiId = {
            [1] = 101004
          },
          SpeakNpcId = 110044,
          Subtitle = "Those despicable cowards are using Filthoids as their weapon... The Forsakens are monsters, just like their Filthoid pets!",
          VoiceName = "voice/$Locale$/story/1002/110104/1B903B10"
        },
        [11010409] = {
          ContentEN = "And those blasted airheads giving us the orders are just as bad. The mission brief mentioned nothing about the Filthoid hordes down here.",
          DialogueId = 11010409,
          Duration = 3,
          GUID = "1B903B3A",
          NextDialogue = 11010410,
          SpeakNpcId = 110044,
          Subtitle = "And those blasted airheads giving us the orders are just as bad. The mission brief mentioned nothing about the Filthoid hordes down here.",
          VoiceName = "voice/$Locale$/story/1002/110104/1B903B3A"
        },
        [11010410] = {
          ContentEN = "...Sorry about that. I shouldn't have vented my frustration in front of you, Captain.",
          DialogueId = 11010410,
          Duration = 3,
          GUID = "1B903B64",
          NextDialogue = 11010411,
          SpeakNpcId = 110044,
          Subtitle = "...Sorry about that. I shouldn't have vented my frustration in front of you, Captain.",
          VoiceName = "voice/$Locale$/story/1002/110104/1B903B64"
        },
        [11010411] = {
          ContentEN = "It's alright. Letting out emotions is better than being unable to speak at all.",
          DialogueId = 11010411,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B903B8E",
          NextDialogue = 11010412,
          SpeakNpcId = 110022,
          Subtitle = "It's alright. Letting out emotions is better than being unable to speak at all.",
          VoiceName = "voice/$Locale$/story/1002/110104/1B903B8E"
        },
        [11010412] = {
          ContentEN = "Hah! You always know how to soothe people, Captain!",
          DialogueId = 11010412,
          Duration = 3,
          GUID = "1B903BB8",
          NextDialogue = 11010413,
          SpeakNpcId = 110044,
          Subtitle = "Hah! You always know how to soothe people, Captain!",
          VoiceName = "voice/$Locale$/story/1002/110104/1B903BB8"
        },
        [11010413] = {
          ContentEN = "And thank goodness we have you. We thought we were goners.",
          DialogueId = 11010413,
          Duration = 3,
          GUID = "1B903BE2",
          NextDialogue = 11010414,
          SpeakNpcId = 110044,
          Subtitle = "And thank goodness we have you. We thought we were goners.",
          VoiceName = "voice/$Locale$/story/1002/110104/1B903BE2"
        },
        [11010414] = {
          ContentEN = "It's just that we're too green. If only <H>Commander Avar</> were here... As a veteran, he must have a way to get us out.",
          DialogueId = 11010414,
          Duration = 3,
          GUID = "1B903C0C",
          SpeakNpcId = 110044,
          Subtitle = "It's just that we're too green. If only Commander Avar were here... As a veteran, he must have a way to get us out.",
          VoiceName = "voice/$Locale$/story/1002/110104/1B903C0C"
        },
        [11010415] = {
          ContentEN = "(Sir Avar... Still no words from him.)",
          DialogueId = 11010415,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B903C36",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(Sir Avar... Still no words from him.)",
          VoiceName = "voice/$Locale$/story/1002/110104/1B903C36"
        },
        [11010416] = {
          ContentEN = "Please be careful. I'll be waiting for you right here.",
          DialogueId = 11010416,
          GUID = "1B903C37",
          SpeakNpcId = 110005,
          Subtitle = "Please be careful. I'll be waiting for you right here.",
          VoiceName = "voice/$Locale$/story/1002/110104/1B903C37"
        },
        [11010501] = {
          ContentEN = "Doctor... Dr Daphne... We're stuck in this bloody dump. Please, Dr Daphne, if I don't make it, do me a favour and bury me...",
          DialogueId = 11010501,
          Duration = 3,
          GUID = "1B904A52",
          NextOptions = {
