        },
        [11010506] = {
          ContentEN = "Dr Daphne and you covered our retreat just then. How is she?",
          DialogueId = 11010506,
          Duration = 3,
          GUID = "1B904B24",
          NextDialogue = 11010507,
          SpeakNpcId = 110045,
          Subtitle = "Dr Daphne and you covered our retreat just then. How is she?",
          VoiceName = "voice/$Locale$/story/1002/110105/1B904B24"
        },
        [11010507] = {
          ContentEN = "She's all right. She told me to come check on all of you.",
          DialogueId = 11010507,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B904B4E",
          NextDialogue = 11010508,
          SpeakNpcId = 110022,
          Subtitle = "She's all right. She told me to come check on all of you.",
          VoiceName = "voice/$Locale$/story/1002/110105/1B904B4E"
        },
        [11010508] = {
          ContentEN = "Good to hear that. *sigh* A high-born lady like her could've stayed at the Academy, but no, she chose to serve with the 13th Legion. What was she thinking?",
          DialogueId = 11010508,
          Duration = 3,
          GUID = "1B904B78",
          NextDialogue = 11010509,
          RelatedWikiId = {
            [1] = 101007
          },
          SpeakNpcId = 110045,
          Subtitle = "Good to hear that. *sigh* A high-born lady like her could've stayed at the Academy, but no, she chose to serve with the 13th Legion. What was she thinking?",
          VoiceName = "voice/$Locale$/story/1002/110105/1B904B78"
        },
        [11010509] = {
          ContentEN = "...\"Eternal glory and loyalty to our Emperor!\" Those aristocrats say that all the time. I wonder if any of them would still be so keen on that when they're actually in a filth pit like this.",
          DialogueId = 11010509,
          Duration = 3,
          GUID = "1B904BA2",
          NextDialogue = 11010510,
          SpeakNpcId = 110045,
          Subtitle = "...\"Eternal glory and loyalty to our Emperor!\" Those aristocrats say that all the time. I wonder if any of them would still be so keen on that when they're actually in a filth pit like this.",
          VoiceName = "voice/$Locale$/story/1002/110105/1B904BA2"
        },
        [11010510] = {
          ContentEN = "But Dr Daphne has real medical skills and a soft, pretty voice. We gotta keep her safe, Captain. Don't want her to die here.",
          DialogueId = 11010510,
          Duration = 3,
          GUID = "1B904BCC",
          SpeakNpcId = 110045,
          Subtitle = "But Dr Daphne has real medical skills and a soft, pretty voice. We gotta keep her safe, Captain. Don't want her to die here.",
          VoiceName = "voice/$Locale$/story/1002/110105/1B904BCC"
        },
