        [11010710] = {
          ContentEN = "We're currently in the storage area where the exit is blocked. However, there are some <H>underground tunnels</> that we haven't checked yet.",
          DialogueId = 11010710,
          Duration = 3,
          GUID = "1B906C9C",
          NextDialogue = 11010711,
          SpeakNpcId = 110005,
          Subtitle = "We're currently in the storage area where the exit is blocked. However, there are some underground tunnels that we haven't checked yet.",
          VoiceName = "voice/$Locale$/story/1002/110107/1B906C9C"
        },
        [11010711] = {
          ContentEN = "Most imperial cities and fortresses have elaborate networks of underground sewers. In recent years, some of these tunnels were expanded and reinforced to serve as air raid shelters.",
          DialogueId = 11010711,
          Duration = 3,
          GUID = "1B906CC6",
          NextDialogue = 11010712,
          SpeakNpcId = 110005,
          Subtitle = "Most imperial cities and fortresses have elaborate networks of underground sewers. In recent years, some of these tunnels were expanded and reinforced to serve as air raid shelters.",
          TalkActionId = {
            [1] = "110005:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110107/1B906CC6"
        },
        [11010712] = {
          ContentEN = "If we're lucky enough and The Forsakens didn't set up any ambushes, maybe we could get the wounded there to rest and recover. Besides, the sewer tunnels run all the way outside the fortress, so if our reinforcements arrive, they can easily get to us.",
          DialogueId = 11010712,
          Duration = 3,
          GUID = "1B906CF0",
          NextDialogue = 11010713,
          SpeakNpcId = 110005,
          Subtitle = "If we're lucky enough and The Forsakens didn't set up any ambushes, maybe we could get the wounded there to rest and recover. Besides, the sewer tunnels run all the way outside the fortress, so if our reinforcements arrive, they can easily get to us.",
