          NextDialogue = 11011308,
          SpeakNpcId = 110010,
          Subtitle = "Regardless of how our plans got out, The Forsakens were undoubtedly well-prepared.",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110113/1B90CE8E"
        },
        [11011308] = {
          ContentEN = "They used the fortress's defense systems to ambush us, and even lured a bunch of Filthoids here... We planned for an infiltration strike, so none of us were equipped with heavy weapons for large beasts. The only option was to throw our lives at it.",
          DialogueId = 11011308,
          FacialId = {
