          Duration = 3,
          GUID = "1B91267E",
          NextDialogue = 11011844,
          SpeakNpcId = 110015,
          Subtitle = "Right, you have a point there."
        },
        [11011844] = {
          ContentEN = "There's no need to so on guard. We Charons are ordinary people too, with families we're desperate to see again.",
          DialogueId = 11011844,
          Duration = 3,
          GUID = "1B9126A8",
          NextDialogue = 11011845,
          SpeakNpcId = 110034,
          Subtitle = "There's no need to so on guard. We Charons are ordinary people too, with families we're desperate to see again."
        },
