          GUID = "1B9126D2",
          NextDialogue = 11011846,
          SpeakNpcId = 110017,
          Subtitle = "...*sigh* Katya..."
        },
        [11011846] = {
          ContentEN = "...Captain, why did you stop me!?",
          DialogueId = 11011846,
          GUID = "1B9126FC",
          NextDialogue = 11011847,
          SpeakNpcId = 110016,
          Subtitle = "...Captain, why did you stop me!?"
        },
        [11011847] = {
          ContentEN = "Not all Charons are rebels from The Forsakens — Commander Avar is a Charon, remember? And even if they are, they'd be worth more to us alive.",
          DialogueId = 11011847,
          ExStoryInfo = "EXPlayer",
          GUID = "1B912726",
          NextDialogue = 11011848,
          SpeakNpcId = 110022,
          Subtitle = "Not all Charons are rebels from The Forsakens — Commander Avar is a Charon, remember? And even if they are, they'd be worth more to us alive."
        },
        [11011848] = {
          ContentEN = "...An inner voice might tell you otherwise, Marco, but don't listen to it. Don't let emotions cloud your judgment.",
          DialogueId = 11011848,
          ExStoryInfo = "EXPlayer",
          GUID = "1B912750",
          SpeakNpcId = 110022,
          Subtitle = "...An inner voice might tell you otherwise, Marco, but don't listen to it. Don't let emotions cloud your judgment."
