          TalkActionId = {
            [1] = "110005:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110151/1B934560"
        },
        [11015153] = {
          Camera = "179.789062,39.516891,181.891464,0.000178,-14.491817,-158.539825,35.0,100000.0,false,Disable,22.0",
          ContentEN = "But Fulvis has already condemned us and even fabricated evidence... Wait, I get why you want to turn ourselves in.",
