          GUID = "1B94B978",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 11017421,
          SpeakNpcId = 110034,
          Subtitle = "They refer to this place as a \"Simulated Battlefield,\" saying that... \"The theme this time is the Defence of Icelake City.\"",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B978"
        },
        [11017421] = {
          ContentEN = "I heard that this Icelake City is covered in snow, something that I've never seen in my entire life... How I wish I could go there and see it myself!",
