        [11018807] = {
          ContentEN = [[
Lonza Fortress Maintenance Log
Safety Hazards:
1. Underground Sewers: Severe corrosion in the piping. High-pressure gas leaks occur frequently. Several maintenance personnel have already suffered burns.
Reply: Perfect. If our own engineers can't get in, neither can those slippery Forsakens.]],
          DialogueId = 11018807,
          GUID = "1B959D06",
          NextDialogue = 11018808,
          Subtitle = [[
Lonza Fortress Maintenance Log
Safety Hazards:
1. Underground Sewers: Severe corrosion in the piping. High-pressure gas leaks occur frequently. Several maintenance personnel have already suffered burns.
Reply: Perfect. If our own engineers can't get in, neither can those slippery Forsakens.]],
          VoiceName = "voice/$Locale$/story/1002/110188/1B959D06"
        },
        [11018808] = {
          ContentEN = "2. Engine Room: The fortress currently depends on a single power source. If the enemy takes the engine room, all defensive systems will go offline.\nRecommendation: Establish a backup engine room or redesign the grid so each area — like the central control room — has its own independent power supply.\nReply: Brilliant. Who's footing the bill, then?",
          DialogueId = 11018808,
          GUID = "1B959D30",
          NextDialogue = 11018809,
          Subtitle = "2. Engine Room: The fortress currently depends on a single power source. If the enemy takes the engine room, all defensive systems will go offline.\nRecommendation: Establish a backup engine room or redesign the grid so each area — like the central control room — has its own independent power supply.\nReply: Brilliant. Who's footing the bill, then?",
          VoiceName = "voice/$Locale$/story/1002/110188/1B959D30"
        },
        [11018809] = {
