        [12001781] = {
          Camera = "259.166016,139.326172,124.026855,0.0001,-2.599324,-148.204941,30.000002,100000.0,false,DoNotOverride,10.0",
          ContentEN = "...How about this, ma'am: we won't delay your journey any further, but we'll assign personnel to escort you and ensure safe passage out of the city.",
