        [12001802] = {
          ContentEN = "Ah, that would be a Phoxhunter I hired.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001802,
          GUID = "1E0B95A4",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001803,
          SpeakNpcId = 220014,
          Subtitle = "Ah, that would be a Phoxhunter I hired.",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B95A4"
        },
        [12001803] = {
          ContentEN = "It required very little — just a modest sum of money to entice someone into taking the risk. The amount was so minimal, it wouldn't even cover the cost of a single hunting hound owned by the Finance Minister at her countryside estate.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001803,
          GUID = "1E0B95CE",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001804,
          SpeakNpcId = 220014,
          Subtitle = "It required very little — just a modest sum of money to entice someone into taking the risk. The amount was so minimal, it wouldn't even cover the cost of a single hunting hound owned by the Finance Minister at her countryside estate.",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B95CE"
        },
        [12001804] = {
          ContentEN = "And yet, that small investment was all it took to steer us safely through tonight's crisis.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001804,
          GUID = "1E0B95F8",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001830,
          SpeakNpcId = 220014,
          Subtitle = "And yet, that small investment was all it took to steer us safely through tonight's crisis.",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B95F8"
        },
        [12001805] = {
          ContentEN = "Would you like to hear something intriguing?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001805,
          GUID = "1E0B9622",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001806,
          SpeakNpcId = 220014,
          Subtitle = "Would you like to hear something intriguing?",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B9622"
        },
        [12001806] = {
          ContentEN = "The Hyperborea Daily is a newspaper sold throughout the entire Empire. And, as it happens, every major city in Hyperborea has... a red phone booth in its central square.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001806,
          GUID = "1E0B964C",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001807,
          SpeakNpcId = 220014,
          Subtitle = "The Hyperborea Daily is a newspaper sold throughout the entire Empire. And, as it happens, every major city in Hyperborea has... a red phone booth in its central square.",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B964C"
        },
        [12001807] = {
          ContentEN = "This morning, Camilla shared the story behind that article with me. After hearing the details, I decided to take precautions and sent out a few extra telegrams.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001807,
          GUID = "1E0B9676",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001808,
          SpeakNpcId = 220014,
          Subtitle = "This morning, Camilla shared the story behind that article with me. After hearing the details, I decided to take precautions and sent out a few extra telegrams.",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B9676"
        },
        [12001808] = {
          ContentEN = "Here's some good news for you: tonight, in each of those cities, a white-haired woman is standing inside a red phone booth, patiently awaiting a \"long-lost family\" who will never arrive.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001808,
          GUID = "1E0B96A0",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001809,
          SpeakNpcId = 220014,
          Subtitle = "Here's some good news for you: tonight, in each of those cities, a white-haired woman is standing inside a red phone booth, patiently awaiting a \"long-lost family\" who will never arrive.",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B96A0"
        },
        [12001809] = {
          ContentEN = "Why is that good news? I don't get it...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001809,
          GUID = "1E0B96CA",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001810,
          SpeakNpcId = 200002,
          Subtitle = "Why is that good news? I don't get it...",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B96CA"
        },
        [12001810] = {
          ContentEN = "I think Proprietress Zhiliu means they aren't sure where I am — or even if I'm still alive. So, they had to scatter their bait across multiple cities to draw me out...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001810,
          GUID = "1E0B96F4",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001811,
          SpeakNpcId = 100001,
          Subtitle = "I think Proprietress Zhiliu means they aren't sure where I am — or even if I'm still alive. So, they had to scatter their bait across multiple cities to draw me out...",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B96F4"
        },
        [12001811] = {
          ContentEN = "Precisely. You're quite the clever one.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001811,
          GUID = "1E0B971E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001812,
          SpeakNpcId = 220014,
          Subtitle = "Precisely. You're quite the clever one.",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B971E"
        },
        [12001812] = {
          ContentEN = "(They know I exist, and they've gone to such lengths to set such a complicated trap... Who in the Legion could be behind this?)",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001812,
          GUID = "1E0B9748",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001830,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(They know I exist, and they've gone to such lengths to set such a complicated trap... Who in the Legion could be behind this?)",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B9748"
        },
        [12001813] = {
          ContentEN = "Given the current circumstances, I'm afraid you can't leave the car until the airship departs. My apologies — it appears I'll have to take you to Huaxu with me.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001813,
          GUID = "1E0B9772",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001814,
          RelatedWikiId = {
            [1] = 203001,
            [2] = 408010
          },
          SpeakNpcId = 220014,
          Subtitle = "Given the current circumstances, I'm afraid you can't leave the car until the airship departs. My apologies — it appears I'll have to take you to Huaxu with me.",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B9772"
        },
        [12001814] = {
          ContentEN = "Proprietress Zhiliu, you've saved me from trouble on multiple occasions. I don't even know how to begin repaying you.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001814,
          GUID = "1E0B979C",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001815,
          SpeakNpcId = 100001,
          Subtitle = "Proprietress Zhiliu, you've saved me from trouble on multiple occasions. I don't even know how to begin repaying you.",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B979C"
        },
        [12001815] = {
          ContentEN = "Repay me? Hmm...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001815,
          GUID = "1E0B97C6",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001816,
          SpeakNpcId = 220014,
          Subtitle = "Repay me? Hmm...",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B97C6"
        },
        [12001816] = {
          ContentEN = "As it happens, there is a task that would benefit from an extra pair of capable hands. The airship returning from Huaxu to Hyperborea departs in seven days. If you don't mind staying with me until then, perhaps you could assist me.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001816,
          GUID = "1E0B97F0",
