          VoiceName = "voice/$Locale$/story/1200/120018/1E0B98EC"
        },
        [12001823] = {
          ContentEN = "There's no need to worry. I've hired temporary workers in other cities as well. With so many \"fish\" taking the bait across the country, the Hyperborean soldiers will be kept busy tonight and come up empty-handed — they won't have a clue you're actually here in Icelake.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001823,
          GUID = "1E0B9916",
