        [12010000] = {
          ContentEN = "Sails down — coming into port—!",
          DialogueId = 12010000,
          Duration = 5,
          GUID = "1E10D6A0",
          Subtitle = "Sails down — coming into port—!",
          VoiceName = "voice/$Locale$/story/1201/120100/1E10D6A0"
        },
        [12010001] = {
          ContentEN = "Ugh... we've been on a cart, an airship, and now a boat — my poor buns are squished as flat as a pancake...",
          DialogueId = 12010001,
          GUID = "1E10D6CA",
          NextDialogue = 12010002,
          RelatedWikiId = {
            [1] = 408010,
            [2] = 408011,
            [3] = 203001
          },
          SpeakNpcId = 200002,
          Subtitle = "Ugh... we've been on a cart, an airship, and now a boat — my poor buns are squished as flat as a pancake...",
          VoiceName = "voice/$Locale$/story/1201/120100/1E10D6CA"
        },
        [12010002] = {
          ContentEN = "Hehe... The journey from Huaxu to Hyperborea spans hundreds — maybe even thousands — of miles. To think we've crossed that distance in just one day... that's the power of Phoxene-based technology.",
          DialogueId = 12010002,
          GUID = "1E10D6F4",
          NextDialogue = 12010003,
          SpeakNpcId = 210004,
          Subtitle = "Hehe... The journey from Huaxu to Hyperborea spans hundreds — maybe even thousands — of miles. To think we've crossed that distance in just one day... that's the power of Phoxene-based technology.",
          VoiceName = "voice/$Locale$/story/1201/120100/1E10D6F4"
        },
        [12010003] = {
          ContentEN = "You're right... Heh, this is the farthest I've ever gone!",
          DialogueId = 12010003,
          GUID = "1E10D71E",
          NextDialogue = 12010004,
          SpeakNpcId = 200002,
          Subtitle = "You're right... Heh, this is the farthest I've ever gone!",
          VoiceName = "voice/$Locale$/story/1201/120100/1E10D71E"
        },
        [12010004] = {
          ContentEN = "Look at those green mountains, totally worth it! If I were still stuck in Icelake, I'd just be staring at snow wolves all day — not cute at all.",
          DialogueId = 12010004,
          GUID = "1E10D748",
          NextDialogue = 12010005,
          SpeakNpcId = 200002,
          Subtitle = "Look at those green mountains, totally worth it! If I were still stuck in Icelake, I'd just be staring at snow wolves all day — not cute at all.",
          VoiceName = "voice/$Locale$/story/1201/120100/1E10D748"
        },
        [12010005] = {
          ContentEN = "Little Minion, this is the \"south\" you're always going on about, isn't it? Does it look anything like your hometown?",
          DialogueId = 12010005,
          GUID = "1E10D772",
          NextDialogue = 12010006,
          SpeakNpcId = 200002,
          Subtitle = "Little Minion, this is the \"south\" you're always going on about, isn't it? Does it look anything like your hometown?",
          VoiceName = "voice/$Locale$/story/1201/120100/1E10D772"
        },
        [12010006] = {
          ContentEN = "A little... but there are lots of differences too.",
          DialogueId = 12010006,
          GUID = "1E10D79C",
          NextDialogue = 12010007,
          SpeakNpcId = 100001,
          Subtitle = "A little... but there are lots of differences too.",
          VoiceName = "voice/$Locale$/story/1201/120100/1E10D79C"
        },
        [12010007] = {
          ContentEN = "Purgatorio Island is tiny. Even its tallest hill — if a kid really puts their mind to it, they could sprint all the way up in one go. And from up there, the deep blue sea stretches out forever...",
          DialogueId = 12010007,
          GUID = "1E10D7C6",
          NextDialogue = 12010008,
          SpeakNpcId = 100001,
          Subtitle = "Purgatorio Island is tiny. Even its tallest hill — if a kid really puts their mind to it, they could sprint all the way up in one go. And from up there, the deep blue sea stretches out forever...",
          VoiceName = "voice/$Locale$/story/1201/120100/1E10D7C6"
        },
        [12010008] = {
          ContentEN = "Proprietress Zhiliu, what's Huaxu like?",
          DialogueId = 12010008,
          GUID = "1E10D7F0",
          NextDialogue = 12010009,
          SpeakNpcId = 100001,
          Subtitle = "Proprietress Zhiliu, what's Huaxu like?",
          VoiceName = "voice/$Locale$/story/1201/120100/1E10D7F0"
        },
        [12010009] = {
          ContentEN = "Let me think... what you've seen so far is only a small corner of Huaxu.",
          DialogueId = 12010009,
          GUID = "1E10D81A",
          NextDialogue = 12010010,
          SpeakNpcId = 210004,
          Subtitle = "Let me think... what you've seen so far is only a small corner of Huaxu.",
          VoiceName = "voice/$Locale$/story/1201/120100/1E10D81A"
        },
        [12010010] = {
          ContentEN = "In ancient times, our ancestors united their strength to drive out the monstrous Filthoids that once plagued these lands. They settled here, their numbers grew, and so too did their domain.",
          DialogueId = 12010010,
          GUID = "1E10D844",
          NextDialogue = 12010011,
          SpeakNpcId = 210004,
          Subtitle = "In ancient times, our ancestors united their strength to drive out the monstrous Filthoids that once plagued these lands. They settled here, their numbers grew, and so too did their domain.",
          VoiceName = "voice/$Locale$/story/1201/120100/1E10D844"
        },
        [12010011] = {
          ContentEN = "Today, this estuary has become what we call the Old Capital. It may be but a fraction of Huaxu's vast expanse, but its influence is anything but small.",
          DialogueId = 12010011,
          GUID = "1E10D86E",
          NextDialogue = 12010012,
          SpeakNpcId = 210004,
          Subtitle = "Today, this estuary has become what we call the Old Capital. It may be but a fraction of Huaxu's vast expanse, but its influence is anything but small.",
          VoiceName = "voice/$Locale$/story/1201/120100/1E10D86E"
        },
        [12010012] = {
          ContentEN = "Huaxu is lush and scenic — evergreen throughout the year. With the Starweavers leading the way, trade and commerce here are positively thriving...",
          DialogueId = 12010012,
          GUID = "1E10D898",
          NextDialogue = 12010013,
          RelatedWikiId = {
            [1] = 405007
          },
          SpeakNpcId = 210004,
          Subtitle = "Huaxu is lush and scenic — evergreen throughout the year. With the Starweavers leading the way, trade and commerce here are positively thriving...",
          VoiceName = "voice/$Locale$/story/1201/120100/1E10D898"
        },
        [12010013] = {
          ContentEN = "Hehe... you're looking rather serious — was that all a bit too formal for your liking?",
          DialogueId = 12010013,
          GUID = "1E10D8C2",
          NextOptions = {
            [1] = 120100131,
            [2] = 120100132
          },
          SpeakNpcId = 210004,
          Subtitle = "Hehe... you're looking rather serious — was that all a bit too formal for your liking?",
          VoiceName = "voice/$Locale$/story/1201/120100/1E10D8C2"
        },
        [12010014] = {
          ContentEN = "Very well, then. Let me share something more to your taste: Huaxu is a realm of peace — where <H>no blade is ever unsheathed in wrath, nor discord allowed to sully the land</>.",
          DialogueId = 12010014,
          GUID = "1E10D8EC",
          NextDialogue = 12010015,
          SpeakNpcId = 210004,
          Subtitle = "Very well, then. Let me share something more to your taste: Huaxu is a realm of peace — where no blade is ever unsheathed in wrath, nor discord allowed to sully the land.",
          VoiceName = "voice/$Locale$/story/1201/120100/1E10D8EC"
        },
        [12010015] = {
          ContentEN = "No blades something... nor what now? I've no clue what those fancy words are supposed to mean...",
          DialogueId = 12010015,
          GUID = "1E10D916",
          NextDialogue = 12010016,
          SpeakNpcId = 200002,
          Subtitle = "No blades something... nor what now? I've no clue what those fancy words are supposed to mean...",
          VoiceName = "voice/$Locale$/story/1201/120100/1E10D916"
        },
        [12010016] = {
          ContentEN = "I think she means... there's no war here. People don't go around picking fights like in Icelake.",
