        [12010218] = {
          Camera = "999.449219,-469.097656,578.913574,0.000173,-25.402763,150.978256,35.0,100000.0,false,Manual,12.0",
          ContentEN = "Oi! You're the helmsman, yeah? Move this boat — now! I don't care where, just get me out of this damned place!",
