        [12010305] = {
          ContentEN = "The <W>Scourge of Zhuyin</> has been escalating recently. Some Starweavers, unwilling to abide by the lockdown, bypassed EverSpring and hired outside escorts to brave the danger on their own.",
          DialogueId = 12010305,
          GUID = "1E1108AA",
          NextDialogue = 12010306,
          RelatedWikiId = {
            [1] = 304004
          },
          SpeakNpcId = 210032,
          Subtitle = "The Scourge of Zhuyin has been escalating recently. Some Starweavers, unwilling to abide by the lockdown, bypassed EverSpring and hired outside escorts to brave the danger on their own.",
          TalkActionId = {
            [1] = "210032:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120103/1E1108AA"
        },
        [12010306] = {
          ContentEN = "But they didn't bother to check the character of those they hired — and so, we ended up with this situation.",
          DialogueId = 12010306,
          GUID = "1E1108D4",
          NextDialogue = 12010307,
          SpeakNpcId = 210032,
          Subtitle = "But they didn't bother to check the character of those they hired — and so, we ended up with this situation.",
          VoiceName = "voice/$Locale$/story/1201/120103/1E1108D4"
        },
        [12010307] = {
          Camera = "-24.557076,-109.239418,131.683594,0.000153,-0.802465,48.999199,50.0,257.290894,false,DoNotOverride,2.8",
          ContentEN = "Before I left, the merchants were still in a heated argument, shouting up a storm outside EverSpring. I'm afraid you'll be needed to calm them down, Miss Zhiliu.",
