          NextDialogue = 12010426,
          SpeakNpcId = 100001,
          Subtitle = "...!?",
          VoiceName = "voice/$Locale$/story/1201/120104/1E111C5A"
        },
        [12010426] = {
          ContentEN = "(That stele... it almost feels like it's... <H>calling</> to me...)",
          DialogueId = 12010426,
          DisableMouth = 1,
          GUID = "1E111C84",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(That stele... it almost feels like it's... calling to me...)",
