        },
        [12010510] = {
          Camera = "-309.597839,264.643616,19.609375,0.000098,-13.798676,-30.610697,28.0,100000.0,false,DoNotOverride,2.8",
          ContentEN = "I'm fine. That beast's terrifying glare shook me a bit. I'll feel better after a short rest. But you seemed new to this place... I couldn't just stand by and leave you in danger.",
