          VoiceName = "voice/$Locale$/story/1201/120105/1E112A76"
        },
        [12010512] = {
          ContentEN = "I see... I'm glad to hear it.",
          DialogueId = 12010512,
          GUID = "1E112AA0",
          NextDialogue = 12010513,
          SpeakNpcId = 210033,
          SpeakNpcName = "UI_Npc_CMName_LuGuoXingShang",
          Subtitle = "I see... I'm glad to hear it.",
          VoiceName = "voice/$Locale$/story/1201/120105/1E112AA0"
        },
        [12010513] = {
          ContentEN = "But seriously, what was that!? I wasn't seeing things, was I? Why would one of Huaxu's guardian beasts suddenly attack us!?",
          DialogueId = 12010513,
          GUID = "1E112ACA",
          NextDialogue = 12010514,
          SpeakNpcId = 200002,
          Subtitle = "But seriously, what was that!? I wasn't seeing things, was I? Why would one of Huaxu's guardian beasts suddenly attack us!?",
          VoiceName = "voice/$Locale$/story/1201/120105/1E112ACA"
        },
        [12010514] = {
          ContentEN = "For the record — I didn't do anything illegal, okay? Though... I guess at this point it'd be pointless to clarify...",
