          Subtitle = "And now look at us — all the way out here, so far from home, on some epic, destiny-shaping quest!",
          VoiceName = "voice/$Locale$/story/1201/120110/1E117B2E"
        },
        [12011004] = {
          ContentEN = "...Yeah. That time we ran into Outsider and kind of... shook him down. And Psyche... was still with us back then.",
          DialogueId = 12011004,
          Duration = 3,
          GUID = "1E117B58",
          GuideFacialId = "Sad",
