          DefaultLookAt = "TalkNpc",
          DialogueId = 12012017,
          GUID = "1E12218A",
          NextDialogue = 12012018,
          SpeakNpcId = 100001,
          Subtitle = "You sure? That looks pretty bad... Maybe we should have a doctor take a look?",
          VoiceName = "voice/$Locale$/story/1201/120120/1E12218A"
        },
        [12012018] = {
          ContentEN = "As a Magistrate of Yingtian, my strength does not come solely from flesh and bone — it draws upon the Nine Chapters of Dafeng.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012018,
          GUID = "1E1221B4",
          NextDialogue = 12012019,
          SpeakNpcId = 210007,
          Subtitle = "As a Magistrate of Yingtian, my strength does not come solely from flesh and bone — it draws upon the Nine Chapters of Dafeng.",
          VoiceName = "voice/$Locale$/story/1201/120120/1E1221B4"
        },
        [12012019] = {
          ContentEN = "So long as my spine remains unbroken, even the gravest wounds can mend with the Nine Chapters' energy. It's slow and painful, but certain.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012019,
          GUID = "1E1221DE",
