        [12012701] = {
          Camera = "69.70105,1077.539062,187.139709,0.0,-5.999931,-101.595413,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentEN = "What a joy it is to welcome friends from afar.",
          DialogueId = 12012701,
