        },
        [12012806] = {
          ContentEN = "But she looks awful... C'mon, let's check on her!",
          DialogueId = 12012806,
          Duration = 2,
          GUID = "1E12A2FC",
          SpeakNpcId = 200002,
          Subtitle = "But she looks awful... C'mon, let's check on her!",
          VoiceName = "voice/$Locale$/story/1201/120128/1E12A2FC"
        },
        [12012901] = {
          ContentEN = "Didn't expect her to be this frail... One strike from the Bi'an, and she's been bedridden ever since.",
          DialogueId = 12012901,
          GUID = "1E12B292",
          NextDialogue = 12012902,
          SpeakNpcId = 210008,
          Subtitle = "Didn't expect her to be this frail... One strike from the Bi'an, and she's been bedridden ever since.",
          VoiceName = "voice/$Locale$/story/1201/120129/1E12B292"
        },
        [12012902] = {
          ContentEN = "At this rate, not even a miracle could save her.",
          DialogueId = 12012902,
          GUID = "1E12B2BC",
          SpeakNpcId = 210009,
          Subtitle = "At this rate, not even a miracle could save her.",
          VoiceName = "voice/$Locale$/story/1201/120129/1E12B2BC"
        },
        [12013001] = {
          ContentEN = "Hey—! Watch where you're going!",
          DialogueId = 12013001,
          Duration = 2,
          GUID = "1E12C2FA",
          RelatedWikiId = {
