        [12013101] = {
          Camera = "428.589844,98.277344,126.54541,0.0,0.0,-179.794739,35.0,100000.0,false,DoNotOverride,2.8",
          ContentEN = "It is done. You'll get well soon.",
          DialogueId = 12013101,
          GUID = "1E12D362",
          NextDialogue = 12013102,
          SpeakNpcId = 210013,
          Subtitle = "It is done. You'll get well soon.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D362"
        },
        [12013102] = {
          ContentEN = "Is this young lady a friend of yours?",
          DialogueId = 12013102,
          GUID = "1E12D38C",
          NextDialogue = 12013103,
          SpeakNpcId = 210013,
          Subtitle = "Is this young lady a friend of yours?",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D38C"
        },
        [12013103] = {
          ContentEN = "...Forgive me. I have yet to introduce myself. I'm Fushu, a healer who uses <H>Zhuyou</> therapy. I practise the <H>Art of Ephemerality</> passed down through my line — to cleanse affliction and expel foulness that clings to the suffering.",
          DialogueId = 12013103,
          GUID = "1E12D3B6",
          NextDialogue = 12013104,
          RelatedWikiId = {
            [1] = 405012,
            [2] = 203006
          },
          SpeakNpcId = 210013,
          Subtitle = "...Forgive me. I have yet to introduce myself. I'm Fushu, a healer who uses Zhuyou therapy. I practise the Art of Ephemerality passed down through my line — to cleanse affliction and expel foulness that clings to the suffering.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D3B6"
        },
        [12013104] = {
          ContentEN = "So... you're a doctor?",
          DialogueId = 12013104,
          GUID = "1E12D3E0",
          NextDialogue = 12013105,
          SpeakNpcId = 100001,
          Subtitle = "So... you're a doctor?",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D3E0"
        },
        [12013105] = {
          ContentEN = "In Huaxu, the Art of Ephemerality and the practice of medicine do not share the same roots. Yet if calling me a doctor brings you ease, I shall not object. Or if you prefer, simply call me Fushu.",
          DialogueId = 12013105,
          GUID = "1E12D40A",
          NextDialogue = 12013106,
          RelatedWikiId = {
            [1] = 304005
          },
          SpeakNpcId = 210013,
          Subtitle = "In Huaxu, the Art of Ephemerality and the practice of medicine do not share the same roots. Yet if calling me a doctor brings you ease, I shall not object. Or if you prefer, simply call me Fushu.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D40A"
        },
        [12013106] = {
          ContentEN = "Do you know this young lady?",
          DialogueId = 12013106,
          GUID = "1E12D434",
          NextOptions = {
            [1] = 120131061,
            [2] = 120131062
          },
          SpeakNpcId = 210013,
          Subtitle = "Do you know this young lady?",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D434"
        },
        [12013107] = {
          ContentEN = "I cannot cleanse this affliction entirely. May I inquire... how did she come by these wounds?",
          DialogueId = 12013107,
          GUID = "1E12D45E",
          NextDialogue = 12013108,
          SpeakNpcId = 210013,
          Subtitle = "I cannot cleanse this affliction entirely. May I inquire... how did she come by these wounds?",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D45E"
        },
        [12013108] = {
          ContentEN = "Her wounds were caused by a Bi'an. But she's not a criminal.",
          DialogueId = 12013108,
          GUID = "1E12D488",
          NextDialogue = 12013109,
          SpeakNpcId = 100001,
          Subtitle = "Her wounds were caused by a Bi'an. But she's not a criminal.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D488"
        },
        [12013109] = {
          ContentEN = "She was framed by some bad guys in the black market! That's why the Nine Chapters punished her! Please... don't give up on her.",
          DialogueId = 12013109,
          GUID = "1E12D4B2",
          NextDialogue = 12013110,
          SpeakNpcId = 200002,
          Subtitle = "She was framed by some bad guys in the black market! That's why the Nine Chapters punished her! Please... don't give up on her.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D4B2"
        },
        [12013110] = {
          ContentEN = "I see. The Art of Ephemerality is drawn from the same source as the Nine Chapters, and thus cannot mend wounds wrought by a Bi'an. I shall take her with me and seek out other remedies.",
          DialogueId = 12013110,
          GUID = "1E12D4DC",
          NextDialogue = 12013111,
          SpeakNpcId = 210013,
          Subtitle = "I see. The Art of Ephemerality is drawn from the same source as the Nine Chapters, and thus cannot mend wounds wrought by a Bi'an. I shall take her with me and seek out other remedies.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D4DC"
        },
        [12013111] = {
          ContentEN = "You...",
          DialogueId = 12013111,
          GUID = "1E12D506",
          NextDialogue = 12013112,
          SpeakNpcId = 210013,
          Subtitle = "You...",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D506"
        },
        [12013112] = {
          ContentEN = "Huh? Why are you staring at my Little Minion like that, Miss Fushu? Wait... don't tell me my Little Minion's still got some hidden injury that needs treatment!",
          DialogueId = 12013112,
          GUID = "1E12D530",
          NextDialogue = 12013113,
          SpeakNpcId = 200002,
          Subtitle = "Huh? Why are you staring at my Little Minion like that, Miss Fushu? Wait... don't tell me my Little Minion's still got some hidden injury that needs treatment!",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D530"
        },
        [12013113] = {
          ContentEN = "...Forgive my staring. It was unseemly of me. Your form is sound. Rather... it was that bamboo flute of yours. It resembles a relic once held by one dear to me.",
          DialogueId = 12013113,
          GUID = "1E12D55A",
          NextDialogue = 12013114,
          SpeakNpcId = 210013,
          Subtitle = "...Forgive my staring. It was unseemly of me. Your form is sound. Rather... it was that bamboo flute of yours. It resembles a relic once held by one dear to me.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D55A"
        },
        [12013114] = {
          ContentEN = "If I might be so bold — would you part with it? I would repay you, by whatever means I may.",
          DialogueId = 12013114,
          GUID = "1E12D584",
          NextOptions = {
            [1] = 120131141,
            [2] = 120131142,
            [3] = 120131143
          },
          SpeakNpcId = 210013,
          Subtitle = "If I might be so bold — would you part with it? I would repay you, by whatever means I may.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D584"
        },
        [12013115] = {
          ContentEN = "The Art of Ephemerality is not to be bartered for gain. Such is the teaching of my line — one I dare not transgress.",
          DialogueId = 12013115,
          GUID = "1E12D5AE",
          NextDialogue = 12013119,
          SpeakNpcId = 210013,
          Subtitle = "The Art of Ephemerality is not to be bartered for gain. Such is the teaching of my line — one I dare not transgress.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D5AE"
        },
        [12013116] = {
          ContentEN = "To accept a gift unearned is a violation of the teachings of my line — one I dare not transgress.",
          DialogueId = 12013116,
          GUID = "1E12D5D8",
          NextDialogue = 12013119,
          SpeakNpcId = 210013,
          Subtitle = "To accept a gift unearned is a violation of the teachings of my line — one I dare not transgress.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D5D8"
        },
        [12013117] = {
          ContentEN = "You speak with reason.",
          DialogueId = 12013117,
          GUID = "1E12D602",
          NextDialogue = 12013118,
          SpeakNpcId = 210013,
          Subtitle = "You speak with reason.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D602"
        },
        [12013118] = {
          ContentEN = "To accept a gift unearned is a violation of the teachings of my line — one I dare not transgress.",
          DialogueId = 12013118,
          GUID = "1E12D62C",
          NextDialogue = 12013119,
          SpeakNpcId = 210013,
          Subtitle = "To accept a gift unearned is a violation of the teachings of my line — one I dare not transgress.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D62C"
        },
        [12013119] = {
          ContentEN = "But I have nothing of worth on my person now. Thus let me offer this instead: should you ever call upon me, if it lies within my power — I shall not refuse.",
          DialogueId = 12013119,
          GUID = "1E12D656",
          NextDialogue = 12013120,
          SpeakNpcId = 210013,
          Subtitle = "But I have nothing of worth on my person now. Thus let me offer this instead: should you ever call upon me, if it lies within my power — I shall not refuse.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D656"
        },
        [12013120] = {
          ContentEN = "To us, it's just a flute. But to you, it clearly means much more. Here — take it.",
          DialogueId = 12013120,
          GUID = "1E12D680",
          NextDialogue = 12013121,
          SpeakNpcId = 100001,
          Subtitle = "To us, it's just a flute. But to you, it clearly means much more. Here — take it.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D680"
        },
        [12013121] = {
          ContentEN = "Much obliged. Might I know your names? I shall keep them close to heart.",
          DialogueId = 12013121,
          GUID = "1E12D6AA",
          NextOptions = {
            [1] = 120131211,
            [2] = 120131212
          },
          SpeakNpcId = 210013,
          Subtitle = "Much obliged. Might I know your names? I shall keep them close to heart.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D6AA"
        },
        [12013122] = {
          ContentEN = "Hmm... I have read some travel accounts from abroad. \"Duke\" appears to be a noble title in the Hyperborean Empire. As for the \"Sewers\"...",
          DialogueId = 12013122,
          GUID = "1E12D6D4",
          NextDialogue = 12013123,
          SpeakNpcId = 210013,
          Subtitle = "Hmm... I have read some travel accounts from abroad. \"Duke\" appears to be a noble title in the Hyperborean Empire. As for the \"Sewers\"...",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D6D4"
        },
        [12013123] = {
          ContentEN = "Never mind. Perhaps it is simply that I am out of touch with the times.",
          DialogueId = 12013123,
          GUID = "1E12D6FE",
          NextDialogue = 12013124,
          SpeakNpcId = 210013,
          Subtitle = "Never mind. Perhaps it is simply that I am out of touch with the times.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D6FE"
        },
        [12013124] = {
          ContentEN = "Just kidding. I'm {nickname} and this little Luno is Snow.",
          DialogueId = 12013124,
          GUID = "1E12D728",
          NextDialogue = 12013125,
          SpeakNpcId = 100001,
          Subtitle = "Just kidding. I'm  and this little Luno is Snow.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D728"
        },
        [12013125] = {
          ContentEN = "Understood. It's nice to meet you, {nickname}, and Snow.",
          DialogueId = 12013125,
          GUID = "1E12D752",
          NextDialogue = 12013126,
          SpeakNpcId = 210013,
