          ContentEN = "When stirred by incense, the Taixu rides upon the wind and becomes the medium through which the Nine Chapters of Dafeng weave their power. When left undisturbed, it condenses into the Taixu runes drifting in the air.",
          DialogueId = 12013419,
          FacialId = {
            [1] = "210014:CM_Idle"
          },
          FinalCamera = "-1628.330078,-611.611572,740.382324,0.000072,-29.399687,18.407286,35.000011,555.878662,false,DoNotOverride,2.8",
          GUID = "1E13078E",
          NextDialogue = 12013420,
          SpeakNpcId = 210014,
          Subtitle = "When stirred by incense, the Taixu rides upon the wind and becomes the medium through which the Nine Chapters of Dafeng weave their power. When left undisturbed, it condenses into the Taixu runes drifting in the air.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1201/120134/1E13078E"
        },
        [12013420] = {
          ContentEN = "But here in this land, shrouded by the Scourge of Zhuyin, the Taixu has sunk downwards and congealed into the Gritblight, swallowing all that bears shape and form.",
