          SpeakNpcId = 100001,
          Subtitle = "...Okay. I understand.",
          VoiceName = "voice/$Locale$/story/1201/120161/1E14C03A"
        },
        [12016201] = {
          ContentEN = "Do you see those lantern blossoms? The living send forth their prayers upon them, setting them adrift in deep, silent waters — hoping they might reach those who have departed.",
          DialogueId = 12016201,
          Duration = 4,
          GUID = "1E14CFFA",
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "Do you see those lantern blossoms? The living send forth their prayers upon them, setting them adrift in deep, silent waters — hoping they might reach those who have departed.",
          VoiceName = "voice/$Locale$/story/1201/120162/1E14CFFA"
        },
        [12016202] = {
          ContentEN = "Their gentle light shall shield you from the oblivion's creeping grasp.",
          DialogueId = 12016202,
          Duration = 3,
          GUID = "1E14D024",
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "Their gentle light shall shield you from the oblivion's creeping grasp.",
          VoiceName = "voice/$Locale$/story/1201/120162/1E14D024"
        },
        [12016251] = {
          ContentEN = "How am I supposed to leave here, Fushu?",
