          SpeakNpcId = 210013,
          Subtitle = "Stay close to me. I will guide you to safety as well.",
          VoiceName = "voice/$Locale$/story/1201/120172/1E1574B2"
        },
        [12017206] = {
          ContentEN = "Ee!",
          DialogueId = 12017206,
          GUID = "1E1574DC",
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "Ee!",
          VoiceName = "voice/$Locale$/story/1201/120172/1E1574DC"
        },
        [12017301] = {
          ContentEN = "(In this fleeting life, my sole resolve is to wield the Art of Ephemerality — to heal all who suffer. That resolve, I shall never forsake.)",
          DialogueId = 12017301,
          Duration = 3,
          GUID = "1E158472",
          NextDialogue = 12017302,
          SnapShot = "HEART",
          SpeakNpcId = 210013,
          Subtitle = "(In this fleeting life, my sole resolve is to wield the Art of Ephemerality — to heal all who suffer. That resolve, I shall never forsake.)",
          VoiceName = "voice/$Locale$/story/1201/120173/1E158472"
        },
        [12017302] = {
          ContentEN = "The colour of the flame... it's not as it should be.",
          DialogueId = 12017302,
          Duration = 2,
          GUID = "1E15849C",
          SpeakNpcId = 210013,
          Subtitle = "The colour of the flame... it's not as it should be.",
          VoiceName = "voice/$Locale$/story/1201/120173/1E15849C"
        },
        [12017401] = {
          ContentEN = "It hurts so much... My wounds are festering — I haven't known sleep in days...",
          DialogueId = 12017401,
          Duration = 2,
          GUID = "1E1594DA",
          SnapShot = "MEMORY",
          SpeakNpcName = "UI_CMName_Name_HuanzhePhantom",
          Subtitle = "It hurts so much... My wounds are festering — I haven't known sleep in days...",
          VoiceName = "voice/$Locale$/story/1201/120174/1E1594DA"
        },
        [12017402] = {
          ContentEN = "There's no hope left, is there? Lady Zhuyou... please, put me out of my misery...",
          DialogueId = 12017402,
          Duration = 3,
          GUID = "1E159504",
          SnapShot = "MEMORY",
          SpeakNpcName = "UI_CMName_Name_HuanzhePhantom",
          Subtitle = "There's no hope left, is there? Lady Zhuyou... please, put me out of my misery...",
          VoiceName = "voice/$Locale$/story/1201/120174/1E159504"
        },
        [12017403] = {
          ContentEN = "My baby... she's just come into the world, and hasn't even called me \"Mama\" yet! Please, I beg you — save her. Save her!",
          DialogueId = 12017403,
          Duration = 3,
          GUID = "1E15952E",
          SnapShot = "MEMORY",
          SpeakNpcName = "UI_CMName_Name_HuanzhePhantom",
          Subtitle = "My baby... she's just come into the world, and hasn't even called me \"Mama\" yet! Please, I beg you — save her. Save her!",
          VoiceName = "voice/$Locale$/story/1201/120174/1E15952E"
        },
        [12017404] = {
          ContentEN = "They say the House of Zhuyou can heal any affliction — so why won't you help us? Don't you care!?",
          DialogueId = 12017404,
          Duration = 4,
          GUID = "1E159558",
          SnapShot = "MEMORY",
          SpeakNpcName = "UI_CMName_Name_HuanzhePhantom",
          Subtitle = "They say the House of Zhuyou can heal any affliction — so why won't you help us? Don't you care!?",
          VoiceName = "voice/$Locale$/story/1201/120174/1E159558"
        },
        [12017405] = {
          ContentEN = "This was... the plague that ravaged our lands a century ago.",
          DialogueId = 12017405,
          Duration = 1,
          GUID = "1E159582",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 12017406,
          SpeakNpcId = 210013,
          Subtitle = "This was... the plague that ravaged our lands a century ago.",
          VoiceName = "voice/$Locale$/story/1201/120174/1E159582"
        },
        [12017406] = {
          ContentEN = "I ran from dawn to dusk, doing all I could... yet still, all I could do was watch them die, one by one — helpless in their agony.",
          DialogueId = 12017406,
          Duration = 3,
          GUID = "1E1595AC",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          SpeakNpcId = 210013,
          Subtitle = "I ran from dawn to dusk, doing all I could... yet still, all I could do was watch them die, one by one — helpless in their agony.",
          VoiceName = "voice/$Locale$/story/1201/120174/1E1595AC"
        },
        [12017407] = {
          ContentEN = "(Such is the flame's response... So my heart had wavered, after all?)",
          DialogueId = 12017407,
          Duration = 2,
          GUID = "1E1595D6",
          NextDialogue = 12017501,
          SnapShot = "HEART",
          SpeakNpcId = 210013,
          Subtitle = "(Such is the flame's response... So my heart had wavered, after all?)",
          VoiceName = "voice/$Locale$/story/1201/120174/1E1595D6"
        },
        [12017501] = {
          ContentEN = "(Is it only the pain of others I grieve... or is it something I've long kept hidden?)",
          DialogueId = 12017501,
          Duration = 3,
          GUID = "1E15A542",
          NextDialogue = 12017502,
          SnapShot = "HEART",
          SpeakNpcId = 210013,
          Subtitle = "(Is it only the pain of others I grieve... or is it something I've long kept hidden?)",
          VoiceName = "voice/$Locale$/story/1201/120175/1E15A542"
        },
        [12017502] = {
          ContentEN = "(Yet all I have known, all I have ever offered, is the Art of Ephemerality. If my heart wavers... how can I find a way back?)",
          DialogueId = 12017502,
          Duration = 4,
          GUID = "1E15A56C",
          SnapShot = "HEART",
          SpeakNpcId = 210013,
          Subtitle = "(Yet all I have known, all I have ever offered, is the Art of Ephemerality. If my heart wavers... how can I find a way back?)",
          VoiceName = "voice/$Locale$/story/1201/120175/1E15A56C"
        },
        [12017601] = {
          ContentEN = "...As I feared.",
          DialogueId = 12017601,
          Duration = 1,
          GUID = "1E15B5AA",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 12017602,
          SpeakNpcId = 210013,
          Subtitle = "...As I feared.",
          VoiceName = "voice/$Locale$/story/1201/120176/1E15B5AA"
        },
        [12017602] = {
          ContentEN = "Forgive me... I promised to lead you out. But now... it seems I must break that promise.",
          DialogueId = 12017602,
          Duration = 2,
          GUID = "1E15B5D4",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 210013,
          Subtitle = "Forgive me... I promised to lead you out. But now... it seems I must break that promise.",
          VoiceName = "voice/$Locale$/story/1201/120176/1E15B5D4"
        },
        [12017701] = {
          ContentEN = "Ee-ya, ee-ee-ya, ee!",
          DialogueId = 12017701,
          Duration = 1,
          GUID = "1E15C612",
          NextDialogue = 12017702,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "Ee-ya, ee-ee-ya, ee!",
          VoiceName = "voice/$Locale$/story/1201/120177/1E15C612"
        },
        [12017702] = {
          ContentEN = "...! You would burn yourself as fuel? If you continue, your form will fade into nothingness...",
          DialogueId = 12017702,
          Duration = 3,
          GUID = "1E15C63C",
          NextDialogue = 12017703,
          SpeakNpcId = 210013,
          Subtitle = "...! You would burn yourself as fuel? If you continue, your form will fade into nothingness...",
          VoiceName = "voice/$Locale$/story/1201/120177/1E15C63C"
        },
        [12017703] = {
          ContentEN = "Ee!",
          DialogueId = 12017703,
          Duration = 1,
          GUID = "1E15C666",
          NextDialogue = 12017704,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "Ee!",
          VoiceName = "voice/$Locale$/story/1201/120177/1E15C666"
        },
        [12017704] = {
          ContentEN = "...I understand. Then I shall shield you with all that I am.",
          DialogueId = 12017704,
          Duration = 2,
          GUID = "1E15C690",
          SpeakNpcId = 210013,
          Subtitle = "...I understand. Then I shall shield you with all that I am.",
          VoiceName = "voice/$Locale$/story/1201/120177/1E15C690"
        },
        [12017801] = {
          ContentEN = "Fushu, I heard you collapsed while treating the sick — I travelled far to see you... You must stop using the Art of Ephemerality.",
          DialogueId = 12017801,
          GUID = "1E15D67A",
          NextDialogue = 12017802,
          SnapShot = "ECHO",
          SpeakNpcId = 210028,
          Subtitle = "Fushu, I heard you collapsed while treating the sick — I travelled far to see you... You must stop using the Art of Ephemerality.",
          VoiceName = "voice/$Locale$/story/1201/120178/1E15D67A"
        },
        [12017802] = {
          ContentEN = "Thank you for your concern. But I am well now, Sister. You should return.",
          DialogueId = 12017802,
          GUID = "1E15D6A4",
          NextDialogue = 12017803,
          SnapShot = "ECHO",
          SpeakNpcId = 210029,
          Subtitle = "Thank you for your concern. But I am well now, Sister. You should return.",
          VoiceName = "voice/$Locale$/story/1201/120178/1E15D6A4"
        },
        [12017803] = {
          ContentEN = "Well? You call this \"well\"? You're harming your own life, Fushu — can't you see that?",
          DialogueId = 12017803,
          GUID = "1E15D6CE",
          NextDialogue = 12017804,
          SnapShot = "ECHO",
          SpeakNpcId = 210028,
          Subtitle = "Well? You call this \"well\"? You're harming your own life, Fushu — can't you see that?",
          VoiceName = "voice/$Locale$/story/1201/120178/1E15D6CE"
        },
        [12017804] = {
          ContentEN = "Saving lives is the mission the Nine Chapters gave to us. Should I stand idle as others suffer in agony?",
          DialogueId = 12017804,
          GUID = "1E15D6F8",
          NextDialogue = 12017805,
          SnapShot = "ECHO",
          SpeakNpcId = 210029,
          Subtitle = "Saving lives is the mission the Nine Chapters gave to us. Should I stand idle as others suffer in agony?",
          VoiceName = "voice/$Locale$/story/1201/120178/1E15D6F8"
        },
        [12017805] = {
          ContentEN = "Had you not forsaken our ancestral art to pursue <H>pharmacology</>, I wouldn't have pushed myself this far!",
          DialogueId = 12017805,
          GUID = "1E15D722",
          NextDialogue = 12017806,
          SnapShot = "ECHO",
          SpeakNpcId = 210029,
          Subtitle = "Had you not forsaken our ancestral art to pursue pharmacology, I wouldn't have pushed myself this far!",
          VoiceName = "voice/$Locale$/story/1201/120178/1E15D722"
        },
        [12017806] = {
          ContentEN = "Forgive me, Sister... but I cannot bring myself to cherish my own life above others', as you do.",
          DialogueId = 12017806,
          GUID = "1E15D74C",
          NextDialogue = 12017901,
          SnapShot = "ECHO",
          SpeakNpcId = 210029,
          Subtitle = "Forgive me, Sister... but I cannot bring myself to cherish my own life above others', as you do.",
          VoiceName = "voice/$Locale$/story/1201/120178/1E15D74C"
        },
        [12017901] = {
          ContentEN = "...So this is how you see me, Fushu.",
          DialogueId = 12017901,
          Duration = 2,
          GUID = "1E15E6E2",
          SnapShot = "ECHO",
          SpeakNpcId = 210028,
          Subtitle = "...So this is how you see me, Fushu.",
          VoiceName = "voice/$Locale$/story/1201/120179/1E15E6E2"
        },
        [12017902] = {
          ContentEN = "(Those words... they were never what I meant. But once I spoke, the bitterness surged forth like a flood I couldn't hold back.)",
          DialogueId = 12017902,
          Duration = 3,
          GUID = "1E15E70C",
          NextDialogue = 12017903,
          SnapShot = "HEART",
          SpeakNpcId = 210013,
          Subtitle = "(Those words... they were never what I meant. But once I spoke, the bitterness surged forth like a flood I couldn't hold back.)",
          VoiceName = "voice/$Locale$/story/1201/120179/1E15E70C"
        },
        [12017903] = {
          ContentEN = "(In the end, I didn't know how to face her... so I left. That was the last time we ever spoke.)",
          DialogueId = 12017903,
          Duration = 3,
          GUID = "1E15E736",
          SnapShot = "HEART",
          SpeakNpcId = 210013,
          Subtitle = "(In the end, I didn't know how to face her... so I left. That was the last time we ever spoke.)",
          VoiceName = "voice/$Locale$/story/1201/120179/1E15E736"
        },
        [12018001] = {
          Camera = "-361.291565,868.035156,176.938965,0.000062,-2.401447,-174.821503,35.0,506.121063,false,Manual,2.8",
          ContentEN = "Fushu... You're still in the prime of your life. I will not stand by and watch you die.",
          DialogueId = 12018001,
          Duration = 3,
          GUID = "1E15F74A",
          NextDialogue = 12018002,
          SnapShot = "ECHO",
          SpeakNpcId = 210028,
          Subtitle = "Fushu... You're still in the prime of your life. I will not stand by and watch you die.",
          VoiceName = "voice/$Locale$/story/1201/120180/1E15F74A"
        },
        [12018002] = {
          ContentEN = "I will find a cure for you. Even if it costs me everything — my life, my years — I will not rest until I do. Wait for me.",
          DialogueId = 12018002,
          Duration = 2,
          GUID = "1E15F774",
          SnapShot = "ECHO",
          SpeakNpcId = 210028,
          Subtitle = "I will find a cure for you. Even if it costs me everything — my life, my years — I will not rest until I do. Wait for me.",
          VoiceName = "voice/$Locale$/story/1201/120180/1E15F774"
        },
        [12018003] = {
          ContentEN = "...",
          DialogueId = 12018003,
          GUID = "1E15F775",
          SpeakNpcId = 210013,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1201/120180/1E15F775"
        },
        [12018004] = {DialogueId = 12018004, GUID = "1E15F776"},
        [12018101] = {
          ContentEN = "...Sister...",
          DialogueId = 12018101,
          Duration = 2,
          GUID = "1E1607B2",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 12018102,
          SpeakNpcId = 210013,
          Subtitle = "...Sister...",
          VoiceName = "voice/$Locale$/story/1201/120181/1E1607B2"
        },
        [12018102] = {
          ContentEN = "She gave her whole heart to me, and I was blind to it.",
          DialogueId = 12018102,
          Duration = 3,
          GUID = "1E1607DC",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 12018103,
          SpeakNpcId = 210013,
          Subtitle = "She gave her whole heart to me, and I was blind to it.",
          VoiceName = "voice/$Locale$/story/1201/120181/1E1607DC"
        },
        [12018103] = {
          ContentEN = "All I want is to see her again. To say that \"I'm sorry.\"",
          DialogueId = 12018103,
          Duration = 2,
          GUID = "1E160806",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          SpeakNpcId = 210013,
          Subtitle = "All I want is to see her again. To say that \"I'm sorry.\"",
          VoiceName = "voice/$Locale$/story/1201/120181/1E160806"
        },
        [12018201] = {
          ContentEN = "Ee-ee! Ee!",
          DialogueId = 12018201,
          Duration = 1,
          GUID = "1E16181A",
          SpeakNpcId = 210017,
          SpeakNpcName = "UI_CMName_Name_WuyouWuyan",
          Subtitle = "Ee-ee! Ee!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E16181A"
        },
        [12018202] = {
          ContentEN = "Fushu! I thought...",
          DialogueId = 12018202,
          GUID = "1E161844",
          NextDialogue = 12018203,
          SpeakNpcId = 100001,
          Subtitle = "Fushu! I thought...",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161844"
        },
        [12018203] = {
          ContentEN = "I am well. Forgive me for worrying you.",
          DialogueId = 12018203,
          GUID = "1E16186E",
          NextDialogue = 12018204,
          SpeakNpcId = 210013,
          Subtitle = "I am well. Forgive me for worrying you.",
          VoiceName = "voice/$Locale$/story/1201/120182/1E16186E"
        },
        [12018204] = {
          ContentEN = "Thanks to this nameless little one, I did not lose myself in the Oblivion Rift. As the old saying goes: \"By guiding others, we find our own path as well.\" Once again, these words have proven true.",
          DialogueId = 12018204,
          GUID = "1E161898",
          NextDialogue = 12018205,
          SpeakNpcId = 210013,
          Subtitle = "Thanks to this nameless little one, I did not lose myself in the Oblivion Rift. As the old saying goes: \"By guiding others, we find our own path as well.\" Once again, these words have proven true.",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161898"
        },
        [12018205] = {
          ContentEN = "Ee, ee-ya-ee, ee!",
          DialogueId = 12018205,
          GUID = "1E1618C2",
          NextDialogue = 12018206,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "Ee, ee-ya-ee, ee!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E1618C2"
        },
        [12018206] = {
          ContentEN = "I'm glad you're safe. That's a big relief.",
          DialogueId = 12018206,
          GUID = "1E1618EC",
          NextDialogue = 12018207,
          SpeakNpcId = 100001,
          Subtitle = "I'm glad you're safe. That's a big relief.",
          VoiceName = "voice/$Locale$/story/1201/120182/1E1618EC"
        },
        [12018207] = {
          ContentEN = "We are not yet free of peril. Though we have emerged from the deepest shadow, we must not let caution slip. Come — let us return to the world of the living.",
          DialogueId = 12018207,
          GUID = "1E161916",
          NextDialogue = 12018208,
          SpeakNpcId = 210013,
          Subtitle = "We are not yet free of peril. Though we have emerged from the deepest shadow, we must not let caution slip. Come — let us return to the world of the living.",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161916"
        },
        [12018208] = {
          ContentEN = "Right. I'm ready.",
          DialogueId = 12018208,
          GUID = "1E161940",
          NextDialogue = 12018209,
          SpeakNpcId = 100001,
          Subtitle = "Right. I'm ready.",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161940"
        },
        [12018209] = {
          ContentEN = "Follow the Luminous Jades. They shall illuminate the path ahead.",
          DialogueId = 12018209,
          GUID = "1E16196A",
          SpeakNpcId = 210013,
          Subtitle = "Follow the Luminous Jades. They shall illuminate the path ahead.",
          VoiceName = "voice/$Locale$/story/1201/120182/1E16196A"
        },
        [12018210] = {
          ContentEN = "Fushu, what did you see in the River of Forgetting?",
          DialogueId = 12018210,
          GUID = "1E161994",
          NextDialogue = 12018211,
          SpeakNpcId = 100001,
          Subtitle = "Fushu, what did you see in the River of Forgetting?",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161994"
        },
        [12018211] = {
          ContentEN = "Just echoes of the past... people and moments long since gone.",
          DialogueId = 12018211,
          GUID = "1E1619BE",
          NextDialogue = 12018212,
          SpeakNpcId = 210013,
          Subtitle = "Just echoes of the past... people and moments long since gone.",
          VoiceName = "voice/$Locale$/story/1201/120182/1E1619BE"
        },
        [12018212] = {
          ContentEN = "Doesn't sound like they were happy memories...",
          DialogueId = 12018212,
          GUID = "1E1619E8",
          NextDialogue = 12018213,
          SpeakNpcId = 100001,
          Subtitle = "Doesn't sound like they were happy memories...",
          VoiceName = "voice/$Locale$/story/1201/120182/1E1619E8"
        },
        [12018213] = {
          ContentEN = "Help—!",
          DialogueId = 12018213,
          GUID = "1E161A12",
          NextDialogue = 12018214,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "Help—!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161A12"
        },
        [12018214] = {
          ContentEN = "Ee-ya, ee!",
          DialogueId = 12018214,
          GUID = "1E161A3C",
          NextDialogue = 12018215,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          SpeakNpcName = "UI_CMName_Name_WuyouWuyan",
          Subtitle = "Ee-ya, ee!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161A3C"
        },
        [12018215] = {
          ContentEN = "Someone's calling for help — let's move!",
          DialogueId = 12018215,
          GUID = "1E161A66",
          SpeakNpcId = 100001,
          Subtitle = "Someone's calling for help — let's move!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161A66"
        },
        [12018216] = {
          ContentEN = "Thank you, kind soul!",
          DialogueId = 12018216,
          GUID = "1E161A90",
          NextDialogue = 12018217,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "Thank you, kind soul!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161A90"
        },
        [12018217] = {
          ContentEN = "Others... more of us, still trapped.",
          DialogueId = 12018217,
          GUID = "1E161ABA",
          NextDialogue = 12018218,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "Others... more of us, still trapped.",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161ABA"
        },
        [12018218] = {
          ContentEN = "This place... feels wrong. Must leave. Need everyone's strength, to escape!",
          DialogueId = 12018218,
          GUID = "1E161AE4",
          NextDialogue = 12018219,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "This place... feels wrong. Must leave. Need everyone's strength, to escape!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161AE4"
        },
        [12018219] = {
          ContentEN = "You mean there are still more of you trapped here? Got it. I'll keep an eye out.",
          DialogueId = 12018219,
          GUID = "1E161B0E",
          NextDialogue = 12018220,
          SpeakNpcId = 100001,
          Subtitle = "You mean there are still more of you trapped here? Got it. I'll keep an eye out.",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161B0E"
        },
        [12018220] = {
          ContentEN = "Thank you, thank you! My strength... take it!",
          DialogueId = 12018220,
          GUID = "1E161B38",
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "Thank you, thank you! My strength... take it!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161B38"
        },
        [12018221] = {
