          DialogueId = 12018231,
          GUID = "1E161D06",
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          SpeakNpcName = "UI_Npc_Name_WuyoushengA&B",
          Subtitle = "Ee-ya! Now we're all set — let's go!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161D06"
        },
        [12018232] = {
          ContentEN = "Ee-ee, ya!",
