          SpeakNpcName = "UI_Npc_Name_WuyoushengShoukun",
          Subtitle = "Ee-ee, ya!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161D30"
        },
        [12018233] = {
          ContentEN = "The mean flowers have trapped my friends! Please, help them!",
          DialogueId = 12018233,
          GUID = "1E161D5A",
          NextDialogue = 12018234,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "The mean flowers have trapped my friends! Please, help them!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161D5A"
        },
        [12018234] = {
          ContentEN = "I have seen this kind of flower in the old records. When its petals are shut, no blade can cut it. We must wait for it to bloom.",
          DialogueId = 12018234,
          GUID = "1E161D84",
          SpeakNpcId = 210013,
          Subtitle = "I have seen this kind of flower in the old records. When its petals are shut, no blade can cut it. We must wait for it to bloom.",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161D84"
        },
        [12018235] = {
          ContentEN = "The core is exposed — strike now!",
          DialogueId = 12018235,
          GUID = "1E161DAE",
          SpeakNpcId = 210013,
          Subtitle = "The core is exposed — strike now!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161DAE"
        },
        [12018236] = {
          ContentEN = "Lady Zhuyou! And the white-haired stranger — thank you both!",
          DialogueId = 12018236,
