          SnapShot = "WUYOU",
          SpeakNpcName = "UI_Npc_Name_WuyoushengShoukun",
          Subtitle = "Lady Zhuyou! And the white-haired stranger — thank you both!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161DD8"
        },
        [12018237] = {
          ContentEN = "Let me lend a hand too! My iron headbutt can even crack the earth!",
