          SpeakNpcName = "UI_Npc_Name_WuyoushengShoukun",
          Subtitle = "Let me lend a hand too! My iron headbutt can even crack the earth!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161E02"
        },
        [12018238] = {
          ContentEN = "The last ones! Friends still trapped!",
          DialogueId = 12018238,
          GUID = "1E161E2C",
          NextDialogue = 12018239,
          SnapShot = "WUYOU",
          SpeakNpcName = "UI_Npc_Name_WuyoushengA",
          Subtitle = "The last ones! Friends still trapped!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161E2C"
        },
        [12018239] = {
          ContentEN = "It is the same kind of flower as before. {nickname}, wait for it to bloom fully — then strike the core and all the vines in one stroke.",
          DialogueId = 12018239,
          GUID = "1E161E56",
          SpeakNpcId = 210013,
          Subtitle = "It is the same kind of flower as before. , wait for it to bloom fully — then strike the core and all the vines in one stroke.",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161E56"
        },
        [12018240] = {
          ContentEN = "With all my years of martial skill, I nearly met my end here... How shameful...",
          DialogueId = 12018240,
          GUID = "1E161E80",
          NextDialogue = 12018241,
          SnapShot = "WUYOU",
          SpeakNpcName = "UI_CMName_Name_MatureWuyou",
          Subtitle = "With all my years of martial skill, I nearly met my end here... How shameful...",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161E80"
        },
        [12018241] = {
          ContentEN = "Now we're all here — no one left behind, not a single one!",
          DialogueId = 12018241,
          GUID = "1E161EAA",
          NextDialogue = 12018242,
          SnapShot = "WUYOU",
          SpeakNpcName = "UI_Npc_Name_WuyoushengA",
          Subtitle = "Now we're all here — no one left behind, not a single one!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161EAA"
        },
        [12018242] = {
          ContentEN = "The final path is blocked by a monstrous Filthoid flower. Let me stand with you. Together, we shall cut it down and restore this place!",
          DialogueId = 12018242,
          GUID = "1E161ED4",
          SnapShot = "WUYOU",
          SpeakNpcName = "UI_CMName_Name_MatureWuyou",
          Subtitle = "The final path is blocked by a monstrous Filthoid flower. Let me stand with you. Together, we shall cut it down and restore this place!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161ED4"
        },
        [12018243] = {
          ContentEN = "{nickname}, the River of Forgetting is about to collapse! We must end this now!",
          DialogueId = 12018243,
          GUID = "1E161EFE",
          Subtitle = ", the River of Forgetting is about to collapse! We must end this now!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161EFE"
        },
        [12018244] = {
