          DialogueId = 12018244,
          GUID = "1E161F28",
          Subtitle = "Now — take my hand.",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161F28"
        },
        [12018300] = {
          ContentEN = "Thank you, both of you! We'll never forget this kindness. Goodbye for now!",
          DialogueId = 12018300,
          GUID = "1E162858",
          NextDialogue = 12018301,
          RelatedWikiId = {
