        [12018410] = {
          Camera = "64.890961,321.150482,91.39502,0.000176,5.395296,-137.398178,24.0,297.770538,false,Manual,6.0",
          ContentEN = "Come, then. Let us speak as we walk. I shall do my best to answer what questions weigh upon your mind.",
