          SpeakNpcId = 210012,
          Subtitle = "Come, then. Let us speak as we walk. I shall do my best to answer what questions weigh upon your mind.",
          TalkActionId = {
            [1] = "210012:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120184/1E163A64"
        },
        [12018501] = {
          ContentEN = "Tell me, young friend — have you ever wondered why the Scourge of Zhuyin takes the form of Sable Bi'an?",
          DialogueId = 12018501,
          Duration = 3,
          GUID = "1E164952",
          NextDialogue = 12018502,
          SpeakNpcId = 210012,
          Subtitle = "Tell me, young friend — have you ever wondered why the Scourge of Zhuyin takes the form of Sable Bi'an?",
          VoiceName = "voice/$Locale$/story/1201/120185/1E164952"
        },
        [12018502] = {
          ContentEN = "The Bi'an, revered in Huaxu, is elsewhere known as a Filthoid — a harbinger of calamity and dread. The difference lies in the constraints imposed by the Nine Chapters of Dafeng.",
          DialogueId = 12018502,
          Duration = 5,
          GUID = "1E16497C",
          SpeakNpcId = 210012,
          Subtitle = "The Bi'an, revered in Huaxu, is elsewhere known as a Filthoid — a harbinger of calamity and dread. The difference lies in the constraints imposed by the Nine Chapters of Dafeng.",
          VoiceName = "voice/$Locale$/story/1201/120185/1E16497C"
        },
        [12018503] = {
          ContentEN = "The emergence of these Sable Bi'an suggests but one troubling possibility: that the Nine Chapters are beginning to waver.",
          DialogueId = 12018503,
          Duration = 3,
          GUID = "1E1649A6",
          NextDialogue = 12018504,
          SpeakNpcId = 210012,
          Subtitle = "The emergence of these Sable Bi'an suggests but one troubling possibility: that the Nine Chapters are beginning to waver.",
          VoiceName = "voice/$Locale$/story/1201/120185/1E1649A6"
        },
        [12018504] = {
          ContentEN = "But Proprietress Zhiliu said once we resolve the Scourge of Zhuyin, everything will go back to normal.",
          DialogueId = 12018504,
          Duration = 3,
          GUID = "1E1649D0",
          NextDialogue = 12018505,
          SpeakNpcId = 100001,
          Subtitle = "But Proprietress Zhiliu said once we resolve the Scourge of Zhuyin, everything will go back to normal.",
          VoiceName = "voice/$Locale$/story/1201/120185/1E1649D0"
        },
        [12018505] = {
          ContentEN = "Indeed. But that would be a temporary reprieve at best.",
          DialogueId = 12018505,
          Duration = 2,
          GUID = "1E1649FA",
          NextDialogue = 12018506,
          SpeakNpcId = 210012,
          Subtitle = "Indeed. But that would be a temporary reprieve at best.",
          VoiceName = "voice/$Locale$/story/1201/120185/1E1649FA"
        },
        [12018506] = {
          ContentEN = "What if it returns, again and again, steadily hollowing out the people's strength?",
          DialogueId = 12018506,
          Duration = 3,
          GUID = "1E164A24",
          NextDialogue = 12018507,
          SpeakNpcId = 210012,
          Subtitle = "What if it returns, again and again, steadily hollowing out the people's strength?",
          VoiceName = "voice/$Locale$/story/1201/120185/1E164A24"
        },
        [12018507] = {
          ContentEN = "The Proprietress has her own considerations — some suspicions she may not yet share with you.",
          DialogueId = 12018507,
          Duration = 3,
          GUID = "1E164A4E",
          NextDialogue = 12018508,
          SpeakNpcId = 210012,
          Subtitle = "The Proprietress has her own considerations — some suspicions she may not yet share with you.",
          VoiceName = "voice/$Locale$/story/1201/120185/1E164A4E"
        },
        [12018508] = {
          ContentEN = "From my perspective... if the very foundations of the Nine Chapters are compromised, no amount of patchwork can truly cure the rot.",
          DialogueId = 12018508,
          Duration = 3,
          GUID = "1E164A78",
          NextDialogue = 12018509,
          SpeakNpcId = 210012,
          Subtitle = "From my perspective... if the very foundations of the Nine Chapters are compromised, no amount of patchwork can truly cure the rot.",
          VoiceName = "voice/$Locale$/story/1201/120185/1E164A78"
        },
        [12018509] = {
          ContentEN = "So you're saying... you've never really believed in the Nine Chapters?",
          DialogueId = 12018509,
          Duration = 2,
          GUID = "1E164AA2",
          NextDialogue = 12018510,
          SpeakNpcId = 100001,
          Subtitle = "So you're saying... you've never really believed in the Nine Chapters?",
          VoiceName = "voice/$Locale$/story/1201/120185/1E164AA2"
        },
        [12018510] = {
          ContentEN = "Haha... No need to be so categorical, young friend. As the saying goes: Know yourself, know your enemy, and you shall never taste defeat.",
          DialogueId = 12018510,
          Duration = 4,
          GUID = "1E164ACC",
          NextDialogue = 12018511,
          SpeakNpcId = 210012,
          Subtitle = "Haha... No need to be so categorical, young friend. As the saying goes: Know yourself, know your enemy, and you shall never taste defeat.",
          VoiceName = "voice/$Locale$/story/1201/120185/1E164ACC"
        },
        [12018511] = {
          ContentEN = "This trip's purpose is to capture a Bi'an for my \"collection.\" I intend to study it thoroughly — a form of insurance against the worst.",
          DialogueId = 12018511,
          Duration = 5,
          GUID = "1E164AF6",
          NextDialogue = 12018512,
          SpeakNpcId = 210012,
          Subtitle = "This trip's purpose is to capture a Bi'an for my \"collection.\" I intend to study it thoroughly — a form of insurance against the worst.",
          VoiceName = "voice/$Locale$/story/1201/120185/1E164AF6"
        },
        [12018512] = {
          ContentEN = "So — does this reasoning satisfy you?",
          DialogueId = 12018512,
          Duration = 2,
          GUID = "1E164B20",
          NextDialogue = 12018513,
          SpeakNpcId = 210012,
          Subtitle = "So — does this reasoning satisfy you?",
          VoiceName = "voice/$Locale$/story/1201/120185/1E164B20"
        },
        [12018513] = {
          ContentEN = "...Won't turning against a Bi'an bring punishment from the Nine Chapters?",
          DialogueId = 12018513,
          Duration = 5,
          GUID = "1E164B4A",
          NextDialogue = 12018514,
          SpeakNpcId = 100001,
          Subtitle = "...Won't turning against a Bi'an bring punishment from the Nine Chapters?",
          VoiceName = "voice/$Locale$/story/1201/120185/1E164B4A"
        },
        [12018514] = {
          ContentEN = "Heh. We in the black market have long walked the knife's edge of the Nine Chapters. We know well how to stay within bounds.",
          DialogueId = 12018514,
          Duration = 2,
          GUID = "1E164B74",
          SpeakNpcId = 210012,
          Subtitle = "Heh. We in the black market have long walked the knife's edge of the Nine Chapters. We know well how to stay within bounds.",
          VoiceName = "voice/$Locale$/story/1201/120185/1E164B74"
        },
