        [12019908] = {
          ContentEN = "Why do you both act as though I intend to kill him? Quite the opposite — I mean to offer him a chance to break free of the Nine Chapters' shackles.",
          DialogueId = 12019908,
          GUID = "1E173028",
          NextDialogue = 12019909,
          SpeakNpcId = 210012,
          Subtitle = "Why do you both act as though I intend to kill him? Quite the opposite — I mean to offer him a chance to break free of the Nine Chapters' shackles.",
          VoiceName = "voice/$Locale$/story/1201/120199/1E173028"
        },
        [12019909] = {
          ContentEN = "And did you ever ask him if he wanted that?",
          DialogueId = 12019909,
          GUID = "1E173052",
          NextDialogue = 12019910,
          SpeakNpcId = 100001,
          Subtitle = "And did you ever ask him if he wanted that?",
          VoiceName = "voice/$Locale$/story/1201/120199/1E173052"
        },
        [12019910] = {
          ContentEN = "Your actions have already endangered the people and the realm. I ask that you stand down.",
          DialogueId = 12019910,
          GUID = "1E17307C",
          NextDialogue = 12019911,
          SpeakNpcId = 210007,
          Subtitle = "Your actions have already endangered the people and the realm. I ask that you stand down.",
          VoiceName = "voice/$Locale$/story/1201/120199/1E17307C"
        },
        [12019911] = {
          ContentEN = "Hehe... tell me — am I the one endangering the realm, or is it the manners and morals of the age? Will you pretend not to see the cracks the Nine Chapters have wrought?",
          DialogueId = 12019911,
          GUID = "1E1730A6",
          NextDialogue = 12019912,
          SpeakNpcId = 210012,
          Subtitle = "Hehe... tell me — am I the one endangering the realm, or is it the manners and morals of the age? Will you pretend not to see the cracks the Nine Chapters have wrought?",
          VoiceName = "voice/$Locale$/story/1201/120199/1E1730A6"
        },
        [12019912] = {
          ContentEN = "If I could decipher the means by which you became a Magistrate of Yingtian, I might forge a counter to the Sable Bi'an — and perhaps grant you the freedom you seek. Would that not be a fitting outcome for all?",
          DialogueId = 12019912,
          GUID = "1E1730D0",
          NextDialogue = 12019913,
          SpeakNpcId = 210012,
          Subtitle = "If I could decipher the means by which you became a Magistrate of Yingtian, I might forge a counter to the Sable Bi'an — and perhaps grant you the freedom you seek. Would that not be a fitting outcome for all?",
          VoiceName = "voice/$Locale$/story/1201/120199/1E1730D0"
        },
        [12019913] = {
          ContentEN = "...This is not your burden to bear.",
          DialogueId = 12019913,
          GUID = "1E1730FA",
          NextDialogue = 12019914,
          SpeakNpcId = 210007,
          Subtitle = "...This is not your burden to bear.",
          VoiceName = "voice/$Locale$/story/1201/120199/1E1730FA"
        },
        [12019914] = {
          ContentEN = "He's made himself clear. I won't help you.",
          DialogueId = 12019914,
          GUID = "1E173124",
          NextDialogue = 12019915,
          SpeakNpcId = 100001,
          Subtitle = "He's made himself clear. I won't help you.",
          VoiceName = "voice/$Locale$/story/1201/120199/1E173124"
        },
        [12019915] = {
          ContentEN = "Still clinging to your tiresome pretence of duty and honour, I see... Tsk. I had hoped it wouldn't come to this.",
          DialogueId = 12019915,
          GUID = "1E17314E",
          SpeakNpcId = 210012,
          Subtitle = "Still clinging to your tiresome pretence of duty and honour, I see... Tsk. I had hoped it wouldn't come to this.",
          VoiceName = "voice/$Locale$/story/1201/120199/1E17314E"
        },
        [12020001] = {
          ContentEN = "Wh—What are you doing!?",
          DialogueId = 12020001,
          Duration = 2,
          GUID = "1E173F6A",
          SpeakNpcId = 200002,
          Subtitle = "Wh—What are you doing!?",
          VoiceName = "voice/$Locale$/story/1201/120200/1E173F6A"
        },
        [12020002] = {
          ContentEN = "{nickname}, you wouldn't raise your blade against him — but he was all too ready to strike at you.",
          DialogueId = 12020002,
          Duration = 3,
          GUID = "1E173F94",
          SpeakNpcId = 210012,
          Subtitle = ", you wouldn't raise your blade against him — but he was all too ready to strike at you.",
          VoiceName = "voice/$Locale$/story/1201/120200/1E173F94"
        },
        [12020003] = {
          ContentEN = "Well then, Magistrate of Yingtian — your victim stands before you. Will you stand by and do nothing? That is not what the Nine Chapters dictates.",
          DialogueId = 12020003,
          Duration = 5,
          GUID = "1E173FBE",
          SpeakNpcId = 210012,
          Subtitle = "Well then, Magistrate of Yingtian — your victim stands before you. Will you stand by and do nothing? That is not what the Nine Chapters dictates.",
          VoiceName = "voice/$Locale$/story/1201/120200/1E173FBE"
        },
        [12020004] = {
          ContentEN = "...Shame on you!! You attacked my Little Minion first!",
          DialogueId = 12020004,
          Duration = 3,
          GUID = "1E173FE8",
          SpeakNpcId = 200002,
          Subtitle = "...Shame on you!! You attacked my Little Minion first!",
          VoiceName = "voice/$Locale$/story/1201/120200/1E173FE8"
        },
        [12020005] = {
          ContentEN = "Hahaha...! Exactly. Punishing only those who have drawn blood, without regard for motive or for justice. Is this blind dogma what you fight to uphold?",
          DialogueId = 12020005,
          Duration = 5,
          GUID = "1E174012",
          SpeakNpcId = 210012,
          Subtitle = "Hahaha...! Exactly. Punishing only those who have drawn blood, without regard for motive or for justice. Is this blind dogma what you fight to uphold?",
          VoiceName = "voice/$Locale$/story/1201/120200/1E174012"
        },
        [12020006] = {
          ContentEN = "...Forgive me, {nickname}. This is not my will.",
          DialogueId = 12020006,
          Duration = 2,
          GUID = "1E17403C",
          SpeakNpcId = 210007,
          Subtitle = "...Forgive me, . This is not my will.",
          VoiceName = "voice/$Locale$/story/1201/120200/1E17403C"
        },
        [12020101] = {
          ContentEN = "Watch my moves closely — and dodge carefully.",
          DialogueId = 12020101,
          Duration = 2,
          GUID = "1E174FD2",
          NextDialogue = 12020102,
          SpeakNpcId = 210007,
          Subtitle = "Watch my moves closely — and dodge carefully.",
          VoiceName = "voice/$Locale$/story/1201/120201/1E174FD2"
        },
        [12020102] = {
          ContentEN = "I'll resist the Nine Chapters' commands with all I have... Please — don't let yourself be hurt.",
          DialogueId = 12020102,
          Duration = 3,
          GUID = "1E174FFC",
          SpeakNpcId = 210007,
          Subtitle = "I'll resist the Nine Chapters' commands with all I have... Please — don't let yourself be hurt.",
          VoiceName = "voice/$Locale$/story/1201/120201/1E174FFC"
        },
        [12020103] = {
          ContentEN = "{nickname}, the next strike... Be wary.",
          DialogueId = 12020103,
          GUID = "1E174FFD",
          NextDialogue = 12020104,
          SpeakNpcId = 210007,
          Subtitle = ", the next strike... Be wary.",
          VoiceName = "voice/$Locale$/story/1201/120201/1E174FFD"
        },
        [12020104] = {
          ContentEN = "The assault is too fierce! So this is the power of the Nine Chapters...",
          DialogueId = 12020104,
          GUID = "1E174FFF",
          NextDialogue = 12020105,
          SpeakNpcId = 200002,
          Subtitle = "The assault is too fierce! So this is the power of the Nine Chapters...",
          VoiceName = "voice/$Locale$/story/1201/120201/1E174FFF"
        },
        [12020105] = {
          ContentEN = "What do we do, Little Minion? Are you alright?!",
          DialogueId = 12020105,
          GUID = "1E174111",
          NextDialogue = 12020106,
          SpeakNpcId = 200002,
          Subtitle = "What do we do, Little Minion? Are you alright?!",
          VoiceName = "voice/$Locale$/story/1201/120201/1E174111"
        },
        [12020106] = {
          ContentEN = "Don't worry, I can handle it. Yuming, are you okay?",
          DialogueId = 12020106,
          GUID = "1E174112",
          NextDialogue = 12020107,
          SpeakNpcId = 100001,
          Subtitle = "Don't worry, I can handle it. Yuming, are you okay?",
          VoiceName = "voice/$Locale$/story/1201/120201/1E174112"
        },
        [12020107] = {
          ContentEN = "Do not concern yourself with me. I shall put an end to this with all haste.",
          DialogueId = 12020107,
          GUID = "1E174113",
          SpeakNpcId = 210007,
          Subtitle = "Do not concern yourself with me. I shall put an end to this with all haste.",
          VoiceName = "voice/$Locale$/story/1201/120201/1E174113"
        },
        [12020108] = {
          ContentEN = "Stop it, please...",
          DialogueId = 12020108,
          GUID = "1E174114",
          NextDialogue = 12020109,
          SpeakNpcId = 200002,
          Subtitle = "Stop it, please...",
          VoiceName = "voice/$Locale$/story/1201/120201/1E174114"
        },
        [12020109] = {
          ContentEN = "Why do you two have to fight like this? It's so frustrating!",
          DialogueId = 12020109,
          GUID = "1E174115",
          NextDialogue = 12020110,
          SpeakNpcId = 200002,
          Subtitle = "Why do you two have to fight like this? It's so frustrating!",
          VoiceName = "voice/$Locale$/story/1201/120201/1E174115"
        },
        [12020110] = {
          ContentEN = "Stupid Nine Chapters... No, wait! That despicable guy is definitely worse!",
          DialogueId = 12020110,
          GUID = "1E174116",
          NextDialogue = 12020111,
          SpeakNpcId = 200002,
          Subtitle = "Stupid Nine Chapters... No, wait! That despicable guy is definitely worse!",
          VoiceName = "voice/$Locale$/story/1201/120201/1E174116"
        },
        [12020111] = {
          ContentEN = "Heh. May I take that as a compliment?",
          DialogueId = 12020111,
          GUID = "1E174117",
          SpeakNpcId = 210012,
          Subtitle = "Heh. May I take that as a compliment?",
          VoiceName = "voice/$Locale$/story/1201/120201/1E174117"
        },
        [12020201] = {
          ContentEN = "Hey! You lot - what the hell are you all doing here, ganging up on my shixiong!?",
          DialogueId = 12020201,
          Duration = 2,
          GUID = "1E17603A",
          SpeakNpcId = 210021,
          Subtitle = "Hey! You lot - what the hell are you all doing here, ganging up on my shixiong!?",
          VoiceName = "voice/$Locale$/story/1201/120202/1E17603A"
        },
        [12020202] = {
          ContentEN = "Boss, he's trying to get away...!",
          DialogueId = 12020202,
          Duration = 2,
          GUID = "1E176064",
          Subtitle = "Boss, he's trying to get away...!",
          VoiceName = "voice/$Locale$/story/1201/120202/1E176064"
        },
        [12020203] = {
