        },
        [12020301] = {
          Camera = "-78.574219,498.462891,113.020996,0.000014,-0.99994,-74.596542,35.0,100000.0,false,DoNotOverride,2.8",
          ContentEN = "Finally got to see my shixiong again, only for you lot to ruin everything. Now he's slipped away once more.",
          DialogueId = 12020301,
          GUID = "1E1770A2",
          NextDialogue = 12020302,
          RelatedWikiId = {
            [1] = 203007,
            [2] = 203004,
            [3] = 203005
          },
          SpeakNpcId = 210021,
          Subtitle = "Finally got to see my shixiong again, only for you lot to ruin everything. Now he's slipped away once more.",
          VoiceName = "voice/$Locale$/story/1201/120203/1E1770A2"
        },
        [12020302] = {
          ContentEN = "This osmanthus cake... I've been carrying it around for so long, it's gone cold and hard. Who knows when I'll ever get to give it to him?",
          DialogueId = 12020302,
          GUID = "1E1770CC",
          NextDialogue = 12020303,
          SpeakNpcId = 210021,
          Subtitle = "This osmanthus cake... I've been carrying it around for so long, it's gone cold and hard. Who knows when I'll ever get to give it to him?",
          VoiceName = "voice/$Locale$/story/1201/120203/1E1770CC"
        },
        [12020303] = {
          ContentEN = "So the one you've been looking for was Yuming.",
          DialogueId = 12020303,
          GUID = "1E1770F6",
          NextDialogue = 12020304,
          SpeakNpcId = 100001,
          Subtitle = "So the one you've been looking for was Yuming.",
          VoiceName = "voice/$Locale$/story/1201/120203/1E1770F6"
        },
        [12020304] = {
          ContentEN = "Say... what are you doing here? What exactly happened here before I came?",
          DialogueId = 12020304,
          GUID = "1E177120",
          NextDialogue = 12020305,
          SpeakNpcId = 210021,
          Subtitle = "Say... what are you doing here? What exactly happened here before I came?",
          VoiceName = "voice/$Locale$/story/1201/120203/1E177120"
        },
        [12020305] = {
          ContentEN = "(Fill him in)",
          DialogueId = 12020305,
          GUID = "1E17714A",
          IsBlack = 1,
          NextDialogue = 12020306,
          Subtitle = "(Fill him in)",
          VoiceName = "voice/$Locale$/story/1201/120203/1E17714A"
        },
        [12020306] = {
          ContentEN = "That bastard — he set you up, didn't he!? {nickname}, are you hurt?",
          DialogueId = 12020306,
          GUID = "1E177174",
          NextDialogue = 12020307,
          SpeakNpcId = 210021,
          Subtitle = "That bastard — he set you up, didn't he!? , are you hurt?",
          VoiceName = "voice/$Locale$/story/1201/120203/1E177174"
        },
        [12020307] = {
          ContentEN = "Damn it... my shixiong's tied down by those nonsense rules, but I'm not. Anyone who messes with him — I'll make sure they pay for it!",
          DialogueId = 12020307,
          GUID = "1E17719E",
          NextDialogue = 12020308,
          SpeakNpcId = 210021,
          Subtitle = "Damn it... my shixiong's tied down by those nonsense rules, but I'm not. Anyone who messes with him — I'll make sure they pay for it!",
          VoiceName = "voice/$Locale$/story/1201/120203/1E17719E"
        },
        [12020308] = {
          ContentEN = "I've had it with those people too! Let's team up and turn this whole place upside down!",
          DialogueId = 12020308,
          GUID = "1E1771C8",
          NextDialogue = 12020309,
          SpeakNpcId = 200002,
          Subtitle = "I've had it with those people too! Let's team up and turn this whole place upside down!",
          VoiceName = "voice/$Locale$/story/1201/120203/1E1771C8"
        },
        [12020309] = {
          ContentEN = "Alright, alright — no need for all this fuss. I heard every word, clear as day. Consider this my most humble apology.",
          DialogueId = 12020309,
          GUID = "1E1771F2",
          NextDialogue = 12020310,
          SpeakNpcId = 210012,
          Subtitle = "Alright, alright — no need for all this fuss. I heard every word, clear as day. Consider this my most humble apology.",
          VoiceName = "voice/$Locale$/story/1201/120203/1E1771F2"
        },
        [12020310] = {
          ContentEN = "You'd better keep your mouth shut. I'm still mad at you.",
          DialogueId = 12020310,
          GUID = "1E17721C",
          NextDialogue = 12020311,
          SpeakNpcId = 100001,
          Subtitle = "You'd better keep your mouth shut. I'm still mad at you.",
          VoiceName = "voice/$Locale$/story/1201/120203/1E17721C"
        },
        [12020311] = {
          ContentEN = "The only reason I'm not coming after you right now is because I refuse to stoop to your level.",
          DialogueId = 12020311,
          GUID = "1E177246",
          NextDialogue = 12020312,
          SpeakNpcId = 100001,
          Subtitle = "The only reason I'm not coming after you right now is because I refuse to stoop to your level.",
          VoiceName = "voice/$Locale$/story/1201/120203/1E177246"
        },
        [12020312] = {
          ContentEN = "Fair enough. Such magnanimity is admirable, young friend.",
          DialogueId = 12020312,
          GUID = "1E177270",
          NextDialogue = 12020313,
          SpeakNpcId = 210012,
          Subtitle = "Fair enough. Such magnanimity is admirable, young friend.",
          VoiceName = "voice/$Locale$/story/1201/120203/1E177270"
        },
        [12020313] = {
          ContentEN = "And your loyalty... truly stirring. You have my respect. I'll gladly shoulder the blame for this failure: I'll let the \"prey\" go out of deference to you. As for Proprietress Zhiliu, I'll explain to her myself.",
          DialogueId = 12020313,
          GUID = "1E17729A",
          NextDialogue = 12020314,
          SpeakNpcId = 210012,
          Subtitle = "And your loyalty... truly stirring. You have my respect. I'll gladly shoulder the blame for this failure: I'll let the \"prey\" go out of deference to you. As for Proprietress Zhiliu, I'll explain to her myself.",
          VoiceName = "voice/$Locale$/story/1201/120203/1E17729A"
        },
        [12020314] = {
          ContentEN = "Are you saying this is all Proprietress Zhiliu's idea? I don't buy it. And another thing — stop calling him the \"prey.\"",
          DialogueId = 12020314,
          GUID = "1E1772C4",
          NextDialogue = 12020315,
          SpeakNpcId = 100001,
          Subtitle = "Are you saying this is all Proprietress Zhiliu's idea? I don't buy it. And another thing — stop calling him the \"prey.\"",
          VoiceName = "voice/$Locale$/story/1201/120203/1E1772C4"
        },
        [12020315] = {
          ContentEN = "Haha... as I told you before, the Proprietress has her own designs.",
          DialogueId = 12020315,
          GUID = "1E1772EE",
          NextDialogue = 12020316,
          SpeakNpcId = 210012,
          Subtitle = "Haha... as I told you before, the Proprietress has her own designs.",
          VoiceName = "voice/$Locale$/story/1201/120203/1E1772EE"
        },
        [12020316] = {
          ContentEN = "If it weren't for you lot butting in, I'd have had a proper reunion with my shixiong! Old Fox — how exactly are you planning to make this right?",
          DialogueId = 12020316,
          GUID = "1E177318",
          NextDialogue = 12020317,
          SpeakNpcId = 210021,
          Subtitle = "If it weren't for you lot butting in, I'd have had a proper reunion with my shixiong! Old Fox — how exactly are you planning to make this right?",
          VoiceName = "voice/$Locale$/story/1201/120203/1E177318"
        },
        [12020317] = {
          ContentEN = "Oh? From what I saw, that Magistrate of Yingtian is avoiding you quite deliberately. If he'd stayed behind, and the two of you joined forces — who here could possibly stand in your way?",
          DialogueId = 12020317,
          GUID = "1E177342",
          NextDialogue = 12020318,
          SpeakNpcId = 210012,
          Subtitle = "Oh? From what I saw, that Magistrate of Yingtian is avoiding you quite deliberately. If he'd stayed behind, and the two of you joined forces — who here could possibly stand in your way?",
          VoiceName = "voice/$Locale$/story/1201/120203/1E177342"
        },
        [12020318] = {
          ContentEN = "Shut it! Another word and I'll shut it for you myself!",
          DialogueId = 12020318,
          GUID = "1E17736C",
          NextDialogue = 12020319,
          SpeakNpcId = 210021,
          Subtitle = "Shut it! Another word and I'll shut it for you myself!",
          VoiceName = "voice/$Locale$/story/1201/120203/1E17736C"
        },
        [12020319] = {
          ContentEN = "Hahahaha!",
          DialogueId = 12020319,
          GUID = "1E177396",
          NextDialogue = 12020320,
          SpeakNpcId = 210012,
          Subtitle = "Hahahaha!",
          VoiceName = "voice/$Locale$/story/1201/120203/1E177396"
        },
        [12020320] = {
          ContentEN = "But enough chatter. I have other matters to attend to. I'll take my leave for now.",
          DialogueId = 12020320,
          GUID = "1E1773C0",
          NextDialogue = 12020321,
          SpeakNpcId = 210012,
          Subtitle = "But enough chatter. I have other matters to attend to. I'll take my leave for now.",
          VoiceName = "voice/$Locale$/story/1201/120203/1E1773C0"
        },
        [12020321] = {
          ContentEN = "A small piece of advice — Yuming slipped off that way. If you don't hurry, you'll lose him yet again.",
          DialogueId = 12020321,
          GUID = "1E1773EA",
          NextDialogue = 12020322,
          SpeakNpcId = 210012,
          Subtitle = "A small piece of advice — Yuming slipped off that way. If you don't hurry, you'll lose him yet again.",
          VoiceName = "voice/$Locale$/story/1201/120203/1E1773EA"
        },
        [12020322] = {
          ContentEN = "And one last word for you, young friend — not everyone is as candid as I am. You may know a man's face... but never assume you know his heart.",
          DialogueId = 12020322,
          GUID = "1E177414",
          SpeakNpcId = 210012,
          Subtitle = "And one last word for you, young friend — not everyone is as candid as I am. You may know a man's face... but never assume you know his heart.",
          VoiceName = "voice/$Locale$/story/1201/120203/1E177414"
        },
        [12020401] = {
          ContentEN = "There he goes again — so full of himself!",
          DialogueId = 12020401,
          Duration = 2,
          GUID = "1E17810A",
          NextDialogue = 12020402,
          SpeakNpcId = 200002,
          Subtitle = "There he goes again — so full of himself!",
