          NextDialogue = 12022011,
          SnapShot = "MEMORY",
          Subtitle = "Back off! This rite must not be marred!",
          VoiceName = "voice/$Locale$/story/1201/120220/1E188904"
        },
        [12022011] = {
          ContentEN = "For centuries thereafter, the Sable Bi'an arose — calamity blooming in the shadows... The ruin we see today was sown in that distant hour!",
          DialogueId = 12022011,
          GUID = "1E18892E",
          NextDialogue = 12022012,
          SnapShot = "MEMORY",
          Subtitle = "For centuries thereafter, the Sable Bi'an arose — calamity blooming in the shadows... The ruin we see today was sown in that distant hour!",
          VoiceName = "voice/$Locale$/story/1201/120220/1E18892E"
        },
        [12022012] = {
          ContentEN = "Zhuyin springs from the depths of the mortal heart. So long as human desire endures, how can Zhuyin be truly undone?",
          DialogueId = 12022012,
          GUID = "1E188958",
          NextDialogue = 12022013,
          SnapShot = "MEMORY",
          Subtitle = "Zhuyin springs from the depths of the mortal heart. So long as human desire endures, how can Zhuyin be truly undone?",
          VoiceName = "voice/$Locale$/story/1201/120220/1E188958"
        },
        [12022013] = {
          ContentEN = "To seal it by secret arts is but to ladle water upon a boiling pot — once spent, it shall rise anew, a hidden canker in the bone, sure to fester into grievous affliction!",
