          DialogueId = 12022812,
          GUID = "1E190C98",
          SpeakNpcId = 100001,
          Subtitle = "Right. We're off. Stay safe, everyone.",
          VoiceName = "voice/$Locale$/story/1201/120228/1E190C98"
        },
        [12022813] = {
          ContentEN = "Are the barricades set in the road?",
