          Subtitle = "Heh... and what do you suppose?"
        },
        [12025417] = {
          ContentEN = "How do I get to the black market to pick up the tools?",
          DialogueId = 12025417,
          GUID = "1E1AB7FA",
          NextDialogue = 12025418,
          Subtitle = "How do I get to the black market to pick up the tools?"
        },
        [12025418] = {
