          DialogueId = 12025418,
          GUID = "1E1AB824",
          NextDialogue = 12025419,
          SpeakNpcId = 210115,
          Subtitle = "First-time visitors to the black market must enter through the coastal cavern, carrying a specific pendant. If they see you emerge with it, they will recognise you as one of ours."
        },
        [12025419] = {
          ContentEN = "Why the coastal cave? Can't I just take the main road?",
          DialogueId = 12025419,
          GUID = "1E1AB84E",
          NextDialogue = 12025420,
          SpeakNpcId = 100001,
          Subtitle = "Why the coastal cave? Can't I just take the main road?"
        },
        [12025420] = {
          ContentEN = "As I mentioned, it is simply how the identification works.",
          DialogueId = 12025420,
          GUID = "1E1AB878",
          NextDialogue = 12025421,
          SpeakNpcId = 210115,
          Subtitle = "As I mentioned, it is simply how the identification works."
        },
        [12025421] = {
          ContentEN = "Many attempt to enter the black market under various pretexts. Without reliable means of telling insiders from outsiders, the overseer there would find the situation difficult to manage.",
          DialogueId = 12025421,
