        [12025501] = {
          ContentEN = "You must be the honoured guest Miss Zhiliu invited all the way from Hyperborea. I didn't expect you to be so young and so good-loo— ahem... I mean, so accomplished!",
          DialogueId = 12025501,
          GUID = "1E1AC5C2",
          NextDialogue = 12025502,
          SpeakNpcId = 210116,
          Subtitle = "You must be the honoured guest Miss Zhiliu invited all the way from Hyperborea. I didn't expect you to be so young and so good-loo— ahem... I mean, so accomplished!"
        },
        [12025502] = {
          ContentEN = "Proprietress Zhiliu is often occupied, with very little time to spare. If there's anything we may have overlooked, please let me know — I'll attend to it immediately.",
          DialogueId = 12025502,
          GUID = "1E1AC5EC",
