        [12025503] = {
          ContentEN = "What kind of guild is EverSpring?",
          DialogueId = 12025503,
          GUID = "1E1AC616",
          NextDialogue = 12025504,
          Subtitle = "What kind of guild is EverSpring?"
        },
        [12025504] = {
          ContentEN = "EverSpring isn't just the biggest guild around Mistwharf — it's the largest in all of Haojing.",
          DialogueId = 12025504,
          GUID = "1E1AC640",
          NextDialogue = 12025505,
          SpeakNpcId = 210116,
          Subtitle = "EverSpring isn't just the biggest guild around Mistwharf — it's the largest in all of Haojing."
        },
        [12025505] = {
          ContentEN = "The people of Huaxu rely on EverSpring for almost everything — from everyday necessities and rare imports to the transport and distribution of incense, and even the procedures for becoming a Starweaver. All of it is handled through us.",
          DialogueId = 12025505,
          GUID = "1E1AC66A",
          NextDialogue = 12025506,
          SpeakNpcId = 210116,
          Subtitle = "The people of Huaxu rely on EverSpring for almost everything — from everyday necessities and rare imports to the transport and distribution of incense, and even the procedures for becoming a Starweaver. All of it is handled through us."
        },
        [12025506] = {
          ContentEN = "As you can see, the stalls outside EverSpring offer goods from all across the land. You're welcome to browse freely. Every transaction here is supervised by the Ministry of Fortune and governed by the Nine Chapters of Dafeng.",
          DialogueId = 12025506,
          GUID = "1E1AC694",
          NextDialogue = 12025507,
          SpeakNpcId = 210116,
          Subtitle = "As you can see, the stalls outside EverSpring offer goods from all across the land. You're welcome to browse freely. Every transaction here is supervised by the Ministry of Fortune and governed by the Nine Chapters of Dafeng."
        },
        [12025507] = {
          ContentEN = "If you're interested in becoming a Starweaver, you may submit your application at the window over there. We also provide comprehensive support — from start-up loans to full, complimentary training in navigation across international trade routes.",
          DialogueId = 12025507,
          GUID = "1E1AC6BE",
          NextDialogue = 12025521,
          SpeakNpcId = 210116,
          Subtitle = "If you're interested in becoming a Starweaver, you may submit your application at the window over there. We also provide comprehensive support — from start-up loans to full, complimentary training in navigation across international trade routes."
        },
        [12025508] = {
          ContentEN = "How badly has the lockdown affected everyone here?",
          DialogueId = 12025508,
          GUID = "1E1AC6E8",
          NextDialogue = 12025509,
          Subtitle = "How badly has the lockdown affected everyone here?"
        },
        [12025509] = {
          ContentEN = "It has caused some inconvenience, that's true... but it was unavoidable. The restrictions mainly apply to the inland regions affected by Sable Bi'an.",
          DialogueId = 12025509,
          GUID = "1E1AC712",
          NextDialogue = 12025510,
          SpeakNpcId = 210116,
          Subtitle = "It has caused some inconvenience, that's true... but it was unavoidable. The restrictions mainly apply to the inland regions affected by Sable Bi'an."
        },
        [12025510] = {
          ContentEN = "After all, the safety of everyone is what EverSpring must prioritise above all else. I'm confident that once Miss Zhiliu finds a way to seal Zhuyin again, things will return to normal soon enough.",
          DialogueId = 12025510,
          GUID = "1E1AC73C",
          NextDialogue = 12025511,
          SpeakNpcId = 210116,
          Subtitle = "After all, the safety of everyone is what EverSpring must prioritise above all else. I'm confident that once Miss Zhiliu finds a way to seal Zhuyin again, things will return to normal soon enough."
        },
        [12025511] = {
          ContentEN = "And with your help, I believe that day will come all the sooner.",
          DialogueId = 12025511,
          GUID = "1E1AC766",
          NextDialogue = 12025521,
          SpeakNpcId = 210116,
          Subtitle = "And with your help, I believe that day will come all the sooner."
        },
        [12025512] = {
          ContentEN = "What's Proprietress Zhiliu like?",
          DialogueId = 12025512,
          GUID = "1E1AC790",
          NextDialogue = 12025513,
          Subtitle = "What's Proprietress Zhiliu like?"
        },
        [12025513] = {
          ContentEN = "She's incredible! No matter how difficult the situation, she handles it with effortless composure.",
          DialogueId = 12025513,
          GUID = "1E1AC7BA",
          NextDialogue = 12025514,
          SpeakNpcId = 210116,
          Subtitle = "She's incredible! No matter how difficult the situation, she handles it with effortless composure."
        },
        [12025514] = {
          ContentEN = "She serves as the High Chancellor of Loongyuan, assists the Ministry of Fortune, and still oversees EverSpring. It's difficult for people like us to imagine just how much she manages — anyone else would have been overwhelmed long ago.",
          DialogueId = 12025514,
          GUID = "1E1AC7E4",
          NextDialogue = 12025515,
          SpeakNpcId = 210116,
          Subtitle = "She serves as the High Chancellor of Loongyuan, assists the Ministry of Fortune, and still oversees EverSpring. It's difficult for people like us to imagine just how much she manages — anyone else would have been overwhelmed long ago."
        },
        [12025515] = {
          ContentEN = "But none of it ever seems to weigh on her. Whenever you see her, she is so calm and assured that her presence alone puts you at ease.",
          DialogueId = 12025515,
          GUID = "1E1AC80E",
          NextDialogue = 12025516,
          SpeakNpcId = 210116,
          Subtitle = "But none of it ever seems to weigh on her. Whenever you see her, she is so calm and assured that her presence alone puts you at ease."
        },
        [12025516] = {
          ContentEN = "Ah... listen to me, going on like this.",
          DialogueId = 12025516,
          GUID = "1E1AC838",
          NextDialogue = 12025517,
          SpeakNpcId = 210116,
          Subtitle = "Ah... listen to me, going on like this."
        },
        [12025517] = {
          ContentEN = "It's a little embarrassing to say out loud, but I truly admire Miss Zhiliu...",
          DialogueId = 12025517,
          GUID = "1E1AC862",
          NextDialogue = 12025518,
          SpeakNpcId = 210116,
          Subtitle = "It's a little embarrassing to say out loud, but I truly admire Miss Zhiliu..."
        },
        [12025518] = {
          ContentEN = "She seems to hold you in especially high regard. And her guest is EverSpring's guest. If you need anything, simply let me know — I'll do everything within my power to assist.",
          DialogueId = 12025518,
          GUID = "1E1AC88C",
          NextDialogue = 12025521,
          SpeakNpcId = 210116,
          Subtitle = "She seems to hold you in especially high regard. And her guest is EverSpring's guest. If you need anything, simply let me know — I'll do everything within my power to assist."
        },
        [12025519] = {
          ContentEN = "That's all for now.",
          DialogueId = 12025519,
          GUID = "1E1AC8B6",
          NextDialogue = 12025520,
          Subtitle = "That's all for now."
        },
