        },
        [12025603] = {
          ContentEN = "(Do Magistrates of Yingtian dream as well? What does he see in his dreams? You can't help wondering.)",
          DialogueId = 12025603,
          GUID = "1E1AD67E",
          NextDialogue = 12025604,
          Subtitle = "(Do Magistrates of Yingtian dream as well? What does he see in his dreams? You can't help wondering.)"
        },
        [12025604] = {
          ContentEN = "Whatcha doing, little minion? Admiring my masterpiece?",
          DialogueId = 12025604,
          GUID = "1E1AD6A8",
          NextDialogue = 12025605,
          SpeakNpcName = "UI_Npc_Name_Bai",
          Subtitle = "Whatcha doing, little minion? Admiring my masterpiece?"
        },
        [12025605] = {
          ContentEN = "If you like it, I can doodle something cute on your face too! Perks of being my minion!",
          DialogueId = 12025605,
          GUID = "1E1AD6D2",
          NextDialogue = 12025606,
          SpeakNpcName = "UI_Npc_Name_Bai",
          Subtitle = "If you like it, I can doodle something cute on your face too! Perks of being my minion!"
        },
        [12025606] = {
          ContentEN = "...Thanks, Snow. Come on, we should get moving.",
          DialogueId = 12025606,
          GUID = "1E1AD6FC",
          SpeakNpcId = 100001,
          Subtitle = "...Thanks, Snow. Come on, we should get moving."
        },
        [12025701] = {
          ContentEN = "Hey, you two — so you really are Proprietress Zhiliu's guests, huh.",
          DialogueId = 12025701,
          GUID = "1E1AE692",
          NextDialogue = 12025702,
          SpeakNpcId = 210118,
          Subtitle = "Hey, you two — so you really are Proprietress Zhiliu's guests, huh."
        },
        [12025702] = {
          ContentEN = "I'm on the lookout here every day. People try to sneak into the market all the time — I've heard every excuse under the sun. But I've never seen anyone as reckless as you two.",
          DialogueId = 12025702,
          GUID = "1E1AE6BC",
          NextDialogue = 12025703,
          SpeakNpcId = 210118,
          Subtitle = "I'm on the lookout here every day. People try to sneak into the market all the time — I've heard every excuse under the sun. But I've never seen anyone as reckless as you two."
        },
        [12025703] = {
          ContentEN = "Since you're Mr Qiu's honoured guests now... heh, could you put in a good word for me with the boss? Just tell him that his man Zhang San is ready to work himself to the bone to serve him!",
          DialogueId = 12025703,
          GUID = "1E1AE6E6",
          NextDialogue = 12025704,
          SpeakNpcId = 210118,
          Subtitle = "Since you're Mr Qiu's honoured guests now... heh, could you put in a good word for me with the boss? Just tell him that his man Zhang San is ready to work himself to the bone to serve him!"
        },
        [12025704] = {
          ContentEN = "I'm stuck keeping watch here every damn day — staring so long I'm starting to see the other side of Tidesong Cavern in my sleep. And hey, luck's supposed to turn, right? Shouldn't it be my turn to land a gig with some actual payoff?",
          DialogueId = 12025704,
          GUID = "1E1AE710",
          NextDialogue = 12025705,
          SpeakNpcId = 210118,
          Subtitle = "I'm stuck keeping watch here every damn day — staring so long I'm starting to see the other side of Tidesong Cavern in my sleep. And hey, luck's supposed to turn, right? Shouldn't it be my turn to land a gig with some actual payoff?"
        },
        [12025705] = {
          ContentEN = "You can't keep dumping all the dirty work on one poor man, right? I mean, tell me I'm not wrong here.",
          DialogueId = 12025705,
          GUID = "1E1AE73A",
          SpeakNpcId = 210118,
          Subtitle = "You can't keep dumping all the dirty work on one poor man, right? I mean, tell me I'm not wrong here."
        },
        [12025801] = {
          ContentEN = "Ah, you're here. Sit down, my young friend.",
          DialogueId = 12025801,
          GUID = "1E1AF6FA",
          NextDialogue = 12025802,
          SpeakNpcId = 210119,
          Subtitle = "Ah, you're here. Sit down, my young friend."
        },
        [12025802] = {
          ContentEN = "I've just brewed a cup of tangerine peel tea, aged for centuries. Let it soothe your throat, then indulge me with tales of your travels.",
          DialogueId = 12025802,
          GUID = "1E1AF724",
          NextDialogue = 12025828,
          SpeakNpcId = 210119,
          Subtitle = "I've just brewed a cup of tangerine peel tea, aged for centuries. Let it soothe your throat, then indulge me with tales of your travels."
        },
        [12025803] = {
          ContentEN = "Why surround yourself with so many antiques?",
          DialogueId = 12025803,
          GUID = "1E1AF74E",
          NextDialogue = 12025804,
          Subtitle = "Why surround yourself with so many antiques?"
        },
        [12025804] = {
          ContentEN = "Desire shapes the very core of life. To yearn is to seek, and to seek is to claim — a drive as old as existence itself.",
          DialogueId = 12025804,
          GUID = "1E1AF778",
          NextDialogue = 12025805,
          SpeakNpcId = 210119,
          Subtitle = "Desire shapes the very core of life. To yearn is to seek, and to seek is to claim — a drive as old as existence itself."
        },
        [12025805] = {
          ContentEN = "And these so-called \"antiques\" are far from mere lifeless trinkets. Each one has breathed another's story, a thread woven into countless ages of history.",
          DialogueId = 12025805,
          GUID = "1E1AF7A2",
          NextDialogue = 12025806,
          SpeakNpcId = 210119,
          Subtitle = "And these so-called \"antiques\" are far from mere lifeless trinkets. Each one has breathed another's story, a thread woven into countless ages of history."
        },
        [12025806] = {
          ContentEN = "That sounds awfully abstract and cryptic.",
          DialogueId = 12025806,
          GUID = "1E1AF7CC",
          NextDialogue = 12025807,
          SpeakNpcId = 100001,
          Subtitle = "That sounds awfully abstract and cryptic."
        },
        [12025807] = {
          ContentEN = "Take this dagger, for instance. It once repelled invaders, cut down monarchs, and ultimately perished by its master's side. And this cracked teacup? It welcomed weary travellers and saw off loved ones, only to be toppled in a wager of wit and verse.",
          DialogueId = 12025807,
          GUID = "1E1AF7F6",
          NextDialogue = 12025808,
          SpeakNpcId = 210119,
          Subtitle = "Take this dagger, for instance. It once repelled invaders, cut down monarchs, and ultimately perished by its master's side. And this cracked teacup? It welcomed weary travellers and saw off loved ones, only to be toppled in a wager of wit and verse."
        },
        [12025808] = {
          ContentEN = "When I hold these relics, it feels as though we're no longer alone in this room. Figures from ages past seem to gather with us — seven or eight scenes, each carrying centuries of memories. That, my young friend, is why I gather them... and why I shall never stop.",
          DialogueId = 12025808,
          GUID = "1E1AF820",
          NextDialogue = 12025828,
          SpeakNpcId = 210119,
          Subtitle = "When I hold these relics, it feels as though we're no longer alone in this room. Figures from ages past seem to gather with us — seven or eight scenes, each carrying centuries of memories. That, my young friend, is why I gather them... and why I shall never stop."
        },
        [12025809] = {
          ContentEN = "I've heard you're quite insatiable.",
          DialogueId = 12025809,
          GUID = "1E1AF84A",
          NextDialogue = 12025810,
          Subtitle = "I've heard you're quite insatiable."
        },
        [12025810] = {
          ContentEN = "Insatiable? I must say, I find that rather flattering.",
          DialogueId = 12025810,
          GUID = "1E1AF874",
          NextDialogue = 12025811,
          SpeakNpcId = 210119,
          Subtitle = "Insatiable? I must say, I find that rather flattering."
        },
        [12025811] = {
          ContentEN = "Were I not \"insatiable,\" I'd be forsaking all the treasures this world holds. Countless relics and untold secrets would remain entombed in time, never to grace the light of day again.",
          DialogueId = 12025811,
          GUID = "1E1AF89E",
          NextDialogue = 12025812,
          SpeakNpcId = 210119,
          Subtitle = "Were I not \"insatiable,\" I'd be forsaking all the treasures this world holds. Countless relics and untold secrets would remain entombed in time, never to grace the light of day again."
        },
        [12025812] = {
          ContentEN = "And if one suppresses desire, doesn't that defy the most fundamental truth of life? Desire propels us forward; it spurs every inch of progress.",
          DialogueId = 12025812,
          GUID = "1E1AF8C8",
          NextDialogue = 12025813,
          SpeakNpcId = 210119,
          Subtitle = "And if one suppresses desire, doesn't that defy the most fundamental truth of life? Desire propels us forward; it spurs every inch of progress."
        },
        [12025813] = {
          ContentEN = "Not everyone sees it that way.",
          DialogueId = 12025813,
          GUID = "1E1AF8F2",
          NextDialogue = 12025814,
          SpeakNpcId = 100001,
          Subtitle = "Not everyone sees it that way."
        },
        [12025814] = {
          ContentEN = "It matters little. Call it brazen sophistry if you wish — I prefer to call it embracing one's nature and living true to oneself.",
          DialogueId = 12025814,
          GUID = "1E1AF91C",
          NextDialogue = 12025815,
          SpeakNpcId = 210119,
          Subtitle = "It matters little. Call it brazen sophistry if you wish — I prefer to call it embracing one's nature and living true to oneself."
        },
        [12025815] = {
          ContentEN = "Many wish to become like me, yet lack the courage to take the first step, let alone follow through. In their fear, they fail even to become their truest selves, hiding behind the safety of rules and morals while hurling insults my way from the shadows. Pitiful, isn't it?",
          DialogueId = 12025815,
          GUID = "1E1AF946",
          NextDialogue = 12025802,
          SpeakNpcId = 210119,
          Subtitle = "Many wish to become like me, yet lack the courage to take the first step, let alone follow through. In their fear, they fail even to become their truest selves, hiding behind the safety of rules and morals while hurling insults my way from the shadows. Pitiful, isn't it?"
        },
        [12025816] = {
          ContentEN = "Who is Master Gongshang?",
          DialogueId = 12025816,
          GUID = "1E1AF970",
          NextDialogue = 12025817,
          Subtitle = "Who is Master Gongshang?"
        },
        [12025817] = {
          ContentEN = "A most singular craftsman of the Jishu Sect — one whom I now patronise.",
          DialogueId = 12025817,
          GUID = "1E1AF99A",
          NextDialogue = 12025818,
          SpeakNpcId = 210119,
          Subtitle = "A most singular craftsman of the Jishu Sect — one whom I now patronise."
        },
        [12025818] = {
          ContentEN = "There's a saying: a man without his peculiarities is hardly worth keeping company with. And among all the people I've met, his obsessions run the deepest, and his manner is the most unconventional.",
          DialogueId = 12025818,
          GUID = "1E1AF9C4",
          NextDialogue = 12025819,
          SpeakNpcId = 210119,
          Subtitle = "There's a saying: a man without his peculiarities is hardly worth keeping company with. And among all the people I've met, his obsessions run the deepest, and his manner is the most unconventional."
        },
        [12025819] = {
          ContentEN = "Strange temperaments don't trouble me — mediocrity does. In craftsmanship, there are few today who can match his skill. Had he not taken issue with the Ministry of Works' methods, he wouldn't have left their ranks, nor would he have needed my support.",
          DialogueId = 12025819,
          GUID = "1E1AF9EE",
          NextDialogue = 12025820,
          SpeakNpcId = 210119,
          Subtitle = "Strange temperaments don't trouble me — mediocrity does. In craftsmanship, there are few today who can match his skill. Had he not taken issue with the Ministry of Works' methods, he wouldn't have left their ranks, nor would he have needed my support."
        },
        [12025820] = {
          ContentEN = "A character like that... he could hurl insults right to my face, and I'd simply laugh them off.",
          DialogueId = 12025820,
          GUID = "1E1AFA18",
          NextDialogue = 12025828,
          SpeakNpcId = 210119,
          Subtitle = "A character like that... he could hurl insults right to my face, and I'd simply laugh them off."
        },
        [12025821] = {
          ContentEN = "Are you and Proprietress Zhiliu partners?",
          DialogueId = 12025821,
          GUID = "1E1AFA42",
          NextDialogue = 12025822,
          Subtitle = "Are you and Proprietress Zhiliu partners?"
        },
        [12025822] = {
          ContentEN = "If you wish to call a relationship built on mutual interest a partnership, then yes.",
          DialogueId = 12025822,
          GUID = "1E1AFA6C",
          NextDialogue = 12025823,
          SpeakNpcId = 210119,
          Subtitle = "If you wish to call a relationship built on mutual interest a partnership, then yes."
        },
        [12025823] = {
          ContentEN = "And if one day she couldn't give you what you wanted anymore... would you betray her?",
          DialogueId = 12025823,
          GUID = "1E1AFA96",
          NextDialogue = 12025824,
          SpeakNpcId = 100001,
          Subtitle = "And if one day she couldn't give you what you wanted anymore... would you betray her?"
        },
        [12025824] = {
          ContentEN = "Hah. My young friend, that is a rather naive question. There are no eternal friends, nor eternal enemies. People's ties shift constantly — so what does \"betrayal\" really amount to?",
          DialogueId = 12025824,
          GUID = "1E1AFAC0",
          NextDialogue = 12025825,
          SpeakNpcId = 210119,
          Subtitle = "Hah. My young friend, that is a rather naive question. There are no eternal friends, nor eternal enemies. People's ties shift constantly — so what does \"betrayal\" really amount to?"
        },
        [12025825] = {
          ContentEN = "Still, this is not something you need worry about. Proprietress Zhiliu is a shrewd woman. She binds people to her through shared interests — firmly enough that the day you speak of is unlikely ever to come.",
          DialogueId = 12025825,
          GUID = "1E1AFAEA",
          NextDialogue = 12025828,
          SpeakNpcId = 210119,
          Subtitle = "Still, this is not something you need worry about. Proprietress Zhiliu is a shrewd woman. She binds people to her through shared interests — firmly enough that the day you speak of is unlikely ever to come."
        },
        [12025826] = {
          ContentEN = "I should get going.",
          DialogueId = 12025826,
          GUID = "1E1AFB14",
          NextDialogue = 12025827,
          Subtitle = "I should get going."
        },
        [12025827] = {
          ContentEN = "Go on, then. I won't see you out.",
          DialogueId = 12025827,
          GUID = "1E1AFB3E",
          SpeakNpcId = 210119,
          Subtitle = "Go on, then. I won't see you out."
        },
