        [12025901] = {
          ContentEN = "Th—Thank you... for saving my life...",
          DialogueId = 12025901,
          GUID = "1E1B0762",
          NextDialogue = 12025902,
          SpeakNpcId = 210120,
          Subtitle = "Th—Thank you... for saving my life..."
        },
        [12025902] = {
          ContentEN = "(The young woman before you is pale as a ghost, sweat beading on her brow. Even so, she forces herself to thank you. After the Bi'an's punishment, she clearly needs rest.)",
          DialogueId = 12025902,
          GUID = "1E1B078C",
          NextDialogue = 12025903,
          Subtitle = "(The young woman before you is pale as a ghost, sweat beading on her brow. Even so, she forces herself to thank you. After the Bi'an's punishment, she clearly needs rest.)"
        },
        [12025903] = {
          ContentEN = "Don't worry, {性别：sir|ma'am} — we're all friends here! I'll take good care of her, not a single hair out of place! I swear it!",
          DialogueId = 12025903,
          GUID = "1E1B07B6",
          NextDialogue = 12025904,
          SpeakNpcName = "UI_Npc_Name_Badshangren",
          Subtitle = "Don't worry, {性别：sir|ma'am} — we're all friends here! I'll take good care of her, not a single hair out of place! I swear it!"
        },
        [12025904] = {
          ContentEN = "Please... {性别：sir|ma'am}, I'm begging you here — please go see Mr Qiu first! Don't keep him waiting. With you standing here, the girl just can't calm down and rest, can she?",
          DialogueId = 12025904,
          GUID = "1E1B07E0",
          SpeakNpcName = "UI_Npc_Name_Badshangren",
          Subtitle = "Please... {性别：sir|ma'am}, I'm begging you here — please go see Mr Qiu first! Don't keep him waiting. With you standing here, the girl just can't calm down and rest, can she?"
        },
        [12026001] = {
          ContentEN = "So, my honorary learner — what is it you want to ask?",
          DialogueId = 12026001,
          GUID = "1E1B17CA",
          NextDialogue = 12026025,
          SpeakNpcId = 210121,
          Subtitle = "So, my honorary learner — what is it you want to ask?"
        },
        [12026002] = {
          ContentEN = "Could you explain what Gritblight is again?",
          DialogueId = 12026002,
          GUID = "1E1B17F4",
          NextDialogue = 12026003,
          Subtitle = "Could you explain what Gritblight is again?"
        },
        [12026003] = {
          ContentEN = "Ah... back in my day, a good memory was the most basic requirement for joining the Jishu Sect. The slow-witted were weeded out while they were still toddlers.",
          DialogueId = 12026003,
          GUID = "1E1B181E",
          NextDialogue = 12026004,
          SpeakNpcId = 210121,
          Subtitle = "Ah... back in my day, a good memory was the most basic requirement for joining the Jishu Sect. The slow-witted were weeded out while they were still toddlers."
        },
        [12026004] = {
          ContentEN = "Ah, never mind. Talent can't be forced. Since you're willing to learn, that's good enough. I'll explain it once more.",
          DialogueId = 12026004,
          GUID = "1E1B1848",
          NextDialogue = 12026005,
          SpeakNpcId = 210121,
          Subtitle = "Ah, never mind. Talent can't be forced. Since you're willing to learn, that's good enough. I'll explain it once more."
        },
        [12026005] = {
          ContentEN = "The air is suffused with something called Taixu, an unseen, intangible substance. And naturally, you'll ask: \"If we can't see it or touch it, how do we know it exists?\"",
          DialogueId = 12026005,
          GUID = "1E1B1872",
          NextDialogue = 12026006,
          SpeakNpcId = 210121,
          Subtitle = "The air is suffused with something called Taixu, an unseen, intangible substance. And naturally, you'll ask: \"If we can't see it or touch it, how do we know it exists?\""
        },
        [12026006] = {
          ContentEN = "Those of us who study it have ways to observe it indirectly. And Gritblight is the clearest proof that Taixu is real.",
          DialogueId = 12026006,
          GUID = "1E1B189C",
          NextDialogue = 12026007,
          SpeakNpcId = 210121,
          Subtitle = "Those of us who study it have ways to observe it indirectly. And Gritblight is the clearest proof that Taixu is real."
        },
        [12026007] = {
          ContentEN = "When the Taixu in the air is disturbed by the Scourge of Zhuyin, its nature changes. It hardens into a fine powder that settles over everything — and that powder, harmful to ordinary life, is what we call Gritblight. Does it make sense to you now?",
          DialogueId = 12026007,
          GUID = "1E1B18C6",
          NextDialogue = 12026025,
          SpeakNpcId = 210121,
          Subtitle = "When the Taixu in the air is disturbed by the Scourge of Zhuyin, its nature changes. It hardens into a fine powder that settles over everything — and that powder, harmful to ordinary life, is what we call Gritblight. Does it make sense to you now?"
        },
        [12026008] = {
          ContentEN = "Could you go over how to use the Mechanical Nexus again?",
          DialogueId = 12026008,
          GUID = "1E1B18F0",
          NextDialogue = 12026009,
          Subtitle = "Could you go over how to use the Mechanical Nexus again?"
        },
        [12026009] = {
          ContentEN = "Hm? I hand-wrote hundreds of pages of instructions and left them with the device at Qin Qiu's place. He didn't give them to you?",
          DialogueId = 12026009,
          GUID = "1E1B191A",
          NextDialogue = 12026010,
          SpeakNpcId = 210121,
          Subtitle = "Hm? I hand-wrote hundreds of pages of instructions and left them with the device at Qin Qiu's place. He didn't give them to you?"
        },
        [12026010] = {
          ContentEN = "No. He just sent me to ask you.",
          DialogueId = 12026010,
          GUID = "1E1B1944",
          NextDialogue = 12026011,
          SpeakNpcId = 100001,
          Subtitle = "No. He just sent me to ask you."
        },
        [12026011] = {
          ContentEN = "...That old bastard. I knew it. He must've figured you wouldn't bother reading a manual that long, so he simply kept it from you. As if the Jishu Sect's honorary learner were so impatient and careless.",
          DialogueId = 12026011,
          GUID = "1E1B196E",
          NextDialogue = 12026012,
          SpeakNpcId = 210121,
          Subtitle = "...That old bastard. I knew it. He must've figured you wouldn't bother reading a manual that long, so he simply kept it from you. As if the Jishu Sect's honorary learner were so impatient and careless."
        },
        [12026012] = {
          ContentEN = "Forget it. I'll make it simple for you. It's easy — press this button, point it at the Gritblight, and it'll suck it in. That's all.",
          DialogueId = 12026012,
          GUID = "1E1B1998",
          NextDialogue = 12026013,
          SpeakNpcId = 210121,
          Subtitle = "Forget it. I'll make it simple for you. It's easy — press this button, point it at the Gritblight, and it'll suck it in. That's all."
        },
        [12026013] = {
          ContentEN = "That's it?",
          DialogueId = 12026013,
          GUID = "1E1B19C2",
          NextDialogue = 12026014,
          SpeakNpcId = 100001,
          Subtitle = "That's it?"
        },
        [12026014] = {
          ContentEN = "That's it. Or did you expect me to start explaining the theory behind it as well?",
          DialogueId = 12026014,
          GUID = "1E1B19EC",
          NextDialogue = 12026015,
          SpeakNpcId = 210121,
          Subtitle = "That's it. Or did you expect me to start explaining the theory behind it as well?"
        },
        [12026015] = {
          ContentEN = "No, no — this is perfect. Thank you, shifu!",
          DialogueId = 12026015,
          GUID = "1E1B1A16",
          NextDialogue = 12026025,
          Subtitle = "No, no — this is perfect. Thank you, shifu!"
        },
        [12026016] = {
          ContentEN = "Why has the Jishu Sect declined?",
          DialogueId = 12026016,
          GUID = "1E1B1A40",
          NextDialogue = 12026017,
          Subtitle = "Why has the Jishu Sect declined?"
        },
        [12026017] = {
          ContentEN = "We in the Jishu Sect are taught to look at things from more than one angle. So — what exactly do you mean by \"decline\"?",
          DialogueId = 12026017,
          GUID = "1E1B1A6A",
          NextDialogue = 12026018,
          SpeakNpcId = 210121,
          Subtitle = "We in the Jishu Sect are taught to look at things from more than one angle. So — what exactly do you mean by \"decline\"?"
        },
        [12026018] = {
          ContentEN = "Our creations are found everywhere in Huaxu. At every dock you'll see wooden steeds hauling cargo. The Ministry of Works is still one of the three great ministries of Huaxu. And you call that \"decline\"?",
          DialogueId = 12026018,
          GUID = "1E1B1A94",
          NextDialogue = 12026019,
          SpeakNpcId = 210121,
          Subtitle = "Our creations are found everywhere in Huaxu. At every dock you'll see wooden steeds hauling cargo. The Ministry of Works is still one of the three great ministries of Huaxu. And you call that \"decline\"?"
        },
        [12026019] = {
          ContentEN = "Um... but didn't you tell me the Jishu Sect had fallen on hard times and couldn't attract any new apprentices?",
          DialogueId = 12026019,
          GUID = "1E1B1ABE",
          NextDialogue = 12026020,
          SpeakNpcId = 100001,
          Subtitle = "Um... but didn't you tell me the Jishu Sect had fallen on hard times and couldn't attract any new apprentices?"
        },
        [12026020] = {
          ContentEN = "Sharp kid — from that angle, you're not wrong.",
          DialogueId = 12026020,
          GUID = "1E1B1AE8",
          NextDialogue = 12026021,
          SpeakNpcId = 210121,
          Subtitle = "Sharp kid — from that angle, you're not wrong."
        },
        [12026021] = {
          ContentEN = "People have lost their desire to learn. No one wants to join the Jishu Sect anymore, and those hidebound old men in the Ministry of Works shut themselves away, tinkering all day but no longer seeking the highest principles — that, now, is decline.",
          DialogueId = 12026021,
          GUID = "1E1B1B12",
          NextDialogue = 12026022,
          SpeakNpcId = 210121,
          Subtitle = "People have lost their desire to learn. No one wants to join the Jishu Sect anymore, and those hidebound old men in the Ministry of Works shut themselves away, tinkering all day but no longer seeking the highest principles — that, now, is decline."
        },
        [12026022] = {
          ContentEN = "Now then, to answer your question: why has the Jishu Sect declined? Because of the Xuanheng Sect. They fear the power that comes with knowledge may slip beyond their control, so they suppressed the Jishu Sect until it weakened. It's as simple as that.",
          DialogueId = 12026022,
          GUID = "1E1B1B3C",
          NextDialogue = 12026025,
          SpeakNpcId = 210121,
          Subtitle = "Now then, to answer your question: why has the Jishu Sect declined? Because of the Xuanheng Sect. They fear the power that comes with knowledge may slip beyond their control, so they suppressed the Jishu Sect until it weakened. It's as simple as that."
        },
        [12026023] = {
          ContentEN = "I've still got loads of questions... let me think.",
          DialogueId = 12026023,
          GUID = "1E1B1B66",
          NextDialogue = 12026024,
          Subtitle = "I've still got loads of questions... let me think."
        },
        [12026024] = {
          ContentEN = "You keep digging until you truly grasp something — that's what I like to see. Now, I've work to do. Make sure you keep up with your daily practice.",
          DialogueId = 12026024,
          GUID = "1E1B1B90",
          SpeakNpcId = 210121,
          Subtitle = "You keep digging until you truly grasp something — that's what I like to see. Now, I've work to do. Make sure you keep up with your daily practice."
        },
        [12026025] = {
          DialogueId = 12026025,
