        [12026101] = {
          ContentEN = "Look who it is — {nickname}, the hero who helped lead EverSpring through the crisis!",
          DialogueId = 12026101,
          GUID = "1E1B2832",
          NextDialogue = 12026102,
          SpeakNpcId = 210122,
          Subtitle = "Look who it is — , the hero who helped lead EverSpring through the crisis!"
        },
        [12026102] = {
          ContentEN = "You flatter me. I only played a small part — most of the credit goes to Proprietress Zhiliu and everyone else.",
          DialogueId = 12026102,
          GUID = "1E1B285C",
          NextDialogue = 12026103,
          SpeakNpcId = 100001,
          Subtitle = "You flatter me. I only played a small part — most of the credit goes to Proprietress Zhiliu and everyone else."
        },
        [12026103] = {
          ContentEN = "And you? After all that's happened, how have you been?",
          DialogueId = 12026103,
          GUID = "1E1B2886",
          NextDialogue = 12026104,
          SpeakNpcId = 100001,
          Subtitle = "And you? After all that's happened, how have you been?"
        },
        [12026104] = {
          ContentEN = "It may sound a little silly, but instead of feeling shaken afterward, I actually felt... exhilarated. There was a quiet thrill in being able to protect our home, as though a steady strength had taken root within me.",
          DialogueId = 12026104,
          GUID = "1E1B28B0",
          NextDialogue = 12026105,
          SpeakNpcId = 210122,
          Subtitle = "It may sound a little silly, but instead of feeling shaken afterward, I actually felt... exhilarated. There was a quiet thrill in being able to protect our home, as though a steady strength had taken root within me."
        },
        [12026105] = {
          ContentEN = "I even found myself thinking about learning some basic self-defense, so that when I travel to more perilous regions for trade, I won't have to rely entirely on my escorts.",
          DialogueId = 12026105,
          GUID = "1E1B28DA",
          NextDialogue = 12026106,
          SpeakNpcId = 210122,
          Subtitle = "I even found myself thinking about learning some basic self-defense, so that when I travel to more perilous regions for trade, I won't have to rely entirely on my escorts."
        },
        [12026106] = {
          ContentEN = "Although... thoughts like these do stray from the teachings of the Nine Chapters of Dafeng...",
          DialogueId = 12026106,
          GUID = "1E1B2904",
          SpeakNpcId = 210122,
          Subtitle = "Although... thoughts like these do stray from the teachings of the Nine Chapters of Dafeng..."
        },
        [12026201] = {
          ContentEN = "What is it, {nickname}? Was there something you wished to discuss?",
          DialogueId = 12026201,
          GUID = "1E1B389A",
          NextDialogue = 12026202,
          SpeakNpcId = 210123,
          Subtitle = "What is it, ? Was there something you wished to discuss?"
        },
        [12026202] = {
          ContentEN = "(Her composure seems unchanged, yet you sense a faint weariness beneath it — something easy to overlook. Perhaps it is only your imagination.)",
          DialogueId = 12026202,
          GUID = "1E1B38C4",
          NextDialogue = 12026213,
          Subtitle = "(Her composure seems unchanged, yet you sense a faint weariness beneath it — something easy to overlook. Perhaps it is only your imagination.)"
        },
        [12026203] = {
          ContentEN = "Proprietress Zhiliu, what will you do next?",
          DialogueId = 12026203,
          GUID = "1E1B38EE",
          NextDialogue = 12026204,
          Subtitle = "Proprietress Zhiliu, what will you do next?"
        },
        [12026204] = {
          ContentEN = "With the Zhuyin scales you recovered, the preparations for the sealing are complete. I must now turn to the matters that follow, and may not be able to receive you for a while. Allow me to offer my apologies in advance.",
          DialogueId = 12026204,
          GUID = "1E1B3918",
          NextDialogue = 12026205,
          SpeakNpcId = 210123,
          Subtitle = "With the Zhuyin scales you recovered, the preparations for the sealing are complete. I must now turn to the matters that follow, and may not be able to receive you for a while. Allow me to offer my apologies in advance."
        },
        [12026205] = {
          ContentEN = "Are you sure you don't need my help?",
          DialogueId = 12026205,
          GUID = "1E1B3942",
          NextDialogue = 12026206,
          SpeakNpcId = 100001,
          Subtitle = "Are you sure you don't need my help?"
        },
        [12026206] = {
          ContentEN = "Heh... your offer is appreciated. But I cannot allow you to shoulder everything on your own. If a matter arises that truly requires your strength, I will seek your aid again.",
          DialogueId = 12026206,
          GUID = "1E1B396C",
          NextDialogue = 12026213,
          SpeakNpcId = 210123,
          Subtitle = "Heh... your offer is appreciated. But I cannot allow you to shoulder everything on your own. If a matter arises that truly requires your strength, I will seek your aid again."
        },
        [12026207] = {
          ContentEN = "It was really dangerous back there.",
          DialogueId = 12026207,
          GUID = "1E1B3996",
          NextDialogue = 12026208,
          Subtitle = "It was really dangerous back there."
        },
        [12026208] = {
          ContentEN = "Indeed. You played a part in resolving it as well. My thanks to you, {nickname}.",
          DialogueId = 12026208,
          GUID = "1E1B39C0",
          NextDialogue = 12026209,
          SpeakNpcId = 210123,
          Subtitle = "Indeed. You played a part in resolving it as well. My thanks to you, ."
        },
        [12026209] = {
          ContentEN = "I didn't do much. You were the one who brought everyone together — you handled everything so quickly and calmly.",
          DialogueId = 12026209,
          GUID = "1E1B39EA",
          NextDialogue = 12026210,
          SpeakNpcId = 100001,
          Subtitle = "I didn't do much. You were the one who brought everyone together — you handled everything so quickly and calmly."
        },
        [12026210] = {
          ContentEN = "Heh... if one hesitates at every turn, forever weighing each step, how could one hope to shoulder the expectations and responsibilities placed upon them?",
          DialogueId = 12026210,
          GUID = "1E1B3A14",
          NextDialogue = 12026213,
          SpeakNpcId = 210123,
          Subtitle = "Heh... if one hesitates at every turn, forever weighing each step, how could one hope to shoulder the expectations and responsibilities placed upon them?"
        },
        [12026211] = {
          Content = "……",
          DialogueId = 12026211,
          GUID = "1E1B3A3E",
          NextDialogue = 12026212
        },
        [12026212] = {
          ContentEN = "I must see to the remaining preparations for the sealing. You have some time to yourself now — feel free to look around as you wish. Should you incur any expenses, have them charged to my account; think nothing of the cost.",
          DialogueId = 12026212,
