        [12026302] = {
          ContentEN = "Are you feeling any better now?",
          DialogueId = 12026302,
          GUID = "1E1B492C",
          NextDialogue = 12026303,
          SpeakNpcId = 100001,
          Subtitle = "Are you feeling any better now?"
        },
        [12026303] = {
          ContentEN = "Thanks to the herbs you and Lady Fushu brought back for me, my injuries have started to settle. In another day or two, I might even be able to get out of bed and walk.",
          DialogueId = 12026303,
          GUID = "1E1B4956",
          NextDialogue = 12026304,
          SpeakNpcId = 210124,
          Subtitle = "Thanks to the herbs you and Lady Fushu brought back for me, my injuries have started to settle. In another day or two, I might even be able to get out of bed and walk."
        },
        [12026304] = {
          ContentEN = "After everything that's happened, you've shown me more kindness than I can even put into words... I... I really don't know how to repay you. If there's ever anything I can do for you, just say the word. I'll do my best.",
          DialogueId = 12026304,
          GUID = "1E1B4980",
          SpeakNpcId = 210124,
          Subtitle = "After everything that's happened, you've shown me more kindness than I can even put into words... I... I really don't know how to repay you. If there's ever anything I can do for you, just say the word. I'll do my best."
        },
        [12026401] = {
          ContentEN = "If you come across any Wishen stranded near the waterfall, please lend them your aid. My thanks to both of you.",
          DialogueId = 12026401,
          GUID = "1E1B596A",
          SpeakNpcId = 210125,
          Subtitle = "If you come across any Wishen stranded near the waterfall, please lend them your aid. My thanks to both of you."
        },
        [12026501] = {
          ContentEN = "My heartfelt thanks. With all the missing Wishen safely returned, we are deeply grateful for your help.",
          DialogueId = 12026501,
          GUID = "1E1B69D2",
          SpeakNpcId = 210126,
          Subtitle = "My heartfelt thanks. With all the missing Wishen safely returned, we are deeply grateful for your help."
        },
        [12026601] = {
          ContentEN = "{nickname}, you've come.",
          DialogueId = 12026601,
          GUID = "1E1B7A3A",
          NextDialogue = 12026602,
          SpeakNpcId = 210127,
          Subtitle = ", you've come."
        },
        [12026602] = {
          ContentEN = "I am accustomed to quietude, and here in the Hall of Ephemerality I have little with which to receive you — only these shelves of medical texts and a pot of tea. I hope it does not strike you as too dull.",
          DialogueId = 12026602,
          GUID = "1E1B7A64",
          NextDialogue = 12026603,
          SpeakNpcId = 210127,
          Subtitle = "I am accustomed to quietude, and here in the Hall of Ephemerality I have little with which to receive you — only these shelves of medical texts and a pot of tea. I hope it does not strike you as too dull."
        },
        [12026603] = {
          ContentEN = "You may move about as you please. Please make yourself at ease here.",
          DialogueId = 12026603,
          GUID = "1E1B7A8E",
          NextDialogue = 12026640,
          SpeakNpcId = 210127,
          Subtitle = "You may move about as you please. Please make yourself at ease here."
        },
        [12026604] = {
          ContentEN = "Apart from healing people, what do you do in your spare time?",
          DialogueId = 12026604,
          GUID = "1E1B7AB8",
          NextDialogue = 12026605,
          Subtitle = "Apart from healing people, what do you do in your spare time?"
        },
        [12026605] = {
          ContentEN = "Most of my days are taken up with tending to patients. Should I chance upon a rare moment of leisure... I would likely spend it reading the medical texts my elder sister left behind.",
          DialogueId = 12026605,
          GUID = "1E1B7AE2",
          NextDialogue = 12026606,
          SpeakNpcId = 210127,
          Subtitle = "Most of my days are taken up with tending to patients. Should I chance upon a rare moment of leisure... I would likely spend it reading the medical texts my elder sister left behind."
        },
        [12026606] = {
          ContentEN = "Wouldn't that be basically the same as working?",
          DialogueId = 12026606,
          GUID = "1E1B7B0C",
          NextDialogue = 12026607,
          SpeakNpcId = 100001,
          Subtitle = "Wouldn't that be basically the same as working?"
        },
        [12026607] = {
          ContentEN = "When a patient stands before me, my mind is seldom still, and I cannot quite settle myself to study the subtleties of medicine. Yet when I turn to some page of an old text and take my time with its more difficult passages, there often comes a moment of clarity — a quiet joy in its own right.",
          DialogueId = 12026607,
          GUID = "1E1B7B36",
          NextDialogue = 12026608,
          SpeakNpcId = 210127,
          Subtitle = "When a patient stands before me, my mind is seldom still, and I cannot quite settle myself to study the subtleties of medicine. Yet when I turn to some page of an old text and take my time with its more difficult passages, there often comes a moment of clarity — a quiet joy in its own right."
        },
        [12026608] = {
          ContentEN = "So you don't have any hobbies besides that?",
          DialogueId = 12026608,
          GUID = "1E1B7B60",
          NextDialogue = 12026609,
          SpeakNpcId = 100001,
          Subtitle = "So you don't have any hobbies besides that?"
        },
        [12026609] = {
          ContentEN = "Let me think... Perhaps playing the zheng, or whiling away a little time with Yunchi — such were the quiet pleasures of my youth.",
          DialogueId = 12026609,
          GUID = "1E1B7B8A",
          NextDialogue = 12026610,
          SpeakNpcId = 210127,
          Subtitle = "Let me think... Perhaps playing the zheng, or whiling away a little time with Yunchi — such were the quiet pleasures of my youth."
        },
        [12026610] = {
          ContentEN = "Then can you play a piece for me next time?",
          DialogueId = 12026610,
          GUID = "1E1B7BB4",
          NextDialogue = 12026611,
          SpeakNpcId = 100001,
          Subtitle = "Then can you play a piece for me next time?"
        },
        [12026611] = {
          ContentEN = "...Indeed. How could I have forgotten? The greatest pleasure, I find, lies in the company of friends — whether we share music or speak at ease, there is a quiet delight in it.",
          DialogueId = 12026611,
          GUID = "1E1B7BDE",
          NextDialogue = 12026612,
          SpeakNpcId = 210127,
          Subtitle = "...Indeed. How could I have forgotten? The greatest pleasure, I find, lies in the company of friends — whether we share music or speak at ease, there is a quiet delight in it."
        },
        [12026612] = {
          ContentEN = "{nickname}, you are welcome to visit the Hall of Ephemerality whenever you have a moment to spare. Your company would be most welcome.",
          DialogueId = 12026612,
          GUID = "1E1B7C08",
          NextDialogue = 12026613,
          SpeakNpcId = 210127,
          Subtitle = ", you are welcome to visit the Hall of Ephemerality whenever you have a moment to spare. Your company would be most welcome."
        },
        [12026613] = {
          ContentEN = "Then it's settled!",
          DialogueId = 12026613,
          GUID = "1E1B7C32",
          NextDialogue = 12026640,
          SpeakNpcId = 100001,
          Subtitle = "Then it's settled!"
        },
        [12026614] = {
          ContentEN = "I've been feeling off lately.",
          DialogueId = 12026614,
          GUID = "1E1B7C5C",
          NextDialogue = 12026615,
          Subtitle = "I've been feeling off lately."
        },
        [12026615] = {
          ContentEN = "What troubles you? Do you feel pain anywhere — or did you perhaps injure yourself while making your way through Mistwharf? Let me see your hand. I shall examine it carefully.",
          DialogueId = 12026615,
          GUID = "1E1B7C86",
          NextDialogue = 12026616,
          SpeakNpcId = 210127,
          Subtitle = "What troubles you? Do you feel pain anywhere — or did you perhaps injure yourself while making your way through Mistwharf? Let me see your hand. I shall examine it carefully."
        },
        [12026616] = {
          ContentEN = "Haha... Fushu, you're so tense — you really do worry about me, don't you?",
          DialogueId = 12026616,
          GUID = "1E1B7CB0",
          NextDialogue = 12026617,
          SpeakNpcId = 100001,
          Subtitle = "Haha... Fushu, you're so tense — you really do worry about me, don't you?"
        },
        [12026617] = {
          ContentEN = "It's nothing serious. I just wake up with a stiff back and aching shoulders, that's all.",
          DialogueId = 12026617,
          GUID = "1E1B7CDA",
          NextDialogue = 12026618,
          SpeakNpcId = 100001,
          Subtitle = "It's nothing serious. I just wake up with a stiff back and aching shoulders, that's all."
        },
        [12026618] = {
          ContentEN = "Health is no trifling matter; even minor discomforts should not be overlooked. I can instruct you in the Five-Animal Frolics, which help loosen the limbs and fortify the body.",
          DialogueId = 12026618,
          GUID = "1E1B7D04",
          NextDialogue = 12026619,
          SpeakNpcId = 210127,
          Subtitle = "Health is no trifling matter; even minor discomforts should not be overlooked. I can instruct you in the Five-Animal Frolics, which help loosen the limbs and fortify the body."
        },
        [12026619] = {
          ContentEN = "To grasp the essence of the Five Animals, practice should begin at cockcrow, while the world is still dim with the last of night. As the morning light strengthens and a gentle breeze stirs, you will feel the ease and clarity this training brings to both body and mind.",
          DialogueId = 12026619,
          GUID = "1E1B7D2E",
          NextDialogue = 12026620,
          SpeakNpcId = 210127,
          Subtitle = "To grasp the essence of the Five Animals, practice should begin at cockcrow, while the world is still dim with the last of night. As the morning light strengthens and a gentle breeze stirs, you will feel the ease and clarity this training brings to both body and mind."
        },
        [12026620] = {
          ContentEN = "I—I'm okay!",
          DialogueId = 12026620,
          GUID = "1E1B7D58",
          NextDialogue = 12026621,
          SpeakNpcId = 100001,
          Subtitle = "I—I'm okay!"
        },
        [12026621] = {
          ContentEN = "You know what — I just realised I'm actually fine, perfectly fine. I've never been this healthy in my life! Thank you for your kind advice, but there's really no need to put it into action...",
          DialogueId = 12026621,
          GUID = "1E1B7D82",
          NextDialogue = 12026622,
          SpeakNpcId = 100001,
          Subtitle = "You know what — I just realised I'm actually fine, perfectly fine. I've never been this healthy in my life! Thank you for your kind advice, but there's really no need to put it into action..."
        },
        [12026622] = {
          ContentEN = "*sigh*... {nickname}.",
          DialogueId = 12026622,
          GUID = "1E1B7DAC",
          NextDialogue = 12026623,
          SpeakNpcId = 210127,
          Subtitle = "*sigh*... ."
        },
        [12026623] = {
          ContentEN = "I shall let it pass this time. But should you feel unwell again, do not force yourself to bear it alone. Come to me, and I shall ease your troubles.",
          DialogueId = 12026623,
          GUID = "1E1B7DD6",
          NextDialogue = 12026640,
          SpeakNpcId = 210127,
          Subtitle = "I shall let it pass this time. But should you feel unwell again, do not force yourself to bear it alone. Come to me, and I shall ease your troubles."
        },
        [12026624] = {
          ContentEN = "You've seemed a bit off since you left the Oblivion Rift. Is something bothering you?",
          DialogueId = 12026624,
          GUID = "1E1B7E00",
          NextDialogue = 12026625,
          Subtitle = "You've seemed a bit off since you left the Oblivion Rift. Is something bothering you?"
        },
        [12026625] = {
          ContentEN = "You perceived it... Thank you for your concern.",
          DialogueId = 12026625,
          GUID = "1E1B7E2A",
          NextDialogue = 12026626,
          SpeakNpcId = 210127,
          Subtitle = "You perceived it... Thank you for your concern."
        },
        [12026626] = {
          ContentEN = "{nickname}, you too must have family who are dear to you. If you had, in a moment of carelessness, said something that caused them hurt... what would you do?",
          DialogueId = 12026626,
          GUID = "1E1B7E54",
          NextDialogue = 12026627,
          SpeakNpcId = 210127,
          Subtitle = ", you too must have family who are dear to you. If you had, in a moment of carelessness, said something that caused them hurt... what would you do?"
        },
        [12026627] = {
          ContentEN = "If it's family, there's nothing you can't work out. If something like that happened, I'd try my best to apologise — I'm sure she'd forgive me.",
          DialogueId = 12026627,
          GUID = "1E1B7E7E",
          NextDialogue = 12026628,
          SpeakNpcId = 100001,
          Subtitle = "If it's family, there's nothing you can't work out. If something like that happened, I'd try my best to apologise — I'm sure she'd forgive me."
        },
        [12026628] = {
          ContentEN = "But if that person had already passed on, and there was no one left to hear your apology... what then?",
          DialogueId = 12026628,
          GUID = "1E1B7EA8",
          NextDialogue = 12026629,
          SpeakNpcId = 210127,
          Subtitle = "But if that person had already passed on, and there was no one left to hear your apology... what then?"
        },
        [12026629] = {
          ContentEN = "Fushu...",
          DialogueId = 12026629,
          GUID = "1E1B7ED2",
          NextDialogue = 12026630,
          SpeakNpcId = 100001,
          Subtitle = "Fushu..."
        },
        [12026630] = {
          ContentEN = "Forgive me. I did not mean to burden you with my own sorrow.",
          DialogueId = 12026630,
          GUID = "1E1B7EFC",
          NextDialogue = 12026631,
          SpeakNpcId = 210127,
          Subtitle = "Forgive me. I did not mean to burden you with my own sorrow."
        },
        [12026631] = {
          ContentEN = "It's okay. If anything's ever bothering you, just come talk to me. I'm always there for you.",
          DialogueId = 12026631,
          GUID = "1E1B7F26",
          NextDialogue = 12026640,
          SpeakNpcId = 100001,
          Subtitle = "It's okay. If anything's ever bothering you, just come talk to me. I'm always there for you."
        },
        [12026632] = {
          ContentEN = "So you really are from a hundred years ago?",
          DialogueId = 12026632,
          GUID = "1E1B7F50",
          NextDialogue = 12026633,
          Subtitle = "So you really are from a hundred years ago?"
        },
        [12026633] = {
          ContentEN = "Mm... As I mentioned before, my elder sister placed my body in a deep sleep to arrest the course of my illness. Only recently was I awakened from that century of sleep.",
          DialogueId = 12026633,
          GUID = "1E1B7F7A",
          NextDialogue = 12026634,
          SpeakNpcId = 210127,
          Subtitle = "Mm... As I mentioned before, my elder sister placed my body in a deep sleep to arrest the course of my illness. Only recently was I awakened from that century of sleep."
        },
        [12026634] = {
          ContentEN = "Does the world feel strange to you now?",
          DialogueId = 12026634,
          GUID = "1E1B7FA4",
          NextDialogue = 12026635,
          SpeakNpcId = 100001,
          Subtitle = "Does the world feel strange to you now?"
        },
        [12026635] = {
          ContentEN = "Perhaps. When I first awoke, the world felt distant — as though all things beneath the sky no longer concerned me.",
          DialogueId = 12026635,
          GUID = "1E1B7FCE",
          NextDialogue = 12026636,
          SpeakNpcId = 210127,
          Subtitle = "Perhaps. When I first awoke, the world felt distant — as though all things beneath the sky no longer concerned me."
        },
        [12026636] = {
          ContentEN = "But as time passed, I came to meet companions such as yourself.",
          DialogueId = 12026636,
          GUID = "1E1B7FF8",
          NextDialogue = 12026637,
          SpeakNpcId = 210127,
          Subtitle = "But as time passed, I came to meet companions such as yourself."
        },
        [12026637] = {
          ContentEN = "The many changes in the world today, and the advances in medicine, are all new to me. In another light, that too may be considered a small blessing.",
          DialogueId = 12026637,
          GUID = "1E1B8022",
          NextDialogue = 12026640,
          SpeakNpcId = 210127,
          Subtitle = "The many changes in the world today, and the advances in medicine, are all new to me. In another light, that too may be considered a small blessing."
        },
        [12026638] = {
          ContentEN = "I should get going.",
          DialogueId = 12026638,
          GUID = "1E1B804C",
          NextDialogue = 12026639,
          Subtitle = "I should get going."
        },
        [12026639] = {
          ContentEN = "Go and see to your affairs — and take care of your health.",
          DialogueId = 12026639,
          GUID = "1E1B8076",
          SpeakNpcId = 210127,
          Subtitle = "Go and see to your affairs — and take care of your health."
