        },
        [12026901] = {
          ContentEN = "If I'm not mistaken, this ancient array's true name is the Myriad-Snare Hunting Array — crafted with countless snares that close in on the prey, and with gaps so fine they shut out even the faintest trace of light.",
          DialogueId = 12026901,
          GUID = "1E1BAB72",
          NextDialogue = 12026902,
          Subtitle = "If I'm not mistaken, this ancient array's true name is the Myriad-Snare Hunting Array — crafted with countless snares that close in on the prey, and with gaps so fine they shut out even the faintest trace of light."
