        },
        [12034002] = {
          Camera = "-60.111835,138.167587,81.243164,0.000218,5.395651,-9.014689,25.0,255.333679,false,Manual,6.0",
          ContentEN = "There's a terrifying monster in this world — one we can't see. It's called Prejudice. It makes people who should care about each other hate and hurt one another. That's what took your mum and dad.",
          DialogueId = 12034002,
          GUID = "1E203874",
          NextDialogue = 12034003,
          Scripts = "PlayAnimation{_delay{0},ActorId{100001},AnimationId{\"Explain02_Start\"}}",
          SpeakNpcId = 100001,
          Subtitle = "There's a terrifying monster in this world — one we can't see. It's called Prejudice. It makes people who should care about each other hate and hurt one another. That's what took your mum and dad.",
          VoiceName = "voice/$Locale$/story/1201/120114/1E203874"
        },
        [12034003] = {
          Camera = "116.961861,174.154648,120.447266,0.000223,-16.204643,-136.614212,25.0,255.333679,false,Manual,6.0",
          ContentEN = "Then I'll go fight it and bring them back!",
          DialogueId = 12034003,
          GUID = "1E20389E",
          NextDialogue = 12034004,
          Scripts = "PlayAnimation{_delay{0},ActorId{211015},AnimationId{\"Angry01_Start\"}}",
          SpeakNpcId = 211015,
          Subtitle = "Then I'll go fight it and bring them back!",
          VoiceName = "voice/$Locale$/story/1201/120114/1E20389E"
        },
        [12034004] = {
          Camera = "-29.829901,107.802788,74.746094,0.00025,12.194851,5.783125,25.000002,153.736694,false,Manual,6.0",
          ContentEN = "You're brave — but you're still young. And Prejudice isn't a monster you can punch away.",
          DialogueId = 12034004,
          GUID = "1E2038C8",
          NextDialogue = 12034005,
          Scripts = "PlayAnimation{_delay{0},ActorId{100001},AnimationId{\"Explain02_End\"}}",
          SpeakNpcId = 100001,
          Subtitle = "You're brave — but you're still young. And Prejudice isn't a monster you can punch away.",
          VoiceName = "voice/$Locale$/story/1201/120114/1E2038C8"
        },
        [12034005] = {
          ContentEN = "Because it feeds on people's doubts and fears. And it's grown strong because so many in this city have fallen under its spell.",
          DialogueId = 12034005,
          GUID = "1E2038F2",
          NextDialogue = 12034006,
          Scripts = "PlayAnimation{_delay{0},ActorId{100001},AnimationId{\"Talk02_Start\"}}",
          SpeakNpcId = 100001,
          Subtitle = "Because it feeds on people's doubts and fears. And it's grown strong because so many in this city have fallen under its spell.",
          VoiceName = "voice/$Locale$/story/1201/120114/1E2038F2"
        },
        [12034006] = {
          Camera = "159.328293,-18.95005,85.956055,0.00025,5.194987,100.784615,25.000002,138.543365,false,Manual,6.0",
          ContentEN = "But if we choose not to believe in it — if you don't, and I don't — and if we help our friends to be brave enough to fight its spell... then little by little, it'll lose its power.",
          DialogueId = 12034006,
          GUID = "1E20391C",
          NextDialogue = 12034007,
