        },
        [12035001] = {
          Content = "今天还是不要走太远比较好。",
          DialogueId = 12035001,
          GUID = "1E20DC5A"
        },
        [12035002] = {
          Content = "巢穴之外，有着广阔的世界。",
          DialogueId = 12035002,
          GUID = "1E20DC84"
        },
        [12035003] = {
          Content = "这条河流，一路向着危险的秘境。",
          DialogueId = 12035003,
          GUID = "1E20DCAE"
        },
        [12035004] = {
          Content = "是点石成金的公主殿下！",
          DialogueId = 12035004,
          GUID = "1E20DCD8"
        },
        [12035005] = {
          Content = "公主殿下看上去似乎很忙，还是不要打扰她了。",
          DialogueId = 12035005,
          GUID = "1E20DD02"
        },
        [12035006] = {
          Content = "小夜莺与点石成金的公主殿下擦肩而过，继续踏上旅途。",
          DialogueId = 12035006,
          GUID = "1E20DD2C"
        },
        [12035007] = {
          Content = "穿过砖石和钢铁铸造的森林。",
          DialogueId = 12035007,
          GUID = "1E20DD56"
        },
        [12035008] = {
          Content = "前方还有什么在等待着她呢？",
          DialogueId = 12035008,
          GUID = "1E20DD80"
        },
        [12035009] = {
          Content = "就像是童话里魔龙的嘴。",
          DialogueId = 12035009,
          GUID = "1E20DDAA"
        },
        [12035010] = {
          Content = "吸血鬼？他们似乎在谈论菲娜的事。",
          DialogueId = 12035010,
          GUID = "1E20DDD4"
        },
        [12035011] = {
          Content = "怎么办！她过来了！",
          DialogueId = 12035011,
          GUID = "1E20DDFE"
        },
        [12035012] = {
          Content = "先往这个方向看看？",
          DialogueId = 12035012,
          GUID = "1E20DE28"
        },
        [12035013] = {
          Content = "似乎不在这里……",
          DialogueId = 12035013,
          GUID = "1E20DE52"
        },
        [12035014] = {
          Content = "也许……",
          DialogueId = 12035014,
          GUID = "1E20DE7C"
        },
        [12035015] = {
          Content = "是保卫水管的叔叔。",
          DialogueId = 12035015,
          GUID = "1E20DEA6"
        },
        [12035016] = {
          Content = "那边的是！",
          DialogueId = 12035016,
          GUID = "1E20DED0"
        },
        [12035017] = {
          Content = "好可爱！",
          DialogueId = 12035017,
          GUID = "1E20DEFA"
        }
      }
    end
  },
