        [20006019] = {
          Camera = "-152.133362,-1170.719727,714.169434,0.000035,-27.996868,146.383102,35.0,674.116943,false,Manual,22.0",
          ContentEN = "There was that one time she insisted on going into a valley that looked barren — turns out she'd sniffed out a hidden patch of berries deep inside. Then there was the time she wouldn't budge from a flower shop until I bought some flowers — just so she could eat them in one bite.",
          DialogueId = 20006019,
          FinalCamera = "-66.008728,-699.472656,615.159668,0.000042,-26.596804,175.382294,35.0,671.116943,false,Manual,22.0",
          GUID = "32153D7E",
          NextDialogue = 20006020,
          SpeakNpcId = 200074,
          Subtitle = "There was that one time she insisted on going into a valley that looked barren — turns out she'd sniffed out a hidden patch of berries deep inside. Then there was the time she wouldn't budge from a flower shop until I bought some flowers — just so she could eat them in one bite.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/2001/200060/32153D7E"
        },
        [20006020] = {
          ContentEN = "And that other time, when she suddenly took off, sprinting straight up a hill without looking back at me for once. Then I realised there was a snake in the grass, and she was leading it away.",
          DialogueId = 20006020,
          GUID = "32153DA8",
          NextDialogue = 20006021,
          SpeakNpcId = 200074,
          Subtitle = "And that other time, when she suddenly took off, sprinting straight up a hill without looking back at me for once. Then I realised there was a snake in the grass, and she was leading it away.",
          VoiceName = "voice/$Locale$/story/2001/200060/32153DA8"
        },
