        [20006701] = {
          Camera = "-939.216797,26.854492,320.087097,0.0,-13.407927,0.807412,35.000008,450.0,false,Manual,6.0",
          ContentEN = "Lord {nickname}, Great Geniemon Hunter Hunter, and mighty Demon King of Light — have mercy! We're sorry! We'll leave the Geniemons alone!",
