          GUID = "7D6BBCA2",
          Subtitle = "I wonder... what the world beyond the sea is like.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6BBCA2"
        },
        [50100311] = {
          ContentEN = "The foreman was in a good mood yesterday — he even slipped us a little bonus.",
