        },
        [50107094] = {
          ContentEN = "\"One principle\" is the idea that heaven, earth, and all things share a single underlying truth. \"Many expressions\" means that the countless differences we see are simply manifestations of that same truth.",
          DialogueId = 50107094,
          GUID = "7D70171C",
          Subtitle = "\"One principle\" is the idea that heaven, earth, and all things share a single underlying truth. \"Many expressions\" means that the countless differences we see are simply manifestations of that same truth."
        },
        [50107095] = {
          ContentEN = "Flavours may differ a thousand ways, yet all tend towards the good. Tunes may change without end, yet all return to harmony. The young may vary in temperament, yet all share a quickness of wit. Methods of teaching may be many, yet all come back to the heart.",
          DialogueId = 50107095,
          GUID = "7D701746",
          Subtitle = "Flavours may differ a thousand ways, yet all tend towards the good. Tunes may change without end, yet all return to harmony. The young may vary in temperament, yet all share a quickness of wit. Methods of teaching may be many, yet all come back to the heart."
        },
        [50107096] = {
          ContentEN = "There's one principle behind everything. If it encompasses all things, it must come before all else!",
          DialogueId = 50107096,
          GUID = "7D701770",
          Subtitle = "There's one principle behind everything. If it encompasses all things, it must come before all else!"
        },
