          NextDialogue = 51000108,
          SpeakNpcId = 700020,
          Subtitle = "Ungrateful brat! You don't know what's good for you."
        },
        [51000108] = {
          ContentEN = "Ever since her ladyship was a little girl, she has loved my soups — it's been almost forty years.",
          DialogueId = 51000108,
          GUID = "7FAC6538",
          NextDialogue = 51000109,
          SpeakNpcId = 700020,
          Subtitle = "Ever since her ladyship was a little girl, she has loved my soups — it's been almost forty years."
        },
        [51000109] = {
          ContentEN = "*sigh* Her ladyship... I wonder if she'll ever get better.",
          DialogueId = 51000109,
          GUID = "7FAC6562",
          NextDialogue = 51000110,
          SpeakNpcId = 700020,
          Subtitle = "*sigh* Her ladyship... I wonder if she'll ever get better."
        },
        [51000110] = {
