            [1] = "700019:Sigh_End"
          }
        },
        [51000308] = {
          ContentEN = "I haven't seen you before. Are you from a nearby village?",
          DialogueId = 51000308,
          GUID = "7FAC8608",
          NextDialogue = 51000309,
          SpeakNpcId = 700019,
          Subtitle = "I haven't seen you before. Are you from a nearby village?",
          TalkActionId = {
            [1] = "700019:Explain02_Start"
          }
        },
        [51000309] = {
          ContentEN = "Have you ever come across a Charon man named Hamel Dickinson? He's an Icelake local, light brown hair, about nineteen years old, wears... Oh, no, I think he'd be about my age now.",
          DialogueId = 51000309,
          GUID = "7FAC8632",
          NextDialogue = 51000310,
          SpeakNpcId = 700019,
          Subtitle = "Have you ever come across a Charon man named Hamel Dickinson? He's an Icelake local, light brown hair, about nineteen years old, wears... Oh, no, I think he'd be about my age now."
        },
        [51000310] = {
          ContentEN = "I left Icelake forty years ago and lost touch with him ever since. Now I'm back, but I haven't found any trace of him.",
          DialogueId = 51000310,
          GUID = "7FAC865C",
          NextDialogue = 51000311,
          SpeakNpcId = 700019,
          Subtitle = "I left Icelake forty years ago and lost touch with him ever since. Now I'm back, but I haven't found any trace of him."
        },
        [51000311] = {
          ContentEN = "He was born and raised here in Icelake, so I figure, even if he doesn't live here anymore, he can't be far. Young one, have you seen him around?",
          DialogueId = 51000311,
          GUID = "7FAC8686",
          NextOptions = {
            [1] = 510003111
          },
          SpeakNpcId = 700019,
          Subtitle = "He was born and raised here in Icelake, so I figure, even if he doesn't live here anymore, he can't be far. Young one, have you seen him around?",
          TalkActionId = {
            [1] = "700019:Explain02_End"
          },
          bForbidSkipOptions = true
        },
        [51000312] = {
          ContentEN = "Okay...",
          DialogueId = 51000312,
          GUID = "7FAC86B0",
          NextDialogue = 51000313,
          SpeakNpcId = 700019,
          Subtitle = "Okay...",
          TalkActionId = {
            [1] = "700019:Agree"
          }
        },
        [51000313] = {
          ContentEN = "If you do see him someday, could you pass on a message?",
          DialogueId = 51000313,
          GUID = "7FAC86DA",
          NextDialogue = 51000314,
          SpeakNpcId = 700019,
          Subtitle = "If you do see him someday, could you pass on a message?"
        },
        [51000314] = {
          ContentEN = "\"Hilin has returned to Icelake. She's been waiting for you and an explanation that is forty years overdue.\"",
          DialogueId = 51000314,
          GUID = "7FAC8704",
          NextDialogue = 51000315,
          SpeakNpcId = 700019,
          Subtitle = "\"Hilin has returned to Icelake. She's been waiting for you and an explanation that is forty years overdue.\"",
          TalkActionId = {
            [1] = "700019:Explain01_Start"
          }
        },
        [51000315] = {
          ContentEN = "If you don't see him until next year, ask him why he's forty-one years late. If it's the year after, it'll be forty-two... I've been keeping count.",
          DialogueId = 51000315,
          GUID = "7FAC872E",
          NextDialogue = 51000316,
          SpeakNpcId = 700019,
          Subtitle = "If you don't see him until next year, ask him why he's forty-one years late. If it's the year after, it'll be forty-two... I've been keeping count.",
          TalkActionId = {
            [1] = "700019:Explain01_End"
          }
        },
