          SpeakNpcId = 700032,
          SpeakNpcName = "UI_CMNpc_Name_Alice",
          Subtitle = "My name is Alice, I'm an archaeology student from Aethyrie...",
          TalkActionId = {
            [1] = "700032:Talk02_Start"
          }
        },
        [51000806] = {
          ContentEN = "I was conducting a survey in the Vidofnir Mountains when I got caught in a snowstorm that lasted for days, and soon I lost my way...",
          DialogueId = 51000806,
          GUID = "7FACD7BC",
          NextDialogue = 51000807,
          SpeakNpcId = 700032,
          SpeakNpcName = "UI_CMNpc_Name_Alice",
          Subtitle = "I was conducting a survey in the Vidofnir Mountains when I got caught in a snowstorm that lasted for days, and soon I lost my way..."
        },
        [51000807] = {
          ContentEN = "Later on, I met Annie, who was clinging to life by a mere thread. Together, we struggled to live on for several days. We encouraged each other to try to survive, and she invited me to visit her home in Icelake after the storm...",
          DialogueId = 51000807,
          GUID = "7FACD7E6",
          NextDialogue = 51000808,
          SpeakNpcId = 700032,
          SpeakNpcName = "UI_CMNpc_Name_Alice",
          Subtitle = "Later on, I met Annie, who was clinging to life by a mere thread. Together, we struggled to live on for several days. We encouraged each other to try to survive, and she invited me to visit her home in Icelake after the storm..."
        },
        [51000808] = {
          ContentEN = "But... she was too badly hurt. She didn't make it. Before she passed, she gave me her coat. Said it might keep me warm enough to get through...",
          DialogueId = 51000808,
          GUID = "7FACD810",
          NextDialogue = 51000809,
          SpeakNpcId = 700032,
          SpeakNpcName = "UI_CMNpc_Name_Alice",
          Subtitle = "But... she was too badly hurt. She didn't make it. Before she passed, she gave me her coat. Said it might keep me warm enough to get through...",
