          GUID = "7FACE752",
          NextDialogue = 51000902,
          SpeakNpcId = 700022,
          Subtitle = "A new customer! What brings you here? But if you're looking for some fun, you've come to the right place with Martin!",
          TalkActionId = {
            [1] = "700022:Talk01_Start"
          }
        },
        [51000902] = {
          ContentEN = "(The man in front of you performs an extravagant bow, then magically displays a bunch of scattered goods.)",
          DialogueId = 51000902,
          GUID = "7FACE77C",
          NextDialogue = 51000903,
          SpeakNpcId = 700022,
          Subtitle = "(The man in front of you performs an extravagant bow, then magically displays a bunch of scattered goods.)"
        },
        [51000903] = {
          ContentEN = "Feel free to choose. Trust Martin's choice! You can find everything here, seen or unseen, occasionally spicing up your life!",
          DialogueId = 51000903,
          GUID = "7FACE7A6",
          SpeakNpcId = 700022,
          Subtitle = "Feel free to choose. Trust Martin's choice! You can find everything here, seen or unseen, occasionally spicing up your life!",
          TalkActionId = {
            [1] = "700022:Talk01_End"
          },
          TalkOptions = {
            [1] = 510009031,
            [2] = 510009032,
            [3] = 510009033
          }
        },
        [51000904] = {
          ContentEN = "You're quite impolite. Being able to appraise doesn't mean you have good taste, sweetheart.",
          DialogueId = 51000904,
          GUID = "7FACE7D0",
          SpeakNpcId = 700022,
          Subtitle = "You're quite impolite. Being able to appraise doesn't mean you have good taste, sweetheart.",
          TalkOptions = {
            [1] = 510009071
          }
        },
        [51000905] = {
          ContentEN = "Isn't letting them go to waste also a crime? I just want to find a home for them all.",
          DialogueId = 51000905,
          GUID = "7FACE7FA",
          SpeakNpcId = 700022,
          Subtitle = "Isn't letting them go to waste also a crime? I just want to find a home for them all.",
          TalkOptions = {
            [1] = 510009071
          }
        },
        [51000906] = {
          ContentEN = "Nah-ah. That's a trade secret. So, have you thought about what you'd like to exchange with me?",
          DialogueId = 51000906,
          GUID = "7FACE824",
          SpeakNpcId = 700022,
          Subtitle = "Nah-ah. That's a trade secret. So, have you thought about what you'd like to exchange with me?",
          TalkOptions = {
            [1] = 510009071
          }
        },
        [51000907] = {
          ContentEN = "(You look at his goods and sadly shake your head.) ",
          DialogueId = 51000907,
          GUID = "7FACE84E",
          Subtitle = "(You look at his goods and sadly shake your head.) ",
          TalkOptions = {
            [1] = 510009072
          }
        },
        [51000908] = {
          ContentEN = "Then I'm probably not the person you need, but I'll wait for the day you extend your patronage.",
          DialogueId = 51000908,
          GUID = "7FACE878",
          SpeakNpcId = 700022,
          Subtitle = "Then I'm probably not the person you need, but I'll wait for the day you extend your patronage."
        },
        [51000909] = {
          ContentEN = "I got it! You're a rare kind of person in Icelake…",
          DialogueId = 51000909,
          GUID = "7FACE8A2",
          NextDialogue = 51000910,
          SpeakNpcId = 700022,
          Subtitle = "I got it! You're a rare kind of person in Icelake…",
          TalkActionId = {
            [1] = "700022:Think_Start"
          }
        },
        [51000910] = {
          ContentEN = "You're neither a slum dweller here to buy cheap supplies nor a noble interested in the private lives of your neighbors. You have no desire or need for Martin. You've never even heard my name, have you?",
          DialogueId = 51000910,
          GUID = "7FACE8CC",
          SpeakNpcId = 700022,
          Subtitle = "You're neither a slum dweller here to buy cheap supplies nor a noble interested in the private lives of your neighbors. You have no desire or need for Martin. You've never even heard my name, have you?",
          TalkActionId = {
            [1] = "700022:Think_End"
          },
          TalkOptions = {
            [1] = 510009101,
            [2] = 510009102,
            [3] = 510009103
          }
        },
        [51000911] = {
          ContentEN = "Then allow me to introduce myself! I am the King of Scavengers in Icelake, the confidant brother of every rubbish bin, and the best spokesperson and promoter of discarded items. ",
          DialogueId = 51000911,
          GUID = "7FACE8F6",
          NextDialogue = 51000990,
          SpeakNpcId = 700022,
          Subtitle = "Then allow me to introduce myself! I am the King of Scavengers in Icelake, the confidant brother of every rubbish bin, and the best spokesperson and promoter of discarded items. ",
          TalkActionId = {
            [1] = "700022:Confident_Start"
          }
        },
        [51000912] = {
          ContentEN = "In fact, rubbish bins hide all sorts of secrets. As long as you're patient enough and don't mind the hard work, they will continue to share with you the secrets of their households.",
          DialogueId = 51000912,
          GUID = "7FACE920",
          SpeakNpcId = 700022,
          Subtitle = "In fact, rubbish bins hide all sorts of secrets. As long as you're patient enough and don't mind the hard work, they will continue to share with you the secrets of their households.",
          TalkActionId = {
            [1] = "700022:Confident_End"
          }
        },
        [51000913] = {
          ContentEN = "Now you get intrigued? That's great. I know ordinary goods won't impress you, but Martin has his ways.",
          DialogueId = 51000913,
          GUID = "7FACE94A",
          NextDialogue = 51000991,
          SpeakNpcId = 700022,
          Subtitle = "Now you get intrigued? That's great. I know ordinary goods won't impress you, but Martin has his ways.",
          TalkActionId = {
            [1] = "700022:Explain01_Start"
          }
        },
        [51000914] = {
          ContentEN = "If you can help find their owners, you might understand this city better. Even if you get nothing, at least you satisfy your curiosity.",
          DialogueId = 51000914,
          GUID = "7FACE974",
          NextDialogue = 51000915,
          SpeakNpcId = 700022,
          Subtitle = "If you can help find their owners, you might understand this city better. Even if you get nothing, at least you satisfy your curiosity.",
          TalkActionId = {
            [1] = "700022:Explain01_End"
          }
        },
        [51000915] = {
          ContentEN = "(Martin produces some indescribable things and winks at you.)",
          DialogueId = 51000915,
          GUID = "7FACE99E",
          NextDialogue = 51000916,
          Subtitle = "(Martin produces some indescribable things and winks at you.)"
        },
        [51000916] = {
          ContentEN = "Want to give it a try?",
          DialogueId = 51000916,
