          LookAt = {
            [1] = "0:n(700021)"
          },
          NextDialogue = 51001004,
          SpeakNpcId = 700021,
          Subtitle = "Will you politely pull out a huge amount of money to buy a ticket, or will you fiddle with your empty pockets and boss me around?"
        },
        [51001091] = {
          Camera = "-104.777344,10.944336,99.62793,0.000124,-3.797551,-18.159431,35.0,200.0,false,Manual,2.8",
          ContentEN = "This weather is just right for you to strike a match and call for grandma, dreaming that she takes you on a train. Go wherever you like in your dream, and stop shaming yourself in front of me!",
          DialogueId = 51001091,
          GUID = "7FAD067E",
          LookAt = {
