        [51001092] = {
          ContentEN = "(But the good thing is she was no longer as temperamental and foul-mouthed as before.)",
          DialogueId = 51001092,
          GUID = "7FAD06A8",
          Subtitle = "(But the good thing is she was no longer as temperamental and foul-mouthed as before.)"
        },
        [51001101] = {
          ContentEN = "(A Filthoid, wandering from nowhere, clutched a notebook in its jaws. After defeating the Filthoid, you picked up the notebook...)",
          DialogueId = 51001101,
          GUID = "7FAD0822",
          NextDialogue = 51001102,
          Subtitle = "(A Filthoid, wandering from nowhere, clutched a notebook in its jaws. After defeating the Filthoid, you picked up the notebook...)"
        },
        [51001102] = {
          ContentEN = "(If the words in this diary are true... then the truth is clear at last.)",
          DialogueId = 51001102,
          GUID = "7FAD084C",
          NextDialogue = 51001103,
          Subtitle = "(If the words in this diary are true... then the truth is clear at last.)"
        },
        [51001103] = {
          ContentEN = "(...Annie has tragically passed away, while the other girl, Alice, who ended up with Annie's clothes, has survived. Although Alice made it through the ordeal in the snowy mountains, the severe fevers she suffered afterwards took away her memories.)",
          DialogueId = 51001103,
          GUID = "7FAD0876",
          Subtitle = "(...Annie has tragically passed away, while the other girl, Alice, who ended up with Annie's clothes, has survived. Although Alice made it through the ordeal in the snowy mountains, the severe fevers she suffered afterwards took away her memories.)"
        },
        [51001201] = {
          ContentEN = "A Phoxhunter? Can't believe anyone would still make it here. You've got what it takes to be a hero like them, I guess.",
          DialogueId = 51001201,
          GUID = "7FAD188A",
          NextDialogue = 51001212,
          SpeakNpcId = 700003,
          Subtitle = "A Phoxhunter? Can't believe anyone would still make it here. You've got what it takes to be a hero like them, I guess.",
          TalkActionId = {
            [1] = "700003:Explain01_Start"
          }
        },
        [51001202] = {
          ContentEN = "Well, who else but this old geezer would bother keeping these birds nowadays.",
          DialogueId = 51001202,
          GUID = "7FAD18B4",
          NextDialogue = 51001204,
          SpeakNpcId = 700003,
          Subtitle = "Well, who else but this old geezer would bother keeping these birds nowadays.",
          TalkActionId = {
            [1] = "700003:Explain01_End"
          }
        },
        [51001203] = {
          ContentEN = "Are you insane?? Do you have any idea how precious these birds are to a miner?!",
          DialogueId = 51001203,
          GUID = "7FAD18DE",
          NextDialogue = 51001204,
          SpeakNpcId = 700003,
          Subtitle = "Are you insane?? Do you have any idea how precious these birds are to a miner?!",
          TalkActionId = {
            [1] = "700003:Disagree"
          }
        },
        [51001204] = {
          ContentEN = "Miners today have grown so reliant on the high-tech gadgets from the Alchemy Academy, that they have forgotten the old ways.",
          DialogueId = 51001204,
          GUID = "7FAD1908",
          NextOptions = {
            [1] = 510012041,
            [2] = 510012042,
            [3] = 510012043
          },
          SpeakNpcId = 700003,
          Subtitle = "Miners today have grown so reliant on the high-tech gadgets from the Alchemy Academy, that they have forgotten the old ways.",
          bForbidSkipOptions = true
        },
        [51001205] = {
          ContentEN = "Exactly, their amazing sensitivity to harmful gases made them a must-have for us miners in the old days. We'd always have one by our side underground to help detect whether the tunnels were safe.",
          DialogueId = 51001205,
          GUID = "7FAD1932",
          NextDialogue = 51001208,
          SpeakNpcId = 700003,
          Subtitle = "Exactly, their amazing sensitivity to harmful gases made them a must-have for us miners in the old days. We'd always have one by our side underground to help detect whether the tunnels were safe.",
          TalkActionId = {
            [1] = "700003:Agree"
          }
        },
        [51001206] = {
          ContentEN = "Well said. Quite rare to find young folks with such insight these days.",
          DialogueId = 51001206,
          GUID = "7FAD195C",
          NextDialogue = 51001208,
          SpeakNpcId = 700003,
          Subtitle = "Well said. Quite rare to find young folks with such insight these days.",
          TalkActionId = {
            [1] = "700003:Explain01_Start"
          }
        },
        [51001207] = {
          ContentEN = "Hmph, I do what I do for us miners' sake. I don't need others' approval.",
          DialogueId = 51001207,
          GUID = "7FAD1986",
          NextDialogue = 51001208,
          SpeakNpcId = 700003,
          Subtitle = "Hmph, I do what I do for us miners' sake. I don't need others' approval.",
          TalkActionId = {
            [1] = "700003:Explain01_End"
          }
        },
        [51001208] = {
          ContentEN = "Soulless tools may fail you, or even betray you. It's the companion you've always cherished that will stand by you through every trial.",
          DialogueId = 51001208,
          GUID = "7FAD19B0",
          NextDialogue = 51001209,
          SpeakNpcId = 700003,
          Subtitle = "Soulless tools may fail you, or even betray you. It's the companion you've always cherished that will stand by you through every trial.",
          TalkActionId = {
            [1] = "700003:Think_Start"
          }
        },
        [51001209] = {
          ContentEN = "Should the day come when the Academy's fancy tools give out, it may well be these loyal friends that save miners' lives...",
          DialogueId = 51001209,
          GUID = "7FAD19DA",
          NextDialogue = 51001210,
          SpeakNpcId = 700003,
          Subtitle = "Should the day come when the Academy's fancy tools give out, it may well be these loyal friends that save miners' lives...",
          TalkActionId = {
            [1] = "700003:Think_End"
          }
        },
        [51001210] = {
          ContentEN = "(The old miner's gaze settles on a nearby mound, his lips trembling with unvoiced thoughts, culminating in nothing but a weary sigh.)",
          DialogueId = 51001210,
          GUID = "7FAD1A04",
          Subtitle = "(The old miner's gaze settles on a nearby mound, his lips trembling with unvoiced thoughts, culminating in nothing but a weary sigh.)"
        },
        [51001211] = {
          ContentEN = "(In silence, the elder periodically snaps from his thoughts, letting out a lingering sigh. It's unclear whether it's a tribute to a fallen comrade or a lament for the changing times.)",
          DialogueId = 51001211,
          GUID = "7FAD1A2E",
          Subtitle = "(In silence, the elder periodically snaps from his thoughts, letting out a lingering sigh. It's unclear whether it's a tribute to a fallen comrade or a lament for the changing times.)"
        },
        [51001212] = {
          ContentEN = "The elder watched a dark speck in the sky with a soft gaze. You looked out and saw a distant flock of birds. The conversation resumed only after the last one had vanished.",
          DialogueId = 51001212,
          GUID = "7FAD188B",
          NextOptions = {
            [1] = 510012011,
            [2] = 510012012
          },
          Subtitle = "The elder watched a dark speck in the sky with a soft gaze. You looked out and saw a distant flock of birds. The conversation resumed only after the last one had vanished.",
          bForbidSkipOptions = true
        },
        [51001301] = {
          ContentEN = "That blasted Camilla! Stupid hag! She has no idea what good stuff tastes like!",
          DialogueId = 51001301,
          GUID = "7FAD28F2",
          NextDialogue = 510013013,
          SpeakNpcId = 700014,
          Subtitle = "That blasted Camilla! Stupid hag! She has no idea what good stuff tastes like!"
        },
        [51001302] = {
