          NextDialogue = 51001609,
          SpeakNpcId = 700068,
          Subtitle = "For your information, we Charons aren't all cut from the same cloth!"
        },
        [51001609] = {
          ContentEN = "Since I was a kid, I've held myself to Sola standards, and never mingled with other Charons. Ever met a Charon who speaks like I do? Just so you know, this is a standard Dismania accent!",
          DialogueId = 51001609,
          GUID = "7FAD5B7A",
          NextDialogue = 51001691,
          SpeakNpcId = 700068,
          Subtitle = "Since I was a kid, I've held myself to Sola standards, and never mingled with other Charons. Ever met a Charon who speaks like I do? Just so you know, this is a standard Dismania accent!"
        },
        [51001610] = {
          ContentEN = "Jealous, huh? Well, I've earned this!",
