        [51001704] = {
          ContentEN = "You might not believe it, but there was a time people respectfully addressed me as \"Doctor Dutton\".",
          DialogueId = 51001704,
          GUID = "7FAD6B10",
          NextDialogue = 51001705,
          SpeakNpcId = 700069,
          Subtitle = "You might not believe it, but there was a time people respectfully addressed me as \"Doctor Dutton\"."
        },
        [51001705] = {
          ContentEN = "You get what that title means to a Charon who's come up from the slums, right?",
          DialogueId = 51001705,
          GUID = "7FAD6B3A",
          NextDialogue = 51001706,
          SpeakNpcId = 700069,
          Subtitle = "You get what that title means to a Charon who's come up from the slums, right?"
        },
        [51001706] = {
          ContentEN = "I've treated countless Charons at the central hospital; even the nobility sought me out for consultations.",
          DialogueId = 51001706,
          GUID = "7FAD6B64",
          NextDialogue = 51001707,
          SpeakNpcId = 700069,
          Subtitle = "I've treated countless Charons at the central hospital; even the nobility sought me out for consultations.",
          TalkActionId = {
            [1] = "700069:Explain02_Start"
          }
        },
        [51001707] = {
          ContentEN = "Don't take my word for it — go ask the younger Charons. Their folks always told them to model themselves on me.",
          DialogueId = 51001707,
          GUID = "7FAD6B8E",
          NextDialogue = 51001708,
          SpeakNpcId = 700069,
          Subtitle = "Don't take my word for it — go ask the younger Charons. Their folks always told them to model themselves on me.",
          TalkActionId = {
            [1] = "700069:Explain02_End"
          }
        },
        [51001708] = {
          ContentEN = "I was quite a stickler for cleanliness back then; a single speck of dust between the tiles would drive me nuts...",
          DialogueId = 51001708,
          GUID = "7FAD6BB8",
          NextOptions = {
