          },
          bForbidSkipOptions = true
        },
        [51001924] = {
          ContentEN = "He made it himself. Over a decade ago, there wasn't a soul who hadn't heard of Todd Wells, the prodigy clockmaker. Back then, his craftsmanship almost won him the title of Laurelled Charon.",
          DialogueId = 51001924,
          GUID = "7FAD8F28",
          NextDialogue = 51001925,
          SpeakNpcId = 200003,
          Subtitle = "He made it himself. Over a decade ago, there wasn't a soul who hadn't heard of Todd Wells, the prodigy clockmaker. Back then, his craftsmanship almost won him the title of Laurelled Charon.",
          TalkActionId = {
            [1] = "200003:Explain01_Start"
          }
        },
        [51001925] = {
          ContentEN = "Such a beautifully crafted watch. It's a pity it cracked like that.",
