          TalkActionId = {
            [1] = "700020:Explain01_End"
          }
        },
        [51002440] = {
          ContentEN = "She made up her mind that if he showed up, she would run away with him, no matter the destination.",
          DialogueId = 51002440,
          GUID = "51002440.0",
          NextOptions = {
            [1] = 51002441
          },
          SpeakNpcId = 700020,
          Subtitle = "She made up her mind that if he showed up, she would run away with him, no matter the destination."
        },
        [51002441] = {
          ContentEN = "He didn't show up?",
          DialogueId = 51002441,
          GUID = "51002441.0",
          NextDialogue = 51002442,
          Subtitle = "He didn't show up?"
        },
        [51002442] = {
          ContentEN = "That's right. Miss Hilin waited there till dawn, but only her furious father showed up. Soon after, she was sent away like a parcel to Flagson.",
          DialogueId = 51002442,
          GUID = "51002442.0",
          NextDialogue = 51002443,
          SpeakNpcId = 700020,
          Subtitle = "That's right. Miss Hilin waited there till dawn, but only her furious father showed up. Soon after, she was sent away like a parcel to Flagson.",
          TalkActionId = {
            [1] = "700020:Agree"
          }
        },
        [51002443] = {
          ContentEN = "Thank goodness that her husband — his lordship — treated her well, and she spent forty peaceful years with him. She never mentioned those days again, as if Hamel Dickinson had never existed.",
          DialogueId = 51002443,
          GUID = "51002443.0",
          NextDialogue = 51002444,
          SpeakNpcId = 700020,
          Subtitle = "Thank goodness that her husband — his lordship — treated her well, and she spent forty peaceful years with him. She never mentioned those days again, as if Hamel Dickinson had never existed."
        },
        [51002444] = {
          ContentEN = "A year ago, his lordship passed away, and her ladyship's health began to fail. One day, she suddenly told me she wanted to return to Icelake in her final days, to find the answer she deserved. That's when I realised, she had never forgotten Hamel Dickinson — he had become a missing piece of her heart.",
          DialogueId = 51002444,
          GUID = "51002444.0",
          NextDialogue = 51002445,
          SpeakNpcId = 700020,
          Subtitle = "A year ago, his lordship passed away, and her ladyship's health began to fail. One day, she suddenly told me she wanted to return to Icelake in her final days, to find the answer she deserved. That's when I realised, she had never forgotten Hamel Dickinson — he had become a missing piece of her heart."
        },
        [51002445] = {
          ContentEN = "So we moved back to Icelake, but no one knew of Hamel Dickinson's whereabouts. We managed to track down a few old miners, but after racking their memories, the last time they remembered seeing Mr Dickinson was forty years ago...",
          DialogueId = 51002445,
          GUID = "51002445.0",
          NextDialogue = 51002425,
          SpeakNpcId = 700020,
          Subtitle = "So we moved back to Icelake, but no one knew of Hamel Dickinson's whereabouts. We managed to track down a few old miners, but after racking their memories, the last time they remembered seeing Mr Dickinson was forty years ago...",
          TalkActionId = {
            [1] = "700020:Sigh_Start"
          }
        },
