        [51002909] = {
          ContentEN = "Mr Buck. Can't handle even a drop of alcohol — so it's always fruit juice or milk for him. Profession... third-rate playwright, first-rate producer of mumble-jumble. He's been spinning his yarns for a while now.",
          DialogueId = 51002909,
          GUID = "7FAE30C2",
          NextDialogue = 51002910,
          SpeakNpcId = 200003,
          Subtitle = "Mr Buck. Can't handle even a drop of alcohol — so it's always fruit juice or milk for him. Profession... third-rate playwright, first-rate producer of mumble-jumble. He's been spinning his yarns for a while now."
        },
        [51002910] = {
          ContentEN = "As you can see, the man struggles to convey his thoughts clearly. Could you help by translating his flamboyant narratives?",
          DialogueId = 51002910,
          GUID = "7FAE30EC",
