          },
          bForbidSkipOptions = true
        },
        [51003004] = {
          ContentEN = "Alas! Either my unwitting arrogance has peeved the goddess of inspiration, or the deity of sleep has played his cruel tricks on me! Otherwise, I would have noticed the sands of time trickling by!",
          DialogueId = 51003004,
          GUID = "7FAE4058",
          NextDialogue = 51003005,
          SpeakNpcId = 700015,
          Subtitle = "Alas! Either my unwitting arrogance has peeved the goddess of inspiration, or the deity of sleep has played his cruel tricks on me! Otherwise, I would have noticed the sands of time trickling by!",
          TalkActionId = {
            [1] = "700015:Sigh_Start"
          }
        },
        [51003005] = {
          ContentEN = "I ought to have greeted dawn with pages filled with prose and stanzas. Instead, I awoke refreshed with an empty soul, and my sheets of paper blank!",
          DialogueId = 51003005,
          GUID = "7FAE4082",
          NextOptions = {
            [1] = 510030051,
            [2] = 510030052
          },
          SpeakNpcId = 700015,
          Subtitle = "I ought to have greeted dawn with pages filled with prose and stanzas. Instead, I awoke refreshed with an empty soul, and my sheets of paper blank!",
          TalkActionId = {
            [1] = "700015:Sigh_End"
          },
          bForbidSkipOptions = true
        },
        [51003006] = {
          ContentEN = "In my enthralling dreams, I heard gentle footsteps, light as the dance of fairies. The scent of ripe fruits slathered in sweet honey wafted through the air!",
          DialogueId = 51003006,
          GUID = "7FAE40AC",
          NextDialogue = 51003007,
          SpeakNpcId = 700015,
          Subtitle = "In my enthralling dreams, I heard gentle footsteps, light as the dance of fairies. The scent of ripe fruits slathered in sweet honey wafted through the air!",
          TalkActionId = {
            [1] = "700015:Explain01_Start"
          }
        },
        [51003007] = {
          ContentEN = "Perhaps I was lost in my dreams, but those sounds and smells brought me back to reality! They are ephemeral, lingering by my side. Yet I am certain of their existence...",
          DialogueId = 51003007,
          GUID = "7FAE40D6",
          NextOptions = {
            [1] = 510030071,
            [2] = 510030072
          },
          SpeakNpcId = 700015,
          Subtitle = "Perhaps I was lost in my dreams, but those sounds and smells brought me back to reality! They are ephemeral, lingering by my side. Yet I am certain of their existence...",
          TalkActionId = {
            [1] = "700015:Explain01_End"
          },
          bForbidSkipOptions = true
        },
        [51003008] = {
          ContentEN = "They are not hallucinations, yet I fail to grasp their trails. I cannot fathom these strange incidents. Are they phantoms? Ghosts? Or mere illusions?",
          DialogueId = 51003008,
          GUID = "7FAE4100",
          NextDialogue = 51003009,
          SpeakNpcId = 700015,
          Subtitle = "They are not hallucinations, yet I fail to grasp their trails. I cannot fathom these strange incidents. Are they phantoms? Ghosts? Or mere illusions?",
          TalkActionId = {
            [1] = "700015:Disagree"
          }
        },
        [51003009] = {
          ContentEN = "My dilapidated abode remained untouched. This spirit stole nothing but my inspiration, which I cherish as dearly as life itself! It threatens to shatter my dreams...",
          DialogueId = 51003009,
          GUID = "7FAE412A",
          NextOptions = {
