          },
          SpeakNpcId = 700015,
          Subtitle = "My dilapidated abode remained untouched. This spirit stole nothing but my inspiration, which I cherish as dearly as life itself! It threatens to shatter my dreams...",
          bForbidSkipOptions = true
        },
        [51003010] = {
          ContentEN = "A playwright's night cannot be squandered on sleep! I implore any of you to heed my plea! Banish this vile burglar of inspiration so that my magnum opus may yet be completed!",
          DialogueId = 51003010,
          GUID = "7FAE4154",
