        [51003101] = {
          ContentEN = "Camila said Mr Buck can't handle alcohol — he never drinks. So... someone must've spiked the milk.",
          DialogueId = 51003101,
          GUID = "7FAE5042",
          NextDialogue = 51003102,
          SpeakNpcId = 100001,
          Subtitle = "Camila said Mr Buck can't handle alcohol — he never drinks. So... someone must've spiked the milk."
        },
        [51003102] = {
          ContentEN = "Wait — there's a sticky fingerprint on the jug. Small... child-sized, even.",
          DialogueId = 51003102,
          GUID = "7FAE506C",
          SpeakNpcId = 100001,
          Subtitle = "Wait — there's a sticky fingerprint on the jug. Small... child-sized, even."
        },
        [51003103] = {
          ContentEN = "The prints lead from the street right up to the window. And there's melted snow inside... No attempt to cover their tracks — looks like it really was just a kid.",
          DialogueId = 51003103,
          GUID = "7FAE5096",
          SpeakNpcId = 100001,
          Subtitle = "The prints lead from the street right up to the window. And there's melted snow inside... No attempt to cover their tracks — looks like it really was just a kid."
        },
        [51003104] = {
          ContentEN = "So a kid poured booze into Buck's milk and knocked him out cold. Better have another look around, see what else I can dig up.",
          DialogueId = 51003104,
          Duration = 4,
          GUID = "7FAE50C0",
          SpeakNpcId = 100001,
          Subtitle = "So a kid poured booze into Buck's milk and knocked him out cold. Better have another look around, see what else I can dig up."
        },
        [51003105] = {
          ContentEN = "Excuse me — do any kids ever visit Mr Buck?",
          DialogueId = 51003105,
          GUID = "7FAE50EA",
          NextDialogue = 51003106,
          SpeakNpcId = 100001,
          Subtitle = "Excuse me — do any kids ever visit Mr Buck?"
        },
        [51003106] = {
          ContentEN = "Kids? Visiting Buck? You're kidding, right? What kid would wanna hang around him? The guy <H>barely leaves the house — unless it's the tavern or the theatre</>. And when he talks, it's like listening to a bad play in reverse.",
          DialogueId = 51003106,
          GUID = "7FAE5114",
          NextDialogue = 51003107,
          SpeakNpcId = 700213,
          Subtitle = "Kids? Visiting Buck? You're kidding, right? What kid would wanna hang around him? The guy barely leaves the house — unless it's the tavern or the theatre. And when he talks, it's like listening to a bad play in reverse."
        },
        [51003107] = {
          ContentEN = "Not just kids — we hardly speak to him either. He's a nuisance. No one can understand a word he says. He hasn't done anything illegal, has he? 'Cause I always said there was something off about that man.",
          DialogueId = 51003107,
          GUID = "7FAE513E",
          NextDialogue = 51003108,
          SpeakNpcId = 700213,
          Subtitle = "Not just kids — we hardly speak to him either. He's a nuisance. No one can understand a word he says. He hasn't done anything illegal, has he? 'Cause I always said there was something off about that man."
        },
        [51003108] = {
          ContentEN = "(The old woman rattles off a list of Buck's \"crimes\" — too old to be jobless, never leaves the house, no wife, no friends... It isn't until she's talked herself hoarse that you finally manage to slip away.)",
          DialogueId = 51003108,
          GUID = "7FAE5168",
          NextDialogue = 51003109,
          Subtitle = "(The old woman rattles off a list of Buck's \"crimes\" — too old to be jobless, never leaves the house, no wife, no friends... It isn't until she's talked herself hoarse that you finally manage to slip away.)"
        },
        [51003109] = {
          ContentEN = "(Mr Buck rarely leaves home and keeps to himself — most people hardly know a thing about him. So if a kid somehow knew about his weakness for alcohol... they must've picked it up somewhere.)",
          DialogueId = 51003109,
          GUID = "7FAE5192",
          NextDialogue = 51003110,
          SpeakNpcId = 100001,
          Subtitle = "(Mr Buck rarely leaves home and keeps to himself — most people hardly know a thing about him. So if a kid somehow knew about his weakness for alcohol... they must've picked it up somewhere.)"
        },
        [51003110] = {
          ContentEN = "(The Asphodel's no place for kids, and no one's seen any near Buck's house. That leaves one place: the theatre. I should check it out.)",
          DialogueId = 51003110,
          GUID = "7FAE51BC",
          SpeakNpcId = 100001,
          Subtitle = "(The Asphodel's no place for kids, and no one's seen any near Buck's house. That leaves one place: the theatre. I should check it out.)"
        },
        [51003111] = {
          ContentEN = "(A young Charon boy huddles near the ticket booth, shivering in the cold. He calls out to passersby, trying to sell tickets, posters, beer, and popcorn.)",
          DialogueId = 51003111,
          GUID = "7FAE51E6",
          NextDialogue = 51003112,
          Subtitle = "(A young Charon boy huddles near the ticket booth, shivering in the cold. He calls out to passersby, trying to sell tickets, posters, beer, and popcorn.)"
        },
        [51003112] = {
