          NextDialogue = 51003304,
          SpeakNpcId = 100001,
          Subtitle = "Hello."
        },
        [51003304] = {
          ContentEN = "Greetings, my dear patron! Did you enjoy the play? You must be hungry after sitting through the show for three hours! Would you like some snacks and drinks?",
