          GUID = "7FAE71E4",
          NextDialogue = 51003307,
          SpeakNpcId = 100001,
          Subtitle = "Okay, let's see what you've got."
        },
        [51003307] = {
          ContentEN = "A special edition poster signed by Vitti, Tales of Icelake souvenir albums, glacial meltwater, theatre-themed popcorn... and refreshing beer!",
          DialogueId = 51003307,
          GUID = "7FAE720E",
          NextDialogue = 51003308,
          SpeakNpcId = 700080,
          Subtitle = "A special edition poster signed by Vitti, Tales of Icelake souvenir albums, glacial meltwater, theatre-themed popcorn... and refreshing beer!",
          TalkActionId = {
            [1] = "700080:Explain01_Start"
          }
        },
        [51003308] = {
          ContentEN = "Don't you worry! This barely contains any alcohol and won't get you drunk!",
          DialogueId = 51003308,
          GUID = "7FAE7238",
          NextDialogue = 51003309,
          SpeakNpcId = 700080,
          Subtitle = "Don't you worry! This barely contains any alcohol and won't get you drunk!",
          TalkActionId = {
            [1] = "700080:Explain01_End"
          }
        },
        [51003309] = {
          ContentEN = "That's hard to say... Do you happen to know Mr Buck the playwright?",
          DialogueId = 51003309,
          GUID = "7FAE7262",
          NextDialogue = 51003310,
          SpeakNpcId = 100001,
          Subtitle = "That's hard to say... Do you happen to know Mr Buck the playwright?"
        },
        [51003310] = {
          ContentEN = "Of course I do! Mr Buck frequents the theatre and is one of my most cherished patrons! Despite being a noble, he actually respects Charon kids like me. Mr Buck is one fine gentleman!",
          DialogueId = 51003310,
          GUID = "7FAE728C",
          NextDialogue = 51003311,
          SpeakNpcId = 700080,
          Subtitle = "Of course I do! Mr Buck frequents the theatre and is one of my most cherished patrons! Despite being a noble, he actually respects Charon kids like me. Mr Buck is one fine gentleman!",
          TalkActionId = {
            [1] = "700080:Agree"
          }
        },
        [51003311] = {
          ContentEN = "I know people make fun of Mr Buck, but unlike most people, he genuinely deserves respect.",
          DialogueId = 51003311,
          GUID = "7FAE72B6",
          NextDialogue = 51003312,
          SpeakNpcId = 700080,
          Subtitle = "I know people make fun of Mr Buck, but unlike most people, he genuinely deserves respect."
        },
        [51003312] = {
          ContentEN = "That may be true, but I doubt it gives you the right to sneak into his house through the window and pour beer into his milk.",
          DialogueId = 51003312,
          GUID = "7FAE72E0",
          NextDialogue = 51003313,
          SpeakNpcId = 100001,
          Subtitle = "That may be true, but I doubt it gives you the right to sneak into his house through the window and pour beer into his milk."
        },
        [51003313] = {
          ContentEN = "H—How did you know?",
          DialogueId = 51003313,
          GUID = "7FAE730A",
          NextDialogue = 51003321,
          SpeakNpcId = 700080,
          Subtitle = "H—How did you know?",
          TalkActionId = {
            [1] = "700080:Shock_Start"
          }
        },
        [51003314] = {
          ContentEN = "Mr Buck has a habit of writing his works at night. Your actions have delayed his progress for a month, so he hired me to find the mysterious \"Inspiration Stealer\".",
          DialogueId = 51003314,
          GUID = "7FAE7334",
          NextOptions = {
            [1] = 510033141
          },
          SpeakNpcId = 100001,
          Subtitle = "Mr Buck has a habit of writing his works at night. Your actions have delayed his progress for a month, so he hired me to find the mysterious \"Inspiration Stealer\".",
          TalkActionId = {
            [1] = "700080:Shock_End"
          },
          bForbidSkipOptions = true
        },
        [51003315] = {
          ContentEN = "(You formulate a theory but pause before articulating it, needing to organise your thoughts more clearly.)",
          DialogueId = 51003315,
          GUID = "7FAE735E",
          Subtitle = "(You formulate a theory but pause before articulating it, needing to organise your thoughts more clearly.)"
        },
        [51003316] = {
          ContentEN = "Your business income isn't enough to cover your needs through the winter. Mr Buck might not be wealthy, but he is a noble and his house is warm enough. So, you sneaked into Mr Buck's home for the heating.",
          DialogueId = 51003316,
          GUID = "7FAE7388",
          NextDialogue = 51003317,
          SpeakNpcId = 100001,
          Subtitle = "Your business income isn't enough to cover your needs through the winter. Mr Buck might not be wealthy, but he is a noble and his house is warm enough. So, you sneaked into Mr Buck's home for the heating."
        },
        [51003317] = {
          ContentEN = "As for why you chose Mr Buck — even the smallest amount of alcohol makes him doze off. You could then sleep in his house without the fear of freezing to death. Am I right?",
          DialogueId = 51003317,
          GUID = "7FAE73B2",
          NextDialogue = 51003318,
          SpeakNpcId = 100001,
          Subtitle = "As for why you chose Mr Buck — even the smallest amount of alcohol makes him doze off. You could then sleep in his house without the fear of freezing to death. Am I right?"
        },
