        [51003509] = {
          ContentEN = "Last month, I sneaked out to the slums and ran into a mysterious old lady called Belinda in an alleyway!",
          DialogueId = 51003509,
          GUID = "7FAE9332",
          NextDialogue = 51003510,
          SpeakNpcId = 700016,
          Subtitle = "Last month, I sneaked out to the slums and ran into a mysterious old lady called Belinda in an alleyway!"
        },
        [51003510] = {
          ContentEN = "And she's got magic hands — she can braid all sorts of pretty pigtails and dye my nails with fresh flowers! She even told me stories I'd never heard before!",
          DialogueId = 51003510,
          GUID = "7FAE935C",
          NextDialogue = 51003511,
          SpeakNpcId = 700016,
          Subtitle = "And she's got magic hands — she can braid all sorts of pretty pigtails and dye my nails with fresh flowers! She even told me stories I'd never heard before!",
          TalkActionId = {
            [1] = "700016:Confident_End"
          }
        },
        [51003511] = {
          ContentEN = "Ms Belinda never nagged at me nor treated me like a child. Though it was the first time I met her, she felt like my own granny when she held me in her arms...",
          DialogueId = 51003511,
          GUID = "7FAE9386",
          NextDialogue = 51003512,
          SpeakNpcId = 700016,
          Subtitle = "Ms Belinda never nagged at me nor treated me like a child. Though it was the first time I met her, she felt like my own granny when she held me in her arms..."
        },
        [51003512] = {
          ContentEN = "That sounds really beautiful. Why do you want to keep it a secret?",
          DialogueId = 51003512,
          GUID = "7FAE93B0",
          NextDialogue = 51003513,
          SpeakNpcId = 100001,
          Subtitle = "That sounds really beautiful. Why do you want to keep it a secret?"
        },
        [51003513] = {
          ContentEN = "Because Ms Belinda has horns... She might get into trouble if I tell my parents, classmates, or teachers about her...",
          DialogueId = 51003513,
          GUID = "7FAE93DA",
          NextDialogue = 51003514,
          SpeakNpcId = 700016,
          Subtitle = "Because Ms Belinda has horns... She might get into trouble if I tell my parents, classmates, or teachers about her...",
          TalkActionId = {
            [1] = "700016:Explain02_Start"
          }
        },
        [51003514] = {
          ContentEN = "We were supposed to meet today. But I can't make it anymore because the school suddenly added this memorial event. If you have the time, could you bring this doll to her?",
          DialogueId = 51003514,
          GUID = "7FAE9404",
          LookAt = {
            [1] = "700016:n(0)"
          },
          NextOptions = {
