        [51003520] = {
          ContentEN = "May our student, Emma, offer the floral tribute...",
          DialogueId = 51003520,
          GUID = "7FAE9500",
          NextDialogue = 51003502,
          SpeakNpcId = 700086,
          Subtitle = "May our student, Emma, offer the floral tribute..."
        },
        [51003601] = {
          Camera = "-59.474121,-281.53418,130.205078,0.000004,0.0,71.19751,35.0,100000.0,false,DoNotOverride,2.8",
          ContentEN = "Thank you, Ms Belinda. I feel a lot better. If this is the wish of Robb, then I'll be brave and live on... for his sake.",
          DialogueId = 51003601,
          GUID = "7FAEA24A",
          NextDialogue = 51003602,
          SpeakNpcId = 700087,
          Subtitle = "Thank you, Ms Belinda. I feel a lot better. If this is the wish of Robb, then I'll be brave and live on... for his sake.",
          TalkActionId = {
            [1] = "700087:Explain02_Start"
          }
        },
        [51003602] = {
          Camera = "-83.495605,207.759766,134.179199,0.000004,-0.199981,-68.802429,35.0,100000.0,false,DoNotOverride,2.8",
          ContentEN = "May you find the strength to leave your sadness behind. We are always with you, kid. Belinda's hut is always open if you need anything.",
          DialogueId = 51003602,
          GUID = "7FAEA274",
          SpeakNpcId = 700081,
          Subtitle = "May you find the strength to leave your sadness behind. We are always with you, kid. Belinda's hut is always open if you need anything.",
          TalkActionId = {
            [1] = "700087:Explain02_End",
            [2] = "700081:Explain01_Start"
          }
        },
        [51003604] = {
          ContentEN = "Greetings. I haven't seen you around before. Have you just arrived at Icelake? Is there anything you seek from this old lady?",
          DialogueId = 51003604,
          GUID = "7FAEA2C8",
          NextOptions = {
            [1] = 510036041
          },
          SpeakNpcId = 700081,
          Subtitle = "Greetings. I haven't seen you around before. Have you just arrived at Icelake? Is there anything you seek from this old lady?",
          TalkActionId = {
            [1] = "700081:Explain01_Start"
          }
        },
        [51003605] = {
          ContentEN = "(The doll, though crudely made, captures Belinda's essence. The old Charon lady's eyes light up with joy as she gently caresses the doll.)",
          DialogueId = 51003605,
          GUID = "7FAEA2F2",
          NextDialogue = 51003606,
          Subtitle = "(The doll, though crudely made, captures Belinda's essence. The old Charon lady's eyes light up with joy as she gently caresses the doll.)",
          TalkActionId = {
            [1] = "700081:Explain01_End"
          }
        },
        [51003606] = {
          ContentEN = "I can feel the plaza's essence in this doll... Ah, my memory eludes me! It's Memorial Week, filled with all sorts of events...",
          DialogueId = 51003606,
          GUID = "7FAEA31C",
          NextDialogue = 51003607,
          SpeakNpcId = 700081,
          Subtitle = "I can feel the plaza's essence in this doll... Ah, my memory eludes me! It's Memorial Week, filled with all sorts of events...",
          TalkActionId = {
            [1] = "700081:Agree"
          }
        },
        [51003607] = {
          ContentEN = "Thank you very much, {性别:young man|young lady}.",
          DialogueId = 51003607,
          GUID = "7FAEA346",
          NextDialogue = 51003608,
          SpeakNpcId = 700081,
          Subtitle = "Thank you very much, {性别:young man|young lady}."
        },
        [51003608] = {
          ContentEN = "(She observes you silently for a long moment.)",
          DialogueId = 51003608,
          GUID = "7FAEA370",
          NextDialogue = 51003609,
          Subtitle = "(She observes you silently for a long moment.)"
        },
        [51003609] = {
          ContentEN = "You seem to be carrying a heavy burden. I smell the ocean's breeze and tides on you, and the lingering warmth in your palm... it is fading...",
          DialogueId = 51003609,
          GUID = "7FAEA39A",
          NextDialogue = 51003610,
          SpeakNpcId = 700081,
          Subtitle = "You seem to be carrying a heavy burden. I smell the ocean's breeze and tides on you, and the lingering warmth in your palm... it is fading...",
          TalkActionId = {
            [1] = "700081:Explain02_Start"
          }
        },
        [51003610] = {
          ContentEN = "Every moment you spend in this city is entwined in confusion and sorrow. You try to hide your pain, keeping your sorrows buried deep away from others...",
          DialogueId = 51003610,
          GUID = "7FAEA3C4",
          NextDialogue = 51003611,
          SpeakNpcId = 700081,
          Subtitle = "Every moment you spend in this city is entwined in confusion and sorrow. You try to hide your pain, keeping your sorrows buried deep away from others...",
          TalkActionId = {
            [1] = "700081:Explain02_End"
          }
        },
        [51003611] = {
          ContentEN = "Pardon me for this intrusion, but have you recently lost someone dear?",
          DialogueId = 51003611,
          GUID = "7FAEA3EE",
          NextOptions = {
            [1] = 510036111,
            [2] = 510036112,
            [3] = 510036113
          },
          SpeakNpcId = 700081,
          Subtitle = "Pardon me for this intrusion, but have you recently lost someone dear?",
          bForbidSkipOptions = true
        },
        [51003612] = {
          ContentEN = "Indeed. It is rare for Charons to reach my age.",
          DialogueId = 51003612,
          GUID = "7FAEA418",
          NextDialogue = 51003615,
          SpeakNpcId = 700081,
          Subtitle = "Indeed. It is rare for Charons to reach my age."
        },
        [51003613] = {
          ContentEN = "Your soul is in pain.",
          DialogueId = 51003613,
          GUID = "7FAEA442",
          NextDialogue = 51003615,
          SpeakNpcId = 700081,
          Subtitle = "Your soul is in pain."
        },
        [51003614] = {
          ContentEN = "You don't have to put on an act. I see the pain you hide.",
          DialogueId = 51003614,
          GUID = "7FAEA46C",
          NextDialogue = 51003615,
          SpeakNpcId = 700081,
          Subtitle = "You don't have to put on an act. I see the pain you hide."
        },
        [51003615] = {
          ContentEN = "Though I'm unsure how to ease your suffering, an old saying might provide some comfort...",
          DialogueId = 51003615,
          GUID = "7FAEA496",
          NextDialogue = 51003616,
          SpeakNpcId = 700081,
          Subtitle = "Though I'm unsure how to ease your suffering, an old saying might provide some comfort..."
        },
        [51003616] = {
          ContentEN = "\"They don their boots to traverse as Fate retracts her spindle. Doubt and uncertainty dost confound, but what is lost may come around.\"",
          DialogueId = 51003616,
          GUID = "7FAEA4C0",
          NextOptions = {
