        [51004905] = {
          ContentEN = "Dr Luna, is it? Did you write this prescription?",
          DialogueId = 51004905,
          GUID = "7FAF783A",
          NextDialogue = 51004906,
          SpeakNpcId = 100001,
          Subtitle = "Dr Luna, is it? Did you write this prescription?"
        },
        [51004906] = {
          ContentEN = "(You present the prescription in your hand and show Luna the dangerous lines.)",
          DialogueId = 51004906,
          GUID = "7FAF7864",
          NextDialogue = 51004907,
          Subtitle = "(You present the prescription in your hand and show Luna the dangerous lines.)"
        },
        [51004907] = {
          ContentEN = "\"Wild Filthoids gorge on our flesh, city lords shear our fleece. The hounds dine on fine white loaves, while lowly Charon sheep chew yellowed grass. We roll and we crawl, we baa and we fawn. The masters laugh, while we bear it all.\"",
          DialogueId = 51004907,
          GUID = "7FAF788E",
          NextDialogue = 51004908,
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          Subtitle = "\"Wild Filthoids gorge on our flesh, city lords shear our fleece. The hounds dine on fine white loaves, while lowly Charon sheep chew yellowed grass. We roll and we crawl, we baa and we fawn. The masters laugh, while we bear it all.\""
        },
        [51004908] = {
          ContentEN = "Ah... Uhm... I...",
          DialogueId = 51004908,
          GUID = "7FAF78B8",
          NextDialogue = 51004909,
          SpeakNpcId = 700010,
          Subtitle = "Ah... Uhm... I...",
          TalkActionId = {
            [1] = "700010:Shock_Start"
          }
        },
        [51004909] = {
