        },
        [51004910] = {
          ContentEN = "(Your words seem to calm Luna down a little.)",
          DialogueId = 51004910,
          GUID = "7FAF790C",
          NextDialogue = 51004912,
          Subtitle = "(Your words seem to calm Luna down a little.)",
