          }
        },
        [51004911] = {
          ContentEN = "(Your actions seem to make her more anxious.)",
          DialogueId = 51004911,
          GUID = "7FAF7936",
          NextDialogue = 51004912,
          Subtitle = "(Your actions seem to make her more anxious.)",
