          GUID = "7FAF9862",
          NextDialogue = 51005102,
          SpeakNpcId = 700115,
          Subtitle = "Ah, it's you, !"
        },
        [51005102] = {
          ContentEN = "I really appreciate what you did for us last time! The money helped the families in the slums get food on the table. They wanted me to thank you for that.",
          DialogueId = 51005102,
          GUID = "7FAF988C",
          NextOptions = {
            [1] = 51005103
          },
          SpeakNpcId = 700115,
          Subtitle = "I really appreciate what you did for us last time! The money helped the families in the slums get food on the table. They wanted me to thank you for that.",
          TalkActionId = {
