          }
        },
        [51005103] = {
          ContentEN = "It's nothing.",
          DialogueId = 51005103,
          GUID = "7FAF98B6",
          NextDialogue = 51005104,
          Subtitle = "It's nothing."
        },
        [51005104] = {
          ContentEN = "It's everything! I haven't met anyone as kind, capable, and polite as you in ages.",
          DialogueId = 51005104,
          GUID = "7FAF98E0",
          NextDialogue = 51005105,
          SpeakNpcId = 700115,
          Subtitle = "It's everything! I haven't met anyone as kind, capable, and polite as you in ages.",
          TalkActionId = {
            [1] = "700115:Talk02_Start"
          }
        },
        [51005105] = {
          ContentEN = "How's life in Icelake, now that you've been here for a while?",
          DialogueId = 51005105,
          GUID = "7FAF990A",
          NextOptions = {
            [1] = 510051051,
            [2] = 510051052,
            [3] = 510051053
          },
          SpeakNpcId = 700115,
          Subtitle = "How's life in Icelake, now that you've been here for a while?",
          TalkActionId = {
            [1] = "700115:Talk02_End"
          },
          bForbidSkipOptions = true
        },
        [51005106] = {
          ContentEN = "Well, even though I agree that life is a journey to the finish line, it would be a shame to miss out on the scenery along the way!",
          DialogueId = 51005106,
          GUID = "7FAF9934",
          NextDialogue = 51005109,
          SpeakNpcId = 700115,
          Subtitle = "Well, even though I agree that life is a journey to the finish line, it would be a shame to miss out on the scenery along the way!",
          TalkActionId = {
            [1] = "700115:Agree"
          }
        },
        [51005107] = {
          ContentEN = "I TOTALLY UNDERSTAND THAT! I felt exactly the same when I first got here! The place has so many strange rules and the people are pretty weird as well!",
          DialogueId = 51005107,
          GUID = "7FAF995E",
          NextDialogue = 51005109,
          SpeakNpcId = 700115,
          Subtitle = "I TOTALLY UNDERSTAND THAT! I felt exactly the same when I first got here! The place has so many strange rules and the people are pretty weird as well!",
          TalkActionId = {
            [1] = "700115:Agree"
          }
        },
        [51005108] = {
