          }
        },
        [51005120] = {
          ContentEN = "The price lies in... their mysterious and interesting backstories! You chose it specifically for that reason, right?",
          DialogueId = 51005120,
          GUID = "7FAF9B80",
          NextDialogue = 51005121,
          SpeakNpcId = 700115,
          Subtitle = "The price lies in... their mysterious and interesting backstories! You chose it specifically for that reason, right?",
          TalkActionId = {
            [1] = "700115:Think_End"
          }
        },
        [51005121] = {
