            [1] = "700147:Explain02_Start"
          }
        },
        [51007142] = {
          ContentEN = "I wanted to go with him and hear more of his endless stories. But I couldn't afford the ticket, so all I could do was watch him board that train and leave.",
          DialogueId = 51007142,
          GUID = "7FB0E73C",
          NextDialogue = 51007143,
          SpeakNpcName = "UI_CMNpc_Name_Jiexi",
          Subtitle = "I wanted to go with him and hear more of his endless stories. But I couldn't afford the ticket, so all I could do was watch him board that train and leave.",
          TalkActionId = {
            [1] = "700147:Explain02_End"
          }
        },
        [51007143] = {
          ContentEN = "(She unfolds another star. The train ticket has yellowed with age. On its back, it reads, \"I want to leave here, to follow your steps.\")",
          DialogueId = 51007143,
          GUID = "7FB0E766",
          NextDialogue = 51007144,
          Subtitle = "(She unfolds another star. The train ticket has yellowed with age. On its back, it reads, \"I want to leave here, to follow your steps.\")"
        },
        [51007144] = {
          ContentEN = "Ha... here it is. This is the ticket from his train — the one bound for the far south, across the great plains of Hyperborea.",
          DialogueId = 51007144,
          GUID = "7FB0E790",
          NextDialogue = 51007145,
          SpeakNpcName = "UI_CMNpc_Name_Jiexi",
          Subtitle = "Ha... here it is. This is the ticket from his train — the one bound for the far south, across the great plains of Hyperborea.",
          TalkActionId = {
            [1] = "700147:Talk02_Start"
          }
        },
        [51007145] = {
          ContentEN = "The ticket seller back then... she felt sorry for me. After the train left, she slipped me an expired, unsold ticket and told me there'd be other trains heading that way.",
          DialogueId = 51007145,
          GUID = "7FB0E7BA",
          NextDialogue = 51007146,
          SpeakNpcName = "UI_CMNpc_Name_Jiexi",
          Subtitle = "The ticket seller back then... she felt sorry for me. After the train left, she slipped me an expired, unsold ticket and told me there'd be other trains heading that way.",
          TalkActionId = {
            [1] = "700147:Talk02_End"
          }
        },
        [51007146] = {
          ContentEN = "But I could never afford the real thing. All I could do was stand there and watch the trains roll out. I learned every step of the process by heart. And when that old ticket seller retired, I took her place.",
          DialogueId = 51007146,
          GUID = "7FB0E7E4",
          NextDialogue = 51006931,
          SpeakNpcName = "UI_CMNpc_Name_Jiexi",
          Subtitle = "But I could never afford the real thing. All I could do was stand there and watch the trains roll out. I learned every step of the process by heart. And when that old ticket seller retired, I took her place.",
          TalkActionId = {
            [1] = "700147:Disagree"
          }
        },
        [51007147] = {
