          DialogueId = 51007831,
          GUID = "7FB15846",
          ImprPlusId = 1002,
          NextDialogue = 51007832
        },
        [51007832] = {
          Content = "这还用说，我建议你精读一下这篇论文——《海伯利亚帝国生物多样性和生态系统保护的伦理之争》。",
          DialogueId = 51007832,
          GUID = "7FB15870",
          NextDialogue = 51007833,
          SpeakNpcId = 700018
        },
        [51007833] = {
          Content = "这篇论文是以红角鹿为典型案例，对环境伦理学和人类中心主义伦理观进行综述——当然，很巧的是，这篇论文的作者正是我。",
          DialogueId = 51007833,
          GUID = "7FB1589A",
          NextDialogue = 51007837,
          SpeakNpcId = 700018
        },
        [51007834] = {
          Content = "您为了红角鹿一直很辛苦，可以休息一阵了。",
          DialogueId = 51007834,
          GUID = "7FB158C4",
          ImprPlusId = 1004,
          NextDialogue = 51007835
        },
        [51007835] = {
          Content = "休息？休息什么？就算那些见钱眼开的臭虫们愿意消停一会儿，红角鹿的生存环境依然受到了不小的破坏。",
          DialogueId = 51007835,
          GUID = "7FB158EE",
          NextDialogue = 51007836,
          SpeakNpcId = 700018
        },
        [51007836] = {
          Content = "我得赶在这段时间里好好磨一磨那群婆婆妈妈的政客，让他们马上围栏保护好栖息地，否则红角鹿还是永无宁日。",
          DialogueId = 51007836,
          GUID = "7FB15918",
          NextDialogue = 51007837,
          SpeakNpcId = 700018
        },
        [51007837] = {
          Content = "唉，我在几十年前就发过誓，要为生物学事业付出我的一切。",
          DialogueId = 51007837,
          GUID = "7FB15942",
          NextDialogue = 51007838,
          SpeakNpcId = 700018
        },
        [51007838] = {
          Content = "我自认做到了，也付出了代价，这代价里包括我的家人、爱人与朋友，哦对，还有所有的积蓄。",
          DialogueId = 51007838,
          GUID = "7FB1596C",
          NextDialogue = 51007839,
          SpeakNpcId = 700018
        },
        [51007839] = {
          Content = "你能想象到吗？每分每秒都聒噪不停的刻薄奚落，只能荒郊破屋里睡觉导致的一身的冻疮，还有曾经真诚支持你的人转身离开的背影。",
          DialogueId = 51007839,
          GUID = "7FB15996",
          NextDialogue = 51007840,
          SpeakNpcId = 700018
        },
        [51007840] = {
          Content = "我得承认，这确实是一场颠沛流离又漫长的旅程。",
          DialogueId = 51007840,
          GUID = "7FB159C0",
          NextDialogue = 51007841,
          SpeakNpcId = 700018
        },
        [51007841] = {
          Content = "（阿尔加尔看向红角鹿的标本，他的眼神变了，像慈爱的父亲，忽然又像委屈的孩子。）",
          DialogueId = 51007841,
          GUID = "7FB159EA",
          NextDialogue = 51007842
        },
        [51007842] = {
          Content = "说实话，我不知道要做什么才能真的挽留这些即将消失的生灵。",
          DialogueId = 51007842,
          GUID = "7FB15A14",
          NextDialogue = 51007843,
          SpeakNpcId = 700018
        },
        [51007843] = {
          Content = "但是，我想我知道要为此尽瘁到何时——",
          DialogueId = 51007843,
          GUID = "7FB15A3E",
          NextDialogue = 51007844,
          SpeakNpcId = 700018
        },
        [51007844] = {
          Content = "直到鹿角上面落满花瓣。",
          DialogueId = 51007844,
          GUID = "7FB15A68",
          SpeakNpcId = 700018
        },
        [51007845] = {
          Content = "我们人类，存续于自然中的意义，究竟是什么？",
          DialogueId = 51007845,
          GUID = "7FB15A92",
          SpeakNpcId = 700018
        },
        [51007901] = {
          ContentEN = "Step right up, folks! Try Mist Aken's very own version of the hottest, coolest new ride — absolutely free! Miss it today, and you'll regret it for life!",
          DialogueId = 51007901,
          GUID = "7FB163C2",
          SpeakNpcId = 700069,
          Subtitle = "Step right up, folks! Try Mist Aken's very own version of the hottest, coolest new ride — absolutely free! Miss it today, and you'll regret it for life!"
        },
        [51007902] = {
          ContentEN = "(As soon as Dutton spots you, he rushes over, practically buzzing with excitement. A thick cloud of perfume — mixed with the damp stink of the sewers — slams into your face, so strong it makes your eyes water.)",
          DialogueId = 51007902,
          GUID = "7FB163EC",
          IsBlack = 1,
          NextDialogue = 51007903,
          Subtitle = "(As soon as Dutton spots you, he rushes over, practically buzzing with excitement. A thick cloud of perfume — mixed with the damp stink of the sewers — slams into your face, so strong it makes your eyes water.)"
        },
        [51007903] = {
          ContentEN = "Ah, my dear friend! You've come at just the right moment! You're exactly the one-hundredth participant! You'll get a free ride — and even a reward after you play! So, what do you say? Want to give it a shot?",
          DialogueId = 51007903,
          GUID = "7FB16416",
          SpeakNpcId = 700069,
          Subtitle = "Ah, my dear friend! You've come at just the right moment! You're exactly the one-hundredth participant! You'll get a free ride — and even a reward after you play! So, what do you say? Want to give it a shot?"
        },
        [51007904] = {
