          GUID = "7FB16440",
          NextOptions = {
            [1] = 51007905,
            [2] = 51007906
          },
          Subtitle = "(You catch a flicker of guilt in Dutton's eyes — clearly, this \"ride\" isn't quite as thrilling as he makes it sound.)"
        },
        [51007905] = {
          ContentEN = "(I have a bad feeling about this... but if the reward's good enough, it might be worth the risk.)",
          DialogueId = 51007905,
          GUID = "7FB1646A",
          ImprPlusId = 1001,
          NextDialogue = 51007907,
          Subtitle = "(I have a bad feeling about this... but if the reward's good enough, it might be worth the risk.)"
        },
        [51007906] = {
          ContentEN = "Free money? Don't mind if I do.",
          DialogueId = 51007906,
          GUID = "7FB16494",
          ImprPlusId = 1005,
          NextDialogue = 51007907,
          Subtitle = "Free money? Don't mind if I do."
        },
        [51007907] = {
          ContentEN = "Now that's the spirit! Come on, this way. Little heads-up: we might run into a Filthoid or two — but I'm sure that's no problem for a Phoxhunter like you!",
          DialogueId = 51007907,
          GUID = "7FB164BE",
          SpeakNpcId = 700069,
          Subtitle = "Now that's the spirit! Come on, this way. Little heads-up: we might run into a Filthoid or two — but I'm sure that's no problem for a Phoxhunter like you!"
        },
        [51007908] = {
          ContentEN = "Are you sure this ride is safe...? We're getting deeper and deeper into the sewers...",
          DialogueId = 51007908,
          GUID = "7FB164E8",
          NextDialogue = 51007909,
          SpeakNpcId = 100001,
          Subtitle = "Are you sure this ride is safe...? We're getting deeper and deeper into the sewers..."
        },
        [51007909] = {
          ContentEN = "Safe? Of course! Ever heard of Luca's Water Slides? You know — those fancy rides where folks slide down pipes from high up and splash into a giant pool, laughing all the way?",
          DialogueId = 51007909,
          GUID = "7FB16512",
          NextDialogue = 51007910,
          SpeakNpcId = 700191,
          Subtitle = "Safe? Of course! Ever heard of Luca's Water Slides? You know — those fancy rides where folks slide down pipes from high up and splash into a giant pool, laughing all the way?"
        },
        [51007910] = {
          ContentEN = "Well, going to Luca costs more than most people here make in a lifetime — but thanks to me, you can have the exact same experience right here in Icelake!",
          DialogueId = 51007910,
          GUID = "7FB1653C",
          NextDialogue = 51007911,
          SpeakNpcId = 700191,
          Subtitle = "Well, going to Luca costs more than most people here make in a lifetime — but thanks to me, you can have the exact same experience right here in Icelake!"
        },
        [51007911] = {
          ContentEN = "Affordable! Exciting! Safe! Fun! Practically tailor-made for folks like us. And look at these pipes! Built solid by the Empire — way sturdier than Luca's cheap plastic stuff!",
          DialogueId = 51007911,
          GUID = "7FB16566",
          NextDialogue = 51007912,
          SpeakNpcId = 700191,
          Subtitle = "Affordable! Exciting! Safe! Fun! Practically tailor-made for folks like us. And look at these pipes! Built solid by the Empire — way sturdier than Luca's cheap plastic stuff!"
        },
        [51007912] = {
          ContentEN = "(As Dutton brags, he slaps a nearby pipe — only for a loose screw to ping off and clatter loudly down the tunnel. He either doesn't notice... or pretends not to, beckoning you towards the entrance.)",
          DialogueId = 51007912,
          GUID = "7FB16590",
          NextOptions = {
            [1] = 51007913
          },
          RestartTag = 51007912,
          Subtitle = "(As Dutton brags, he slaps a nearby pipe — only for a loose screw to ping off and clatter loudly down the tunnel. He either doesn't notice... or pretends not to, beckoning you towards the entrance.)"
        },
        [51007913] = {
          ContentEN = "I'm not quite sure how to ride this... Why don't you go first and show me?",
          DialogueId = 51007913,
          GUID = "7FB165BA",
          ImprCheckId = 1064,
          Subtitle = "I'm not quite sure how to ride this... Why don't you go first and show me?"
        },
        [51007914] = {
          ContentEN = "Ah, no worries! Totally normal to feel a bit jittery your first time. Take your time — when you're ready, come find me!",
          DialogueId = 51007914,
          GUID = "7FB165E4",
          SpeakNpcId = 700191,
          Subtitle = "Ah, no worries! Totally normal to feel a bit jittery your first time. Take your time — when you're ready, come find me!"
        },
        [51007915] = {
          ContentEN = "Alright, alright. I'll show you — but you gotta promise to spread the word for me when you get back to Mist Aken, yeah?",
          DialogueId = 51007915,
          GUID = "7FB1660E",
          NextDialogue = 51007916,
          SpeakNpcId = 700191,
          Subtitle = "Alright, alright. I'll show you — but you gotta promise to spread the word for me when you get back to Mist Aken, yeah?"
        },
        [51007916] = {
          ContentEN = "(With that, Dutton squeezes himself into the pipe. The metal groans and creaks under his weight. Once he's wedged in, he gives the pipe a good smack and shouts back to you.)",
          DialogueId = 51007916,
          GUID = "7FB16638",
          NextDialogue = 51007917,
          Subtitle = "(With that, Dutton squeezes himself into the pipe. The metal groans and creaks under his weight. Once he's wedged in, he gives the pipe a good smack and shouts back to you.)"
        },
        [51007917] = {
          ContentEN = "Tell you what — you're gonna regret not going first! It's spotless in here, and smells nice! Alright, the exit's just up ahead — I'm off! See you at the bottom!",
          DialogueId = 51007917,
          GUID = "7FB16662",
          SpeakNpcId = 700191,
          Subtitle = "Tell you what — you're gonna regret not going first! It's spotless in here, and smells nice! Alright, the exit's just up ahead — I'm off! See you at the bottom!"
        },
        [51007918] = {
