        [51008018] = {
          ContentEN = "(Scattered debris litters the ground — pebbles from the lake, snapped branches, and splinters of masonry. Judging by the mess, a fight broke out here.)",
          DialogueId = 51008018,
          GUID = "7FB176F4",
          NextDialogue = 51008019,
          Subtitle = "(Scattered debris litters the ground — pebbles from the lake, snapped branches, and splinters of masonry. Judging by the mess, a fight broke out here.)"
        },
        [51008019] = {
          ContentEN = "(Among the rubble, you spot scraps of torn fabric and tufts of stuffing... the same kind as on that man's threadbare clothes.)",
          DialogueId = 51008019,
          GUID = "7FB1771E",
          Subtitle = "(Among the rubble, you spot scraps of torn fabric and tufts of stuffing... the same kind as on that man's threadbare clothes.)"
        },
        [51008020] = {
          ContentEN = "(Sifting through the wreckage, you uncover another small Phoxene shard — stained dark with blood.)",
          DialogueId = 51008020,
          GUID = "7FB17748",
          Subtitle = "(Sifting through the wreckage, you uncover another small Phoxene shard — stained dark with blood.)"
        },
        [51008021] = {
          ContentEN = "(The footprints are a tangled mess, crisscrossing wildly through the dirt — but there's something telling. No claw marks. No beast tracks. Just human prints.)",
          DialogueId = 51008021,
          GUID = "7FB17772",
          Subtitle = "(The footprints are a tangled mess, crisscrossing wildly through the dirt — but there's something telling. No claw marks. No beast tracks. Just human prints.)"
        },
        [51008022] = {
          ContentEN = "(A long drag mark scores the earth, trailing off into the distance — as if something heavy had been hauled away.)",
          DialogueId = 51008022,
          GUID = "7FB1779C",
          NextDialogue = 51008023,
          Subtitle = "(A long drag mark scores the earth, trailing off into the distance — as if something heavy had been hauled away.)"
        },
        [51008023] = {
          ContentEN = "Hm... it's coming together now. The blood on that Phoxene — it came from:",
          DialogueId = 51008023,
          GUID = "7FB177C6",
          NextOptions = {
            [1] = 51008024,
            [2] = 51008026,
            [3] = 51008028
          },
          SpeakNpcId = 100001,
          Subtitle = "Hm... it's coming together now. The blood on that Phoxene — it came from:"
        },
        [51008024] = {
          ContentEN = "Humans",
          DialogueId = 51008024,
          GUID = "7FB177F0",
          NextDialogue = 51008025,
          Subtitle = "Humans"
        },
        [51008025] = {
          ContentEN = "(That's right. No beast tracks. No Filthoid claws. Just humans.)",
          DialogueId = 51008025,
          GUID = "7FB1781A",
          NextDialogue = 51008030,
          Subtitle = "(That's right. No beast tracks. No Filthoid claws. Just humans.)"
        },
        [51008026] = {
          ContentEN = "Beasts",
          DialogueId = 51008026,
          GUID = "7FB17844",
          NextDialogue = 51008027,
          Subtitle = "Beasts"
        },
        [51008027] = {
          ContentEN = "(No... if beasts had passed through, there'd be pawprints or claw marks.)",
          DialogueId = 51008027,
          GUID = "7FB1786E",
          NextDialogue = 51008030,
          Subtitle = "(No... if beasts had passed through, there'd be pawprints or claw marks.)"
        },
        [51008028] = {
          ContentEN = "Filthoids",
          DialogueId = 51008028,
          GUID = "7FB17898",
          NextDialogue = 51008029,
          Subtitle = "Filthoids"
        },
        [51008029] = {
          ContentEN = "(No... if Filthoids had been here, there'd be gouges and claw marks all over.)",
          DialogueId = 51008029,
          GUID = "7FB178C2",
          NextDialogue = 51008030,
          Subtitle = "(No... if Filthoids had been here, there'd be gouges and claw marks all over.)"
        },
        [51008030] = {
          ContentEN = "Looks like there was a fight here... probably over that sack of Phoxene. Now then — what's my next move?",
          DialogueId = 51008030,
          GUID = "7FB178EC",
          SpeakNpcId = 100001,
          Subtitle = "Looks like there was a fight here... probably over that sack of Phoxene. Now then — what's my next move?",
          TalkOptions = {
            [1] = 51008031,
            [2] = 51008032
          }
        },
        [51008031] = {
          ContentEN = "That Phoxene was taken in blood anyway. Why shouldn't I claim it for myself?",
          DialogueId = 51008031,
          GUID = "7FB17916",
          ImprPlusId = 1005,
          Subtitle = "That Phoxene was taken in blood anyway. Why shouldn't I claim it for myself?"
        },
        [51008032] = {
          ContentEN = "That guy did some really bad things. Better report him to the Escort.",
          DialogueId = 51008032,
          GUID = "7FB17940",
          ImprPlusId = 1002,
          Subtitle = "That guy did some really bad things. Better report him to the Escort."
        },
        [51008033] = {
          ContentEN = "You've done something you're not proud of... haven't you?",
          DialogueId = 51008033,
          GUID = "7FB1796A",
          NextDialogue = 51008034,
          SpeakNpcId = 100001,
          Subtitle = "You've done something you're not proud of... haven't you?"
        },
        [51008034] = {
          ContentEN = "This little Phoxene nugget — maybe you don't remember it, but it remembers you. And so does the one whose blood is on it.",
          DialogueId = 51008034,
          GUID = "7FB17994",
          NextDialogue = 51008035,
          SpeakNpcId = 100001,
          Subtitle = "This little Phoxene nugget — maybe you don't remember it, but it remembers you. And so does the one whose blood is on it."
        },
        [51008035] = {
          ContentEN = "I... I don't know what you're talking about!",
          DialogueId = 51008035,
          GUID = "7FB179BE",
          NextDialogue = 51008036,
          SpeakNpcId = 700113,
          Subtitle = "I... I don't know what you're talking about!"
        },
        [51008036] = {
          ContentEN = "I don't need your help anymore — just leave me alone!",
          DialogueId = 51008036,
          GUID = "7FB179E8",
          NextDialogue = 51008037,
          SpeakNpcId = 700113,
          Subtitle = "I don't need your help anymore — just leave me alone!"
        },
        [51008037] = {
          ContentEN = "Easy. The Escort's on their way. I could make them turn around — but that'll cost you. Let's say... one sack of Phoxene.",
          DialogueId = 51008037,
          GUID = "7FB17A12",
          NextDialogue = 51008038,
          SpeakNpcId = 100001,
          Subtitle = "Easy. The Escort's on their way. I could make them turn around — but that'll cost you. Let's say... one sack of Phoxene."
        },
        [51008038] = {
          ContentEN = "You—! I...",
          DialogueId = 51008038,
          GUID = "7FB17A3C",
          NextDialogue = 51008039,
          SpeakNpcId = 700113,
          Subtitle = "You—! I..."
        },
        [51008039] = {
          ContentEN = "Up to you. Stay and greet them if you want.",
          DialogueId = 51008039,
          GUID = "7FB17A66",
          NextDialogue = 51008040,
          SpeakNpcId = 100001,
          Subtitle = "Up to you. Stay and greet them if you want."
        },
        [51008040] = {
          ContentEN = "I'm fine either way. Take your time and think it over — oh wait, I forgot the Escort aren't exactly known for their patience.",
          DialogueId = 51008040,
          GUID = "7FB17A90",
          NextDialogue = 51008041,
          SpeakNpcId = 100001,
          Subtitle = "I'm fine either way. Take your time and think it over — oh wait, I forgot the Escort aren't exactly known for their patience."
        },
        [51008041] = {
          ContentEN = "Fine! You want it? Take it! All yours!",
          DialogueId = 51008041,
          GUID = "7FB17ABA",
          NextDialogue = 51008042,
          SpeakNpcId = 700113,
          Subtitle = "Fine! You want it? Take it! All yours!"
        },
        [51008042] = {
          ContentEN = "Take this bloody sack of Phoxene... it's all because of this damn thing! If we hadn't stumbled across it... my mates would still be alive!",
          DialogueId = 51008042,
          GUID = "7FB17AE4",
          NextDialogue = 51008043,
          SpeakNpcId = 700113,
          Subtitle = "Take this bloody sack of Phoxene... it's all because of this damn thing! If we hadn't stumbled across it... my mates would still be alive!"
        },
        [51008043] = {
          ContentEN = "If they were, we'd be packing up by now... hell, we'd probably be down at the tavern already, raising a full pint of malt to a good day's haul...",
          DialogueId = 51008043,
          GUID = "7FB17B0E",
          NextDialogue = 51008044,
          SpeakNpcId = 700113,
          Subtitle = "If they were, we'd be packing up by now... hell, we'd probably be down at the tavern already, raising a full pint of malt to a good day's haul..."
        },
        [51008044] = {
          ContentEN = "We'd drink 'til we sloshed. Shoot the breeze 'til the stars went out. And tomorrow... we'd—",
          DialogueId = 51008044,
          GUID = "7FB17B38",
          NextDialogue = 51008045,
          SpeakNpcId = 700113,
          Subtitle = "We'd drink 'til we sloshed. Shoot the breeze 'til the stars went out. And tomorrow... we'd—"
        },
        [51008045] = {
          ContentEN = "No... I... I can't give it to you!",
          DialogueId = 51008045,
          GUID = "7FB17B62",
          SpeakNpcId = 700113,
          Subtitle = "No... I... I can't give it to you!"
        },
        [51008046] = {
          Camera = "-607.952148,-441.947266,565.15332,0.000023,-34.799801,23.996548,35.0,100000.0,false,DoNotOverride,2.8",
          ContentEN = "You tricked me! There's no Escort coming — you just wanted the Phoxene for yourself!",
          DialogueId = 51008046,
          GUID = "7FB17B8C",
          NextDialogue = 51008047,
          SpeakNpcId = 700113,
          Subtitle = "You tricked me! There's no Escort coming — you just wanted the Phoxene for yourself!"
        },
        [51008047] = {
          ContentEN = "You killed your mates for these shiny rocks, didn't you? Same way you just tried to kill me?",
          DialogueId = 51008047,
          GUID = "7FB17BB6",
          NextDialogue = 51008048,
          SpeakNpcId = 100001,
          Subtitle = "You killed your mates for these shiny rocks, didn't you? Same way you just tried to kill me?"
        },
        [51008048] = {
          ContentEN = "They attacked me first... I... I was defending myself!",
          DialogueId = 51008048,
          GUID = "7FB17BE0",
          NextDialogue = 51008049,
          SpeakNpcId = 700113,
          Subtitle = "They attacked me first... I... I was defending myself!"
        },
        [51008049] = {
          ContentEN = "And you — don't act high and mighty! You're after the Phoxene too, aren't you? What makes you any different from me!?",
          DialogueId = 51008049,
          GUID = "7FB17C0A",
          NextOptions = {
            [1] = 51008050,
            [2] = 51008051
          },
          SpeakNpcId = 700113,
          Subtitle = "And you — don't act high and mighty! You're after the Phoxene too, aren't you? What makes you any different from me!?"
        },
        [51008050] = {
          ContentEN = "Grown men pay for their mistakes. Think of this sack of Phoxene as your price.",
          DialogueId = 51008050,
          GUID = "7FB17C34",
          ImprPlusId = 1001,
          NextDialogue = 51008052,
          Subtitle = "Grown men pay for their mistakes. Think of this sack of Phoxene as your price."
        },
        [51008051] = {
          ContentEN = "I'm no saint — and you're no better than me. But at least I'm letting you live. Now get lost.",
          DialogueId = 51008051,
          GUID = "7FB17C5E",
          ImprPlusId = 1005,
          NextDialogue = 51008052,
          Subtitle = "I'm no saint — and you're no better than me. But at least I'm letting you live. Now get lost."
        },
        [51008052] = {
          ContentEN = "(The bloodstained Phoxene sits heavy in your hand. Heavier than it should be — almost as if it might twist itself into a gaping maw, waiting to devour the next \"Larry\" who gets too close.)",
          DialogueId = 51008052,
          GUID = "7FB17C88",
          IsBlack = 1,
          Subtitle = "(The bloodstained Phoxene sits heavy in your hand. Heavier than it should be — almost as if it might twist itself into a gaping maw, waiting to devour the next \"Larry\" who gets too close.)"
        },
        [51008053] = {
          ContentEN = "Look down and search",
          DialogueId = 51008053,
          GUID = "7FB17CB2",
          ImprCheckId = 1070,
          Subtitle = "Look down and search"
        },
        [51008054] = {
          Content = "（清理掉这群碍眼的秽兽后，附近的地面上某些似乎被掩埋过的痕迹暴露了出来。你决定去检查一下这些新的线索。）",
          DialogueId = 51008054,
          GUID = "7FB17CDC"
        },
