        [51009116] = {
          Camera = "-47.538391,-157.203125,145.923813,0.00021,-15.601462,76.384178,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentEN = "A weapon is a young adventurer's most faithful companion. You should never be caught unprepared.",
          DialogueId = 51009116,
          FacialId = {
            [1] = "230002:Happy02"
          },
          GUID = "7FB22B18",
          NextDialogue = 51009117,
          SpeakNpcId = 230002,
          Subtitle = "A weapon is a young adventurer's most faithful companion. You should never be caught unprepared.",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          }
        },
        [51009117] = {
          ContentEN = "I've seen more youngsters like you than I can count — some faded into quiet obscurity, others became legends of Atlasia. But they all began the same: curious, reckless, full of fire and far too little caution.",
          DialogueId = 51009117,
          FacialId = {
            [1] = "230002:Ahaha02"
          },
          GUID = "7FB22B42",
          NextDialogue = 51009118,
          SpeakNpcId = 230002,
          Subtitle = "I've seen more youngsters like you than I can count — some faded into quiet obscurity, others became legends of Atlasia. But they all began the same: curious, reckless, full of fire and far too little caution."
        },
        [51009118] = {
          ContentEN = "That's why a dependable weapon matters — it tempers the heat of youth and steadies hands not yet tested by time.",
          DialogueId = 51009118,
          FacialId = {
            [1] = "230002:Satisfy01"
          },
          GUID = "7FB22B6C",
          NextDialogue = 51009119,
          SpeakNpcId = 230002,
          Subtitle = "That's why a dependable weapon matters — it tempers the heat of youth and steadies hands not yet tested by time."
        },
