        },
        [51009206] = {
          ContentEN = "Tell me — have you noticed? Modern weaponry is obsessed with damage output and cost-efficiency, yet utterly blind to beauty!",
          DialogueId = 51009206,
          GUID = "7FB239DC",
          NextDialogue = 51009207,
          SpeakNpcId = 230003,
          Subtitle = "Tell me — have you noticed? Modern weaponry is obsessed with damage output and cost-efficiency, yet utterly blind to beauty!",
          TalkActionId = {
            [1] = "230003:Explain01_End"
          }
        },
        [51009207] = {
