        [51009343] = {
          ContentEN = "(The woman falls silent, gazing out the window, her eyes filled with a gentle nostalgia.)",
          DialogueId = 51009343,
          GUID = "7FB25056",
          NextDialogue = 51009344,
          Subtitle = "(The woman falls silent, gazing out the window, her eyes filled with a gentle nostalgia.)"
        },
        [51009344] = {
          ContentEN = "I first met him outside the city. We were the same age, and our personalities just clicked, so we became fast friends.",
          DialogueId = 51009344,
          GUID = "7FB25080",
          NextDialogue = 51009345,
          SpeakNpcId = 700247,
          Subtitle = "I first met him outside the city. We were the same age, and our personalities just clicked, so we became fast friends."
        },
        [51009345] = {
          ContentEN = "He told me he was a \"faerie\" from the sky... Hehe, truthfully, I knew all along he was Charon. But every time I saw him trying so hard to keep up the story, I couldn't bear to spoil it for him.",
          DialogueId = 51009345,
          GUID = "7FB250AA",
          NextDialogue = 51009346,
          SpeakNpcId = 700247,
          Subtitle = "He told me he was a \"faerie\" from the sky... Hehe, truthfully, I knew all along he was Charon. But every time I saw him trying so hard to keep up the story, I couldn't bear to spoil it for him."
        },
        [51009346] = {
          ContentEN = "Besides, he really was just like a faerie from the stories — he knew so many things I didn't, and always had endless fascinating tales to tell.",
          DialogueId = 51009346,
          GUID = "7FB250D4",
          NextOptions = {
            [1] = 51009347,
            [2] = 51009349
          },
          SpeakNpcId = 700247,
          Subtitle = "Besides, he really was just like a faerie from the stories — he knew so many things I didn't, and always had endless fascinating tales to tell."
        },
        [51009347] = {
          ContentEN = "Sounds like a wonderful friend.",
          DialogueId = 51009347,
          GUID = "7FB250FE",
          NextDialogue = 51009348,
          Subtitle = "Sounds like a wonderful friend."
        },
        [51009348] = {
