          NextDialogue = 51009351,
          SpeakNpcId = 700247,
          Subtitle = "Yes! He's the best friend ever."
        },
        [51009349] = {
          ContentEN = "So he was playing the part of a faerie his whole life?",
          DialogueId = 51009349,
          GUID = "7FB25152",
          NextDialogue = 51009350,
          Subtitle = "So he was playing the part of a faerie his whole life?"
        },
        [51009350] = {
          ContentEN = "Sounds a bit childish when you put it like that, doesn't it?",
          DialogueId = 51009350,
          GUID = "7FB2517C",
          NextDialogue = 51009351,
          SpeakNpcId = 700247,
          Subtitle = "Sounds a bit childish when you put it like that, doesn't it?"
        },
        [51009351] = {
          ContentEN = "It always bothered me a little... wondering how we would finally talk about it, once we grew up and passed the age where believing in fairy tales came naturally.",
          DialogueId = 51009351,
          GUID = "7FB251A6",
          NextDialogue = 51009352,
          SpeakNpcId = 700247,
          Subtitle = "It always bothered me a little... wondering how we would finally talk about it, once we grew up and passed the age where believing in fairy tales came naturally."
        },
        [51009352] = {
          ContentEN = "Whether I brought it up or he did, just imagining it felt so awkward...",
          DialogueId = 51009352,
          GUID = "7FB251D0",
          NextDialogue = 51009353,
          SpeakNpcId = 700247,
          Subtitle = "Whether I brought it up or he did, just imagining it felt so awkward..."
        },
        [51009353] = {
          ContentEN = "But in the end, we never reached that point. He left before we came of age.",
