          GUID = "7FB2534A",
          NextDialogue = 51009362,
          SpeakNpcId = 700247,
          Subtitle = "Well, that's what I thought. After all, he left just before he turned eighteen."
        },
        [51009362] = {
          ContentEN = "He had foreseen his own fate. The last time we met, he told me he was returning to his homeland in the sky and wouldn't be able to visit me anymore.",
          DialogueId = 51009362,
          GUID = "7FB25374",
          NextDialogue = 51009363,
          SpeakNpcId = 700247,
          Subtitle = "He had foreseen his own fate. The last time we met, he told me he was returning to his homeland in the sky and wouldn't be able to visit me anymore."
        },
        [51009363] = {
          ContentEN = "It was the most poorly told lie of his life... His eyes were already brimming with tears, yet he forced a smile and said to me in the cheeriest voice—",
          DialogueId = 51009363,
          GUID = "7FB2539E",
          NextDialogue = 51009364,
          SpeakNpcId = 700247,
          Subtitle = "It was the most poorly told lie of his life... His eyes were already brimming with tears, yet he forced a smile and said to me in the cheeriest voice—"
        },
        [51009364] = {
          ContentEN = "\"Please don't be sad. Even though I can't come to see you anymore, I'll be watching over you from above the clouds, always...\"",
          DialogueId = 51009364,
          GUID = "7FB253C8",
          NextDialogue = 51009365,
          SpeakNpcId = 700247,
          Subtitle = "\"Please don't be sad. Even though I can't come to see you anymore, I'll be watching over you from above the clouds, always...\""
        },
