        [51009662] = {
          Camera = "201.632812,149.822754,39.556641,0.000044,-1.60086,173.405228,35.0,100000.0,false,DoNotOverride,2.8",
          ContentEN = "Ah... would you humour an old man for a moment? I've a few old stories to tell.",
          DialogueId = 51009662,
          GUID = "7FB284AC",
          NextDialogue = 51009663,
          SpeakNpcId = 700301,
          Subtitle = "Ah... would you humour an old man for a moment? I've a few old stories to tell.",
          TalkActionId = {
