        },
        [51009663] = {
          Camera = "-160.715332,330.500977,58.830566,0.00003,-6.800997,-43.798355,35.0,100000.0,false,DoNotOverride,2.8",
          ContentEN = "I'd love to. But let's head back first, alright? Lars must be worried sick.",
          DialogueId = 51009663,
