          ContentEN = "Uncle Donat — you're back!",
          DialogueId = 51009665,
          GUID = "7FB2852A",
          NextDialogue = 51009666,
          SpeakNpcId = 700303,
          Subtitle = "Uncle Donat — you're back!",
