          GUID = "7FB28554",
          NextDialogue = 51009667,
          SpeakNpcId = 700301,
          Subtitle = "Sorry, lad... made you worry again — *cough*",
          TalkActionId = {
            [1] = "700301:Explain02_Start"
          }
        },
        [51009667] = {
          Camera = "489.740967,-276.444336,121.044434,0.000018,-7.20046,148.799316,35.0,100000.0,false,DoNotOverride,2.8",
          ContentEN = "You're coughing again! Come on — let me take you to a doctor.",
          DialogueId = 51009667,
          GUID = "7FB2857E",
          NextDialogue = 51009668,
          SpeakNpcId = 700303,
          Subtitle = "You're coughing again! Come on — let me take you to a doctor.",
          TalkActionId = {
            [1] = "700303:Talk02_Start"
          }
        },
        [51009668] = {
          Camera = "12.182617,54.006836,128.048828,0.000051,-5.600557,-66.002014,30.0,100000.0,false,DoNotOverride,2.8",
          ContentEN = "No, no need... This is what I deserve. No cure's going to fix it.",
          DialogueId = 51009668,
          GUID = "7FB285A8",
          NextDialogue = 51009669,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0036_story_renweidaozu\"}}",
          SpeakNpcId = 700301,
          Subtitle = "No, no need... This is what I deserve. No cure's going to fix it.",
          TalkActionId = {
            [1] = "700303:Talk02_End"
          }
        },
        [51009669] = {
          Camera = "489.740967,-276.444336,121.044434,0.000018,-7.20046,148.799316,35.0,100000.0,false,DoNotOverride,2.8",
          ContentEN = "Don't say that, Uncle Donat...",
          DialogueId = 51009669,
          GUID = "7FB285D2",
          NextDialogue = 51009670,
          SpeakNpcId = 700303,
          Subtitle = "Don't say that, Uncle Donat...",
          TalkActionId = {
            [1] = "700303:Confident_Start"
          }
        },
        [51009670] = {
          ContentEN = "Remember that winter, when I had to sleep next to the factory vents just to stay warm? You were freezing too — and still gave me the only padded coat you had.",
          DialogueId = 51009670,
          GUID = "7FB285FC",
          NextDialogue = 51009671,
          SpeakNpcId = 700303,
          Subtitle = "Remember that winter, when I had to sleep next to the factory vents just to stay warm? You were freezing too — and still gave me the only padded coat you had."
        },
        [51009671] = {
          ContentEN = "Everyone round here knows what a good person you are! So why do you keep saying you deserve this? It's just not true!",
          DialogueId = 51009671,
          GUID = "7FB28626",
          LookAt = {
            [1] = "100001:n(700301)"
          },
          NextDialogue = 51009672,
          SpeakNpcId = 700303,
          Subtitle = "Everyone round here knows what a good person you are! So why do you keep saying you deserve this? It's just not true!"
        },
        [51009672] = {
          Camera = "-115.218262,-202.711914,123.809082,0.000057,-5.200553,24.798326,30.0,100000.0,false,DoNotOverride,2.8",
          ContentEN = "...Does this have to do with the \"old stories\" you wanted to tell?",
          DialogueId = 51009672,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB28650",
          LookAt = {
            [1] = "700301:n(100001)"
          },
          NextDialogue = 51009673,
          SpeakNpcId = 100001,
          Subtitle = "...Does this have to do with the \"old stories\" you wanted to tell?",
          TalkActionId = {
            [1] = "100001:Think_Start",
            [2] = "700301:Explain02_End"
          }
        },
        [51009673] = {
          Camera = "78.660156,141.991211,123.371582,0.000067,-4.400513,-84.600342,30.0,100000.0,false,DoNotOverride,2.8",
          ContentEN = "Mm. Sixteen years back...",
          DialogueId = 51009673,
          FacialId = {
            [1] = "700301:CM_Sad01"
          },
          GUID = "7FB2867A",
          NextDialogue = 51009674,
          SpeakNpcId = 700301,
          Subtitle = "Mm. Sixteen years back...",
          TalkActionId = {
            [1] = "700301:Talk02_Start",
            [2] = "700303:Confident_End"
          }
        },
        [51009674] = {
          Camera = "51.153076,68.407227,128.048828,0.000057,-5.000518,-77.201683,30.0,100000.0,false,DoNotOverride,2.8",
          ContentEN = "Like every other dreary chapter of my life, the years I spent as a miner weren't good, but they weren't the worst either. Long days of grind, just enough to wear you down, just enough to put bread on the table.",
          DialogueId = 51009674,
          GUID = "7FB286A4",
          NextDialogue = 51009675,
          SpeakNpcId = 700301,
          Subtitle = "Like every other dreary chapter of my life, the years I spent as a miner weren't good, but they weren't the worst either. Long days of grind, just enough to wear you down, just enough to put bread on the table."
        },
        [51009675] = {
          ContentEN = "Looking back... even though the bigwigs never treated us fairly, those might've been the least troubled days I ever had...",
          DialogueId = 51009675,
          GUID = "7FB286CE",
          NextDialogue = 51009676,
          SpeakNpcId = 700301,
          Subtitle = "Looking back... even though the bigwigs never treated us fairly, those might've been the least troubled days I ever had..."
        },
        [51009676] = {
          Camera = "-21.725342,235.385742,212.564453,0.000078,-22.799852,-68.394066,20.0,100000.0,false,DoNotOverride,2.8",
          ContentEN = "But my friend Sig... he wasn't so lucky. His little sister, Violet — the only family he had — fell ill. Only eighteen, that girl...",
          DialogueId = 51009676,
          GUID = "7FB286F8",
          NextDialogue = 51009677,
          SpeakNpcId = 700301,
          Subtitle = "But my friend Sig... he wasn't so lucky. His little sister, Violet — the only family he had — fell ill. Only eighteen, that girl..."
        },
        [51009677] = {
          ContentEN = "And just when you think things can't get worse... they usually do.",
          DialogueId = 51009677,
          GUID = "7FB28722",
          NextDialogue = 51009678,
          SpeakNpcId = 700301,
          Subtitle = "And just when you think things can't get worse... they usually do."
        },
        [51009678] = {
          ContentEN = "Phoxene from Glevum Pit grew scarcer by the day — and so did our wages. White bread became dust-stained bread... then even that was bulked with husks and sawdust.",
          DialogueId = 51009678,
          GUID = "7FB2874C",
          NextDialogue = 51009679,
          SpeakNpcId = 700301,
          Subtitle = "Phoxene from Glevum Pit grew scarcer by the day — and so did our wages. White bread became dust-stained bread... then even that was bulked with husks and sawdust."
        },
        [51009679] = {
          ContentEN = "For Sig — barely making ends meet — Violet falling ill was like hearing her death sentence out loud.",
          DialogueId = 51009679,
          GUID = "7FB28776",
          NextDialogue = 51009680,
          SpeakNpcId = 700301,
          Subtitle = "For Sig — barely making ends meet — Violet falling ill was like hearing her death sentence out loud.",
          TalkActionId = {
            [1] = "700301:Talk02_End"
          }
        },
        [51009680] = {
          ContentEN = "I still remember that dawn. Sig scrounged up cheap liquor from the lads, and we sat on the stone outside the pit, knocking them back one bottle at a time.",
          DialogueId = 51009680,
          GUID = "7FB287A0",
          NextDialogue = 51009681,
          SpeakNpcId = 700301,
          Subtitle = "I still remember that dawn. Sig scrounged up cheap liquor from the lads, and we sat on the stone outside the pit, knocking them back one bottle at a time.",
          TalkActionId = {
            [1] = "700301:Talk01_Start"
          }
        },
        [51009681] = {
          ContentEN = "He cried like a child, rambling on about how the two of them had always relied on each other. One moment he was softly humming her favourite songs... the next, muttering curses at Fabrice Ruthford through gritted teeth.",
          DialogueId = 51009681,
          GUID = "7FB287CA",
          NextDialogue = 51009682,
          SpeakNpcId = 700301,
          Subtitle = "He cried like a child, rambling on about how the two of them had always relied on each other. One moment he was softly humming her favourite songs... the next, muttering curses at Fabrice Ruthford through gritted teeth."
        },
        [51009682] = {
          Camera = "-115.218262,-202.711914,123.809082,0.000057,-5.200553,24.798326,30.0,100000.0,false,DoNotOverride,2.8",
          ContentEN = "Who's that?",
          DialogueId = 51009682,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB287F4",
          NextDialogue = 51009683,
          SpeakNpcId = 100001,
          Subtitle = "Who's that?",
          TalkActionId = {
            [1] = "100001:Talk03_Start",
            [2] = "700301:Talk01_End"
          }
        },
        [51009683] = {
          Camera = "78.660156,141.991211,123.371582,0.000067,-4.400513,-84.600342,30.0,100000.0,false,DoNotOverride,2.8",
          ContentEN = "An officer at The Aeolipile, the one who ran Glevum Pit back then.",
          DialogueId = 51009683,
          GUID = "7FB2881E",
          NextDialogue = 51009684,
          SpeakNpcId = 700301,
          Subtitle = "An officer at The Aeolipile, the one who ran Glevum Pit back then.",
          TalkActionId = {
            [1] = "700301:Talk02_Start"
          }
        },
        [51009684] = {
          ContentEN = "I remember clapping him on the shoulder and saying, \"What good does cursing him do? We're just nobodies. If you've got guts, why not grab the man himself and get the money straight from his pocket?\"",
          DialogueId = 51009684,
          GUID = "7FB28848",
          NextDialogue = 51009685,
          SpeakNpcId = 700301,
          Subtitle = "I remember clapping him on the shoulder and saying, \"What good does cursing him do? We're just nobodies. If you've got guts, why not grab the man himself and get the money straight from his pocket?\"",
          TalkActionId = {
            [1] = "700301:Talk02_End"
          }
        },
        [51009685] = {
          ContentEN = "...Sixteen years on, I still ask myself — if I hadn't been drunk and mouthing off like that, would any of this have happened?",
          DialogueId = 51009685,
          GUID = "7FB28872",
          NextDialogue = 51009686,
          SpeakNpcId = 700301,
          Subtitle = "...Sixteen years on, I still ask myself — if I hadn't been drunk and mouthing off like that, would any of this have happened?",
          TalkActionId = {
            [1] = "700301:Explain02_Start"
          }
        },
        [51009686] = {
          Camera = "489.740967,-276.444336,121.044434,0.000018,-7.20046,148.799316,35.0,100000.0,false,DoNotOverride,2.8",
          ContentEN = "You mean... Sig actually did it?",
          DialogueId = 51009686,
          GUID = "7FB2889C",
          NextDialogue = 51009687,
          SpeakNpcId = 700303,
          Subtitle = "You mean... Sig actually did it?",
          TalkActionId = {
            [1] = "700301:Explain02_End"
          },
          TurnTo = {
            [1] = "700301:n(700303)"
          }
        },
        [51009687] = {
          Camera = "12.182617,54.006836,128.048828,0.000051,-5.600557,-66.002014,30.0,100000.0,false,DoNotOverride,2.8",
          ContentEN = "Yes. One day, he quit the mine without a word. When I went to his house to check on him, both he and Violet were gone.",
          DialogueId = 51009687,
          GUID = "7FB288C6",
          NextDialogue = 51009688,
          SpeakNpcId = 700301,
          Subtitle = "Yes. One day, he quit the mine without a word. When I went to his house to check on him, both he and Violet were gone.",
          TalkActionId = {
            [1] = "700301:Agree"
          }
        },
        [51009688] = {
          ContentEN = "I thought he'd taken her elsewhere for treatment... until a week later, I received a letter from Violet.",
          DialogueId = 51009688,
          GUID = "7FB288F0",
          NextDialogue = 51009689,
          SpeakNpcId = 700301,
          Subtitle = "I thought he'd taken her elsewhere for treatment... until a week later, I received a letter from Violet."
        },
        [51009689] = {
          ContentEN = "Sig and I were close back then, but I hardly knew his sister. She was always bedridden. She spent her last coins getting that letter delivered to the mine via a passing Phoxhunter.",
          DialogueId = 51009689,
          GUID = "7FB2891A",
          NextDialogue = 51009690,
          SpeakNpcId = 700301,
          Subtitle = "Sig and I were close back then, but I hardly knew his sister. She was always bedridden. She spent her last coins getting that letter delivered to the mine via a passing Phoxhunter."
        },
        [51009690] = {
          Camera = "-21.725342,235.385742,212.564453,0.000078,-22.799852,-68.394066,20.0,100000.0,false,DoNotOverride,2.8",
          ContentEN = "She said Sig had kidnapped Officer Ruthford's daughter, demanding ransom. She begged me to stop him before it was too late.",
          DialogueId = 51009690,
          GUID = "7FB28944",
          NextDialogue = 51009691,
          SpeakNpcId = 700301,
          Subtitle = "She said Sig had kidnapped Officer Ruthford's daughter, demanding ransom. She begged me to stop him before it was too late."
        },
        [51009691] = {
          ContentEN = "He was holding the girl in an old house on the outskirts. When I found him, he was stunned... but he owned up to it.",
          DialogueId = 51009691,
          GUID = "7FB2896E",
          NextDialogue = 51009692,
          SpeakNpcId = 700301,
          Subtitle = "He was holding the girl in an old house on the outskirts. When I found him, he was stunned... but he owned up to it."
        },
        [51009692] = {
          Camera = "12.182617,54.006836,128.048828,0.000051,-5.600557,-66.002014,30.0,100000.0,false,DoNotOverride,2.8",
          ContentEN = "My drunken rant that night opened a door to a nightmare. I was consumed by regret. I wanted to stop him — I truly did... but when I saw Violet, so frail she could barely speak... I hesitated.",
          DialogueId = 51009692,
          GUID = "7FB28998",
          NextDialogue = 51009693,
          SpeakNpcId = 700301,
          Subtitle = "My drunken rant that night opened a door to a nightmare. I was consumed by regret. I wanted to stop him — I truly did... but when I saw Violet, so frail she could barely speak... I hesitated."
        },
        [51009693] = {
          ContentEN = "He begged me to pretend nothing had happened. But the investigation was tightening... and the fear... it shook me to my bones.",
          DialogueId = 51009693,
          GUID = "7FB289C2",
          NextDialogue = 51009694,
          SpeakNpcId = 700301,
          Subtitle = "He begged me to pretend nothing had happened. But the investigation was tightening... and the fear... it shook me to my bones."
        },
        [51009694] = {
          ContentEN = "In the end... I—",
          DialogueId = 51009694,
          GUID = "7FB289EC",
          NextDialogue = 51009695,
          SpeakNpcId = 700301,
          Subtitle = "In the end... I—"
        },
        [51009695] = {
          Camera = "-115.218262,-202.711914,123.809082,0.000057,-5.200553,24.798326,30.0,100000.0,false,DoNotOverride,2.8",
          ContentEN = "You... turned them in?",
          DialogueId = 51009695,
          GUID = "7FB28A16",
          NextDialogue = 51009696,
          SpeakNpcId = 100001,
          Subtitle = "You... turned them in?",
          TalkActionId = {
            [1] = "100001:Talk03_End"
          },
          TurnTo = {
            [1] = "700301:n(100001)"
          }
        },
        [51009696] = {
          Camera = "78.660156,141.991211,123.371582,0.000067,-4.400513,-84.600342,30.0,100000.0,false,DoNotOverride,2.8",
          ContentEN = "I shouldn't have... I never should have!",
          DialogueId = 51009696,
          GUID = "7FB28A40",
          NextDialogue = 51009697,
          SpeakNpcId = 700301,
          Subtitle = "I shouldn't have... I never should have!",
          TalkActionId = {
            [1] = "700301:Sigh_Start"
          }
        },
        [51009697] = {
          Camera = "489.740967,-276.444336,121.044434,0.000018,-7.20046,148.799316,35.0,100000.0,false,DoNotOverride,2.8",
          ContentEN = "What happened after that?",
          DialogueId = 51009697,
          GUID = "7FB28A6A",
          LookAt = {
            [1] = "700301:n(700303)"
          },
          NextDialogue = 51009698,
          SpeakNpcId = 700303,
          Subtitle = "What happened after that?",
          TalkActionId = {
            [1] = "700301:Sigh_End"
          }
        },
        [51009698] = {
          Camera = "-21.725342,235.385742,212.564453,0.000078,-22.799852,-68.394066,20.0,100000.0,false,DoNotOverride,2.8",
          ContentEN = "The officer came himself, leading the arrest. During the struggle, Sig accidentally set the house on fire.",
          DialogueId = 51009698,
          GUID = "7FB28A94",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023101.T_Story_Recall_20023101'",
          NextDialogue = 51009699,
          SpeakNpcId = 700301,
          Subtitle = "The officer came himself, leading the arrest. During the struggle, Sig accidentally set the house on fire.",
          TalkActionId = {
            [1] = "700301:Explain02_Start"
          }
        },
        [51009699] = {
          ContentEN = "I rushed in, trying to save them — but in the chaos, I only managed to get Violet out. Her face was black with soot... only her tears had carved two pale trails down her cheeks.",
          DialogueId = 51009699,
          GUID = "7FB28ABE",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023101.T_Story_Recall_20023101'",
          NextDialogue = 51009700,
          SpeakNpcId = 700301,
          Subtitle = "I rushed in, trying to save them — but in the chaos, I only managed to get Violet out. Her face was black with soot... only her tears had carved two pale trails down her cheeks."
        },
        [51009700] = {
          ContentEN = "I was terrified she'd be punished for her brother's crime. So I hid her in a water barrel, hoping the Legion wouldn't find her.",
          DialogueId = 51009700,
          GUID = "7FB28AE8",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023101.T_Story_Recall_20023101'",
          NextDialogue = 51009701,
          SpeakNpcId = 700301,
          Subtitle = "I was terrified she'd be punished for her brother's crime. So I hid her in a water barrel, hoping the Legion wouldn't find her."
        },
        [51009701] = {
          ContentEN = "In the end, Sig was caught. And the officer's daughter... all they found was her charred remains in the rubble.",
          DialogueId = 51009701,
          GUID = "7FB28B12",
          NextDialogue = 51009702,
          SpeakNpcId = 700301,
          Subtitle = "In the end, Sig was caught. And the officer's daughter... all they found was her charred remains in the rubble."
        },
        [51009702] = {
          ContentEN = "The officer was enraged. He didn't even wait for a trial — he executed Sig with his own hands. As for Violet... I gave her all the bounty money and smuggled her out of Icelake, praying she'd get away from all this.",
          DialogueId = 51009702,
          GUID = "7FB28B3C",
          NextDialogue = 51009703,
          SpeakNpcId = 700301,
          Subtitle = "The officer was enraged. He didn't even wait for a trial — he executed Sig with his own hands. As for Violet... I gave her all the bounty money and smuggled her out of Icelake, praying she'd get away from all this."
        },
        [51009703] = {
          Camera = "12.182617,54.006836,128.048828,0.000051,-5.600557,-66.002014,30.0,100000.0,false,DoNotOverride,2.8",
          ContentEN = "I still remember her face when she left — worn thin by sickness, but her eyes were burning with fury. She was wearing this violet ribbon that day...",
          DialogueId = 51009703,
          GUID = "7FB28B66",
          NextDialogue = 51009704,
          SpeakNpcId = 700301,
          Subtitle = "I still remember her face when she left — worn thin by sickness, but her eyes were burning with fury. She was wearing this violet ribbon that day..."
        },
        [51009704] = {
          ContentEN = "She said she'd leave Icelake for good. Said she never wanted to see me again.",
          DialogueId = 51009704,
          GUID = "7FB28B90",
          NextDialogue = 51009705,
          SpeakNpcId = 700301,
