          TalkActionId = {
            [1] = "700300:Explain02_Start"
          }
        },
        [51009865] = {
          ContentEN = "But I only arrived in Icelake a few years ago. What could any of this possibly have to do with me?",
          DialogueId = 51009865,
          GUID = "7FB2A5FA",
          NextDialogue = 51009866,
          SpeakNpcId = 700300,
          Subtitle = "But I only arrived in Icelake a few years ago. What could any of this possibly have to do with me?"
        },
        [51009866] = {
          Camera = "-357.697266,-104.112305,130.897461,0.99998,-2.799988,24.192202,24.205383,100000.0,false,DoNotOverride,2.8",
          ContentEN = "Because someone survived that fire.",
          DialogueId = 51009866,
          GUID = "7FB2A624",
          NextDialogue = 51009867,
          SpeakNpcId = 700302,
          Subtitle = "Because someone survived that fire.",
          TalkActionId = {
            [1] = "700300:Explain02_End"
          }
        },
        [51009867] = {
          ContentEN = "A witness said there were three people in the house that night — Sig, Enola... and Sig's sister, Violet. A girl around the same age as Enola.",
          DialogueId = 51009867,
          GUID = "7FB2A64E",
          NextDialogue = 51009868,
          SpeakNpcId = 700302,
          Subtitle = "A witness said there were three people in the house that night — Sig, Enola... and Sig's sister, Violet. A girl around the same age as Enola."
        },
        [51009868] = {
          ContentEN = "In the chaos, that witness managed to pull a girl from the flames — a girl he <H>thought</> was Violet. But was she really?",
          DialogueId = 51009868,
          GUID = "7FB2A678",
          NextDialogue = 51009869,
          SpeakNpcId = 700302,
          Subtitle = "In the chaos, that witness managed to pull a girl from the flames — a girl he thought was Violet. But was she really?"
        },
        [51009869] = {
          ContentEN = "Tell me I'm wrong. Sixteen years ago, you killed Violet in that fire — then took her name, and tricked Donat into helping you escape Icelake. Didn't you, Enola Ruthford?",
          DialogueId = 51009869,
          FacialId = {
            [1] = "700302:CM_Angry01"
          },
          GUID = "7FB2A6A2",
          NextDialogue = 51009870,
          SpeakNpcId = 700302,
          Subtitle = "Tell me I'm wrong. Sixteen years ago, you killed Violet in that fire — then took her name, and tricked Donat into helping you escape Icelake. Didn't you, Enola Ruthford?",
          TalkActionId = {
            [1] = "700302:Angry01_Start"
          }
        },
        [51009870] = {
          Camera = "-220.682617,16.6875,142.309082,1.000003,-2.999962,-14.610696,35.0,100000.0,false,DoNotOverride,2.8",
          ContentEN = "...Heh. Now there's a compelling tale. Good mysteries are so rare these days.",
          DialogueId = 51009870,
          FacialId = {
            [1] = "700300:CM_Idle"
          },
          GUID = "7FB2A6CC",
          NextDialogue = 51009871,
          SpeakNpcId = 700300,
          Subtitle = "...Heh. Now there's a compelling tale. Good mysteries are so rare these days.",
          TalkActionId = {
            [1] = "700300:Talk01_Start",
            [2] = "700302:Angry01_End"
          }
        },
        [51009871] = {
          ContentEN = "Please, do go on. I'm dying to hear how it ends.",
          DialogueId = 51009871,
          FacialId = {
            [1] = "700302:CM_Idle"
          },
          GUID = "7FB2A6F6",
          NextDialogue = 51009872,
          SpeakNpcId = 700300,
          Subtitle = "Please, do go on. I'm dying to hear how it ends.",
          TalkActionId = {
            [1] = "700302:Confident_End"
          }
        },
        [51009872] = {
          Camera = "-357.697266,-104.112305,130.897461,0.99998,-2.799988,24.192202,24.205383,100000.0,false,DoNotOverride,2.8",
          ContentEN = "I spent years combing through that case. A body burnt beyond recognition... a lone survivor... it was all just a little too convenient.",
          DialogueId = 51009872,
          GUID = "7FB2A720",
          NextDialogue = 51009873,
          SpeakNpcId = 700302,
          Subtitle = "I spent years combing through that case. A body burnt beyond recognition... a lone survivor... it was all just a little too convenient.",
          TalkActionId = {
            [1] = "700300:Talk01_End",
            [2] = "700302:Think_Start"
          }
        },
        [51009873] = {
          ContentEN = "All the pieces were there, but the thread connecting them all together was missing.",
          DialogueId = 51009873,
          GUID = "7FB2A74A",
          NextDialogue = 51009874,
          SpeakNpcId = 700302,
          Subtitle = "All the pieces were there, but the thread connecting them all together was missing."
        },
        [51009874] = {
          ContentEN = "As luck would have it, back when I was assigned to guard Fabrice Ruthford, I once heard his daughter sing.",
          DialogueId = 51009874,
          GUID = "7FB2A774",
          NextDialogue = 51009875,
          SpeakNpcId = 700302,
          Subtitle = "As luck would have it, back when I was assigned to guard Fabrice Ruthford, I once heard his daughter sing."
        },
        [51009875] = {
          Camera = "-220.682617,16.6875,142.309082,1.000003,-2.999962,-14.610696,35.0,100000.0,false,DoNotOverride,2.8",
          ContentEN = "That voice... I'd recognise it anywhere. And that's when I knew who you really were, \"Violetta of a Thousand Faces.\"",
          DialogueId = 51009875,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB2A79E",
          NextDialogue = 51009876,
          SpeakNpcId = 700302,
          Subtitle = "That voice... I'd recognise it anywhere. And that's when I knew who you really were, \"Violetta of a Thousand Faces.\""
        },
        [51009876] = {
          ContentEN = "I tried to study your habits — even arranged for false letters to be delivered, just to keep tabs on you.",
          DialogueId = 51009876,
          GUID = "7FB2A7C8",
          NextDialogue = 51009877,
          SpeakNpcId = 700302,
          Subtitle = "I tried to study your habits — even arranged for false letters to be delivered, just to keep tabs on you.",
          TalkActionId = {
            [1] = "700302:Explain01_Start"
          }
        },
        [51009877] = {
          ContentEN = "Ah, so he was one of yours.",
          DialogueId = 51009877,
          GUID = "7FB2A7F2",
          NextDialogue = 51009878,
          SpeakNpcId = 700300,
          Subtitle = "Ah, so he was one of yours.",
          TalkActionId = {
            [1] = "700300:Talk01_Start",
            [2] = "700302:Explain01_End"
          }
        },
        [51009878] = {
          ContentEN = "Not quite. He really was a fan. I just gave him a gentle nudge. And thanks to him, I got the answer I needed.",
          DialogueId = 51009878,
          GUID = "7FB2A81C",
          NextDialogue = 51009879,
          SpeakNpcId = 700302,
          Subtitle = "Not quite. He really was a fan. I just gave him a gentle nudge. And thanks to him, I got the answer I needed."
        },
        [51009879] = {
          Camera = "127.291016,-233.679688,146.983398,1.000008,-1.000206,118.987587,38.469608,100000.0,false,DoNotOverride,2.8",
          ContentEN = "Still, there's one thing I don't understand.",
          DialogueId = 51009879,
          GUID = "7FB2A846",
          NextDialogue = 51009880,
          SpeakNpcId = 700302,
          Subtitle = "Still, there's one thing I don't understand."
        },
        [51009880] = {
          ContentEN = "Swapping places with Violet — it couldn't have been possible unless both Sig and the girl went along with it. How did you convince them?",
          DialogueId = 51009880,
          GUID = "7FB2A870",
          NextDialogue = 51009881,
          SpeakNpcId = 700302,
          Subtitle = "Swapping places with Violet — it couldn't have been possible unless both Sig and the girl went along with it. How did you convince them?",
          TalkActionId = {
            [1] = "700300:Talk01_End",
            [2] = "700302:Think_Start"
          }
        },
        [51009881] = {
          Camera = "-294.663086,168.334961,176.219727,1.000005,-6.799897,-27.606359,56.0,100000.0,false,DoNotOverride,2.8",
          ContentEN = "That's your big mystery? The answer's simple.",
          DialogueId = 51009881,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB2A89A",
          NextDialogue = 51009882,
          SpeakNpcId = 700300,
          Subtitle = "That's your big mystery? The answer's simple.",
          TalkActionId = {
            [1] = "700300:Sigh_Start",
            [2] = "700302:Think_End"
          }
        },
        [51009882] = {
          ContentEN = "You used to serve under my father. Then you should know what it meant to defy him.",
          DialogueId = 51009882,
          GUID = "7FB2A8C4",
          NextDialogue = 51009883,
          SpeakNpcId = 700300,
          Subtitle = "You used to serve under my father. Then you should know what it meant to defy him.",
          TalkActionId = {
            [1] = "700300:Sigh_End"
          }
        },
        [51009883] = {
          ContentEN = "Poor Sig was already prepared to throw his life away — but knowing my father, Violet was as good as dead too.",
          DialogueId = 51009883,
          GUID = "7FB2A8EE",
          NextDialogue = 51009884,
          SpeakNpcId = 700300,
          Subtitle = "Poor Sig was already prepared to throw his life away — but knowing my father, Violet was as good as dead too."
        },
        [51009884] = {
          ContentEN = "So I offered them a way out: Once the ransom was collected, stall as long as possible while creating a distraction to buy some time for Violet.",
          DialogueId = 51009884,
          GUID = "7FB2A918",
          NextDialogue = 51009885,
          SpeakNpcId = 700300,
          Subtitle = "So I offered them a way out: Once the ransom was collected, stall as long as possible while creating a distraction to buy some time for Violet."
        },
        [51009885] = {
          ContentEN = "Pathetic, isn't it? In his panic, he actually ran off on his own to hold off the Escort, hoping that a sickly little girl might somehow escape a blazing house...",
          DialogueId = 51009885,
          GUID = "7FB2A942",
          NextDialogue = 51009886,
          SpeakNpcId = 700300,
          Subtitle = "Pathetic, isn't it? In his panic, he actually ran off on his own to hold off the Escort, hoping that a sickly little girl might somehow escape a blazing house...",
          TalkActionId = {
            [1] = "700300:Talk02_Start"
          }
        },
        [51009886] = {
          ContentEN = "I took my chance. Killed that poor wretch who stood in my way. Took her name, left behind the dump — and my father. Left behind everything that ever stood between me and the stage.",
          DialogueId = 51009886,
          GUID = "7FB2A96C",
          NextDialogue = 51009887,
          SpeakNpcId = 700300,
          Subtitle = "I took my chance. Killed that poor wretch who stood in my way. Took her name, left behind the dump — and my father. Left behind everything that ever stood between me and the stage."
        },
        [51009887] = {
          Camera = "96.022461,-329.655273,121.388672,0.999973,0.800034,107.991287,33.074104,100000.0,false,DoNotOverride,2.8",
          ContentEN = "...",
          DialogueId = 51009887,
