          },
          GUID = "7FB2A996",
          NextDialogue = 51009888,
          SpeakNpcId = 700302,
          Subtitle = "..."
        },
        [51009888] = {
          ContentEN = "What's the matter, Giselle? You've chased this truth for years... and now that you have it, you don't look the least bit satisfied.",
          DialogueId = 51009888,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB2A9C0",
          NextDialogue = 51009889,
          SpeakNpcId = 700300,
          Subtitle = "What's the matter, Giselle? You've chased this truth for years... and now that you have it, you don't look the least bit satisfied."
        },
        [51009889] = {
          ContentEN = "You're insane... All of this — just for the spotlight!? You killed two people! Two innocent lives!",
          DialogueId = 51009889,
          GUID = "7FB2A9EA",
          NextDialogue = 51009890,
          SpeakNpcId = 700302,
          Subtitle = "You're insane... All of this — just for the spotlight!? You killed two people! Two innocent lives!",
          TalkActionId = {
            [1] = "700302:Angry01_Start",
            [2] = "700300:Talk02_End"
          }
        },
        [51009890] = {
          ContentEN = "So what will it be? Drag my sins into the light? Or take your revenge, right here and now?",
          DialogueId = 51009890,
          GUID = "7FB2AA14",
          NextDialogue = 51009891,
          SpeakNpcId = 700300,
          Subtitle = "So what will it be? Drag my sins into the light? Or take your revenge, right here and now?",
          TalkActionId = {
            [1] = "700300:Confident_Start"
          }
        },
        [51009891] = {
          ContentEN = "...I only ever meant to reveal the truth... and turn you in to the Escort.",
          DialogueId = 51009891,
          GUID = "7FB2AA3E",
          NextDialogue = 51009892,
          SpeakNpcId = 700302,
          Subtitle = "...I only ever meant to reveal the truth... and turn you in to the Escort."
        },
        [51009892] = {
          ContentEN = "(Giselle draws a dagger. Her fury thickens the air — you can almost hear her teeth grinding, the hilt creaking under the pressure of her grip.)",
          DialogueId = 51009892,
          GUID = "7FB2AA68",
          IsBlack = 1,
          NextDialogue = 51009893,
          Subtitle = "(Giselle draws a dagger. Her fury thickens the air — you can almost hear her teeth grinding, the hilt creaking under the pressure of her grip.)",
          TalkActionId = {
            [1] = "700302:Angry01_End"
          }
        },
        [51009893] = {
          ContentEN = "(If no one stops her, that dagger will silence the finest voice in Icelake. Whatever the truth... you can't just stand by and watch someone commit murder.)",
          DialogueId = 51009893,
          GUID = "7FB2AA69",
          IsBlack = 1,
          Subtitle = "(If no one stops her, that dagger will silence the finest voice in Icelake. Whatever the truth... you can't just stand by and watch someone commit murder.)"
        },
        [51009894] = {
          ContentEN = "{nickname}? What are you doing here?",
          DialogueId = 51009894,
          GUID = "7FB2AABC",
          NextDialogue = 51009895,
          SpeakNpcId = 700300,
          Subtitle = "? What are you doing here?"
        },
        [51009895] = {
          ContentEN = "Get out of my way. I won't let a monster like her walk free!",
          DialogueId = 51009895,
          GUID = "7FB2AAE6",
          NextDialogue = 51009896,
          SpeakNpcId = 700302,
          Subtitle = "Get out of my way. I won't let a monster like her walk free!",
          TalkActionId = {
            [1] = "700302:Angry01_Start"
          }
        },
        [51009896] = {
          ContentEN = "(She's lost it... I have to bring her back to her senses.)",
