        [51009905] = {
          ContentEN = "Huh... just as I thought. You left this ribbon at Sig's grave, didn't you?",
          DialogueId = 51009905,
          GUID = "7FB2AC8A",
          NextDialogue = 51009906,
          SpeakNpcId = 100001,
          Subtitle = "Huh... just as I thought. You left this ribbon at Sig's grave, didn't you?"
        },
        [51009906] = {
          ContentEN = "You once told me it belonged to a dear friend — and that you took to the stage to fulfil her dream.",
          DialogueId = 51009906,
          GUID = "7FB2ACB4",
          NextDialogue = 51009907,
          SpeakNpcId = 100001,
          Subtitle = "You once told me it belonged to a dear friend — and that you took to the stage to fulfil her dream.",
          TalkActionId = {
            [1] = "700300:Sigh_End"
          }
        },
        [51009907] = {
          ContentEN = "You're a naive fool. I can't believe you actually fell for such sentimental drivel.",
          DialogueId = 51009907,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB2ACDE",
          NextDialogue = 51009908,
          SpeakNpcId = 700300,
          Subtitle = "You're a naive fool. I can't believe you actually fell for such sentimental drivel."
        },
        [51009908] = {
          Camera = "233.676758,-71.671875,155.098145,0.000096,-6.00058,179.598373,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentEN = "Maybe. Which is why I borrowed this ribbon from Donat — to find out the truth.",
          DialogueId = 51009908,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB2AD08",
          NextDialogue = 51009909,
          SpeakNpcId = 100001,
          Subtitle = "Maybe. Which is why I borrowed this ribbon from Donat — to find out the truth.",
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51009909] = {
          ContentEN = "He told me about Violet. About how gifted she was. If not for poverty and illness, she might've been a great playwright.",
          DialogueId = 51009909,
          GUID = "7FB2AD32",
          NextDialogue = 51009910,
          SpeakNpcId = 100001,
          Subtitle = "He told me about Violet. About how gifted she was. If not for poverty and illness, she might've been a great playwright."
        },
        [51009910] = {
          ContentEN = "Fate dealt her a cruel hand, but she never gave up. Even when she could barely leave her bed, she still found a way to pursue her dream.",
          DialogueId = 51009910,
          GUID = "7FB2AD5C",
          NextDialogue = 51009911,
          SpeakNpcId = 100001,
          Subtitle = "Fate dealt her a cruel hand, but she never gave up. Even when she could barely leave her bed, she still found a way to pursue her dream."
        },
        [51009911] = {
          ContentEN = "She dreamed of the world's greatest actor performing her work — of her final, proudest piece reaching every corner of Atlasia.",
          DialogueId = 51009911,
          GUID = "7FB2AD86",
          NextDialogue = 51009912,
          SpeakNpcId = 100001,
          Subtitle = "She dreamed of the world's greatest actor performing her work — of her final, proudest piece reaching every corner of Atlasia."
        },
        [51009912] = {
          ContentEN = "And that piece was—",
          DialogueId = 51009912,
          GUID = "7FB2ADB0",
          NextDialogue = 51009913,
          SpeakNpcId = 100001,
          Subtitle = "And that piece was—",
          TalkActionId = {
            [1] = "100001:Talk02R_End"
          }
        },
        [51009913] = {
          Camera = "-62.486328,-300.395508,128.418945,0.000093,0.0,73.193901,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentEN = "...Putini. A three-act play. Later adapted into the opera.",
          DialogueId = 51009913,
          GUID = "7FB2ADDA",
          NextDialogue = 51009914,
          SpeakNpcId = 700300,
          Subtitle = "...Putini. A three-act play. Later adapted into the opera.",
          TalkActionId = {
            [1] = "700300:Agree"
          }
        },
        [51009914] = {
          Camera = "233.676758,-71.671875,155.098145,0.000096,-6.00058,179.598373,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentEN = "Good. You get it now — lying any further would only make things worse. So...",
          DialogueId = 51009914,
          GUID = "7FB2AE04",
          NextOptions = {
            [1] = 510098241,
            [2] = 510098242
          },
          SpeakNpcId = 100001,
          Subtitle = "Good. You get it now — lying any further would only make things worse. So...",
          TalkActionId = {
            [1] = "100001:ConfidentLR_Start"
          }
        },
        [51009915] = {
          Camera = "-62.486328,-300.395508,128.418945,0.000093,0.0,73.193901,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentEN = "I suppose you're right. Every play must end eventually.",
          DialogueId = 51009915,
          GUID = "7FB2AE2E",
          NextDialogue = 51009917,
          SpeakNpcId = 700300,
          Subtitle = "I suppose you're right. Every play must end eventually.",
          TalkActionId = {
            [1] = "700300:Agree"
          }
        },
        [51009916] = {
          Camera = "-62.486328,-300.395508,128.418945,0.000093,0.0,73.193901,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentEN = "...Is this really the time for theatrics?",
          DialogueId = 51009916,
          GUID = "7FB2AE58",
          NextDialogue = 51009917,
          SpeakNpcId = 700300,
          Subtitle = "...Is this really the time for theatrics?",
          TalkActionId = {
            [1] = "700300:Disagree"
          }
        },
        [51009917] = {
          ContentEN = "Well, if every audience were as sharp as you, mystery playwrights wouldn't have to twist themselves in knots to dumb things down.",
          DialogueId = 51009917,
          GUID = "7FB2AE82",
          NextDialogue = 51009918,
          SpeakNpcId = 700300,
          Subtitle = "Well, if every audience were as sharp as you, mystery playwrights wouldn't have to twist themselves in knots to dumb things down."
        },
        [51009918] = {
          Camera = "167.182617,-305.451172,119.724609,0.000095,2.599987,124.794083,44.87347,100000.0,false,DoNotOverride,2.8",
          ContentEN = "What are you two talking about? What's going on here?",
          DialogueId = 51009918,
          GUID = "7FB2AEAC",
          LookAt = {
            [1] = "100001:n(700302)"
          },
          NextDialogue = 51009919,
          SpeakNpcId = 700302,
          Subtitle = "What are you two talking about? What's going on here?",
          TalkActionId = {
            [1] = "100001:ConfidentLR_End"
          },
          TurnTo = {
            [1] = "700300:n(700302)"
          }
        },
        [51009919] = {
          Camera = "-19.636719,461.339844,156.540039,0.000053,-6.400208,-95.20314,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentEN = "It's simple, Giselle. If she really saw Violet as nothing but a pawn, why would she take a name so close to hers?",
          DialogueId = 51009919,
          GUID = "7FB2AED6",
          NextDialogue = 51009920,
          SpeakNpcId = 100001,
          Subtitle = "It's simple, Giselle. If she really saw Violet as nothing but a pawn, why would she take a name so close to hers?",
          TalkActionId = {
            [1] = "100001:Talk01_Start"
          }
        },
        [51009920] = {
          Camera = "-1216.617188,-202.104492,761.92041,0.000021,-23.200226,22.597822,35.0,100000.0,false,Manual,2.8",
          ContentEN = "Let me tell you the version I see: Sixteen years ago, Sig kidnapped Enola Ruthford — the girl who would one day call herself Violetta — to raise money for his sister's treatment.",
          DialogueId = 51009920,
          FinalCamera = "-1418.189453,-286.000977,855.499756,0.000021,-23.200226,22.597822,35.0,100000.0,false,Manual,2.8",
          GUID = "7FB2AF00",
          NextDialogue = 51009921,
          SpeakNpcId = 100001,
          Subtitle = "Let me tell you the version I see: Sixteen years ago, Sig kidnapped Enola Ruthford — the girl who would one day call herself Violetta — to raise money for his sister's treatment.",
          ToFinalCameraBlendTime = 10
        },
        [51009921] = {
          ContentEN = "While she was held captive, Enola met the bedridden Violet. And somewhere in that brief time, the two became close friends.",
          DialogueId = 51009921,
          GUID = "7FB2AF2A",
          NextDialogue = 51009922,
          SpeakNpcId = 100001,
          Subtitle = "While she was held captive, Enola met the bedridden Violet. And somewhere in that brief time, the two became close friends."
        },
        [51009922] = {
          ContentEN = "But it didn't last long.",
          DialogueId = 51009922,
          GUID = "7FB2AF54",
          NextDialogue = 51009923,
          SpeakNpcId = 100001,
          Subtitle = "But it didn't last long."
        },
        [51009923] = {
          ContentEN = "Violet knew her time was running out. She didn't want her brother sinking deeper down the wrong path. So she wrote to Donat — a trusted friend of Sig's — hoping he'd intervene.",
          DialogueId = 51009923,
          GUID = "7FB2AF7E",
          NextDialogue = 51009924,
          SpeakNpcId = 100001,
          Subtitle = "Violet knew her time was running out. She didn't want her brother sinking deeper down the wrong path. So she wrote to Donat — a trusted friend of Sig's — hoping he'd intervene."
        },
        [51009924] = {
          ContentEN = "And Donat did. He reported the kidnapping... to you, Giselle. But by then, I suspect Violet was already—",
          DialogueId = 51009924,
          GUID = "7FB2AFA8",
          NextDialogue = 51009925,
          SpeakNpcId = 100001,
          Subtitle = "And Donat did. He reported the kidnapping... to you, Giselle. But by then, I suspect Violet was already—"
        },
        [51009925] = {
          Camera = "-158.601562,204.59082,150.237305,0.000071,-3.199944,-50.20327,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentEN = "Ah... strange, isn't it? I was kidnapped, yet somehow... those were the happiest days of my life.",
          DialogueId = 51009925,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          FinalCamera = "-91.950195,124.576172,144.41748,0.000071,-3.199944,-50.20327,35.333332,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB2AFD2",
          LookAt = {
            [1] = "100001:n(700300)"
          },
          NextDialogue = 51009926,
          SpeakNpcId = 700300,
          Subtitle = "Ah... strange, isn't it? I was kidnapped, yet somehow... those were the happiest days of my life.",
          TalkActionId = {
            [1] = "700300:Explain02_Start"
          },
          ToFinalCameraBlendTime = 15
        },
        [51009926] = {
          ContentEN = "Sig kept me tied up in a room, but he never meant me harm. He barely paid me any attention — just paced endlessly around the house.",
          DialogueId = 51009926,
          GUID = "7FB2AFFC",
          NextDialogue = 51009927,
          SpeakNpcId = 700300,
          Subtitle = "Sig kept me tied up in a room, but he never meant me harm. He barely paid me any attention — just paced endlessly around the house."
        },
        [51009927] = {
          ContentEN = "I knew there was someone else — a girl — in the house. I could hear her humming softly, on days when her mood was light...",
          DialogueId = 51009927,
          GUID = "7FB2B026",
          NextDialogue = 51009928,
          SpeakNpcId = 700300,
          Subtitle = "I knew there was someone else — a girl — in the house. I could hear her humming softly, on days when her mood was light..."
        },
        [51009928] = {
          ContentEN = "Perhaps Sig realised he couldn't possibly tend to two helpless people at once. So a few days in, he untied me — let me move around the ground floor as I pleased.",
          DialogueId = 51009928,
          GUID = "7FB2B050",
          NextDialogue = 51009929,
          SpeakNpcId = 700300,
          Subtitle = "Perhaps Sig realised he couldn't possibly tend to two helpless people at once. So a few days in, he untied me — let me move around the ground floor as I pleased."
        },
        [51009929] = {
          Camera = "-91.950195,124.576172,144.41748,0.000071,-3.199944,-50.20327,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentEN = "And whenever he left the house, I'd steal upstairs to see Violet. She'd tell me the stories she was writing... and I'd act them out — bringing the characters to life.",
          DialogueId = 51009929,
          GUID = "7FB2B07A",
          NextDialogue = 51009930,
          SpeakNpcId = 700300,
          Subtitle = "And whenever he left the house, I'd steal upstairs to see Violet. She'd tell me the stories she was writing... and I'd act them out — bringing the characters to life."
        },
        [51009930] = {
          ContentEN = "\"My dearest, weep no tears for me — on this sleepless night, I set off in silver light.\"",
          DialogueId = 51009930,
          GUID = "7FB2B0A4",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009931,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora",
          Subtitle = "\"My dearest, weep no tears for me — on this sleepless night, I set off in silver light.\""
        },
        [51009931] = {
          ContentEN = "\"The wind fills my sail, the tide kisses my oar. The lighthouse aglow, 'neath the moon — oh, so bright!\"",
          DialogueId = 51009931,
          GUID = "7FB2B0CE",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009932,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora",
          Subtitle = "\"The wind fills my sail, the tide kisses my oar. The lighthouse aglow, 'neath the moon — oh, so bright!\""
        },
        [51009932] = {
          ContentEN = "Thank you, Enola... that was beautiful. Truly. Hehe... Whenever I imagined Putini, she always looked like you — bold, radiant, and forever chasing her freedom...",
          DialogueId = 51009932,
          GUID = "7FB2B0F8",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009933,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Violet",
          Subtitle = "Thank you, Enola... that was beautiful. Truly. Hehe... Whenever I imagined Putini, she always looked like you — bold, radiant, and forever chasing her freedom..."
        },
        [51009933] = {
          ContentEN = "Thanks! I did a bit of improvising... But I know a brilliant composer — his name's Cavaradossi. Maybe we could ask him to adapt Putini into an opera—",
          DialogueId = 51009933,
          GUID = "7FB2B122",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009934,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora",
          Subtitle = "Thanks! I did a bit of improvising... But I know a brilliant composer — his name's Cavaradossi. Maybe we could ask him to adapt Putini into an opera—"
        },
        [51009934] = {
          ContentEN = "...Not that I'll ever get the chance to sing it.",
          DialogueId = 51009934,
          GUID = "7FB2B14C",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009935,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora",
          Subtitle = "...Not that I'll ever get the chance to sing it."
        },
        [51009935] = {
          ContentEN = "I'm eighteen now. My father's already arranged my marriage — two months from now, to some young officer from the Alchemy Academy.",
          DialogueId = 51009935,
          GUID = "7FB2B176",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009936,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora",
          Subtitle = "I'm eighteen now. My father's already arranged my marriage — two months from now, to some young officer from the Alchemy Academy."
        },
        [51009936] = {
          ContentEN = "Guess I'll spend the rest of my life as a pretty trophy collecting dust in a parlour... or elbow-deep in those wretched Phoxichor canisters.",
          DialogueId = 51009936,
          GUID = "7FB2B1A0",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009937,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora",
          Subtitle = "Guess I'll spend the rest of my life as a pretty trophy collecting dust in a parlour... or elbow-deep in those wretched Phoxichor canisters."
        },
        [51009937] = {
          ContentEN = "No, no... Enola, this isn't how it should be. You have a voice as sweet as a lark's... You don't belong in some parlour... You belong on a grand stage — the grandest there is.",
          DialogueId = 51009937,
          GUID = "7FB2B1CA",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009938,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Violet",
          Subtitle = "No, no... Enola, this isn't how it should be. You have a voice as sweet as a lark's... You don't belong in some parlour... You belong on a grand stage — the grandest there is."
        },
        [51009938] = {
          ContentEN = "Everyone who loves to sing... deserves their moment in the spotlight... Solarian or Charon, rich or poor...",
          DialogueId = 51009938,
          GUID = "7FB2B1F4",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009939,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Violet",
          Subtitle = "Everyone who loves to sing... deserves their moment in the spotlight... Solarian or Charon, rich or poor..."
        },
        [51009939] = {
          ContentEN = "I'll talk to my brother. I'll find a way to help you escape. My body's already giving out... and I may never finish the final act of Putini...",
          DialogueId = 51009939,
          GUID = "7FB2B21E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009940,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Violet",
          Subtitle = "I'll talk to my brother. I'll find a way to help you escape. My body's already giving out... and I may never finish the final act of Putini..."
        },
        [51009940] = {
          ContentEN = "But Enola — promise me that you'll take the stage, and share our Putini with the world...",
          DialogueId = 51009940,
          GUID = "7FB2B248",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009941,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Violet",
          Subtitle = "But Enola — promise me that you'll take the stage, and share our Putini with the world..."
        },
        [51009941] = {
          ContentEN = "\"Everyone who loves to sing deserves their moment in the spotlight. Solarian or Charon, rich or poor...\" That was Violet's final wish — and it became the truth I live by.",
          DialogueId = 51009941,
          GUID = "7FB2B272",
          NextDialogue = 51009942,
          SpeakNpcId = 700300,
          Subtitle = "\"Everyone who loves to sing deserves their moment in the spotlight. Solarian or Charon, rich or poor...\" That was Violet's final wish — and it became the truth I live by."
        },
        [51009942] = {
          ContentEN = "...After she passed, I sang the finished final act of Putini for Sig. He was hollowed by grief — but when he heard it, his eyes lit with disbelief... and for a moment, I saw hope flicker in the ashes.",
          DialogueId = 51009942,
          GUID = "7FB2B29C",
          NextDialogue = 51009943,
          SpeakNpcId = 700300,
          Subtitle = "...After she passed, I sang the finished final act of Putini for Sig. He was hollowed by grief — but when he heard it, his eyes lit with disbelief... and for a moment, I saw hope flicker in the ashes."
        },
        [51009943] = {
          ContentEN = "We still have a chance to honour her. Violet poured her joy, sorrow, hope, and longing into that script. I want the world to hear it — I need to make sure they do.",
          DialogueId = 51009943,
          GUID = "7FB2B2C6",
          NextDialogue = 51009944,
          SpeakNpcId = 700300,
          Subtitle = "We still have a chance to honour her. Violet poured her joy, sorrow, hope, and longing into that script. I want the world to hear it — I need to make sure they do."
        },
        [51009944] = {
          ContentEN = "We were both born for the stage. Illness took her far too soon, but I'll carry her soul in every role I play — in every spotlight I step into.",
          DialogueId = 51009944,
          GUID = "7FB2B2F0",
          NextDialogue = 51009945,
          SpeakNpcId = 700300,
          Subtitle = "We were both born for the stage. Illness took her far too soon, but I'll carry her soul in every role I play — in every spotlight I step into."
        },
        [51009945] = {
          ContentEN = "So to help you escape your father's grip — and to fulfil Violet's last wish — Sig agreed to play his part in the act.",
          DialogueId = 51009945,
          GUID = "7FB2B31A",
          NextDialogue = 51009946,
          SpeakNpcId = 100001,
          Subtitle = "So to help you escape your father's grip — and to fulfil Violet's last wish — Sig agreed to play his part in the act."
        },
        [51009946] = {
          Camera = "173.006836,-16.306641,127.36377,0.000095,0.999769,158.194092,44.87347,100000.0,false,DoNotOverride,2.8",
          ContentEN = "No... That can't be... If that's true, then why did she just—?",
          DialogueId = 51009946,
          FacialId = {
            [1] = "700302:CM_Shock01"
          },
          GUID = "7FB2B344",
          NextDialogue = 51009947,
          SpeakNpcId = 700302,
          Subtitle = "No... That can't be... If that's true, then why did she just—?",
          TalkActionId = {
            [1] = "700302:Shock_Start"
          }
        },
        [51009947] = {
          ContentEN = "You came here convinced of her guilt, Giselle. And Ms Violetta couldn't risk provoking you — not with her student Rosalind's safety at stake.",
          DialogueId = 51009947,
          GUID = "7FB2B36E",
          NextDialogue = 51009948,
          SpeakNpcId = 100001,
          Subtitle = "You came here convinced of her guilt, Giselle. And Ms Violetta couldn't risk provoking you — not with her student Rosalind's safety at stake."
        },
        [51009948] = {
          ContentEN = "What—?",
          DialogueId = 51009948,
          FacialId = {
            [1] = "700302:CM_Angry01"
          },
          GUID = "7FB2B398",
          NextDialogue = 51009949,
          SpeakNpcId = 700302,
          Subtitle = "What—?",
          TalkActionId = {
            [1] = "700302:Shock_End"
          }
        },
        [51009949] = {
          Camera = "-158.601562,204.59082,150.237305,0.000071,-3.199944,-50.20327,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentEN = "I have a request... I won't run, I promise. Just — come with me. There's somewhere I need to go.",
          DialogueId = 51009949,
          GUID = "7FB2B3C2",
          NextOptions = {
            [1] = 510098591
          },
          Scripts = "PlayOrStopBGM{PlayType{\"Stop\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0036_story_renweidaozu\"}}",
          SpeakNpcId = 700300,
          Subtitle = "I have a request... I won't run, I promise. Just — come with me. There's somewhere I need to go."
        },
        [51009950] = {
          Camera = "173.006836,-16.306641,127.36377,0.000095,0.999769,158.194092,44.87347,100000.0,false,DoNotOverride,2.8",
          ContentEN = "Fine. But don't think you can pull any tricks.",
          DialogueId = 51009950,
          GUID = "7FB2B3EC",
          LookAt = {
            [1] = "100001:n(700302)"
          },
          SpeakNpcId = 700302,
          Subtitle = "Fine. But don't think you can pull any tricks.",
          TalkActionId = {
            [1] = "700302:Agree"
          }
        },
        [51009951] = {
          Camera = "-257.950684,511.992188,553.037598,0.000167,-36.995567,-61.979073,17.27956,100000.0,false,DoNotOverride,2.8",
          ContentEN = "It's all been rebuilt... But to me, every brick, every stone still looks just as it did back then.",
          DialogueId = 51009951,
          FinalCamera = "-156.373047,321.121094,390.135742,0.000167,-36.995567,-61.979073,17.27956,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB2B416",
          LookAt = {
            [1] = "100001:n(700300)",
            [2] = "700302:n(700300)"
          },
          NextDialogue = 51009952,
          SpeakNpcId = 700300,
          Subtitle = "It's all been rebuilt... But to me, every brick, every stone still looks just as it did back then.",
          ToFinalCameraBlendTime = 5
        },
        [51009952] = {
          ContentEN = "Violet... I came back to see you. And I brought our work with me.",
          DialogueId = 51009952,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB2B440",
          LookAt = {
            [1] = "100001:n(700300)"
          },
          NextDialogue = 51009953,
          SpeakNpcId = 700300,
          Subtitle = "Violet... I came back to see you. And I brought our work with me.",
          TalkActionId = {
            [1] = "700300:Explain01_Start"
          }
        },
        [51009953] = {
          ContentEN = "Someone with a sharp eye pieced together our story. Strangely, I'm not scared. I feel... relieved. Maybe because, at long last, I can say this to you properly: I'm sorry. About Sig.",
          DialogueId = 51009953,
          GUID = "7FB2B46A",
          NextDialogue = 51009954,
          SpeakNpcId = 700300,
          Subtitle = "Someone with a sharp eye pieced together our story. Strangely, I'm not scared. I feel... relieved. Maybe because, at long last, I can say this to you properly: I'm sorry. About Sig."
        },
        [51009954] = {
          ContentEN = "(Violetta's fingers graze the wall, as if sharing memories with an old friend she hasn't seen in years. Perhaps the time for farewell has come, and that's what brought her back here.)",
          DialogueId = 51009954,
          GUID = "7FB2B494",
          NextDialogue = 51009955,
          Subtitle = "(Violetta's fingers graze the wall, as if sharing memories with an old friend she hasn't seen in years. Perhaps the time for farewell has come, and that's what brought her back here.)",
          TalkActionId = {
            [1] = "700300:Explain01_End"
          }
        },
        [51009955] = {
          Camera = "-412.794434,216.719727,171.631836,0.000165,-6.39514,-27.7768,35.0,100000.0,false,DoNotOverride,2.8",
          ContentEN = "Thank you... for indulging me.",
          DialogueId = 51009955,
          GUID = "7FB2B4BE",
          NextDialogue = 51009956,
          SpeakNpcId = 700300,
          Subtitle = "Thank you... for indulging me.",
          TurnTo = {
            [1] = "700300:n(700302)"
          }
        },
        [51009956] = {
          ContentEN = "So, Violetta... You went along with the accusations for another reason, didn't you? Because Sig's death — that wasn't part of your plan.",
          DialogueId = 51009956,
          GUID = "7FB2B4E8",
          NextDialogue = 51009957,
          SpeakNpcId = 100001,
          Subtitle = "So, Violetta... You went along with the accusations for another reason, didn't you? Because Sig's death — that wasn't part of your plan.",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          }
        },
        [51009957] = {
          ContentEN = "Fabrice Ruthford... He was a ruthless, heartless man. The miners under him starved. His Escort officers weren't much better off.",
          DialogueId = 51009957,
          GUID = "7FB2B512",
          NextDialogue = 51009958,
          SpeakNpcId = 700300,
          Subtitle = "Fabrice Ruthford... He was a ruthless, heartless man. The miners under him starved. His Escort officers weren't much better off.",
          TalkActionId = {
            [1] = "700300:Disagree",
            [2] = "100001:Explain01_End"
          }
        },
        [51009958] = {
          Camera = "-412.794434,216.719727,171.631836,0.000165,-6.39514,-27.7768,35.0,100000.0,false,DoNotOverride,2.8",
          ContentEN = "He showed no mercy — not even to his own daughter. He dismissed everything she was, crushed her dreams, caged her spirit... and forced her into the lifeless future he had planned.",
          DialogueId = 51009958,
          FinalCamera = "-134.225342,69.999023,159.965332,0.000165,-6.39514,-27.776773,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB2B53C",
          NextDialogue = 51009959,
          SpeakNpcId = 700300,
          Subtitle = "He showed no mercy — not even to his own daughter. He dismissed everything she was, crushed her dreams, caged her spirit... and forced her into the lifeless future he had planned.",
          TalkActionId = {
            [1] = "700300:Sigh_Start"
          },
          ToFinalCameraBlendTime = 10
        },
        [51009959] = {
          ContentEN = "And yet... when his daughter \"died,\" the same heartless man threw aside all legal procedure and executed the kidnapper with his own hands — knowing full well it would cost him his career.",
          DialogueId = 51009959,
          GUID = "7FB2B566",
          NextDialogue = 51009960,
          SpeakNpcId = 700300,
          Subtitle = "And yet... when his daughter \"died,\" the same heartless man threw aside all legal procedure and executed the kidnapper with his own hands — knowing full well it would cost him his career."
        },
        [51009960] = {
          ContentEN = "I thought of countless ways to slip the truth to the court once I was free. I thought I could save Sig in secret. But the one thing I never imagined—",
          DialogueId = 51009960,
          GUID = "7FB2B590",
          NextDialogue = 51009961,
          SpeakNpcId = 700300,
          Subtitle = "I thought of countless ways to slip the truth to the court once I was free. I thought I could save Sig in secret. But the one thing I never imagined—"
        },
        [51009961] = {
          ContentEN = "...Was that your father loved you more than you ever knew.",
          DialogueId = 51009961,
          GUID = "7FB2B5BA",
          NextDialogue = 51009962,
          SpeakNpcId = 700302,
          Subtitle = "...Was that your father loved you more than you ever knew.",
          TalkActionId = {
            [1] = "700302:Talk02_Start"
          }
        },
        [51009962] = {
          ContentEN = "...There were so many times I wanted to reveal the truth. But Hyperborea was only the beginning — her story needed to reach the world. I had to keep my promise... or at least, keep trying.",
          DialogueId = 51009962,
          GUID = "7FB2B5E4",
          NextDialogue = 51009963,
          SpeakNpcId = 700300,
          Subtitle = "...There were so many times I wanted to reveal the truth. But Hyperborea was only the beginning — her story needed to reach the world. I had to keep my promise... or at least, keep trying.",
          TalkActionId = {
            [1] = "700300:Sigh_End",
            [2] = "700302:Talk02_End"
          }
        },
        [51009963] = {
          ContentEN = "So when you came to me, Giselle... I felt oddly relieved. I've trained many gifted children over the years. They can carry Putini farther and wider than I ever could.",
          DialogueId = 51009963,
          GUID = "7FB2B60E",
          LookAt = {
            [1] = "700300:n(700302)"
          },
          NextDialogue = 51009964,
          SpeakNpcId = 700300,
          Subtitle = "So when you came to me, Giselle... I felt oddly relieved. I've trained many gifted children over the years. They can carry Putini farther and wider than I ever could.",
          TalkActionId = {
            [1] = "700300:Talk02_Start"
          }
        },
        [51009964] = {
          ContentEN = "And all you had to do... was let Giselle believe it was true. So you could finally clear Sig's name.",
