        },
        [51010301] = {
          ContentEN = "The Misty Sea myths of the Charon...",
          DialogueId = 51010301,
          GUID = "7FB2ED82",
          SpeakNpcId = 700342,
          Subtitle = "The Misty Sea myths of the Charon...",
          VoiceName = "voice/$Locale$/env/700342/7FB2ED82"
        },
        [51010302] = {
          ContentEN = "This one's the most fascinating — it says everything in the Misty Sea is caught in an endless cycle of life and death. What do you think, Idy—",
          DialogueId = 51010302,
          GUID = "7FB2EDAC",
          NextDialogue = 51010303,
          SpeakNpcId = 700342,
          Subtitle = "This one's the most fascinating — it says everything in the Misty Sea is caught in an endless cycle of life and death. What do you think, Idy—",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EDAC"
        },
        [51010303] = {
          ContentEN = "Ah! It's you! I remember — we spoke right here, didn't we?",
          DialogueId = 51010303,
          GUID = "7FB2EDD6",
          NextDialogue = 51010304,
          SpeakNpcId = 700342,
          Subtitle = "Ah! It's you! I remember — we spoke right here, didn't we?",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EDD6"
        },
        [51010304] = {
          ContentEN = "Have you seen my friend? Red hair, always drifting in and out like the wind... She was just here a moment ago.",
          DialogueId = 51010304,
          GUID = "7FB2EE00",
          NextOptions = {
            [1] = 51010305
          },
          SpeakNpcId = 700342,
          Subtitle = "Have you seen my friend? Red hair, always drifting in and out like the wind... She was just here a moment ago.",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EE00"
        },
        [51010305] = {
          ContentEN = "I haven't seen anyone like that around.",
          DialogueId = 51010305,
          GUID = "7FB2EE2A",
          NextDialogue = 51010306,
          Subtitle = "I haven't seen anyone like that around."
        },
        [51010306] = {
          ContentEN = "Thanks anyway. I'll wait a bit — she has a habit of vanishing... then turning up out of nowhere.",
          DialogueId = 51010306,
          GUID = "7FB2EE54",
          NextDialogue = 51010307,
          SpeakNpcId = 700342,
          Subtitle = "Thanks anyway. I'll wait a bit — she has a habit of vanishing... then turning up out of nowhere.",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EE54"
        },
        [51010307] = {
          ContentEN = "We've been gathering Charon myths these past few days. It's surprising how openly people speak of them here.",
          DialogueId = 51010307,
          GUID = "7FB2EE7E",
          NextDialogue = 51010308,
          SpeakNpcId = 700342,
          Subtitle = "We've been gathering Charon myths these past few days. It's surprising how openly people speak of them here.",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EE7E"
        },
        [51010308] = {
          ContentEN = "Charons are shunned here in Hyperborea, but back in my homeland, Elysium, they're venerated as divine messengers enthroned in sacred halls. But to speak those old myths aloud... is dangerous there.",
          DialogueId = 51010308,
          GUID = "7FB2EEA8",
          NextDialogue = 51010309,
          SpeakNpcId = 700342,
          Subtitle = "Charons are shunned here in Hyperborea, but back in my homeland, Elysium, they're venerated as divine messengers enthroned in sacred halls. But to speak those old myths aloud... is dangerous there.",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EEA8"
        },
        [51010309] = {
          ContentEN = "Do you know much about the myths of the Charon?",
          DialogueId = 51010309,
          GUID = "7FB2EED2",
          NextOptions = {
            [1] = 51010310,
            [2] = 51010311
          },
          SpeakNpcId = 700342,
          Subtitle = "Do you know much about the myths of the Charon?",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EED2"
        },
        [51010310] = {
          ContentEN = "A little.",
          DialogueId = 51010310,
          GUID = "7FB2EEFC",
          NextDialogue = 51010312,
          Subtitle = "A little."
        },
        [51010311] = {
          ContentEN = "Not really.",
          DialogueId = 51010311,
          GUID = "7FB2EF26",
          NextDialogue = 51010312,
          Subtitle = "Not really."
        },
        [51010312] = {
          ContentEN = "\"Charon\" means \"those who came from the Misty Sea\"...",
          DialogueId = 51010312,
          GUID = "7FB2EF50",
          NextDialogue = 51010313,
          SpeakNpcId = 700342,
          Subtitle = "\"Charon\" means \"those who came from the Misty Sea\"...",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EF50"
        },
        [51010313] = {
          ContentEN = "The Misty Sea is the origin of all things. From it rose the Sacred Tree. Its canopy stretched across the heavens — and each of its branches became a Heaventree. Its roots, meanwhile, cradled the world.",
          DialogueId = 51010313,
          GUID = "7FB2EF7A",
          NextDialogue = 51010314,
          SpeakNpcId = 700342,
          Subtitle = "The Misty Sea is the origin of all things. From it rose the Sacred Tree. Its canopy stretched across the heavens — and each of its branches became a Heaventree. Its roots, meanwhile, cradled the world.",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EF7A"
        },
        [51010314] = {
          ContentEN = "The tree bloomed with white flowers, and from them stepped forth Mother Embla. She created all things — and from her came Father Ask. Together, they gave birth to the first of the Charons.",
          DialogueId = 51010314,
          GUID = "7FB2EFA4",
          NextDialogue = 51010315,
          SpeakNpcId = 700342,
          Subtitle = "The tree bloomed with white flowers, and from them stepped forth Mother Embla. She created all things — and from her came Father Ask. Together, they gave birth to the first of the Charons.",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EFA4"
        },
        [51010315] = {
          ContentEN = "Yet Ask, bearer of <W>the power of death</>, became a vessel of calamity. In the end, it was he who brought ruin to the world — the cataclysm we call Ragnarok.",
          DialogueId = 51010315,
          GUID = "7FB2EFCE",
          NextDialogue = 51010316,
          SpeakNpcId = 700342,
          Subtitle = "Yet Ask, bearer of the power of death, became a vessel of calamity. In the end, it was he who brought ruin to the world — the cataclysm we call Ragnarok.",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EFCE"
        },
        [51010316] = {
          ContentEN = "In that final hour, Mother Embla — keeper of <H>the power of life</> — gathered her children and sheltered them. Her soul scattered into the sea... and at last, returned to the Misty Sea.",
          DialogueId = 51010316,
          GUID = "7FB2EFF8",
          NextDialogue = 51010317,
          SpeakNpcId = 700342,
          Subtitle = "In that final hour, Mother Embla — keeper of the power of life — gathered her children and sheltered them. Her soul scattered into the sea... and at last, returned to the Misty Sea.",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EFF8"
        },
        [51010317] = {
          ContentEN = "Ask's body became the land and his arms, upraised, became the mountains, still reaching for the gods... who no longer come.",
          DialogueId = 51010317,
          GUID = "7FB2F022",
          NextOptions = {
            [1] = 51010318
          },
          SpeakNpcId = 700342,
          Subtitle = "Ask's body became the land and his arms, upraised, became the mountains, still reaching for the gods... who no longer come.",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F022"
        },
        [51010318] = {
          ContentEN = "That's... kind of a sad story.",
          DialogueId = 51010318,
          GUID = "7FB2F04C",
          NextDialogue = 51010319,
          Subtitle = "That's... kind of a sad story."
        },
        [51010319] = {
          ContentEN = "Mm... but there's another thread in the myths that caught my ear.",
          DialogueId = 51010319,
          GUID = "7FB2F076",
          NextDialogue = 51010320,
          SpeakNpcId = 700342,
          Subtitle = "Mm... but there's another thread in the myths that caught my ear.",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F076"
        },
        [51010320] = {
          ContentEN = "It says Ask and Embla were reborn after the world's end — in new forms, walking again in a new world.",
          DialogueId = 51010320,
          GUID = "7FB2F0A0",
          NextDialogue = 51010321,
          SpeakNpcId = 700342,
          Subtitle = "It says Ask and Embla were reborn after the world's end — in new forms, walking again in a new world.",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F0A0"
        },
        [51010321] = {
          ContentEN = "And that their reborn selves would one day bring about another ending — and another beginning.",
          DialogueId = 51010321,
          GUID = "7FB2F0CA",
          NextDialogue = 51010322,
          SpeakNpcId = 700342,
          Subtitle = "And that their reborn selves would one day bring about another ending — and another beginning.",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F0CA"
        },
        [51010322] = {
          ContentEN = "Thus the world turns, ever in circles. Life and death, again and again.",
          DialogueId = 51010322,
          GUID = "7FB2F0F4",
          NextOptions = {
            [1] = 51010323
          },
          SpeakNpcId = 700342,
          Subtitle = "Thus the world turns, ever in circles. Life and death, again and again.",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F0F4"
        },
        [51010323] = {
          ContentEN = "Seems that the ancients didn't like tragic endings either.",
          DialogueId = 51010323,
          GUID = "7FB2F11E",
          NextDialogue = 51010324,
          Subtitle = "Seems that the ancients didn't like tragic endings either."
        },
        [51010324] = {
          ContentEN = "But... what I keep wondering is — why was the storyteller so sure that the gods were reborn? Or rather... what makes Embla and Ask who they are?",
          DialogueId = 51010324,
          GUID = "7FB2F148",
          NextDialogue = 51010325,
          SpeakNpcId = 700342,
          Subtitle = "But... what I keep wondering is — why was the storyteller so sure that the gods were reborn? Or rather... what makes Embla and Ask who they are?",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F148"
        },
        [51010325] = {
          ContentEN = "Is it their bodies? Their souls? ...Or something else entirely?",
          DialogueId = 51010325,
          GUID = "7FB2F172",
          NextDialogue = 51010326,
          SpeakNpcId = 700342,
          Subtitle = "Is it their bodies? Their souls? ...Or something else entirely?",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F172"
        },
        [51010326] = {
          ContentEN = "Imagine this — just for a moment — that a great mage turned the land beneath our feet back into Ask's original form... Then who would truly be Father Ask? The one made of ancient earth? Or the one who bears his soul reborn?",
          DialogueId = 51010326,
          GUID = "7FB2F19C",
          NextOptions = {
            [1] = 510103261,
            [2] = 510103262,
            [3] = 510103263,
            [4] = 510103264
          },
          SpeakNpcId = 700342,
          Subtitle = "Imagine this — just for a moment — that a great mage turned the land beneath our feet back into Ask's original form... Then who would truly be Father Ask? The one made of ancient earth? Or the one who bears his soul reborn?",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F19C"
        },
        [51010327] = {
          ContentEN = "Ah... so that's how you see it. Thank you. You've given me something new to ponder.",
          DialogueId = 51010327,
          GUID = "7FB2F1C6",
          NextDialogue = 51010329,
          SpeakNpcId = 700342,
          Subtitle = "Ah... so that's how you see it. Thank you. You've given me something new to ponder.",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F1C6"
        },
        [51010328] = {
          ContentEN = "Most songs begin with a question that sounds pointless, don't they?",
          DialogueId = 51010328,
          GUID = "7FB2F1F0",
          NextDialogue = 51010329,
          SpeakNpcId = 700342,
          Subtitle = "Most songs begin with a question that sounds pointless, don't they?",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F1F0"
        },
        [51010329] = {
          ContentEN = "Thank you for your time, dear {性别:sir|miss}. You're a spark on a cold wick. I've come to love these myths. I think... I've found a song inside them, at last.",
          DialogueId = 51010329,
          GUID = "7FB2F21A",
          SpeakNpcId = 700342,
          Subtitle = "Thank you for your time, dear {性别:sir|miss}. You're a spark on a cold wick. I've come to love these myths. I think... I've found a song inside them, at last.",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F21A"
        },
        [51010330] = {
          ContentEN = "What made us who we are?",
          DialogueId = 51010330,
          GUID = "7FB2F244",
          SpeakNpcId = 700342,
          Subtitle = "What made us who we are?",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F244"
        },
        [51010401] = {
          ContentEN = "The Galea Theatre...",
          DialogueId = 51010401,
          GUID = "7FB2FDEA",
          SpeakNpcId = 700342,
          Subtitle = "The Galea Theatre...",
          VoiceName = "voice/$Locale$/env/700342/7FB2FDEA"
        },
        [51010402] = {
          ContentEN = "We meet again, dear {性别:sir|miss}. You're a garnet on white sand. You must like it here. I do too.",
          DialogueId = 51010402,
          GUID = "7FB2FE14",
          NextDialogue = 51010403,
          SpeakNpcId = 700342,
          Subtitle = "We meet again, dear {性别:sir|miss}. You're a garnet on white sand. You must like it here. I do too.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FE14"
        },
        [51010403] = {
          ContentEN = "Have you ever been inside the Galea Theatre?",
          DialogueId = 51010403,
          GUID = "7FB2FE3E",
          NextOptions = {
            [1] = 510104031,
            [2] = 510104032,
            [3] = 510104033
          },
          SpeakNpcId = 700342,
          Subtitle = "Have you ever been inside the Galea Theatre?",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FE3E"
        },
        [51010404] = {
          ContentEN = "Oh! How enviable... You must be well-off.",
          DialogueId = 51010404,
          GUID = "7FB2FE68",
          NextDialogue = 51010407,
          SpeakNpcId = 700342,
          Subtitle = "Oh! How enviable... You must be well-off.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FE68"
        },
        [51010405] = {
          ContentEN = "Ah... then I'm not the only one kept outside the gates.",
          DialogueId = 51010405,
          GUID = "7FB2FE92",
          NextDialogue = 51010407,
          SpeakNpcId = 700342,
          Subtitle = "Ah... then I'm not the only one kept outside the gates.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FE92"
        },
        [51010406] = {
          ContentEN = "You fought the Legion? Remarkable... You must have stories tucked away like old sheet music.",
          DialogueId = 51010406,
          GUID = "7FB2FEBC",
          NextDialogue = 51010407,
          SpeakNpcId = 700342,
          Subtitle = "You fought the Legion? Remarkable... You must have stories tucked away like old sheet music.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FEBC"
        },
        [51010407] = {
          ContentEN = "I've visited opera houses across Luca, but here in Hyperborea... they always turn me away.",
          DialogueId = 51010407,
          GUID = "7FB2FEE6",
          NextDialogue = 51010408,
          SpeakNpcId = 700342,
          Subtitle = "I've visited opera houses across Luca, but here in Hyperborea... they always turn me away.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FEE6"
        },
        [51010408] = {
          ContentEN = "I knew Charons had it rough in this city, but I never imagined the supervision levies for public spaces would be so steep...",
          DialogueId = 51010408,
          GUID = "7FB2FF10",
          NextDialogue = 51010409,
          SpeakNpcId = 700342,
          Subtitle = "I knew Charons had it rough in this city, but I never imagined the supervision levies for public spaces would be so steep...",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FF10"
        },
        [51010409] = {
          ContentEN = "Still — I was lucky to arrive just in time for the Silvercandle Carnival. It's the city's one day when even paupers like me can step through the theatre doors for free. Tragic, though... to hear there'd been a shootout inside. Absolutely dreadful.",
          DialogueId = 51010409,
          GUID = "7FB2FF3A",
          NextDialogue = 51010410,
          SpeakNpcId = 700342,
          Subtitle = "Still — I was lucky to arrive just in time for the Silvercandle Carnival. It's the city's one day when even paupers like me can step through the theatre doors for free. Tragic, though... to hear there'd been a shootout inside. Absolutely dreadful.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FF3A"
        },
        [51010410] = {
          ContentEN = "Even so, I gathered plenty of sheet music! The bookshop prices were fair, and a few kind souls let me trade verses for pages. And one mysterious person... even taught me a famous aria.",
          DialogueId = 51010410,
          GUID = "7FB2FF64",
          NextOptions = {
            [1] = 510104101
          },
          SpeakNpcId = 700342,
          Subtitle = "Even so, I gathered plenty of sheet music! The bookshop prices were fair, and a few kind souls let me trade verses for pages. And one mysterious person... even taught me a famous aria.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FF64"
        },
        [51010411] = {
          ContentEN = "A few nights ago, I was leaning against a wall under the moonlight, humming a melody I'd picked up from a second-hand score. It was simple enough — soft, easy to carry on the wind.",
          DialogueId = 51010411,
          GUID = "7FB2FF8E",
          NextDialogue = 51010412,
          SpeakNpcId = 700342,
          Subtitle = "A few nights ago, I was leaning against a wall under the moonlight, humming a melody I'd picked up from a second-hand score. It was simple enough — soft, easy to carry on the wind.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FF8E"
        }
      }
    end
  },
  {
