    MaxKey = 51011314,
    Loader = function()
      return {
        [51010412] = {
          ContentEN = "When I finished, I heard knocking — on the other side of the wall. Rhythmic. Intentional. Bards are always sensitive to rhythm... I knew it wasn't random.",
          DialogueId = 51010412,
          GUID = "7FB2FFB8",
          NextDialogue = 51010413,
          SpeakNpcId = 700342,
          Subtitle = "When I finished, I heard knocking — on the other side of the wall. Rhythmic. Intentional. Bards are always sensitive to rhythm... I knew it wasn't random.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FFB8"
        },
        [51010413] = {
          ContentEN = "It was code — old knock code, passed down long ago. Just two kinds of taps, but enough to send meaning through stone.",
          DialogueId = 51010413,
          GUID = "7FB2FFE2",
          NextDialogue = 51010414,
          SpeakNpcId = 700342,
          Subtitle = "It was code — old knock code, passed down long ago. Just two kinds of taps, but enough to send meaning through stone.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FFE2"
        },
        [51010414] = {
          ContentEN = "They told me I'd sung it wrong. It was a well-known operatic piece here — but I hadn't read the libretto, so I'd missed its feeling and heart.",
          DialogueId = 51010414,
          GUID = "7FB3000C",
          NextDialogue = 51010415,
          SpeakNpcId = 700342,
          Subtitle = "They told me I'd sung it wrong. It was a well-known operatic piece here — but I hadn't read the libretto, so I'd missed its feeling and heart.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB3000C"
        },
        [51010415] = {
          ContentEN = "They couldn't speak or sing. I don't know why. But they used that rhythm to teach me how to sing it true.",
          DialogueId = 51010415,
          GUID = "7FB30036",
          NextDialogue = 51010416,
          SpeakNpcId = 700342,
          Subtitle = "They couldn't speak or sing. I don't know why. But they used that rhythm to teach me how to sing it true.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB30036"
        },
        [51010416] = {
          ContentEN = "And when I had finally mastered the song, I ran to the other side of the wall to thank them... Only to find they were already gone.",
          DialogueId = 51010416,
          GUID = "7FB30060",
          NextOptions = {
            [1] = 510104161,
            [2] = 510104162
          },
          SpeakNpcId = 700342,
          Subtitle = "And when I had finally mastered the song, I ran to the other side of the wall to thank them... Only to find they were already gone.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB30060"
        },
        [51010417] = {
          ContentEN = "Oh, how lucky!",
          DialogueId = 51010417,
          GUID = "7FB3008A",
          NextDialogue = 51010418,
          SpeakNpcId = 700342,
          Subtitle = "Oh, how lucky!",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB3008A"
        },
        [51010418] = {
          ContentEN = "If it's not too much trouble... would you thank them for me? And send them my best wishes, too. I don't know why they couldn't sing — but I'm sure they loved music, deeply.",
          DialogueId = 51010418,
          GUID = "7FB300B4",
          NextDialogue = 51010419,
          SpeakNpcId = 700342,
          Subtitle = "If it's not too much trouble... would you thank them for me? And send them my best wishes, too. I don't know why they couldn't sing — but I'm sure they loved music, deeply.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB300B4"
        },
        [51010419] = {
