        [51100001] = {
          ContentEN = "With a true heart, no road brings dread — Lord Argent watches o'er me where'er I tread. Though filth and thorns may line the path, to fulfil my vow, I press o—on—Oi! You there — Loongscion! Hold, a moment!",
          DialogueId = 51100001,
          GUID = "7FEC69EA",
          Subtitle = "With a true heart, no road brings dread — Lord Argent watches o'er me where'er I tread. Though filth and thorns may line the path, to fulfil my vow, I press o—on—Oi! You there — Loongscion! Hold, a moment!"
        },
        [51100002] = {
