          NextDialogue = 51100027,
          SpeakNpcId = 700319,
          Subtitle = "Nothing I'd like more — yet to turn back now would be to betray Taihao Themselves!",
          TalkActionId = {
            [1] = "700319:Disagree"
          }
        },
        [51100023] = {
          ContentEN = "If you're braving danger like this, then it must be for something that's very important to you.",
          DialogueId = 51100023,
          GUID = "7FEC6D86",
          ImprPlusId = 1209,
          NextDialogue = 51100024,
          Subtitle = "If you're braving danger like this, then it must be for something that's very important to you."
        },
        [51100024] = {
          ContentEN = "Didn't expect such wisdom from one so young. Aye... there are things in life a man simply cannot back down from.",
          DialogueId = 51100024,
          GUID = "7FEC6DB0",
          NextDialogue = 51100027,
          SpeakNpcId = 700319,
          Subtitle = "Didn't expect such wisdom from one so young. Aye... there are things in life a man simply cannot back down from.",
          TalkActionId = {
            [1] = "700319:Agree"
          }
        },
        [51100025] = {
          ContentEN = "Cut the crap. You're not faking an injury to shake me down, are you?",
          DialogueId = 51100025,
          GUID = "7FEC6DDA",
          ImprPlusId = 1210,
          NextDialogue = 51100026,
          Subtitle = "Cut the crap. You're not faking an injury to shake me down, are you?"
        },
        [51100026] = {
