          DialogueId = 51100027,
          GUID = "7FEC6E2E",
          NextDialogue = 51100028,
          SpeakNpcId = 700319,
          Subtitle = "Truth is, I can't reach the Gritblight Expanse on my own."
        },
        [51100028] = {
          ContentEN = "So here I wait, praying Taihao might send me a kind, able soul — one bold enough to brave the Expanse and see me through.",
          DialogueId = 51100028,
          GUID = "7FEC6E58",
          NextDialogue = 51100029,
          SpeakNpcId = 700319,
          Subtitle = "So here I wait, praying Taihao might send me a kind, able soul — one bold enough to brave the Expanse and see me through.",
