        },
        [51100037] = {
          ContentEN = "Has the Gritblight Expanse always been this bleak and frightening?",
          DialogueId = 51100037,
          Duration = 4,
          GUID = "7FEC6FD2",
          NextDialogue = 51100038,
          SpeakNpcId = 100001,
          Subtitle = "Has the Gritblight Expanse always been this bleak and frightening?"
        },
        [51100038] = {
          ContentEN = "Ah... that's a tale and a half.",
          DialogueId = 51100038,
          Duration = 2,
          GUID = "7FEC6FFC",
          NextDialogue = 51100039,
          SpeakNpcId = 700319,
          Subtitle = "Ah... that's a tale and a half."
        },
        [51100039] = {
          ContentEN = "Long ago, this was but an ordinary stone forest. Then came the Scourge of Zhuyin, and the Gritblight swallowed it whole.",
          DialogueId = 51100039,
          Duration = 8,
          GUID = "7FEC7026",
          NextDialogue = 51100040,
          SpeakNpcId = 700319,
          Subtitle = "Long ago, this was but an ordinary stone forest. Then came the Scourge of Zhuyin, and the Gritblight swallowed it whole."
        },
        [51100040] = {
          ContentEN = "All the trees and grasses were wrapped in dark-violet crystal. Once caught, they were like insects in amber — frozen at that moment, life sealed away.",
          DialogueId = 51100040,
          Duration = 10,
          GUID = "7FEC7050",
          NextDialogue = 51100041,
          SpeakNpcId = 700319,
          Subtitle = "All the trees and grasses were wrapped in dark-violet crystal. Once caught, they were like insects in amber — frozen at that moment, life sealed away."
        },
        [51100041] = {
          ContentEN = "Even the beasts, if they lingered too long, became \"living fossils\".",
          DialogueId = 51100041,
          Duration = 6,
          GUID = "7FEC707A",
          NextDialogue = 51100042,
          SpeakNpcId = 700319,
          Subtitle = "Even the beasts, if they lingered too long, became \"living fossils\"."
        },
        [51100042] = {
          ContentEN = "Some even whisper the Sable Bi'an were once Argent Bi'an — corrupted by the Gritblight's taint...",
          DialogueId = 51100042,
          Duration = 8,
          GUID = "7FEC70A4",
          SpeakNpcId = 700319,
          Subtitle = "Some even whisper the Sable Bi'an were once Argent Bi'an — corrupted by the Gritblight's taint..."
        },
        [51100043] = {
          ContentEN = "This place is desolate. So long as we don't linger, we're unlikely to cross paths with beasts or Bi'an. That's precisely why I chose this route.",
          DialogueId = 51100043,
          DisableMouth = 0,
          GUID = "7FEC70CE",
          IsBlack = 0,
          NextDialogue = 51100044,
          SpeakNpcId = 700319,
          Subtitle = "This place is desolate. So long as we don't linger, we're unlikely to cross paths with beasts or Bi'an. That's precisely why I chose this route.",
          TalkActionId = {
