          },
          bAllowClickSkipScript = false
        },
        [51100044] = {
          ContentEN = "It's called \"hiding in plain sight\" in Huaxu, right?",
          DialogueId = 51100044,
          DisableMouth = 0,
          GUID = "7FEC70F8",
          IsBlack = 0,
          NextDialogue = 51100045,
          SpeakNpcId = 100001,
          Subtitle = "It's called \"hiding in plain sight\" in Huaxu, right?",
          bAllowClickSkipScript = false
        },
        [51100045] = {
          ContentEN = "Hah! Sharp one, aren't you!",
          DialogueId = 51100045,
          DisableMouth = 0,
          GUID = "7FEC7122",
          IsBlack = 0,
          NextDialogue = 51100046,
          SpeakNpcId = 700319,
          Subtitle = "Hah! Sharp one, aren't you!",
          bAllowClickSkipScript = false
        },
        [51100046] = {
          ContentEN = "Truth be told, I've cut through here many a time. Never thought I'd take a tumble last time.",
          DialogueId = 51100046,
          DisableMouth = 0,
          GUID = "7FEC714C",
          IsBlack = 0,
          NextDialogue = 51100047,
          SpeakNpcId = 700319,
          Subtitle = "Truth be told, I've cut through here many a time. Never thought I'd take a tumble last time.",
          TalkActionId = {
            [1] = "700319:Talk01_End"
          },
          bAllowClickSkipScript = false
        },
        [51100047] = {
          ContentEN = "That day, the Expanse felt vaster than ever. I walked and walked, till nightfall — yet found no way out.",
          DialogueId = 51100047,
          DisableMouth = 0,
          GUID = "7FEC7176",
          IsBlack = 0,
          NextDialogue = 51100048,
          SpeakNpcId = 700319,
          Subtitle = "That day, the Expanse felt vaster than ever. I walked and walked, till nightfall — yet found no way out.",
          bAllowClickSkipScript = false
        },
        [51100048] = {
          ContentEN = "Even in daylight it's a gloomy place. Once the sun sets, you can scarce see your own hand. With these old eyes, I wandered in circles, lost in the dark.",
          DialogueId = 51100048,
          DisableMouth = 0,
          GUID = "7FEC71A0",
          IsBlack = 0,
          NextDialogue = 51100049,
          SpeakNpcId = 700319,
          Subtitle = "Even in daylight it's a gloomy place. Once the sun sets, you can scarce see your own hand. With these old eyes, I wandered in circles, lost in the dark.",
          TalkActionId = {
            [1] = "700319:Talk02_Start"
          },
          bAllowClickSkipScript = false
        },
        [51100049] = {
          ContentEN = "At last I toppled, struck the back of my skull. In the haze, I swear I saw a pack of Bi'an darting to and fro before me...",
          DialogueId = 51100049,
          DisableMouth = 0,
          GUID = "7FEC71CA",
          IsBlack = 0,
          NextDialogue = 51100050,
          SpeakNpcId = 700319,
          Subtitle = "At last I toppled, struck the back of my skull. In the haze, I swear I saw a pack of Bi'an darting to and fro before me...",
          bAllowClickSkipScript = false
        },
        [51100050] = {
          ContentEN = "Ah, and I heard a voice! To have Argent Bi'an at their side — surely it could only have been Lord Argent Themselves! I must have heard divine words that night!",
          DialogueId = 51100050,
          DisableMouth = 0,
          GUID = "7FEC71F4",
          IsBlack = 0,
          NextDialogue = 51100051,
          SpeakNpcId = 700319,
          Subtitle = "Ah, and I heard a voice! To have Argent Bi'an at their side — surely it could only have been Lord Argent Themselves! I must have heard divine words that night!",
          bAllowClickSkipScript = false
        },
        [51100051] = {
