          DialogueId = 51101067,
          GUID = "7FED18CE",
          NextDialogue = 51101068,
          Subtitle = "(Zhao Qian gives a wry smile, then gently cups the withered flower in his hands.)"
        },
        [51101068] = {
          ContentEN = "This one's simpler — I met a girl half-dead from thirst in Khemet's desert.",
          DialogueId = 51101068,
          GUID = "7FED18F8",
          NextDialogue = 51101069,
          SpeakNpcId = 700321,
          Subtitle = "This one's simpler — I met a girl half-dead from thirst in Khemet's desert."
        },
        [51101069] = {
          ContentEN = "We were too far from any proper town to call for help. It took quite an effort, but in the end I managed to save her.",
          DialogueId = 51101069,
          GUID = "7FED1922",
          NextDialogue = 51101070,
          SpeakNpcId = 700321,
          Subtitle = "We were too far from any proper town to call for help. It took quite an effort, but in the end I managed to save her."
        },
        [51101070] = {
          ContentEN = "She told me she wasn't the first to fall in that desert. Many had perished of thirst before her. Yet, desperate to find a way of living, they still walked into those merciless sands one after another.",
          DialogueId = 51101070,
          GUID = "7FED194C",
          NextDialogue = 51101071,
          SpeakNpcId = 700321,
          Subtitle = "She told me she wasn't the first to fall in that desert. Many had perished of thirst before her. Yet, desperate to find a way of living, they still walked into those merciless sands one after another."
        },
        [51101071] = {
          ContentEN = "I couldn't save them all. But I could hire others to search for water. This flower — the girl took it from an oasis born of those efforts.",
          DialogueId = 51101071,
          GUID = "7FED1976",
          NextDialogue = 51101072,
          SpeakNpcId = 700321,
          Subtitle = "I couldn't save them all. But I could hire others to search for water. This flower — the girl took it from an oasis born of those efforts."
        },
        [51101072] = {
          ContentEN = "Funny thing — I've travelled far and wide, but most of what I've earned got spent along the way, heh heh...",
          DialogueId = 51101072,
          GUID = "7FED19A0",
          NextDialogue = 51101073,
          SpeakNpcId = 700321,
          Subtitle = "Funny thing — I've travelled far and wide, but most of what I've earned got spent along the way, heh heh..."
        },
