          SpeakNpcId = 700321,
          Subtitle = "Do you know what this is?"
        },
        [51101077] = {
          ContentEN = "I know, I know — stars!",
          DialogueId = 51101077,
          GUID = "7FED1A72",
          NextDialogue = 51101078,
          SpeakNpcId = 900003,
          Subtitle = "I know, I know — stars!"
        },
        [51101078] = {
          ContentEN = "Right. But if you connect them — what do they become?",
          DialogueId = 51101078,
          GUID = "7FED1A9C",
          NextDialogue = 51101079,
          SpeakNpcId = 700321,
          Subtitle = "Right. But if you connect them — what do they become?"
