          DialogueId = 51101079,
          GUID = "7FED1AC6",
          NextDialogue = 51101080,
          SpeakNpcId = 900003,
          Subtitle = "Umm..."
        },
        [51101080] = {
          ContentEN = "They form the Astrolabe Constellation, the one we use to guide our way. And over there — that's the Starweaver Constellation, from which our trade takes its name.",
          DialogueId = 51101080,
          GUID = "7FED1AF0",
          NextDialogue = 51101081,
          SpeakNpcId = 700321,
          Subtitle = "They form the Astrolabe Constellation, the one we use to guide our way. And over there — that's the Starweaver Constellation, from which our trade takes its name."
        },
        [51101081] = {
          ContentEN = "The nations and towns of Atlasia are like those stars — some bright, some dim, yet each with its place.",
          DialogueId = 51101081,
          GUID = "7FED1B1A",
          NextDialogue = 51101082,
          SpeakNpcId = 700321,
          Subtitle = "The nations and towns of Atlasia are like those stars — some bright, some dim, yet each with its place."
        },
        [51101082] = {
          ContentEN = "On their own they may seem far apart. But draw the lines between them, and they form a constellation. Our journeys are those lines.",
          DialogueId = 51101082,
          GUID = "7FED1B44",
          NextDialogue = 51101083,
          SpeakNpcId = 700321,
          Subtitle = "On their own they may seem far apart. But draw the lines between them, and they form a constellation. Our journeys are those lines."
        },
        [51101083] = {
          ContentEN = "Long ago, when humankind first cried out on this land, they had nothing but the sky above.",
          DialogueId = 51101083,
          GUID = "7FED1B6E",
          NextDialogue = 51101084,
          SpeakNpcId = 700321,
          Subtitle = "Long ago, when humankind first cried out on this land, they had nothing but the sky above."
        },
        [51101084] = {
          ContentEN = "And one day, maybe we'll find ourselves with nothing again... but the lines we've woven will still remain.",
          DialogueId = 51101084,
          GUID = "7FED1B98",
          NextDialogue = 51101085,
          SpeakNpcId = 700321,
          Subtitle = "And one day, maybe we'll find ourselves with nothing again... but the lines we've woven will still remain."
        },
        [51101085] = {
          ContentEN = "Goods, stories, knowledge — all carried along those paths, reaching every corner of the continent, to those who need them. And just like that, the \"stars\" on the ground will grow ever brighter.",
          DialogueId = 51101085,
          GUID = "7FED1BC2",
          NextDialogue = 51101086,
          SpeakNpcId = 700321,
          Subtitle = "Goods, stories, knowledge — all carried along those paths, reaching every corner of the continent, to those who need them. And just like that, the \"stars\" on the ground will grow ever brighter."
        },
