        [51104044] = {
          ContentEN = "Osmanthus",
          DialogueId = 51104044,
          GUID = "7FEF0138",
          NextDialogue = 51104045,
          Subtitle = "Osmanthus"
        },
        [51104045] = {
          ContentEN = "That's it. Osmanthus it is — just like the cake's name. Fresh from the steamer. Here you are.",
          DialogueId = 51104045,
          GUID = "7FEF0162",
          NextDialogue = 51104046,
          SpeakNpcId = 700328,
          Subtitle = "That's it. Osmanthus it is — just like the cake's name. Fresh from the steamer. Here you are.",
          TalkActionId = {
            [1] = "700328:Talk02_End",
            [2] = "700324:Angry02_End"
          }
        },
        [51104046] = {
          ContentEN = "Still don't know what the old man was thinking... running a little stall like this, giving out free cakes to anyone who cracks a riddle. Keep that up and he'll burn through his retirement money in no time.",
          DialogueId = 51104046,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_ChapterEast01_GuiHuaCake01.T_Guide_ChapterEast01_GuiHuaCake01'}",
          GUID = "7FEF018C",
          NextDialogue = 51104047,
          SpeakNpcId = 700328,
          Subtitle = "Still don't know what the old man was thinking... running a little stall like this, giving out free cakes to anyone who cracks a riddle. Keep that up and he'll burn through his retirement money in no time.",
          TalkActionId = {
            [1] = "700328:Sigh_Start"
          }
        },
        [51104047] = {
          Camera = "393.902344,31.90625,149.760742,0.000111,-7.799338,-168.793396,35.0,100000.0,false,DoNotOverride,2.8",
          ContentEN = "So... you don't agree with it?",
          DialogueId = 51104047,
          GUID = "7FEF01B6",
          NextDialogue = 51104048,
          SpeakNpcId = 100001,
          Subtitle = "So... you don't agree with it?",
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51104048] = {
          Camera = "68.732422,-386.160156,178.870117,0.000121,-11.199583,62.005909,35.0,100000.0,false,DoNotOverride,2.8",
          ContentEN = "Oh, don't get me wrong. If we say it's free for a right answer, then it's free. You see a kid staring, drool on their chin and wiping it off on their sleeve... who'd have the heart to turn them away?",
          DialogueId = 51104048,
          GUID = "7FEF01E0",
          NextDialogue = 51104049,
          SpeakNpcId = 700328,
          Subtitle = "Oh, don't get me wrong. If we say it's free for a right answer, then it's free. You see a kid staring, drool on their chin and wiping it off on their sleeve... who'd have the heart to turn them away?",
          TalkActionId = {
            [1] = "700328:Sigh_End",
            [2] = "100001:Think_End"
          }
        },
        [51104049] = {
          ContentEN = "Kids don't eat much anyway — what's a single cake? Truth is, I used to wander these streets with no home to return to. It was that same craving for osmanthus cake that caught the old man's eye. He took me in, made me his apprentice... I'd rather not think where I'd have ended up if he hadn't.",
          DialogueId = 51104049,
          FacialId = {
            [1] = "700328:Happy01"
          },
          GUID = "7FEF020A",
          NextDialogue = 51104050,
          SpeakNpcId = 700328,
          Subtitle = "Kids don't eat much anyway — what's a single cake? Truth is, I used to wander these streets with no home to return to. It was that same craving for osmanthus cake that caught the old man's eye. He took me in, made me his apprentice... I'd rather not think where I'd have ended up if he hadn't.",
          TalkActionId = {
            [1] = "700328:Talk02_Start"
          }
        },
        [51104050] = {
          ContentEN = "Ah, listen to me rambling... Anyway, I've always wondered why he ever made that rule of riddles for cake.",
          DialogueId = 51104050,
          FacialId = {
            [1] = "700328:None"
          },
          GUID = "7FEF0234",
          NextDialogue = 51104051,
          SpeakNpcId = 700328,
          Subtitle = "Ah, listen to me rambling... Anyway, I've always wondered why he ever made that rule of riddles for cake.",
          TalkActionId = {
            [1] = "700328:Talk02_End"
          }
        },
        [51104051] = {
          ContentEN = "But he never said, and I never asked. The stall, the recipe, the customers — they were all his. And he handed them down to a stray like me. That's more than I ever deserved.",
          DialogueId = 51104051,
          GUID = "7FEF025E",
          NextDialogue = 51104052,
          SpeakNpcId = 700328,
          Subtitle = "But he never said, and I never asked. The stall, the recipe, the customers — they were all his. And he handed them down to a stray like me. That's more than I ever deserved."
        },
        [51104052] = {
          Camera = "393.902344,31.90625,149.760742,0.000111,-7.799338,-168.793396,35.0,100000.0,false,DoNotOverride,2.8",
          ContentEN = "Sounds like you're complaining... but really, you're quite fond of him, aren't you?",
          DialogueId = 51104052,
          GUID = "7FEF0288",
          NextDialogue = 51104053,
          SpeakNpcId = 100001,
          Subtitle = "Sounds like you're complaining... but really, you're quite fond of him, aren't you?",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51104053] = {
          Camera = "68.732422,-386.160156,178.870117,0.000121,-11.199583,62.005909,35.0,100000.0,false,DoNotOverride,2.8",
          ContentEN = "Haha... you've seen through me. He gave me a roof, filled my bowl, taught me everything I know. I've long seen him as a father. But he won't let me call him that — insists on \"Shifu\" instead.",
          DialogueId = 51104053,
          GUID = "7FEF02B2",
          NextDialogue = 51104054,
          SpeakNpcId = 700328,
          Subtitle = "Haha... you've seen through me. He gave me a roof, filled my bowl, taught me everything I know. I've long seen him as a father. But he won't let me call him that — insists on \"Shifu\" instead.",
          TalkActionId = {
            [1] = "100001:Talk02_End"
          }
        },
        [51104054] = {
          ContentEN = "There's no repaying a debt like that. All I can do is look after him, and see that he spends his days in peace.",
          DialogueId = 51104054,
          GUID = "7FEF02DC",
          NextDialogue = 51104055,
          SpeakNpcId = 700328,
          Subtitle = "There's no repaying a debt like that. All I can do is look after him, and see that he spends his days in peace."
        },
        [51104055] = {
