          }
        },
        [51104057] = {
          ContentEN = "Nah, don't fuss. See to your customers. Just tell your old man to drop in like he promised. Said he'd come by for a drink, but I've been waiting ages. If he doesn't show soon, there'll be no good wine left for him!",
          DialogueId = 51104057,
          GUID = "7FEF035A",
          NextDialogue = 51104058,
          SpeakNpcId = 700332,
