          TalkActionId = {
            [1] = "700333:Talk01_Start"
          }
        },
        [51104095] = {
          ContentEN = "There used to be a grove of osmanthus trees out that way. Well... not a grove, really — just a handful of trees growing close together. But when they bloomed, their scent drifted clear across the hills.",
          DialogueId = 51104095,
          GUID = "7FEF0996",
          LookAt = {
            [1] = "100001:n(700333)",
            [2] = "700325:n(700333)"
          },
          NextDialogue = 51104096,
          SpeakNpcId = 700333,
          Subtitle = "There used to be a grove of osmanthus trees out that way. Well... not a grove, really — just a handful of trees growing close together. But when they bloomed, their scent drifted clear across the hills.",
          TalkActionId = {
            [1] = "700333:Talk01_End"
          }
        },
        [51104096] = {
          ContentEN = "Beneath those trees stood a tiny village. \"Village\" might be too grand a word — just a handful of scattered homes. A modest plot of land nearby, just enough to keep those families fed.",
          DialogueId = 51104096,
          GUID = "7FEF09C0",
          LookAt = {
            [1] = "100001:n(700333)",
            [2] = "700325:n(700333)"
          },
          NextDialogue = 51104097,
          SpeakNpcId = 700333,
          Subtitle = "Beneath those trees stood a tiny village. \"Village\" might be too grand a word — just a handful of scattered homes. A modest plot of land nearby, just enough to keep those families fed."
        },
        [51104097] = {
          ContentEN = "It was quiet, far from Haojing. With little for the children to do, I set them gathering osmanthus blossoms, made cakes with them, shared them round. I'd throw in a riddle or two for fun, just to keep their wits sharp.",
          DialogueId = 51104097,
          GUID = "7FEF09EA",
          LookAt = {
            [1] = "100001:n(700333)",
            [2] = "700325:n(700333)"
          },
          NextDialogue = 51104098,
          SpeakNpcId = 700333,
          Subtitle = "It was quiet, far from Haojing. With little for the children to do, I set them gathering osmanthus blossoms, made cakes with them, shared them round. I'd throw in a riddle or two for fun, just to keep their wits sharp."
        },
        [51104098] = {
          ContentEN = "The one best at solving them... was my son. Huan was a bright boy. I never asked much — only that he grow up safe, and maybe take on this little trade of mine one day.",
          DialogueId = 51104098,
          GUID = "7FEF0A14",
          LookAt = {
            [1] = "100001:n(700333)",
            [2] = "700325:n(700333)"
          },
          NextDialogue = 51104099,
          SpeakNpcId = 700333,
          Subtitle = "The one best at solving them... was my son. Huan was a bright boy. I never asked much — only that he grow up safe, and maybe take on this little trade of mine one day.",
          TalkActionId = {
            [1] = "700333:Disagree"
          }
        },
        [51104099] = {
          Camera = "-118.90625,-330.195312,98.025879,0.0002,-11.993771,63.773678,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentEN = "You mean...",
          DialogueId = 51104099,
          GUID = "7FEF0A3E",
