        [51104100] = {
          Camera = "500.710938,139.5625,82.334961,0.000169,-10.993831,-172.027054,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentEN = "Heh... Huan revered the Magistrates. One day he insisted on watching an arrest — said he wanted to see justice done. He was caught in the chaos... and never made it home.",
          DialogueId = 51104100,
          GUID = "7FEF0A68",
          LookAt = {
            [1] = "100001:n(700333)",
            [2] = "700325:n(700333)"
          },
          NextDialogue = 51104101,
          SpeakNpcId = 700333,
          Subtitle = "Heh... Huan revered the Magistrates. One day he insisted on watching an arrest — said he wanted to see justice done. He was caught in the chaos... and never made it home.",
          TalkActionId = {
            [1] = "100001:Think_End"
          }
        },
        [51104101] = {
          ContentEN = "Decades have passed. The villagers I once knew are long gone, and the ones who came after never knew my name. To them, I'm just the man who sells osmanthus cake.",
          DialogueId = 51104101,
          GUID = "7FEF0A92",
          LookAt = {
            [1] = "100001:n(700333)",
            [2] = "700325:n(700333)"
          },
          NextDialogue = 51104102,
          SpeakNpcId = 700333,
          Subtitle = "Decades have passed. The villagers I once knew are long gone, and the ones who came after never knew my name. To them, I'm just the man who sells osmanthus cake."
        },
        [51104102] = {
          ContentEN = "I didn't want to leave, but with no kin left and no one to turn to, I couldn't stay in that place forever. So I came to the city, selling steamed cakes by the dock. Took in a little orphan, and gave him my son's name.",
          DialogueId = 51104102,
          GUID = "7FEF0ABC",
          LookAt = {
            [1] = "100001:n(700333)",
            [2] = "700325:n(700333)"
          },
          NextDialogue = 51104103,
          SpeakNpcId = 700333,
          Subtitle = "I didn't want to leave, but with no kin left and no one to turn to, I couldn't stay in that place forever. So I came to the city, selling steamed cakes by the dock. Took in a little orphan, and gave him my son's name."
        },
        [51104103] = {
          ContentEN = "I raised him as my own... yet when he calls me \"Dad\", it still tears at me. When that pain grows too heavy, I find myself walking back here.",
          DialogueId = 51104103,
          GUID = "7FEF0AE6",
          LookAt = {
            [1] = "100001:n(700333)",
            [2] = "700325:n(700333)"
          },
          NextDialogue = 51104104,
          SpeakNpcId = 700333,
          Subtitle = "I raised him as my own... yet when he calls me \"Dad\", it still tears at me. When that pain grows too heavy, I find myself walking back here."
        },
        [51104104] = {
          ContentEN = "From this hill, looking down... it's as though the village were still there.",
          DialogueId = 51104104,
          GUID = "7FEF0B10",
          LookAt = {
            [1] = "100001:n(700333)",
            [2] = "700325:n(700333)"
          },
          NextDialogue = 51104105,
          SpeakNpcId = 700333,
          Subtitle = "From this hill, looking down... it's as though the village were still there."
        },
        [51104105] = {
          ContentEN = "Child... do you remember the riddle I gave you, that first time you brought your Shidi to buy osmanthus cake?",
          DialogueId = 51104105,
          GUID = "7FEF0B3A",
          LookAt = {
            [1] = "100001:n(700333)",
            [2] = "700325:n(700333)"
          },
          NextDialogue = 51104106,
          SpeakNpcId = 700333,
          Subtitle = "Child... do you remember the riddle I gave you, that first time you brought your Shidi to buy osmanthus cake?"
        },
        [51104106] = {
          Camera = "-86.242188,466.148438,64.947754,0.000178,-7.393345,-67.627014,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentEN = "The wind sighs, the rain sighs too. Where osmanthus falls, autumn returns anew. A lonely shadow drifts at the prow.",
          DialogueId = 51104106,
          GUID = "7FEF0B64",
          LookAt = {
            [1] = "100001:n(700333)",
            [2] = "700333:n(700325)"
          },
          NextDialogue = 51104107,
          SpeakNpcId = 700325,
          Subtitle = "The wind sighs, the rain sighs too. Where osmanthus falls, autumn returns anew. A lonely shadow drifts at the prow."
        },
        [51104107] = {
          Camera = "500.710938,139.5625,82.334961,0.000169,-10.993831,-172.027054,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentEN = "Quite the memory you have. You couldn't solve it back then — because it wasn't really a riddle. Just something an old man murmured to himself.",
          DialogueId = 51104107,
          GUID = "7FEF0B8E",
          LookAt = {
            [1] = "100001:n(700333)",
            [2] = "700325:n(700333)"
          },
          NextDialogue = 51104108,
          SpeakNpcId = 700333,
          Subtitle = "Quite the memory you have. You couldn't solve it back then — because it wasn't really a riddle. Just something an old man murmured to himself."
        },
        [51104108] = {
          ContentEN = "All these years... My son is gone, but I have an apprentice. My old friends are gone, yet I've found new ones to drink with. Only that little village beneath the osmanthus trees... never returned.",
          DialogueId = 51104108,
          GUID = "7FEF0BB8",
          LookAt = {
            [1] = "100001:n(700333)",
            [2] = "700325:n(700333)"
          },
          NextDialogue = 51104109,
          SpeakNpcId = 700333,
          Subtitle = "All these years... My son is gone, but I have an apprentice. My old friends are gone, yet I've found new ones to drink with. Only that little village beneath the osmanthus trees... never returned."
        },
        [51104109] = {
          ContentEN = "You're still young. Those you cherish are still around, and a home still awaits your return. Don't end up like me...",
          DialogueId = 51104109,
          GUID = "7FEF0BE2",
          LookAt = {
            [1] = "100001:n(700333)",
            [2] = "700325:n(700333)"
          },
          NextDialogue = 51104110,
          SpeakNpcId = 700333,
          Subtitle = "You're still young. Those you cherish are still around, and a home still awaits your return. Don't end up like me..."
        },
        [51104110] = {
          ContentEN = "This is far enough. I can walk the rest on my own. Thank you again, all of you.",
          DialogueId = 51104110,
          GUID = "7FEF0C0C",
          LookAt = {
            [1] = "100001:n(700333)",
            [2] = "700325:n(700333)"
          },
