          GUID = "7FEF0C8A",
          LookAt = {
            [1] = "100001:n(700324)",
            [2] = "700325:n(700324)"
          },
          NextDialogue = 51104114,
          SpeakNpcId = 700324,
          Subtitle = "Hey hey, come on now! Weren't you two thick as thieves? You bought osmanthus cake together! Whatever happened — can't you just talk it out?",
          TalkActionId = {
            [1] = "700324:Think_Start"
          }
        },
        [51104114] = {
          Camera = "156.148438,383.179688,54.88623,0.000159,-8.793397,-104.439034,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentEN = "...Some seek to return home, only to find it gone. Some still have a home, yet can never return.",
          DialogueId = 51104114,
          GUID = "7FEF0CB4",
          LookAt = {
            [1] = "100001:n(700325)",
            [2] = "700324:n(700325)"
          },
          NextDialogue = 51104115,
          SpeakNpcId = 700325,
          Subtitle = "...Some seek to return home, only to find it gone. Some still have a home, yet can never return.",
          TalkActionId = {
            [1] = "700324:Think_End"
          }
        },
        [51104115] = {
          ContentEN = "What lies between us cannot be set right with a few words. Now I serve as a Magistrate of Yingtian... and he, a Drifter. Our paths lie worlds apart.",
          DialogueId = 51104115,
          GUID = "7FEF0CDE",
          LookAt = {
            [1] = "100001:n(700325)",
            [2] = "700324:n(700325)"
          },
          NextDialogue = 51104116,
          SpeakNpcId = 700325,
          Subtitle = "What lies between us cannot be set right with a few words. Now I serve as a Magistrate of Yingtian... and he, a Drifter. Our paths lie worlds apart."
        },
        [51104116] = {
          ContentEN = "Still, I thank you both. Forgive me for letting you down.",
          DialogueId = 51104116,
          GUID = "7FEF0D08",
          LookAt = {
            [1] = "100001:n(700325)",
            [2] = "700324:n(700325)",
