          SpeakNpcId = 700329,
          Subtitle = "You promise you won't get scared? There's been loads of strange things at my house! Like — thud! — books falling right off the shelf! I was way too scared to go near them...",
          TalkActionId = {
            [1] = "700329:Think_Start"
          }
        },
        [51105012] = {
