        [51105900] = {
          ContentEN = "Master! You must be the fated encounter I've been waiting for!",
          DialogueId = 51105900,
          GUID = "7FF031B8",
          LookAt = {
            [1] = "701005:n(0)"
          },
          NextOptions = {
            [1] = 51105901,
            [2] = 51105905,
            [3] = 51105909
          },
          SpeakNpcId = 701005,
          Subtitle = "Master! You must be the fated encounter I've been waiting for!"
        },
        [51105901] = {
          ContentEN = "What \"fated encounter\"? Am I supposed to get something out of this?",
          DialogueId = 51105901,
          GUID = "7FF031E2",
          ImprPlusId = 1206,
          NextDialogue = 51105902,
          Subtitle = "What \"fated encounter\"? Am I supposed to get something out of this?"
        },
        [51105902] = {
          ContentEN = "Huh? Of course not... The gains from a fated encounter aren't something you can share.",
          DialogueId = 51105902,
          GUID = "7FF0320C",
          NextDialogue = 51105903,
          SpeakNpcId = 701005,
          Subtitle = "Huh? Of course not... The gains from a fated encounter aren't something you can share.",
          TalkActionId = {
            [1] = "701005:Talk01_Start"
          }
        },
        [51105903] = {
          ContentEN = "Ah— wait. I get it. You're testing my character!",
          DialogueId = 51105903,
          GUID = "7FF03236",
          NextDialogue = 51105904,
          SpeakNpcId = 701005,
          Subtitle = "Ah— wait. I get it. You're testing my character!"
        },
        [51105904] = {
          ContentEN = "My mistake. I almost let a little greed cloud my mind. True martial skill should serve the world — how could I keep it to myself?",
          DialogueId = 51105904,
          GUID = "7FF03260",
          NextDialogue = 51105913,
          SpeakNpcId = 701005,
          Subtitle = "My mistake. I almost let a little greed cloud my mind. True martial skill should serve the world — how could I keep it to myself?",
          TalkActionId = {
            [1] = "701005:Talk01_End"
          }
        },
        [51105905] = {
          ContentEN = "Is this... some kind of role-playing?",
          DialogueId = 51105905,
          GUID = "7FF0328A",
          ImprPlusId = 1208,
          NextDialogue = 51105906,
          Subtitle = "Is this... some kind of role-playing?"
        },
        [51105906] = {
          ContentEN = "Huh? What's that supposed to mean?",
          DialogueId = 51105906,
          GUID = "7FF032B4",
          NextDialogue = 51105907,
          SpeakNpcId = 701005,
          Subtitle = "Huh? What's that supposed to mean?",
          TalkActionId = {
            [1] = "701005:Talk02_Start"
          }
        },
        [51105907] = {
          ContentEN = "Uh... it's a kind of game. People pretend to be characters in a story and act things out. You never did that as a kid?",
          DialogueId = 51105907,
          GUID = "7FF032DE",
          NextDialogue = 51105908,
          SpeakNpcId = 100001,
          Subtitle = "Uh... it's a kind of game. People pretend to be characters in a story and act things out. You never did that as a kid?"
        },
        [51105908] = {
          ContentEN = "Pretend? No way. If we're doing something, we do it for real. Pretending is dull.",
          DialogueId = 51105908,
          GUID = "7FF03308",
          NextDialogue = 51105913,
          SpeakNpcId = 701005,
          Subtitle = "Pretend? No way. If we're doing something, we do it for real. Pretending is dull.",
          TalkActionId = {
            [1] = "701005:Talk02_End"
          }
        },
        [51105909] = {
          ContentEN = "Right — one look at you and I can tell you're a once-in-a-century martial prodigy.",
          DialogueId = 51105909,
          GUID = "7FF03332",
          ImprPlusId = 1210,
          NextDialogue = 51105910,
          Subtitle = "Right — one look at you and I can tell you're a once-in-a-century martial prodigy."
        },
        [51105910] = {
          ContentEN = "Really?! I knew I was destined for greatness!",
          DialogueId = 51105910,
          GUID = "7FF0335C",
          NextDialogue = 51105911,
          SpeakNpcId = 701005,
          Subtitle = "Really?! I knew I was destined for greatness!"
        },
        [51105911] = {
          ContentEN = "Wait— no, no, I'm getting carried away. I'm shouting like a madman... how rude of me. Master, please allow me to bow to you!",
          DialogueId = 51105911,
          GUID = "7FF03386",
          NextDialogue = 51105912,
          SpeakNpcId = 701005,
          Subtitle = "Wait— no, no, I'm getting carried away. I'm shouting like a madman... how rude of me. Master, please allow me to bow to you!",
          TalkActionId = {
            [1] = "701005:Salute_Start"
          }
        },
        [51105912] = {
          ContentEN = "Hold on — I never agreed to be your master!",
          DialogueId = 51105912,
          GUID = "7FF033B0",
          NextDialogue = 51105913,
          SpeakNpcId = 100001,
          Subtitle = "Hold on — I never agreed to be your master!",
          TalkActionId = {
            [1] = "701005:Salute_End"
          }
        },
        [51105913] = {
          ContentEN = "So what exactly is this \"fated encounter\" you keep mentioning?",
          DialogueId = 51105913,
          GUID = "7FF033DA",
          NextDialogue = 51105914,
          SpeakNpcId = 100001,
          Subtitle = "So what exactly is this \"fated encounter\" you keep mentioning?"
        },
        [51105914] = {
          ContentEN = "Let me explain. A few days ago, I spotted two seasoned martial artists being chased by some vicious beast. I wanted to help, but I was too weak — I couldn't even catch up to them.",
          DialogueId = 51105914,
          GUID = "7FF03404",
          NextDialogue = 51105915,
          SpeakNpcId = 701005,
          Subtitle = "Let me explain. A few days ago, I spotted two seasoned martial artists being chased by some vicious beast. I wanted to help, but I was too weak — I couldn't even catch up to them.",
          TalkActionId = {
            [1] = "701005:Explain01_Start"
          }
        },
        [51105915] = {
          ContentEN = "After they ran past, I found this torn manual on the ground. I figured it had to contain some secret technique powerful enough to shake the martial world. Their trouble must've been because of it!",
          DialogueId = 51105915,
          GUID = "7FF0342E",
          NextDialogue = 51105916,
          SpeakNpcId = 701005,
          Subtitle = "After they ran past, I found this torn manual on the ground. I figured it had to contain some secret technique powerful enough to shake the martial world. Their trouble must've been because of it!"
        },
        [51105916] = {
          ContentEN = "I tried telling my shifu, but he completely lost it — said I was wasting my time on violent nonsense instead of studying. Then he sent me out to these barren hills to \"reflect on my actions\".",
          DialogueId = 51105916,
          GUID = "7FF03458",
          NextDialogue = 51105917,
          SpeakNpcId = 701005,
          Subtitle = "I tried telling my shifu, but he completely lost it — said I was wasting my time on violent nonsense instead of studying. Then he sent me out to these barren hills to \"reflect on my actions\".",
          TalkActionId = {
            [1] = "701005:Explain01_End"
          }
        },
        [51105917] = {
          ContentEN = "Studying...? So your shifu teaches literature, not martial arts?",
          DialogueId = 51105917,
          GUID = "7FF03482",
          NextDialogue = 51105918,
          SpeakNpcId = 100001,
          Subtitle = "Studying...? So your shifu teaches literature, not martial arts?"
        },
        [51105918] = {
          ContentEN = "I admit it — my heart's always been set on the martial path. But every time I bring up martial arts, people get all tense and start quoting things like \"To wound or kill — this must not be done.\"",
          DialogueId = 51105918,
          GUID = "7FF034AC",
          NextDialogue = 51105919,
          SpeakNpcId = 701005,
          Subtitle = "I admit it — my heart's always been set on the martial path. But every time I bring up martial arts, people get all tense and start quoting things like \"To wound or kill — this must not be done.\"",
          TalkActionId = {
            [1] = "701005:Talk01_Start"
          }
        },
        [51105919] = {
          ContentEN = "My family only hired a scholar to teach me. I've never even seen a real martial arts master.",
          DialogueId = 51105919,
          GUID = "7FF034D6",
          NextDialogue = 51105920,
          SpeakNpcId = 701005,
          Subtitle = "My family only hired a scholar to teach me. I've never even seen a real martial arts master."
        },
        [51105920] = {
          ContentEN = "My shifu doesn't know any martial arts himself, but he's always treated me kindly. Thinking back now, he must've thought the manual looked suspicious — that's probably why he was so upset.",
          DialogueId = 51105920,
          GUID = "7FF03500",
          NextDialogue = 51105921,
          SpeakNpcId = 701005,
          Subtitle = "My shifu doesn't know any martial arts himself, but he's always treated me kindly. Thinking back now, he must've thought the manual looked suspicious — that's probably why he was so upset."
        },
        [51105921] = {
          ContentEN = "(You take a look at the \"manual\". No matter how you look at it, it's just a martial-arts comic book — with BANNED stamped loudly across the cover.)",
          DialogueId = 51105921,
          GUID = "7FF0352A",
          NextDialogue = 51105922,
          Subtitle = "(You take a look at the \"manual\". No matter how you look at it, it's just a martial-arts comic book — with BANNED stamped loudly across the cover.)"
        },
        [51105922] = {
          ContentEN = "(With a bit of deduction, the whole situation becomes clear: someone out in the wild got attacked by a Sable Bi'an, dropped their comic, and this young man happened to pick it up.)",
          DialogueId = 51105922,
          GUID = "7FF03554",
          NextDialogue = 51105923,
          Subtitle = "(With a bit of deduction, the whole situation becomes clear: someone out in the wild got attacked by a Sable Bi'an, dropped their comic, and this young man happened to pick it up.)"
        },
        [51105923] = {
          ContentEN = "Still, meeting you turned my bad luck around. With your guidance, once I master great skills, I'll fight for justice, save the martial world, and stop Huaxu from falling apart!",
          DialogueId = 51105923,
          GUID = "7FF0357E",
          NextDialogue = 51105924,
          SpeakNpcId = 701005,
          Subtitle = "Still, meeting you turned my bad luck around. With your guidance, once I master great skills, I'll fight for justice, save the martial world, and stop Huaxu from falling apart!",
          TalkActionId = {
            [1] = "701005:Talk01_End"
          }
        },
        [51105924] = {
          ContentEN = "So... you picked up a random book, your teacher panicked, and now you're stuck out here doing \"self-reflection\"?",
          DialogueId = 51105924,
          GUID = "7FF035A8",
          NextDialogue = 51105925,
          SpeakNpcId = 100001,
          Subtitle = "So... you picked up a random book, your teacher panicked, and now you're stuck out here doing \"self-reflection\"?"
        },
        [51105925] = {
          ContentEN = "Exactly. You truly are perceptive, master.",
          DialogueId = 51105925,
          GUID = "7FF035D2",
          NextDialogue = 51105926,
          SpeakNpcId = 701005,
          Subtitle = "Exactly. You truly are perceptive, master.",
          TalkActionId = {
            [1] = "701005:Sigh_Start"
          }
        },
        [51105926] = {
          ContentEN = "I even tried everything the book said about fated encounters — throwing myself off cliffs to find hidden caves, triggering traps to stumble into ancient tombs... none of it worked.",
          DialogueId = 51105926,
          GUID = "7FF035FC",
          NextDialogue = 51105927,
          SpeakNpcId = 701005,
          Subtitle = "I even tried everything the book said about fated encounters — throwing myself off cliffs to find hidden caves, triggering traps to stumble into ancient tombs... none of it worked.",
          TalkActionId = {
            [1] = "701005:Sigh_End"
          }
        },
        [51105927] = {
          ContentEN = "This was the last method I hadn't tried yet, so I came to the spot mentioned in the book to wait for one... and then you appeared.",
          DialogueId = 51105927,
          GUID = "7FF03626",
          NextDialogue = 51105928,
          SpeakNpcId = 701005,
          Subtitle = "This was the last method I hadn't tried yet, so I came to the spot mentioned in the book to wait for one... and then you appeared."
        },
        [51105928] = {
          ContentEN = "Dressed in pristine white, drifting in like an immortal — you must be a true master! Your eyes must be hiding some extraordinary power — that's why you keep one concealed, isn't it? Please, allow me to bow to you!",
          DialogueId = 51105928,
          GUID = "7FF03650",
          NextDialogue = 51105929,
          SpeakNpcId = 701005,
          Subtitle = "Dressed in pristine white, drifting in like an immortal — you must be a true master! Your eyes must be hiding some extraordinary power — that's why you keep one concealed, isn't it? Please, allow me to bow to you!",
          TalkActionId = {
            [1] = "701005:Salute_Start"
          }
        },
        [51105929] = {
          ContentEN = "(He's completely swept up in his own fantasy — cliffs, caves, tombs... this is a whole new level of absurd.)",
          DialogueId = 51105929,
          GUID = "7FF0367A",
          NextDialogue = 51105930,
          Subtitle = "(He's completely swept up in his own fantasy — cliffs, caves, tombs... this is a whole new level of absurd.)"
        },
        [51105930] = {
          ContentEN = "(You've met people who are obsessed with stories before, but someone who mixes fiction with reality this thoroughly... that's a first.)",
          DialogueId = 51105930,
          GUID = "7FF036A4",
          NextDialogue = 51105931,
          Subtitle = "(You've met people who are obsessed with stories before, but someone who mixes fiction with reality this thoroughly... that's a first.)",
          TalkActionId = {
            [1] = "701005:Salute_End"
          }
        },
        [51105931] = {
          ContentEN = "(Faced with someone this ridiculous yet oddly sincere, the best approach might be to just...)",
          DialogueId = 51105931,
          GUID = "7FF036CE",
          NextOptions = {
            [1] = 51105932,
            [2] = 51105941
          },
          RestartTag = 51105931,
          Subtitle = "(Faced with someone this ridiculous yet oddly sincere, the best approach might be to just...)"
        },
        [51105932] = {
          ContentEN = "Masters who walk outside worldly norms don't fuss over rules anyway — and he is quite a character. What's the harm in teaching him a move or two?",
          DialogueId = 51105932,
          FailDialogue = 51105933,
          GUID = "7FF036F8",
          ImprCheckId = 1115,
          NextDialogue = 51105934,
          Subtitle = "Masters who walk outside worldly norms don't fuss over rules anyway — and he is quite a character. What's the harm in teaching him a move or two?"
        },
        [51105933] = {
          ContentEN = "(Real masters don't just accept disciples on a whim — better think it through.)",
          DialogueId = 51105933,
          GUID = "7FF03722",
          Subtitle = "(Real masters don't just accept disciples on a whim — better think it through.)"
        },
        [51105934] = {
          ContentEN = "In that case... why don't you start by cutting that waterfall in half?",
          DialogueId = 51105934,
          GUID = "7FF0374C",
          NextDialogue = 51105935,
          SpeakNpcId = 100001,
          Subtitle = "In that case... why don't you start by cutting that waterfall in half?"
        },
        [51105935] = {
          ContentEN = "Huh? M—Master, isn't cutting a waterfall a bit too much for a starter like me...?",
          DialogueId = 51105935,
          GUID = "7FF03776",
          NextDialogue = 51105936,
          SpeakNpcId = 701005,
          Subtitle = "Huh? M—Master, isn't cutting a waterfall a bit too much for a starter like me...?"
        },
        [51105936] = {
          ContentEN = "Ahem. Training in the great arts is never easy. If you back down at the first step, what will you do when things actually get difficult?",
          DialogueId = 51105936,
          GUID = "7FF037A0",
          NextDialogue = 51105937,
          SpeakNpcId = 100001,
          Subtitle = "Ahem. Training in the great arts is never easy. If you back down at the first step, what will you do when things actually get difficult?"
        },
        [51105937] = {
          ContentEN = "Y—You're right, but...",
          DialogueId = 51105937,
          GUID = "7FF037CA",
          NextDialogue = 51105938,
          SpeakNpcId = 701005,
          Subtitle = "Y—You're right, but...",
          TalkActionId = {
            [1] = "701005:Talk02_Start"
          }
        },
        [51105938] = {
          ContentEN = "Look at you — all hesitation and no resolve. How are you supposed to learn anything formidable like this? By whining?",
          DialogueId = 51105938,
          GUID = "7FF037F4",
          NextDialogue = 51105939,
          SpeakNpcId = 100001,
          Subtitle = "Look at you — all hesitation and no resolve. How are you supposed to learn anything formidable like this? By whining?"
        },
        [51105939] = {
          ContentEN = "I was ready to make an exception and give you a little guidance because you seemed sincere — but your willpower is disappointingly mediocre.",
          DialogueId = 51105939,
          GUID = "7FF0381E",
          NextDialogue = 51105940,
          SpeakNpcId = 100001,
          Subtitle = "I was ready to make an exception and give you a little guidance because you seemed sincere — but your willpower is disappointingly mediocre."
        },
        [51105940] = {
          ContentEN = "...You're right, master. I shouldn't shy away just because it's difficult. I'll head into the mountains and start training right now!",
          DialogueId = 51105940,
          GUID = "7FF03848",
          NextDialogue = 51105950,
          SpeakNpcId = 701005,
          Subtitle = "...You're right, master. I shouldn't shy away just because it's difficult. I'll head into the mountains and start training right now!",
          TalkActionId = {
            [1] = "701005:Talk02_End"
          }
        },
        [51105941] = {
          ContentEN = "Time to drag him back to reality.",
          DialogueId = 51105941,
          FailDialogue = 51105942,
          GUID = "7FF03872",
          ImprCheckId = 1116,
          NextDialogue = 51105943,
          Subtitle = "Time to drag him back to reality."
        },
        [51105942] = {
          ContentEN = "(Shattering someone's dream is always rough... better ease into it.)",
          DialogueId = 51105942,
          GUID = "7FF0389C",
          SpeakNpcId = 100001,
          Subtitle = "(Shattering someone's dream is always rough... better ease into it.)"
        },
        [51105943] = {
          ContentEN = "I think your shifu had a point.",
          DialogueId = 51105943,
          GUID = "7FF038C6",
          NextDialogue = 51105944,
          SpeakNpcId = 100001,
          Subtitle = "I think your shifu had a point."
        },
        [51105944] = {
          ContentEN = "Huh? Master, what do you mean...?",
          DialogueId = 51105944,
          GUID = "7FF038F0",
          NextDialogue = 51105945,
          SpeakNpcId = 701005,
          Subtitle = "Huh? Master, what do you mean...?",
          TalkActionId = {
            [1] = "701005:Talk02_Start"
          }
        },
        [51105945] = {
          ContentEN = "If you truly want to master great skills, you need real training. Sitting around waiting for miracles won't get you anywhere.",
          DialogueId = 51105945,
          GUID = "7FF0391A",
          NextDialogue = 51105946,
          SpeakNpcId = 100001,
          Subtitle = "If you truly want to master great skills, you need real training. Sitting around waiting for miracles won't get you anywhere."
        },
        [51105946] = {
          ContentEN = "Besides, Huaxu forbids violence. Even if you learned a whole arsenal of techniques, where would you use them? Push things too far and a Bi'an will show up to punish you.",
          DialogueId = 51105946,
          GUID = "7FF03944",
          NextDialogue = 51105947,
          SpeakNpcId = 100001,
          Subtitle = "Besides, Huaxu forbids violence. Even if you learned a whole arsenal of techniques, where would you use them? Push things too far and a Bi'an will show up to punish you."
        },
        [51105947] = {
          ContentEN = "Channel that energy into studying instead. Return the comic, clear things up with your shifu, and focus on your lessons. That's as much guidance as I can offer.",
          DialogueId = 51105947,
          GUID = "7FF0396E",
          NextDialogue = 51105948,
          SpeakNpcId = 100001,
          Subtitle = "Channel that energy into studying instead. Return the comic, clear things up with your shifu, and focus on your lessons. That's as much guidance as I can offer."
        },
        [51105948] = {
          ContentEN = "That's exactly what my shifu said... so everything in the book really is made up?",
          DialogueId = 51105948,
          GUID = "7FF03998",
          NextDialogue = 51105949,
          SpeakNpcId = 701005,
          Subtitle = "That's exactly what my shifu said... so everything in the book really is made up?",
          TalkActionId = {
            [1] = "701005:Talk02_End"
          }
        },
        [51105949] = {
          ContentEN = "But... but even if that's true... did you have to say it that harshly...?",
          DialogueId = 51105949,
          GUID = "7FF039C2",
          NextDialogue = 51105950,
          SpeakNpcId = 701005,
          Subtitle = "But... but even if that's true... did you have to say it that harshly...?"
        },
        [51105950] = {
          ContentEN = "(You watch the young man run off and give a small, satisfied nod. If he ever becomes someone remarkable, he'll probably remember the \"master\" who set him straight in these mountains.)",
          DialogueId = 51105950,
          GUID = "7FF039EC",
          LookAt = {
            [1] = "701005:n(701005)"
          },
          NextDialogue = 51105951,
          Scripts = "MoveTo{ActorId{701005},TargetPoint{\"LinghuNing_Target\"},MoveSpeed{200},Visibility{\"Hide\"}}",
          Subtitle = "(You watch the young man run off and give a small, satisfied nod. If he ever becomes someone remarkable, he'll probably remember the \"master\" who set him straight in these mountains.)"
        },
        [51105951] = {
          ContentEN = "(In short... well done, you.)",
          DialogueId = 51105951,
          GUID = "7FF03A16",
          Subtitle = "(In short... well done, you.)"
        },
        [51106000] = {
          ContentEN = "Keep looking... there must be something I've overlooked.",
          DialogueId = 51106000,
          GUID = "7FF04220",
          LookAt = {
            [1] = "701006:n(0)"
          },
          NextDialogue = 51106001,
          SpeakNpcId = 701006,
          Subtitle = "Keep looking... there must be something I've overlooked."
        },
        [51106001] = {
          ContentEN = "Are you searching for something?",
          DialogueId = 51106001,
          GUID = "7FF0424A",
          NextDialogue = 51106002,
          SpeakNpcId = 100001,
          Subtitle = "Are you searching for something?"
        },
        [51106002] = {
          ContentEN = "Hm? I didn't realise anyone else was nearby.",
          DialogueId = 51106002,
          GUID = "7FF04274",
          NextDialogue = 51106003,
          SpeakNpcId = 701006,
          Subtitle = "Hm? I didn't realise anyone else was nearby."
        },
        [51106003] = {
          ContentEN = "Friend, Sable Bi'an appear in this area rather frequently. It's not a place ordinary travellers should approach without caution.",
          DialogueId = 51106003,
          GUID = "7FF0429E",
          NextDialogue = 51106004,
          SpeakNpcId = 701006,
          Subtitle = "Friend, Sable Bi'an appear in this area rather frequently. It's not a place ordinary travellers should approach without caution."
        },
        [51106004] = {
          ContentEN = "Thanks for the warning. I've been here before — I can take care of myself.",
          DialogueId = 51106004,
          GUID = "7FF042C8",
          NextDialogue = 51106005,
          SpeakNpcId = 100001,
          Subtitle = "Thanks for the warning. I've been here before — I can take care of myself."
        },
        [51106005] = {
          ContentEN = "And you? Why take the risk of walking around here?",
          DialogueId = 51106005,
          GUID = "7FF042F2",
          NextDialogue = 51106006,
          SpeakNpcId = 100001,
          Subtitle = "And you? Why take the risk of walking around here?"
        },
        [51106006] = {
          ContentEN = "Exploring, investigating, searching for archaeological clues... call it what you will. In essence, I'm examining whether anything of historical value remains here.",
          DialogueId = 51106006,
          GUID = "7FF0431C",
          NextDialogue = 51106007,
          SpeakNpcId = 701006,
          Subtitle = "Exploring, investigating, searching for archaeological clues... call it what you will. In essence, I'm examining whether anything of historical value remains here.",
          TalkActionId = {
            [1] = "701006:Talk01_Start"
          }
        },
        [51106007] = {
          ContentEN = "Something valuable? So you're treasure-hunting for money?",
          DialogueId = 51106007,
          GUID = "7FF04346",
          NextDialogue = 51106008,
          SpeakNpcId = 100001,
          Subtitle = "Something valuable? So you're treasure-hunting for money?"
        },
        [51106008] = {
          ContentEN = "Haha. Many people do make a living that way, but please don't mistake me for one of them. I'm not seeking wealth. What I'm after is insight.",
          DialogueId = 51106008,
          GUID = "7FF04370",
          NextDialogue = 51106009,
          SpeakNpcId = 701006,
          Subtitle = "Haha. Many people do make a living that way, but please don't mistake me for one of them. I'm not seeking wealth. What I'm after is insight."
        },
        [51106009] = {
          ContentEN = "Fragments of old writings, components from ancient mechanisms... things others dismiss as worthless often contain hints. They help me piece together what might have taken place here.",
          DialogueId = 51106009,
          GUID = "7FF0439A",
          NextDialogue = 51106010,
          SpeakNpcId = 701006,
          Subtitle = "Fragments of old writings, components from ancient mechanisms... things others dismiss as worthless often contain hints. They help me piece together what might have taken place here.",
          TalkActionId = {
            [1] = "701006:Talk01_End"
          }
        },
        [51106010] = {
          ContentEN = "So, friend — do you know anything about the history of this place?",
          DialogueId = 51106010,
          GUID = "7FF043C4",
          NextOptions = {
            [1] = 51106011
          },
          RestartTag = 51106010,
          SpeakNpcId = 701006,
          Subtitle = "So, friend — do you know anything about the history of this place?"
        },
        [51106011] = {
          ContentEN = "(What happened here? You feel like someone mentioned it to you before.)",
          DialogueId = 51106011,
          FailDialogue = 51106012,
          GUID = "7FF043EE",
          ImprCheckId = 1117,
          NextDialogue = 51106013,
          Subtitle = "(What happened here? You feel like someone mentioned it to you before.)"
        },
        [51106012] = {
          ContentEN = "(If you're being honest, ancient history interests you far less than any treasure you can actually pick up.)",
          DialogueId = 51106012,
          GUID = "7FF04418",
          Subtitle = "(If you're being honest, ancient history interests you far less than any treasure you can actually pick up.)"
        },
        [51106013] = {
          ContentEN = "I vaguely remember — this used to be a battlefield, right? Two groups fought here and a lot of people died. That's why it gets so creepy at night... and all those ghost-story rumours.",
          DialogueId = 51106013,
          GUID = "7FF04442",
          NextDialogue = 51106014,
          SpeakNpcId = 100001,
          Subtitle = "I vaguely remember — this used to be a battlefield, right? Two groups fought here and a lot of people died. That's why it gets so creepy at night... and all those ghost-story rumours."
        },
        [51106014] = {
          ContentEN = "Precisely.",
          DialogueId = 51106014,
          GUID = "7FF0446C",
          NextDialogue = 51106015,
          SpeakNpcId = 701006,
          Subtitle = "Precisely.",
          TalkActionId = {
            [1] = "701006:Talk02_Start"
          }
        },
        [51106015] = {
          ContentEN = "I didn't expect an outlander to know anything about this place. Either your memory is impressive, or you have a genuine interest in these old events. See? People are drawn to history without even noticing it.",
          DialogueId = 51106015,
          GUID = "7FF04496",
          NextDialogue = 51106016,
          SpeakNpcId = 701006,
          Subtitle = "I didn't expect an outlander to know anything about this place. Either your memory is impressive, or you have a genuine interest in these old events. See? People are drawn to history without even noticing it."
        },
        [51106016] = {
          ContentEN = "So what actually happened here?",
          DialogueId = 51106016,
          GUID = "7FF044C0",
          NextDialogue = 51106017,
          SpeakNpcId = 100001,
          Subtitle = "So what actually happened here?"
        },
        [51106017] = {
          ContentEN = "This is where the Battle of Shuli took place. Several centuries ago, the Jishu Sect rose in revolt here, and the Xuanheng Sect sent forces to suppress them. In the end, none of them survived.",
          DialogueId = 51106017,
          GUID = "7FF044EA",
          NextDialogue = 51106018,
          SpeakNpcId = 701006,
          Subtitle = "This is where the Battle of Shuli took place. Several centuries ago, the Jishu Sect rose in revolt here, and the Xuanheng Sect sent forces to suppress them. In the end, none of them survived."
        },
        [51106018] = {
          ContentEN = "It left a considerable mark on Huaxu's history, influencing many decisions in the ages that followed — or so the official records state.",
          DialogueId = 51106018,
          GUID = "7FF04514",
          NextDialogue = 51106019,
          SpeakNpcId = 701006,
          Subtitle = "It left a considerable mark on Huaxu's history, influencing many decisions in the ages that followed — or so the official records state."
        },
        [51106019] = {
          ContentEN = "But the curious thing is that those records are rather vague about how it all began — almost as though something has been deliberately glossed over.",
          DialogueId = 51106019,
          GUID = "7FF0453E",
          NextOptions = {
            [1] = 51106020,
            [2] = 51106022
          },
          SpeakNpcId = 701006,
          Subtitle = "But the curious thing is that those records are rather vague about how it all began — almost as though something has been deliberately glossed over.",
          TalkActionId = {
            [1] = "701006:Talk02_End"
          }
        },
        [51106020] = {
          ContentEN = "So you think the official record isn't telling the whole truth?",
          DialogueId = 51106020,
          GUID = "7FF04568",
          ImprPlusId = 1208,
          NextDialogue = 51106021,
          Subtitle = "So you think the official record isn't telling the whole truth?"
        },
        [51106021] = {
          ContentEN = "Hah! I wouldn't frame it as doubt — I'd call it a hypothesis.",
          DialogueId = 51106021,
          GUID = "7FF04592",
          NextDialogue = 51106024,
          SpeakNpcId = 701006,
          Subtitle = "Hah! I wouldn't frame it as doubt — I'd call it a hypothesis."
        },
        [51106022] = {
          ContentEN = "Dig too deeply and you'll get silenced — that's how these stories usually go.",
          DialogueId = 51106022,
          GUID = "7FF045BC",
          ImprPlusId = 1210,
          NextDialogue = 51106023,
          Subtitle = "Dig too deeply and you'll get silenced — that's how these stories usually go."
        },
        [51106023] = {
          ContentEN = "Haha. You jest. Under the Nine Chapters of Dafeng, no one in Huaxu has to worry about matters like that — the Bi'an and the Magistrates of Yingtian will see to my safety.",
          DialogueId = 51106023,
          GUID = "7FF045E6",
          NextDialogue = 51106024,
          SpeakNpcId = 701006,
          Subtitle = "Haha. You jest. Under the Nine Chapters of Dafeng, no one in Huaxu has to worry about matters like that — the Bi'an and the Magistrates of Yingtian will see to my safety.",
          TalkActionId = {
            [1] = "701006:Explain01_Start"
          }
        },
        [51106024] = {
          ContentEN = "Even so, if the truth really were just what the official records claim, it wouldn't be nearly as intriguing.",
          DialogueId = 51106024,
          GUID = "7FF04610",
          NextDialogue = 51106025,
          SpeakNpcId = 701006,
          Subtitle = "Even so, if the truth really were just what the official records claim, it wouldn't be nearly as intriguing."
        },
        [51106025] = {
          ContentEN = "History shows only what it chooses to. Over time, the truth becomes distorted — shaped to serve the interests of whoever is recording it.",
          DialogueId = 51106025,
          GUID = "7FF0463A",
          NextDialogue = 51106026,
          SpeakNpcId = 701006,
          Subtitle = "History shows only what it chooses to. Over time, the truth becomes distorted — shaped to serve the interests of whoever is recording it."
        },
        [51106026] = {
          ContentEN = "So I prefer to take what little imagination I have and picture how events might actually have unfolded. Tell me, friend — what possibilities do you think there are?",
          DialogueId = 51106026,
          GUID = "7FF04664",
          NextOptions = {
            [1] = 51106027,
            [2] = 51106029,
            [3] = 51106031
          },
          SpeakNpcId = 701006,
          Subtitle = "So I prefer to take what little imagination I have and picture how events might actually have unfolded. Tell me, friend — what possibilities do you think there are?",
          TalkActionId = {
            [1] = "701006:Explain01_End"
          }
        },
        [51106027] = {
          ContentEN = "I'd sooner trust the records — unless there's clear evidence they're wrong.",
          DialogueId = 51106027,
          GUID = "7FF0468E",
          ImprPlusId = 1207,
          NextDialogue = 51106028,
          Subtitle = "I'd sooner trust the records — unless there's clear evidence they're wrong."
        },
        [51106028] = {
