          DialogueId = 51106028,
          GUID = "7FF046B8",
          NextDialogue = 51106033,
          SpeakNpcId = 701006,
          Subtitle = "A prudent and measured stance."
        },
        [51106029] = {
          ContentEN = "If we're making bold guesses... I'd say Xuanheng started it.",
          DialogueId = 51106029,
          GUID = "7FF046E2",
          ImprPlusId = 1206,
          NextDialogue = 51106030,
          Subtitle = "If we're making bold guesses... I'd say Xuanheng started it."
        },
        [51106030] = {
