          GUID = "7FF04736",
          ImprPlusId = 1210,
          NextDialogue = 51106032,
          Subtitle = "It was aliens disguised as humans who started it!"
        },
        [51106032] = {
          ContentEN = "Hah! Well, that's a possibility too.",
          DialogueId = 51106032,
          GUID = "7FF04760",
          NextDialogue = 51106033,
          SpeakNpcId = 701006,
          Subtitle = "Hah! Well, that's a possibility too."
        },
        [51106033] = {
          ContentEN = "But speculation is only the first step. To lift the veil, you need the second step — evidence.",
          DialogueId = 51106033,
          GUID = "7FF0478A",
          NextDialogue = 51106034,
          SpeakNpcId = 701006,
          Subtitle = "But speculation is only the first step. To lift the veil, you need the second step — evidence.",
          TalkActionId = {
            [1] = "701006:Think_Start"
          }
        },
        [51106034] = {
          ContentEN = "To test my hypothesis, I joined the Ministry of Works. It allowed me to gain a deeper understanding of how the mechapuppets function and to learn more about what truly happened back then.",
          DialogueId = 51106034,
          GUID = "7FF047B4",
          NextDialogue = 51106035,
          SpeakNpcId = 701006,
          Subtitle = "To test my hypothesis, I joined the Ministry of Works. It allowed me to gain a deeper understanding of how the mechapuppets function and to learn more about what truly happened back then."
        },
        [51106035] = {
          ContentEN = "The masters there didn't take offence when I told them my intentions. Instead, they said the Jishu Sect is short on young people like me these days — and so they simply kept me.",
          DialogueId = 51106035,
          GUID = "7FF047DE",
          NextDialogue = 51106036,
          SpeakNpcId = 701006,
          Subtitle = "The masters there didn't take offence when I told them my intentions. Instead, they said the Jishu Sect is short on young people like me these days — and so they simply kept me.",
          TalkActionId = {
            [1] = "701006:Think_End"
          }
        },
        [51106036] = {
          ContentEN = "You've done all this just to study the past?",
          DialogueId = 51106036,
          GUID = "7FF04808",
          NextDialogue = 51106037,
          SpeakNpcId = 100001,
          Subtitle = "You've done all this just to study the past?"
        },
        [51106037] = {
          ContentEN = "I can't say what any of it will ultimately amount to, but once I began, I simply couldn't stop. Different clues link together in ways you wouldn't expect. Perhaps they'll lead to the truth, perhaps not — but my curiosity won't let me ignore them.",
          DialogueId = 51106037,
          GUID = "7FF04832",
          NextDialogue = 51106038,
          SpeakNpcId = 701006,
          Subtitle = "I can't say what any of it will ultimately amount to, but once I began, I simply couldn't stop. Different clues link together in ways you wouldn't expect. Perhaps they'll lead to the truth, perhaps not — but my curiosity won't let me ignore them.",
          TalkActionId = {
            [1] = "701006:Explain01_Start"
          }
        },
        [51106038] = {
