        [51107017] = {
          ContentEN = "(The Wishen accepts the sweet with a gentle, careful motion and lifts it towards what might once have been its mouth.)",
          DialogueId = 51107017,
          GUID = "7FF0E8FA",
          NextDialogue = 51107018,
          Subtitle = "(The Wishen accepts the sweet with a gentle, careful motion and lifts it towards what might once have been its mouth.)"
        },
        [51107018] = {
          ContentEN = "(Its mirage-like form can hardly be called a body. You can't tell whether this gesture counts as eating — perhaps it's simply copying something it remembers from when it was alive.)",
          DialogueId = 51107018,
          GUID = "7FF0E924",
          NextDialogue = 51107019,
          Subtitle = "(Its mirage-like form can hardly be called a body. You can't tell whether this gesture counts as eating — perhaps it's simply copying something it remembers from when it was alive.)"
        },
