        [51107021] = {
          ContentEN = "Describe the taste of barley sugar for the Wishen.",
          DialogueId = 51107021,
          GUID = "7FF0E9A2",
          ImprPlusId = 1208,
          NextDialogue = 51107022,
          Subtitle = "Describe the taste of barley sugar for the Wishen."
        },
        [51107022] = {
          ContentEN = "It feels soft at first, but becomes chewy when you bite into it. As the sweetness melts, there's a light, grain-like aroma that follows.",
          DialogueId = 51107022,
          GUID = "7FF0E9CC",
          NextDialogue = 51107023,
          SpeakNpcId = 100001,
          Subtitle = "It feels soft at first, but becomes chewy when you bite into it. As the sweetness melts, there's a light, grain-like aroma that follows."
        },
        [51107023] = {
          ContentEN = "It's not as heavy or sugary as other sweets. It tastes gentle — like standing beside rice fields in early autumn, with the wind brushing through the stalks and carrying a faint scent of earth.",
          DialogueId = 51107023,
          GUID = "7FF0E9F6",
          NextDialogue = 51107024,
          SpeakNpcId = 100001,
          Subtitle = "It's not as heavy or sugary as other sweets. It tastes gentle — like standing beside rice fields in early autumn, with the wind brushing through the stalks and carrying a faint scent of earth."
        },
        [51107024] = {
          ContentEN = "I don't understand... But it sounds... nice. So... it's good?",
          DialogueId = 51107024,
          GUID = "7FF0EA20",
          NextDialogue = 51107025,
          SpeakNpcId = 701007,
          Subtitle = "I don't understand... But it sounds... nice. So... it's good?"
        },
        [51107025] = {
          ContentEN = "Yeah. It's a lovely taste.",
          DialogueId = 51107025,
          GUID = "7FF0EA4A",
          NextDialogue = 51107026,
          SpeakNpcId = 100001,
          Subtitle = "Yeah. It's a lovely taste."
        },
        [51107026] = {
          ContentEN = "My memories... blurry. When I was little, the other children ate sweets... and laughed. I wanted one too... but I had no money.",
          DialogueId = 51107026,
          GUID = "7FF0EA74",
          NextDialogue = 51107027,
          SpeakNpcId = 701007,
          Subtitle = "My memories... blurry. When I was little, the other children ate sweets... and laughed. I wanted one too... but I had no money."
        },
        [51107027] = {
          ContentEN = "When I grew up, there was work... a family to care for... no time. I kept thinking, \"next time... next time\".",
          DialogueId = 51107027,
          GUID = "7FF0EA9E",
          NextDialogue = 51107028,
          SpeakNpcId = 701007,
          Subtitle = "When I grew up, there was work... a family to care for... no time. I kept thinking, \"next time... next time\"."
        },
        [51107028] = {
          ContentEN = "When I got old, my teeth were gone... I couldn't eat sweets anymore... I could only buy them for the children.",
          DialogueId = 51107028,
          GUID = "7FF0EAC8",
          NextDialogue = 51107029,
          SpeakNpcId = 701007,
          Subtitle = "When I got old, my teeth were gone... I couldn't eat sweets anymore... I could only buy them for the children."
        },
        [51107029] = {
          ContentEN = "I wanted to try them... but everyone had duties. I couldn't be selfish... Sweets were for children... grown-ups had to work... keep going.",
          DialogueId = 51107029,
          GUID = "7FF0EAF2",
          NextDialogue = 51107030,
          SpeakNpcId = 701007,
          Subtitle = "I wanted to try them... but everyone had duties. I couldn't be selfish... Sweets were for children... grown-ups had to work... keep going."
        },
        [51107030] = {
          ContentEN = "But even then... I never forgot. Still curious... what it tasted like.",
          DialogueId = 51107030,
          GUID = "7FF0EB1C",
          NextDialogue = 51107031,
          SpeakNpcId = 701007,
          Subtitle = "But even then... I never forgot. Still curious... what it tasted like."
        },
        [51107031] = {
          ContentEN = "Everyone ate them... and smiled. It must be a taste... that makes people happy...",
          DialogueId = 51107031,
          GUID = "7FF0EB46",
          NextDialogue = 51107032,
          SpeakNpcId = 701007,
          Subtitle = "Everyone ate them... and smiled. It must be a taste... that makes people happy..."
        },
        [51107032] = {
          ContentEN = "You didn't have to shoulder everything alone. If you wanted a sweet, you could've just had one. No one would've blamed you.",
          DialogueId = 51107032,
          GUID = "7FF0EB70",
          NextDialogue = 51107033,
          SpeakNpcId = 100001,
          Subtitle = "You didn't have to shoulder everything alone. If you wanted a sweet, you could've just had one. No one would've blamed you."
        },
        [51107033] = {
          ContentEN = "I... could? I was... allowed?",
          DialogueId = 51107033,
          GUID = "7FF0EB9A",
          NextDialogue = 51107034,
          SpeakNpcId = 701007,
          Subtitle = "I... could? I was... allowed?"
