          DialogueId = 51112007,
          GUID = "7FF41BA6",
          NextDialogue = 51112008,
          Subtitle = "(The leader dips his head — a courtesy entirely out of place in the black market.)"
        },
        [51112008] = {
          ContentEN = "Since you've crossed paths with us, I'd best be clear — save you from any misunderstanding.",
          DialogueId = 51112008,
          GUID = "7FF41BD0",
          NextDialogue = 51112009,
          SpeakNpcId = 701013,
          Subtitle = "Since you've crossed paths with us, I'd best be clear — save you from any misunderstanding.",
          TalkActionId = {
            [1] = "701013:Explain01_Start"
          }
        },
        [51112009] = {
          ContentEN = "(Seeing the doubt in your eyes, Li Shi nods towards the man lying on the ground.)",
          DialogueId = 51112009,
          GUID = "7FF41BFA",
          NextDialogue = 51112010,
          Subtitle = "(Seeing the doubt in your eyes, Li Shi nods towards the man lying on the ground.)"
        },
        [51112010] = {
          ContentEN = "Not long ago he took a heavy loss in a deal. In the quarrel that followed, he lost his temper and lashed out — so he drew a Bi'an's punishment, and ended up half-dead like this.",
          DialogueId = 51112010,
          GUID = "7FF41C24",
          NextOptions = {
            [1] = 51112011
          },
          RestartTag = 51112011,
          SpeakNpcId = 701013,
          Subtitle = "Not long ago he took a heavy loss in a deal. In the quarrel that followed, he lost his temper and lashed out — so he drew a Bi'an's punishment, and ended up half-dead like this."
        },
        [51112011] = {
          ContentEN = "So... you're bringing your men to take revenge?",
          DialogueId = 51112011,
          FailDialogue = 51112012,
          GUID = "7FF41C4E",
          ImprCheckId = 1122,
          NextDialogue = 51112013,
          Subtitle = "So... you're bringing your men to take revenge?"
        },
        [51112012] = {
          ContentEN = "I'm afraid that's not something I can comment on.",
          DialogueId = 51112012,
          GUID = "7FF41C78",
          SpeakNpcId = 701013,
          Subtitle = "I'm afraid that's not something I can comment on."
        },
        [51112013] = {
          ContentEN = "Heh. The black market doesn't take revenge for anyone. You place your stake, you shoulder the consequences — Mr Qiu's rule. So the man swallows that bitter pill himself.",
          DialogueId = 51112013,
          GUID = "7FF41CA2",
          NextDialogue = 51112014,
          SpeakNpcId = 701013,
          Subtitle = "Heh. The black market doesn't take revenge for anyone. You place your stake, you shoulder the consequences — Mr Qiu's rule. So the man swallows that bitter pill himself."
        },
        [51112014] = {
          ContentEN = "Lose, and you bear the cost yourself. Whether you survive, and what you choose to do afterwards — that's no one else's concern.",
          DialogueId = 51112014,
          GUID = "7FF41CCC",
          NextDialogue = 51112015,
          SpeakNpcId = 701013,
          Subtitle = "Lose, and you bear the cost yourself. Whether you survive, and what you choose to do afterwards — that's no one else's concern.",
          TalkActionId = {
            [1] = "701013:Explain01_End"
          }
        },
        [51112015] = {
          ContentEN = "I thought you lot were the radical sort.",
          DialogueId = 51112015,
          GUID = "7FF41CF6",
          NextDialogue = 51112016,
          SpeakNpcId = 100001,
          Subtitle = "I thought you lot were the radical sort."
        },
        [51112016] = {
          ContentEN = "Many hold that same mistaken view. But the black market is, at its core, only loosely bound.",
          DialogueId = 51112016,
          GUID = "7FF41D20",
          NextDialogue = 51112017,
          SpeakNpcId = 701013,
          Subtitle = "Many hold that same mistaken view. But the black market is, at its core, only loosely bound.",
          TalkActionId = {
            [1] = "701013:Talk01_Start"
          }
        },
        [51112017] = {
          ContentEN = "Those who remain here are the ones who answer to no outside rules — and can afford the cost of that freedom.",
          DialogueId = 51112017,
          GUID = "7FF41D4A",
          NextDialogue = 51112018,
          SpeakNpcId = 701013,
          Subtitle = "Those who remain here are the ones who answer to no outside rules — and can afford the cost of that freedom."
        },
        [51112018] = {
          ContentEN = "We're not afraid of losing. You take the blow, you get back up. What we can't stand are the sore losers — bold and swaggering when things go their way, then crying for protection the moment they don't. There's no room for that sort of weakness here.",
          DialogueId = 51112018,
          GUID = "7FF41D74",
          NextDialogue = 51112019,
          SpeakNpcId = 701013,
          Subtitle = "We're not afraid of losing. You take the blow, you get back up. What we can't stand are the sore losers — bold and swaggering when things go their way, then crying for protection the moment they don't. There's no room for that sort of weakness here."
        },
        [51112019] = {
          ContentEN = "So, I trust you see what I'm saying — we're not out to avenge anyone.",
          DialogueId = 51112019,
          GUID = "7FF41D9E",
          NextDialogue = 51112020,
          SpeakNpcId = 701013,
          Subtitle = "So, I trust you see what I'm saying — we're not out to avenge anyone."
        },
        [51112020] = {
          ContentEN = "As for what we are doing... with the Scourge of Zhuyin ebbing, we're heading into the shadows it leaves behind — to take whatever profit's there. Nothing more.",
          DialogueId = 51112020,
          GUID = "7FF41DC8",
          NextDialogue = 51112021,
          SpeakNpcId = 701013,
          Subtitle = "As for what we are doing... with the Scourge of Zhuyin ebbing, we're heading into the shadows it leaves behind — to take whatever profit's there. Nothing more.",
          TalkActionId = {
            [1] = "701013:Talk01_End"
          }
        },
        [51112021] = {
          ContentEN = "(He moves off with his men, but after only a few steps he pauses and glances back.)",
          DialogueId = 51112021,
          GUID = "7FF41DF2",
          NextDialogue = 51112022,
          Subtitle = "(He moves off with his men, but after only a few steps he pauses and glances back.)"
        },
        [51112022] = {
          ContentEN = "Since you're Mr Qiu's guest, here's a piece of advice — free of charge.",
          DialogueId = 51112022,
          GUID = "7FF41E1C",
          NextDialogue = 51112023,
          SpeakNpcId = 701013,
          Subtitle = "Since you're Mr Qiu's guest, here's a piece of advice — free of charge.",
          TalkActionId = {
            [1] = "701013:Talk02_Start"
          }
        },
        [51112023] = {
          ContentEN = "Some things belong to no one. Those with the strength to claim them... may. Keep your eyes open — you might spot something worthwhile in Mistwharf. Farewell.",
          DialogueId = 51112023,
          GUID = "7FF41E46",
          SpeakNpcId = 701013,
          Subtitle = "Some things belong to no one. Those with the strength to claim them... may. Keep your eyes open — you might spot something worthwhile in Mistwharf. Farewell.",
          TalkActionId = {
            [1] = "701013:Talk02_End"
          }
        },
        [51112024] = {
          ContentEN = "My apologies for not greeting you properly. What brings you to the market today?",
          DialogueId = 51112024,
          GUID = "7FF41E70",
          SpeakNpcId = 701013,
          Subtitle = "My apologies for not greeting you properly. What brings you to the market today?"
        },
