        },
        [51113005] = {
          ContentEN = "Oi, what an odd youngster you are. You meet Huaxu's famed incense master — me — and instead of offering respect, you carry on like that. Terribly uncouth.",
          DialogueId = 51113005,
          GUID = "7FF4BF62",
          LookAt = {
