          GUID = "7FF4BFB6",
          ImprPlusId = 1206,
          NextDialogue = 51113008,
          Subtitle = "That's exactly what a swindler would say."
        },
        [51113008] = {
          ContentEN = "Now, now — let's set a few things straight.",
          DialogueId = 51113008,
          GUID = "7FF4BFE0",
          NextDialogue = 51113009,
          SpeakNpcId = 701014,
          Subtitle = "Now, now — let's set a few things straight.",
          TalkActionId = {
            [1] = "701014:Talk01_Start"
          }
        },
        [51113009] = {
          ContentEN = "Most people burn incense just to go through the motions, never realising the incense itself is an art.",
          DialogueId = 51113009,
          GUID = "7FF4C00A",
          NextDialogue = 51113010,
          SpeakNpcId = 701014,
          Subtitle = "Most people burn incense just to go through the motions, never realising the incense itself is an art."
        },
        [51113010] = {
          ContentEN = "Take these EverSpring sticks, for instance... hold on, another sniff...",
          DialogueId = 51113010,
          GUID = "7FF4C034",
          NextDialogue = 51113011,
          SpeakNpcId = 701014,
          Subtitle = "Take these EverSpring sticks, for instance... hold on, another sniff..."
        },
        [51113011] = {
          ContentEN = "Mmm~ That's got to be Emerald Sandalwood from around Starwharf, with a touch of Azure Mugwort and a bit of Dewgrass in the mix.",
          DialogueId = 51113011,
          GUID = "7FF4C05E",
          NextDialogue = 51113012,
          SpeakNpcId = 701014,
          Subtitle = "Mmm~ That's got to be Emerald Sandalwood from around Starwharf, with a touch of Azure Mugwort and a bit of Dewgrass in the mix."
        },
        [51113012] = {
          ContentEN = "Mistwharf's been Huaxu's harbour since forever. The waters here nurture people — and plants — like nowhere else. EverSpring incense uses whatever grows nearby. Brilliant work, truly.",
          DialogueId = 51113012,
          GUID = "7FF4C088",
          NextDialogue = 51113013,
          SpeakNpcId = 701014,
          Subtitle = "Mistwharf's been Huaxu's harbour since forever. The waters here nurture people — and plants — like nowhere else. EverSpring incense uses whatever grows nearby. Brilliant work, truly."
        },
