        [51119004] = {
          ContentEN = "Aye, fine — I made it up. Lord Argent's never said a word to me. But if I don't dress things up a bit, who's going to stop and listen? And should Lord Argent catch wind of it, I reckon he'll forgive a storyteller his little embellishments.",
          DialogueId = 51119004,
          GUID = "7FF89798",
          NextDialogue = 51119009,
          SpeakNpcId = 701026,
          Subtitle = "Aye, fine — I made it up. Lord Argent's never said a word to me. But if I don't dress things up a bit, who's going to stop and listen? And should Lord Argent catch wind of it, I reckon he'll forgive a storyteller his little embellishments."
        },
        [51119005] = {
          ContentEN = "Then you'd better earn it with a decent tale.",
          DialogueId = 51119005,
          GUID = "7FF897C2",
          ImprPlusId = 1206,
          NextDialogue = 51119006,
          Subtitle = "Then you'd better earn it with a decent tale."
        },
        [51119006] = {
          ContentEN = "True enough! I'm only asking for a small donation out of goodwill — no one's twisting arms here. Just seeing whether anyone's kind enough to help a thirsty storyteller — one favoured by Lord Argent — wet his throat.",
          DialogueId = 51119006,
          GUID = "7FF897EC",
          NextDialogue = 51119009,
          SpeakNpcId = 701026,
          Subtitle = "True enough! I'm only asking for a small donation out of goodwill — no one's twisting arms here. Just seeing whether anyone's kind enough to help a thirsty storyteller — one favoured by Lord Argent — wet his throat."
        },
        [51119007] = {
          ContentEN = "(Give him some silver for tea.)",
          DialogueId = 51119007,
          GUID = "7FF89816",
          ImprPlusId = 1209,
          NextDialogue = 51119008,
          Subtitle = "(Give him some silver for tea.)"
        },
        [51119008] = {
          ContentEN = "Many thanks, traveller — I'll remember the kindness.",
          DialogueId = 51119008,
          GUID = "7FF89840",
          NextDialogue = 51119009,
          SpeakNpcId = 701026,
          Subtitle = "Many thanks, traveller — I'll remember the kindness."
        },
        [51119009] = {
          ContentEN = "(A few generous onlookers toss over some silver coins. Before long, a tea-seller trots up with a clay pot. Quan Doutong snatches it up, takes a long, satisfied gulp, wipes his mouth, and carries on.)",
          DialogueId = 51119009,
          GUID = "7FF8986A",
          NextDialogue = 51119010,
          Subtitle = "(A few generous onlookers toss over some silver coins. Before long, a tea-seller trots up with a clay pot. Quan Doutong snatches it up, takes a long, satisfied gulp, wipes his mouth, and carries on.)"
        },
        [51119010] = {
          ContentEN = "Right then! Thanks for the tea. Now gather close — I've a brand-new tale fresh from the streets.",
          DialogueId = 51119010,
          GUID = "7FF89894",
          NextDialogue = 51119011,
          SpeakNpcId = 701026,
          Subtitle = "Right then! Thanks for the tea. Now gather close — I've a brand-new tale fresh from the streets.",
          TalkActionId = {
            [1] = "701026:Talk02_Start"
          }
        },
        [51119011] = {
          ContentEN = "Where's the busiest place in all Huaxu? Haojing, of course — and that's where our story begins. Tucked away in one of its narrow little lanes lived two households: the Lyus on one side, the Mas on the other.",
          DialogueId = 51119011,
          GUID = "7FF898BE",
          NextDialogue = 51119012,
          SpeakNpcId = 701026,
          Subtitle = "Where's the busiest place in all Huaxu? Haojing, of course — and that's where our story begins. Tucked away in one of its narrow little lanes lived two households: the Lyus on one side, the Mas on the other."
        },
        [51119012] = {
          ContentEN = "They usually rubbed along well enough — polite, neighbourly, never a harsh word. But then the Ministry of Fortune announced that, with so many old houses falling into disrepair, they were organising restoration works — which meant every household now had to report the size of its property.",
          DialogueId = 51119012,
          GUID = "7FF898E8",
          NextDialogue = 51119013,
          SpeakNpcId = 701026,
          Subtitle = "They usually rubbed along well enough — polite, neighbourly, never a harsh word. But then the Ministry of Fortune announced that, with so many old houses falling into disrepair, they were organising restoration works — which meant every household now had to report the size of its property."
        },
        [51119013] = {
          ContentEN = "And that, dear guests, is where things took a turn. The larger the area you reported, the more silver the Ministry would hand out for repairs. So both families — without comparing notes — began thinking the same thought: \"What if we just stretched the numbers a touch?\"",
          DialogueId = 51119013,
          GUID = "7FF89912",
          NextDialogue = 51119014,
          SpeakNpcId = 701026,
          Subtitle = "And that, dear guests, is where things took a turn. The larger the area you reported, the more silver the Ministry would hand out for repairs. So both families — without comparing notes — began thinking the same thought: \"What if we just stretched the numbers a touch?\""
        },
        [51119014] = {
          ContentEN = "The snag was that the strip of ground in the lane belonged to no one — not a single record said whose it was. And just like that, they were at a standstill.",
          DialogueId = 51119014,
          GUID = "7FF8993C",
          NextDialogue = 51119015,
          SpeakNpcId = 701026,
          Subtitle = "The snag was that the strip of ground in the lane belonged to no one — not a single record said whose it was. And just like that, they were at a standstill."
        },
        [51119015] = {
          ContentEN = "The Lyus said, \"Our pear tree throws its shade over the lane — so the land must be ours!\"",
          DialogueId = 51119015,
          GUID = "7FF89966",
          NextDialogue = 51119016,
          SpeakNpcId = 701026,
          Subtitle = "The Lyus said, \"Our pear tree throws its shade over the lane — so the land must be ours!\""
        },
        [51119016] = {
          ContentEN = "The Mas shot back, \"We've dried our spices there for years, and you never complained! That makes it ours!\"",
          DialogueId = 51119016,
          GUID = "7FF89990",
          NextDialogue = 51119017,
          SpeakNpcId = 701026,
          Subtitle = "The Mas shot back, \"We've dried our spices there for years, and you never complained! That makes it ours!\""
        },
        [51119017] = {
          ContentEN = "Soon enough they were bickering loud enough to shake the roof tiles loose. If not for the Nine Chapters of Dafeng, they'd have been rolling on the ground wrestling like street dogs.",
          DialogueId = 51119017,
          GUID = "7FF899BA",
          NextDialogue = 51119018,
          SpeakNpcId = 701026,
          Subtitle = "Soon enough they were bickering loud enough to shake the roof tiles loose. If not for the Nine Chapters of Dafeng, they'd have been rolling on the ground wrestling like street dogs.",
          TalkActionId = {
            [1] = "701026:Talk02_End"
          }
        },
        [51119018] = {
          ContentEN = "Each side had its reasons — so how could the dispute be settled?",
          DialogueId = 51119018,
          GUID = "7FF899E4",
          NextDialogue = 51119019,
          SpeakNpcId = 701026,
          Subtitle = "Each side had its reasons — so how could the dispute be settled?"
        },
        [51119019] = {
          ContentEN = "(He pauses dramatically, milking the moment.)",
          DialogueId = 51119019,
          GUID = "7FF89A0E",
          NextDialogue = 51119020,
          Subtitle = "(He pauses dramatically, milking the moment.)"
        },
        [51119020] = {
          ContentEN = "Now, remember — this is Haojing, a city full of folk who make their living sorting out neighbourly quarrels.",
          DialogueId = 51119020,
          GUID = "7FF89A38",
          NextDialogue = 51119021,
          SpeakNpcId = 701026,
          Subtitle = "Now, remember — this is Haojing, a city full of folk who make their living sorting out neighbourly quarrels.",
          TalkActionId = {
            [1] = "701026:Explain01_Start"
          }
        },
        [51119021] = {
          ContentEN = "So one such mediator caught wind of the fuss and hurried over at once. He hears them out, smiles, and rattles off a verse on the spot:",
          DialogueId = 51119021,
          GUID = "7FF89A62",
          NextDialogue = 51119022,
          SpeakNpcId = 701026,
          Subtitle = "So one such mediator caught wind of the fuss and hurried over at once. He hears them out, smiles, and rattles off a verse on the spot:"
        },
        [51119022] = {
          ContentEN = "\"The black loong stirs up the worst in men; Lord Argent's wrath checks greed and pain. Rows flare bright then fade in vain — yield three feet, and peace shall remain.\"",
          DialogueId = 51119022,
          GUID = "7FF89A8C",
          NextDialogue = 51119023,
          SpeakNpcId = 701026,
          Subtitle = "\"The black loong stirs up the worst in men; Lord Argent's wrath checks greed and pain. Rows flare bright then fade in vain — yield three feet, and peace shall remain.\""
        },
        [51119023] = {
          ContentEN = "Aha! See his point, good folk? He likened the two families to that wicked black loong of legend — saying they'd forgotten Lord Argent's teachings!",
          DialogueId = 51119023,
          GUID = "7FF89AB6",
          NextDialogue = 51119024,
          SpeakNpcId = 701026,
          Subtitle = "Aha! See his point, good folk? He likened the two families to that wicked black loong of legend — saying they'd forgotten Lord Argent's teachings!"
        },
        [51119024] = {
          ContentEN = "Even Zhuyin was sealed away by Lord Argent for its wickedness — so why should decent folk in fair Huaxu behave with such greed and temper today? Hearing that, both families fell silent. Their faces went red as cooked prawns, and they slunk back home without another word.",
          DialogueId = 51119024,
          GUID = "7FF89AE0",
          NextDialogue = 51119025,
          SpeakNpcId = 701026,
          Subtitle = "Even Zhuyin was sealed away by Lord Argent for its wickedness — so why should decent folk in fair Huaxu behave with such greed and temper today? Hearing that, both families fell silent. Their faces went red as cooked prawns, and they slunk back home without another word."
        },
        [51119025] = {
          ContentEN = "To show they truly meant to make peace, the Lyus pulled down their front wall and rebuilt it three feet further in — even set up a little statue of Lord Argent by the gate. The Mas saw that and did exactly the same.",
          DialogueId = 51119025,
          GUID = "7FF89B0A",
          NextDialogue = 51119026,
          SpeakNpcId = 701026,
          Subtitle = "To show they truly meant to make peace, the Lyus pulled down their front wall and rebuilt it three feet further in — even set up a little statue of Lord Argent by the gate. The Mas saw that and did exactly the same."
        },
        [51119026] = {
          ContentEN = "And just like that — harmony restored! In time, that very lane became the place neighbours went whenever a quarrel arose, letting Lord Argent witness their goodwill for themself.",
          DialogueId = 51119026,
          GUID = "7FF89B34",
          NextDialogue = 51119027,
          SpeakNpcId = 701026,
          Subtitle = "And just like that — harmony restored! In time, that very lane became the place neighbours went whenever a quarrel arose, letting Lord Argent witness their goodwill for themself."
        },
        [51119027] = {
          ContentEN = "And today, allow me to tweak that verse a touch — like so: \"To show that virtue dwells within the heart — yield three feet, and goodwill speaks for itself.\" What say you, folks?",
          DialogueId = 51119027,
          GUID = "7FF89B5E",
          NextDialogue = 51119028,
          SpeakNpcId = 701026,
          Subtitle = "And today, allow me to tweak that verse a touch — like so: \"To show that virtue dwells within the heart — yield three feet, and goodwill speaks for itself.\" What say you, folks?",
          TalkActionId = {
            [1] = "701026:Explain01_End"
          }
        },
        [51119028] = {
          ContentEN = "(The crowd breaks into cheerful applause, praising Lord Argent. A fresh handful of coins slips into Quan Doutong's palms as people wander off in twos and threes.)",
          DialogueId = 51119028,
          GUID = "7FF89B88",
          Scripts = [[
PARA{
MoveTo{ActorId{701081},TargetPoint{"quandoutong_show1"},MoveSpeed{100},Visibility{"Hide"}},
MoveTo{ActorId{701082},TargetPoint{"quandoutong_show2"},MoveSpeed{100},Visibility{"Hide"}},
MoveTo{ActorId{701083},TargetPoint{"quandoutong_show3"},MoveSpeed{100},Visibility{"Hide"}},
