MoveTo{ActorId{701085},TargetPoint{"quandoutong_show5"},MoveSpeed{100},Visibility{"Hide"}},
MoveTo{ActorId{701086},TargetPoint{"quandoutong_show6"},MoveSpeed{100},Visibility{"Hide"}}
}]],
          Subtitle = "(The crowd breaks into cheerful applause, praising Lord Argent. A fresh handful of coins slips into Quan Doutong's palms as people wander off in twos and threes.)"
        },
        [51119029] = {
          ContentEN = "If you've got a few coins to spare, toss them in. If not, a bit of applause'll do!",
          DialogueId = 51119029,
          GUID = "7FF89BB2",
          SpeakNpcId = 701026,
          Subtitle = "If you've got a few coins to spare, toss them in. If not, a bit of applause'll do!"
        },
        [51120000] = {
          ContentEN = "Apothecary Huang, is there anything I need to watch out for after taking this? Any foods I should avoid?",
          DialogueId = 51120000,
          GUID = "7FF93B00",
          LookAt = {
            [1] = "701028:n(701027)",
            [2] = "701027:n(701028)"
          },
          NextDialogue = 51120001,
          SpeakNpcId = 701028,
          Subtitle = "Apothecary Huang, is there anything I need to watch out for after taking this? Any foods I should avoid?",
          TalkActionId = {
            [1] = "701028:Talk01_Start"
          }
        },
        [51120001] = {
          ContentEN = "Of course there are. And mind you — whether it works or not depends entirely on how well you follow what I'm about to tell you.",
          DialogueId = 51120001,
          GUID = "7FF93B2A",
          NextDialogue = 51120002,
          SpeakNpcId = 701027,
          Subtitle = "Of course there are. And mind you — whether it works or not depends entirely on how well you follow what I'm about to tell you.",
          TalkActionId = {
            [1] = "701028:Talk01_End"
          }
        },
        [51120002] = {
          ContentEN = "First, don't take it on an empty stomach. Do that, and you'll end up putting on weight instead of losing it. You must eat three proper meals a day — at least enough so you're not hungry — before taking it.",
          DialogueId = 51120002,
          GUID = "7FF93B54",
          NextDialogue = 51120003,
          SpeakNpcId = 701027,
          Subtitle = "First, don't take it on an empty stomach. Do that, and you'll end up putting on weight instead of losing it. You must eat three proper meals a day — at least enough so you're not hungry — before taking it.",
          TalkActionId = {
            [1] = "701027:Talk02_Start"
          }
        },
        [51120003] = {
          ContentEN = "Second, the side effects are strong, so you'll need to exercise properly. I'll give you a booklet. Follow the routine in it and work out for an hour every day, until you're sweating. That's the only way to clear the side effects.",
          DialogueId = 51120003,
          GUID = "7FF93B7E",
          NextDialogue = 51120004,
          SpeakNpcId = 701027,
          Subtitle = "Second, the side effects are strong, so you'll need to exercise properly. I'll give you a booklet. Follow the routine in it and work out for an hour every day, until you're sweating. That's the only way to clear the side effects."
        },
        [51120004] = {
          ContentEN = "Third, don't stop midway. You only bought one month's supply. Once you finish it, come straight back for the next batch. If you interrupt the course, everything you achieved in the first month will be wasted, and you'll have to start from scratch!",
          DialogueId = 51120004,
          GUID = "7FF93BA8",
          NextDialogue = 51120005,
          SpeakNpcId = 701027,
          Subtitle = "Third, don't stop midway. You only bought one month's supply. Once you finish it, come straight back for the next batch. If you interrupt the course, everything you achieved in the first month will be wasted, and you'll have to start from scratch!"
        },
        [51120005] = {
          ContentEN = "That's all. Understood?",
          DialogueId = 51120005,
          GUID = "7FF93BD2",
          NextDialogue = 51120006,
          SpeakNpcId = 701027,
          Subtitle = "That's all. Understood?",
          TalkActionId = {
            [1] = "701027:Talk02_End"
          }
        },
        [51120006] = {
          ContentEN = "I... I think so. But with rules this strict... can you really guarantee I'll be as thin as a whip in three months?",
          DialogueId = 51120006,
          GUID = "7FF93BFC",
          NextDialogue = 51120007,
          SpeakNpcId = 701028,
          Subtitle = "I... I think so. But with rules this strict... can you really guarantee I'll be as thin as a whip in three months?",
          TalkActionId = {
            [1] = "701028:Think_Start"
          }
        },
        [51120007] = {
          ContentEN = "Ah, Yan, when have I ever lied to anyone? If my remedies didn't work wonders, how would you have found your way to me?",
          DialogueId = 51120007,
          GUID = "7FF93C26",
          NextDialogue = 51120008,
          SpeakNpcId = 701027,
          Subtitle = "Ah, Yan, when have I ever lied to anyone? If my remedies didn't work wonders, how would you have found your way to me?"
        },
        [51120008] = {
          ContentEN = "W—Well... that's true... I get it now. I will lose weight this time!",
          DialogueId = 51120008,
          GUID = "7FF93C50",
          NextDialogue = 51120009,
          SpeakNpcId = 701028,
          Subtitle = "W—Well... that's true... I get it now. I will lose weight this time!",
          TalkActionId = {
            [1] = "701028:Think_End"
          }
        },
        [51120009] = {
          ContentEN = "(Clutching the phial to her chest, the girl called Yan dashed off, full of excitement.)",
          DialogueId = 51120009,
          GUID = "7FF93C7A",
          NextDialogue = 51120010,
          Scripts = "MoveTo{ActorId{701028},TargetPoint{\"LuoYan_Target\"},MoveSpeed{200},Visibility{\"Hide\"}}",
          Subtitle = "(Clutching the phial to her chest, the girl called Yan dashed off, full of excitement.)"
        },
        [51120010] = {
          ContentEN = "You're a patient one, guest — waiting here all this time. So then, what sort of draught are you after? A tonic for your health? Or, like that girl just now, something to slim the figure?",
          DialogueId = 51120010,
          GUID = "7FF93CA4",
          LookAt = {
            [1] = "701027:n(0)"
          },
          NextOptions = {
            [1] = 51120011,
            [2] = 51120013,
            [3] = 51120015
          },
          SpeakNpcId = 701027,
          Subtitle = "You're a patient one, guest — waiting here all this time. So then, what sort of draught are you after? A tonic for your health? Or, like that girl just now, something to slim the figure?"
        },
        [51120011] = {
          ContentEN = "She could lose weight without the medicine if she really follows your rules, couldn't she?",
          DialogueId = 51120011,
          GUID = "7FF93CCE",
          ImprPlusId = 1208,
          NextDialogue = 51120012,
          Subtitle = "She could lose weight without the medicine if she really follows your rules, couldn't she?"
        },
        [51120012] = {
          ContentEN = "Oh? Sharp, aren't you. You're right — if she truly sticks to the instructions, she'll see results in two months, three at most.",
          DialogueId = 51120012,
          GUID = "7FF93CF8",
          NextDialogue = 51120017,
          SpeakNpcId = 701027,
          Subtitle = "Oh? Sharp, aren't you. You're right — if she truly sticks to the instructions, she'll see results in two months, three at most."
        },
        [51120013] = {
          ContentEN = "You'd better not be flogging quack medicine to rip people off.",
          DialogueId = 51120013,
          GUID = "7FF93D22",
          ImprPlusId = 1207,
          NextDialogue = 51120014,
          Subtitle = "You'd better not be flogging quack medicine to rip people off."
        },
        [51120014] = {
          ContentEN = "Quack? Now why jump to that? She hasn't even taken a single dose yet, and you've seen no results. Isn't it a bit early to start throwing accusations?",
          DialogueId = 51120014,
          GUID = "7FF93D4C",
          NextDialogue = 51120017,
          SpeakNpcId = 701027,
          Subtitle = "Quack? Now why jump to that? She hasn't even taken a single dose yet, and you've seen no results. Isn't it a bit early to start throwing accusations?"
        },
        [51120015] = {
          ContentEN = "Sounds like you owe me some hush money.",
          DialogueId = 51120015,
          GUID = "7FF93D76",
          ImprPlusId = 1206,
          NextDialogue = 51120016,
          Subtitle = "Sounds like you owe me some hush money."
        },
        [51120016] = {
          ContentEN = "Hush money? For what, exactly? I'm running an honest business, nothing against the Nine Chapters of Dafeng. Why would I have to pay anyone to keep quiet?",
          DialogueId = 51120016,
          GUID = "7FF93DA0",
          NextDialogue = 51120017,
          SpeakNpcId = 701027,
          Subtitle = "Hush money? For what, exactly? I'm running an honest business, nothing against the Nine Chapters of Dafeng. Why would I have to pay anyone to keep quiet?"
        },
        [51120017] = {
          ContentEN = "So what exactly did you sell her?",
          DialogueId = 51120017,
          GUID = "7FF93DCA",
          NextDialogue = 51120018,
          SpeakNpcId = 100001,
          Subtitle = "So what exactly did you sell her?"
        },
        [51120018] = {
          ContentEN = "Since you've already figured it out, why bother asking? I sold her a draught to make her wish come true — one that'll bring about exactly what her heart desires.",
          DialogueId = 51120018,
          GUID = "7FF93DF4",
          NextDialogue = 51120019,
          SpeakNpcId = 701027,
          Subtitle = "Since you've already figured it out, why bother asking? I sold her a draught to make her wish come true — one that'll bring about exactly what her heart desires.",
          TalkActionId = {
            [1] = "701027:Explain01_Start"
          }
        },
        [51120019] = {
          ContentEN = "...So it is quack medicine, then? What if she gets sick from it?",
          DialogueId = 51120019,
          GUID = "7FF93E1E",
          NextDialogue = 51120020,
          SpeakNpcId = 100001,
          Subtitle = "...So it is quack medicine, then? What if she gets sick from it?"
        },
        [51120020] = {
          ContentEN = "Heh, you've a kind heart, I'll give you that. But I'm no cut-throat poisoning people for profit. The young lady's perfectly healthy — yet she's determined to starve herself and gulp down potions to lose weight. Not wise.",
          DialogueId = 51120020,
          GUID = "7FF93E48",
          NextDialogue = 51120021,
          SpeakNpcId = 701027,
          Subtitle = "Heh, you've a kind heart, I'll give you that. But I'm no cut-throat poisoning people for profit. The young lady's perfectly healthy — yet she's determined to starve herself and gulp down potions to lose weight. Not wise.",
          TalkActionId = {
            [1] = "701027:Explain01_End"
          }
        },
        [51120021] = {
          ContentEN = "So I told her to keep a proper diet, and gave her some supplements to prevent her from fainting after her workouts.",
          DialogueId = 51120021,
          GUID = "7FF93E72",
          NextDialogue = 51120022,
          SpeakNpcId = 701027,
          Subtitle = "So I told her to keep a proper diet, and gave her some supplements to prevent her from fainting after her workouts.",
          TalkActionId = {
            [1] = "701027:Talk01_Start"
          }
        },
        [51120022] = {
          ContentEN = "You really do know your stuff, huh?",
          DialogueId = 51120022,
          GUID = "7FF93E9C",
          NextDialogue = 51120023,
          SpeakNpcId = 100001,
          Subtitle = "You really do know your stuff, huh?"
        },
        [51120023] = {
          ContentEN = "Me? I'd hardly claim that. I'm just a small-time apothecary making ends meet in this black market.",
          DialogueId = 51120023,
          GUID = "7FF93EC6",
          NextDialogue = 51120024,
          SpeakNpcId = 701027,
          Subtitle = "Me? I'd hardly claim that. I'm just a small-time apothecary making ends meet in this black market.",
          TalkActionId = {
            [1] = "701027:Talk01_End"
          }
        },
        [51120024] = {
          ContentEN = "So you do this with your other medicines too? Just hand out supplements instead?",
          DialogueId = 51120024,
          GUID = "7FF93EF0",
          NextDialogue = 51120025,
          SpeakNpcId = 100001,
          Subtitle = "So you do this with your other medicines too? Just hand out supplements instead?"
        },
        [51120025] = {
          ContentEN = "You people do love digging until you hit the bottom, don't you? Some things don't need such close inspection. I've never harmed anyone — I'm simply helping them take the right approach.",
          DialogueId = 51120025,
          GUID = "7FF93F1A",
          NextDialogue = 51120026,
          SpeakNpcId = 701027,
          Subtitle = "You people do love digging until you hit the bottom, don't you? Some things don't need such close inspection. I've never harmed anyone — I'm simply helping them take the right approach.",
          TalkActionId = {
            [1] = "701027:Talk02_Start"
          }
        },
        [51120026] = {
          ContentEN = "Those who seek longevity should rest well and eat well. Those who hope for beauty should mind their skin, keep themselves pleasant, and not push too hard. Guest, you're taking the word \"medicine\" far too rigidly.",
          DialogueId = 51120026,
          GUID = "7FF93F44",
          NextDialogue = 51120027,
          SpeakNpcId = 701027,
          Subtitle = "Those who seek longevity should rest well and eat well. Those who hope for beauty should mind their skin, keep themselves pleasant, and not push too hard. Guest, you're taking the word \"medicine\" far too rigidly."
        },
        [51120027] = {
