        },
        [51121006] = {
          ContentEN = "Are you blind? A perfectly decent young {性别：man|woman}, and you call {性别：him|her} old. You're making a fool of yourself. Best go home and have a lie-down.",
          DialogueId = 51121006,
          GUID = "7FF9E00C",
          LookAt = {
