          Subtitle = "All right, enough — stop it, both of you."
        },
        [51121018] = {
          ContentEN = "You heard him, didn't you? Sleeps through the day, clatters about all night — I never get any rest! I'm at home trying to write, my head's empty, my nerves are shot — and still his noise keeps me awake!",
          DialogueId = 51121018,
          GUID = "7FF9E204",
          NextDialogue = 51121019,
          SpeakNpcId = 701029,
          Subtitle = "You heard him, didn't you? Sleeps through the day, clatters about all night — I never get any rest! I'm at home trying to write, my head's empty, my nerves are shot — and still his noise keeps me awake!",
          TalkActionId = {
            [1] = "701029:Talk01_Start"
          }
        },
        [51121019] = {
          ContentEN = "What earth-shattering racket did I supposedly make? You're trying to police how I walk in my own home. Do you expect me to tiptoe around like a thief for your sake?",
          DialogueId = 51121019,
          GUID = "7FF9E22E",
          NextDialogue = 51121020,
          SpeakNpcId = 701030,
          Subtitle = "What earth-shattering racket did I supposedly make? You're trying to police how I walk in my own home. Do you expect me to tiptoe around like a thief for your sake?",
          TalkActionId = {
