            [2] = "701030:Talk02_Start"
          }
        },
        [51121020] = {
          ContentEN = "All right, all right... let me ask you first: why are you out at night and sleeping during the day?",
          DialogueId = 51121020,
          GUID = "7FF9E258",
          NextDialogue = 51121021,
          SpeakNpcId = 100001,
          Subtitle = "All right, all right... let me ask you first: why are you out at night and sleeping during the day?",
          TalkActionId = {
            [1] = "701030:Talk02_End"
          }
        },
        [51121021] = {
          ContentEN = "Me? I've got no choice. I'm a dock worker. The boss tells me when to shift cargo, and off I go. Lately all the jobs are at night. By the time we finish and I drag home, day's breaking.",
          DialogueId = 51121021,
          GUID = "7FF9E282",
          NextDialogue = 51121022,
          SpeakNpcId = 701030,
          Subtitle = "Me? I've got no choice. I'm a dock worker. The boss tells me when to shift cargo, and off I go. Lately all the jobs are at night. By the time we finish and I drag home, day's breaking.",
          TalkActionId = {
            [1] = "701030:Explain01_Start"
          }
        },
        [51121022] = {
          ContentEN = "Why take jobs at those dreadful hours?",
          DialogueId = 51121022,
          GUID = "7FF9E2AC",
          LookAt = {
