          SpeakNpcId = 701029,
          Subtitle = "Why take jobs at those dreadful hours?",
          TalkActionId = {
            [1] = "701029:Talk02_Start"
          }
        },
        [51121023] = {
          ContentEN = "Hah... you think the rest of us can sit about at home like you and still put food on the table? If I don't work, I don't earn — and the night shifts pay more.",
