          TalkActionId = {
            [1] = "701031:Talk01_Start"
          }
        },
        [51122007] = {
          ContentEN = "But seeing you up close — bright as a button — nothing wrong with you after all.",
          DialogueId = 51122007,
          GUID = "7FFA8446",
          NextDialogue = 51122008,
          SpeakNpcId = 701031,
          Subtitle = "But seeing you up close — bright as a button — nothing wrong with you after all.",
          TalkActionId = {
            [1] = "701031:Talk01_End"
          }
        },
        [51122008] = {
          ContentEN = "So... what do you want?",
          DialogueId = 51122008,
          GUID = "7FFA8470",
          NextDialogue = 51122009,
          SpeakNpcId = 100001,
          Subtitle = "So... what do you want?"
        },
        [51122009] = {
          ContentEN = "Easy, kid. Huaxu's not the sort of place that attracts shady types. I've just brewed a new jug and wanted someone to give it a taste.",
          DialogueId = 51122009,
          GUID = "7FFA849A",
          NextDialogue = 51122010,
          SpeakNpcId = 701031,
          Subtitle = "Easy, kid. Huaxu's not the sort of place that attracts shady types. I've just brewed a new jug and wanted someone to give it a taste.",
          TalkActionId = {
            [1] = "701031:Talk02_Start"
          }
        },
        [51122010] = {
          ContentEN = "Oh, I know that look. Let me explain — I'm a proper wine-seller. Go ask round town for Old Jug. Anyone who enjoys a decent drink will know the name.",
          DialogueId = 51122010,
          GUID = "7FFA84C4",
          NextDialogue = 51122011,
          SpeakNpcId = 701031,
          Subtitle = "Oh, I know that look. Let me explain — I'm a proper wine-seller. Go ask round town for Old Jug. Anyone who enjoys a decent drink will know the name."
        },
        [51122011] = {
          ContentEN = "Thing is, I've had an order in from a Starweaver — wants a whole batch of sweet rice wine sent all the way to Hyperborea, right on the far end of the continent.",
          DialogueId = 51122011,
          GUID = "7FFA84EE",
          NextDialogue = 51122012,
          SpeakNpcId = 701031,
          Subtitle = "Thing is, I've had an order in from a Starweaver — wants a whole batch of sweet rice wine sent all the way to Hyperborea, right on the far end of the continent."
        },
        [51122012] = {
          ContentEN = "But the moment I read it, I was stumped. It's got to be light, gentle, properly sweet... nothing like the strong, fiery stuff I usually brew. But the payment's generous — very generous.",
          DialogueId = 51122012,
          GUID = "7FFA8518",
          NextDialogue = 51122013,
          SpeakNpcId = 701031,
          Subtitle = "But the moment I read it, I was stumped. It's got to be light, gentle, properly sweet... nothing like the strong, fiery stuff I usually brew. But the payment's generous — very generous.",
          TalkActionId = {
            [1] = "701031:Talk02_End"
          }
        },
        [51122013] = {
          ContentEN = "So you made a new brew and now you need someone to test it.",
          DialogueId = 51122013,
          GUID = "7FFA8542",
          NextDialogue = 51122014,
          SpeakNpcId = 100001,
          Subtitle = "So you made a new brew and now you need someone to test it."
        },
        [51122014] = {
          ContentEN = "Sharp kid! Exactly. Nothing dodgy. As for this spiced rice wine, I used a special sticky rice, steamed it with cinnamon for a warm sweetness, then added tea leaves to lift the aroma and round out the flavour.",
          DialogueId = 51122014,
          GUID = "7FFA856C",
          NextDialogue = 51122015,
          SpeakNpcId = 701031,
          Subtitle = "Sharp kid! Exactly. Nothing dodgy. As for this spiced rice wine, I used a special sticky rice, steamed it with cinnamon for a warm sweetness, then added tea leaves to lift the aroma and round out the flavour.",
          TalkActionId = {
            [1] = "701031:Explain01_Start"
          }
        },
        [51122015] = {
          ContentEN = "And to finish, I had some sweet fruit from the southern hills brought in — crushed the pulp into juice, mixed it with fresh spring water, and spent three full days bringing the brew together.",
          DialogueId = 51122015,
          GUID = "7FFA8596",
          NextDialogue = 51122016,
          SpeakNpcId = 701031,
          Subtitle = "And to finish, I had some sweet fruit from the southern hills brought in — crushed the pulp into juice, mixed it with fresh spring water, and spent three full days bringing the brew together."
        },
        [51122016] = {
          ContentEN = "The old codgers I know drink nothing but burning spirits all day — their tongues can't taste a thing any more. I asked them, and all they said was \"too sweet\". With no one else to turn to, I've been waiting here for fate to send along someone with a proper palate.",
          DialogueId = 51122016,
          GUID = "7FFA85C0",
          NextDialogue = 51122017,
          SpeakNpcId = 701031,
          Subtitle = "The old codgers I know drink nothing but burning spirits all day — their tongues can't taste a thing any more. I asked them, and all they said was \"too sweet\". With no one else to turn to, I've been waiting here for fate to send along someone with a proper palate."
        },
        [51122017] = {
          ContentEN = "So, kid — will you try it? Don't fret, it's barely alcoholic. If you've things to do later, a sip won't muddle your head.",
          DialogueId = 51122017,
          GUID = "7FFA85EA",
          NextDialogue = 51122018,
          SpeakNpcId = 701031,
          Subtitle = "So, kid — will you try it? Don't fret, it's barely alcoholic. If you've things to do later, a sip won't muddle your head.",
          TalkActionId = {
            [1] = "701031:Explain01_End"
          }
        },
        [51122018] = {
          ContentEN = "All right. I'll give it a try.",
          DialogueId = 51122018,
          GUID = "7FFA8614",
          NextOptions = {
            [1] = 51122019
          },
          RestartTag = 51122018,
          SpeakNpcId = 100001,
