          SpeakNpcId = 100001,
          Subtitle = "(I... can't quite place the flavour.)"
        },
        [51122021] = {
          ContentEN = "It's sweet on the tongue, almost like honey, and there's a faint fragrance as it goes down... a lovely brew.",
          DialogueId = 51122021,
          GUID = "7FFA8692",
          NextDialogue = 51122022,
          SpeakNpcId = 100001,
          Subtitle = "It's sweet on the tongue, almost like honey, and there's a faint fragrance as it goes down... a lovely brew."
        },
        [51122022] = {
          ContentEN = "Ha! You're sweeter than the wine, kid. Hearing that warms my heart. Makes all those days of fretting over the order worth it.",
          DialogueId = 51122022,
          GUID = "7FFA86BC",
          NextDialogue = 51122023,
          SpeakNpcId = 701031,
          Subtitle = "Ha! You're sweeter than the wine, kid. Hearing that warms my heart. Makes all those days of fretting over the order worth it.",
          TalkActionId = {
            [1] = "701031:Confident_Start"
          }
        },
        [51122023] = {
          ContentEN = "Why not just give the client something you already make?",
          DialogueId = 51122023,
          GUID = "7FFA86E6",
          NextDialogue = 51122024,
          SpeakNpcId = 100001,
          Subtitle = "Why not just give the client something you already make?"
        },
        [51122024] = {
          ContentEN = "Think about it — Hyperborea's a world away, yet that lass sent an order from across half the continent. She must trust my brewing.",
          DialogueId = 51122024,
          GUID = "7FFA8710",
          NextDialogue = 51122025,
          SpeakNpcId = 701031,
          Subtitle = "Think about it — Hyperborea's a world away, yet that lass sent an order from across half the continent. She must trust my brewing."
        },
        [51122025] = {
          ContentEN = "If I fobbed her off with any old brew, I'd only let her down — and drag my shop's good name through the mud.",
          DialogueId = 51122025,
          GUID = "7FFA873A",
          NextDialogue = 51122026,
          SpeakNpcId = 701031,
          Subtitle = "If I fobbed her off with any old brew, I'd only let her down — and drag my shop's good name through the mud."
        },
        [51122026] = {
          ContentEN = "But hearing your kind words takes a load off my mind. I reckon that foreign lass — Cami... something — will fancy this sweet brew.",
          DialogueId = 51122026,
          GUID = "7FFA8764",
          NextDialogue = 51122027,
          SpeakNpcId = 701031,
          Subtitle = "But hearing your kind words takes a load off my mind. I reckon that foreign lass — Cami... something — will fancy this sweet brew."
        },
        [51122027] = {
