          GUID = "7FFB2856",
          NextDialogue = 51123008,
          SpeakNpcId = 100001,
          Subtitle = "Not really. Just a bit of clumsy phrasing."
        },
        [51123008] = {
          ContentEN = "Hahaha! You're being too modest — that's miles better than anything I thought of. Tell me, {性别：lad|lass}, what brings you out to these fields?",
          DialogueId = 51123008,
