        },
        [51123013] = {
          ContentEN = "So... are you some sort of wandering bard?",
          DialogueId = 51123013,
          GUID = "7FFB2952",
          NextDialogue = 51123014,
          SpeakNpcId = 100001,
          Subtitle = "So... are you some sort of wandering bard?"
        },
        [51123014] = {
          ContentEN = "A wandering bard? That's a new one. No, nothing like that — I'm just a farmer. Look — this whole stretch is my family's land.",
          DialogueId = 51123014,
          GUID = "7FFB297C",
          NextDialogue = 51123015,
          SpeakNpcId = 701032,
          Subtitle = "A wandering bard? That's a new one. No, nothing like that — I'm just a farmer. Look — this whole stretch is my family's land.",
          TalkActionId = {
            [1] = "701032:Talk01_Start"
          }
        },
        [51123015] = {
          ContentEN = "For an old farmer like me, spinning a few lines of verse is just something to pass the time. Same as admiring flowers or watching a show.",
          DialogueId = 51123015,
          GUID = "7FFB29A6",
          NextDialogue = 51123016,
          SpeakNpcId = 701032,
          Subtitle = "For an old farmer like me, spinning a few lines of verse is just something to pass the time. Same as admiring flowers or watching a show."
        },
        [51123016] = {
          ContentEN = "Mind you, when I was young I did study hard for a few years, dreaming I might one day join one of the ministries and serve Lord Argent. Just thinking about it felt like a fine dream back then.",
          DialogueId = 51123016,
          GUID = "7FFB29D0",
          NextDialogue = 51123017,
          SpeakNpcId = 701032,
          Subtitle = "Mind you, when I was young I did study hard for a few years, dreaming I might one day join one of the ministries and serve Lord Argent. Just thinking about it felt like a fine dream back then."
        },
        [51123017] = {
          ContentEN = "And what stopped you?",
          DialogueId = 51123017,
          GUID = "7FFB29FA",
          NextDialogue = 51123018,
          SpeakNpcId = 701032,
          Subtitle = "And what stopped you?"
        },
        [51123018] = {
          ContentEN = "Up at dawn to cut the wheat, reaping till the fields run further than the eye can see; I work all day without a break, then head home for a little drink. I know my way round the fields — but ministry paperwork? I'd be staring at it till sundown.",
          DialogueId = 51123018,
          GUID = "7FFB2A24",
          NextDialogue = 51123019,
          SpeakNpcId = 701032,
          Subtitle = "Up at dawn to cut the wheat, reaping till the fields run further than the eye can see; I work all day without a break, then head home for a little drink. I know my way round the fields — but ministry paperwork? I'd be staring at it till sundown."
        },
        [51123019] = {
          ContentEN = "I can't make head nor tail of any of it — the debates in the Ministry of Rites, the bookkeeping in the Ministry of Fortune, the gadgets they fiddle with in the Ministry of Works. They'd never take someone like me — and even if they did, I'd be more trouble than help.",
          DialogueId = 51123019,
          GUID = "7FFB2A4E",
          NextDialogue = 51123020,
          SpeakNpcId = 701032,
          Subtitle = "I can't make head nor tail of any of it — the debates in the Ministry of Rites, the bookkeeping in the Ministry of Fortune, the gadgets they fiddle with in the Ministry of Works. They'd never take someone like me — and even if they did, I'd be more trouble than help.",
          TalkActionId = {
            [1] = "701032:Talk01_End"
          }
        },
        [51123020] = {
          ContentEN = "I see.",
          DialogueId = 51123020,
          GUID = "7FFB2A78",
          NextDialogue = 51123021,
          SpeakNpcId = 100001,
          Subtitle = "I see."
        },
        [51123021] = {
          ContentEN = "Still, I've no real complaints — making up a clumsy verse or two when I've got a moment, shooting the breeze with young folk, then heading home for some braised meat and a cup of rice wine with my lad... that's a fine enough life.",
          DialogueId = 51123021,
          GUID = "7FFB2AA2",
          NextDialogue = 51123022,
          SpeakNpcId = 701032,
          Subtitle = "Still, I've no real complaints — making up a clumsy verse or two when I've got a moment, shooting the breeze with young folk, then heading home for some braised meat and a cup of rice wine with my lad... that's a fine enough life.",
          TalkActionId = {
            [1] = "701032:Talk02_Start"
          }
        },
        [51123022] = {
          ContentEN = "Ah, look at the time. Good talking with you, {性别：lad|lass}. I'd better finish up and get myself home for a few drinks!",
          DialogueId = 51123022,
          GUID = "7FFB2ACC",
          SpeakNpcId = 701032,
          Subtitle = "Ah, look at the time. Good talking with you, {性别：lad|lass}. I'd better finish up and get myself home for a few drinks!",
          TalkActionId = {
            [1] = "701032:Talk02_End"
          }
        },
        [51123023] = {
          ContentEN = "Hoeing in the noonday heat, sweat falls to the earth at my feet... Now that's a poem!",
          DialogueId = 51123023,
          GUID = "7FFB2AF6",
          SpeakNpcId = 701032,
          Subtitle = "Hoeing in the noonday heat, sweat falls to the earth at my feet... Now that's a poem!"
