        [51125201] = {
          ContentEN = "Phew... that's the last of it. We're not short of anything, are we?",
          DialogueId = 51125201,
          GUID = "7FFC904A",
          NextDialogue = 51125202,
          SpeakNpcId = 701034,
          Subtitle = "Phew... that's the last of it. We're not short of anything, are we?"
        },
        [51125202] = {
          ContentEN = "Zhuang's off today — we've got to finish his load too.",
          DialogueId = 51125202,
          GUID = "7FFC9074",
          NextDialogue = 51125203,
          SpeakNpcId = 701035,
          Subtitle = "Zhuang's off today — we've got to finish his load too."
        },
        [51125203] = {
          ContentEN = "And why can't he haul it himself tomorrow?",
          DialogueId = 51125203,
          GUID = "7FFC909E",
          NextDialogue = 51125204,
          SpeakNpcId = 701034,
          Subtitle = "And why can't he haul it himself tomorrow?"
        },
        [51125204] = {
          ContentEN = "Says there's good news at home. When he's back, he's treating us to tea.",
          DialogueId = 51125204,
          GUID = "7FFC90C8",
          NextDialogue = 51125205,
          SpeakNpcId = 701035,
          Subtitle = "Says there's good news at home. When he's back, he's treating us to tea."
        },
        [51125205] = {
          ContentEN = "Ha! Celebrating without us, is he? I'll make him cough up a pot of his finest!",
          DialogueId = 51125205,
          GUID = "7FFC90F2",
          SpeakNpcId = 701034,
          Subtitle = "Ha! Celebrating without us, is he? I'll make him cough up a pot of his finest!"
        },
        [51125301] = {
          ContentEN = "You've got to admit, Huaxu's one of the safest places around. See those Bi'an patrols everywhere? The moment someone stirs up trouble, they pounce and bring them down.",
          DialogueId = 51125301,
          GUID = "7FFCA0B2",
          NextDialogue = 51125302,
          SpeakNpcId = 701036,
          Subtitle = "You've got to admit, Huaxu's one of the safest places around. See those Bi'an patrols everywhere? The moment someone stirs up trouble, they pounce and bring them down."
        },
        [51125302] = {
          ContentEN = "Hmph. Hyperborea's just as safe, I'll have you know. Ever heard of the Hyperborean Legion? The Empire's cavalry silences any whisper of rebellion.",
          DialogueId = 51125302,
          GUID = "7FFCA0DC",
          NextDialogue = 51125303,
          SpeakNpcId = 701037,
          Subtitle = "Hmph. Hyperborea's just as safe, I'll have you know. Ever heard of the Hyperborean Legion? The Empire's cavalry silences any whisper of rebellion."
        },
        [51125303] = {
          ContentEN = "Oh, come off it. Every Starweaver back from abroad says Hyperborea's always at war with the south. You call that safe?",
          DialogueId = 51125303,
          GUID = "7FFCA106",
          NextDialogue = 51125304,
          SpeakNpcId = 701036,
          Subtitle = "Oh, come off it. Every Starweaver back from abroad says Hyperborea's always at war with the south. You call that safe?"
        },
        [51125304] = {
          ContentEN = "Uh... well, that's how the Empire shows its might. We fight for peace, don't you see?",
          DialogueId = 51125304,
          GUID = "7FFCA130",
          NextDialogue = 51125305,
          SpeakNpcId = 701037,
          Subtitle = "Uh... well, that's how the Empire shows its might. We fight for peace, don't you see?"
        },
        [51125305] = {
          ContentEN = "Pfft. Then why did you come all the way to move to Huaxu, eh? Trust me, mate — keep a good heart here and Lord Argent will see you safe day in, day out.",
          DialogueId = 51125305,
          GUID = "7FFCA15A",
          SpeakNpcId = 701036,
          Subtitle = "Pfft. Then why did you come all the way to move to Huaxu, eh? Trust me, mate — keep a good heart here and Lord Argent will see you safe day in, day out."
        },
        [51125401] = {
          ContentEN = "This old tower's seen better days. I'd wager it was fine work of our sect once. Hard to watch it left to wind and rain, with no one to tend it...",
          DialogueId = 51125401,
          GUID = "7FFCB11A",
          NextOptions = {
            [1] = 51125402
          },
          SpeakNpcId = 701038,
          Subtitle = "This old tower's seen better days. I'd wager it was fine work of our sect once. Hard to watch it left to wind and rain, with no one to tend it..."
        },
        [51125402] = {
          ContentEN = "What was it for?",
          DialogueId = 51125402,
          GUID = "7FFCB144",
          NextDialogue = 51125403,
          Subtitle = "What was it for?"
        },
        [51125403] = {
          ContentEN = "Back in the day, our sect built it for the Starweavers — they called it a Tower of Divination. These days it's just forgotten scrap and rust.",
          DialogueId = 51125403,
          GUID = "7FFCB16E",
          NextOptions = {
            [1] = 51125404
          },
          SpeakNpcId = 701038,
          Subtitle = "Back in the day, our sect built it for the Starweavers — they called it a Tower of Divination. These days it's just forgotten scrap and rust."
        },
        [51125404] = {
          ContentEN = "Tower of Divination?",
          DialogueId = 51125404,
          GUID = "7FFCB198",
          NextDialogue = 51125405,
          Subtitle = "Tower of Divination?"
        },
        [51125405] = {
          ContentEN = "Right — for reading the heavens and charting omens and fortunes, or so they said. In truth, nothing so mystical: it helped them study the stars and forecast the days ahead.",
          DialogueId = 51125405,
          GUID = "7FFCB1C2",
          NextOptions = {
            [1] = 51125406
          },
          SpeakNpcId = 701038,
          Subtitle = "Right — for reading the heavens and charting omens and fortunes, or so they said. In truth, nothing so mystical: it helped them study the stars and forecast the days ahead."
        },
        [51125406] = {
          ContentEN = "Why was it abandoned?",
          DialogueId = 51125406,
          GUID = "7FFCB1EC",
          NextDialogue = 51125407,
          Subtitle = "Why was it abandoned?"
        },
        [51125407] = {
          ContentEN = "Ah, that's a long one. It began when the Jishu Sect fell on hard times — few were left to tend the towers, and the readings grew increasingly unreliable.",
          DialogueId = 51125407,
          GUID = "7FFCB216",
          NextDialogue = 51125408,
          SpeakNpcId = 701038,
          Subtitle = "Ah, that's a long one. It began when the Jishu Sect fell on hard times — few were left to tend the towers, and the readings grew increasingly unreliable."
        },
        [51125408] = {
          ContentEN = "Later, the Starweavers refined their Stellapasses — clever things. They could forecast the weather well enough on their own, so the towers were no longer needed.",
          DialogueId = 51125408,
          GUID = "7FFCB240",
          NextDialogue = 51125409,
          SpeakNpcId = 701038,
          Subtitle = "Later, the Starweavers refined their Stellapasses — clever things. They could forecast the weather well enough on their own, so the towers were no longer needed."
        },
        [51125409] = {
          ContentEN = "Still, if you ask me — had the Jishu Sect been what it was a century ago, these towers would have found new purposes by now.",
          DialogueId = 51125409,
          GUID = "7FFCB26A",
          NextDialogue = 51125410,
          SpeakNpcId = 701038,
          Subtitle = "Still, if you ask me — had the Jishu Sect been what it was a century ago, these towers would have found new purposes by now."
        },
        [51125410] = {
          ContentEN = "*sigh* It's long past now. No sense raking through the dust. Let it be.",
          DialogueId = 51125410,
          GUID = "7FFCB294",
          SpeakNpcId = 701038,
          Subtitle = "*sigh* It's long past now. No sense raking through the dust. Let it be."
        },
        [51125501] = {
          ContentEN = "Hey there, friend from afar — give us a bit of space, yeah?",
          DialogueId = 51125501,
          GUID = "7FFCC182",
          NextOptions = {
            [1] = 51125502,
            [2] = 51125505
          },
          SpeakNpcId = 701039,
          Subtitle = "Hey there, friend from afar — give us a bit of space, yeah?"
        },
        [51125502] = {
          ContentEN = "Ah, my bad.",
          DialogueId = 51125502,
          GUID = "7FFCC1AC",
          ImprPlusId = 1207,
          NextDialogue = 51125503,
          Subtitle = "Ah, my bad."
        },
        [51125503] = {
          ContentEN = "No worries at all. First time in Huaxu, eh? It's normal not to know your way around. If there's anything you don't get, just holler.",
          DialogueId = 51125503,
          GUID = "7FFCC1D6",
          NextDialogue = 51125504,
          SpeakNpcId = 701039,
          Subtitle = "No worries at all. First time in Huaxu, eh? It's normal not to know your way around. If there's anything you don't get, just holler."
        },
        [51125504] = {
          ContentEN = "I might not look like much, but I'm one of the best tallymen on Starwharf. Ask me anything — from the skies above to life on the streets — I've got it all down pat.",
          DialogueId = 51125504,
          GUID = "7FFCC200",
          SpeakNpcId = 701039,
          Subtitle = "I might not look like much, but I'm one of the best tallymen on Starwharf. Ask me anything — from the skies above to life on the streets — I've got it all down pat."
        },
        [51125505] = {
          ContentEN = "You don't own this road.",
          DialogueId = 51125505,
          GUID = "7FFCC22A",
          ImprPlusId = 1210,
          NextDialogue = 51125506,
          Subtitle = "You don't own this road."
        },
        [51125506] = {
          ContentEN = "Whoa there, friend from afar — no need to get all worked up! I'm just looking out for you. Porters come and go here all day, hauling heavy stuff. One wrong bump and you'll get hurt.",
          DialogueId = 51125506,
          GUID = "7FFCC254",
          NextDialogue = 51125507,
          SpeakNpcId = 701039,
          Subtitle = "Whoa there, friend from afar — no need to get all worked up! I'm just looking out for you. Porters come and go here all day, hauling heavy stuff. One wrong bump and you'll get hurt."
        },
        [51125507] = {
          ContentEN = "First time in Huaxu, eh? It's normal not to know your way around. If there's anything you don't get, just holler. I may just be a tallyman, but hey — I grew up here.",
          DialogueId = 51125507,
          GUID = "7FFCC27E",
          SpeakNpcId = 701039,
          Subtitle = "First time in Huaxu, eh? It's normal not to know your way around. If there's anything you don't get, just holler. I may just be a tallyman, but hey — I grew up here."
        },
        [51125508] = {
          ContentEN = "Fifty catties of Frostleaf, thirty of Vernal Prime — whoa, easy there! Those aromatics are rare stuff!",
          DialogueId = 51125508,
          GUID = "7FFCC2A8",
          NextDialogue = 51125509,
          Subtitle = "Fifty catties of Frostleaf, thirty of Vernal Prime — whoa, easy there! Those aromatics are rare stuff!"
        },
        [51125509] = {
          ContentEN = "Hey, look who it is! Still hanging around Starwharf, huh? What's this then — come to trade, young merchant? Or just curious to see how we tallymen earn our rice?",
          DialogueId = 51125509,
          GUID = "7FFCC2D2",
          NextOptions = {
            [1] = 51125510,
            [2] = 51125527
          },
          SpeakNpcId = 701039,
          Subtitle = "Hey, look who it is! Still hanging around Starwharf, huh? What's this then — come to trade, young merchant? Or just curious to see how we tallymen earn our rice?"
        },
        [51125510] = {
          ContentEN = "I have something to ask you.",
          DialogueId = 51125510,
          GUID = "7FFCC2FC",
          NextDialogue = 51125511,
          Subtitle = "I have something to ask you."
        },
        [51125511] = {
          ContentEN = "Ask away, friend! Anything I know, I'll share.",
          DialogueId = 51125511,
          GUID = "7FFCC326",
          NextOptions = {
            [1] = 51125512,
            [2] = 51125516
          },
          SpeakNpcId = 701039,
          Subtitle = "Ask away, friend! Anything I know, I'll share."
        },
        [51125512] = {
          ContentEN = "What's a tallyman do?",
          DialogueId = 51125512,
          GUID = "7FFCC350",
          NextDialogue = 51125513,
          Subtitle = "What's a tallyman do?"
        },
        [51125513] = {
          ContentEN = "Pretty much what the name says — we help the Starweavers keep track of their cargo.",
          DialogueId = 51125513,
          GUID = "7FFCC37A",
          NextDialogue = 51125514,
          SpeakNpcId = 701039,
          Subtitle = "Pretty much what the name says — we help the Starweavers keep track of their cargo."
        },
        [51125514] = {
          ContentEN = "You see, Starwharf's busy every day — ships coming and going nonstop. If the Starweavers had to handle all the counting, they'd never get a break.",
          DialogueId = 51125514,
          GUID = "7FFCC3A4",
          NextDialogue = 51125515,
          SpeakNpcId = 701039,
          Subtitle = "You see, Starwharf's busy every day — ships coming and going nonstop. If the Starweavers had to handle all the counting, they'd never get a break."
        },
        [51125515] = {
          ContentEN = "That's where we tallymen come in. We check what's coming and going, make sure nothing's short — otherwise the Starweavers would have a hard time explaining it to their buyers in distant lands.",
          DialogueId = 51125515,
          GUID = "7FFCC3CE",
          NextOptions = {
            [1] = 51125516,
            [2] = 51125527
          },
          SpeakNpcId = 701039,
          Subtitle = "That's where we tallymen come in. We check what's coming and going, make sure nothing's short — otherwise the Starweavers would have a hard time explaining it to their buyers in distant lands."
        },
        [51125516] = {
          ContentEN = "So the Starweavers here have to log everything coming in and out?",
          DialogueId = 51125516,
          GUID = "7FFCC3F8",
          NextDialogue = 51125517,
          Subtitle = "So the Starweavers here have to log everything coming in and out?"
        },
        [51125517] = {
          ContentEN = "Naturally! Trade's booming here in Huaxu, and the Ministry of Fortune's got rules — whatever comes in or goes out gets taxed.",
          DialogueId = 51125517,
          GUID = "7FFCC422",
          NextDialogue = 51125518,
          SpeakNpcId = 701039,
          Subtitle = "Naturally! Trade's booming here in Huaxu, and the Ministry of Fortune's got rules — whatever comes in or goes out gets taxed."
        },
        [51125518] = {
          ContentEN = "And some of the key incense materials — they've got strict limits. Take Skylilies, for instance: folks here burn a lot of it. If the Starweavers ship it all overseas, what are we supposed to do when we run short?",
          DialogueId = 51125518,
          GUID = "7FFCC44C",
          NextDialogue = 51125519,
          SpeakNpcId = 701039,
          Subtitle = "And some of the key incense materials — they've got strict limits. Take Skylilies, for instance: folks here burn a lot of it. If the Starweavers ship it all overseas, what are we supposed to do when we run short?"
        },
        [51125519] = {
          ContentEN = "And what's coming in needs even tighter checks! Take Hyperborea — blades, firearms, that sort of stuff. Let all that in unchecked and Huaxu'd be a madhouse!",
          DialogueId = 51125519,
          GUID = "7FFCC476",
          NextOptions = {
            [1] = 51125520,
            [2] = 51125524,
            [3] = 51125527
          },
          SpeakNpcId = 701039,
          Subtitle = "And what's coming in needs even tighter checks! Take Hyperborea — blades, firearms, that sort of stuff. Let all that in unchecked and Huaxu'd be a madhouse!"
        },
        [51125520] = {
          ContentEN = "So what happens if something illegal slips through?",
          DialogueId = 51125520,
          GUID = "7FFCC4A0",
          NextDialogue = 51125521,
          Subtitle = "So what happens if something illegal slips through?"
        },
        [51125521] = {
          ContentEN = "Ha! My friend, it's not that easy. We tallymen've been at this forever — one look, one sniff, and we know what's in the crate.",
          DialogueId = 51125521,
          GUID = "7FFCC4CA",
          NextDialogue = 51125522,
          SpeakNpcId = 701039,
          Subtitle = "Ha! My friend, it's not that easy. We tallymen've been at this forever — one look, one sniff, and we know what's in the crate."
        },
        [51125522] = {
          ContentEN = "See those Bi'an patrolling the docks? What we catch, they spot — and what we don't, ha, they still will.",
          DialogueId = 51125522,
          GUID = "7FFCC4F4",
          NextDialogue = 51125523,
          SpeakNpcId = 701039,
          Subtitle = "See those Bi'an patrolling the docks? What we catch, they spot — and what we don't, ha, they still will."
        },
        [51125523] = {
          ContentEN = "Those Bi'an keep watch day and night to stop anything shady from getting into Huaxu. Their noses? Sharp as can be — one sniff and they'll know exactly who's hiding what.",
          DialogueId = 51125523,
          GUID = "7FFCC51E",
          SpeakNpcId = 701039,
          Subtitle = "Those Bi'an keep watch day and night to stop anything shady from getting into Huaxu. Their noses? Sharp as can be — one sniff and they'll know exactly who's hiding what."
        },
        [51125524] = {
          ContentEN = "Oh, so you're not a Starweaver?",
          DialogueId = 51125524,
          GUID = "7FFCC548",
          NextDialogue = 51125525,
          Subtitle = "Oh, so you're not a Starweaver?"
        },
        [51125525] = {
          ContentEN = "Yes and no. In Huaxu, anyone can be a Starweaver if they want — but why bother?",
          DialogueId = 51125525,
          GUID = "7FFCC572",
          NextDialogue = 51125526,
          SpeakNpcId = 701039,
          Subtitle = "Yes and no. In Huaxu, anyone can be a Starweaver if they want — but why bother?"
        },
        [51125526] = {
          ContentEN = "You know how it is for traders — sometimes they make a fortune, sometimes they lose their shirts. Me, I keep it simple — easy job, steady coin. Why run off to sea like them and barely ever see home?",
          DialogueId = 51125526,
          GUID = "7FFCC59C",
          SpeakNpcId = 701039,
          Subtitle = "You know how it is for traders — sometimes they make a fortune, sometimes they lose their shirts. Me, I keep it simple — easy job, steady coin. Why run off to sea like them and barely ever see home?"
        },
        [51125527] = {
          ContentEN = "I should get going.",
          DialogueId = 51125527,
          GUID = "7FFCC5C6",
          NextDialogue = 51125528,
          Subtitle = "I should get going."
        },
        [51125528] = {
          ContentEN = "Have a nice day, friend! If you've got questions, you know where to find me!",
          DialogueId = 51125528,
          GUID = "7FFCC5F0",
          SpeakNpcId = 701039,
          Subtitle = "Have a nice day, friend! If you've got questions, you know where to find me!"
        },
        [51125601] = {
          ContentEN = "Good taste, my friend — Huaxu's finest, right here. These Lunarose sachets above all: if you'd seek Lord Argent's favour, you'll want one.",
          DialogueId = 51125601,
          GUID = "7FFCD1EA",
          NextOptions = {
            [1] = 51125602,
            [2] = 51125604
          },
          SpeakNpcId = 701040,
          Subtitle = "Good taste, my friend — Huaxu's finest, right here. These Lunarose sachets above all: if you'd seek Lord Argent's favour, you'll want one."
        },
        [51125602] = {
          ContentEN = "Someone already gave me one.",
          DialogueId = 51125602,
          GUID = "7FFCD214",
          ImprPlusId = 1209,
          NextDialogue = 51125603,
          Subtitle = "Someone already gave me one."
        },
        [51125603] = {
          ContentEN = "Oh? So you've friends in Huaxu — maybe a Starweaver brought you? No matter! I've plenty besides sachets — a silk fan, perhaps, or an embossed gilt-lacquered mirror?",
          DialogueId = 51125603,
          GUID = "7FFCD23E",
          SpeakNpcId = 701040,
          Subtitle = "Oh? So you've friends in Huaxu — maybe a Starweaver brought you? No matter! I've plenty besides sachets — a silk fan, perhaps, or an embossed gilt-lacquered mirror?"
