        },
        [51125613] = {
          ContentEN = "Oh, and don't miss our new scented candles: a breath of Huaxu in each — travellers from abroad always come back for more!",
          DialogueId = 51125613,
          GUID = "7FFCD3E2",
          NextOptions = {
