          GUID = "7FFD034C",
          NextDialogue = 51125903,
          SpeakNpcId = 701044,
          Subtitle = "In Huaxu, none may harm another — by any means, for any reason. Should another be hurt because of you, the fault is yours."
        },
        [51125903] = {
