        [51126116] = {
          ContentEN = "Quite a few, actually. For newcomers like me, once you join, you can apply for a starting fund — there's interest, but it's low — and you can use it for any kind of trade you prefer.",
          DialogueId = 51126116,
          GUID = "7FFD2668",
          NextDialogue = 51126117,
          SpeakNpcId = 701046,
          Subtitle = "Quite a few, actually. For newcomers like me, once you join, you can apply for a starting fund — there's interest, but it's low — and you can use it for any kind of trade you prefer."
        },
        [51126117] = {
          ContentEN = "With EverSpring's name behind us, even the largest merchants treat us with respect — some even approach us first simply because we're Starweavers.",
          DialogueId = 51126117,
          GUID = "7FFD2692",
          NextDialogue = 51126118,
          SpeakNpcId = 701046,
          Subtitle = "With EverSpring's name behind us, even the largest merchants treat us with respect — some even approach us first simply because we're Starweavers."
        },
        [51126118] = {
          ContentEN = "It's a far cry from the days when I had to go door to door trying to gather stock.",
          DialogueId = 51126118,
          GUID = "7FFD26BC",
          SpeakNpcId = 701046,
          Subtitle = "It's a far cry from the days when I had to go door to door trying to gather stock."
        },
        [51126119] = {
          ContentEN = "So not every merchant in Huaxu is a Starweaver, then?",
          DialogueId = 51126119,
          GUID = "7FFD26E6",
          NextDialogue = 51126120,
          Subtitle = "So not every merchant in Huaxu is a Starweaver, then?"
        },
        [51126120] = {
          ContentEN = "No, not at all. Starweavers are one group; there are also hawkers and stallholders — quite a different crowd.",
          DialogueId = 51126120,
          GUID = "7FFD2710",
          NextDialogue = 51126121,
          SpeakNpcId = 701046,
          Subtitle = "No, not at all. Starweavers are one group; there are also hawkers and stallholders — quite a different crowd."
        },
        [51126121] = {
          ContentEN = "Being a Starweaver certainly has its advantages, but also plenty of rules. Once a deal is made, you must seal a covenant and follow the proper terms. For those used to traveling trade or running small stalls, such rules can feel a bit restrictive.",
          DialogueId = 51126121,
          GUID = "7FFD273A",
          NextDialogue = 51126122,
          SpeakNpcId = 701046,
          Subtitle = "Being a Starweaver certainly has its advantages, but also plenty of rules. Once a deal is made, you must seal a covenant and follow the proper terms. For those used to traveling trade or running small stalls, such rules can feel a bit restrictive."
        },
        [51126122] = {
          ContentEN = "I used to be the same — traveling from place to place, doing small trades along the way. Saved up a little, then came here hoping to make something bigger of it.",
          DialogueId = 51126122,
          GUID = "7FFD2764",
          NextOptions = {
            [1] = 51126123
          },
          SpeakNpcId = 701046,
          Subtitle = "I used to be the same — traveling from place to place, doing small trades along the way. Saved up a little, then came here hoping to make something bigger of it."
        },
        [51126123] = {
          ContentEN = "How many Starweavers are there in Huaxu?",
          DialogueId = 51126123,
          GUID = "7FFD278E",
          NextDialogue = 51126124,
          Subtitle = "How many Starweavers are there in Huaxu?"
        },
        [51126124] = {
          ContentEN = "How many? Hard to say. Plenty of shops register just to make their names sound more trustworthy. If I had to guess... perhaps six or seven out of ten.",
          DialogueId = 51126124,
          GUID = "7FFD27B8",
          NextDialogue = 51126125,
          SpeakNpcId = 701046,
          Subtitle = "How many? Hard to say. Plenty of shops register just to make their names sound more trustworthy. If I had to guess... perhaps six or seven out of ten."
        },
        [51126125] = {
          ContentEN = "In any case, it's common to meet Starweavers in all sorts of trades wherever you go.",
          DialogueId = 51126125,
          GUID = "7FFD27E2",
          SpeakNpcId = 701046,
          Subtitle = "In any case, it's common to meet Starweavers in all sorts of trades wherever you go."
        },
        [51126126] = {
          ContentEN = "Let's talk next time.",
          DialogueId = 51126126,
          GUID = "7FFD280C",
          NextDialogue = 51126127,
          Subtitle = "Let's talk next time."
        },
        [51126127] = {
          ContentEN = "Of course. Come find me when you're ready to apply.",
          DialogueId = 51126127,
          GUID = "7FFD2836",
          SpeakNpcId = 701046,
          Subtitle = "Of course. Come find me when you're ready to apply."
        },
        [51126201] = {
          ContentEN = "Mr Cong, this year's building work at EverSpring has already gone well beyond the plan. It was meant to be a modest repair, and now there's even a tea room added.",
          DialogueId = 51126201,
          GUID = "7FFD345A",
          NextDialogue = 51126202,
          SpeakNpcId = 701047,
          Subtitle = "Mr Cong, this year's building work at EverSpring has already gone well beyond the plan. It was meant to be a modest repair, and now there's even a tea room added."
        },
        [51126202] = {
          ContentEN = "Yes, I know — Li provided the silver for that. If his gift was accepted, why not mine? We Starweavers earn our living abroad and return home to honour EverSpring — it's been our custom for generations.",
          DialogueId = 51126202,
          GUID = "7FFD3484",
          NextDialogue = 51126203,
          SpeakNpcId = 701048,
          Subtitle = "Yes, I know — Li provided the silver for that. If his gift was accepted, why not mine? We Starweavers earn our living abroad and return home to honour EverSpring — it's been our custom for generations."
        },
        [51126203] = {
          ContentEN = "We truly cannot, sir. You know how people are — everyone wishes to contribute to EverSpring. The guild was never a grand one to begin with; it's grown brick by brick to what it is now. We can't continue like this forever.",
          DialogueId = 51126203,
          GUID = "7FFD34AE",
          NextDialogue = 51126204,
          SpeakNpcId = 701047,
          Subtitle = "We truly cannot, sir. You know how people are — everyone wishes to contribute to EverSpring. The guild was never a grand one to begin with; it's grown brick by brick to what it is now. We can't continue like this forever."
        },
        [51126204] = {
          ContentEN = "If we keep building at this rate, EverSpring will wear itself thin — and we'll all end up rebuilding in the end.",
          DialogueId = 51126204,
          GUID = "7FFD34D8",
          NextDialogue = 51126205,
          SpeakNpcId = 701047,
          Subtitle = "If we keep building at this rate, EverSpring will wear itself thin — and we'll all end up rebuilding in the end."
        },
        [51126205] = {
          ContentEN = "I don't care. You've taken Li's silver, you'll take mine as well. If not, I'll come by in the dead of night and leave the money here myself.",
          DialogueId = 51126205,
          GUID = "7FFD3502",
          NextDialogue = 51126206,
          SpeakNpcId = 701048,
          Subtitle = "I don't care. You've taken Li's silver, you'll take mine as well. If not, I'll come by in the dead of night and leave the money here myself."
        },
        [51126206] = {
          ContentEN = "Well... Mr Li has been waiting since the year before last for this year's building quota. He put in his request the moment it opened — there is, after all, an order of precedence.",
          DialogueId = 51126206,
          GUID = "7FFD352C",
          NextDialogue = 51126207,
          SpeakNpcId = 701047,
          Subtitle = "Well... Mr Li has been waiting since the year before last for this year's building quota. He put in his request the moment it opened — there is, after all, an order of precedence."
        },
        [51126207] = {
          ContentEN = "Then use my silver to help the new Starweavers — just as the guild once lent its hand to me.",
          DialogueId = 51126207,
          GUID = "7FFD3556",
          SpeakNpcId = 701048,
          Subtitle = "Then use my silver to help the new Starweavers — just as the guild once lent its hand to me."
        },
        [51126301] = {
          ContentEN = "I'm not sure. But the Starweavers made this moon, piece by piece — there must be a way up!",
          DialogueId = 51126301,
          GUID = "7FFD44C2",
          NextDialogue = 51126302,
          SpeakNpcId = 701049,
          Subtitle = "I'm not sure. But the Starweavers made this moon, piece by piece — there must be a way up!"
        },
        [51126302] = {
          ContentEN = "And it's like a huge incense burner for our city! Someone's got to climb up and clean it once in a while.",
          DialogueId = 51126302,
          GUID = "7FFD44EC",
          NextDialogue = 51126303,
          SpeakNpcId = 701049,
          Subtitle = "And it's like a huge incense burner for our city! Someone's got to climb up and clean it once in a while."
        },
        [51126303] = {
          ContentEN = "Yes, but where's the way up? I can't see anything!",
          DialogueId = 51126303,
          GUID = "7FFD4516",
          NextDialogue = 51126304,
          SpeakNpcId = 701050,
          Subtitle = "Yes, but where's the way up? I can't see anything!"
        },
        [51126304] = {
          ContentEN = "Shh, I'm thinking! I'll figure something out!",
          DialogueId = 51126304,
          GUID = "7FFD4540",
          NextOptions = {
            [1] = 51126305,
            [2] = 51126312,
            [3] = 51126323
          },
          SpeakNpcId = 701049,
          Subtitle = "Shh, I'm thinking! I'll figure something out!"
        },
        [51126305] = {
          ContentEN = "What are you two talking about?",
          DialogueId = 51126305,
          GUID = "7FFD456A",
          NextDialogue = 51126306,
          Subtitle = "What are you two talking about?"
        },
        [51126306] = {
          ContentEN = "Whoa! A foreigner!?",
          DialogueId = 51126306,
          GUID = "7FFD4594",
          NextDialogue = 51126307,
          SpeakNpcId = 701050,
          Subtitle = "Whoa! A foreigner!?"
        },
        [51126307] = {
          ContentEN = "Do you like the big moon too?",
          DialogueId = 51126307,
          GUID = "7FFD45BE",
          NextOptions = {
            [1] = 51126308,
            [2] = 51126310
          },
          SpeakNpcId = 701049,
          Subtitle = "Do you like the big moon too?"
        },
        [51126308] = {
          ContentEN = "I do.",
          DialogueId = 51126308,
          GUID = "7FFD45E8",
          NextDialogue = 51126309,
          Subtitle = "I do."
        },
        [51126309] = {
          ContentEN = "Silly Bunny! Everyone likes it! It's so big you can even see it from the sea!",
          DialogueId = 51126309,
          GUID = "7FFD4612",
          SpeakNpcId = 701049,
          Subtitle = "Silly Bunny! Everyone likes it! It's so big you can even see it from the sea!"
        },
        [51126310] = {
          ContentEN = "Not really.",
          DialogueId = 51126310,
          GUID = "7FFD463C",
          NextDialogue = 51126311,
          Subtitle = "Not really."
        },
        [51126311] = {
          ContentEN = "What? Really? It's so bright and huge! How can you not like it? You must be fibbing!",
          DialogueId = 51126311,
          GUID = "7FFD4666",
          SpeakNpcId = 701050,
          Subtitle = "What? Really? It's so bright and huge! How can you not like it? You must be fibbing!"
        },
        [51126312] = {
          ContentEN = "Why do you want to climb it?",
          DialogueId = 51126312,
          GUID = "7FFD4690",
          NextDialogue = 51126313,
          Subtitle = "Why do you want to climb it?"
        },
        [51126313] = {
          ContentEN = "Someone said the very top's the highest place in Mistwharf! You can see the whole Mistwharf from up there. We just want to have a look!",
          DialogueId = 51126313,
          GUID = "7FFD46BA",
          NextDialogue = 51126314,
          SpeakNpcId = 701049,
          Subtitle = "Someone said the very top's the highest place in Mistwharf! You can see the whole Mistwharf from up there. We just want to have a look!"
        },
        [51126314] = {
          ContentEN = "Uh-huh! We want to count all the Chipgulls that fly over EverSpring in one day!",
          DialogueId = 51126314,
          GUID = "7FFD46E4",
          NextOptions = {
            [1] = 51126315
          },
          SpeakNpcId = 701050,
          Subtitle = "Uh-huh! We want to count all the Chipgulls that fly over EverSpring in one day!"
        },
        [51126315] = {
          ContentEN = "So it's not real? People built it?",
          DialogueId = 51126315,
          GUID = "7FFD470E",
          NextDialogue = 51126316,
          Subtitle = "So it's not real? People built it?"
        },
        [51126316] = {
          ContentEN = "You didn't know? Oh, right — you're not from here! The moon's actually a giant incense burner in Mistwharf. A really rich Starweaver paid to have it built!",
          DialogueId = 51126316,
          GUID = "7FFD4738",
          NextOptions = {
            [1] = 51126317
          },
          SpeakNpcId = 701049,
          Subtitle = "You didn't know? Oh, right — you're not from here! The moon's actually a giant incense burner in Mistwharf. A really rich Starweaver paid to have it built!"
        },
        [51126317] = {
          ContentEN = "Why did they make it look like a moon?",
          DialogueId = 51126317,
          GUID = "7FFD4762",
          NextDialogue = 51126318,
          Subtitle = "Why did they make it look like a moon?"
        },
        [51126318] = {
          ContentEN = "Oh, I know this one! The Starweaver said people who sail away are like stars in the sky — they'll all come home one day! So home needs a bright moon to guide them back!",
          DialogueId = 51126318,
          GUID = "7FFD478C",
          NextDialogue = 51126319,
          SpeakNpcId = 701050,
          Subtitle = "Oh, I know this one! The Starweaver said people who sail away are like stars in the sky — they'll all come home one day! So home needs a bright moon to guide them back!"
        },
        [51126319] = {
          ContentEN = "Aren't you a know-it-all! Then do you know what the Starweaver called it?",
          DialogueId = 51126319,
          GUID = "7FFD47B6",
          NextDialogue = 51126320,
          SpeakNpcId = 701049,
          Subtitle = "Aren't you a know-it-all! Then do you know what the Starweaver called it?"
        },
        [51126320] = {
          ContentEN = "Erm... I forgot...",
          DialogueId = 51126320,
          GUID = "7FFD47E0",
          NextDialogue = 51126321,
          SpeakNpcId = 701050,
          Subtitle = "Erm... I forgot..."
        },
        [51126321] = {
          ContentEN = "Ahem! Let me tell you then — it's called... Homeward Bright Moon!",
          DialogueId = 51126321,
          GUID = "7FFD480A",
          NextDialogue = 51126322,
          SpeakNpcId = 701049,
          Subtitle = "Ahem! Let me tell you then — it's called... Homeward Bright Moon!"
        },
        [51126322] = {
          ContentEN = "That's such a long name! No wonder I forgot. \"Big Moon\" sounds much better!",
          DialogueId = 51126322,
          GUID = "7FFD4834",
          SpeakNpcId = 701050,
          Subtitle = "That's such a long name! No wonder I forgot. \"Big Moon\" sounds much better!"
        },
        [51126323] = {
          ContentEN = "See you next time.",
          DialogueId = 51126323,
          GUID = "7FFD485E",
          NextDialogue = 51126324,
          Subtitle = "See you next time."
        },
        [51126324] = {
          ContentEN = "See you, traveller! Come on, let's get back to figuring out how to climb it!",
          DialogueId = 51126324,
          GUID = "7FFD4888",
          SpeakNpcId = 701049,
          Subtitle = "See you, traveller! Come on, let's get back to figuring out how to climb it!"
        },
        [51126401] = {
          ContentEN = "Didn't expect to stumble upon something this old today. It seems barely stable enough to read the weather, let alone fortunes...",
          DialogueId = 51126401,
          GUID = "7FFD552A",
          NextDialogue = 51126402,
          SpeakNpcId = 701051,
          Subtitle = "Didn't expect to stumble upon something this old today. It seems barely stable enough to read the weather, let alone fortunes..."
        },
        [51126402] = {
          ContentEN = "It must date back to my great-great-grandfather's time — or perhaps even earlier. Well, you get the idea. It's ancient.",
          DialogueId = 51126402,
          GUID = "7FFD5554",
          NextOptions = {
            [1] = 51126403,
            [2] = 51126405
          },
          SpeakNpcId = 701051,
          Subtitle = "It must date back to my great-great-grandfather's time — or perhaps even earlier. Well, you get the idea. It's ancient."
        },
        [51126403] = {
          ContentEN = "What are you doing?",
          DialogueId = 51126403,
          GUID = "7FFD557E",
          NextDialogue = 51126404,
          Subtitle = "What are you doing?"
        },
        [51126404] = {
          ContentEN = "Me? I happened upon this old Stellapass and thought I'd keep it as a curio. And you? Are you interested in relics as well?",
          DialogueId = 51126404,
          GUID = "7FFD55A8",
          SpeakNpcId = 701051,
          Subtitle = "Me? I happened upon this old Stellapass and thought I'd keep it as a curio. And you? Are you interested in relics as well?"
        },
        [51126405] = {
          ContentEN = "Just curious about the Stellapass.",
          DialogueId = 51126405,
          GUID = "7FFD55D2",
          NextDialogue = 51126406,
          Subtitle = "Just curious about the Stellapass."
        },
        [51126406] = {
          ContentEN = "Ah, a traveller with a taste for Huaxu craftsmanship. Then allow me to play the host — ask away, and I'll share what I know.",
          DialogueId = 51126406,
          GUID = "7FFD55FC",
          SpeakNpcId = 701051,
          Subtitle = "Ah, a traveller with a taste for Huaxu craftsmanship. Then allow me to play the host — ask away, and I'll share what I know."
        },
        [51126407] = {
          ContentEN = "Ah... this Stellapass — now that's a piece of history!",
          DialogueId = 51126407,
          GUID = "7FFD5626",
          NextDialogue = 51126408,
          SpeakNpcId = 701051,
          Subtitle = "Ah... this Stellapass — now that's a piece of history!"
        },
        [51126408] = {
          ContentEN = "There you are. You wished to learn about the Stellapass, did you not?",
          DialogueId = 51126408,
          GUID = "7FFD5650",
          NextDialogue = 51126430,
          SpeakNpcId = 701051,
          Subtitle = "There you are. You wished to learn about the Stellapass, did you not?"
        },
        [51126409] = {
          ContentEN = "Can you tell me the story of the Stellapass?",
          DialogueId = 51126409,
          GUID = "7FFD567A",
          NextDialogue = 51126410,
          Subtitle = "Can you tell me the story of the Stellapass?"
        },
        [51126410] = {
          ContentEN = "A long story indeed. These instruments date back to before the founding of Huaxu — to the age of Ju and Yang. In those days, a hundred schools of thought flourished, and among them, the Bingzhu Sect devoted itself to the study of the stars.",
          DialogueId = 51126410,
          GUID = "7FFD56A4",
          NextDialogue = 51126411,
          SpeakNpcId = 701051,
          Subtitle = "A long story indeed. These instruments date back to before the founding of Huaxu — to the age of Ju and Yang. In those days, a hundred schools of thought flourished, and among them, the Bingzhu Sect devoted itself to the study of the stars."
        },
        [51126411] = {
          ContentEN = "The Bingzhu believed the heavens concealed a calamity great enough to end the world. To withstand it, they refined the art of Stellomancy — reading the stars for omens, seeking a way to avert disaster.",
          DialogueId = 51126411,
          GUID = "7FFD56CE",
          NextDialogue = 51126412,
          SpeakNpcId = 701051,
          Subtitle = "The Bingzhu believed the heavens concealed a calamity great enough to end the world. To withstand it, they refined the art of Stellomancy — reading the stars for omens, seeking a way to avert disaster."
        },
        [51126412] = {
          ContentEN = "From that very school came a remarkable mind named Beiluo. He found endless stargazing and talk of destiny rather tiresome.",
          DialogueId = 51126412,
          GUID = "7FFD56F8",
          NextDialogue = 51126413,
          SpeakNpcId = 701051,
          Subtitle = "From that very school came a remarkable mind named Beiluo. He found endless stargazing and talk of destiny rather tiresome."
        },
        [51126413] = {
          ContentEN = "He preferred wandering the streets with his friends — one of whom was Ju, long before Ju ever left Huaxu.",
          DialogueId = 51126413,
          GUID = "7FFD5722",
          NextDialogue = 51126414,
          SpeakNpcId = 701051,
          Subtitle = "He preferred wandering the streets with his friends — one of whom was Ju, long before Ju ever left Huaxu."
        },
        [51126414] = {
          ContentEN = "Together they built the first Stellapass — much like this one. It served only for navigation at first, yet even that was a marvel for its time.",
          DialogueId = 51126414,
          GUID = "7FFD574C",
          NextDialogue = 51126430,
          SpeakNpcId = 701051,
          Subtitle = "Together they built the first Stellapass — much like this one. It served only for navigation at first, yet even that was a marvel for its time."
        },
        [51126415] = {
          ContentEN = "So only Starweavers have these devices?",
          DialogueId = 51126415,
          GUID = "7FFD5776",
          NextDialogue = 51126416,
          Subtitle = "So only Starweavers have these devices?"
        },
        [51126416] = {
          ContentEN = "One could acquire one easily enough. Yet owning a Stellapass and understanding it are very different matters.",
          DialogueId = 51126416,
          GUID = "7FFD57A0",
          NextDialogue = 51126417,
          SpeakNpcId = 701051,
          Subtitle = "One could acquire one easily enough. Yet owning a Stellapass and understanding it are very different matters."
        },
        [51126417] = {
          ContentEN = "Observe — I shall set it in motion. See whether its design speaks to you.",
          DialogueId = 51126417,
          GUID = "7FFD57CA",
          NextDialogue = 51126418,
          SpeakNpcId = 701051,
          Subtitle = "Observe — I shall set it in motion. See whether its design speaks to you."
        },
        [51126418] = {
          ContentEN = "(He sets the Stellapass upon his palm. The interlocking squares lift and turn, layer by layer, until a shard drifts between them and the smallest square atop comes to rest.)",
          DialogueId = 51126418,
          GUID = "7FFD57F4",
          NextDialogue = 51126419,
          Subtitle = "(He sets the Stellapass upon his palm. The interlocking squares lift and turn, layer by layer, until a shard drifts between them and the smallest square atop comes to rest.)"
        },
        [51126419] = {
          ContentEN = "There — a clean start. The Stellapass turns as direction shifts. Only trained Starweavers can read those changing angles.",
          DialogueId = 51126419,
          GUID = "7FFD581E",
          NextDialogue = 51126420,
          SpeakNpcId = 701051,
          Subtitle = "There — a clean start. The Stellapass turns as direction shifts. Only trained Starweavers can read those changing angles."
        },
        [51126420] = {
          ContentEN = "In theory, anyone might learn to do so — but in practice, it's far from easy.",
          DialogueId = 51126420,
          GUID = "7FFD5848",
          NextDialogue = 51126430,
          SpeakNpcId = 701051,
          Subtitle = "In theory, anyone might learn to do so — but in practice, it's far from easy."
        },
        [51126421] = {
          ContentEN = "What can a Stellapass do?",
          DialogueId = 51126421,
          GUID = "7FFD5872",
          NextDialogue = 51126422,
          Subtitle = "What can a Stellapass do?"
        },
        [51126422] = {
          ContentEN = "Its earliest use was navigation. Later, the Starweavers refined their craft, adding new functions.",
          DialogueId = 51126422,
          GUID = "7FFD589C",
          NextDialogue = 51126423,
          SpeakNpcId = 701051,
          Subtitle = "Its earliest use was navigation. Later, the Starweavers refined their craft, adding new functions."
        },
        [51126423] = {
          ContentEN = "One is the reading of weather — observing how the stars drift to foresee the coming days. Most helpful when your cargo must be kept dry.",
          DialogueId = 51126423,
          GUID = "7FFD58C6",
          NextDialogue = 51126424,
          SpeakNpcId = 701051,
          Subtitle = "One is the reading of weather — observing how the stars drift to foresee the coming days. Most helpful when your cargo must be kept dry."
        },
        [51126424] = {
          ContentEN = "Another is divination. The Starweavers hold that the heavens move in rhythm with all things below — especially commerce and travel.",
          DialogueId = 51126424,
          GUID = "7FFD58F0",
          NextDialogue = 51126425,
          SpeakNpcId = 701051,
          Subtitle = "Another is divination. The Starweavers hold that the heavens move in rhythm with all things below — especially commerce and travel."
        },
        [51126425] = {
