        },
        [51126605] = {
          ContentEN = "Hehe, the name \"EverSpring\" speaks of lasting prosperity — and indeed, we have endured for well over several centuries. We were already among the merchant guilds of Mistwharf when Huaxu itself was founded.",
          DialogueId = 51126605,
          GUID = "7FFD76A2",
