        [51127012] = {
          ContentEN = "In lives to come, rise or fall as thy heart inclineth; sow thine own good fortune, and its fruit shall long endure.",
          DialogueId = 51127012,
          GUID = "7FFDB968",
          NextDialogue = 51127013,
          SpeakNpcId = 701060,
          Subtitle = "In lives to come, rise or fall as thy heart inclineth; sow thine own good fortune, and its fruit shall long endure."
        },
        [51127013] = {
          ContentEN = "By writ and vow we charge the dead: cast off the cloud of doubt; swift as the edict bids, depart to blissful fields.",
          DialogueId = 51127013,
          GUID = "7FFDB992",
          SpeakNpcId = 701060,
          Subtitle = "By writ and vow we charge the dead: cast off the cloud of doubt; swift as the edict bids, depart to blissful fields."
        },
        [51127014] = {
          ContentEN = "What brings you to chant it?",
          DialogueId = 51127014,
          GUID = "7FFDB9BC",
          NextDialogue = 51127015,
          Subtitle = "What brings you to chant it?"
        },
        [51127015] = {
          ContentEN = "My father... he passed away last year. Now it's only my mother and me. Whenever I miss him, I come here to recite a prayer or two.",
          DialogueId = 51127015,
          GUID = "7FFDB9E6",
          NextOptions = {
            [1] = 51127016,
            [2] = 51127019,
            [3] = 51127026
          },
          SpeakNpcId = 701060,
          Subtitle = "My father... he passed away last year. Now it's only my mother and me. Whenever I miss him, I come here to recite a prayer or two."
        },
        [51127016] = {
          ContentEN = "Does it help?",
          DialogueId = 51127016,
          GUID = "7FFDBA10",
          NextDialogue = 51127017,
          Subtitle = "Does it help?"
        },
        [51127017] = {
          ContentEN = "Perhaps it does, perhaps not. For me, it's a small solace. When I was little, I always thought Father worked too hard. I used to tell myself — once I was grown, I'd let him live in ease and peace.",
          DialogueId = 51127017,
          GUID = "7FFDBA3A",
          NextDialogue = 51127018,
          SpeakNpcId = 701060,
          Subtitle = "Perhaps it does, perhaps not. For me, it's a small solace. When I was little, I always thought Father worked too hard. I used to tell myself — once I was grown, I'd let him live in ease and peace."
        },
        [51127018] = {
          ContentEN = "But before I could shoulder the family myself, he was already gone... So I come here and pray, hoping he's at peace, somewhere beyond my reach...",
          DialogueId = 51127018,
          GUID = "7FFDBA64",
          SpeakNpcId = 701060,
          Subtitle = "But before I could shoulder the family myself, he was already gone... So I come here and pray, hoping he's at peace, somewhere beyond my reach..."
        },
        [51127019] = {
          ContentEN = "Why here, of all places?",
          DialogueId = 51127019,
          GUID = "7FFDBA8E",
          NextDialogue = 51127020,
          Subtitle = "Why here, of all places?"
        },
        [51127020] = {
          ContentEN = "Have you heard the tale of Huaxu's Wishen? They are spirits bound by unfinished business, unable to move on. If Father still can't let us go... he might have become one too.",
          DialogueId = 51127020,
          GUID = "7FFDBAB8",
          NextDialogue = 51127021,
          SpeakNpcId = 701060,
          Subtitle = "Have you heard the tale of Huaxu's Wishen? They are spirits bound by unfinished business, unable to move on. If Father still can't let us go... he might have become one too."
        },
        [51127021] = {
          ContentEN = "Perhaps... perhaps he'll come here too, one day...",
          DialogueId = 51127021,
          GUID = "7FFDBAE2",
          NextOptions = {
            [1] = 51127022,
            [2] = 51127024,
            [3] = 51127026
          },
          SpeakNpcId = 701060,
          Subtitle = "Perhaps... perhaps he'll come here too, one day..."
        },
        [51127022] = {
          ContentEN = "What makes you think your father would come here?",
          DialogueId = 51127022,
          GUID = "7FFDBB0C",
          NextDialogue = 51127023,
          Subtitle = "What makes you think your father would come here?"
        },
        [51127023] = {
          ContentEN = "I cannot say... it's only a feeling. If he isn't here, then let this prayer be for the other Wishen still bound to this world. And if they cross paths on that unseen shore... please... tell my father of me.",
          DialogueId = 51127023,
          GUID = "7FFDBB36",
          SpeakNpcId = 701060,
          Subtitle = "I cannot say... it's only a feeling. If he isn't here, then let this prayer be for the other Wishen still bound to this world. And if they cross paths on that unseen shore... please... tell my father of me."
        },
        [51127024] = {
          ContentEN = "If he could see you now, he'd rest easy.",
          DialogueId = 51127024,
          GUID = "7FFDBB60",
          NextDialogue = 51127025,
          Subtitle = "If he could see you now, he'd rest easy."
        },
        [51127025] = {
          ContentEN = "Then... may this prayer reach the other Wishen still bound to this world. And if they cross paths on that unseen shore... please... tell my father of me.",
          DialogueId = 51127025,
          GUID = "7FFDBB8A",
          SpeakNpcId = 701060,
          Subtitle = "Then... may this prayer reach the other Wishen still bound to this world. And if they cross paths on that unseen shore... please... tell my father of me."
        },
        [51127026] = {
          ContentEN = "Leave quietly.",
          DialogueId = 51127026,
          GUID = "7FFDBBB4",
          NextDialogue = 51127027,
          Subtitle = "Leave quietly."
        },
        [51127027] = {
          ContentEN = "By vow and decree we summon the lost: Cease your wandering; hasten unto the Realm of Bliss...",
          DialogueId = 51127027,
          GUID = "7FFDBBDE",
          SpeakNpcId = 701060,
          Subtitle = "By vow and decree we summon the lost: Cease your wandering; hasten unto the Realm of Bliss..."
        },
        [51127101] = {
          ContentEN = "Oh, Grandpa, you're being silly again! Not on the ground, not in the water — on my head! Hmm... if that's too hard, my shoulder's okay too!",
          DialogueId = 51127101,
          GUID = "7FFDC802",
          NextOptions = {
            [1] = 51127102,
            [2] = 51127104
          },
          SpeakNpcId = 701061,
          Subtitle = "Oh, Grandpa, you're being silly again! Not on the ground, not in the water — on my head! Hmm... if that's too hard, my shoulder's okay too!"
        },
        [51127102] = {
          ContentEN = "Are you talking to yourself?",
          DialogueId = 51127102,
          GUID = "7FFDC82C",
          ImprPlusId = 1208,
          NextDialogue = 51127103,
          Subtitle = "Are you talking to yourself?"
        },
        [51127103] = {
          ContentEN = "Huh? Talking to myself? Maybe! But you spoke to me first — so now I'm talking to you!",
          DialogueId = 51127103,
          GUID = "7FFDC856",
          NextDialogue = 51127106,
          SpeakNpcId = 701061,
          Subtitle = "Huh? Talking to myself? Maybe! But you spoke to me first — so now I'm talking to you!"
        },
        [51127104] = {
          ContentEN = "Were you talking to a Wishen?",
          DialogueId = 51127104,
          GUID = "7FFDC880",
          ImprPlusId = 1209,
          NextDialogue = 51127105,
          Subtitle = "Were you talking to a Wishen?"
        },
        [51127105] = {
          ContentEN = "Nope! Just me talking to me! But then you said something — so now I'm talking to you!",
          DialogueId = 51127105,
          GUID = "7FFDC8AA",
          NextDialogue = 51127106,
          SpeakNpcId = 701061,
          Subtitle = "Nope! Just me talking to me! But then you said something — so now I'm talking to you!"
        },
        [51127106] = {
          ContentEN = "Then who were you really talking to?",
          DialogueId = 51127106,
          GUID = "7FFDC8D4",
          NextDialogue = 51127107,
          SpeakNpcId = 100001,
          Subtitle = "Then who were you really talking to?"
        },
        [51127107] = {
          ContentEN = "You don't know where you are, do you, traveller from far away? It's scary here! Really scary! All the Loongcions and Earthborn who die in Huaxu — they all turn into Wishen and come here!",
          DialogueId = 51127107,
          GUID = "7FFDC8FE",
          NextDialogue = 51127108,
          SpeakNpcId = 701061,
          Subtitle = "You don't know where you are, do you, traveller from far away? It's scary here! Really scary! All the Loongcions and Earthborn who die in Huaxu — they all turn into Wishen and come here!"
        },
        [51127108] = {
          ContentEN = "Well? Are you scared? If you are... you'd better run quick!",
          DialogueId = 51127108,
          GUID = "7FFDC928",
          SpeakNpcId = 701061,
          Subtitle = "Well? Are you scared? If you are... you'd better run quick!"
        },
        [51127109] = {
          ContentEN = "Grandpa! If you're really back, make a leaf fall on my head!",
          DialogueId = 51127109,
          GUID = "7FFDC952",
          NextDialogue = 51127110,
          SpeakNpcId = 701061,
          Subtitle = "Grandpa! If you're really back, make a leaf fall on my head!"
        },
        [51127110] = {
          ContentEN = "Hey! You really came back? Not even a little bit scared?",
          DialogueId = 51127110,
          GUID = "7FFDC97C",
          NextOptions = {
            [1] = 51127111,
            [2] = 51127123
          },
          SpeakNpcId = 701061,
          Subtitle = "Hey! You really came back? Not even a little bit scared?"
        },
        [51127111] = {
          ContentEN = "The Wishen won't hurt me. So why would I be afraid?",
          DialogueId = 51127111,
          GUID = "7FFDC9A6",
          NextDialogue = 51127112,
          Subtitle = "The Wishen won't hurt me. So why would I be afraid?"
        },
        [51127112] = {
          ContentEN = "Me too! But some travellers I met before — when they heard the dead turn into Wishen here, they just screamed and ran away!",
          DialogueId = 51127112,
          GUID = "7FFDC9D0",
          NextDialogue = 51127113,
          SpeakNpcId = 701061,
          Subtitle = "Me too! But some travellers I met before — when they heard the dead turn into Wishen here, they just screamed and ran away!"
        },
        [51127113] = {
          ContentEN = "They don't know the Wishen don't hurt anyone. They just stay here... really quiet...",
          DialogueId = 51127113,
          GUID = "7FFDC9FA",
          NextOptions = {
            [1] = 51127114
          },
          SpeakNpcId = 701061,
          Subtitle = "They don't know the Wishen don't hurt anyone. They just stay here... really quiet..."
        },
        [51127114] = {
          ContentEN = "So what are you doing here?",
          DialogueId = 51127114,
          GUID = "7FFDCA24",
          NextDialogue = 51127115,
          Subtitle = "So what are you doing here?"
        },
        [51127115] = {
          ContentEN = "Grandpa got really sick — he said it was something called \"ageing\". Then Lord Argent came and took him away. Before he went to sleep, he told me he once saw, at Twilight Ravine, people who died turning into Wishen.",
          DialogueId = 51127115,
          GUID = "7FFDCA4E",
          NextDialogue = 51127116,
          SpeakNpcId = 701061,
          Subtitle = "Grandpa got really sick — he said it was something called \"ageing\". Then Lord Argent came and took him away. Before he went to sleep, he told me he once saw, at Twilight Ravine, people who died turning into Wishen."
        },
        [51127116] = {
          ContentEN = "He said maybe he'd turn into one too — then he could stay with me forever.",
          DialogueId = 51127116,
          GUID = "7FFDCA78",
          NextDialogue = 51127117,
          SpeakNpcId = 701061,
          Subtitle = "He said maybe he'd turn into one too — then he could stay with me forever."
        },
        [51127117] = {
          ContentEN = "I waited and waited at home, but Grandpa never came back. Then Mum said the Wishen only live here... so I came to find him.",
          DialogueId = 51127117,
          GUID = "7FFDCAA2",
          NextOptions = {
            [1] = 51127118,
            [2] = 51127120
          },
          SpeakNpcId = 701061,
          Subtitle = "I waited and waited at home, but Grandpa never came back. Then Mum said the Wishen only live here... so I came to find him."
        },
        [51127118] = {
          ContentEN = "Have you seen him, then?",
          DialogueId = 51127118,
          GUID = "7FFDCACC",
          NextDialogue = 51127119,
          Subtitle = "Have you seen him, then?"
        },
        [51127119] = {
          ContentEN = "Mum says we can't see the Wishen. So I told Grandpa — if he can hear me, drop a leaf on my head! But Grandpa's so silly... he still hasn't done it...",
          DialogueId = 51127119,
          GUID = "7FFDCAF6",
          SpeakNpcId = 701061,
          Subtitle = "Mum says we can't see the Wishen. So I told Grandpa — if he can hear me, drop a leaf on my head! But Grandpa's so silly... he still hasn't done it..."
        },
        [51127120] = {
          ContentEN = "But it's so spooky here. Aren't you scared?",
          DialogueId = 51127120,
          GUID = "7FFDCB20",
          NextDialogue = 51127121,
          Subtitle = "But it's so spooky here. Aren't you scared?"
        },
        [51127121] = {
          ContentEN = "I was, at first. So I started talking to Grandpa. Then I thought... even if there are other Wishen here, they were people once too, right?",
          DialogueId = 51127121,
          GUID = "7FFDCB4A",
          NextDialogue = 51127122,
          SpeakNpcId = 701061,
          Subtitle = "I was, at first. So I started talking to Grandpa. Then I thought... even if there are other Wishen here, they were people once too, right?"
        },
        [51127122] = {
          ContentEN = "People who die still have family. And when there's family, someone's always missing them. Like me and Grandpa — even if he's gone, we still remember him. When I think about that... I'm not scared anymore.",
          DialogueId = 51127122,
          GUID = "7FFDCB74",
          SpeakNpcId = 701061,
          Subtitle = "People who die still have family. And when there's family, someone's always missing them. Like me and Grandpa — even if he's gone, we still remember him. When I think about that... I'm not scared anymore."
        },
        [51127123] = {
          ContentEN = "I hope you'll get to see your grandpa.",
          DialogueId = 51127123,
          GUID = "7FFDCB9E",
          NextDialogue = 51127124,
          Subtitle = "I hope you'll get to see your grandpa."
        },
        [51127124] = {
          ContentEN = "I will! Grandpa's definitely coming back to stay with me.",
          DialogueId = 51127124,
          GUID = "7FFDCBC8",
          SpeakNpcId = 701061,
          Subtitle = "I will! Grandpa's definitely coming back to stay with me."
        },
        [51127201] = {
          ContentEN = "Hmm... I wonder how long this tree has been standing here.",
          DialogueId = 51127201,
          GUID = "7FFDD86A",
          NextDialogue = 51127202,
          SpeakNpcId = 701062,
          Subtitle = "Hmm... I wonder how long this tree has been standing here."
        },
        [51127202] = {
          ContentEN = "I asked Fang — he said it was already here when he got here. Jie said the same. But they've both been gone for ages now... So when did this tree start growing?",
          DialogueId = 51127202,
          GUID = "7FFDD894",
          NextDialogue = 51127203,
          SpeakNpcId = 701062,
          Subtitle = "I asked Fang — he said it was already here when he got here. Jie said the same. But they've both been gone for ages now... So when did this tree start growing?"
        },
        [51127203] = {
          ContentEN = "Hi there! Did you come to see the big tree too?",
          DialogueId = 51127203,
          GUID = "7FFDD8BE",
          NextOptions = {
            [1] = 51127204,
            [2] = 51127215,
            [3] = 51127218
          },
          SpeakNpcId = 701062,
          Subtitle = "Hi there! Did you come to see the big tree too?"
        },
        [51127204] = {
          ContentEN = "Uh... yes?",
          DialogueId = 51127204,
          GUID = "7FFDD8E8",
          NextDialogue = 51127205,
          Subtitle = "Uh... yes?"
        },
        [51127205] = {
          ContentEN = "Heehee, I knew it! I told Fang and Jie people would be curious about it — but they just laughed! And look, someone really came!",
          DialogueId = 51127205,
          GUID = "7FFDD912",
          NextDialogue = 51127220,
          SpeakNpcId = 701062,
          Subtitle = "Heehee, I knew it! I told Fang and Jie people would be curious about it — but they just laughed! And look, someone really came!"
        },
        [51127206] = {
          ContentEN = "So what's so special about it?",
          DialogueId = 51127206,
          GUID = "7FFDD93C",
          NextDialogue = 51127207,
          Subtitle = "So what's so special about it?"
        },
        [51127207] = {
          ContentEN = "Can't you tell? It doesn't look like the others. See the colour? Kind of like the Heaventree, right? That's what you call it? But the Heaventrees in Huaxu grow under the ground...",
          DialogueId = 51127207,
          GUID = "7FFDD966",
          NextDialogue = 51127208,
          SpeakNpcId = 701062,
          Subtitle = "Can't you tell? It doesn't look like the others. See the colour? Kind of like the Heaventree, right? That's what you call it? But the Heaventrees in Huaxu grow under the ground..."
        },
        [51127208] = {
          ContentEN = "There are lots of trees in Huaxu — fruit trees, fragrant trees, big ones, small ones. Every tree's got its own use. But this one? No flowers, no fruit... it just stands here, quiet as ever.",
          DialogueId = 51127208,
          GUID = "7FFDD990",
          NextDialogue = 51127220,
          SpeakNpcId = 701062,
          Subtitle = "There are lots of trees in Huaxu — fruit trees, fragrant trees, big ones, small ones. Every tree's got its own use. But this one? No flowers, no fruit... it just stands here, quiet as ever."
        },
        [51127209] = {
          ContentEN = "How long's it been here?",
          DialogueId = 51127209,
          GUID = "7FFDD9BA",
          NextDialogue = 51127210,
          Subtitle = "How long's it been here?"
        },
        [51127210] = {
          ContentEN = "That's what I wanna know! I asked lots of Wishen — every one of them said the tree was already this big when they came. One of them's been here since Huaxu began!",
          DialogueId = 51127210,
          GUID = "7FFDD9E4",
          NextDialogue = 51127211,
          SpeakNpcId = 701062,
          Subtitle = "That's what I wanna know! I asked lots of Wishen — every one of them said the tree was already this big when they came. One of them's been here since Huaxu began!"
        },
        [51127211] = {
          ContentEN = "So maybe... this tree's even older than Huaxu itself? If it's that old, how come it's not dead yet? Even we Wishen fade someday, right?",
          DialogueId = 51127211,
          GUID = "7FFDDA0E",
          NextDialogue = 51127220,
          SpeakNpcId = 701062,
          Subtitle = "So maybe... this tree's even older than Huaxu itself? If it's that old, how come it's not dead yet? Even we Wishen fade someday, right?"
        },
        [51127212] = {
          ContentEN = "It's a pretty nice-looking tree.",
          DialogueId = 51127212,
          GUID = "7FFDDA38",
          NextDialogue = 51127213,
          Subtitle = "It's a pretty nice-looking tree."
        },
        [51127213] = {
          ContentEN = "Yeah! I think so too! I told Jie, if we still had bodies, we'd pick some leaves and make little leaf hats!",
          DialogueId = 51127213,
          GUID = "7FFDDA62",
          NextDialogue = 51127214,
          SpeakNpcId = 701062,
          Subtitle = "Yeah! I think so too! I told Jie, if we still had bodies, we'd pick some leaves and make little leaf hats!"
        },
        [51127214] = {
          ContentEN = "Mm... but they say the leaves dry up really fast once you pick them. I don't know if they'd still look pretty after that... Better not pick any, okay? The living who pass by say it brings bad luck.",
          DialogueId = 51127214,
          GUID = "7FFDDA8C",
          NextDialogue = 51127220,
          SpeakNpcId = 701062,
          Subtitle = "Mm... but they say the leaves dry up really fast once you pick them. I don't know if they'd still look pretty after that... Better not pick any, okay? The living who pass by say it brings bad luck."
        },
        [51127215] = {
          ContentEN = "Mm... no.",
          DialogueId = 51127215,
          GUID = "7FFDDAB6",
          NextDialogue = 51127216,
          Subtitle = "Mm... no."
        },
        [51127216] = {
          ContentEN = "Huh? You don't like trees? But this one's special! It's not like any of the others!",
          DialogueId = 51127216,
          GUID = "7FFDDAE0",
          NextDialogue = 51127217,
          SpeakNpcId = 701062,
          Subtitle = "Huh? You don't like trees? But this one's special! It's not like any of the others!"
        },
        [51127217] = {
          ContentEN = "Oh well... if you don't like it, that's fine. I'll just keep thinking about the tree. You can go talk to someone else!",
          DialogueId = 51127217,
          GUID = "7FFDDB0A",
          SpeakNpcId = 701062,
          Subtitle = "Oh well... if you don't like it, that's fine. I'll just keep thinking about the tree. You can go talk to someone else!"
        },
        [51127218] = {
          ContentEN = "See you.",
          DialogueId = 51127218,
          GUID = "7FFDDB34",
          NextDialogue = 51127219,
          Subtitle = "See you."
        },
        [51127219] = {
          ContentEN = "Bye-bye! Next time you come back, let's talk about the tree again!",
          DialogueId = 51127219,
          GUID = "7FFDDB5E",
          SpeakNpcId = 701062,
          Subtitle = "Bye-bye! Next time you come back, let's talk about the tree again!"
        },
        [51127220] = {
          DialogueId = 51127220,
          DialoguePanelType = "None",
          Duration = 0.1,
          FinalDialogueId = 51127219,
          GUID = "7FFDDB88",
          NextOptions = {
            [1] = 51127206,
            [2] = 51127209,
            [3] = 51127212
          }
        },
        [51127301] = {
          ContentEN = "I can hear it — the breath of all things: the whisper of leaves, the murmur beneath the soil, the drip of water. I can hear... everything.",
          DialogueId = 51127301,
          GUID = "7FFDE8D2",
          NextDialogue = 51127302,
          SpeakNpcId = 701063,
          Subtitle = "I can hear it — the breath of all things: the whisper of leaves, the murmur beneath the soil, the drip of water. I can hear... everything."
        },
        [51127302] = {
          ContentEN = "Do you hear it? The tree — it keeps talking. None of them can hear... no one but me... only me.",
          DialogueId = 51127302,
          GUID = "7FFDE8FC",
          NextOptions = {
            [1] = 51127303,
            [2] = 51127305
          },
          SpeakNpcId = 701063,
          Subtitle = "Do you hear it? The tree — it keeps talking. None of them can hear... no one but me... only me."
        },
        [51127303] = {
          ContentEN = "How would a tree talk?",
          DialogueId = 51127303,
          GUID = "7FFDE926",
          ImprPlusId = 1208,
          NextDialogue = 51127304,
          Subtitle = "How would a tree talk?"
        },
        [51127304] = {
          ContentEN = "Of course they do! You just don't listen — your ears are sealed shut! Be still. Feel it. Listen... there! It's speaking again — it's saying...",
          DialogueId = 51127304,
          GUID = "7FFDE950",
          SpeakNpcId = 701063,
          Subtitle = "Of course they do! You just don't listen — your ears are sealed shut! Be still. Feel it. Listen... there! It's speaking again — it's saying..."
        },
        [51127305] = {
          ContentEN = "What is it?",
          DialogueId = 51127305,
          GUID = "7FFDE97A",
          ImprPlusId = 1209,
          NextDialogue = 51127306,
          Subtitle = "What is it?"
        },
        [51127306] = {
          ContentEN = "Hush... its voice... so faint... I can't quite catch it. Just a bit more time... just a little more...",
          DialogueId = 51127306,
          GUID = "7FFDE9A4",
          SpeakNpcId = 701063,
          Subtitle = "Hush... its voice... so faint... I can't quite catch it. Just a bit more time... just a little more..."
        },
        [51127307] = {
          ContentEN = "This tree! It keeps talking!",
          DialogueId = 51127307,
          GUID = "7FFDE9CE",
          NextDialogue = 51127308,
          SpeakNpcId = 701063,
          Subtitle = "This tree! It keeps talking!"
        },
        [51127308] = {
          ContentEN = "I hear it! Louder than before! You — were you drawn here by the leaves as well? Tell me — did you hear it too!?",
          DialogueId = 51127308,
          GUID = "7FFDE9F8",
          NextOptions = {
