        [51127601] = {
          ContentEN = "Let's see... old cotton, bit of tung oil — pack it in tight. Two thin planks either side, nail 'em firm... aye, that'll hold her.",
          DialogueId = 51127601,
          GUID = "7FFE1A0A",
          NextDialogue = 51127602,
          SpeakNpcId = 701067,
          Subtitle = "Let's see... old cotton, bit of tung oil — pack it in tight. Two thin planks either side, nail 'em firm... aye, that'll hold her."
        },
        [51127602] = {
          ContentEN = "Kiddo, do me a favour — pass me the rivets from that tool kit of mine, will you? Look at these old nails — barely holding on. Leave 'em like this and she'll shake herself apart in no time.",
          DialogueId = 51127602,
          GUID = "7FFE1A34",
          NextDialogue = 51127603,
          SpeakNpcId = 701067,
          Subtitle = "Kiddo, do me a favour — pass me the rivets from that tool kit of mine, will you? Look at these old nails — barely holding on. Leave 'em like this and she'll shake herself apart in no time."
        },
        [51127603] = {
          ContentEN = "(You follow his gesture, find the rivets, and hand them over.)",
          DialogueId = 51127603,
          GUID = "7FFE1A5E",
          NextDialogue = 51127604,
          Subtitle = "(You follow his gesture, find the rivets, and hand them over.)"
        },
        [51127604] = {
          ContentEN = "Cheers, kiddo. Right then... ha! Done!",
          DialogueId = 51127604,
          GUID = "7FFE1A88",
          NextOptions = {
            [1] = 51127605
          },
          SpeakNpcId = 701067,
          Subtitle = "Cheers, kiddo. Right then... ha! Done!"
        },
        [51127605] = {
          ContentEN = "You're fixing this boat?",
          DialogueId = 51127605,
          GUID = "7FFE1AB2",
          NextDialogue = 51127606,
          Subtitle = "You're fixing this boat?"
        },
        [51127606] = {
          ContentEN = "Aye. Mr Qiu brought me in to patch this old tub up a bit. Man like him could build a few hundred new ones, yet he clings to this battered heap — funny thing, that.",
          DialogueId = 51127606,
          GUID = "7FFE1ADC",
          NextDialogue = 51127607,
          SpeakNpcId = 701067,
          Subtitle = "Aye. Mr Qiu brought me in to patch this old tub up a bit. Man like him could build a few hundred new ones, yet he clings to this battered heap — funny thing, that."
        },
        [51127607] = {
          ContentEN = "Best step back, kiddo. I need to saw off this rotten bit — noisy work. Don't want you going half-deaf on my account.",
          DialogueId = 51127607,
          GUID = "7FFE1B06",
          SpeakNpcId = 701067,
          Subtitle = "Best step back, kiddo. I need to saw off this rotten bit — noisy work. Don't want you going half-deaf on my account."
        },
        [51127608] = {
          ContentEN = "Best patch that seam up soon... leave her soaking a few more months and the core'll rot clean through.",
          DialogueId = 51127608,
          GUID = "7FFE1B30",
          NextDialogue = 51127609,
          SpeakNpcId = 701067,
          Subtitle = "Best patch that seam up soon... leave her soaking a few more months and the core'll rot clean through."
        },
        [51127609] = {
          ContentEN = "She's old, aye — but good timber lasts. Treat her right and she'll see out a few more decades yet.",
          DialogueId = 51127609,
          GUID = "7FFE1B5A",
          NextDialogue = 51127610,
          SpeakNpcId = 701067,
          Subtitle = "She's old, aye — but good timber lasts. Treat her right and she'll see out a few more decades yet."
        },
        [51127610] = {
          ContentEN = "Ah, you're back, kiddo. Got questions in that head of yours, or just here to shoot the breeze with an old carpenter?",
          DialogueId = 51127610,
          GUID = "7FFE1B84",
          NextDialogue = 51127633,
          SpeakNpcId = 701067,
          Subtitle = "Ah, you're back, kiddo. Got questions in that head of yours, or just here to shoot the breeze with an old carpenter?"
        },
        [51127611] = {
          ContentEN = "What's so special about this boat?",
          DialogueId = 51127611,
          GUID = "7FFE1BAE",
          NextDialogue = 51127612,
          Subtitle = "What's so special about this boat?"
        },
        [51127612] = {
          ContentEN = "Her age — that's what makes her special. Among all Mr Qiu's antiques, she may not be the oldest, but she's surely the biggest.",
          DialogueId = 51127612,
          GUID = "7FFE1BD8",
          NextDialogue = 51127613,
          SpeakNpcId = 701067,
          Subtitle = "Her age — that's what makes her special. Among all Mr Qiu's antiques, she may not be the oldest, but she's surely the biggest."
        },
        [51127613] = {
          ContentEN = "Funny thing about her, though — she's got history. Word is, this boat drifted in long before Haze Market even existed. She ran aground by the shore, and folk settled nearby, hauled her ashore, and put her to use again.",
          DialogueId = 51127613,
          GUID = "7FFE1C02",
          NextDialogue = 51127614,
          SpeakNpcId = 701067,
          Subtitle = "Funny thing about her, though — she's got history. Word is, this boat drifted in long before Haze Market even existed. She ran aground by the shore, and folk settled nearby, hauled her ashore, and put her to use again."
        },
        [51127614] = {
          ContentEN = "Seems she once belonged to the Starweavers. They used to mount a great Stellapass over the hold — but this one's been stripped off, looks like.",
          DialogueId = 51127614,
          GUID = "7FFE1C2C",
          NextDialogue = 51127615,
          SpeakNpcId = 701067,
          Subtitle = "Seems she once belonged to the Starweavers. They used to mount a great Stellapass over the hold — but this one's been stripped off, looks like."
        },
        [51127615] = {
          ContentEN = "Maybe the Starweavers reclaimed it. I asked Mr Qiu, but he wasn't keen to say much.",
          DialogueId = 51127615,
          GUID = "7FFE1C56",
          NextDialogue = 51127633,
          SpeakNpcId = 701067,
          Subtitle = "Maybe the Starweavers reclaimed it. I asked Mr Qiu, but he wasn't keen to say much."
        },
        [51127616] = {
          ContentEN = "Are you a carpenter with the Jishu Sect?",
          DialogueId = 51127616,
          GUID = "7FFE1C80",
          NextDialogue = 51127617,
          Subtitle = "Are you a carpenter with the Jishu Sect?"
        },
        [51127617] = {
          ContentEN = "Sharp eyes, kiddo. Aye, I trained with the Jishu for a spell, but I never cared much for those walking wooden dolls. I've always liked things that stay still while you're carving them.",
          DialogueId = 51127617,
          GUID = "7FFE1CAA",
          NextDialogue = 51127618,
          SpeakNpcId = 701067,
          Subtitle = "Sharp eyes, kiddo. Aye, I trained with the Jishu for a spell, but I never cared much for those walking wooden dolls. I've always liked things that stay still while you're carving them."
        },
        [51127618] = {
          ContentEN = "Huaxu architecture's full of fine craft — soaring eaves, interlocking brackets, carved rails, stone inlay — clever stuff, all of it. If I could master all that, now that'd be a fine way to end a life's work.",
          DialogueId = 51127618,
          GUID = "7FFE1CD4",
          NextDialogue = 51127619,
          SpeakNpcId = 701067,
          Subtitle = "Huaxu architecture's full of fine craft — soaring eaves, interlocking brackets, carved rails, stone inlay — clever stuff, all of it. If I could master all that, now that'd be a fine way to end a life's work."
        },
        [51127619] = {
          ContentEN = "Interest's one thing, but a man's got to eat. Mr Qiu pays well enough — truth be told, one job from him keeps me fed for the year.",
          DialogueId = 51127619,
          GUID = "7FFE1CFE",
          NextDialogue = 51127633,
          SpeakNpcId = 701067,
          Subtitle = "Interest's one thing, but a man's got to eat. Mr Qiu pays well enough — truth be told, one job from him keeps me fed for the year."
        },
        [51127620] = {
          ContentEN = "How old would you say this ship is?",
          DialogueId = 51127620,
          GUID = "7FFE1D28",
          NextDialogue = 51127621,
          Subtitle = "How old would you say this ship is?"
        },
        [51127621] = {
          ContentEN = "Never studied her up close, but by the timber, I'd say she's a hundred years old — give or take. Hard to be sure.",
          DialogueId = 51127621,
          GUID = "7FFE1D52",
          NextDialogue = 51127622,
          SpeakNpcId = 701067,
          Subtitle = "Never studied her up close, but by the timber, I'd say she's a hundred years old — give or take. Hard to be sure."
        },
        [51127622] = {
          ContentEN = "Maybe before Mr Qiu got her, some eccentric with a soft spot for antiques refitted her inside and out. Wouldn't surprise me.",
          DialogueId = 51127622,
          GUID = "7FFE1D7C",
          NextDialogue = 51127623,
          SpeakNpcId = 701067,
          Subtitle = "Maybe before Mr Qiu got her, some eccentric with a soft spot for antiques refitted her inside and out. Wouldn't surprise me."
        },
        [51127623] = {
          ContentEN = "But one thing's certain — she was built by the first Starweavers. Who else would leave such a hollow in her deck for a Stellapass?",
          DialogueId = 51127623,
          GUID = "7FFE1DA6",
          NextDialogue = 51127633,
          SpeakNpcId = 701067,
          Subtitle = "But one thing's certain — she was built by the first Starweavers. Who else would leave such a hollow in her deck for a Stellapass?"
        },
        [51127624] = {
          ContentEN = "Where did this ship come from?",
          DialogueId = 51127624,
          GUID = "7FFE1DD0",
          NextDialogue = 51127625,
          Subtitle = "Where did this ship come from?"
        },
        [51127625] = {
          ContentEN = "Hmm... can't say for sure. Put aside all that mythical nonsense — or those wild tales about the Ministry of Fortune scheming with Haze Market — there are two stories folk reckon might hold water.",
          DialogueId = 51127625,
          GUID = "7FFE1DFA",
          NextDialogue = 51127626,
          SpeakNpcId = 701067,
          Subtitle = "Hmm... can't say for sure. Put aside all that mythical nonsense — or those wild tales about the Ministry of Fortune scheming with Haze Market — there are two stories folk reckon might hold water."
        },
        [51127626] = {
          ContentEN = "First one goes back a hundred years. When the Dark Loong ran wild, Lord Argent struck it down. A Starweaver ship happened to be nearby, homeward bound, and couldn't withstand his fury.",
          DialogueId = 51127626,
          GUID = "7FFE1E24",
          NextDialogue = 51127627,
          SpeakNpcId = 701067,
          Subtitle = "First one goes back a hundred years. When the Dark Loong ran wild, Lord Argent struck it down. A Starweaver ship happened to be nearby, homeward bound, and couldn't withstand his fury."
        },
        [51127627] = {
          ContentEN = "A great surge overturned the ship, killed everyone aboard, and she drifted on the currents till she ran aground here.",
          DialogueId = 51127627,
          GUID = "7FFE1E4E",
          NextDialogue = 51127628,
          SpeakNpcId = 701067,
          Subtitle = "A great surge overturned the ship, killed everyone aboard, and she drifted on the currents till she ran aground here."
        },
        [51127628] = {
          ContentEN = "The other tale is... (lowers his voice) you know the folk round here aren't ones to mess with, right?",
          DialogueId = 51127628,
          GUID = "7FFE1E78",
          NextDialogue = 51127629,
          SpeakNpcId = 701067,
          Subtitle = "The other tale is... (lowers his voice) you know the folk round here aren't ones to mess with, right?"
        },
        [51127629] = {
          ContentEN = "(whispering) They say some cruel, cunning soul wormed his way into the Starweavers' crew — killed the lot, then staged the wreck himself.",
          DialogueId = 51127629,
          GUID = "7FFE1EA2",
          NextDialogue = 51127630,
          SpeakNpcId = 701067,
          Subtitle = "(whispering) They say some cruel, cunning soul wormed his way into the Starweavers' crew — killed the lot, then staged the wreck himself."
        },
        [51127630] = {
          ContentEN = "(regular voice) Ah, just stories to pass the time. Truth's probably duller — someone's old collection, nothing more.",
          DialogueId = 51127630,
          GUID = "7FFE1ECC",
          NextDialogue = 51127633,
          SpeakNpcId = 701067,
          Subtitle = "(regular voice) Ah, just stories to pass the time. Truth's probably duller — someone's old collection, nothing more."
        },
        [51127631] = {
          ContentEN = "That's all I needed to know.",
          DialogueId = 51127631,
          GUID = "7FFE1EF6",
          NextDialogue = 51127632,
          Subtitle = "That's all I needed to know."
        },
        [51127632] = {
          ContentEN = "Heading off, kiddo? Drop by again sometime — old folks like me don't mind a bit of chatter with you fresh-faced kids.",
          DialogueId = 51127632,
          GUID = "7FFE1F20",
          SpeakNpcId = 701067,
          Subtitle = "Heading off, kiddo? Drop by again sometime — old folks like me don't mind a bit of chatter with you fresh-faced kids."
        },
        [51127633] = {
          DialogueId = 51127633,
          DialoguePanelType = "None",
          Duration = 0.1,
          FinalDialogueId = 51127632,
          GUID = "7FFE1F4A",
          NextOptions = {
            [1] = 51127611,
            [2] = 51127616,
