            [5] = 51127631
          }
        },
        [51127701] = {
          ContentEN = "Quite a few new faces in Haze Market of late — far too chatty when they trade. No class whatsoever.",
          DialogueId = 51127701,
          GUID = "7FFE2A72",
          NextDialogue = 51127702,
          SpeakNpcId = 701068,
          Subtitle = "Quite a few new faces in Haze Market of late — far too chatty when they trade. No class whatsoever."
        },
        [51127702] = {
          ContentEN = "Tell me about it. Saw this fine little trinket at a stall the other day — thought I'd buy it for the missus. So I asked the price, and guess what he said?",
          DialogueId = 51127702,
          GUID = "7FFE2A9C",
          NextDialogue = 51127703,
          SpeakNpcId = 701069,
          Subtitle = "Tell me about it. Saw this fine little trinket at a stall the other day — thought I'd buy it for the missus. So I asked the price, and guess what he said?"
        },
        [51127703] = {
          ContentEN = "Let me guess — \"family heirloom,\" \"dug up from a tomb,\" one of those tales best left untold.",
          DialogueId = 51127703,
          GUID = "7FFE2AC6",
          NextDialogue = 51127704,
          SpeakNpcId = 701068,
          Subtitle = "Let me guess — \"family heirloom,\" \"dug up from a tomb,\" one of those tales best left untold."
        },
        [51127704] = {
          ContentEN = "Worse — breaks the Market's rules! Everyone knows the golden line here: talk price, not provenance. Trade the goods, never the tale behind them.",
          DialogueId = 51127704,
          GUID = "7FFE2AF0",
          NextDialogue = 51127705,
          SpeakNpcId = 701069,
          Subtitle = "Worse — breaks the Market's rules! Everyone knows the golden line here: talk price, not provenance. Trade the goods, never the tale behind them."
        },
        [51127705] = {
          ContentEN = "Ha! That reminds me — a few greenhorns at my stall the other day, calling out prices in the open. Not a whisper of code between them. No respect for the rules at all!",
          DialogueId = 51127705,
          GUID = "7FFE2B1A",
          NextDialogue = 51127727,
          SpeakNpcId = 701068,
          Subtitle = "Ha! That reminds me — a few greenhorns at my stall the other day, calling out prices in the open. Not a whisper of code between them. No respect for the rules at all!"
        },
        [51127706] = {
          ContentEN = "You lot have rules?",
          DialogueId = 51127706,
          GUID = "7FFE2B44",
          NextDialogue = 51127707,
          Subtitle = "You lot have rules?"
        },
        [51127707] = {
          ContentEN = "And who the heck are you, kid?",
          DialogueId = 51127707,
          GUID = "7FFE2B6E",
          NextDialogue = 51127708,
          SpeakNpcId = 701069,
          Subtitle = "And who the heck are you, kid?"
        },
        [51127708] = {
          ContentEN = "Easy, now. Take a closer look — that's Mr Qiu's honoured guest.",
          DialogueId = 51127708,
          GUID = "7FFE2B98",
          NextDialogue = 51127709,
          SpeakNpcId = 701068,
          Subtitle = "Easy, now. Take a closer look — that's Mr Qiu's honoured guest."
        },
        [51127709] = {
          ContentEN = "That so? Hard to see what business he'd have with a green pup like this.",
          DialogueId = 51127709,
          GUID = "7FFE2BC2",
          NextDialogue = 51127710,
          SpeakNpcId = 701069,
          Subtitle = "That so? Hard to see what business he'd have with a green pup like this."
        },
        [51127710] = {
          ContentEN = "Well, perhaps the child's got some talent of their own. Mr Qiu always has his reasons — no use second-guessing. So then, what brings you here?",
          DialogueId = 51127710,
          GUID = "7FFE2BEC",
          NextDialogue = 51127727,
          SpeakNpcId = 701068,
          Subtitle = "Well, perhaps the child's got some talent of their own. Mr Qiu always has his reasons — no use second-guessing. So then, what brings you here?"
        },
        [51127711] = {
          ContentEN = "Aren't you black marketeers? Didn't think there'd be rules down here.",
          DialogueId = 51127711,
          GUID = "7FFE2C16",
          NextDialogue = 51127712,
          Subtitle = "Aren't you black marketeers? Didn't think there'd be rules down here."
        },
        [51127712] = {
          ContentEN = "None, back in the day. Haze Market didn't even have a name then — just a place for those without a proper trade, swapping goods as they pleased.",
          DialogueId = 51127712,
          GUID = "7FFE2C40",
          NextDialogue = 51127713,
          SpeakNpcId = 701068,
          Subtitle = "None, back in the day. Haze Market didn't even have a name then — just a place for those without a proper trade, swapping goods as they pleased."
        },
        [51127713] = {
          ContentEN = "If the enforcers of the Nine Chapters caught you, you might lose an arm or a leg — but if you kept your skin and a few coins, life was still decent enough.",
          DialogueId = 51127713,
          GUID = "7FFE2C6A",
          NextDialogue = 51127714,
          SpeakNpcId = 701068,
          Subtitle = "If the enforcers of the Nine Chapters caught you, you might lose an arm or a leg — but if you kept your skin and a few coins, life was still decent enough."
        },
        [51127714] = {
          ContentEN = "Ha! Decent, my foot. Everyone here's a greedy cutthroat. Sooner or later they started fighting over turf, scheming, stabbing each other in the back... it was chaos most days.",
          DialogueId = 51127714,
          GUID = "7FFE2C94",
          NextDialogue = 51127715,
          SpeakNpcId = 701069,
          Subtitle = "Ha! Decent, my foot. Everyone here's a greedy cutthroat. Sooner or later they started fighting over turf, scheming, stabbing each other in the back... it was chaos most days."
        },
        [51127715] = {
          ContentEN = "So, in the end, we needed rules. As long as life stays bearable within those lines — well, that's good enough for most of us.",
          DialogueId = 51127715,
          GUID = "7FFE2CBE",
          NextDialogue = 51127727,
          SpeakNpcId = 701068,
          Subtitle = "So, in the end, we needed rules. As long as life stays bearable within those lines — well, that's good enough for most of us."
        },
        [51127716] = {
          ContentEN = "Why go along with those rules?",
          DialogueId = 51127716,
          GUID = "7FFE2CE8",
          NextDialogue = 51127717,
          Subtitle = "Why go along with those rules?"
        },
        [51127717] = {
          ContentEN = "Let me put it this way. Say there's a big deal — could bring ten percent in profit if it goes well. But if we waste time brawling and double-crossing each other, that chaos alone costs us fifteen. Even if the deal goes through, we still end up losing money.",
          DialogueId = 51127717,
          GUID = "7FFE2D12",
          NextDialogue = 51127718,
          SpeakNpcId = 701068,
          Subtitle = "Let me put it this way. Say there's a big deal — could bring ten percent in profit if it goes well. But if we waste time brawling and double-crossing each other, that chaos alone costs us fifteen. Even if the deal goes through, we still end up losing money."
        },
        [51127718] = {
          ContentEN = "So tell me — would you take that kind of deal?",
          DialogueId = 51127718,
          GUID = "7FFE2D3C",
          NextDialogue = 51127719,
          SpeakNpcId = 701068,
          Subtitle = "So tell me — would you take that kind of deal?"
        },
        [51127719] = {
          ContentEN = "Only a fool would! Ha! When it gets like that, best thing to do's toss out the lot who won't play by the rules.",
          DialogueId = 51127719,
          GUID = "7FFE2D66",
          NextDialogue = 51127727,
          SpeakNpcId = 701069,
          Subtitle = "Only a fool would! Ha! When it gets like that, best thing to do's toss out the lot who won't play by the rules."
        },
        [51127720] = {
          ContentEN = "So Mr Qiu's the one who made those rules?",
          DialogueId = 51127720,
          GUID = "7FFE2D90",
          NextDialogue = 51127721,
          Subtitle = "So Mr Qiu's the one who made those rules?"
        },
        [51127721] = {
          ContentEN = "More or less. We owe him some respect — the man's sharp up here...",
          DialogueId = 51127721,
          GUID = "7FFE2DBA",
          NextDialogue = 51127722,
          SpeakNpcId = 701069,
          Subtitle = "More or less. We owe him some respect — the man's sharp up here..."
        },
        [51127722] = {
          ContentEN = "(He taps his temple.)",
          DialogueId = 51127722,
          GUID = "7FFE2DE4",
          NextDialogue = 51127723,
          Subtitle = "(He taps his temple.)"
        },
        [51127723] = {
          ContentEN = "Quick mind, that man. He's taught us a fair bit, so we give him his due. And his rules aren't hard to follow — most times, he just turns a blind eye anyway.",
          DialogueId = 51127723,
          GUID = "7FFE2E0E",
          NextDialogue = 51127724,
          SpeakNpcId = 701069,
          Subtitle = "Quick mind, that man. He's taught us a fair bit, so we give him his due. And his rules aren't hard to follow — most times, he just turns a blind eye anyway."
        },
        [51127724] = {
          ContentEN = "If he cracked down too hard, who'd still be here? We don't need another Nine Chapters — one's quite enough! Ha ha ha!",
          DialogueId = 51127724,
          GUID = "7FFE2E38",
          NextDialogue = 51127727,
          SpeakNpcId = 701068,
          Subtitle = "If he cracked down too hard, who'd still be here? We don't need another Nine Chapters — one's quite enough! Ha ha ha!"
        },
        [51127725] = {
          ContentEN = "That's enough talk.",
          DialogueId = 51127725,
          GUID = "7FFE2E62",
          NextDialogue = 51127726,
          Subtitle = "That's enough talk."
        },
        [51127726] = {
          ContentEN = "Off so soon? Stay a while — have a word, eh?",
          DialogueId = 51127726,
          GUID = "7FFE2E8C",
          SpeakNpcId = 701068,
          Subtitle = "Off so soon? Stay a while — have a word, eh?"
        },
        [51127727] = {
          DialogueId = 51127727,
          DialoguePanelType = "None",
          Duration = 0.1,
          FinalDialogueId = 51127726,
          GUID = "7FFE2EB6",
          NextOptions = {
            [1] = 51127706,
            [2] = 51127711,
            [3] = 51127716,
            [4] = 51127725
          }
        },
        [51127801] = {
          ContentEN = "Next time I meet Mr Qiu, it'll have to be somewhere respectable — a proper teahouse, not... whatever this place is.",
          DialogueId = 51127801,
          GUID = "7FFE3ADA",
          NextDialogue = 51127802,
          SpeakNpcId = 701070,
          Subtitle = "Next time I meet Mr Qiu, it'll have to be somewhere respectable — a proper teahouse, not... whatever this place is."
        },
        [51127802] = {
          ContentEN = "Having to come down to Haze Market every now and then... dreadful for one's reputation! If anyone were to see me here, I'd never live it down — they'd say I was rubbing shoulders with crooks and swindlers!",
          DialogueId = 51127802,
          GUID = "7FFE3B04",
          NextDialogue = 51127803,
          SpeakNpcId = 701070,
          Subtitle = "Having to come down to Haze Market every now and then... dreadful for one's reputation! If anyone were to see me here, I'd never live it down — they'd say I was rubbing shoulders with crooks and swindlers!"
        },
        [51127803] = {
          ContentEN = "You've got quite the opinion of Haze Market.",
          DialogueId = 51127803,
          GUID = "7FFE3B2E",
          NextDialogue = 51127804,
          SpeakNpcId = 100001,
          Subtitle = "You've got quite the opinion of Haze Market."
        },
        [51127804] = {
          ContentEN = "And who might you be? You don't look like one of the locals... Wait, are you from Mr Qiu's Archaeological Society? No, no, that can't be it — those students never carry anything half as dangerous-looking as that sword of yours.",
          DialogueId = 51127804,
          GUID = "7FFE3B58",
          NextDialogue = 51127805,
          SpeakNpcId = 701070,
          Subtitle = "And who might you be? You don't look like one of the locals... Wait, are you from Mr Qiu's Archaeological Society? No, no, that can't be it — those students never carry anything half as dangerous-looking as that sword of yours."
        },
        [51127805] = {
          ContentEN = "So what exactly are you after, then? I'll have you know I'm one of Mr Qiu's honoured guests — here to discuss business! No need to go flashing that sword about. And just so you're aware — I'm carrying a Lunarose sachet!",
          DialogueId = 51127805,
          GUID = "7FFE3B82",
          NextOptions = {
            [1] = 51127806,
            [2] = 51127817,
            [3] = 51127831
          },
          SpeakNpcId = 701070,
          Subtitle = "So what exactly are you after, then? I'll have you know I'm one of Mr Qiu's honoured guests — here to discuss business! No need to go flashing that sword about. And just so you're aware — I'm carrying a Lunarose sachet!"
        },
        [51127806] = {
          ContentEN = "You're awfully jumpy.",
          DialogueId = 51127806,
          GUID = "7FFE3BAC",
          NextDialogue = 51127807,
          Subtitle = "You're awfully jumpy."
        },
        [51127807] = {
          ContentEN = "Jumpy? Nonsense! I simply know better than to trust the sort that lurk around these streets. If you're not one of them, take my advice — keep your wits about you, or they'll have you fleeced before you know it.",
          DialogueId = 51127807,
          GUID = "7FFE3BD6",
          NextDialogue = 51127808,
          SpeakNpcId = 701070,
          Subtitle = "Jumpy? Nonsense! I simply know better than to trust the sort that lurk around these streets. If you're not one of them, take my advice — keep your wits about you, or they'll have you fleeced before you know it."
        },
        [51127808] = {
          ContentEN = "But if you are one of them... well — forget I said anything!",
          DialogueId = 51127808,
          GUID = "7FFE3C00",
          NextOptions = {
            [1] = 51127809
          },
          SpeakNpcId = 701070,
          Subtitle = "But if you are one of them... well — forget I said anything!"
        },
        [51127809] = {
          ContentEN = "So you really despise the people of Haze Market?",
          DialogueId = 51127809,
          GUID = "7FFE3C2A",
          NextDialogue = 51127810,
          Subtitle = "So you really despise the people of Haze Market?"
        },
        [51127810] = {
          ContentEN = "Hmph! That lot — lawless ruffians, the sort who treat lives like weeds. The dregs of Huaxu — rot that's poisoned its very morals!",
          DialogueId = 51127810,
          GUID = "7FFE3C54",
          NextDialogue = 51127811,
          SpeakNpcId = 701070,
          Subtitle = "Hmph! That lot — lawless ruffians, the sort who treat lives like weeds. The dregs of Huaxu — rot that's poisoned its very morals!"
        },
        [51127811] = {
          ContentEN = "\"Haze Market,\" they call it — nothing but a den of thieves and thugs! There's no honour among them — they'll chase any coin, however dirty. Pfah! As if any of them still knew what a conscience was!",
          DialogueId = 51127811,
          GUID = "7FFE3C7E",
          NextDialogue = 51127812,
          SpeakNpcId = 701070,
          Subtitle = "\"Haze Market,\" they call it — nothing but a den of thieves and thugs! There's no honour among them — they'll chase any coin, however dirty. Pfah! As if any of them still knew what a conscience was!"
        },
        [51127812] = {
          ContentEN = "Best keep your distance. Don't be taken in by their polite faces and fine clothes — every one of them's got blood on his hands.",
          DialogueId = 51127812,
          GUID = "7FFE3CA8",
          NextOptions = {
            [1] = 51127813,
            [2] = 51127815
          },
          SpeakNpcId = 701070,
          Subtitle = "Best keep your distance. Don't be taken in by their polite faces and fine clothes — every one of them's got blood on his hands."
        },
        [51127813] = {
          ContentEN = "But isn't Mr Qiu one of them too?",
          DialogueId = 51127813,
          GUID = "7FFE3CD2",
          NextDialogue = 51127814,
          Subtitle = "But isn't Mr Qiu one of them too?"
        },
        [51127814] = {
          ContentEN = "No, no — Mr Qiu's the exception! He's only here to keep that rabble in line, to stop them doing all those wicked, heartless things. He's the only decent soul in this pit.",
          DialogueId = 51127814,
          GUID = "7FFE3CFC",
          SpeakNpcId = 701070,
          Subtitle = "No, no — Mr Qiu's the exception! He's only here to keep that rabble in line, to stop them doing all those wicked, heartless things. He's the only decent soul in this pit."
        },
        [51127815] = {
          ContentEN = "You really think Mr Qiu's clean?",
          DialogueId = 51127815,
          GUID = "7FFE3D26",
          NextDialogue = 51127816,
          Subtitle = "You really think Mr Qiu's clean?"
        },
        [51127816] = {
          ContentEN = "Mr Qiu's like a lotus rising from the muck — pure and untouched by the filth around him! To stay that clean in a place like this, and still make a name for himself... remarkable, truly remarkable. You're too young to understand.",
          DialogueId = 51127816,
          GUID = "7FFE3D50",
          SpeakNpcId = 701070,
          Subtitle = "Mr Qiu's like a lotus rising from the muck — pure and untouched by the filth around him! To stay that clean in a place like this, and still make a name for himself... remarkable, truly remarkable. You're too young to understand."
        },
        [51127817] = {
          ContentEN = "If you despise Haze Market so much, why do business with Mr Qiu?",
          DialogueId = 51127817,
          GUID = "7FFE3D7A",
          NextDialogue = 51127818,
          Subtitle = "If you despise Haze Market so much, why do business with Mr Qiu?"
        },
        [51127818] = {
          ContentEN = "Mr Qiu... he's different.",
          DialogueId = 51127818,
          GUID = "7FFE3DA4",
          NextDialogue = 51127819,
          SpeakNpcId = 701070,
          Subtitle = "Mr Qiu... he's different."
        },
        [51127819] = {
          ContentEN = "He's a man of real talent — everyone in business, every collector worth his salt, knows his name. More than that, he's a pleasure to deal with — it's like he sees straight through you.",
          DialogueId = 51127819,
          GUID = "7FFE3DCE",
          NextDialogue = 51127820,
          SpeakNpcId = 701070,
          Subtitle = "He's a man of real talent — everyone in business, every collector worth his salt, knows his name. More than that, he's a pleasure to deal with — it's like he sees straight through you."
        },
        [51127820] = {
          ContentEN = "There's a saying — when you work with clever folk, you never need to finish your words. They'll catch your meaning and see it done before you even ask.",
          DialogueId = 51127820,
          GUID = "7FFE3DF8",
          NextOptions = {
            [1] = 51127821
          },
          SpeakNpcId = 701070,
          Subtitle = "There's a saying — when you work with clever folk, you never need to finish your words. They'll catch your meaning and see it done before you even ask."
        },
        [51127821] = {
          ContentEN = "Anything else, then?",
          DialogueId = 51127821,
          GUID = "7FFE3E22",
          NextDialogue = 51127822,
          Subtitle = "Anything else, then?"
        },
        [51127822] = {
          ContentEN = "Oh, plenty! Mr Qiu's generous to a fault — every batch of aged tangerine peel he buys off me is over a hundred years old! Not many in Huaxu can afford such treasures, I can tell you that.",
          DialogueId = 51127822,
          GUID = "7FFE3E4C",
          NextDialogue = 51127823,
          SpeakNpcId = 701070,
          Subtitle = "Oh, plenty! Mr Qiu's generous to a fault — every batch of aged tangerine peel he buys off me is over a hundred years old! Not many in Huaxu can afford such treasures, I can tell you that."
        },
        [51127823] = {
          ContentEN = "He even funds archaeology out of his own pocket! Without his support, half of Huaxu's glorious past would still be buried underground, never seeing daylight.",
          DialogueId = 51127823,
          GUID = "7FFE3E76",
          NextDialogue = 51127824,
          SpeakNpcId = 701070,
          Subtitle = "He even funds archaeology out of his own pocket! Without his support, half of Huaxu's glorious past would still be buried underground, never seeing daylight."
        },
        [51127824] = {
          ContentEN = "And besides that... let me think...",
          DialogueId = 51127824,
          GUID = "7FFE3EA0",
          NextOptions = {
            [1] = 51127825,
            [2] = 51127828
          },
          SpeakNpcId = 701070,
          Subtitle = "And besides that... let me think..."
        },
        [51127825] = {
          ContentEN = "Yeah?",
          DialogueId = 51127825,
          GUID = "7FFE3ECA",
          NextDialogue = 51127826,
          Subtitle = "Yeah?"
        },
        [51127826] = {
          ContentEN = "Generous, that's what he is! Those of us who deal with him often — every festival, every holiday — Mr Qiu never forgets us. One time it's fine pastries, another time rare curios... he's thoughtful like that, always is.",
          DialogueId = 51127826,
          GUID = "7FFE3EF4",
          NextDialogue = 51127827,
          SpeakNpcId = 701070,
          Subtitle = "Generous, that's what he is! Those of us who deal with him often — every festival, every holiday — Mr Qiu never forgets us. One time it's fine pastries, another time rare curios... he's thoughtful like that, always is."
        },
        [51127827] = {
          ContentEN = "If he weren't so good to us, do you think I'd drag myself all the way down to this wretched place just to wait on him?",
          DialogueId = 51127827,
          GUID = "7FFE3F1E",
          SpeakNpcId = 701070,
          Subtitle = "If he weren't so good to us, do you think I'd drag myself all the way down to this wretched place just to wait on him?"
        },
        [51127828] = {
          ContentEN = "All right, all right — I get it, you're a hardcore fan of his.",
          DialogueId = 51127828,
          GUID = "7FFE3F48",
          NextDialogue = 51127829,
          Subtitle = "All right, all right — I get it, you're a hardcore fan of his."
        },
        [51127829] = {
          ContentEN = "A what now? \"Hardcore\"? You young folk and your bizarre jargon — half the time I've no idea what you're on about! Just like my eight-year-old, always tossing around some new term... what was it she said the other day—?",
          DialogueId = 51127829,
          GUID = "7FFE3F72",
          NextDialogue = 51127830,
          SpeakNpcId = 701070,
          Subtitle = "A what now? \"Hardcore\"? You young folk and your bizarre jargon — half the time I've no idea what you're on about! Just like my eight-year-old, always tossing around some new term... what was it she said the other day—?"
        },
        [51127830] = {
          ContentEN = "Speaking of my little girl — she's quite taken with Mr Qiu herself! Whenever he visits, he brings her sweets, fine pastries... she's forever asking when he'll come again.",
          DialogueId = 51127830,
          GUID = "7FFE3F9C",
          SpeakNpcId = 701070,
          Subtitle = "Speaking of my little girl — she's quite taken with Mr Qiu herself! Whenever he visits, he brings her sweets, fine pastries... she's forever asking when he'll come again."
        },
        [51127831] = {
          ContentEN = "I'm off.",
          DialogueId = 51127831,
          GUID = "7FFE3FC6",
          NextDialogue = 51127832,
          Subtitle = "I'm off."
        },
        [51127832] = {
          ContentEN = "Off already? But you never told me what brings you here!",
          DialogueId = 51127832,
          GUID = "7FFE3FF0",
          SpeakNpcId = 701070,
          Subtitle = "Off already? But you never told me what brings you here!"
        },
        [51127901] = {
