        },
        [51127915] = {
          ContentEN = "(From dust it rose — and to dust it fades...)",
          DialogueId = 51127915,
          GUID = "7FFE4D8E",
          Subtitle = "(From dust it rose — and to dust it fades...)"
        },
        [51128001] = {
          ContentEN = "Brr... freezing again. Rotten weather. Everything's frosted up — gears stiff, sensors half-asleep. Oh dear. Mr Qiu'll have to foot the repairs again.",
          DialogueId = 51128001,
          GUID = "7FFE5BAA",
          NextDialogue = 51128002,
          SpeakNpcId = 701072,
          Subtitle = "Brr... freezing again. Rotten weather. Everything's frosted up — gears stiff, sensors half-asleep. Oh dear. Mr Qiu'll have to foot the repairs again."
        },
        [51128002] = {
          ContentEN = "Hmm? Who are you? What are you doing out here? Off you pop, now. This isn't a place ordinary folk are meant to wander!",
          DialogueId = 51128002,
          GUID = "7FFE5BD4",
          NextOptions = {
            [1] = 51128003,
            [2] = 51128005
          },
          SpeakNpcId = 701072,
          Subtitle = "Hmm? Who are you? What are you doing out here? Off you pop, now. This isn't a place ordinary folk are meant to wander!"
        },
        [51128003] = {
          ContentEN = "Mr Qiu sent me.",
          DialogueId = 51128003,
          GUID = "7FFE5BFE",
          ImprPlusId = 1208,
          NextDialogue = 51128004,
          Subtitle = "Mr Qiu sent me."
        },
        [51128004] = {
          ContentEN = "He did? That can't be right. He said the Gritblight Expanse was my brief alone. Before I left he even said— what was it — \"no old records, nothing worth digging into,\" or something along those lines.",
          DialogueId = 51128004,
          GUID = "7FFE5C28",
          SpeakNpcId = 701072,
          Subtitle = "He did? That can't be right. He said the Gritblight Expanse was my brief alone. Before I left he even said— what was it — \"no old records, nothing worth digging into,\" or something along those lines."
        },
        [51128005] = {
          ContentEN = "You looked as if you needed a hand, so I thought I'd check in.",
          DialogueId = 51128005,
          GUID = "7FFE5C52",
          ImprPlusId = 1207,
          NextDialogue = 51128006,
          Subtitle = "You looked as if you needed a hand, so I thought I'd check in."
        },
        [51128006] = {
          ContentEN = "Oh, thank you, kind soul! I've been out here so long — camping in the wind and sleeping under the stars — that I'd almost forgotten normal life being existed... apart from those Sable Bi'an prowling around.",
          DialogueId = 51128006,
          GUID = "7FFE5C7C",
          NextDialogue = 51128007,
          SpeakNpcId = 701072,
          Subtitle = "Oh, thank you, kind soul! I've been out here so long — camping in the wind and sleeping under the stars — that I'd almost forgotten normal life being existed... apart from those Sable Bi'an prowling around."
        },
        [51128007] = {
          ContentEN = "Still, you'd best go home and grab a thicker coat. With the swings here you'll be frozen stiff in no time.",
          DialogueId = 51128007,
          GUID = "7FFE5CA6",
          NextDialogue = 51128008,
          SpeakNpcId = 701072,
          Subtitle = "Still, you'd best go home and grab a thicker coat. With the swings here you'll be frozen stiff in no time."
        },
        [51128008] = {
          ContentEN = "Whew. I'd better throw on a couple more layers myself.",
          DialogueId = 51128008,
          GUID = "7FFE5CD0",
          SpeakNpcId = 701072,
          Subtitle = "Whew. I'd better throw on a couple more layers myself."
        },
        [51128101] = {
          ContentEN = "Hot one minute, freezing the next... My grandmother always said it used to be spring all round.",
          DialogueId = 51128101,
          GUID = "7FFE6C12",
          NextDialogue = 51128102,
          SpeakNpcId = 701072,
          Subtitle = "Hot one minute, freezing the next... My grandmother always said it used to be spring all round."
        },
        [51128102] = {
          ContentEN = "Ah—! It's scorching again! Heat makes me tetchy. Ugh, this wretched coat — off you come!",
          DialogueId = 51128102,
          GUID = "7FFE6C3C",
          NextDialogue = 51128103,
          SpeakNpcId = 701072,
          Subtitle = "Ah—! It's scorching again! Heat makes me tetchy. Ugh, this wretched coat — off you come!"
        },
        [51128103] = {
          ContentEN = "Hey! Who are y— oh, right, I remember you. Back again, are you? Brought a coat this time?",
          DialogueId = 51128103,
          GUID = "7FFE6C66",
          NextOptions = {
            [1] = 51128104,
            [2] = 51128106,
            [3] = 51128120
          },
          SpeakNpcId = 701072,
          Subtitle = "Hey! Who are y— oh, right, I remember you. Back again, are you? Brought a coat this time?"
        },
        [51128104] = {
          ContentEN = "Got plenty in my pack.",
          DialogueId = 51128104,
          GUID = "7FFE6C90",
          NextDialogue = 51128105,
          Subtitle = "Got plenty in my pack."
        },
        [51128105] = {
          ContentEN = "Good. You've no idea how absurd this weather gets — teeth chattering one minute, sweating buckets the next. It's crazy.",
          DialogueId = 51128105,
          GUID = "7FFE6CBA",
          NextOptions = {
            [1] = 51128108
          },
          SpeakNpcId = 701072,
          Subtitle = "Good. You've no idea how absurd this weather gets — teeth chattering one minute, sweating buckets the next. It's crazy."
        },
        [51128106] = {
          ContentEN = "I don't mind the cold or the heat.",
          DialogueId = 51128106,
          GUID = "7FFE6CE4",
          NextDialogue = 51128107,
          Subtitle = "I don't mind the cold or the heat."
        },
        [51128107] = {
          ContentEN = "What? Then you've not seen it at its worst. Give it an hour — teeth chattering one minute, sweating buckets the next. It's crazy.",
          DialogueId = 51128107,
          GUID = "7FFE6D0E",
          NextOptions = {
            [1] = 51128108
          },
          SpeakNpcId = 701072,
          Subtitle = "What? Then you've not seen it at its worst. Give it an hour — teeth chattering one minute, sweating buckets the next. It's crazy."
        },
        [51128108] = {
          ContentEN = "What's with the weather here?",
          DialogueId = 51128108,
          GUID = "7FFE6D38",
          NextDialogue = 51128109,
          Subtitle = "What's with the weather here?"
        },
        [51128109] = {
          ContentEN = "Ha! You've come to the right person. I've been out here so long I've nearly pieced the whole story together — this place and that blasted Blightening.",
          DialogueId = 51128109,
          GUID = "7FFE6D62",
          NextDialogue = 51128122,
          SpeakNpcId = 701072,
          Subtitle = "Ha! You've come to the right person. I've been out here so long I've nearly pieced the whole story together — this place and that blasted Blightening."
        },
        [51128110] = {
          ContentEN = "What was it like before?",
          DialogueId = 51128110,
          GUID = "7FFE6D8C",
          NextDialogue = 51128111,
          Subtitle = "What was it like before?"
        },
        [51128111] = {
          ContentEN = "Long ago — so my great-grandmother used to say — it was all green hills and clear streams, spring the year round. People even planted Heavenstep on the slopes.",
          DialogueId = 51128111,
          GUID = "7FFE6DB6",
          NextDialogue = 51128112,
          SpeakNpcId = 701072,
          Subtitle = "Long ago — so my great-grandmother used to say — it was all green hills and clear streams, spring the year round. People even planted Heavenstep on the slopes."
        },
        [51128112] = {
          ContentEN = "When the flowers were out, the hills went scarlet and the scent was heady enough to make travellers woozy. Even the Starweavers complained it could make you swoon.",
          DialogueId = 51128112,
          GUID = "7FFE6DE0",
          SpeakNpcId = 701072,
          Subtitle = "When the flowers were out, the hills went scarlet and the scent was heady enough to make travellers woozy. Even the Starweavers complained it could make you swoon."
        },
        [51128113] = {
          ContentEN = "How did it get like this?",
          DialogueId = 51128113,
          GUID = "7FFE6E0A",
          NextDialogue = 51128114,
          Subtitle = "How did it get like this?"
        },
        [51128114] = {
          ContentEN = "What else? The Scourge of Zhuyin, of course. Vile thing — spewing a black mist that rolls in from the sea and smothers the lot.",
          DialogueId = 51128114,
          GUID = "7FFE6E34",
          NextDialogue = 51128115,
          SpeakNpcId = 701072,
          Subtitle = "What else? The Scourge of Zhuyin, of course. Vile thing — spewing a black mist that rolls in from the sea and smothers the lot."
        },
        [51128115] = {
          ContentEN = "The black mist was foul. Wherever it spread, the air flipped from freezing to scorching in a heartbeat. The jolts split rock to bits, and every flower and blade of grass withered under a strange crust.",
          DialogueId = 51128115,
          GUID = "7FFE6E5E",
          NextDialogue = 51128116,
          SpeakNpcId = 701072,
          Subtitle = "The black mist was foul. Wherever it spread, the air flipped from freezing to scorching in a heartbeat. The jolts split rock to bits, and every flower and blade of grass withered under a strange crust."
        },
        [51128116] = {
          ContentEN = "That's what we call Blightening — the very thing I've been studying out here.",
          DialogueId = 51128116,
          GUID = "7FFE6E88",
          SpeakNpcId = 701072,
          Subtitle = "That's what we call Blightening — the very thing I've been studying out here."
        },
        [51128117] = {
          ContentEN = "What exactly is Blightening?",
          DialogueId = 51128117,
          GUID = "7FFE6EB2",
          NextDialogue = 51128118,
          Subtitle = "What exactly is Blightening?"
        },
        [51128118] = {
          ContentEN = "Hmm... hard to pin down. My best guess is that the black mist carries crystalline motes — too fine to see, easy to breathe in without noticing.",
          DialogueId = 51128118,
          GUID = "7FFE6EDC",
          NextDialogue = 51128119,
          SpeakNpcId = 701072,
          Subtitle = "Hmm... hard to pin down. My best guess is that the black mist carries crystalline motes — too fine to see, easy to breathe in without noticing."
        },
        [51128119] = {
          ContentEN = "Anything that takes them in warps out of shape. As for the cause... no idea. Uncanny stuff — even the Bi'an can't fight it off.",
          DialogueId = 51128119,
          GUID = "7FFE6F06",
          SpeakNpcId = 701072,
          Subtitle = "Anything that takes them in warps out of shape. As for the cause... no idea. Uncanny stuff — even the Bi'an can't fight it off."
        },
        [51128120] = {
          ContentEN = "That'll do for now.",
          DialogueId = 51128120,
          GUID = "7FFE6F30",
          NextDialogue = 51128121,
          Subtitle = "That'll do for now."
        },
        [51128121] = {
          ContentEN = "Aw, don't go! Took me ages to find someone to chat with. If I don't talk to a normal human soon, my tongue'll go rusty.",
          DialogueId = 51128121,
          GUID = "7FFE6F5A",
          SpeakNpcId = 701072,
          Subtitle = "Aw, don't go! Took me ages to find someone to chat with. If I don't talk to a normal human soon, my tongue'll go rusty."
        },
        [51128122] = {
          DialogueId = 51128122,
          DialoguePanelType = "None",
          Duration = 0.1,
          FinalDialogueId = 51128121,
          GUID = "7FFE6F84",
          NextOptions = {
            [1] = 51128110,
            [2] = 51128113,
            [3] = 51128117,
            [4] = 51128120
          }
        },
        [51128201] = {
          ContentEN = "What— no place to set the incense? Good job I brought a burner! After risking my neck to get here, it'd be a bit rich to leave empty-handed!",
          DialogueId = 51128201,
          GUID = "7FFE7C7A",
          NextOptions = {
            [1] = 51128202,
            [2] = 51128204
          },
          SpeakNpcId = 701073,
          Subtitle = "What— no place to set the incense? Good job I brought a burner! After risking my neck to get here, it'd be a bit rich to leave empty-handed!"
        },
        [51128202] = {
          ContentEN = "What are you doing out here? It's dangerous.",
          DialogueId = 51128202,
          GUID = "7FFE7CA4",
          ImprPlusId = 1207,
          NextDialogue = 51128203,
          Subtitle = "What are you doing out here? It's dangerous."
        },
        [51128203] = {
          ContentEN = "I know! Thanks for the warning. That's exactly why I'm here. I'll light a stick of Lunarose for Lord Argent where only the brave venture, and beg Them to purge the Scourge of Zhuyin once and for all!",
          DialogueId = 51128203,
          GUID = "7FFE7CCE",
          SpeakNpcId = 701073,
          Subtitle = "I know! Thanks for the warning. That's exactly why I'm here. I'll light a stick of Lunarose for Lord Argent where only the brave venture, and beg Them to purge the Scourge of Zhuyin once and for all!"
        },
        [51128204] = {
          ContentEN = "Linger any longer and a Sable Bi'an will be along to make a meal of you.",
          DialogueId = 51128204,
          GUID = "7FFE7CF8",
          ImprPlusId = 1205,
          NextDialogue = 51128205,
          Subtitle = "Linger any longer and a Sable Bi'an will be along to make a meal of you."
        },
        [51128205] = {
          ContentEN = "No need to fret. I know it's dangerous — that's the point. I'm lighting a stick of Lunarose for Lord Argent right here, where only the brave venture, and begging Him to purge the Scourge of Zhuyin for good.",
          DialogueId = 51128205,
          GUID = "7FFE7D22",
          NextDialogue = 51128206,
          SpeakNpcId = 701073,
          Subtitle = "No need to fret. I know it's dangerous — that's the point. I'm lighting a stick of Lunarose for Lord Argent right here, where only the brave venture, and begging Him to purge the Scourge of Zhuyin for good."
        },
        [51128206] = {
          ContentEN = "Don't worry about me. I've no weapon, true, but I've got quick legs and a quicker head! It isn't my first time out here. You watch yourself — if a Sable Bi'an shows up, I'll be off like a shot and won't have time to haul you along.",
          DialogueId = 51128206,
          GUID = "7FFE7D4C",
          NextDialogue = 51128207,
          SpeakNpcId = 701073,
          Subtitle = "Don't worry about me. I've no weapon, true, but I've got quick legs and a quicker head! It isn't my first time out here. You watch yourself — if a Sable Bi'an shows up, I'll be off like a shot and won't have time to haul you along."
        },
        [51128207] = {
          ContentEN = "Go on then — don't trouble over me!",
          DialogueId = 51128207,
          GUID = "7FFE7D76",
          SpeakNpcId = 701073,
          Subtitle = "Go on then — don't trouble over me!"
        },
        [51128208] = {
          ContentEN = "Here we are! Once I light the incense, Lord Argent will surely descend and wipe that wicked beast out for good — just like in the old tales!",
          DialogueId = 51128208,
          GUID = "7FFE7DA0",
          NextDialogue = 51128209,
          SpeakNpcId = 701073,
          Subtitle = "Here we are! Once I light the incense, Lord Argent will surely descend and wipe that wicked beast out for good — just like in the old tales!"
        },
        [51128209] = {
          ContentEN = "Huh? You again. You've got nerve, coming back to a place like this.",
          DialogueId = 51128209,
          GUID = "7FFE7DCA",
          NextOptions = {
            [1] = 51128210,
            [2] = 51128233
          },
          SpeakNpcId = 701073,
          Subtitle = "Huh? You again. You've got nerve, coming back to a place like this."
        },
        [51128210] = {
          ContentEN = "I could say the same about you...",
          DialogueId = 51128210,
          GUID = "7FFE7DF4",
          NextDialogue = 51128211,
          Subtitle = "I could say the same about you..."
        },
        [51128211] = {
          ContentEN = "Ha! Fair point. Like I said, I'm quick on my feet. If trouble turns up, I'll be gone before it catches me. You should head out, though — safer that way.",
          DialogueId = 51128211,
          GUID = "7FFE7E1E",
          NextOptions = {
            [1] = 51128212
          },
          SpeakNpcId = 701073,
          Subtitle = "Ha! Fair point. Like I said, I'm quick on my feet. If trouble turns up, I'll be gone before it catches me. You should head out, though — safer that way."
        },
        [51128212] = {
          ContentEN = "I don't need to run. I can drive the Sable Bi'an off myself.",
          DialogueId = 51128212,
          GUID = "7FFE7E48",
          NextDialogue = 51128213,
          Subtitle = "I don't need to run. I can drive the Sable Bi'an off myself."
        },
        [51128213] = {
          ContentEN = "Really? Didn't take you for the tough sort. You're not from Huaxu, are you? Your clothes don't look Huaxu, either.",
          DialogueId = 51128213,
          GUID = "7FFE7E72",
          NextDialogue = 51128214,
          SpeakNpcId = 701073,
          Subtitle = "Really? Didn't take you for the tough sort. You're not from Huaxu, are you? Your clothes don't look Huaxu, either."
        },
        [51128214] = {
          ContentEN = "Will you join me in offering incense, then? Two voices together — surely Lord Argent will hear us better.",
          DialogueId = 51128214,
          GUID = "7FFE7E9C",
          NextOptions = {
            [1] = 51128215,
            [2] = 51128221
          },
          SpeakNpcId = 701073,
          Subtitle = "Will you join me in offering incense, then? Two voices together — surely Lord Argent will hear us better."
        },
        [51128215] = {
          ContentEN = "Doesn't it feel a bit odd to offer incense out in the middle of nowhere?",
          DialogueId = 51128215,
          GUID = "7FFE7EC6",
          NextDialogue = 51128216,
          Subtitle = "Doesn't it feel a bit odd to offer incense out in the middle of nowhere?"
        },
        [51128216] = {
          ContentEN = "You don't know the half of it. You know why the skies twist and churn here, don't you? It's because of the Scourge of Zhuyin a hundred years ago. But do you know why that foul beast brought such ruin on Huaxu?",
          DialogueId = 51128216,
          GUID = "7FFE7EF0",
          NextDialogue = 51128217,
          SpeakNpcId = 701073,
          Subtitle = "You don't know the half of it. You know why the skies twist and churn here, don't you? It's because of the Scourge of Zhuyin a hundred years ago. But do you know why that foul beast brought such ruin on Huaxu?"
        },
        [51128217] = {
          ContentEN = "All right, I won't keep you guessing. Long ago in Huaxu, there lived a wicked creature called Zhuyin.",
          DialogueId = 51128217,
          GUID = "7FFE7F1A",
          NextDialogue = 51128218,
          SpeakNpcId = 701073,
          Subtitle = "All right, I won't keep you guessing. Long ago in Huaxu, there lived a wicked creature called Zhuyin."
        },
        [51128218] = {
          ContentEN = "It sowed unrest in people's hearts and drove them to harm one another. The land fell into misery and people knew no peace, so they lit incense — one after another — and prayed for Lord Argent's help.",
          DialogueId = 51128218,
          GUID = "7FFE7F44",
          NextDialogue = 51128219,
          SpeakNpcId = 701073,
          Subtitle = "It sowed unrest in people's hearts and drove them to harm one another. The land fell into misery and people knew no peace, so they lit incense — one after another — and prayed for Lord Argent's help."
        },
        [51128219] = {
          ContentEN = "On high, Lord Argent caught the scent of the incense, learned of Zhuyin's crime, and grew wrathful. It called on Its divine might and banished the beast beyond Huaxu's shores.",
          DialogueId = 51128219,
          GUID = "7FFE7F6E",
          NextDialogue = 51128220,
          SpeakNpcId = 701073,
          Subtitle = "On high, Lord Argent caught the scent of the incense, learned of Zhuyin's crime, and grew wrathful. It called on Its divine might and banished the beast beyond Huaxu's shores."
        },
        [51128220] = {
          ContentEN = "Then the immortals of the Xuanheng Sect combined their strength, bound Zhuyin with the Loong Seal, and sealed it upon the sacred mountain. Only then did Huaxu know peace again.",
          DialogueId = 51128220,
          GUID = "7FFE7F98",
          NextOptions = {
            [1] = 51128223
          },
          SpeakNpcId = 701073,
          Subtitle = "Then the immortals of the Xuanheng Sect combined their strength, bound Zhuyin with the Loong Seal, and sealed it upon the sacred mountain. Only then did Huaxu know peace again."
        },
        [51128221] = {
          ContentEN = "Sure. Let's do this.",
          DialogueId = 51128221,
          GUID = "7FFE7FC2",
          NextDialogue = 51128222,
          Subtitle = "Sure. Let's do this."
        },
        [51128222] = {
          ContentEN = "(You take a stick of incense and join him in the offering.)",
          DialogueId = 51128222,
          GUID = "7FFE7FEC",
          NextOptions = {
            [1] = 51128223
          },
          Subtitle = "(You take a stick of incense and join him in the offering.)"
        },
        [51128223] = {
          ContentEN = "So you mean to call Lord Argent the way people did in the old tales?",
          DialogueId = 51128223,
          GUID = "7FFE8016",
          NextDialogue = 51128224,
          Subtitle = "So you mean to call Lord Argent the way people did in the old tales?"
        },
        [51128224] = {
          ContentEN = "That's right. These days everyone's burning incense everywhere — Lord Argent must catch it from all sides and hardly know who needs It most! So I figured if I burn mine here, where no one ever comes, It'll take notice.",
          DialogueId = 51128224,
          GUID = "7FFE8040",
          NextDialogue = 51128225,
          SpeakNpcId = 701073,
          Subtitle = "That's right. These days everyone's burning incense everywhere — Lord Argent must catch it from all sides and hardly know who needs It most! So I figured if I burn mine here, where no one ever comes, It'll take notice."
        },
        [51128225] = {
          ContentEN = "Take notice of what, exactly?",
          DialogueId = 51128225,
          GUID = "7FFE806A",
          NextDialogue = 51128226,
          SpeakNpcId = 100001,
          Subtitle = "Take notice of what, exactly?"
        },
        [51128226] = {
          ContentEN = "That there's incense burning in the middle of nowhere, of course! They'll see how sincere my heart is!",
          DialogueId = 51128226,
          GUID = "7FFE8094",
          NextDialogue = 51128227,
          SpeakNpcId = 701073,
          Subtitle = "That there's incense burning in the middle of nowhere, of course! They'll see how sincere my heart is!"
        },
        [51128227] = {
          ContentEN = "...",
          DialogueId = 51128227,
          GUID = "7FFE80BE",
          NextDialogue = 51128228,
          SpeakNpcId = 100001,
          Subtitle = "..."
        },
        [51128228] = {
          ContentEN = "Right, enough chatter. Will you light another stick with me?",
          DialogueId = 51128228,
          GUID = "7FFE80E8",
          NextOptions = {
            [1] = 51128229,
            [2] = 51128231
          },
          SpeakNpcId = 701073,
          Subtitle = "Right, enough chatter. Will you light another stick with me?"
        },
        [51128229] = {
          ContentEN = "All right.",
          DialogueId = 51128229,
          GUID = "7FFE8112",
          NextDialogue = 51128230,
          Subtitle = "All right."
        },
        [51128230] = {
          ContentEN = "Great! Incense side by side today — fast friends tomorrow!",
          DialogueId = 51128230,
          GUID = "7FFE813C",
          SpeakNpcId = 701073,
          Subtitle = "Great! Incense side by side today — fast friends tomorrow!"
        },
        [51128231] = {
          ContentEN = "I'll pass.",
          DialogueId = 51128231,
          GUID = "7FFE8166",
          NextDialogue = 51128232,
          Subtitle = "I'll pass."
        },
        [51128232] = {
          ContentEN = "Fair enough — outsiders don't always get our ways.",
          DialogueId = 51128232,
          GUID = "7FFE8190",
          SpeakNpcId = 701073,
          Subtitle = "Fair enough — outsiders don't always get our ways."
        },
        [51128233] = {
          ContentEN = "I've got other things to do. I should get going.",
          DialogueId = 51128233,
          GUID = "7FFE81BA",
          NextDialogue = 51128234,
          Subtitle = "I've got other things to do. I should get going."
        },
        [51128234] = {
          ContentEN = "All right, then. Until fate brings us together again!",
          DialogueId = 51128234,
          GUID = "7FFE81E4",
          SpeakNpcId = 701073,
          Subtitle = "All right, then. Until fate brings us together again!"
        },
        [51128301] = {
          ContentEN = "(No hand is named. This stele bears these words:)",
          DialogueId = 51128301,
          GUID = "7FFE8CE2",
          NextDialogue = 51128302,
          Subtitle = "(No hand is named. This stele bears these words:)"
        },
        [51128302] = {
