        [51140060] = {
          Camera = "-81.537109,-85.851562,132.566406,0.000039,0.0,11.891485,18.482418,157.042984,false,Manual,1.41721",
          ContentEN = "In her youth, she wrote of a patient whose wife had perished in the Great Plague. From then on, he suffered an ailment of the heart, spending his days believing she still walked among the living, speaking to one who was no longer in this world.",
          DialogueId = 51140060,
          GUID = "80061618",
          SpeakNpcId = 701075,
          Subtitle = "In her youth, she wrote of a patient whose wife had perished in the Great Plague. From then on, he suffered an ailment of the heart, spending his days believing she still walked among the living, speaking to one who was no longer in this world.",
          TalkActionId = {
            [1] = "701075:Talk03_Start"
          }
        },
        [51140061] = {
          Camera = "-51.0,-35.339844,149.195312,0.000083,1.15922,9.291944,35.000008,116.515465,false,Manual,7.0",
          ContentEN = "She wrote that he was like a mirror held up to her — just as she would speak to me in my long sleep. A thing both curious and foolish.",
          DialogueId = 51140061,
          GUID = "80061642",
          LookAt = {
            [1] = "100001:n(200002)",
            [2] = "200002:n(100001)"
          },
          SpeakNpcId = 701075,
          Subtitle = "She wrote that he was like a mirror held up to her — just as she would speak to me in my long sleep. A thing both curious and foolish.",
          TalkActionId = {
            [1] = "701075:Talk03ToThink_Start"
          }
        },
        [51140062] = {
          ContentEN = "He refused all medicine, so my sister devised a gentle ruse. She told him she must also tend to his wife and, under the pretext of testing the remedy, had him take two doses each time — one for \"her\", and the other for him to test its effect. She insisted that he drink his dose first.",
          DialogueId = 51140062,
          GUID = "8006166C",
          LookAt = {
            [1] = "100001:n(100001)",
            [2] = "200002:n(200002)"
          },
          SpeakNpcId = 701075,
          Subtitle = "He refused all medicine, so my sister devised a gentle ruse. She told him she must also tend to his wife and, under the pretext of testing the remedy, had him take two doses each time — one for \"her\", and the other for him to test its effect. She insisted that he drink his dose first.",
          TalkActionId = {
            [1] = "701075:Talk03ToThink_End"
          }
        },
