        },
        [51150003] = {
          Camera = "11.114258,106.112305,84.475708,0.000119,19.999981,-140.838303,64.81044,100000.0,false,DoNotOverride,7.0",
          ContentEN = "What...? You mean Xianshu... she is no longer in this world? Because... I have been dead for more than ninety years...?",
          DialogueId = 51150003,
          GUID = "800C755E",
          SpeakNpcId = 701074,
          Subtitle = "What...? You mean Xianshu... she is no longer in this world? Because... I have been dead for more than ninety years...?"
        },
        [51150004] = {
          Camera = "-125.262207,40.953125,171.12085,0.000126,-15.293818,-18.234081,35.000015,117.407356,false,Manual,3.0",
          ContentEN = "That's right.",
          DialogueId = 51150004,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "800C7588",
          SpeakNpcId = 100001,
          Subtitle = "That's right.",
          TalkActionId = {
            [1] = "100001：Explain01_End"
          }
        },
        [51150005] = {
          Camera = "121.967773,-57.251953,229.506348,0.000098,-10.894431,176.76123,35.0,100000.0,false,DoNotOverride,7.0",
          ContentEN = "Then I've been wandering here all this time... the Spring of Yu... all these long, empty years...",
          DialogueId = 51150005,
          GUID = "800C75B2",
          SpeakNpcId = 701074,
          Subtitle = "Then I've been wandering here all this time... the Spring of Yu... all these long, empty years..."
        },
        [51150006] = {
          Camera = "121.967773,-57.251953,229.506348,0.000098,-10.894431,176.76123,35.0,100000.0,false,DoNotOverride,7.0",
          ContentEN = "And Xianshu...? Where did she go? Has she... has she been well all these years...?",
          DialogueId = 51150006,
          GUID = "800C75DC",
          SpeakNpcId = 701074,
          Subtitle = "And Xianshu...? Where did she go? Has she... has she been well all these years...?"
        },
        [51150007] = {
          Camera = "-455.513672,-227.362305,283.345703,0.000077,-20.494774,26.363897,35.0,100000.0,false,DoNotOverride,7.0",
          ContentEN = "(You and Snow exchange a glance.)",
          DialogueId = 51150007,
          GUID = "800C7606",
          LookAt = {
            [1] = "100001:n(200002)",
            [2] = "200002:n(100001)"
          },
          SpeakNpcId = 0,
          Subtitle = "(You and Snow exchange a glance.)"
        },
        [51150008] = {
          Camera = "-243.208984,-3.944336,191.368408,-0.0,-15.293783,-3.434053,35.000015,266.740662,false,Manual,7.0",
          ContentEN = "When she was ill, you cared for her as best you could. But after so many years of sickness, she feared she'd only burden you further. So... she chose to leave home.",
          DialogueId = 51150008,
          GUID = "800C7630",
          LookAt = {
            [1] = "100001:n(100001)",
            [2] = "200002:n(200002)"
          },
          SpeakNpcId = 100001,
          Subtitle = "When she was ill, you cared for her as best you could. But after so many years of sickness, she feared she'd only burden you further. So... she chose to leave home.",
          TalkActionId = {
            [1] = "100001:ExplainTwo_Start"
          }
        },
        [51150009] = {
          Camera = "-243.208984,-3.944336,191.368408,-0.0,-15.293783,-3.434053,35.000015,266.740662,false,Manual,7.0",
          ContentEN = "But by a stroke of good fortune, she crossed paths with a travelling apothecary — one of remarkable skill. Under her care, she slowly recovered.",
          DialogueId = 51150009,
          GUID = "800C765A",
          LookAt = {
            [1] = "100001:n(701074)",
            [2] = "200002:n(701074)"
          },
          SpeakNpcId = 100001,
          Subtitle = "But by a stroke of good fortune, she crossed paths with a travelling apothecary — one of remarkable skill. Under her care, she slowly recovered."
        },
        [51150010] = {
          Camera = "-243.208984,-3.944336,191.368408,-0.0,-15.293783,-3.434053,35.000015,266.740662,false,Manual,7.0",
          ContentEN = "And when she finally returned home to find you, she learned instead that the flood had taken your life.",
          DialogueId = 51150010,
          FacialId = {
            [1] = "100001:Sad03"
          },
          GUID = "800C7684",
          SpeakNpcId = 100001,
          Subtitle = "And when she finally returned home to find you, she learned instead that the flood had taken your life.",
          TalkActionId = {
            [1] = "100001:ExplainTwo_End"
          }
        },
        [51150011] = {
          Camera = "29.751953,-50.233398,225.475708,0.000091,-14.99999,175.16095,35.000011,100000.0,false,DoNotOverride,7.0",
          ContentEN = "All this time... I never knew...",
          DialogueId = 51150011,
          GUID = "800C76AE",
          SpeakNpcId = 701074,
          Subtitle = "All this time... I never knew..."
        },
        [51150012] = {
          Camera = "-125.262207,40.953125,171.12085,0.000126,-15.293818,-18.234081,35.000015,117.407356,false,Manual,3.0",
          ContentEN = "She grieved for you with all her heart... but she did not lose herself to sorrow forever. She begged that apothecary to take her in as a disciple, and began learning the art of medicine.",
          DialogueId = 51150012,
          FacialId = {
            [1] = "100001:Satisfy01"
          },
          GUID = "800C76D8",
          SpeakNpcId = 100001,
          Subtitle = "She grieved for you with all her heart... but she did not lose herself to sorrow forever. She begged that apothecary to take her in as a disciple, and began learning the art of medicine.",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51150013] = {
          Camera = "-125.262207,40.953125,171.12085,0.000126,-15.293818,-18.234081,35.000015,117.407356,false,Manual,3.0",
          ContentEN = "She wished to help those in pain, so that what happened between you and her would never happen to anyone else.",
          DialogueId = 51150013,
          GUID = "800C7702",
          SpeakNpcId = 100001,
          Subtitle = "She wished to help those in pain, so that what happened between you and her would never happen to anyone else."
        },
        [51150014] = {
          Camera = "-243.208984,-3.944336,191.368408,-0.0,-15.293783,-3.434053,35.000015,266.740662,false,Manual,7.0",
          ContentEN = "She studied with great devotion. And in time, she became an apothecary in her own right — and later took on students of her own. And those students, in time, taught students of their own as well.",
          DialogueId = 51150014,
          GUID = "800C772C",
          SpeakNpcId = 100001,
          Subtitle = "She studied with great devotion. And in time, she became an apothecary in her own right — and later took on students of her own. And those students, in time, taught students of their own as well.",
          TalkActionId = {
            [1] = "100001:Talk02_End"
          }
        },
        [51150015] = {
          Camera = "-243.208984,-3.944336,191.368408,-0.0,-15.293783,-3.434053,35.000015,266.740662,false,Manual,7.0",
          ContentEN = "Together, they healed countless lives. Her students cherished her as though she were family... right up until she passed peacefully in her nineties.",
          DialogueId = 51150015,
          GUID = "800C7756",
          SpeakNpcId = 100001,
          Subtitle = "Together, they healed countless lives. Her students cherished her as though she were family... right up until she passed peacefully in her nineties."
        },
        [51150016] = {
          Camera = "29.751953,-50.233398,225.475708,0.000091,-14.99999,175.16095,35.000011,100000.0,false,DoNotOverride,7.0",
          ContentEN = "Good... That's... that's so good...",
          DialogueId = 51150016,
          GUID = "800C7780",
          SpeakNpcId = 701074,
          Subtitle = "Good... That's... that's so good..."
        },
        [51150017] = {
          Camera = "29.751953,-50.233398,225.475708,0.000091,-14.99999,175.16095,35.000011,100000.0,false,DoNotOverride,7.0",
          ContentEN = "Her illness healed... she lived well... a full, long life... I can rest easy at last...",
          DialogueId = 51150017,
          GUID = "800C77AA",
          SpeakNpcId = 701074,
          Subtitle = "Her illness healed... she lived well... a full, long life... I can rest easy at last...",
          TalkActionId = {
            [1] = "701074:Wuyou_Agree"
          }
        },
        [51150018] = {
          Camera = "333.445312,-77.007812,119.176392,0.000049,3.105147,176.364456,35.0,100000.0,false,DoNotOverride,7.0",
          ContentEN = "Everything I held onto... I can finally let it rest... and now, I can leave without regret...",
          DialogueId = 51150018,
          GUID = "800C77D4",
          SpeakNpcId = 701074,
          Subtitle = "Everything I held onto... I can finally let it rest... and now, I can leave without regret..."
        },
        [51150019] = {
          Camera = "333.445312,-77.007812,119.176392,0.000049,3.105147,176.364456,35.0,100000.0,false,DoNotOverride,7.0",
          ContentEN = "Thank you... both of you... truly... thank... you...",
          DialogueId = 51150019,
          GUID = "800C77FE",
          SpeakNpcId = 701074,
          Subtitle = "Thank you... both of you... truly... thank... you...",
          TalkActionId = {
            [1] = "701074:Wuyou_Disappear"
          }
        },
        [51150020] = {
          ContentEN = "(His voice fades to a whisper as his form grows translucent — until at last he melts into the quiet air. And in the moment he disappears, something glimmering slips from within him and falls gently to the ground.)",
          DialogueId = 51150020,
          GUID = "800C7828",
          SpeakNpcId = 0,
          Subtitle = "(His voice fades to a whisper as his form grows translucent — until at last he melts into the quiet air. And in the moment he disappears, something glimmering slips from within him and falls gently to the ground.)"
        },
        [51150021] = {
          ContentEN = "(Do Wishen cry...? Or was it only a glimmer of sunlight?)",
          DialogueId = 51150021,
          GUID = "800C7852",
          SpeakNpcId = 0,
          Subtitle = "(Do Wishen cry...? Or was it only a glimmer of sunlight?)"
        },
        [51151001] = {
          Camera = "-619.021484,275.37793,18.173828,0.000051,1.999995,-13.887951,33.047028,100000.0,false,DoNotOverride,2.8",
          ContentEN = "You mean that warehouse over in the corner of EverSpring? Mr Tianlan rented it as a storehouse some time ago. Why bring it up now?",
          DialogueId = 51151001,
          FacialId = {
            [1] = "100001:Think01",
            [2] = "700371:Cin_Nervous"
          },
          FinalCamera = "-542.628906,256.49707,21.111328,0.000051,2.499999,-13.887944,33.047028,100000.0,false,DoNotOverride,2.8",
          GUID = "800D191A",
          LookAt = {
            [1] = "100001:n(700370)"
          },
          NextDialogue = 51151002,
          SpeakNpcId = 700370,
          Subtitle = "You mean that warehouse over in the corner of EverSpring? Mr Tianlan rented it as a storehouse some time ago. Why bring it up now?",
          TalkActionId = {
            [1] = "100001:Talk03_Start",
            [2] = "700370:Talk03_Start"
          },
          ToFinalCameraBlendTime = 25
        },
        [51151002] = {
          ContentEN = "Mr Tianlan hasn't returned since he last set sail. The batch of incense he bought beforehand has been sitting in that warehouse for months.",
          DialogueId = 51151002,
          GUID = "800D1944",
          NextDialogue = 51151003,
          SpeakNpcId = 700371,
          Subtitle = "Mr Tianlan hasn't returned since he last set sail. The batch of incense he bought beforehand has been sitting in that warehouse for months.",
          TalkActionId = {
            [1] = "700371:Explain02_Start"
          }
        },
        [51151003] = {
          ContentEN = "I don't quite follow. If the goods are simply sitting there, then let them sit — the rent's paid through next year. What's the harm?",
          DialogueId = 51151003,
          GUID = "800D196E",
          NextDialogue = 51151004,
          SpeakNpcId = 700370,
          Subtitle = "I don't quite follow. If the goods are simply sitting there, then let them sit — the rent's paid through next year. What's the harm?",
          TalkActionId = {
            [1] = "700370:Talk03_End"
          }
        },
        [51151004] = {
          ContentEN = "That's not the issue, Miss Wangchun. Everyone in EverSpring's saying the place is haunted!",
          DialogueId = 51151004,
          GUID = "800D1998",
          NextDialogue = 51151005,
          SpeakNpcId = 700371,
          Subtitle = "That's not the issue, Miss Wangchun. Everyone in EverSpring's saying the place is haunted!"
        },
        [51151005] = {
          ContentEN = "Wh—What!?",
          DialogueId = 51151005,
          FacialId = {
            [1] = "700370:Cin_Angry01"
          },
          GUID = "800D19C2",
          NextDialogue = 51151006,
          SpeakNpcId = 700370,
          Subtitle = "Wh—What!?",
          TalkActionId = {
            [1] = "700370:Shock03_Start",
            [2] = "700371:Explain02_End"
          }
        },
        [51151006] = {
          ContentEN = "Some clerks went in to check the stock, but the moment they stepped inside, they felt dizzy. Before they knew it, they'd already wandered back out without ever seeing the goods.",
          DialogueId = 51151006,
          GUID = "800D19EC",
          NextDialogue = 51151007,
          SpeakNpcId = 700371,
          Subtitle = "Some clerks went in to check the stock, but the moment they stepped inside, they felt dizzy. Before they knew it, they'd already wandered back out without ever seeing the goods.",
          TalkActionId = {
            [1] = "700371:Explain02_Start"
          }
        },
        [51151007] = {
          ContentEN = "Others still didn't believe it, so they sent in a few bolder hands — only for every one of them to be gently guided back outside, as though by unseen forces.",
          DialogueId = 51151007,
          GUID = "800D1A16",
          NextDialogue = 51151008,
          SpeakNpcId = 700371,
          Subtitle = "Others still didn't believe it, so they sent in a few bolder hands — only for every one of them to be gently guided back outside, as though by unseen forces.",
          TalkActionId = {
            [1] = "700370:Shock03_End"
          }
        },
        [51151008] = {
          ContentEN = "I see. No one's been harmed, but it's trouble nonetheless. Very well — I'll arrange for someone to inspect it as soon as I can.",
          DialogueId = 51151008,
          FacialId = {
            [1] = "700370:Cin_Idle"
          },
          GUID = "800D1A40",
          LookAt = {
            [1] = "100001:n(100001)"
          },
          SpeakNpcId = 700370,
          Subtitle = "I see. No one's been harmed, but it's trouble nonetheless. Very well — I'll arrange for someone to inspect it as soon as I can.",
          TalkActionId = {
            [1] = "100001:Talk03ToThink_Start",
            [2] = "700370:Explain01_Start"
          }
        },
        [51151009] = {
          ContentEN = "Hey, Little Minion... doesn't this place feel kinda weird to you?",
          DialogueId = 51151009,
          GUID = "800D1A6A",
          NextDialogue = 51151010,
          SpeakNpcId = 200002,
          Subtitle = "Hey, Little Minion... doesn't this place feel kinda weird to you?"
        },
        [51151010] = {
          ContentEN = "Not really. You're probably just imagining things.",
          DialogueId = 51151010,
          GUID = "800D1A94",
          NextDialogue = 51151011,
          SpeakNpcId = 100001,
          Subtitle = "Not really. You're probably just imagining things."
        },
        [51151011] = {
          ContentEN = "You think so? But it's definitely colder here than the rest of EverSpring... and I keep hearing these strange little noises...",
          DialogueId = 51151011,
          GUID = "800D1ABE",
          NextDialogue = 51151012,
          SpeakNpcId = 200002,
          Subtitle = "You think so? But it's definitely colder here than the rest of EverSpring... and I keep hearing these strange little noises..."
        },
        [51151012] = {
          ContentEN = "If you're that curious, we can come back tonight. Too many people around to poke around properly right now.",
          DialogueId = 51151012,
          GUID = "800D1AE8",
          SpeakNpcId = 100001,
          Subtitle = "If you're that curious, we can come back tonight. Too many people around to poke around properly right now."
        },
        [51151013] = {
