          ContentEN = "Don't talk rubbish. Three parts tea, one part flowers. Half a silver coin for a full bowl. That's how it's always been.",
          DialogueId = 51153005,
          GUID = "800E61E2",
          NextDialogue = 51153006,
          SpeakNpcId = 701090,
          Subtitle = "Don't talk rubbish. Three parts tea, one part flowers. Half a silver coin for a full bowl. That's how it's always been.",
          TalkActionId = {
            [1] = "701090:Talk03_Start"
          }
