        [51153009] = {
          Camera = "-273.785156,39.746094,126.045898,0.000046,1.999934,16.852501,50.0,348.791229,false,Manual,2.8",
          ContentEN = "I'm a Starweaver. I've travelled far from home for many years. This time, crossing the desert parched to the bone, the smell and taste of the flower tea I grew up with came back to me all at once.",
          DialogueId = 51153009,
          GUID = "800E628A",
          LookAt = {
            [1] = "701091:n(100001)",
            [2] = "100001:n(701091)"
          },
          NextDialogue = 51153010,
          SpeakNpcId = 701091,
          Subtitle = "I'm a Starweaver. I've travelled far from home for many years. This time, crossing the desert parched to the bone, the smell and taste of the flower tea I grew up with came back to me all at once.",
          TalkActionId = {
            [1] = "701091:Talk02_Start"
          }
        },
        [51153010] = {
          Camera = "-273.785156,39.746094,126.045898,0.000046,1.999934,16.852501,50.0,348.791229,false,Manual,2.8",
          ContentEN = "So the moment I returned to Starwharf, I came straight here. And yet... this bowl is different. It's a disappointment.",
