          ContentEN = "Sable Bi'an have been active on the roads of late. See me safely to EverSpring, and you will be well compensated.",
          DialogueId = 51153019,
          GUID = "800E642E",
          SpeakNpcId = 701091,
          Subtitle = "Sable Bi'an have been active on the roads of late. See me safely to EverSpring, and you will be well compensated.",
          TalkActionId = {
            [1] = "701091:Talk01_Start"
          }
        },
        [51153020] = {
          ContentEN = "With Sable Bi'an everywhere, you're worried about the road, aren't you?",
          DialogueId = 51153020,
          GUID = "800E6458",
          ImprPlusId = 1204,
          NextDialogue = 51153021,
          Subtitle = "With Sable Bi'an everywhere, you're worried about the road, aren't you?"
        },
        [51153021] = {
          Camera = "-273.785156,39.746094,126.045898,0.000046,1.999934,16.852501,50.0,348.791229,false,Manual,2.8",
          ContentEN = "Precisely. Zhuyin has been causing trouble of late. I've been away for years — I don't even know whether the old road is still passable. See me safely to EverSpring, and you will be well compensated.",
          DialogueId = 51153021,
          GUID = "800E6482",
          SpeakNpcId = 701091,
          Subtitle = "Precisely. Zhuyin has been causing trouble of late. I've been away for years — I don't even know whether the old road is still passable. See me safely to EverSpring, and you will be well compensated.",
          TalkActionId = {
            [1] = "701091:Talk01_Start"
          }
        },
        [51153022] = {
          ContentEN = "This road between Reedshore and Starwharf... I used to walk it all the time as a kid, just to watch the ships at the quay. Never thought it'd turn this dangerous.",
          DialogueId = 51153022,
          GUID = "800E64AC",
          NextDialogue = 51153023,
          SpeakNpcId = 701091,
          Subtitle = "This road between Reedshore and Starwharf... I used to walk it all the time as a kid, just to watch the ships at the quay. Never thought it'd turn this dangerous.",
          TalkActionId = {
            [1] = "701091:Think_Start"
          }
        },
        [51153023] = {
          ContentEN = "How times have changed. And the world with them.",
          DialogueId = 51153023,
          GUID = "800E64D6",
          NextDialogue = 51153024,
          SpeakNpcId = 701091,
          Subtitle = "How times have changed. And the world with them."
        },
        [51153024] = {
          ContentEN = "Come. Let's press on — EverSpring is just ahead.",
          DialogueId = 51153024,
          GUID = "800E6500",
          SpeakNpcId = 701091,
          Subtitle = "Come. Let's press on — EverSpring is just ahead.",
          TalkActionId = {
