        },
        [51155219] = {
          ContentEN = "\"With a crowd\"? He's going to get everyone at once! That's evil! This guy's horrible!",
          DialogueId = 51155219,
          GUID = "800FCD1E",
          NextDialogue = 51155220,
          SpeakNpcId = 200002,
          Subtitle = "\"With a crowd\"? He's going to get everyone at once! That's evil! This guy's horrible!"
        },
        [51155220] = {
          ContentEN = "...Does the Nine Chapters of Dafeng really allow this sort of thing?",
          DialogueId = 51155220,
          GUID = "800FCD48",
          NextDialogue = 51155221,
          SpeakNpcId = 100001,
          Subtitle = "...Does the Nine Chapters of Dafeng really allow this sort of thing?"
        },
        [51155221] = {
          ContentEN = "Ha! The Nine Chapters? That thing's a thousand years old. Full of loopholes. Everyone scraping by in Haze Market knows how to work them.",
          DialogueId = 51155221,
          GUID = "800FCD72",
          NextDialogue = 51155222,
          SpeakNpcId = 701093,
          Subtitle = "Ha! The Nine Chapters? That thing's a thousand years old. Full of loopholes. Everyone scraping by in Haze Market knows how to work them."
        },
        [51155222] = {
          ContentEN = "...Can I ask you something? Why are you doing this?",
          DialogueId = 51155222,
          GUID = "800FCD9C",
          NextDialogue = 51155223,
          SpeakNpcId = 100001,
          Subtitle = "...Can I ask you something? Why are you doing this?"
        },
        [51155223] = {
          ContentEN = "Hm? You're not here to buy, you're here to chat? I run a stall, not a tea party.",
          DialogueId = 51155223,
          GUID = "800FCDC6",
          NextDialogue = 51155224,
          SpeakNpcId = 701093,
          Subtitle = "Hm? You're not here to buy, you're here to chat? I run a stall, not a tea party."
        },
        [51155224] = {
          ContentEN = "No, no. I'm buying. Easy. We're new around here. Just trying to get a sense of how things work before we spend a small fortune.",
          DialogueId = 51155224,
          GUID = "800FCDF0",
          NextDialogue = 51155225,
          SpeakNpcId = 100001,
          Subtitle = "No, no. I'm buying. Easy. We're new around here. Just trying to get a sense of how things work before we spend a small fortune."
        },
        [51155225] = {
          ContentEN = "...Alright. If you really want to know, it's a long story.",
          DialogueId = 51155225,
          GUID = "800FCE1A",
          NextDialogue = 51155226,
          SpeakNpcId = 701093,
          Subtitle = "...Alright. If you really want to know, it's a long story."
        },
        [51155226] = {
          ContentEN = "I didn't have many friends as a kid. Wasn't good at much, either. Then I got on the wrong side of the Nine Chapters over some personal mess. After that, people kept their distance.",
          DialogueId = 51155226,
          GUID = "800FCE44",
          NextDialogue = 51155227,
          SpeakNpcId = 701093,
          Subtitle = "I didn't have many friends as a kid. Wasn't good at much, either. Then I got on the wrong side of the Nine Chapters over some personal mess. After that, people kept their distance."
        },
        [51155227] = {
          ContentEN = "So I ended up in Haze Market. Outsiders love to call this place rotten. But truth is, the people here are sharp. They look after their own.",
          DialogueId = 51155227,
          GUID = "800FCE6E",
          NextDialogue = 51155228,
          SpeakNpcId = 701093,
          Subtitle = "So I ended up in Haze Market. Outsiders love to call this place rotten. But truth is, the people here are sharp. They look after their own."
        },
        [51155228] = {
          ContentEN = "Hang around long enough, you learn the trade. Now I just do my part for Mr Qiu's grand design.",
          DialogueId = 51155228,
          GUID = "800FCE98",
          NextDialogue = 51155229,
          SpeakNpcId = 701093,
          Subtitle = "Hang around long enough, you learn the trade. Now I just do my part for Mr Qiu's grand design."
        },
        [51155229] = {
          ContentEN = "Punished by the Nine Chapters... shunned by everyone... raised by the black market... I knew it! He's totally plotting revenge on the whole world!",
          DialogueId = 51155229,
          GUID = "800FCEC2",
          NextDialogue = 51155230,
          SpeakNpcId = 200002,
          Subtitle = "Punished by the Nine Chapters... shunned by everyone... raised by the black market... I knew it! He's totally plotting revenge on the whole world!"
        },
        [51155230] = {
