          GUID = "B1C10AF4",
          NextDialogue = 71005203,
          SpeakNpcId = 800006,
          Subtitle = "(As you draw closer, the girl hurriedly fishes a few copper coins from her pocket and holds them out to you.)"
        },
        [71005203] = {
          ContentEN = "Hi there, {性别:Sir|Miss}! Would you like a lucky coin? My mum gave them to me! She said — one coin takes away your worries, two keeps happiness close, and three... three can make any wish come true!",
          DialogueId = 71005203,
          GUID = "B1C10B1E",
          NextDialogue = 71005204,
          SpeakNpcId = 818046,
          Subtitle = "Hi there, {性别:Sir|Miss}! Would you like a lucky coin? My mum gave them to me! She said — one coin takes away your worries, two keeps happiness close, and three... three can make any wish come true!"
        },
        [71005204] = {
          ContentEN = "...",
          DialogueId = 71005204,
          GUID = "B1C10B48",
          NextDialogue = 71005205,
          SpeakNpcId = 100001,
          Subtitle = "..."
        },
        [71005205] = {
          ContentEN = "They're really magic! Mum cast a spell on them herself — I swear I'm not lying! If you don't believe me, you can ask around! Go on! I'll be right here waiting.",
