          GUID = "B1C10B49",
          SpeakNpcId = 818046,
          Subtitle = "They're really magic! Mum cast a spell on them herself — I swear I'm not lying! If you don't believe me, you can ask around! Go on! I'll be right here waiting."
        },
        [71005206] = {
          ContentEN = "(You spot a few \"lucky coins\" lying at the feet of an old man. You walk over to speak with him.)",
          DialogueId = 71005206,
          GUID = "B1C10B72",
          NextDialogue = 71005207,
          SpeakNpcId = 800006,
          Subtitle = "(You spot a few \"lucky coins\" lying at the feet of an old man. You walk over to speak with him.)"
        },
        [71005207] = {
          ContentEN = "Lucky coins? Heh... If they really worked, do you think I'd still be starving out here on this street corner?",
          DialogueId = 71005207,
          GUID = "B1C10B73",
          NextDialogue = 71005208,
          SpeakNpcId = 818047,
          Subtitle = "Lucky coins? Heh... If they really worked, do you think I'd still be starving out here on this street corner?"
        },
        [71005208] = {
          ContentEN = "But don't go repeating that to the little girl, alright? She's got no family left. Poor thing... Sometimes, even when something isn't real, it still gives people something to hold on to. You get what I mean?",
