          ContentEN = "It looks like it's longing for a different colour.",
          DialogueId = 80004251,
          Duration = 3,
          GUID = "C8483B0A",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "It looks like it's longing for a different colour.",
          VoiceName = "voice/$Locale$/story/1201/120114/C8483B0A"
        },
        [80004252] = {
          ContentEN = "Oh no, the colour I just painted is gone...",
          DialogueId = 80004252,
          Duration = 3,
          GUID = "C8483B0B",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 80004253,
          SpeakNpcId = 700142,
          Subtitle = "Oh no, the colour I just painted is gone...",
          VoiceName = "voice/$Locale$/story/1201/120114/C8483B0B"
        },
        [80004253] = {
          ContentEN = "I'll have to paint faster before the next vanish!",
          DialogueId = 80004253,
          Duration = 3,
