          SpeakNpcId = 93102,
          Subtitle = "Considering that kind of pressure, randomly cutting several flowers seems quite mild, doesn't it?",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529C5A"
        },
        [80020410] = {
