          DialogueId = 80020410,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8529C84",
          NextDialogue = 80020412,
          SpeakNpcId = 93102,
          Subtitle = "Well, it's not really a bother.",
          TalkActionId = {
