          },
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529C84"
        },
        [80020411] = {
          ContentEN = "It seems you're missing the point of this conversation, aren't you?",
          DialogueId = 80020411,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8529CAE",
          NextDialogue = 80020412,
          SpeakNpcId = 93102,
          Subtitle = "It seems you're missing the point of this conversation, aren't you?",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529CAE"
        },
        [80020412] = {
          ContentEN = "I was just thinking of... um, someone important.",
          DialogueId = 80020412,
          GUID = "C8529CD8",
          NextDialogue = 80020413,
          SpeakNpcId = 93102,
          Subtitle = "I was just thinking of... um, someone important.",
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529CD8"
        },
        [80020413] = {
          ContentEN = "She was a fellow agent, but she always thought I wasn't cut out for the job. So I made so much effort trying to prove to her that I was not only competent but exceptional.",
          DialogueId = 80020413,
          GUID = "C8529D02",
          NextDialogue = 80020414,
          SpeakNpcId = 93102,
          Subtitle = "She was a fellow agent, but she always thought I wasn't cut out for the job. So I made so much effort trying to prove to her that I was not only competent but exceptional.",
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529D02"
        },
        [80020414] = {
          ContentEN = "In the end, it turned out she was right.",
          DialogueId = 80020414,
          FacialId = {
            [1] = "93102:Smile02"
          },
          GUID = "C8529D2C",
          NextDialogue = 80020415,
          SpeakNpcId = 93102,
          Subtitle = "In the end, it turned out she was right.",
          TalkActionId = {
            [1] = "93102:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529D2C"
        },
        [80020415] = {
          ContentEN = "I couldn't put missions above all else like she could.",
          DialogueId = 80020415,
          GUID = "C8529D56",
          NextDialogue = 80020416,
          SpeakNpcId = 93102,
          Subtitle = "I couldn't put missions above all else like she could.",
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529D56"
        },
        [80020416] = {
          ContentEN = "Yet, there's a part of me that's relieved that I didn't end up walking her path.",
          DialogueId = 80020416,
          FacialId = {
            [1] = "93102:Happy01"
          },
          GUID = "C8529D80",
          NextDialogue = 80020417,
          SpeakNpcId = 93102,
          Subtitle = "Yet, there's a part of me that's relieved that I didn't end up walking her path.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529D80"
        },
        [80020417] = {
          ContentEN = "We lost touch when I left the Legion. Now that I'm settling in here, I find myself... wondering how she's doing.",
          DialogueId = 80020417,
          GUID = "C8529DAA",
          NextOptions = {
            [1] = 800204171
          },
          SpeakNpcId = 93102,
          Subtitle = "We lost touch when I left the Legion. Now that I'm settling in here, I find myself... wondering how she's doing.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529DAA"
        },
        [80020418] = {
          ContentEN = "Huh? Well...",
          DialogueId = 80020418,
          FacialId = {
            [1] = "93102:Shock02"
          },
          GUID = "C8529DD4",
          NextDialogue = 80020419,
          SpeakNpcId = 93102,
          Subtitle = "Huh? Well...",
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529DD4"
        },
        [80020419] = {
          ContentEN = "You're right. Instead of trimming flowers here, perhaps I should just go see her in person.",
          DialogueId = 80020419,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8529DFE",
          SpeakNpcId = 93102,
          Subtitle = "You're right. Instead of trimming flowers here, perhaps I should just go see her in person.",
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529DFE"
        },
        [80020501] = {
          Camera = "106.860352,-6.606262,134.715088,0.0,-0.99996,-137.196014,30.0,125.0,false,Manual,2.8",
          ContentEN = "You approached me as soon as I returned, inviting me for a drink. Please be honest with me — have you picked up some of my old agent tricks and been keeping tabs on me?",
          DialogueId = 80020501,
          FacialId = {
            [1] = "93102:Confident02"
          },
          GUID = "C852AB72",
          LookAt = {
            [1] = "93102:p(18000P1)"
          },
          NextOptions = {
            [1] = 800205011,
            [2] = 800205012
          },
          SpeakNpcId = 93102,
          Subtitle = "You approached me as soon as I returned, inviting me for a drink. Please be honest with me — have you picked up some of my old agent tricks and been keeping tabs on me?",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AB72"
        },
        [80020503] = {
          ContentEN = "I was only teasing you. You came over because you're curious if I've met that lady who's important to me, aren't you?",
          DialogueId = 80020503,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C852ABC6",
          NextDialogue = 80020504,
          SpeakNpcId = 93102,
          Subtitle = "I was only teasing you. You came over because you're curious if I've met that lady who's important to me, aren't you?",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852ABC6"
        },
        [80020504] = {
          ContentEN = "Truth be told, no. She was reassigned away from the capital for certain reasons, so I've only caught snippets about her from others.",
          DialogueId = 80020504,
          GUID = "C852ABF0",
          NextDialogue = 80020505,
          SpeakNpcId = 93102,
          Subtitle = "Truth be told, no. She was reassigned away from the capital for certain reasons, so I've only caught snippets about her from others.",
          VoiceName = "voice/$Locale$/inv/Xier/005/C852ABF0"
        },
        [80020505] = {
          ContentEN = "She's in a small town in the south — nothing like the icy grip here, but a place where she can enjoy bright sunlight and some music often.",
          DialogueId = 80020505,
          FacialId = {
            [1] = "93102:Smile02"
          },
          GUID = "C852AC1A",
          NextDialogue = 80020506,
          SpeakNpcId = 93102,
          Subtitle = "She's in a small town in the south — nothing like the icy grip here, but a place where she can enjoy bright sunlight and some music often.",
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AC1A"
        },
        [80020506] = {
          ContentEN = "To be honest, I was relieved. Because I wasn't sure how I would face her... But knowing she's doing well gives me some peace of mind.",
          DialogueId = 80020506,
          GUID = "C852AC44",
          NextDialogue = 80020507,
          SpeakNpcId = 93102,
          Subtitle = "To be honest, I was relieved. Because I wasn't sure how I would face her... But knowing she's doing well gives me some peace of mind.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AC44"
        },
        [80020507] = {
          ContentEN = "This means the last ties between me, the Legion, and my past life as an agent have finally been severed.",
          DialogueId = 80020507,
          GUID = "C852AC6E",
          NextOptions = {
            [1] = 800205071,
            [2] = 800205072
          },
          SpeakNpcId = 93102,
          Subtitle = "This means the last ties between me, the Legion, and my past life as an agent have finally been severed.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AC6E"
        },
        [80020508] = {
          ContentEN = "Yes, finally.",
          DialogueId = 80020508,
          GUID = "C852AC98",
          NextDialogue = 80020510,
          SpeakNpcId = 93102,
          Subtitle = "Yes, finally.",
          TalkActionId = {
            [1] = "93102:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AC98"
        },
        [80020509] = {
          ContentEN = "The old me would, but no, not anymore.",
          DialogueId = 80020509,
          GUID = "C852ACC2",
          NextDialogue = 80020510,
          SpeakNpcId = 93102,
          Subtitle = "The old me would, but no, not anymore.",
          VoiceName = "voice/$Locale$/inv/Xier/005/C852ACC2"
        },
        [80020510] = {
          ContentEN = "She's actually a close family member of mine. She was the reason that I joined the Legion, and the reason I decided to leave.",
          DialogueId = 80020510,
          FacialId = {
            [1] = "93102:Iyada01"
          },
          GUID = "C852ACEC",
          NextDialogue = 80020511,
          SpeakNpcId = 93102,
          Subtitle = "She's actually a close family member of mine. She was the reason that I joined the Legion, and the reason I decided to leave.",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852ACEC"
        },
        [80020511] = {
          ContentEN = "She never wanted me to stay in such a dangerous profession, but I was desperate to show her that I could handle it — maybe even share some of her burdens.",
          DialogueId = 80020511,
          GUID = "C852AD16",
          NextDialogue = 80020512,
          SpeakNpcId = 93102,
          Subtitle = "She never wanted me to stay in such a dangerous profession, but I was desperate to show her that I could handle it — maybe even share some of her burdens.",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AD16"
        },
        [80020512] = {
          ContentEN = "It was the irony of fate that she and I received conflicting missions — hers to eliminate Miss Flora, mine to protect her.",
          DialogueId = 80020512,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C852AD40",
          NextDialogue = 800205121,
          SpeakNpcId = 93102,
          Subtitle = "It was the irony of fate that she and I received conflicting missions — hers to eliminate Miss Flora, mine to protect her.",
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AD40"
        },
        [80020513] = {
          ContentEN = "So I took Miss Flora and fled before her assassination attempt could commence. At that time, I didn't have the leisure to dwell on my days in the Legion or anything related to her.",
          DialogueId = 80020513,
          FacialId = {
            [1] = "93102:Smile02"
          },
          GUID = "C852AD6A",
          NextDialogue = 80020514,
          SpeakNpcId = 93102,
          Subtitle = "So I took Miss Flora and fled before her assassination attempt could commence. At that time, I didn't have the leisure to dwell on my days in the Legion or anything related to her.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AD6A"
        },
        [80020514] = {
          ContentEN = "It's only because things have settled down recently, and you've been there for me to unload these old stories, that this whole thing had become a thorn in my heart, which led to my recent discomposure.",
          DialogueId = 80020514,
          GUID = "C852AD6B",
          NextOptions = {
            [1] = 800205141,
            [2] = 800205142
          },
          SpeakNpcId = 93102,
          Subtitle = "It's only because things have settled down recently, and you've been there for me to unload these old stories, that this whole thing had become a thorn in my heart, which led to my recent discomposure.",
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AD6B"
        },
        [80020515] = {
          ContentEN = "What I knew for sure was that eventually, I had to confront a complete farewell with her, which was something I had been trying to run away from.",
          DialogueId = 80020515,
          GUID = "C852ADBE",
          NextDialogue = 80020516,
          SpeakNpcId = 93102,
          Subtitle = "What I knew for sure was that eventually, I had to confront a complete farewell with her, which was something I had been trying to run away from.",
          VoiceName = "voice/$Locale$/inv/Xier/005/C852ADBE"
        },
        [80020516] = {
          ContentEN = "Now that it's finally happened, it doesn't feel so bad. I'm even relieved that it'll no longer haunt me.",
          DialogueId = 80020516,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C852ADE8",
          NextDialogue = 80020517,
          SpeakNpcId = 93102,
          Subtitle = "Now that it's finally happened, it doesn't feel so bad. I'm even relieved that it'll no longer haunt me.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852ADE8"
        },
        [80020517] = {
          ContentEN = "I've got so much I want to do now — trim flowers, bake a cake, shop for new outfits, maybe even dance a little.",
          DialogueId = 80020517,
          FacialId = {
            [1] = "93102:Smile02"
          },
          GUID = "C852AE12",
          NextDialogue = 80020518,
          SpeakNpcId = 93102,
          Subtitle = "I've got so much I want to do now — trim flowers, bake a cake, shop for new outfits, maybe even dance a little.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AE12"
        },
        [80020518] = {
          ContentEN = "But what I want to do most at the moment is thank you for helping me truly move on.",
          DialogueId = 80020518,
          GUID = "C852AE3C",
          NextOptions = {
            [1] = 800205181,
            [2] = 800205182
          },
          SpeakNpcId = 93102,
          Subtitle = "But what I want to do most at the moment is thank you for helping me truly move on.",
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AE3C"
        },
        [80020519] = {
          ContentEN = "But I must also remind you: now that you know my past, it means that one day when the Legion comes after me and Miss Flora, you won't be able to stay out of it.",
          DialogueId = 80020519,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C852AE66",
          NextDialogue = 80020520,
          SpeakNpcId = 93102,
          Subtitle = "But I must also remind you: now that you know my past, it means that one day when the Legion comes after me and Miss Flora, you won't be able to stay out of it.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AE66"
        },
        [80020520] = {
          ContentEN = "I hope you're not too scared. Do you feel like I've handed you a sugar-coated poison?",
          DialogueId = 80020520,
          FacialId = {
            [1] = "93102:Confident01"
          },
          GUID = "C852AE90",
          NextDialogue = 80020521,
          SpeakNpcId = 93102,
          Subtitle = "I hope you're not too scared. Do you feel like I've handed you a sugar-coated poison?",
          TalkActionId = {
            [1] = "93102:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AE90"
        },
        [80020521] = {
          ContentEN = "Please rest assured that, I, Hilda, the all-capable maid, will always ensure your safety.",
          DialogueId = 80020521,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C852AEBA",
          SpeakNpcId = 93102,
          Subtitle = "Please rest assured that, I, Hilda, the all-capable maid, will always ensure your safety.",
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AEBA"
        },
        [80020522] = {
          ContentEN = "Thank you — is it so strange to hear that from me? I mean it sincerely.",
          DialogueId = 80020522,
          FacialId = {
            [1] = "93102:Happy02"
          },
          GUID = "C852AE65",
          NextDialogue = 80020519,
          SpeakNpcId = 93102,
          Subtitle = "Thank you — is it so strange to hear that from me? I mean it sincerely.",
          TalkActionId = {
            [1] = "93102:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AE65"
        },
        [80030100] = {
          ContentEN = "This holiday is precious, and spending it with you is just as enjoyable as sleeping.",
          DialogueId = 80030100,
          GUID = "C878DD68",
          Subtitle = "This holiday is precious, and spending it with you is just as enjoyable as sleeping.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C878DD68"
        },
        [80030101] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          ContentEN = "Nothing beats having a refreshing drink after a good rest. It's so wonderful to have a break from work!",
          DialogueId = 80030101,
          GUID = "C858D272",
          LookAt = {
            [1] = "94202:p(18000P1)"
          },
          NextDialogue = 80030102,
          SpeakNpcId = 94202,
          Subtitle = "Nothing beats having a refreshing drink after a good rest. It's so wonderful to have a break from work!",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D272"
        },
        [80030102] = {
          ContentEN = "Speaking of which, I got a package before I came here. Let me take a look.",
          DialogueId = 80030102,
          GUID = "C858D29C",
          NextDialogue = 80030103,
          SpeakNpcId = 94202,
          Subtitle = "Speaking of which, I got a package before I came here. Let me take a look.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D29C"
        },
        [80030103] = {
          ContentEN = "This must be the pyjamas and incense my subordinate bought me as a sleep aid. Perfect, I'll go back home and take another rest.",
          DialogueId = 80030103,
          GUID = "C858D2C6",
          NextDialogue = 80030104,
          SpeakNpcId = 94202,
          Subtitle = "This must be the pyjamas and incense my subordinate bought me as a sleep aid. Perfect, I'll go back home and take another rest.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D2C6"
        },
        [80030104] = {
          ContentEN = "Huh? \"Proposal on the Optimisation of Ornamental Plants of the 13th Legion\"? \"Application for Purchasing Recreational Facilities to Enhance Soldiers' Morale\"?",
          DialogueId = 80030104,
          GUID = "C858D2F0",
          NextDialogue = 80030105,
          SpeakNpcId = 94202,
          Subtitle = "Huh? \"Proposal on the Optimisation of Ornamental Plants of the 13th Legion\"? \"Application for Purchasing Recreational Facilities to Enhance Soldiers' Morale\"?",
          TalkActionId = {
            [1] = "94202:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D2F0"
        },
        [80030105] = {
          ContentEN = "Urgh, it's always about work. Let's talk about this later. I won't let my holiday be spoiled by anything or anyone, except the Chief. But I doubt she'll show up here.",
          DialogueId = 80030105,
          GUID = "C858D31A",
          NextOptions = {
            [1] = 800301051,
            [2] = 800301052
          },
          SpeakNpcId = 94202,
          Subtitle = "Urgh, it's always about work. Let's talk about this later. I won't let my holiday be spoiled by anything or anyone, except the Chief. But I doubt she'll show up here.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D31A"
        },
        [80030106] = {
          ContentEN = "It's not easy to come up with such practical principles as these.",
          DialogueId = 80030106,
          GUID = "C858D344",
          NextDialogue = 80030108,
          SpeakNpcId = 94202,
          Subtitle = "It's not easy to come up with such practical principles as these.",
          TalkActionId = {
            [1] = "94202:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D344"
        },
        [80030107] = {
          ContentEN = "Whoa, how could you call this \"slacking off\"?",
          DialogueId = 80030107,
          FacialId = {
            [1] = "94202:Blink"
          },
          GUID = "C858D36E",
          NextDialogue = 80030108,
          SpeakNpcId = 94202,
          Subtitle = "Whoa, how could you call this \"slacking off\"?",
          TalkActionId = {
            [1] = "94202:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D36E"
        },
        [80030108] = {
          ContentEN = "This is the \"Howard High-Efficiency Energy-Saving Mode\", created by yours truly, Randy Howard.",
          DialogueId = 80030108,
          GUID = "C858D398",
          NextDialogue = 80030109,
          SpeakNpcId = 94202,
          Subtitle = "This is the \"Howard High-Efficiency Energy-Saving Mode\", created by yours truly, Randy Howard.",
          TalkActionId = {
            [1] = "94202:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D398"
        },
        [80030109] = {
          ContentEN = "When you take a break, clear your mind of all work so that you can start working again in a good mood. That way, you won't dread getting back to work.",
          DialogueId = 80030109,
          GUID = "C858D3C2",
          NextDialogue = 80030110,
          SpeakNpcId = 94202,
          Subtitle = "When you take a break, clear your mind of all work so that you can start working again in a good mood. That way, you won't dread getting back to work.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D3C2"
        },
        [80030110] = {
          ContentEN = "After years of practising and optimising this method, I've got it working perfectly.",
          DialogueId = 80030110,
          GUID = "C858D3EC",
          NextDialogue = 80030111,
          SpeakNpcId = 94202,
          Subtitle = "After years of practising and optimising this method, I've got it working perfectly.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D3EC"
        },
        [80030111] = {
          ContentEN = "This has helped me to figure out the most energy-saving solution to different problems in seconds.",
          DialogueId = 80030111,
          GUID = "C858D416",
          NextDialogue = 80030112,
          SpeakNpcId = 94202,
          Subtitle = "This has helped me to figure out the most energy-saving solution to different problems in seconds.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D416"
        },
        [80030112] = {
          ContentEN = "Such as this conversation with an ulterior motive.",
          DialogueId = 80030112,
          GUID = "C858D417",
          NextDialogue = 80030113,
          SpeakNpcId = 94202,
          Subtitle = "Such as this conversation with an ulterior motive.",
          TalkActionId = {
            [1] = "94202:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D417"
        },
        [80030113] = {
          ContentEN = "Huh? I'm not following.",
          DialogueId = 80030113,
          GUID = "80030113.0",
          NextDialogue = 80030114,
          SpeakNpcId = 790008,
          Subtitle = "Huh? I'm not following."
        },
        [80030114] = {
          ContentEN = "A bit too late to play dumb, don't you think?",
          DialogueId = 80030114,
          GUID = "C858D418",
          NextDialogue = 80030115,
          SpeakNpcId = 94202,
          Subtitle = "A bit too late to play dumb, don't you think?",
          TalkActionId = {
            [1] = "94202:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D418"
        },
        [80030115] = {
          ContentEN = "...Tell me, how's Berenica doing now?!",
          DialogueId = 80030115,
          GUID = "80030115.0",
          NextDialogue = 80030116,
          SpeakNpcId = 790008,
          Subtitle = "...Tell me, how's Berenica doing now?!"
        },
        [80030116] = {
          ContentEN = "Hah, so that's No. 0's name — Berenica.",
          DialogueId = 80030116,
          GUID = "C858D419",
          NextDialogue = 80030117,
          SpeakNpcId = 94202,
          Subtitle = "Hah, so that's No. 0's name — Berenica.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D419"
        },
        [80030117] = {
          ContentEN = "A bit late to play dumb too, I'd say.",
          DialogueId = 80030117,
          GUID = "80030117.0",
          NextDialogue = 80030118,
          SpeakNpcId = 790008,
          Subtitle = "A bit late to play dumb too, I'd say."
        },
        [80030118] = {
          ContentEN = "Well, playing dumb is how smart people start a conversation.",
          DialogueId = 80030118,
          GUID = "C858D41A",
          NextDialogue = 80030119,
          SpeakNpcId = 94202,
          Subtitle = "Well, playing dumb is how smart people start a conversation.",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D41A"
        },
        [80030119] = {
          ContentEN = "But honestly, your question's moot. For starters, even if I did tell you something, there's no way you could verify it.",
          DialogueId = 80030119,
          GUID = "C858D41B",
          NextDialogue = 80030120,
          SpeakNpcId = 94202,
          Subtitle = "But honestly, your question's moot. For starters, even if I did tell you something, there's no way you could verify it.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D41B"
        },
        [80030120] = {
          ContentEN = "Secondly, in the principle of the \"Howard High-Efficiency Energy-Saving Mode\", I keep work and life separate.",
          DialogueId = 80030120,
          GUID = "C858D41C",
          NextDialogue = 80030121,
          SpeakNpcId = 94202,
          Subtitle = "Secondly, in the principle of the \"Howard High-Efficiency Energy-Saving Mode\", I keep work and life separate.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D41C"
        },
        [80030121] = {
          ContentEN = "Life might blend into work, but work must never intrude on my life. Right now, I'm technically on vacation, and that's the most \"energy-efficient\" way I operate.",
          DialogueId = 80030121,
          GUID = "C858D41D",
          NextDialogue = 80030122,
          SpeakNpcId = 94202,
          Subtitle = "Life might blend into work, but work must never intrude on my life. Right now, I'm technically on vacation, and that's the most \"energy-efficient\" way I operate.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D41D"
        },
        [80030122] = {
          ContentEN = "So, this conversation and any future talks about No. 0 aren't gonna get anywhere; but if you want to chat about life and other fun stuff, I'm all ears.",
          DialogueId = 80030122,
          GUID = "C858D41E",
          NextDialogue = 80030123,
          SpeakNpcId = 94202,
          Subtitle = "So, this conversation and any future talks about No. 0 aren't gonna get anywhere; but if you want to chat about life and other fun stuff, I'm all ears.",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D41E"
        },
        [80030123] = {
          ContentEN = "Then it seems we're done here. You can leave.",
          DialogueId = 80030123,
          GUID = "C858D41F",
          NextDialogue = 80030124,
          SpeakNpcId = 790008,
          Subtitle = "Then it seems we're done here. You can leave.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D41F"
        },
        [80030124] = {
          ContentEN = "While I can't disclose her whereabouts, I can assure you, she's safe.",
          DialogueId = 80030124,
          GUID = "C858D421",
          NextDialogue = 80030125,
          SpeakNpcId = 94202,
          Subtitle = "While I can't disclose her whereabouts, I can assure you, she's safe.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D421"
        },
        [80030125] = {
          ContentEN = "There's no way I could verify that.",
          DialogueId = 80030125,
          GUID = "C858D422",
          NextDialogue = 80030126,
          SpeakNpcId = 790008,
          Subtitle = "There's no way I could verify that.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D422"
        },
        [80030126] = {
          ContentEN = "Hahaha, smart people are all quick learners.",
          DialogueId = 80030126,
          GUID = "C858D423",
          NextDialogue = 80030127,
          SpeakNpcId = 94202,
          Subtitle = "Hahaha, smart people are all quick learners.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D423"
        },
        [80030127] = {
          ContentEN = "*sigh* It's sad to see good intentions go unappreciated — so much so that I might not be able to rest properly tomorrow...",
          DialogueId = 80030127,
          GUID = "C858D4BE",
          NextDialogue = 80030128,
          SpeakNpcId = 94202,
          Subtitle = "*sigh* It's sad to see good intentions go unappreciated — so much so that I might not be able to rest properly tomorrow...",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D4BE"
        },
        [80030128] = {
          ContentEN = "Oh, wait! Maybe I should try to extend my holiday by taking sick leave. Like, I need a prolonged holiday 'cause my illness had prevented me from getting proper rest. That makes perfect sense, doesn't it?!",
          DialogueId = 80030128,
          GUID = "C858D4E8",
          NextDialogue = 80030129,
          SpeakNpcId = 94202,
          Subtitle = "Oh, wait! Maybe I should try to extend my holiday by taking sick leave. Like, I need a prolonged holiday 'cause my illness had prevented me from getting proper rest. That makes perfect sense, doesn't it?!",
          TalkActionId = {
            [1] = "94202:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D4E8"
        },
        [80030129] = {
          ContentEN = "And the reason I'll use will be... I feel achy all over, especially in my heart.",
          DialogueId = 80030129,
          GUID = "C858D512",
          NextDialogue = 80030130,
          SpeakNpcId = 94202,
          Subtitle = "And the reason I'll use will be... I feel achy all over, especially in my heart.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D512"
        },
        [80030130] = {
          ContentEN = "Because of a conflict during a public opinion survey... but it has been resolved through private negotiations. Maybe I'll even get compensation out of it. Today has been very fruitful.",
          DialogueId = 80030130,
          GUID = "C858D53C",
          NextDialogue = 80030131,
          SpeakNpcId = 94202,
          Subtitle = "Because of a conflict during a public opinion survey... but it has been resolved through private negotiations. Maybe I'll even get compensation out of it. Today has been very fruitful.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D53C"
        },
        [80030131] = {
          ContentEN = "You just extended my holiday in mere seconds. My friend, you're the best!",
          DialogueId = 80030131,
          GUID = "C858D566",
          NextDialogue = 80030132,
          SpeakNpcId = 94202,
          Subtitle = "You just extended my holiday in mere seconds. My friend, you're the best!",
          TalkActionId = {
            [1] = "94202:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D566"
        },
        [80030132] = {
          ContentEN = "I'm looking forward to my next excuse for... Ahem... I mean, our next meeting.",
          DialogueId = 80030132,
          GUID = "C858D590",
          SpeakNpcId = 94202,
          Subtitle = "I'm looking forward to my next excuse for... Ahem... I mean, our next meeting.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D590"
        },
        [80030201] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          ContentEN = "Looks like you're finally up for some casual chats, huh?",
          DialogueId = 80030201,
          GUID = "C858E2DA",
          LookAt = {
            [1] = "94202:p(18000P1)"
          },
          NextDialogue = 80030202,
          SpeakNpcId = 94202,
          Subtitle = "Looks like you're finally up for some casual chats, huh?",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E2DA"
        },
        [80030202] = {
          ContentEN = "I'm still on a mission, so I couldn't meet up with you during working hours. I requested leave especially to grab a drink with you.",
          DialogueId = 80030202,
          GUID = "C858E304",
          NextDialogue = 80030203,
          SpeakNpcId = 94202,
          Subtitle = "I'm still on a mission, so I couldn't meet up with you during working hours. I requested leave especially to grab a drink with you.",
          TalkActionId = {
            [1] = "94202:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E304"
        },
        [80030203] = {
          ContentEN = "And my reason for this leave... I told them I was invited to a dance by a young lady of nobility.",
          DialogueId = 80030203,
          GUID = "C858E32E",
          NextDialogue = 80030204,
          SpeakNpcId = 94202,
          Subtitle = "And my reason for this leave... I told them I was invited to a dance by a young lady of nobility.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E32E"
        },
        [80030204] = {
          ContentEN = "Oh don't be surprised. It's quite common for young officers and noble ladies to have romantic affairs. The Legion turns a blind eye to them. After all, having relations with \"the nobility\" can bolster the Legion's influence.",
          DialogueId = 80030204,
          GUID = "C858E358",
          NextDialogue = 80030205,
          SpeakNpcId = 94202,
          Subtitle = "Oh don't be surprised. It's quite common for young officers and noble ladies to have romantic affairs. The Legion turns a blind eye to them. After all, having relations with \"the nobility\" can bolster the Legion's influence.",
          VoiceName = "voice/$Locale$/inv/Landi/0/C858E358"
        },
        [80030205] = {
          ContentEN = "As a gentleman, I had to take longer leave for this reason. I think it makes perfect sense.",
          DialogueId = 80030205,
          GUID = "C858E382",
          NextOptions = {
            [1] = 800302051,
            [2] = 800302052
          },
          SpeakNpcId = 94202,
          Subtitle = "As a gentleman, I had to take longer leave for this reason. I think it makes perfect sense.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E382"
        },
        [80030206] = {
          ContentEN = "Your words are like a dagger in my heart. I might have to extend my leave to recover from that burn.",
          DialogueId = 80030206,
          GUID = "C858E3AC",
          NextDialogue = 80030208,
          SpeakNpcId = 94202,
          Subtitle = "Your words are like a dagger in my heart. I might have to extend my leave to recover from that burn.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E3AC"
        },
        [80030207] = {
          ContentEN = "Thank you, I'll take that as a compliment.",
          DialogueId = 80030207,
          GUID = "C858E3D6",
          NextDialogue = 80030208,
          SpeakNpcId = 94202,
          Subtitle = "Thank you, I'll take that as a compliment.",
          TalkActionId = {
            [1] = "94202:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E3D6"
        },
        [80030208] = {
          ContentEN = "I'm aware by the way, that \"gentleman\" is often used sarcastically, not as praise.",
          DialogueId = 80030208,
          GUID = "C858E400",
          NextDialogue = 80030209,
          SpeakNpcId = 94202,
          Subtitle = "I'm aware by the way, that \"gentleman\" is often used sarcastically, not as praise.",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E400"
        },
        [80030209] = {
          ContentEN = "When I was little, my sisters told me that being a gentleman is the ultimate goal for a man.",
          DialogueId = 80030209,
          GUID = "C858E42A",
          NextOptions = {
            [1] = 800302091,
            [2] = 800302092
          },
          SpeakNpcId = 94202,
          Subtitle = "When I was little, my sisters told me that being a gentleman is the ultimate goal for a man.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E42A"
        },
        [80030210] = {
          ContentEN = "Maybe you're making that assumption based on your high opinion of me, but unfortunately, they're not lovely ladies, not at all.",
          DialogueId = 80030210,
          GUID = "C858E454",
          NextDialogue = 80030212,
          SpeakNpcId = 94202,
          Subtitle = "Maybe you're making that assumption based on your high opinion of me, but unfortunately, they're not lovely ladies, not at all.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E454"
        },
        [80030211] = {
          ContentEN = "I was just like any ordinary kid. Dumb and naive.",
          DialogueId = 80030211,
          GUID = "C858E47E",
          NextDialogue = 80030212,
          SpeakNpcId = 94202,
          Subtitle = "I was just like any ordinary kid. Dumb and naive.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E47E"
        },
        [80030212] = {
          ContentEN = "Look, I really don't feel like talking about my sisters. They tormented me during my childhood. But since you're my holiday buddy, I will tell you this.",
          DialogueId = 80030212,
          GUID = "C858E4A8",
          NextDialogue = 80030213,
          SpeakNpcId = 94202,
          Subtitle = "Look, I really don't feel like talking about my sisters. They tormented me during my childhood. But since you're my holiday buddy, I will tell you this.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E4A8"
        },
        [80030213] = {
          ContentEN = "I grew up with their \"love\". To survive their clutches... ahem, I mean love, I had to develop many skills.",
          DialogueId = 80030213,
          GUID = "C858E4D2",
          NextOptions = {
            [1] = 800302131,
            [2] = 800302132
          },
          SpeakNpcId = 94202,
          Subtitle = "I grew up with their \"love\". To survive their clutches... ahem, I mean love, I had to develop many skills.",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E4D2"
        },
        [80030214] = {
          ContentEN = "Yeah, love. Tough love.",
          DialogueId = 80030214,
          GUID = "C858E4FC",
          NextDialogue = 80030216,
          SpeakNpcId = 94202,
          Subtitle = "Yeah, love. Tough love.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E4FC"
        },
        [80030215] = {
          ContentEN = "Yeah, it was rather bitter.",
          DialogueId = 80030215,
          GUID = "C858E526",
          NextDialogue = 80030216,
          SpeakNpcId = 94202,
          Subtitle = "Yeah, it was rather bitter.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E526"
        },
        [80030216] = {
          ContentEN = "Back then, they told me that a gentleman should kiss a lady's dress when they meet, and that one should adhere to principles and etiquette to conceal their true thoughts and feelings.",
          DialogueId = 80030216,
          GUID = "C858E550",
          NextDialogue = 80030217,
          SpeakNpcId = 94202,
          Subtitle = "Back then, they told me that a gentleman should kiss a lady's dress when they meet, and that one should adhere to principles and etiquette to conceal their true thoughts and feelings.",
          TalkActionId = {
            [1] = "94202:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E550"
        },
        [80030217] = {
          ContentEN = "When I was five or six years old, I acted like a gentleman to every woman I met, even though I didn't want to.",
          DialogueId = 80030217,
          GUID = "C858E57A",
          NextDialogue = 80030218,
          SpeakNpcId = 94202,
          Subtitle = "When I was five or six years old, I acted like a gentleman to every woman I met, even though I didn't want to.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E57A"
        },
        [80030218] = {
          ContentEN = "You can imagine how my sisters watched me and laughed. Later on, they told me that gentlemen didn't really have to do that.",
          DialogueId = 80030218,
          GUID = "C858E5A4",
          NextDialogue = 80030219,
          SpeakNpcId = 94202,
          Subtitle = "You can imagine how my sisters watched me and laughed. Later on, they told me that gentlemen didn't really have to do that.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E5A4"
        },
        [80030219] = {
          ContentEN = "They should actually kiss the back of a lady's hand. Not her dress.",
          DialogueId = 80030219,
          GUID = "C858E5CE",
          NextDialogue = 80030220,
          SpeakNpcId = 94202,
          Subtitle = "They should actually kiss the back of a lady's hand. Not her dress.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E5CE"
        },
        [80030220] = {
          ContentEN = "Anyway, let's not talk about this. Here's a toast to my miserable childhood.",
          DialogueId = 80030220,
          GUID = "C858E5F8",
          SpeakNpcId = 94202,
          Subtitle = "Anyway, let's not talk about this. Here's a toast to my miserable childhood.",
          TalkActionId = {
            [1] = "94202:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E5F8"
        },
        [80030401] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          ContentEN = "I'm here. I couldn't stand you up now, could I?",
          DialogueId = 80030401,
          GUID = "C85903AA",
          LookAt = {
            [1] = "94202:p(18000P1)"
          },
          NextDialogue = 80030402,
          SpeakNpcId = 94202,
          Subtitle = "I'm here. I couldn't stand you up now, could I?",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85903AA"
        },
        [80030402] = {
          ContentEN = "Check this out. The Military Alloy Temperature Control Vessel - Ultimate Type. I've tried it, and it works like a charm... *yawn*",
          DialogueId = 80030402,
          GUID = "C85903D4",
          NextDialogue = 80030403,
          SpeakNpcId = 94202,
          Subtitle = "Check this out. The Military Alloy Temperature Control Vessel - Ultimate Type. I've tried it, and it works like a charm... *yawn*",
          TalkActionId = {
            [1] = "94202:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/004/C85903D4"
        },
        [80030403] = {
          ContentEN = "I'm feeling a bit drowsy at the moment, I need to find a place to get some shut-eye. I've nearly run out of annual leave, and I can't report to Chief Sibylle tomorrow with dark rings around my eyes.",
          DialogueId = 80030403,
          GUID = "C85903FE",
          NextOptions = {
            [1] = 800304031,
            [2] = 800304032
          },
          SpeakNpcId = 94202,
          Subtitle = "I'm feeling a bit drowsy at the moment, I need to find a place to get some shut-eye. I've nearly run out of annual leave, and I can't report to Chief Sibylle tomorrow with dark rings around my eyes.",
          TalkActionId = {
            [1] = "94202:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/004/C85903FE"
        },
        [80030404] = {
          ContentEN = "You're very perceptive. Yes, there's something on my mind.",
          DialogueId = 80030404,
          GUID = "C8590428",
          NextDialogue = 80030405,
          SpeakNpcId = 94202,
          Subtitle = "You're very perceptive. Yes, there's something on my mind.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590428"
        },
        [80030405] = {
          ContentEN = "I won't keep it from you. Basically, I had a nightmare.",
          DialogueId = 80030405,
          GUID = "C8590452",
          NextOptions = {
            [1] = 800304071
          },
          SpeakNpcId = 94202,
          Subtitle = "I won't keep it from you. Basically, I had a nightmare.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590452"
        },
        [80030406] = {
          ContentEN = "Of course not. You know how lazy I am. I turn most invitations down.",
          DialogueId = 80030406,
          GUID = "C859047C",
          NextDialogue = 80030407,
          SpeakNpcId = 94202,
          Subtitle = "Of course not. You know how lazy I am. I turn most invitations down.",
          TalkActionId = {
            [1] = "94202:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Landi/004/C859047C"
        },
        [80030407] = {
          ContentEN = "To be honest, I had a nightmare last night, so I'm feeling a bit off today.",
          DialogueId = 80030407,
          GUID = "C85904A6",
          NextOptions = {
            [1] = 800304071
          },
          SpeakNpcId = 94202,
          Subtitle = "To be honest, I had a nightmare last night, so I'm feeling a bit off today.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85904A6"
        },
        [80030408] = {
          ContentEN = "Well, like many of my nightmares, this one was about my dad.",
          DialogueId = 80030408,
          GUID = "C85904D0",
          NextOptions = {
            [1] = 800304081
          },
          SpeakNpcId = 94202,
          Subtitle = "Well, like many of my nightmares, this one was about my dad.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85904D0"
        },
        [80030409] = {
          ContentEN = "He used to be a soldier in the Empire, but... he's been bedridden for years now.",
          DialogueId = 80030409,
          GUID = "C85904FA",
          NextDialogue = 80030410,
          SpeakNpcId = 94202,
          Subtitle = "He used to be a soldier in the Empire, but... he's been bedridden for years now.",
          TalkActionId = {
            [1] = "94202:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Landi/004/C85904FA"
        },
        [80030410] = {
          ContentEN = "Back when I was tricked by my sisters into becoming a gentleman, he was a sergeant in the Legion. He spent more time on the front lines than at home, just like me now.",
          DialogueId = 80030410,
          GUID = "C8590524",
          NextDialogue = 80030411,
          SpeakNpcId = 94202,
          Subtitle = "Back when I was tricked by my sisters into becoming a gentleman, he was a sergeant in the Legion. He spent more time on the front lines than at home, just like me now.",
          TalkActionId = {
            [1] = "94202:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590524"
        },
        [80030411] = {
          ContentEN = "But the difference between us is that he was proud of being a soldier. He treated the Legion as his home and his actual home as nothing more than a hotel where he could complain as much as he liked.",
          DialogueId = 80030411,
          GUID = "C859054E",
          NextDialogue = 80030412,
          SpeakNpcId = 94202,
          Subtitle = "But the difference between us is that he was proud of being a soldier. He treated the Legion as his home and his actual home as nothing more than a hotel where he could complain as much as he liked.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C859054E"
        },
        [80030412] = {
          ContentEN = "Whenever he came home, he'd complain about something or other, like the Emperor's portrait not being hung up properly, or my sisters coming home too late.",
          DialogueId = 80030412,
          GUID = "C8590578",
          NextDialogue = 80030413,
          SpeakNpcId = 94202,
          Subtitle = "Whenever he came home, he'd complain about something or other, like the Emperor's portrait not being hung up properly, or my sisters coming home too late.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590578"
        },
        [80030413] = {
          ContentEN = "And he'd always check up on me last.",
          DialogueId = 80030413,
          GUID = "C85905A2",
          NextDialogue = 80030414,
          SpeakNpcId = 94202,
          Subtitle = "And he'd always check up on me last.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85905A2"
        },
        [80030414] = {
          ContentEN = "He'd check how much taller I'd got, how many books I'd read, how many forts I'd learned the names of, and what new survival skills I'd acquired.",
          DialogueId = 80030414,
          GUID = "C85905CC",
          NextDialogue = 80030415,
          SpeakNpcId = 94202,
          Subtitle = "He'd check how much taller I'd got, how many books I'd read, how many forts I'd learned the names of, and what new survival skills I'd acquired.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85905CC"
        },
        [80030415] = {
          ContentEN = "I tried talking to him about other things, but he wasn't interested in anything other than \"being a soldier.\"",
          DialogueId = 80030415,
          GUID = "C85905F6",
          NextDialogue = 80030416,
          SpeakNpcId = 94202,
          Subtitle = "I tried talking to him about other things, but he wasn't interested in anything other than \"being a soldier.\"",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85905F6"
        },
        [80030416] = {
          ContentEN = "Once, to try to please him, I painstakingly carved a wooden pistol for him and eagerly awaited his praise.",
          DialogueId = 80030416,
          GUID = "C8590620",
          NextDialogue = 80030417,
          SpeakNpcId = 94202,
          Subtitle = "Once, to try to please him, I painstakingly carved a wooden pistol for him and eagerly awaited his praise.",
          TalkActionId = {
            [1] = "94202:Sit_Talk03ToTalkL_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590620"
        },
        [80030417] = {
          ContentEN = "But with a stren face he just snatched it from me, \"Don't waste your time on things like this. Think about how you can become a better soldier from now on.\"",
          DialogueId = 80030417,
          GUID = "C859064A",
          NextDialogue = 80030418,
          SpeakNpcId = 94202,
          Subtitle = "But with a stren face he just snatched it from me, \"Don't waste your time on things like this. Think about how you can become a better soldier from now on.\"",
          VoiceName = "voice/$Locale$/inv/Landi/004/C859064A"
        },
        [80030418] = {
          ContentEN = "At that moment, I felt something change within me. Something cold, bitter, intangible and unstoppable, like the howling wind outside our home.",
          DialogueId = 80030418,
          GUID = "C8590674",
          NextDialogue = 80030419,
          SpeakNpcId = 94202,
          Subtitle = "At that moment, I felt something change within me. Something cold, bitter, intangible and unstoppable, like the howling wind outside our home.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590674"
        },
        [80030419] = {
          ContentEN = "Later, I gradually realised that it was hatred. Although it was weak to begin with, it was still strong enough to make me feel that the person in front of me was nothing more than a stranger.",
          DialogueId = 80030419,
          GUID = "C859069E",
          NextDialogue = 80030420,
          SpeakNpcId = 94202,
          Subtitle = "Later, I gradually realised that it was hatred. Although it was weak to begin with, it was still strong enough to make me feel that the person in front of me was nothing more than a stranger.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C859069E"
        },
        [80030420] = {
          ContentEN = "So after that, I stopped trying to be the son he wanted me to be. I ignored his check-ups on me, no matter how much he scolded me.",
          DialogueId = 80030420,
          GUID = "C85906C8",
          NextDialogue = 80030421,
          SpeakNpcId = 94202,
          Subtitle = "So after that, I stopped trying to be the son he wanted me to be. I ignored his check-ups on me, no matter how much he scolded me.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85906C8"
        },
        [80030421] = {
          ContentEN = "Years passed... He was shot in the head while protecting one of his subordinates. He was sent home with a purple heart. Although he was still alive, he had fallen into a coma.",
          DialogueId = 80030421,
          GUID = "C85906F2",
          NextDialogue = 80030422,
          SpeakNpcId = 94202,
          Subtitle = "Years passed... He was shot in the head while protecting one of his subordinates. He was sent home with a purple heart. Although he was still alive, he had fallen into a coma.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85906F2"
        },
        [80030422] = {
          ContentEN = "When he came back, he had nothing but shiny medals, his slender savings, and a wooden pistol that was broken in two.",
          DialogueId = 80030422,
          GUID = "C859071C",
          NextDialogue = 80030423,
          SpeakNpcId = 94202,
          Subtitle = "When he came back, he had nothing but shiny medals, his slender savings, and a wooden pistol that was broken in two.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C859071C"
        },
        [80030423] = {
          ContentEN = "I thought he was disappointed in me because of that broken pistol, but his subordinates told me that he carried it with him at all times and that it broke when he fell on the battlefield.",
          DialogueId = 80030423,
          GUID = "C8590746",
          NextDialogue = 80030424,
          SpeakNpcId = 94202,
          Subtitle = "I thought he was disappointed in me because of that broken pistol, but his subordinates told me that he carried it with him at all times and that it broke when he fell on the battlefield.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590746"
        },
        [80030424] = {
          ContentEN = "It seems that he did love me after all. But his way of expressing it was unrecognisable. Maddening.",
          DialogueId = 80030424,
          GUID = "C8590770",
          NextDialogue = 80030425,
          SpeakNpcId = 94202,
          Subtitle = "It seems that he did love me after all. But his way of expressing it was unrecognisable. Maddening.",
          TalkActionId = {
            [1] = "94202:Sit_Talk03ToTalkL_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590770"
        },
        [80030425] = {
          ContentEN = "If he was proud of me, he should've told me. A few words of encouragement would've been enough, but instead, he just forced me to do things I didn't enjoy.",
          DialogueId = 80030425,
          GUID = "C859079A",
          NextDialogue = 80030426,
          SpeakNpcId = 94202,
          Subtitle = "If he was proud of me, he should've told me. A few words of encouragement would've been enough, but instead, he just forced me to do things I didn't enjoy.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C859079A"
        },
        [80030426] = {
          ContentEN = "Although he'd never push me to do anything again, I still joined the army, just like he wanted.",
          DialogueId = 80030426,
          GUID = "C85907C4",
          NextDialogue = 80030427,
          SpeakNpcId = 94202,
          Subtitle = "Although he'd never push me to do anything again, I still joined the army, just like he wanted.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85907C4"
        },
        [80030427] = {
          ContentEN = "I was curious about the Legion, the place that had turned my father into a detached man. I also wanted to prove that I could live a great life without his scolding.",
          DialogueId = 80030427,
          GUID = "C85907EE",
          NextDialogue = 80030428,
          SpeakNpcId = 94202,
          Subtitle = "I was curious about the Legion, the place that had turned my father into a detached man. I also wanted to prove that I could live a great life without his scolding.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85907EE"
        },
        [80030428] = {
          ContentEN = "Unfortunately for both of us, I found out that he was right all along. He was protecting me.",
          DialogueId = 80030428,
          GUID = "C8590818",
          NextDialogue = 80030429,
          SpeakNpcId = 94202,
          Subtitle = "Unfortunately for both of us, I found out that he was right all along. He was protecting me.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590818"
        },
        [80030429] = {
          ContentEN = "We're unlike most people in the Legion. We crawled out of piles of corpses on the battlefield, and kneel down to receive the medals they bestowed upon us like charity.",
          DialogueId = 80030429,
          GUID = "C8590842",
          NextDialogue = 80030430,
          SpeakNpcId = 94202,
          Subtitle = "We're unlike most people in the Legion. We crawled out of piles of corpses on the battlefield, and kneel down to receive the medals they bestowed upon us like charity.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590842"
        },
        [80030430] = {
          ContentEN = "A decent job, a great life, and a means of survival. Everything about us is determined by those small medals. For the sake of our family, my dad devoted himself to them.",
          DialogueId = 80030430,
          GUID = "C859086C",
          NextDialogue = 80030431,
          SpeakNpcId = 94202,
          Subtitle = "A decent job, a great life, and a means of survival. Everything about us is determined by those small medals. For the sake of our family, my dad devoted himself to them.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C859086C"
        },
        [80030431] = {
          ContentEN = "He obeyed, endured, suppressed his feelings, pushed back the tears, and turned himself into a husk of a man.",
          DialogueId = 80030431,
          GUID = "C8590896",
          NextDialogue = 80030432,
          SpeakNpcId = 94202,
          Subtitle = "He obeyed, endured, suppressed his feelings, pushed back the tears, and turned himself into a husk of a man.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590896"
        },
        [80030432] = {
          ContentEN = "I can't do that, but I need money to support myself and maintain my family's decent lifestyle. So, I'm a happy loser now, as you can see.",
          DialogueId = 80030432,
          GUID = "C85908C0",
          NextOptions = {
            [1] = 800304321
          },
          SpeakNpcId = 94202,
          Subtitle = "I can't do that, but I need money to support myself and maintain my family's decent lifestyle. So, I'm a happy loser now, as you can see.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85908C0"
        },
        [80030433] = {
          ContentEN = "...",
          DialogueId = 80030433,
          GUID = "C85908EA",
          NextDialogue = 80030434,
          SpeakNpcId = 94202,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85908EA"
        },
        [80030434] = {
          ContentEN = "You have a keen eye. But to be frank, I have no idea what I want to do. After a long bout of depression, I've finally realised that —",
          DialogueId = 80030434,
          GUID = "C8590914",
          NextDialogue = 80030435,
          SpeakNpcId = 94202,
          Subtitle = "You have a keen eye. But to be frank, I have no idea what I want to do. After a long bout of depression, I've finally realised that —",
          TalkActionId = {
            [1] = "94202:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590914"
        },
        [80030435] = {
          ContentEN = "Even though I haven't lived up to my dad's expectations, I'm happy with the life I have.",
          DialogueId = 80030435,
          GUID = "C859093E",
          NextOptions = {
            [1] = 800304351,
            [2] = 800304352
          },
          SpeakNpcId = 94202,
          Subtitle = "Even though I haven't lived up to my dad's expectations, I'm happy with the life I have.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C859093E"
        },
        [80030436] = {
          ContentEN = "I hope so. If that happens, my nightmares may finally end.",
          DialogueId = 80030436,
          GUID = "C8590968",
          NextDialogue = 80030438,
          SpeakNpcId = 94202,
          Subtitle = "I hope so. If that happens, my nightmares may finally end.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590968"
        },
        [80030437] = {
          ContentEN = "That tastes good. This will help me sleep without nightmares.",
          DialogueId = 80030437,
          GUID = "C8590992",
          NextDialogue = 80030438,
          SpeakNpcId = 94202,
          Subtitle = "That tastes good. This will help me sleep without nightmares.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590992"
        },
        [80030438] = {
          ContentEN = "Thanks, holiday buddy, but I need some sleep now, or else I'll have to take more leave tomorrow.",
          DialogueId = 80030438,
          GUID = "C85909BC",
          NextDialogue = 80030439,
          SpeakNpcId = 94202,
          Subtitle = "Thanks, holiday buddy, but I need some sleep now, or else I'll have to take more leave tomorrow.",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/004/C85909BC"
        },
        [80030439] = {
          ContentEN = "Don't worry, I'll be the regular Randy you know the next time we meet. And if I have another nightmare, please make me one more cup of this delicious drink.",
          DialogueId = 80030439,
          GUID = "C85909E6",
          SpeakNpcId = 94202,
          Subtitle = "Don't worry, I'll be the regular Randy you know the next time we meet. And if I have another nightmare, please make me one more cup of this delicious drink.",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/004/C85909E6"
        },
        [80030501] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          ContentEN = "A hot drink with extra sugar, please. I brought some desserts from the Imperial Capital. I queued up to buy them during my break. Want to try some?",
          DialogueId = 80030501,
          GUID = "C8591412",
          LookAt = {
            [1] = "94202:p(18000P1)"
          },
          NextOptions = {
            [1] = 800305011,
            [2] = 800305012
          },
          SpeakNpcId = 94202,
          Subtitle = "A hot drink with extra sugar, please. I brought some desserts from the Imperial Capital. I queued up to buy them during my break. Want to try some?",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591412"
        },
        [80030502] = {
          ContentEN = "I sure am. I'm in the mood for a sweet drink as a prelude to my invitation.",
          DialogueId = 80030502,
          GUID = "C859143C",
          NextDialogue = 80030504,
          SpeakNpcId = 94202,
          Subtitle = "I sure am. I'm in the mood for a sweet drink as a prelude to my invitation.",
          TalkActionId = {
            [1] = "94202:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C859143C"
        },
        [80030503] = {
          ContentEN = "Ooh! I want to ask a small favour of you, but I wouldn't call it a \"plan.\"",
          DialogueId = 80030503,
          GUID = "C8591466",
          NextDialogue = 80030504,
          SpeakNpcId = 94202,
          Subtitle = "Ooh! I want to ask a small favour of you, but I wouldn't call it a \"plan.\"",
          TalkActionId = {
            [1] = "94202:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591466"
        },
        [80030504] = {
          ContentEN = "Ahem... Maybe this is a little sudden, but do you want to attend a dance with me?",
          DialogueId = 80030504,
          GUID = "C8591490",
          NextDialogue = 80030505,
          SpeakNpcId = 94202,
          Subtitle = "Ahem... Maybe this is a little sudden, but do you want to attend a dance with me?",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591490"
        },
        [80030505] = {
          ContentEN = "Like I mentioned to you before, the Legion needs to maintain ties with local nobility. So, I need to attend annoying social balls in the inner city from time to time.",
          DialogueId = 80030505,
          GUID = "C85914BA",
          NextDialogue = 80030506,
          SpeakNpcId = 94202,
          Subtitle = "Like I mentioned to you before, the Legion needs to maintain ties with local nobility. So, I need to attend annoying social balls in the inner city from time to time.",
          TalkActionId = {
            [1] = "94202:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C85914BA"
        },
        [80030506] = {
          ContentEN = "I really don't want to go. The trip is paid for, but dealing with nobility is such a headache.",
          DialogueId = 80030506,
          GUID = "C85914E4",
          NextDialogue = 80030507,
          SpeakNpcId = 94202,
          Subtitle = "I really don't want to go. The trip is paid for, but dealing with nobility is such a headache.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C85914E4"
        },
        [80030507] = {
          ContentEN = "So, I have a perfect solution. I can take a gorgeous lady with me as my partner.",
          DialogueId = 80030507,
          GUID = "C859150E",
          NextDialogue = 80030508,
          SpeakNpcId = 94202,
          Subtitle = "So, I have a perfect solution. I can take a gorgeous lady with me as my partner.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C859150E"
        },
        [80030508] = {
          ContentEN = "That way, no one will try to introduce me to a female relative I've never met before.",
          DialogueId = 80030508,
          GUID = "C8591538",
          NextOptions = {
            [1] = 800305081,
            [2] = 800305082
          },
          SpeakNpcId = 94202,
          Subtitle = "That way, no one will try to introduce me to a female relative I've never met before.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591538"
        },
        [80030509] = {
          ContentEN = "Well... I was thinking... maybe... you could try to disguise yourself as a lady.",
          DialogueId = 80030509,
          GUID = "C8591562",
          NextOptions = {
            [1] = 800305091,
            [2] = 800305092
          },
          SpeakNpcId = 94202,
          Subtitle = "Well... I was thinking... maybe... you could try to disguise yourself as a lady.",
          TalkActionId = {
            [1] = "94202:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591562"
        },
        [80030510] = {
          ContentEN = "I can't. I'm the one who's been invited.",
          DialogueId = 80030510,
          GUID = "C859158C",
          NextDialogue = 80030512,
          SpeakNpcId = 94202,
          Subtitle = "I can't. I'm the one who's been invited.",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C859158C"
        },
        [80030511] = {
          ContentEN = "Sorry, but you're my last hope. I'm really clutching at straws here!",
          DialogueId = 80030511,
          GUID = "C85915B6",
          NextDialogue = 80030512,
          SpeakNpcId = 94202,
          Subtitle = "Sorry, but you're my last hope. I'm really clutching at straws here!",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C85915B6"
        },
        [80030512] = {
          ContentEN = "We've had so many drinks together, and you're my closest friend. I'm even closer to you than my siblings, so I'm begging you for help.",
          DialogueId = 80030512,
          GUID = "C85915E0",
          NextDialogue = 80030513,
          SpeakNpcId = 94202,
          Subtitle = "We've had so many drinks together, and you're my closest friend. I'm even closer to you than my siblings, so I'm begging you for help.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C85915E0"
        },
        [80030513] = {
          ContentEN = "If you help me in my time of need, I'll give you half of my salary for the next six months. And, if Chief Sibylle tries to arrest you next time, I'll come forward and protect you!",
          DialogueId = 80030513,
          GUID = "C859160A",
          NextDialogue = 80030514,
          SpeakNpcId = 94202,
          Subtitle = "If you help me in my time of need, I'll give you half of my salary for the next six months. And, if Chief Sibylle tries to arrest you next time, I'll come forward and protect you!",
          VoiceName = "voice/$Locale$/inv/Landi/005/C859160A"
        },
        [80030514] = {
          ContentEN = "If that's not enough, I'll dress up like a lady and entertain you after the ball. What do you say?",
          DialogueId = 80030514,
          GUID = "C8591634",
          NextOptions = {
            [1] = 800305141,
            [2] = 800305142
          },
          SpeakNpcId = 94202,
          Subtitle = "If that's not enough, I'll dress up like a lady and entertain you after the ball. What do you say?",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591634"
        },
        [80030515] = {
          ContentEN = "No, no, no! You've got the wrong idea! What makes you think that?",
          DialogueId = 80030515,
          GUID = "C859165E",
          NextDialogue = 80030516,
          SpeakNpcId = 94202,
          Subtitle = "No, no, no! You've got the wrong idea! What makes you think that?",
          TalkActionId = {
            [1] = "94202:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C859165E"
        },
        [80030516] = {
          ContentEN = "I mean, it's normal, right? Best buds do everything together — hang out, share meals, hit the restroom, try on dresses...",
          DialogueId = 80030516,
          GUID = "C8591688",
          NextOptions = {
            [1] = 800305161
          },
          SpeakNpcId = 94202,
          Subtitle = "I mean, it's normal, right? Best buds do everything together — hang out, share meals, hit the restroom, try on dresses...",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591688"
        },
        [80030517] = {
          ContentEN = "Hey, don't laugh at me. I'm really in a bind here. Please just give me your answer. If you say \"no,\" I'll have to find another solution.",
          DialogueId = 80030517,
          GUID = "C85916B2",
          NextOptions = {
            [1] = 800305171,
            [2] = 800305172
          },
          SpeakNpcId = 94202,
          Subtitle = "Hey, don't laugh at me. I'm really in a bind here. Please just give me your answer. If you say \"no,\" I'll have to find another solution.",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C85916B2"
        },
        [80030518] = {
          ContentEN = "Just think about it...",
          DialogueId = 80030518,
          GUID = "C85916DC",
          NextDialogue = 80030519,
          SpeakNpcId = 94202,
          Subtitle = "Just think about it...",
          VoiceName = "voice/$Locale$/inv/Landi/005/C85916DC"
        },
        [80030519] = {
          ContentEN = "Huh? Really? That's fantastic! You're a lifesaver!",
          DialogueId = 80030519,
          FacialId = {
            [1] = "94202:Shock01"
          },
          GUID = "C8591706",
          NextDialogue = 80030520,
          SpeakNpcId = 94202,
          Subtitle = "Huh? Really? That's fantastic! You're a lifesaver!",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591706"
        },
        [80030520] = {
          ContentEN = "You've done me a huge favour. I'll repay you however I can.",
          DialogueId = 80030520,
          FacialId = {
            [1] = "94202:None"
          },
          GUID = "C8591730",
          NextDialogue = 80030521,
          SpeakNpcId = 94202,
          Subtitle = "You've done me a huge favour. I'll repay you however I can.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591730"
        },
        [80030521] = {
          ContentEN = "But let's talk about this after the ball. I need to go home and prepare my outfit before you change your mind.",
          DialogueId = 80030521,
          GUID = "C859175A",
          NextDialogue = 80030522,
