            [1] = "94202:Shock01"
          },
          GUID = "C85918AA",
          NextDialogue = 80030529,
          SpeakNpcId = 94202,
          Subtitle = "Why on earth would you think that? If I really wanted to arrest you, I could've done that the first time we met.",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C85918AA"
        },
        [80030529] = {
          ContentEN = "I don't see the point in using my precious leave to come here and organise something like a \"secret arrest ball\".",
          DialogueId = 80030529,
          GUID = "C85918D4",
          NextDialogue = 80030530,
          SpeakNpcId = 94202,
          Subtitle = "I don't see the point in using my precious leave to come here and organise something like a \"secret arrest ball\".",
          VoiceName = "voice/$Locale$/inv/Landi/005/C85918D4"
        },
        [80030530] = {
          ContentEN = "And what if you turn me down? How would my plan work in that case?",
          DialogueId = 80030530,
          GUID = "C85918FE",
          NextDialogue = 80030531,
          SpeakNpcId = 94202,
          Subtitle = "And what if you turn me down? How would my plan work in that case?",
          VoiceName = "voice/$Locale$/inv/Landi/005/C85918FE"
        },
        [80030531] = {
