          SpeakNpcId = 94202,
          Subtitle = "You must be kidding. Do you seriously think I'm a scheming fool like that?",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591928"
        },
        [80030532] = {
          ContentEN = "Alright then. If you really did misunderstand me and think I was a shameless jerk who'd betray his friends like that, I'd need a month's leave to recover from such heartbreak.",
