        [80040214] = {
          Camera = "-98.115723,8.075684,129.975586,-0.007874,0.586638,40.149609,45.000011,255.283401,false,DoNotOverride,6.056871",
          ContentEN = "When we were kids, some bad grown-ups often picked on us. But you'd rather fight them head-on than back down with smart words, and you always ended up bruised and battered.",
