        [80040216] = {
          Camera = "5.696533,131.451904,130.387329,-0.007873,-1.815492,-128.821289,40.0,258.118256,false,Manual,4.735452",
          ContentEN = "I'm not like you. You're good with words and always know what to say to different people. But I can't do that... People are too complicated. I never really understand what they really mean.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040216,
          FacialId = {
            [1] = "790007:Unhappy01"
          },
          FinalCamera = "2.290283,134.191895,130.387329,-0.007874,-1.815492,-126.620598,40.0,258.118256,false,Manual,4.735452",
          GUID = "C85F4DF0",
          NextDialogue = 80040217,
          Scripts = "SEQ{PlayAnimation{ActorId{790007},AnimationId{\"Disagree\"},Duration{1}},PlayAnimation{ActorId{790007},AnimationId{\"Explain02_Start\"},Duration{2}}}",
          SpeakNpcId = 790007,
          Subtitle = "I'm not like you. You're good with words and always know what to say to different people. But I can't do that... People are too complicated. I never really understand what they really mean.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/002/C85F4DF0"
        },
        [80040217] = {
