        [80050217] = {
          ContentEN = "Why do you like seeing the stars so much, Fina?",
          DialogueId = 80050217,
          GUID = "C865B6BA",
          NextDialogue = 80050218,
          Subtitle = "Why do you like seeing the stars so much, Fina?"
        },
        [80050218] = {
          Camera = "80.75,208.85965,155.646973,0.000058,-12.000109,-112.178284,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentEN = "A long time ago, my mom told me a story about a little bird that turned into a star... It's my favourite, and I'd love to share it with you.",
          DialogueId = 80050218,
          GUID = "C865B6E4",
          NextDialogue = 80050219,
          Scripts = "SEQ{PlayAnimation{ActorId{790017},AnimationId{\"Explain02_Start\"},Duration{3}},PlayAnimation{ActorId{790017},AnimationId{\"Explain02_End\"},Duration{1}}}",
          SpeakNpcId = 790017,
          Subtitle = "A long time ago, my mom told me a story about a little bird that turned into a star... It's my favourite, and I'd love to share it with you.",
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B6E4"
        },
        [80050219] = {
          Camera = "23.431641,110.859238,117.97876,0.000015,-3.600008,-118.598862,35.0,100000.0,false,DoNotOverride,2.8",
          ContentEN = "This bird wasn't like the others: she had ugly feathers, a jarring song, and her claws and beak were not sharp. The other birds didn't like her, always bullying her, trying to chase her away.",
          DialogueId = 80050219,
          GUID = "C865B70E",
          NextDialogue = 80050220,
          Scripts = "PlayAnimation{_delay{2},ActorId{790017},AnimationId{\"DisagreeHead\"},Duration{2}}",
          SpeakNpcId = 790017,
          Subtitle = "This bird wasn't like the others: she had ugly feathers, a jarring song, and her claws and beak were not sharp. The other birds didn't like her, always bullying her, trying to chase her away.",
          TalkActionId = {
            [1] = "100001:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B70E"
        },
        [80050220] = {
          Camera = "23.431641,110.859238,117.97876,0.000015,-3.600008,-118.598862,35.0,100000.0,false,DoNotOverride,2.8",
          ContentEN = "Yet, this little bird yearned for the starry sky. She prayed to the stars, wishing for a chance to join them, even if it meant perishing in their fiery glow.",
          DialogueId = 80050220,
          GUID = "C865B738",
          NextOptions = {
            [1] = 80050221
          },
          SpeakNpcId = 790017,
          Subtitle = "Yet, this little bird yearned for the starry sky. She prayed to the stars, wishing for a chance to join them, even if it meant perishing in their fiery glow.",
          TalkActionId = {
            [1] = "790017:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B738"
        },
        [80050221] = {
          ContentEN = "So the stars answered her prayers?",
          DialogueId = 80050221,
          GUID = "C865B762",
          NextDialogue = 80050222,
          Subtitle = "So the stars answered her prayers?"
        },
        [80050222] = {
          Camera = "23.431641,110.859238,117.97876,0.000015,-3.600008,-118.598862,35.0,100000.0,false,DoNotOverride,2.8",
          ContentEN = "No... Some stars ignored her, while some mocked her for overreaching: a plain little bird dreaming of soaring through the beautiful starry sky, how ridiculous.",
          DialogueId = 80050222,
          GUID = "C865B78C",
          NextOptions = {
            [1] = 80050223
          },
          Scripts = "SEQ{PlayAnimation{ActorId{790017},AnimationId{\"Explain01_End\"},Duration{2}},PlayAnimation{ActorId{790017},AnimationId{\"DisagreeHead\"},Duration{1}}}",
          SpeakNpcId = 790017,
          Subtitle = "No... Some stars ignored her, while some mocked her for overreaching: a plain little bird dreaming of soaring through the beautiful starry sky, how ridiculous.",
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B78C"
        },
        [80050223] = {
          ContentEN = "What happened then?",
          DialogueId = 80050223,
          GUID = "C865B7B6",
          NextDialogue = 80050224,
          Subtitle = "What happened then?"
        },
        [80050224] = {
          Camera = "23.431641,110.859238,117.97876,0.000015,-3.600008,-118.598862,35.0,100000.0,false,DoNotOverride,2.8",
          ContentEN = "She decided not to pin her hopes on others. Bidding farewell to her family, she flew toward the night sky alone.",
          DialogueId = 80050224,
          GUID = "C865B7E0",
          NextDialogue = 80050225,
          SpeakNpcId = 790017,
          Subtitle = "She decided not to pin her hopes on others. Bidding farewell to her family, she flew toward the night sky alone.",
          TalkActionId = {
            [1] = "790017:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B7E0"
        },
        [80050225] = {
          Camera = "23.431641,110.859238,117.97876,0.000015,-3.600008,-118.598862,35.0,100000.0,false,DoNotOverride,2.8",
          ContentEN = "The higher she flew, the colder the sky became; eventually, she froze, never to flap her wings again.",
          DialogueId = 80050225,
          GUID = "C865B80A",
          NextOptions = {
            [1] = 80050226
          },
          SpeakNpcId = 790017,
          Subtitle = "The higher she flew, the colder the sky became; eventually, she froze, never to flap her wings again.",
          TalkActionId = {
            [1] = "790017:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B80A"
        },
        [80050226] = {
          ContentEN = "...That's quite a sad ending.",
          DialogueId = 80050226,
          GUID = "C865B834",
          NextDialogue = 80050227,
          Subtitle = "...That's quite a sad ending."
        },
        [80050227] = {
