          ContentEN = "But don't worry! Now I'm quite the expert at identifying which plants are safe to munch on.",
          DialogueId = 80060124,
          GUID = "C86C1018",
          NextOptions = {
            [1] = 80060125
          },
          SpeakNpcId = 95101,
          Subtitle = "But don't worry! Now I'm quite the expert at identifying which plants are safe to munch on.",
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C1018"
        },
        [80060125] = {
          ContentEN = "How come you've tried so many different \"foods\"?",
          DialogueId = 80060125,
          GUID = "C86C1042",
          NextDialogue = 80060126,
          Subtitle = "How come you've tried so many different \"foods\"?"
        },
        [80060126] = {
          ContentEN = "Because there was nothing much to eat. I started wandering alone at a very young age.",
          DialogueId = 80060126,
          FacialId = {
            [1] = "95101:Iyada01"
          },
          GUID = "C86C106C",
          NextDialogue = 80060127,
          SpeakNpcId = 95101,
          Subtitle = "Because there was nothing much to eat. I started wandering alone at a very young age.",
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C106C"
        },
        [80060127] = {
          ContentEN = "I've always been a big eater, so even though kind people sometimes gave me food, it was never enough — I was always hungry...",
          DialogueId = 80060127,
          FacialId = {
            [1] = "95101:Sad01"
          },
          GUID = "C86C1096",
          NextDialogue = 80060128,
          SpeakNpcId = 95101,
          Subtitle = "I've always been a big eater, so even though kind people sometimes gave me food, it was never enough — I was always hungry...",
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C1096"
        },
        [80060128] = {
          ContentEN = "Aww, don't feel bad for me! I'm not upset about it, because I met Filbert soon after.",
          DialogueId = 80060128,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C10C0",
          NextDialogue = 80060129,
          SpeakNpcId = 95101,
          Subtitle = "Aww, don't feel bad for me! I'm not upset about it, because I met Filbert soon after.",
          TalkActionId = {
            [1] = "95101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C10C0"
        },
        [80060129] = {
          ContentEN = "That day, I was super hungry, and so was Filbert. She was just a tiny piglet then, but she gave me the only piece of bread she had found in a bin.",
          DialogueId = 80060129,
          FacialId = {
            [1] = "95101:Satisfy01"
          },
          GUID = "C86C10EA",
          NextDialogue = 80060130,
          SpeakNpcId = 95101,
          Subtitle = "That day, I was super hungry, and so was Filbert. She was just a tiny piglet then, but she gave me the only piece of bread she had found in a bin.",
          TalkActionId = {
            [1] = "95101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C10EA"
        },
        [80060130] = {
          ContentEN = "I don't quite remember what I was thinking back then, just that I whispered into her ear, \"Let's leave the city and find food in the wild together!\"",
          DialogueId = 80060130,
          FacialId = {
            [1] = "95101:Smile02"
          },
          GUID = "C86C1114",
          NextOptions = {
            [1] = 80060131
          },
          SpeakNpcId = 95101,
          Subtitle = "I don't quite remember what I was thinking back then, just that I whispered into her ear, \"Let's leave the city and find food in the wild together!\"",
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C1114"
        },
        [80060131] = {
          ContentEN = "Wow, a pig that understands human speech...",
          DialogueId = 80060131,
          GUID = "C86C113E",
          NextDialogue = 80060132,
          Subtitle = "Wow, a pig that understands human speech..."
        },
        [80060132] = {
          ContentEN = "Uh-huh, amazing, right? Filbert must be a gift from the gods.",
          DialogueId = 80060132,
          GUID = "C86C1168",
          NextDialogue = 80060133,
          SpeakNpcId = 95101,
          Subtitle = "Uh-huh, amazing, right? Filbert must be a gift from the gods.",
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C1168"
        },
        [80060133] = {
          ContentEN = "Ever since that day, Filbert has carried me to fields and forests to find food... We never went hungry again, and we've even been able to share extra food with other starving people.",
          DialogueId = 80060133,
          GUID = "C86C1192",
          NextDialogue = 80060134,
          SpeakNpcId = 95101,
          Subtitle = "Ever since that day, Filbert has carried me to fields and forests to find food... We never went hungry again, and we've even been able to share extra food with other starving people.",
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C1192"
        },
        [80060134] = {
          ContentEN = "Ah... I wonder if Filbert's hungry out there on her own. Can I take the rest of this drink to share with her?",
          DialogueId = 80060134,
          FacialId = {
            [1] = "95101:Satisfy01"
          },
          GUID = "C86C11BC",
          NextOptions = {
            [1] = 80060135,
            [2] = 80060138
          },
          SpeakNpcId = 95101,
          Subtitle = "Ah... I wonder if Filbert's hungry out there on her own. Can I take the rest of this drink to share with her?",
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C11BC"
        },
        [80060135] = {
          ContentEN = "Of course.",
          DialogueId = 80060135,
          GUID = "C86C11E6",
          NextDialogue = 80060136,
          Subtitle = "Of course."
        },
        [80060136] = {
          ContentEN = "Aww, you're so kind-hearted! Some people frown upon me sharing treats with Filbert, just because she looks like a pig. But to me, Filbert is a dear friend...",
          DialogueId = 80060136,
          FacialId = {
            [1] = "95101:Happy01"
          },
          GUID = "C86C1210",
          NextDialogue = 80060137,
          SpeakNpcId = 95101,
          Subtitle = "Aww, you're so kind-hearted! Some people frown upon me sharing treats with Filbert, just because she looks like a pig. But to me, Filbert is a dear friend...",
          TalkActionId = {
            [1] = "95101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C1210"
        },
        [80060137] = {
          ContentEN = "Anyway, thank you so much for not judging!",
          DialogueId = 80060137,
          GUID = "C86C123A",
          NextDialogue = 80060141,
          SpeakNpcId = 95101,
          Subtitle = "Anyway, thank you so much for not judging!",
          TalkActionId = {
            [1] = "95101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C123A"
        },
        [80060138] = {
          ContentEN = "I'd rather not share my drink with a pig...",
          DialogueId = 80060138,
          GUID = "C86C1264",
          NextDialogue = 80060139,
          Subtitle = "I'd rather not share my drink with a pig..."
        },
        [80060139] = {
          ContentEN = "Oh...Okay. Then I won't drink it either.",
          DialogueId = 80060139,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C128E",
          NextDialogue = 80060140,
          SpeakNpcId = 95101,
          Subtitle = "Oh...Okay. Then I won't drink it either.",
          TalkActionId = {
            [1] = "95101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C128E"
        },
        [80060140] = {
          ContentEN = "Filbert is my best friend; rejecting her is the same as rejecting me... it'd hurt her feelings, and mine too. But still, thank you for the bread drink.",
          DialogueId = 80060140,
          FacialId = {
            [1] = "95101:Happy02"
          },
          GUID = "C86C12B8",
          NextDialogue = 80060141,
          SpeakNpcId = 95101,
          Subtitle = "Filbert is my best friend; rejecting her is the same as rejecting me... it'd hurt her feelings, and mine too. But still, thank you for the bread drink.",
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C12B8"
        },
        [80060141] = {
          ContentEN = "I'm full now. See you around!",
          DialogueId = 80060141,
          FacialId = {
            [1] = "95101:None"
          },
