          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4950"
        },
        [80090121] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          ContentEN = "But I can't turn into anything too big or too small. I can do a cat, but not a mouse; a barrel, but not a lamppost.",
          DialogueId = 80090121,
          GUID = "C87F497A",
          LookAt = {
            [1] = "92301:p(18000P1)"
          },
          NextDialogue = 80090122,
          SpeakNpcId = 92301,
          Subtitle = "But I can't turn into anything too big or too small. I can do a cat, but not a mouse; a barrel, but not a lamppost.",
          TalkActionId = {
            [1] = "92301:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F497A"
        },
        [80090122] = {
          ContentEN = "That's enough to fool most people, though. I can just turn into a bin or a crate, and those rotten thieves won't know what hit them!",
          DialogueId = 80090122,
          GUID = "C87F49A4",
          NextOptions = {
            [1] = 80090123,
            [2] = 80090131
          },
          SpeakNpcId = 92301,
          Subtitle = "That's enough to fool most people, though. I can just turn into a bin or a crate, and those rotten thieves won't know what hit them!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F49A4"
        },
        [80090123] = {
          ContentEN = "...Oh boy, this might be a problem someday.",
          DialogueId = 80090123,
          GUID = "C87F49CE",
          NextDialogue = 80090124,
          Subtitle = "...Oh boy, this might be a problem someday."
        },
        [80090124] = {
          ContentEN = "What are you mumbling about?",
          DialogueId = 80090124,
          FacialId = {
            [1] = "92301:Doubt01"
