          DialogueId = 80090125,
          GUID = "C87F4A22",
          NextDialogue = 80090126,
          SpeakNpcId = 790008,
          Subtitle = "Nothing, I just meant you are awesome.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4A22"
        },
        [80090126] = {
