        [80090201] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          ContentEN = "Mmm, this drink's a bit salty but so yummy — like sea breeze-flavored cotton candy!",
