          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F58E6"
        },
        [80090216] = {
          ContentEN = "I've seen too many bad grown-ups to trust them — I might be better off on my own. So I didn't join those kids, and ended up running away by myself.",
          DialogueId = 80090216,
          FacialId = {
            [1] = "92301:Confident01"
          },
          GUID = "C87F5910",
          NextDialogue = 80090217,
          SpeakNpcId = 92301,
          Subtitle = "I've seen too many bad grown-ups to trust them — I might be better off on my own. So I didn't join those kids, and ended up running away by myself.",
