        [80090437] = {
          ContentEN = "That's one way to see it. Though no one knows how long the drink's effects will last... Actually, there's quite a lot we'd like to talk to you about! Maybe this is the chance... 1, you go first!",
          DialogueId = 80090437,
          DisableMouth = 1,
