        [80100102] = {
          ContentEN = "You should know even the most passionate heart cannot burn forever. Indifference will extinguish those flames, leaving it hard and cold.",
          DialogueId = 80100102,
          GUID = "C885AEFC",
          NextOptions = {
            [1] = 801001021,
            [2] = 801001022
          },
          SpeakNpcId = 92101,
          Subtitle = "You should know even the most passionate heart cannot burn forever. Indifference will extinguish those flames, leaving it hard and cold.",
          TalkActionId = {
            [1] = "92101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885AEFC"
        },
        [80100103] = {
          ContentEN = "You left me out in the cold. Fate is so cruel for giving me a romance that begins with the coldest of shoulders.",
          DialogueId = 80100103,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885AF26",
          NextOptions = {
