          SpeakNpcId = 92101,
          Subtitle = "You left me out in the cold. Fate is so cruel for giving me a romance that begins with the coldest of shoulders.",
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885AF26"
        },
        [80100104] = {
          ContentEN = "*sigh* Never thought your words could be even colder than your actions. Are you truly blind to the romance that is about to blossom?",
          DialogueId = 80100104,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885AF50",
          NextOptions = {
