          },
          SpeakNpcId = 92101,
          Subtitle = "Another occasion of us alone. It's rare that someone hasn't fled screaming in terror after discovering that side of me.",
          TalkActionId = {
            [1] = "92101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885BF3A"
        },
        [80100202] = {
          ContentEN = "You must have sensed it already.",
          DialogueId = 80100202,
          GUID = "C885BF64",
          NextDialogue = 80100203,
          SpeakNpcId = 92101,
          Subtitle = "You must have sensed it already.",
          TalkActionId = {
            [1] = "92101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885BF64"
        },
        [80100203] = {
          ContentEN = "Stretch out your arms and take a look. Aww, such clean and lovely arms. Though callused and scarred, they remain pure and immaculate. And when tired, they only weep with salty sweat—",
          DialogueId = 80100203,
          FacialId = {
            [1] = "92101:Happy01"
          },
          GUID = "C885BF8E",
          NextDialogue = 80100204,
          SpeakNpcId = 92101,
          Subtitle = "Stretch out your arms and take a look. Aww, such clean and lovely arms. Though callused and scarred, they remain pure and immaculate. And when tired, they only weep with salty sweat—",
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885BF8E"
        },
        [80100204] = {
          ContentEN = "They differ from mine, which solely exude and bleed deadly venom.",
          DialogueId = 80100204,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885BFB8",
          NextDialogue = 80100205,
          SpeakNpcId = 92101,
          Subtitle = "They differ from mine, which solely exude and bleed deadly venom.",
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885BFB8"
        },
        [80100205] = {
          ContentEN = "The uncontrollable venom is like a wild old friend of mine. I rely on it to ward off Filthoids pouncing on me in forest trails or to send pursuing soldiers to an eternal sleep.",
          DialogueId = 80100205,
          FacialId = {
            [1] = "92101:Sad01"
          },
          GUID = "C885BFE2",
          NextDialogue = 80100206,
          SpeakNpcId = 92101,
          Subtitle = "The uncontrollable venom is like a wild old friend of mine. I rely on it to ward off Filthoids pouncing on me in forest trails or to send pursuing soldiers to an eternal sleep.",
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885BFE2"
        },
        [80100206] = {
          ContentEN = "But the venom is the vile and vicious repellant of anything and anyone that I wish to get closer to. Merely washing my face in a pond paralyses and suffocates any fish that tries to give me a friendly peck.",
          DialogueId = 80100206,
          GUID = "C885C00C",
          NextDialogue = 80100207,
          SpeakNpcId = 92101,
          Subtitle = "But the venom is the vile and vicious repellant of anything and anyone that I wish to get closer to. Merely washing my face in a pond paralyses and suffocates any fish that tries to give me a friendly peck.",
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C00C"
        },
        [80100207] = {
          ContentEN = "I once detested it. If not for my venom, I would be like many other girls of my age. I would be picking out my favorite clothes at the market, or stealing a glance at my crush.",
          DialogueId = 80100207,
          FacialId = {
            [1] = "92101:Iyada01"
          },
          GUID = "C885C036",
          NextOptions = {
            [1] = 801002071,
            [2] = 801002072
          },
          SpeakNpcId = 92101,
          Subtitle = "I once detested it. If not for my venom, I would be like many other girls of my age. I would be picking out my favorite clothes at the market, or stealing a glance at my crush.",
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C036"
        },
        [80100208] = {
          ContentEN = "They're not dreams. Just occasional notions that never linger. I laugh at myself for having had those thoughts.",
          DialogueId = 80100208,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885C060",
          NextDialogue = 80100210,
          SpeakNpcId = 92101,
          Subtitle = "They're not dreams. Just occasional notions that never linger. I laugh at myself for having had those thoughts.",
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C060"
        },
        [80100209] = {
          ContentEN = "Not exactly. It's more like I've subdued the venom. I found a more fitting way to coexist with it.",
          DialogueId = 80100209,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885C08A",
          NextDialogue = 80100210,
          SpeakNpcId = 92101,
          Subtitle = "Not exactly. It's more like I've subdued the venom. I found a more fitting way to coexist with it.",
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C08A"
        },
        [80100210] = {
          ContentEN = "Now, I no longer peep at someone I like, nor waste time on hours of useless talk to test their sincerity. A moment of sweet embrace is all I need to determine if this one is suited for a long-term commitment with me.",
          DialogueId = 80100210,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885C0B4",
          NextDialogue = 80100211,
          SpeakNpcId = 92101,
          Subtitle = "Now, I no longer peep at someone I like, nor waste time on hours of useless talk to test their sincerity. A moment of sweet embrace is all I need to determine if this one is suited for a long-term commitment with me.",
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C0B4"
        },
        [80100211] = {
          ContentEN = "The venom serves as my most valuable touchstone. If I meet someone capable of withstanding my embrace, I would immediately know that I've met the destined one.",
          DialogueId = 80100211,
          GUID = "C885C0DE",
          NextDialogue = 80100212,
          SpeakNpcId = 92101,
          Subtitle = "The venom serves as my most valuable touchstone. If I meet someone capable of withstanding my embrace, I would immediately know that I've met the destined one.",
          TalkActionId = {
            [1] = "92101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C0DE"
        },
        [80100212] = {
          ContentEN = "It's just that this person has yet to appear — perhaps they never will. But don't you find this far more romantic than the inane love talks between worldly people?",
          DialogueId = 80100212,
          FacialId = {
            [1] = "92101:Iyada01"
          },
          GUID = "C885C108",
          NextDialogue = 80100213,
          SpeakNpcId = 92101,
          Subtitle = "It's just that this person has yet to appear — perhaps they never will. But don't you find this far more romantic than the inane love talks between worldly people?",
          TalkActionId = {
            [1] = "92101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C108"
        },
        [80100213] = {
          ContentEN = "At least for me, it's a gift. Those who fear me, intimidate me, care for me, or obey me are all subject to this fair and equal trial.",
          DialogueId = 80100213,
          GUID = "C885C132",
          NextDialogue = 80100214,
          SpeakNpcId = 92101,
          Subtitle = "At least for me, it's a gift. Those who fear me, intimidate me, care for me, or obey me are all subject to this fair and equal trial.",
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C132"
        },
        [80100214] = {
          ContentEN = "Although I remain the same as I was and my wanderings continue, I no longer envy others, because my unique venom will help me find the special love that will be wholly mine.",
          DialogueId = 80100214,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885C15C",
          NextDialogue = 80100215,
          SpeakNpcId = 92101,
          Subtitle = "Although I remain the same as I was and my wanderings continue, I no longer envy others, because my unique venom will help me find the special love that will be wholly mine.",
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C15C"
        },
        [80100215] = {
          ContentEN = "Now, I intend to open my arms and ask you one question: Will you embrace me?",
          DialogueId = 80100215,
          GUID = "C885C186",
          NextOptions = {
            [1] = 801002151,
            [2] = 801002152
          },
          SpeakNpcId = 92101,
          Subtitle = "Now, I intend to open my arms and ask you one question: Will you embrace me?",
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C186"
        },
        [80100216] = {
          ContentEN = "Hehe, don't be scared. You're the first to hear me divulge this much about my past. You get only one chance, but perhaps you're indeed the one I've been searching for.",
          DialogueId = 80100216,
          FacialId = {
            [1] = "92101:Happy01"
          },
          GUID = "C885C1B0",
          NextDialogue = 80100218,
          SpeakNpcId = 92101,
          Subtitle = "Hehe, don't be scared. You're the first to hear me divulge this much about my past. You get only one chance, but perhaps you're indeed the one I've been searching for.",
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C1B0"
        },
        [80100217] = {
          ContentEN = "And then you'll pierce my throat with that sword in your hand, right? Hehe, don't be so on guard. I can feel it. We're kindred souls, you and me, fated to lead lives not shared by any other.",
          DialogueId = 80100217,
          FacialId = {
            [1] = "92101:Sad01"
          },
          GUID = "C885C1DA",
          NextDialogue = 80100218,
          SpeakNpcId = 92101,
          Subtitle = "And then you'll pierce my throat with that sword in your hand, right? Hehe, don't be so on guard. I can feel it. We're kindred souls, you and me, fated to lead lives not shared by any other.",
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C1DA"
        },
        [80100218] = {
