          DialogueId = 80100305,
          FacialId = {
            [1] = "92101:Happy01"
          },
          GUID = "C885D04A",
          NextDialogue = 80100306,
          SpeakNpcId = 92101,
          Subtitle = "That's right. See, we are so in sync with each other. Seems I've made the right choice in deciding to do this.",
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D04A"
        },
        [80100306] = {
          ContentEN = "I'm about to share a certain secret with you, which also means danger is approaching.",
          DialogueId = 80100306,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885D074",
          NextDialogue = 80100307,
          SpeakNpcId = 92101,
          Subtitle = "I'm about to share a certain secret with you, which also means danger is approaching.",
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D074"
        },
        [80100307] = {
          ContentEN = "I once met someone like me. She was born with fiery-red skin. Her temperament is the same, a blazing firebrand with little tolerance for the impure.",
          DialogueId = 80100307,
          FacialId = {
            [1] = "92101:Sad01"
          },
          GUID = "C885D09E",
          NextDialogue = 80100308,
          SpeakNpcId = 92101,
          Subtitle = "I once met someone like me. She was born with fiery-red skin. Her temperament is the same, a blazing firebrand with little tolerance for the impure.",
          TalkActionId = {
            [1] = "92101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D09E"
        },
        [80100308] = {
          ContentEN = "Unlike me, a monster despised and abandoned since childhood, she carries the legacy and hopes of her family, and ultimately becomes the righteous warden. No criminal she sets her sights on can ever escape her.",
          DialogueId = 80100308,
          GUID = "C885D0C8",
          NextDialogue = 80100309,
          SpeakNpcId = 92101,
          Subtitle = "Unlike me, a monster despised and abandoned since childhood, she carries the legacy and hopes of her family, and ultimately becomes the righteous warden. No criminal she sets her sights on can ever escape her.",
          TalkActionId = {
            [1] = "92101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D0C8"
        },
        [80100309] = {
          ContentEN = "However, like my venom, her flames tend to drive away or scare off anyone who tries to approach, be it with good or ill intent.",
          DialogueId = 80100309,
          GUID = "C885D0F2",
          NextOptions = {
            [1] = 801003091
          },
          SpeakNpcId = 92101,
          Subtitle = "However, like my venom, her flames tend to drive away or scare off anyone who tries to approach, be it with good or ill intent.",
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D0F2"
        },
        [80100310] = {
          ContentEN = "Yes. You know, a monster like me, who's born with lethal venom, can't help but leave a few bodies behind, whether by accident or willful intent. It shouldn't surprise you that I'm wanted.",
          DialogueId = 80100310,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885D11C",
          NextDialogue = 80100311,
          SpeakNpcId = 92101,
          Subtitle = "Yes. You know, a monster like me, who's born with lethal venom, can't help but leave a few bodies behind, whether by accident or willful intent. It shouldn't surprise you that I'm wanted.",
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D11C"
        },
        [80100311] = {
          ContentEN = "During her long and persistent chase, I realised something — she's just like me, we're both lonely monsters. So, I took advantage of this.",
          DialogueId = 80100311,
          GUID = "C885D146",
          NextDialogue = 80100312,
          SpeakNpcId = 92101,
          Subtitle = "During her long and persistent chase, I realised something — she's just like me, we're both lonely monsters. So, I took advantage of this.",
          TalkActionId = {
            [1] = "92101:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D146"
        },
        [80100312] = {
          ContentEN = "I offered a seemingly sincere confession to confuse her, making her realise that she wasn't the only freak in this vast land and think that her pity and clemency would get me back on track.",
          DialogueId = 80100312,
          GUID = "C885D170",
          NextDialogue = 80100313,
          SpeakNpcId = 92101,
          Subtitle = "I offered a seemingly sincere confession to confuse her, making her realise that she wasn't the only freak in this vast land and think that her pity and clemency would get me back on track.",
          TalkActionId = {
            [1] = "92101:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D170"
        },
        [80100313] = {
          ContentEN = "But then, I just ran away right after she destroyed the evidence of my crimes.",
          DialogueId = 80100313,
          GUID = "C885D19A",
          LookAt = {
            [1] = "92101:p(18000P2)"
          },
          NextDialogue = 80100314,
          SpeakNpcId = 92101,
          Subtitle = "But then, I just ran away right after she destroyed the evidence of my crimes.",
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D19A"
        },
        [80100314] = {
          ContentEN = "You can hardly imagine how furious she became, how her fires burnt as she gnashed her teeth and swore to throw me in prison. However, you should know that by granting me refuge, you will be seen as an accomplice.",
          DialogueId = 80100314,
          FacialId = {
            [1] = "92101:Iyada01"
          },
          GUID = "C885D1C4",
          LookAt = {
            [1] = "92101:p(18000P1)"
          },
          NextOptions = {
            [1] = 801003141,
            [2] = 801003142
          },
          SpeakNpcId = 92101,
          Subtitle = "You can hardly imagine how furious she became, how her fires burnt as she gnashed her teeth and swore to throw me in prison. However, you should know that by granting me refuge, you will be seen as an accomplice.",
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D1C4"
        },
        [80100315] = {
          ContentEN = "Is that so? Now I understand why I always feel an intoxicating aura of danger whenever I see you.",
          DialogueId = 80100315,
          FacialId = {
            [1] = "92101:Shock01"
          },
          GUID = "C885D1EE",
          NextDialogue = 80100316,
          SpeakNpcId = 92101,
          Subtitle = "Is that so? Now I understand why I always feel an intoxicating aura of danger whenever I see you.",
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D1EE"
        },
        [80100316] = {
          ContentEN = "Since you showed no sign of displeasure or rejection after I told you about a potential threat, does that mean we're growing closer?",
          DialogueId = 80100316,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885D218",
          NextDialogue = 80100317,
          SpeakNpcId = 92101,
          Subtitle = "Since you showed no sign of displeasure or rejection after I told you about a potential threat, does that mean we're growing closer?",
          TalkActionId = {
            [1] = "92101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D218"
        },
        [80100317] = {
          ContentEN = "I confess that I did struggle a bit when I was deciding if I should tell you about my dangerous past. I was worried that I would end up wandering this world on my own again.",
          DialogueId = 80100317,
          GUID = "C885D242",
          NextDialogue = 80100318,
          SpeakNpcId = 92101,
          Subtitle = "I confess that I did struggle a bit when I was deciding if I should tell you about my dangerous past. I was worried that I would end up wandering this world on my own again.",
          TalkActionId = {
            [1] = "92101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D242"
        },
        [80100318] = {
          ContentEN = "But I cannot bear to see you menaced by other threats. My venom alone is dangerous enough as it is.",
          DialogueId = 80100318,
          FacialId = {
            [1] = "92101:Sad01"
          },
          GUID = "C885D26C",
          NextDialogue = 80100319,
          SpeakNpcId = 92101,
          Subtitle = "But I cannot bear to see you menaced by other threats. My venom alone is dangerous enough as it is.",
          TalkActionId = {
