          SpeakNpcId = 92101,
          Subtitle = "You are so cute, weird, and interesting that I just can't get enough of...",
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D368"
        },
        [80100325] = {
          ContentEN = "I really want to embrace you with my venom now... But I'm 100% serious when it comes to love.",
          DialogueId = 80100325,
