        },
        [80110202] = {
          ContentEN = "Hey, how do you usually pick up your gigs? Still at The Asphodel?",
          DialogueId = 80110202,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C2804",
          NextOptions = {
            [1] = 801102021
          },
          SpeakNpcId = 93101,
          Subtitle = "Hey, how do you usually pick up your gigs? Still at The Asphodel?",
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2804"
        },
        [80110203] = {
          ContentEN = "Hmm, just like old times. The Asphodel is a neat place... At least Camilla doesn't suddenly throw in jobs where you have to kill people and rob their stuff.",
          DialogueId = 80110203,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C282E",
          NextOptions = {
            [1] = 801102031
          },
          SpeakNpcId = 93101,
          Subtitle = "Hmm, just like old times. The Asphodel is a neat place... At least Camilla doesn't suddenly throw in jobs where you have to kill people and rob their stuff.",
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C282E"
        },
        [80110204] = {
          ContentEN = "Hah, never underestimate Icelake. It's teeming with tougher nuts than the capital, especially with the Security Bureau ignoring the outskirts. But don't worry — Camilla's gigs are clean, unless you're dabbling in the sketchy ones.",
          DialogueId = 80110204,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C2858",
          NextDialogue = 80110205,
          SpeakNpcId = 93101,
          Subtitle = "Hah, never underestimate Icelake. It's teeming with tougher nuts than the capital, especially with the Security Bureau ignoring the outskirts. But don't worry — Camilla's gigs are clean, unless you're dabbling in the sketchy ones.",
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2858"
        },
        [80110205] = {
          ContentEN = "Speaking of which, how is Camilla these days? Still got that edge?",
          DialogueId = 80110205,
          GUID = "C88C2882",
          NextOptions = {
            [1] = 801102051,
            [2] = 801102052
          },
          SpeakNpcId = 93101,
          Subtitle = "Speaking of which, how is Camilla these days? Still got that edge?",
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2882"
        },
        [80110206] = {
          ContentEN = "That's good to hear! Ugh, time flies, even turned Camilla sweet, but it still couldn't soften up my iron-fisted supreme officer.",
          DialogueId = 80110206,
          FacialId = {
            [1] = "93101:Happy01"
          },
          GUID = "C88C28AC",
          NextOptions = {
            [1] = 801102071
          },
          SpeakNpcId = 93101,
          Subtitle = "That's good to hear! Ugh, time flies, even turned Camilla sweet, but it still couldn't soften up my iron-fisted supreme officer.",
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C28AC"
        },
        [80110207] = {
          ContentEN = "Okay, so Camilla hasn't changed at all... Ugh, she's just like my supreme officer — pretty but goes around acting like a pissed volcano.",
          DialogueId = 80110207,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C28D6",
          NextOptions = {
            [1] = 801102071
          },
          SpeakNpcId = 93101,
          Subtitle = "Okay, so Camilla hasn't changed at all... Ugh, she's just like my supreme officer — pretty but goes around acting like a pissed volcano.",
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C28D6"
        },
        [80110208] = {
          ContentEN = "Her name is... Sorry, can't tell you. I'd rather not end up on the electric fence getting zapped to ashes.",
          DialogueId = 80110208,
          GUID = "C88C2900",
          NextDialogue = 80110209,
          SpeakNpcId = 93101,
          Subtitle = "Her name is... Sorry, can't tell you. I'd rather not end up on the electric fence getting zapped to ashes.",
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2900"
        },
        [80110209] = {
          ContentEN = "She's always got this long face like the entire Legion owes her money or something.",
          DialogueId = 80110209,
          FacialId = {
            [1] = "93101:Sad02"
          },
          GUID = "C88C292A",
          NextOptions = {
            [1] = 801102091
          },
          SpeakNpcId = 93101,
          Subtitle = "She's always got this long face like the entire Legion owes her money or something.",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C292A"
        },
        [80110210] = {
          ContentEN = "Ugh, and her quirks! Like, who doesn't use a gun these days? But she insists on using her electrified whip and claims it works better.",
          DialogueId = 80110210,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C2954",
          NextDialogue = 80110211,
          SpeakNpcId = 93101,
          Subtitle = "Ugh, and her quirks! Like, who doesn't use a gun these days? But she insists on using her electrified whip and claims it works better.",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2954"
        },
        [80110211] = {
          ContentEN = "(Your heart skipped a beat. Her descriptions reminded you of someone you're looking for — Sibylle.)",
          DialogueId = 80110211,
          GUID = "C88C297E",
          NextDialogue = 80110212,
          Subtitle = "(Your heart skipped a beat. Her descriptions reminded you of someone you're looking for — Sibylle.)",
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C297E"
        },
        [80110212] = {
          ContentEN = "And people usually prefer peace and quiet when they have something to think about, right? Not her — she always blasts a loud recording and says it pumps her up and helps her think better.",
          DialogueId = 80110212,
          GUID = "C88C29A8",
          NextDialogue = 80110213,
          SpeakNpcId = 93101,
          Subtitle = "And people usually prefer peace and quiet when they have something to think about, right? Not her — she always blasts a loud recording and says it pumps her up and helps her think better.",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C29A8"
        },
        [80110213] = {
          ContentEN = "She even keeps crows in her office. Hasn't she ever worried about bird droppings on her reports to His M—um, her higher-ups?",
          DialogueId = 80110213,
          GUID = "C88C29D2",
          NextDialogue = 80110214,
          SpeakNpcId = 93101,
          Subtitle = "She even keeps crows in her office. Hasn't she ever worried about bird droppings on her reports to His M—um, her higher-ups?",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C29D2"
        },
        [80110214] = {
          ContentEN = "And then there's this: normal people go to the riverside to unwind and enjoy the breeze and scenery, right? My boss? She goes there only to watch anglers come back empty-handed, says it's funny and stress-relieving.",
          DialogueId = 80110214,
          GUID = "C88C29FC",
          NextDialogue = 80110215,
          SpeakNpcId = 93101,
          Subtitle = "And then there's this: normal people go to the riverside to unwind and enjoy the breeze and scenery, right? My boss? She goes there only to watch anglers come back empty-handed, says it's funny and stress-relieving.",
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C29FC"
        },
        [80110215] = {
          ContentEN = "I mean — who does that!?",
          DialogueId = 80110215,
          GUID = "C88C2A26",
          NextOptions = {
            [1] = 801102151
          },
          SpeakNpcId = 93101,
          Subtitle = "I mean — who does that!?",
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2A26"
        },
        [80110216] = {
          ContentEN = "She's nuts. Trust me, she's far less interesting in person. Oh, and that's just the top boss. My direct superior? Even nuttier.",
          DialogueId = 80110216,
          FacialId = {
            [1] = "93101:Sad02"
          },
          GUID = "C88C2A50",
          NextDialogue = 80110217,
          SpeakNpcId = 93101,
          Subtitle = "She's nuts. Trust me, she's far less interesting in person. Oh, and that's just the top boss. My direct superior? Even nuttier.",
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2A50"
        },
        [80110217] = {
          ContentEN = "Now this dude rambles in circles and thinks he's all classy. Honestly? He sounds like a wishy-washy wet goose.",
          DialogueId = 80110217,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C2A7A",
          NextDialogue = 80110218,
          SpeakNpcId = 93101,
          Subtitle = "Now this dude rambles in circles and thinks he's all classy. Honestly? He sounds like a wishy-washy wet goose.",
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2A7A"
        },
        [80110218] = {
          ContentEN = "That guy's always babbling about efficiency and energy saving. Ugh, everyone knows that he's just making excuses for his laziness.",
          DialogueId = 80110218,
          GUID = "C88C2AA4",
          NextDialogue = 80110219,
          SpeakNpcId = 93101,
          Subtitle = "That guy's always babbling about efficiency and energy saving. Ugh, everyone knows that he's just making excuses for his laziness.",
          TalkActionId = {
            [1] = "93101:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2AA4"
        },
        [80110219] = {
          ContentEN = "But I'll give him this — he's sharp. Slacks off, sure, but somehow still manages to get the job done. No one can really fault him for that.",
          DialogueId = 80110219,
          GUID = "C88C2ACE",
          NextDialogue = 80110220,
          SpeakNpcId = 93101,
          Subtitle = "But I'll give him this — he's sharp. Slacks off, sure, but somehow still manages to get the job done. No one can really fault him for that.",
          TalkActionId = {
            [1] = "93101:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2ACE"
        },
        [80110220] = {
          ContentEN = "Not long ago, he cracked the location of treasure with just a few clues. That's something my supreme officer had been chasing for years. But, well, there was... a little hiccup.",
          DialogueId = 80110220,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C2AF8",
          NextDialogue = 80110221,
          SpeakNpcId = 93101,
          Subtitle = "Not long ago, he cracked the location of treasure with just a few clues. That's something my supreme officer had been chasing for years. But, well, there was... a little hiccup.",
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2AF8"
        },
        [80110221] = {
