        },
        [80110301] = {
          Camera = "127.060242,12.009277,131.847168,0.0,-0.799959,-137.39563,30.0,150.0,false,Manual,2.8",
          ContentEN = "Hey, do me a favor. I'll pay you.",
          DialogueId = 80110301,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C3842",
          LookAt = {
            [1] = "93101:p(18000P3)"
          },
          NextDialogue = 80110302,
          SpeakNpcId = 93101,
          Subtitle = "Hey, do me a favor. I'll pay you.",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3842"
        },
        [80110302] = {
          ContentEN = "I'm off to the capital tomorrow and I've got a package here that needs to be delivered to No. 48, Oak Street in the west suburbs. It's for a lady named Riola Baker.",
          DialogueId = 80110302,
          GUID = "C88C386C",
          NextOptions = {
            [1] = 801103021
          },
          SpeakNpcId = 93101,
          Subtitle = "I'm off to the capital tomorrow and I've got a package here that needs to be delivered to No. 48, Oak Street in the west suburbs. It's for a lady named Riola Baker.",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C386C"
        },
        [80110303] = {
          ContentEN = "You're asking too many questions.",
          DialogueId = 80110303,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C3896",
          NextOptions = {
            [1] = 801103031,
            [2] = 801103032
          },
          SpeakNpcId = 93101,
          Subtitle = "You're asking too many questions.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3896"
        },
        [80110304] = {
          ContentEN = "Fair point. Alright, I'll spill it. There's a gun and a mask in there.",
          DialogueId = 80110304,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C38C0",
          NextDialogue = 80110305,
          SpeakNpcId = 93101,
          Subtitle = "Fair point. Alright, I'll spill it. There's a gun and a mask in there.",
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C38C0"
        },
        [80110305] = {
          ContentEN = "Don't be nervous. It's just a toy gun. If you don't believe me, feel free to test it on me.",
          DialogueId = 80110305,
          FacialId = {
            [1] = "93101:Iyada01"
          },
          GUID = "C88C38EA",
          NextOptions = {
            [1] = 801103051
          },
          SpeakNpcId = 93101,
          Subtitle = "Don't be nervous. It's just a toy gun. If you don't believe me, feel free to test it on me.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C38EA"
        },
        [80110306] = {
          ContentEN = "(BANG—)",
          DialogueId = 80110306,
          GUID = "C88C3914",
          NextDialogue = 80110307,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_toysshot\"},PlayAs2D{true}}",
          Subtitle = "(BANG—)",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3914"
        },
        [80110307] = {
          ContentEN = "Ow! Fake bullets hurt too! And why aim at the head!? Get over here, I'm gonna give you a thrashing! D**n, that friggin' hurt.",
          DialogueId = 80110307,
          FacialId = {
            [1] = "93101:Sad01"
          },
          GUID = "C88C393E",
          NextDialogue = 80110308,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_toysshot\"},PlayAs2D{true}}",
          SpeakNpcId = 93101,
          Subtitle = "Ow! Fake bullets hurt too! And why aim at the head!? Get over here, I'm gonna give you a thrashing! D**n, that friggin' hurt.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C393E"
        },
        [80110308] = {
          ContentEN = "*sigh* You know what, this reminds me of the fights I used to have with Riola when we were little. We'd use slingshots to hit each other in the head. Lucky I'm still alive, huh? Anyway, this gun... is my present for her.",
          DialogueId = 80110308,
          GUID = "C88C3968",
          NextOptions = {
            [1] = 801103081
          },
          SpeakNpcId = 93101,
          Subtitle = "*sigh* You know what, this reminds me of the fights I used to have with Riola when we were little. We'd use slingshots to hit each other in the head. Lucky I'm still alive, huh? Anyway, this gun... is my present for her.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3968"
        },
        [80110309] = {
          ContentEN = "Yeah, sort of... Had to come to Icelake for a mission, figured I might as well bring something.",
          DialogueId = 80110309,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C3992",
          NextDialogue = 80110310,
          SpeakNpcId = 93101,
          Subtitle = "Yeah, sort of... Had to come to Icelake for a mission, figured I might as well bring something.",
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3992"
        },
        [80110310] = {
          ContentEN = "And you've had way too many questions. Look, are you in or out? There's no shortage of Phoxhunters for the job, you know.",
          DialogueId = 80110310,
          GUID = "C88C39BC",
          NextOptions = {
            [1] = 801103101
          },
          SpeakNpcId = 93101,
          Subtitle = "And you've had way too many questions. Look, are you in or out? There's no shortage of Phoxhunters for the job, you know.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C39BC"
        },
        [80110311] = {
          ContentEN = "Deliver it myself? Forget it. If it weren't for orders from the top, I wouldn't bother coming back to Icelake.",
          DialogueId = 80110311,
          FacialId = {
            [1] = "93101:Sad01"
          },
          GUID = "C88C39E6",
          NextOptions = {
            [1] = 801103111,
            [2] = 801103112
          },
          SpeakNpcId = 93101,
          Subtitle = "Deliver it myself? Forget it. If it weren't for orders from the top, I wouldn't bother coming back to Icelake.",
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C39E6"
        },
        [80110312] = {
          ContentEN = "Tsk, cut it out.",
          DialogueId = 80110312,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C3A10",
          NextDialogue = 80110313,
          SpeakNpcId = 93101,
          Subtitle = "Tsk, cut it out.",
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3A10"
        },
        [80110313] = {
          ContentEN = "I did come back here before and had plans to catch up with the old gang. We used to climb trees and swipe veg together as kids. I wanted to chat with them, laugh about those silly pranks over a pint or two, and forget about life in the Legion for a while.",
          DialogueId = 80110313,
          GUID = "C88C3A3A",
          NextDialogue = 80110314,
          SpeakNpcId = 93101,
          Subtitle = "I did come back here before and had plans to catch up with the old gang. We used to climb trees and swipe veg together as kids. I wanted to chat with them, laugh about those silly pranks over a pint or two, and forget about life in the Legion for a while.",
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3A3A"
        },
        [80110314] = {
          ContentEN = "But word got out I was coming. They all lined up, saluted from a distance, yelling \"Officer Lynn\" so loud it scared the birds off the roofs.",
          DialogueId = 80110314,
          GUID = "C88C3A64",
          NextDialogue = 80110315,
          SpeakNpcId = 93101,
          Subtitle = "But word got out I was coming. They all lined up, saluted from a distance, yelling \"Officer Lynn\" so loud it scared the birds off the roofs.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3A64"
        },
        [80110315] = {
          ContentEN = "I thought I'd let them do their thing. Get it out of their system. Then we'd all loosen up a bit reminiscing about tearing down the streets as kids.",
          DialogueId = 80110315,
          GUID = "C88C3A8E",
          NextDialogue = 80110316,
          SpeakNpcId = 93101,
          Subtitle = "I thought I'd let them do their thing. Get it out of their system. Then we'd all loosen up a bit reminiscing about tearing down the streets as kids.",
          TalkActionId = {
            [1] = "93101:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3A8E"
        },
        [80110316] = {
          ContentEN = "But the old gang never gave me the chance. Everyone was too busy saluting, bowing like they owed me something. Couldn't even look me in the eye.",
          DialogueId = 80110316,
          GUID = "C88C3AB8",
          NextOptions = {
            [1] = 801103161
          },
          SpeakNpcId = 93101,
          Subtitle = "But the old gang never gave me the chance. Everyone was too busy saluting, bowing like they owed me something. Couldn't even look me in the eye.",
          TalkActionId = {
            [1] = "93101:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3AB8"
        },
        [80110317] = {
          ContentEN = "Of course it's normal. I've seen my fair share of things to know why they're so afraid of me. If it weren't for my joining the Legion, I'd be the one who trembles at the sight of soldiers.",
          DialogueId = 80110317,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C3AE2",
          NextDialogue = 80110318,
          SpeakNpcId = 93101,
          Subtitle = "Of course it's normal. I've seen my fair share of things to know why they're so afraid of me. If it weren't for my joining the Legion, I'd be the one who trembles at the sight of soldiers.",
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3AE2"
        },
        [80110318] = {
          ContentEN = "Icelake... No, it's the same for the whole of Hyperborea — the strong and rich walk all over the weak and poor... This has always been the way since I was a little girl. Nothing's changed.",
          DialogueId = 80110318,
          GUID = "C88C3B0C",
          NextDialogue = 80110319,
          SpeakNpcId = 93101,
          Subtitle = "Icelake... No, it's the same for the whole of Hyperborea — the strong and rich walk all over the weak and poor... This has always been the way since I was a little girl. Nothing's changed.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3B0C"
        },
        [80110319] = {
          ContentEN = "Anyway, do you know what the gun and mask are for?",
          DialogueId = 80110319,
          GUID = "C88C3B36",
          NextDialogue = 80110320,
          SpeakNpcId = 93101,
          Subtitle = "Anyway, do you know what the gun and mask are for?",
          TalkActionId = {
            [1] = "93101:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3B36"
        },
        [80110320] = {
          ContentEN = "When we were kids, Riola and I were obsessed with this comic about Leblanc, a rogue who'd steal from wicked rich folks and give to the poor. They called him the \"Masked Hero.\"",
          DialogueId = 80110320,
          GUID = "C88C3B60",
          NextDialogue = 80110321,
          SpeakNpcId = 93101,
          Subtitle = "When we were kids, Riola and I were obsessed with this comic about Leblanc, a rogue who'd steal from wicked rich folks and give to the poor. They called him the \"Masked Hero.\"",
          TalkActionId = {
            [1] = "93101:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3B60"
        },
        [80110321] = {
          ContentEN = "We made masks from scrap cardboard and used slingshots as our guns. We'd climb the town walls of Icelake, shouting Leblanc's lines from the comics. Silly, I know, but we didn't feel a bit embarrassed.",
          DialogueId = 80110321,
          FacialId = {
            [1] = "93101:Syouganai01"
          },
          GUID = "C88C3B8A",
          NextDialogue = 80110322,
          SpeakNpcId = 93101,
          Subtitle = "We made masks from scrap cardboard and used slingshots as our guns. We'd climb the town walls of Icelake, shouting Leblanc's lines from the comics. Silly, I know, but we didn't feel a bit embarrassed.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3B8A"
        },
        [80110322] = {
          ContentEN = "Those were the days when we felt we could... well... eventually become heroes ourselves.",
          DialogueId = 80110322,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C3BB4",
          NextDialogue = 80110323,
          SpeakNpcId = 93101,
          Subtitle = "Those were the days when we felt we could... well... eventually become heroes ourselves.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3BB4"
        },
        [80110323] = {
          ContentEN = "Years later, I spotted a beautifully crafted Leblanc mask and toy gun in a Dismania store. I couldn't resist, so I bought them.",
          DialogueId = 80110323,
          GUID = "C88C3BDE",
          NextDialogue = 80110324,
          SpeakNpcId = 93101,
          Subtitle = "Years later, I spotted a beautifully crafted Leblanc mask and toy gun in a Dismania store. I couldn't resist, so I bought them.",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3BDE"
        },
        [80110324] = {
          ContentEN = "Back then, I thought, \"I might have turned into a Charon-killing baddie, but at least Riola could still be a hero...\"",
          DialogueId = 80110324,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C3C08",
          NextDialogue = 80110325,
          SpeakNpcId = 93101,
          Subtitle = "Back then, I thought, \"I might have turned into a Charon-killing baddie, but at least Riola could still be a hero...\"",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3C08"
        },
        [80110325] = {
          ContentEN = "The last time I saw her in Icelake, she trembled like a scared goose and called me \"Officer Lynn.\" That's when I knew, we'd both changed. There's no going back to the good old days.",
          DialogueId = 80110325,
          GUID = "C88C3C32",
          NextDialogue = 80110326,
          SpeakNpcId = 93101,
          Subtitle = "The last time I saw her in Icelake, she trembled like a scared goose and called me \"Officer Lynn.\" That's when I knew, we'd both changed. There's no going back to the good old days.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3C32"
        },
        [80110326] = {
          ContentEN = "...Ugh, my head's hurting. Hit me with another!",
          DialogueId = 80110326,
          FacialId = {
            [1] = "93101:Syouganai01"
          },
          GUID = "C88C3C5C",
          NextDialogue = 80110327,
          SpeakNpcId = 93101,
          Subtitle = "...Ugh, my head's hurting. Hit me with another!",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3C5C"
        },
        [80110327] = {
          ContentEN = "These are the reasons why I avoid being back at Icelake. I don't even want to meet my own siblings. Just seeing them from afar, knowing they're alive and well, that's enough for me.",
          DialogueId = 80110327,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C3C86",
          NextOptions = {
            [1] = 801103271
          },
          SpeakNpcId = 93101,
          Subtitle = "These are the reasons why I avoid being back at Icelake. I don't even want to meet my own siblings. Just seeing them from afar, knowing they're alive and well, that's enough for me.",
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3C86"
        },
        [80110328] = {
          ContentEN = "No, quite the opposite. They write all the time, saying how much they miss me and wish I'd visit.",
          DialogueId = 80110328,
          FacialId = {
            [1] = "93101:Iyada01"
          },
          GUID = "C88C3CB0",
          NextDialogue = 80110329,
          SpeakNpcId = 93101,
          Subtitle = "No, quite the opposite. They write all the time, saying how much they miss me and wish I'd visit.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3CB0"
        },
        [80110329] = {
          ContentEN = "But what could I tell them? About the latest horrors I've seen at the Academy? Or how many Charon prisoners I took?",
          DialogueId = 80110329,
          GUID = "C88C3CDA",
          NextDialogue = 80110330,
          SpeakNpcId = 93101,
          Subtitle = "But what could I tell them? About the latest horrors I've seen at the Academy? Or how many Charon prisoners I took?",
          TalkActionId = {
            [1] = "93101:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3CDA"
        },
        [80110330] = {
          ContentEN = "...Forget it. Everyone's got their own burdens. It's all so damn normal these days.",
          DialogueId = 80110330,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C3D04",
          NextOptions = {
            [1] = 801103301
          },
          SpeakNpcId = 93101,
          Subtitle = "...Forget it. Everyone's got their own burdens. It's all so damn normal these days.",
          TalkActionId = {
            [1] = "93101:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3D04"
        },
        [80110331] = {
          ContentEN = "This should be a world where you can return home whenever you want... Perhaps our generation should try to make it one.",
          DialogueId = 80110331,
          GUID = "C88C3D2E",
          NextDialogue = 80110332,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          Subtitle = "This should be a world where you can return home whenever you want... Perhaps our generation should try to make it one.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3D2E"
        },
        [80110332] = {
          ContentEN = "Only outsiders like you would think this is weird and believe this can change.",
          DialogueId = 80110332,
          GUID = "C88C3D58",
          NextDialogue = 80110333,
          SpeakNpcId = 93101,
          Subtitle = "Only outsiders like you would think this is weird and believe this can change.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3D58"
        },
        [80110333] = {
          ContentEN = "Perhaps you also believe a day will come when Charons and Solas can live together in peace, and that people won't be judged for their strange-looking horns and spines, and the weird magic in their veins.",
          DialogueId = 80110333,
          GUID = "C88C3D82",
          NextDialogue = 80110334,
          SpeakNpcId = 93101,
          Subtitle = "Perhaps you also believe a day will come when Charons and Solas can live together in peace, and that people won't be judged for their strange-looking horns and spines, and the weird magic in their veins.",
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3D82"
        },
        [80110334] = {
          ContentEN = "That could happen.",
          DialogueId = 80110334,
          GUID = "C88C3DAC",
          NextDialogue = 80110335,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          Subtitle = "That could happen.",
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3DAC"
        },
        [80110335] = {
          ContentEN = "Even if you can't stop the snow in Icelake, you can at least shovel it away and make snowmen out of it, right?",
          DialogueId = 80110335,
          GUID = "C88C3DD6",
          NextDialogue = 80110336,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          Subtitle = "Even if you can't stop the snow in Icelake, you can at least shovel it away and make snowmen out of it, right?",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3DD6"
        },
        [80110336] = {
          ContentEN = "You can at least go to your friend and tell her you remember your childhood dreams, even if they're broken now. You should be able to knock on the door of your family home and tell your folks that you'll always miss them no matter who you've become. That part of you never changes.",
          DialogueId = 80110336,
          GUID = "C88C3E00",
          NextDialogue = 80110337,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          Subtitle = "You can at least go to your friend and tell her you remember your childhood dreams, even if they're broken now. You should be able to knock on the door of your family home and tell your folks that you'll always miss them no matter who you've become. That part of you never changes.",
          TalkActionId = {
            [1] = "93101:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3E00"
        },
        [80110337] = {
          ContentEN = "...Hah. To be honest, I like your way of thinking, even if it's a bit naive for my taste. It's way better than the usual crap like \"Oh, that's the way it is, nobody can change the world.\"",
          DialogueId = 80110337,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C3E2A",
          NextDialogue = 80110338,
          SpeakNpcId = 93101,
          Subtitle = "...Hah. To be honest, I like your way of thinking, even if it's a bit naive for my taste. It's way better than the usual crap like \"Oh, that's the way it is, nobody can change the world.\"",
          TalkActionId = {
            [1] = "93101:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3E2A"
        },
        [80110338] = {
          ContentEN = "And your words actually made this Icelake breeze a bit warmer, I must say. Hmm... Pour me another.",
          DialogueId = 80110338,
          FacialId = {
            [1] = "93101:Happy02"
          },
          GUID = "C88C3E54",
          NextDialogue = 80110339,
          SpeakNpcId = 93101,
          Subtitle = "And your words actually made this Icelake breeze a bit warmer, I must say. Hmm... Pour me another.",
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3E54"
        },
        [80110339] = {
          ContentEN = "Let's see how far you can take this dream of changing the world. I'm curious if a naive fool can actually make a difference, even a little.",
          DialogueId = 80110339,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C3E7E",
          NextDialogue = 80110340,
          SpeakNpcId = 93101,
          Subtitle = "Let's see how far you can take this dream of changing the world. I'm curious if a naive fool can actually make a difference, even a little.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3E7E"
        },
        [80110340] = {
          ContentEN = "And if you ever need help, and I'm free, just ask — as long as it's nothing against the Legion. But not today — I've just changed my mind about something and will be busy later.",
          DialogueId = 80110340,
          GUID = "C88C3EA8",
          NextDialogue = 80110341,
          SpeakNpcId = 93101,
          Subtitle = "And if you ever need help, and I'm free, just ask — as long as it's nothing against the Legion. But not today — I've just changed my mind about something and will be busy later.",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3EA8"
        },
        [80110341] = {
          ContentEN = "I'm cancelling the commission. Now, gimme back my mask and gun.",
          DialogueId = 80110341,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C3ED2",
          SpeakNpcId = 93101,
          Subtitle = "I'm cancelling the commission. Now, gimme back my mask and gun.",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3ED2"
        },
        [80120000] = {
          ContentEN = "Ahh, this is the life — a comfy chair, a drink, some snacks, a warm fireplace, and your company. All nice and cosy...",
          DialogueId = 80120000,
          GUID = "C8926F80",
          Subtitle = "Ahh, this is the life — a comfy chair, a drink, some snacks, a warm fireplace, and your company. All nice and cosy..."
        },
