          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A0E2"
        },
        [80120302] = {
          ContentEN = "Bitter and sweet at the same time... Ugh, this tastes like something my stupid old man would love! As for me, I think I'll need another ten... no, make that twenty years to appreciate this taste.",
          DialogueId = 80120302,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892A10C",
          NextOptions = {
            [1] = 801203021,
            [2] = 801203031
          },
          SpeakNpcId = 93301,
          Subtitle = "Bitter and sweet at the same time... Ugh, this tastes like something my stupid old man would love! As for me, I think I'll need another ten... no, make that twenty years to appreciate this taste.",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A10C"
        },
        [80120303] = {
          ContentEN = "I just don't get this drink! Why would anyone want to torture themselves with this bitter taste?",
          DialogueId = 80120303,
          FacialId = {
            [1] = "93301:Doubt01"
          },
          GUID = "C892A136",
          NextOptions = {
            [1] = 801203041
          },
          SpeakNpcId = 93301,
          Subtitle = "I just don't get this drink! Why would anyone want to torture themselves with this bitter taste?",
          TalkActionId = {
            [1] = "93301:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A136"
        },
        [80120304] = {
          ContentEN = "Exactly! Nothing beats a refreshing drink after a day's work — it's like a cool wave from head to toe!",
          DialogueId = 80120304,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892A160",
          NextOptions = {
