          NextDialogue = 80120404,
          Subtitle = "(Margie gulps down a full glass of water, then gingerly pulls something from her pocket and presents it to you — it's a clump of fur, somewhat familiar in colour.)",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B19E"
        },
        [80120404] = {
          ContentEN = "I found Plumpytail!",
          DialogueId = 80120404,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B1C8",
          NextOptions = {
            [1] = 801204041
          },
          SpeakNpcId = 93301,
          Subtitle = "I found Plumpytail!",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B1C8"
        },
        [80120405] = {
          ContentEN = "Plumpytail's the little cat I used to roam the snowfields with!",
          DialogueId = 80120405,
          FacialId = {
            [1] = "93301:Confident02"
          },
          GUID = "C892B1F2",
          NextDialogue = 80120406,
          SpeakNpcId = 93301,
          Subtitle = "Plumpytail's the little cat I used to roam the snowfields with!",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B1F2"
        },
        [80120406] = {
          ContentEN = "Then I came to Icelake, but she didn't want to come with me and stayed in the wilderness. I made a plushie that looks just like her to remember her!",
          DialogueId = 80120406,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B21C",
          NextDialogue = 80120407,
          SpeakNpcId = 93301,
          Subtitle = "Then I came to Icelake, but she didn't want to come with me and stayed in the wilderness. I made a plushie that looks just like her to remember her!",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B21C"
        },
        [80120407] = {
          ContentEN = "I was just going to check the bins near the city gates today, but instead, I stumbled upon this clump of fur! Look!",
          DialogueId = 80120407,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B246",
          NextDialogue = 80120408,
          SpeakNpcId = 93301,
          Subtitle = "I was just going to check the bins near the city gates today, but instead, I stumbled upon this clump of fur! Look!",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B246"
        },
        [80120408] = {
          ContentEN = "The greyish colour with black spots, the soft yet coarse feel, and the fact that it was even a bit damp when I found it... It's definitely Plumpytail! She came back for me!",
          DialogueId = 80120408,
          GUID = "C892B270",
          NextDialogue = 80120409,
          SpeakNpcId = 93301,
          Subtitle = "The greyish colour with black spots, the soft yet coarse feel, and the fact that it was even a bit damp when I found it... It's definitely Plumpytail! She came back for me!",
          TalkActionId = {
            [1] = "93301:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B270"
        },
        [80120409] = {
          ContentEN = "Back in the day, when Plumpytail and I played \"Tailing the Suspect,\" she would leave bits of furball from her grooming in different directions to throw me off. That was one of her signature tricks.",
          DialogueId = 80120409,
          GUID = "C892B29A",
          NextDialogue = 80120410,
          SpeakNpcId = 93301,
          Subtitle = "Back in the day, when Plumpytail and I played \"Tailing the Suspect,\" she would leave bits of furball from her grooming in different directions to throw me off. That was one of her signature tricks.",
          TalkActionId = {
            [1] = "93301:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B29A"
        },
        [80120410] = {
          ContentEN = "I was such a rookie detective back then, so I always walked straight into Plumpytail's traps. By the time I was worn out from running in circles, Plumpytail would prance around with her head held high, tail swaying like she was king of the world!",
          DialogueId = 80120410,
          FacialId = {
            [1] = "93301:Sad01"
          },
          GUID = "C892B2C4",
          NextDialogue = 80120411,
          SpeakNpcId = 93301,
          Subtitle = "I was such a rookie detective back then, so I always walked straight into Plumpytail's traps. By the time I was worn out from running in circles, Plumpytail would prance around with her head held high, tail swaying like she was king of the world!",
          TalkActionId = {
            [1] = "93301:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B2C4"
        },
        [80120411] = {
          ContentEN = "...It's all coming back to me — the irritation of being toyed with by the \"Suspect Cat,\" the frustration of losing the trail, the panic of getting lost in the snowfields, and the bafflement of holding a handful of wet fur!",
          DialogueId = 80120411,
          FacialId = {
            [1] = "93301:Shock01"
          },
          GUID = "C892B2EE",
          NextOptions = {
            [1] = 801204111
          },
          SpeakNpcId = 93301,
          Subtitle = "...It's all coming back to me — the irritation of being toyed with by the \"Suspect Cat,\" the frustration of losing the trail, the panic of getting lost in the snowfields, and the bafflement of holding a handful of wet fur!",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B2EE"
        },
        [80120412] = {
          ContentEN = "Hmph! Those days are long behind me! I'm no longer the rookie I once was! Plus, Icelake is my turf now, and this time, I'm definitely going to catch the \"Suspect Cat\"!",
          DialogueId = 80120412,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B318",
          NextDialogue = 80120413,
          SpeakNpcId = 93301,
          Subtitle = "Hmph! Those days are long behind me! I'm no longer the rookie I once was! Plus, Icelake is my turf now, and this time, I'm definitely going to catch the \"Suspect Cat\"!",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B318"
        },
        [80120413] = {
          ContentEN = "I've been mapping out the possible hiding spots based on the alley layouts and even bribed the local strays with fish treats. Anyone who can provide a lead on this outsider cat will be handsomely rewarded!",
          DialogueId = 80120413,
          FacialId = {
            [1] = "93301:Confident02"
          },
          GUID = "C892B342",
          NextOptions = {
            [1] = 801204131,
            [2] = 801204141
          },
          SpeakNpcId = 93301,
          Subtitle = "I've been mapping out the possible hiding spots based on the alley layouts and even bribed the local strays with fish treats. Anyone who can provide a lead on this outsider cat will be handsomely rewarded!",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B342"
        },
        [80120414] = {
          ContentEN = "Aha! Caught a white-furred big cat spreading false alarms! As punishment, no fish treats for half a month!",
          DialogueId = 80120414,
          FacialId = {
            [1] = "93301:Confident02"
          },
          GUID = "C892B36C",
          NextDialogue = 80120416,
          SpeakNpcId = 93301,
          Subtitle = "Aha! Caught a white-furred big cat spreading false alarms! As punishment, no fish treats for half a month!",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B36C"
        },
        [80120415] = {
          ContentEN = "Hehe, even if you flatter me like that... hehe, I won't let it go to my head, hehe!",
          DialogueId = 80120415,
          FacialId = {
            [1] = "93301:Happy02"
          },
          GUID = "C892B396",
          NextDialogue = 80120416,
          SpeakNpcId = 93301,
          Subtitle = "Hehe, even if you flatter me like that... hehe, I won't let it go to my head, hehe!",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B396"
        },
        [80120416] = {
          ContentEN = "Ahem, as I was saying... my detailed deductions finally led me to a narrow alley full of cardboard boxes — it's like an irresistible paradise for a cat used to living in the wild!",
          DialogueId = 80120416,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B3C0",
          NextDialogue = 80120417,
          SpeakNpcId = 93301,
          Subtitle = "Ahem, as I was saying... my detailed deductions finally led me to a narrow alley full of cardboard boxes — it's like an irresistible paradise for a cat used to living in the wild!",
          TalkActionId = {
            [1] = "93301:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B3C0"
        },
        [80120417] = {
          ContentEN = "And sure enough, there was the suspect, basking in the sun inside a cardboard box, casually flicking her tail at me as if she owned the place!",
          DialogueId = 80120417,
          FacialId = {
            [1] = "93301:Happy01"
          },
          GUID = "C892B3EA",
          NextDialogue = 80120418,
          SpeakNpcId = 93301,
          Subtitle = "And sure enough, there was the suspect, basking in the sun inside a cardboard box, casually flicking her tail at me as if she owned the place!",
          TalkActionId = {
            [1] = "93301:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B3EA"
        },
        [80120418] = {
          ContentEN = "It's been so long, yet Plumpytail was still the same Plumpytail I knew... No, actually, she seemed a bit different this time.",
          DialogueId = 80120418,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B414",
          NextDialogue = 80120419,
          Scripts = "PlayAnimation{_delay{2},ActorId{93301},AnimationId{\"Sit_DisagreeHead\"},Duration{1}}",
          SpeakNpcId = 93301,
          Subtitle = "It's been so long, yet Plumpytail was still the same Plumpytail I knew... No, actually, she seemed a bit different this time.",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B414"
        },
        [80120419] = {
          ContentEN = "When we last parted, Plumpytail had just grown up and didn't like being petted — one wrong move, and she'd vanish in a flash. But today, she seemed more mature, almost like an old cat.",
          DialogueId = 80120419,
          GUID = "C892B43E",
          NextDialogue = 80120420,
          SpeakNpcId = 93301,
          Subtitle = "When we last parted, Plumpytail had just grown up and didn't like being petted — one wrong move, and she'd vanish in a flash. But today, she seemed more mature, almost like an old cat.",
          TalkActionId = {
            [1] = "93301:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B43E"
        },
        [80120420] = {
          ContentEN = "Does \"mellow with age\" also apply to animals? Even without her favourite jerky, she let me pet her all over — belly rubs, paw squeezes, tail strokes and all.",
          DialogueId = 80120420,
          GUID = "C892B468",
          NextDialogue = 80120421,
          SpeakNpcId = 93301,
          Subtitle = "Does \"mellow with age\" also apply to animals? Even without her favourite jerky, she let me pet her all over — belly rubs, paw squeezes, tail strokes and all.",
          TalkActionId = {
            [1] = "93301:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B468"
        },
        [80120421] = {
          ContentEN = "This time, Plumpytail even brought a few kittens along. They're just as timid as Plumpytail used to be, peeking their little heads out from the box. But just from their fur, I could tell Plumpytail has been taking great care of them!",
          DialogueId = 80120421,
          GUID = "C892B492",
          NextDialogue = 80120422,
          Scripts = "SEQ{PlayAnimation{ActorId{93301},AnimationId{\"Sit_Talk01_Start\"},Duration{1}},PlayAnimation{_delay{2},ActorId{93301},AnimationId{\"Sit_Talk01_End\"},Duration{1}}}",
          SpeakNpcId = 93301,
          Subtitle = "This time, Plumpytail even brought a few kittens along. They're just as timid as Plumpytail used to be, peeking their little heads out from the box. But just from their fur, I could tell Plumpytail has been taking great care of them!",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B492"
        },
        [80120422] = {
          ContentEN = "It's amazing... that clumsy cat who couldn't even catch a snowfield rat is now providing for a whole litter of kittens of her own!",
          DialogueId = 80120422,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B4BC",
          NextOptions = {
            [1] = 801204221
          },
          SpeakNpcId = 93301,
          Subtitle = "It's amazing... that clumsy cat who couldn't even catch a snowfield rat is now providing for a whole litter of kittens of her own!",
          TalkActionId = {
            [1] = "93301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B4BC"
        },
        [80120423] = {
          ContentEN = "You're right... we've both grown since we first met. Hehe... it's kinda embarrassing to admit though...",
          DialogueId = 80120423,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B4E6",
          NextDialogue = 80120424,
          SpeakNpcId = 93301,
          Subtitle = "You're right... we've both grown since we first met. Hehe... it's kinda embarrassing to admit though...",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B4E6"
        },
        [80120424] = {
          ContentEN = "Actually, when I first came to Icelake, I was such a crybaby — hey, don't you dare make fun of me!",
          DialogueId = 80120424,
          GUID = "C892B510",
          NextDialogue = 80120425,
          Scripts = "LookAt{_delay{2},LookAtDescription{\"93301:p(18000P2)\"}}",
          SpeakNpcId = 93301,
          Subtitle = "Actually, when I first came to Icelake, I was such a crybaby — hey, don't you dare make fun of me!",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B510"
        },
        [80120425] = {
          ContentEN = "I thought about leaving Icelake more than once. I figured I could just pretend I'd never come and wander the world with Plumpytail, which seemed pretty great.",
          DialogueId = 80120425,
          FacialId = {
            [1] = "93301:Satisfy01"
          },
          GUID = "C892B53A",
          LookAt = {
            [1] = "93301:p(18000P3)"
          },
          NextOptions = {
            [1] = 801204251
          },
          SpeakNpcId = 93301,
          Subtitle = "I thought about leaving Icelake more than once. I figured I could just pretend I'd never come and wander the world with Plumpytail, which seemed pretty great.",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B53A"
        },
        [80120426] = {
          ContentEN = "Old Martin always said the city was a good place, so I believed it too. I imagined a \"city\" as a sanctuary where torch-bearing folks huddle together for warmth and protection.",
          DialogueId = 80120426,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B564",
          NextDialogue = 80120427,
          SpeakNpcId = 93301,
          Subtitle = "Old Martin always said the city was a good place, so I believed it too. I imagined a \"city\" as a sanctuary where torch-bearing folks huddle together for warmth and protection.",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B564"
        },
        [80120427] = {
          ContentEN = "But... Ugh! The things that go on in this \"sanctuary\" are just absurd. Charons are discriminated against for no reason; rich folks have more furs than they could wear in a lifetime, while the poor in the slums might not even survive the cold winter...",
          DialogueId = 80120427,
          FacialId = {
            [1] = "93301:Sad01"
          },
          GUID = "C892B58E",
          NextDialogue = 80120428,
          SpeakNpcId = 93301,
          Subtitle = "But... Ugh! The things that go on in this \"sanctuary\" are just absurd. Charons are discriminated against for no reason; rich folks have more furs than they could wear in a lifetime, while the poor in the slums might not even survive the cold winter...",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B58E"
        },
        [80120428] = {
          ContentEN = "And I just missed Plumpytail so much! I figured, every place has its good and bad, so why not just stick with my favourite cat?",
          DialogueId = 80120428,
          FacialId = {
            [1] = "93301:Satisfy01"
          },
          GUID = "C892B5B8",
          NextOptions = {
            [1] = 801204281,
            [2] = 801204291
          },
          SpeakNpcId = 93301,
          Subtitle = "And I just missed Plumpytail so much! I figured, every place has its good and bad, so why not just stick with my favourite cat?",
          TalkActionId = {
            [1] = "93301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B5B8"
        },
        [80120429] = {
          ContentEN = "Huh? He wouldn't... um, maybe... Anyway, I'm still here in Icelake, aren't I?",
          DialogueId = 80120429,
          FacialId = {
            [1] = "93301:Shock01"
          },
          GUID = "C892B5E2",
          NextDialogue = 80120431,
          Scripts = "PlayAnimation{_delay{1},ActorId{93301},AnimationId{\"Sit_DisagreeHead\"},Duration{1}}",
          SpeakNpcId = 93301,
          Subtitle = "Huh? He wouldn't... um, maybe... Anyway, I'm still here in Icelake, aren't I?",
          TalkActionId = {
            [1] = "93301:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B5E2"
        },
        [80120430] = {
          ContentEN = "Yeah, now that I think about it, I was just a kid trying to run away from problems.",
          DialogueId = 80120430,
          FacialId = {
            [1] = "93301:None"
          },
          GUID = "C892B60C",
          NextDialogue = 80120431,
          SpeakNpcId = 93301,
          Subtitle = "Yeah, now that I think about it, I was just a kid trying to run away from problems.",
          TalkActionId = {
            [1] = "93301:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B60C"
        },
        [80120431] = {
          ContentEN = "I actually did it once. One time, some Sola kids threw rocks at me, and I got so mad that I ran straight for the city gate. I just kept running, calling out for Plumpytail.",
          DialogueId = 80120431,
          FacialId = {
            [1] = "93301:Uninterested01"
          },
          GUID = "C892B636",
          NextDialogue = 80120432,
          SpeakNpcId = 93301,
          Subtitle = "I actually did it once. One time, some Sola kids threw rocks at me, and I got so mad that I ran straight for the city gate. I just kept running, calling out for Plumpytail.",
          TalkActionId = {
            [1] = "93301:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B636"
        },
        [80120432] = {
          ContentEN = "And then... I did run into Plumpytail. She was fighting a snow wolf over a silverback vole.",
          DialogueId = 80120432,
          FacialId = {
            [1] = "93301:None"
          },
          GUID = "C892B660",
          NextDialogue = 80120433,
          SpeakNpcId = 93301,
          Subtitle = "And then... I did run into Plumpytail. She was fighting a snow wolf over a silverback vole.",
          TalkActionId = {
            [1] = "93301:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B660"
        },
        [80120433] = {
          ContentEN = "I figured Plumpytail must've been starving, so I threw her a piece of jerky. But she didn't even look at it. Her eyes were fixed only on her prey and her enemy.",
          DialogueId = 80120433,
          GUID = "C892B68A",
          NextDialogue = 80120434,
          SpeakNpcId = 93301,
          Subtitle = "I figured Plumpytail must've been starving, so I threw her a piece of jerky. But she didn't even look at it. Her eyes were fixed only on her prey and her enemy.",
          TalkActionId = {
            [1] = "93301:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B68A"
        },
        [80120434] = {
          ContentEN = "In the end, Plumpytail won. She strutted over to me all proud-like, meowing — either showing off or maybe just happy to see me after so long.",
          DialogueId = 80120434,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B6B4",
          NextDialogue = 80120435,
          SpeakNpcId = 93301,
          Subtitle = "In the end, Plumpytail won. She strutted over to me all proud-like, meowing — either showing off or maybe just happy to see me after so long.",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B6B4"
        },
        [80120435] = {
          ContentEN = "I petted her fluffy head and said, \"Plumpytail, I'll go with you. Let's live together in the snowfields.\"",
          DialogueId = 80120435,
          FacialId = {
            [1] = "93301:Happy02"
          },
          GUID = "C892B6DE",
          NextDialogue = 80120436,
          SpeakNpcId = 93301,
          Subtitle = "I petted her fluffy head and said, \"Plumpytail, I'll go with you. Let's live together in the snowfields.\"",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B6DE"
        },
        [80120436] = {
          ContentEN = "But Plumpytail didn't take me to her home. She darted out of my arms and kept meowing in one direction — it was the direction of Icelake.",
          DialogueId = 80120436,
          FacialId = {
            [1] = "93301:Satisfy01"
          },
          GUID = "C892B708",
          NextDialogue = 80120437,
          SpeakNpcId = 93301,
          Subtitle = "But Plumpytail didn't take me to her home. She darted out of my arms and kept meowing in one direction — it was the direction of Icelake.",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B708"
        },
        [80120437] = {
          ContentEN = "I guess she was trying to tell me the snowfields weren't my home, and I belonged to Icelake.",
          DialogueId = 80120437,
          GUID = "C892B732",
          NextDialogue = 80120438,
          SpeakNpcId = 93301,
          Subtitle = "I guess she was trying to tell me the snowfields weren't my home, and I belonged to Icelake.",
          TalkActionId = {
            [1] = "93301:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B732"
        },
        [80120438] = {
          ContentEN = "That's when I realised... Even with me feeding her, Plumpytail would still try her best to hunt, because that was her way of living.",
          DialogueId = 80120438,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B75C",
          NextDialogue = 80120439,
          SpeakNpcId = 93301,
          Subtitle = "That's when I realised... Even with me feeding her, Plumpytail would still try her best to hunt, because that was her way of living.",
          TalkActionId = {
            [1] = "93301:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B75C"
        },
        [80120439] = {
          ContentEN = "And I had my way of living too, but I was too chicken to face my life in the city, always thinking of running back to Plumpytail — ugh, I was such a coward!",
          DialogueId = 80120439,
          FacialId = {
            [1] = "93301:None"
          },
          GUID = "C892B786",
          NextOptions = {
            [1] = 801204391,
            [2] = 801204401
          },
          Scripts = "LookAt{_delay{2},LookAtDescription{\"93301:p(18000P2)\"}}",
          SpeakNpcId = 93301,
          Subtitle = "And I had my way of living too, but I was too chicken to face my life in the city, always thinking of running back to Plumpytail — ugh, I was such a coward!",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B786"
        },
        [80120440] = {
