          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EBFA"
        },
        [80130122] = {
          ContentEN = "Word about you's even made it to Scarletriver. Bet an awesome Phoxhunter like you could use a little extra firepower.",
          DialogueId = 80130122,
          GUID = "C898EC24",
          NextDialogue = 80130123,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Word about you's even made it to Scarletriver. Bet an awesome Phoxhunter like you could use a little extra firepower.",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EC24"
        },
        [80130123] = {
          ContentEN = "If the name's too hard to remember, you can just call them Tot Poppers. That's what I call them... it helps throw off Empire soldiers... makes them think it's just some kid's toy, so they drop their guard.",
          DialogueId = 80130123,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898EC4E",
          NextDialogue = 80130124,
          SpeakNpcId = 93103,
          Subtitle = "If the name's too hard to remember, you can just call them Tot Poppers. That's what I call them... it helps throw off Empire soldiers... makes them think it's just some kid's toy, so they drop their guard.",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EC4E"
        },
        [80130124] = {
          ContentEN = "And the little drawings on the casings — they're also from me... This way the bombs look a bit less scary...",
          DialogueId = 80130124,
          GUID = "C898EC78",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextDialogue = 80130125,
          SpeakNpcId = 93103,
          Subtitle = "And the little drawings on the casings — they're also from me... This way the bombs look a bit less scary...",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EC78"
        },
        [80130125] = {
          ContentEN = "Ugh. How many times do I have to say it? People who buy bombs just want a good BOOM, not some cutesy nonsense.",
          DialogueId = 80130125,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C898ECA2",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130126,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Ugh. How many times do I have to say it? People who buy bombs just want a good BOOM, not some cutesy nonsense.",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898ECA2"
        },
        [80130126] = {
          ContentEN = "But I think the drawings make our products stand out. And when I was sketching them, you were the one shouting all those tips about how to make them even cuter...",
          DialogueId = 80130126,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898ECCC",
          NextDialogue = 80130127,
          SpeakNpcId = 93103,
          Subtitle = "But I think the drawings make our products stand out. And when I was sketching them, you were the one shouting all those tips about how to make them even cuter...",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898ECCC"
        },
        [80130127] = {
          ContentEN = "I... I only did that so you wouldn't botch it, all right? If the logo's ugly, no one's gonna buy them — duh!",
          DialogueId = 80130127,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C898ECF6",
          NextDialogue = 80130128,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "I... I only did that so you wouldn't botch it, all right? If the logo's ugly, no one's gonna buy them — duh!",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898ECF6"
        },
        [80130128] = {
          ContentEN = "Ahem. Anyway — that's our big sales pitch. If you'd like to place an order, just send us a note.",
          DialogueId = 80130128,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C898ED20",
          NextDialogue = 80130129,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Ahem. Anyway — that's our big sales pitch. If you'd like to place an order, just send us a note.",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898ED20"
        },
        [80130129] = {
          ContentEN = "But make sure you write Tot Poppers on your order, not Starshatterers. Otherwise... we'll both be in hot water.",
          DialogueId = 80130129,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C898ED4A",
          NextDialogue = 80130130,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "But make sure you write Tot Poppers on your order, not Starshatterers. Otherwise... we'll both be in hot water.",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898ED4A"
        },
        [80130130] = {
          ContentEN = "Our shop address is on the catalogue. We'll be waiting for your order...",
          DialogueId = 80130130,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898ED74",
          NextDialogue = 80130131,
          SpeakNpcId = 93103,
          Subtitle = "Our shop address is on the catalogue. We'll be waiting for your order...",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898ED74"
        },
        [80130131] = {
          ContentEN = "Yale and Oliver — the unforgettable duo from Scarletriver. If you ever have the chance, why not pick up a few of their creations? Those Kaboom Spinners and Whizpop Fireworks sound like an absolute blast...",
          DialogueId = 80130131,
          GUID = "C898ED9E",
          Subtitle = "Yale and Oliver — the unforgettable duo from Scarletriver. If you ever have the chance, why not pick up a few of their creations? Those Kaboom Spinners and Whizpop Fireworks sound like an absolute blast...",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898ED9E"
        },
        [80130201] = {
          Camera = "126.583923,7.386108,128.715088,0.0,-0.799959,-137.795624,30.0,150.0,false,Manual,2.8",
          ContentEN = "Hello...",
          DialogueId = 80130201,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898F91A",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130202,
          SpeakNpcId = 93103,
          Subtitle = "Hello...",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898F91A"
        },
        [80130202] = {
          ContentEN = "Do you remember me? I'm Yale, from Snap 'n' Spark...",
          DialogueId = 80130202,
          FacialId = {
            [1] = "93103:Ahaha02"
          },
          GUID = "C898F944",
          NextOptions = {
            [1] = 801302021,
            [2] = 801302022
          },
          SpeakNpcId = 93103,
          Subtitle = "Do you remember me? I'm Yale, from Snap 'n' Spark...",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898F944"
        },
        [80130203] = {
          ContentEN = "Th—That was because we barely knew each other then. It's better now.",
          DialogueId = 80130203,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898F96E",
          NextDialogue = 80130205,
          SpeakNpcId = 93103,
          Subtitle = "Th—That was because we barely knew each other then. It's better now.",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898F96E"
        },
        [80130204] = {
          ContentEN = "Mm... He's always been much better at talking than I am.",
          DialogueId = 80130204,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898F998",
          NextDialogue = 80130205,
          SpeakNpcId = 93103,
          Subtitle = "Mm... He's always been much better at talking than I am.",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898F998"
        },
        [80130205] = {
          ContentEN = "I came by myself today, though.",
          DialogueId = 80130205,
          FacialId = {
            [1] = "93103:Iyada01"
          },
          GUID = "C898F9C2",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextDialogue = 80130206,
          SpeakNpcId = 93103,
          Subtitle = "I came by myself today, though.",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898F9C2"
        },
        [80130206] = {
          ContentEN = "It's not that we had a fight or anything — Oliver and I get along just fine. Which... might be exactly why there are things I can't quite say to him.",
          DialogueId = 80130206,
          FacialId = {
            [1] = "93103:Sad01"
          },
          GUID = "C898F9EC",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130207,
          SpeakNpcId = 93103,
          Subtitle = "It's not that we had a fight or anything — Oliver and I get along just fine. Which... might be exactly why there are things I can't quite say to him.",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898F9EC"
        },
        [80130207] = {
          ContentEN = "So... I thought maybe... I could tell you instead. N—No pressure — I'm not here asking for advice. I... just need someone to listen. And... you seemed like a good listener.",
          DialogueId = 80130207,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898FA16",
          NextDialogue = 80130208,
          SpeakNpcId = 93103,
          Subtitle = "So... I thought maybe... I could tell you instead. N—No pressure — I'm not here asking for advice. I... just need someone to listen. And... you seemed like a good listener.",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FA16"
        },
        [80130208] = {
          ContentEN = "I never told you this, but Snap 'n' Spark wasn't ours to begin with. It belonged to a very, very grumpy old man.",
          DialogueId = 80130208,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898FA40",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextDialogue = 80130209,
          SpeakNpcId = 93103,
          Subtitle = "I never told you this, but Snap 'n' Spark wasn't ours to begin with. It belonged to a very, very grumpy old man.",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FA40"
        },
        [80130209] = {
          ContentEN = "He yelled a lot... always bossing me around. I messed up a lot of things at first... But after a while, even through all the shouting... I started to pick up how to run the place.",
          DialogueId = 80130209,
          FacialId = {
            [1] = "93103:Unhappy01"
          },
          GUID = "C898FA6A",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130210,
          SpeakNpcId = 93103,
          Subtitle = "He yelled a lot... always bossing me around. I messed up a lot of things at first... But after a while, even through all the shouting... I started to pick up how to run the place.",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FA6A"
        },
        [80130210] = {
          ContentEN = "Then one day he simply announced he was off somewhere far away — and left the place to me.",
          DialogueId = 80130210,
          FacialId = {
            [1] = "93103:Shock01"
          },
          GUID = "C898FA94",
          NextDialogue = 80130211,
          SpeakNpcId = 93103,
          Subtitle = "Then one day he simply announced he was off somewhere far away — and left the place to me.",
          TalkActionId = {
            [1] = "93103:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FA94"
        },
        [80130211] = {
          ContentEN = "After that, it was just me. Without him there... I didn't really know how to make new toys anymore. So I just kept selling whatever stock he'd left behind...",
          DialogueId = 80130211,
          FacialId = {
            [1] = "93103:Sad01"
          },
          GUID = "C898FABE",
          NextOptions = {
            [1] = 801302111,
            [2] = 801302112
          },
          SpeakNpcId = 93103,
          Subtitle = "After that, it was just me. Without him there... I didn't really know how to make new toys anymore. So I just kept selling whatever stock he'd left behind...",
          TalkActionId = {
            [1] = "93103:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FABE"
        },
        [80130212] = {
          ContentEN = "I... I didn't understand it either. It all happened so suddenly.",
          DialogueId = 80130212,
          FacialId = {
            [1] = "93103:Shock01"
          },
          GUID = "C898FAE8",
          NextDialogue = 80130214,
          SpeakNpcId = 93103,
          Subtitle = "I... I didn't understand it either. It all happened so suddenly.",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FAE8"
        },
        [80130213] = {
          ContentEN = "Thank you... I really did try my best to learn everything I could back then.",
          DialogueId = 80130213,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898FB12",
          NextDialogue = 80130214,
          SpeakNpcId = 93103,
          Subtitle = "Thank you... I really did try my best to learn everything I could back then.",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FB12"
        },
        [80130214] = {
          ContentEN = "Anyway... a few months passed. More parents came in with their kids, business was finally picking up...",
          DialogueId = 80130214,
          FacialId = {
            [1] = "93103:Happy01"
          },
          GUID = "C898FB3C",
          NextDialogue = 80130215,
          SpeakNpcId = 93103,
          Subtitle = "Anyway... a few months passed. More parents came in with their kids, business was finally picking up...",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FB3C"
        },
        [80130215] = {
          ContentEN = "Then one day a boy about my age showed up. I thought he was just another customer, so I started recommending toys.",
          DialogueId = 80130215,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898FB66",
          NextDialogue = 80130216,
          SpeakNpcId = 93103,
          Subtitle = "Then one day a boy about my age showed up. I thought he was just another customer, so I started recommending toys.",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FB66"
        },
        [80130216] = {
          ContentEN = "But he just looked at me and said, in this cold voice, that Snap 'n' Spark wasn't the old man's shop at all — that he had stolen it from him.",
          DialogueId = 80130216,
          FacialId = {
            [1] = "93103:Shock01"
          },
          GUID = "C898FB90",
          NextDialogue = 80130217,
          SpeakNpcId = 93103,
          Subtitle = "But he just looked at me and said, in this cold voice, that Snap 'n' Spark wasn't the old man's shop at all — that he had stolen it from him.",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FB90"
        },
        [80130217] = {
          ContentEN = "I didn't believe him at first. But then he marched straight to the workbench, picked up the tools like he'd been using them forever...",
          DialogueId = 80130217,
          GUID = "C898FBBA",
          NextDialogue = 80130218,
          SpeakNpcId = 93103,
          Subtitle = "I didn't believe him at first. But then he marched straight to the workbench, picked up the tools like he'd been using them forever...",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FBBA"
        },
        [80130218] = {
          ContentEN = "I tried to warn him that the materials were dangerous and not to mess with them — but before I could even finish, he had already put together a bomb. Faster than the old man ever could.",
          DialogueId = 80130218,
          GUID = "C898FBE4",
          NextDialogue = 80130219,
          SpeakNpcId = 93103,
          Subtitle = "I tried to warn him that the materials were dangerous and not to mess with them — but before I could even finish, he had already put together a bomb. Faster than the old man ever could.",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FBE4"
        },
        [80130219] = {
          ContentEN = "He looked at me — and, in this really harsh, accusing voice — said the old man was a thief... and that I was one too.",
          DialogueId = 80130219,
          FacialId = {
            [1] = "93103:Sad01"
          },
          GUID = "C898FC0E",
          NextDialogue = 80130220,
          SpeakNpcId = 93103,
          Subtitle = "He looked at me — and, in this really harsh, accusing voice — said the old man was a thief... and that I was one too.",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FC0E"
        },
        [80130220] = {
          ContentEN = "I didn't want to believe him. But the way he handled everything... it felt like... he really belonged there. Like he was the real owner all along.",
          DialogueId = 80130220,
          GUID = "C898FC38",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextDialogue = 80130221,
          SpeakNpcId = 93103,
          Subtitle = "I didn't want to believe him. But the way he handled everything... it felt like... he really belonged there. Like he was the real owner all along.",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FC38"
        },
        [80130221] = {
          ContentEN = "So... now I...",
          DialogueId = 80130221,
          FacialId = {
            [1] = "93103:Iyada01"
          },
          GUID = "C898FC62",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextOptions = {
            [1] = 801302211,
            [2] = 801302212
          },
          SpeakNpcId = 93103,
          Subtitle = "So... now I...",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FC62"
        },
        [80130222] = {
          ContentEN = "Yes. If what he said is true... maybe I should give Snap 'n' Spark back.",
          DialogueId = 80130222,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898FC8C",
          NextDialogue = 80130224,
          SpeakNpcId = 93103,
          Subtitle = "Yes. If what he said is true... maybe I should give Snap 'n' Spark back.",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FC8C"
        },
        [80130223] = {
          ContentEN = "If he really was the owner... then I think I should.",
          DialogueId = 80130223,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898FCB6",
          NextDialogue = 80130224,
          SpeakNpcId = 93103,
          Subtitle = "If he really was the owner... then I think I should.",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FCB6"
        },
        [80130224] = {
          ContentEN = "The truth is, I'm scared. B—but... if he really is the true owner of Snap 'n' Spark... what am I supposed to do?",
          DialogueId = 80130224,
          FacialId = {
            [1] = "93103:Iyada01"
          },
          GUID = "C898FCE0",
          NextDialogue = 80130225,
          SpeakNpcId = 93103,
          Subtitle = "The truth is, I'm scared. B—but... if he really is the true owner of Snap 'n' Spark... what am I supposed to do?",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FCE0"
        },
        [80130225] = {
          ContentEN = "I've grown so attached to the place... I worked really hard — learning how to greet customers, recommend toys, get better at talking to other kids... Could he do all that too?",
          DialogueId = 80130225,
          GUID = "C898FD0A",
          NextDialogue = 80130226,
          SpeakNpcId = 93103,
          Subtitle = "I've grown so attached to the place... I worked really hard — learning how to greet customers, recommend toys, get better at talking to other kids... Could he do all that too?",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FD0A"
        },
        [80130226] = {
          ContentEN = "And if it was his shop all along... how could I ever make it up to him? I don't know why he left in the first place, but... it just feels wrong.",
          DialogueId = 80130226,
          FacialId = {
            [1] = "93103:Sad01"
          },
          GUID = "C898FD34",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextDialogue = 80130227,
          SpeakNpcId = 93103,
          Subtitle = "And if it was his shop all along... how could I ever make it up to him? I don't know why he left in the first place, but... it just feels wrong.",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FD34"
        },
        [80130227] = {
          ContentEN = "Imagine losing your own shop, then coming back to find a stranger behind the counter... I can't even picture how awful that must feel...",
          DialogueId = 80130227,
          GUID = "C898FD5E",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextOptions = {
            [1] = 801302271
          },
          SpeakNpcId = 93103,
          Subtitle = "Imagine losing your own shop, then coming back to find a stranger behind the counter... I can't even picture how awful that must feel...",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FD5E"
        },
        [80130229] = {
          ContentEN = "I know exactly what he'd say: yell at me, call me an idiot, insist I'm the rightful owner now — tell me to focus on running it better instead of handing it over.",
          DialogueId = 80130229,
          FacialId = {
            [1] = "93103:Confident02"
          },
          GUID = "C898FDB2",
          NextDialogue = 80130230,
          SpeakNpcId = 93103,
          Subtitle = "I know exactly what he'd say: yell at me, call me an idiot, insist I'm the rightful owner now — tell me to focus on running it better instead of handing it over.",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FDB2"
        },
        [80130230] = {
          ContentEN = "He'd definitely try to stop me... But I know — underneath it all, he's actually really kind.",
          DialogueId = 80130230,
          FacialId = {
            [1] = "93103:Syouganai01"
          },
          GUID = "C898FDDC",
          NextDialogue = 80130231,
          SpeakNpcId = 93103,
          Subtitle = "He'd definitely try to stop me... But I know — underneath it all, he's actually really kind.",
          TalkActionId = {
            [1] = "93103:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FDDC"
        },
        [80130231] = {
          ContentEN = "But... that boy was a good person too. And I don't think good people should always get the short end of the stick. Someone ought to do right by him as well.",
          DialogueId = 80130231,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898FE06",
          NextDialogue = 80130232,
          SpeakNpcId = 93103,
          Subtitle = "But... that boy was a good person too. And I don't think good people should always get the short end of the stick. Someone ought to do right by him as well.",
          TalkActionId = {
            [1] = "93103:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FE06"
        },
        [80130232] = {
          ContentEN = "Thanks for the tea. I think I know what I need to do now. Really — thank you. I'll head back to Scarletriver.",
          DialogueId = 80130232,
          FacialId = {
            [1] = "93103:Happy02"
          },
          GUID = "C898FE30",
          NextDialogue = 80130233,
          SpeakNpcId = 93103,
          Subtitle = "Thanks for the tea. I think I know what I need to do now. Really — thank you. I'll head back to Scarletriver.",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FE30"
        },
        [80130233] = {
          ContentEN = "Oh! And if you still want to order something from Snap 'n' Spark, just send a letter. The shop's staying open either way.",
          DialogueId = 80130233,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898FE5A",
          NextDialogue = 80130234,
          SpeakNpcId = 93103,
