        [80140119] = {
          Camera = "-475.37677,-270.540131,435.15625,0.000049,-28.199356,17.585888,25.000002,100000.0,false,DoNotOverride,2.8",
          ContentEN = "Violetta! I could hear you spouting nonsense from all the way across the room — you're making Parsifal the lead!?",
          DialogueId = 80140119,
          FacialId = {
            [1] = "790030:None"
          },
          FinalCamera = "-475.37677,-270.540131,403.910156,0.000049,-28.199356,17.585888,25.000002,100000.0,false,DoNotOverride,2.8",
          GUID = "C89F5446",
          LookAt = {
            [1] = "790030:n(790032)",
            [2] = "790032:n(790031)"
          },
          NextDialogue = 80140120,
          Scripts = "MoveTo{ActorId{790032},MoveSpeed{80},TargetPoint{\"P80140120\"}}",
          SpeakNpcId = 790032,
          Subtitle = "Violetta! I could hear you spouting nonsense from all the way across the room — you're making Parsifal the lead!?",
          ToFinalCameraBlendTime = 15,
          TurnTo = {
            [1] = "790031:n(790032)"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F5446"
        },
        [80140120] = {
          ContentEN = "Are you out of your mind? By tomorrow, the entire city of Icelake will be buzzing with the news that the Magic Flute troupe cast a Charon as their lead! Do you have any idea what that will do to our decades-long reputation?",
          DialogueId = 80140120,
          GUID = "C89F5470",
          LookAt = {
            [1] = "790031:n(790032)"
          },
          NextDialogue = 80140121,
          SpeakNpcId = 790032,
          Subtitle = "Are you out of your mind? By tomorrow, the entire city of Icelake will be buzzing with the news that the Magic Flute troupe cast a Charon as their lead! Do you have any idea what that will do to our decades-long reputation?",
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F5470"
        },
        [80140121] = {
          Camera = "141.589691,-501.412964,133.425781,0.000001,-0.599643,94.196159,52.004452,100000.0,false,DoNotOverride,2.8",
          ContentEN = "Don't worry, Ms Putsch. It's a fairy role. Some extravagant headgear will fit the character perfectly. We'll have the props master design something dramatic. No one will notice Parsifal is a Charon.",
          DialogueId = 80140121,
          FacialId = {
            [1] = "790031:CM_Smile01"
          },
          GUID = "C89F549A",
          LookAt = {
            [1] = "790031:n(790032)"
          },
          NextDialogue = 80140122,
          Scripts = [[
