}]],
          SpeakNpcId = 790031,
          Subtitle = "And don't fret about the rest of the cast. I'll speak to them personally — I'll do my best to minimise any trouble for you. If things really turn messy, just say it was my idea and that I forced the entire troupe into it.",
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F54C4"
        },
        [80140123] = {
          Camera = "141.589691,-501.412964,133.425781,0.000001,-0.599643,94.196159,52.004452,100000.0,false,DoNotOverride,2.8",
          ContentEN = "Besides, we both know Parsifal is the finest singer in the troupe. His talent surpasses even mine at his age. Otherwise, you wouldn't have kept him singing behind the curtain for so long.",
          DialogueId = 80140123,
          FinalCamera = "141.589691,-501.412964,133.425781,0.0,-0.399709,105.796799,52.004452,100000.0,false,DoNotOverride,2.8",
          GUID = "C89F54EE",
          LookAt = {
            [1] = "790031:n(790030)",
            [2] = "790032:n(790030)"
          },
          NextDialogue = 80140124,
          SpeakNpcId = 790031,
          Subtitle = "Besides, we both know Parsifal is the finest singer in the troupe. His talent surpasses even mine at his age. Otherwise, you wouldn't have kept him singing behind the curtain for so long.",
          TalkActionId = {
            [1] = "790031:Explain01_End"
          },
          ToFinalCameraBlendTime = 1,
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F54EE"
        },
        [80140124] = {
          ContentEN = "I refuse to watch such a rare and precious gift remain buried in the shadows, never given the chance to grow. Parsifal deserves the opportunity to shine in the spotlight.",
          DialogueId = 80140124,
          GUID = "C89F5518",
          NextDialogue = 80140125,
          SpeakNpcId = 790031,
          Subtitle = "I refuse to watch such a rare and precious gift remain buried in the shadows, never given the chance to grow. Parsifal deserves the opportunity to shine in the spotlight.",
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F5518"
        },
        [80140125] = {
          Camera = "-93.044205,115.413742,181.152344,0.000014,-13.400175,-51.013519,25.000002,100000.0,false,DoNotOverride,2.8",
          ContentEN = "But Children From the Snowfield is one of our most celebrated productions in recent years. If we suddenly cast a newcomer as the lead, people are bound to be curious about his identity.",
          DialogueId = 80140125,
          GUID = "C89F5542",
          LookAt = {
            [1] = "790032:n(790031)",
            [2] = "790031:n(790032)"
          },
          NextDialogue = 80140126,
          SpeakNpcId = 790032,
          Subtitle = "But Children From the Snowfield is one of our most celebrated productions in recent years. If we suddenly cast a newcomer as the lead, people are bound to be curious about his identity.",
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F5542"
        },
        [80140126] = {
          ContentEN = "You know how ruthless Icelake's tabloids can be. How exactly do we keep his identity under wraps?",
