        [80140136] = {
          Camera = "-176.469574,-68.699188,170.910156,0.000072,-9.199588,8.997595,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentEN = "All right, all right, don't overthink it. Just perform like you always do — that alone is more than enough. Though... Hehe, I must admit, even I'm getting a little excited. Who knows? This might just become our greatest production of Children From the Snowfield yet.",
          DialogueId = 80140136,
          FacialId = {
            [1] = "790031:CM_Happy01"
