          SpeakNpcId = 790034,
          Subtitle = "Though his voice sounds a lot like the previous lead's. Is it some sort of imitation show?",
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F57E2"
        },
        [80140142] = {
          Camera = "-330.339844,-54.918457,134.652344,0.000047,-17.400023,59.799068,35.0,100000.0,false,DoNotOverride,2.8",
