        [80140210] = {
          Camera = "-110.558594,139.20166,173.46875,0.00002,-8.599856,100.192047,35.000008,108.885063,false,Manual,2.8",
          ContentEN = "...No, I'm not on tonight's programme. In fact, beyond delivering the troupe's greetings, I came with some... personal matters I'd like to discuss with you.",
          DialogueId = 80140210,
          GUID = "C89F6334",
          NextDialogue = 80140211,
          SpeakNpcId = 790043,
          Subtitle = "...No, I'm not on tonight's programme. In fact, beyond delivering the troupe's greetings, I came with some... personal matters I'd like to discuss with you.",
