        },
        [80140424] = {
          Camera = "149.733398,593.0,86.0,0.0,0.0,-72.599388,35.0,100000.0,false,DoNotOverride,2.8",
          ContentEN = "Oh, right. I shouldn't have mentioned him in front of you. Last time the director brought him up, you got so mad you nearly smashed the props.",
          DialogueId = 80140424,
          FacialId = {
            [1] = "790026:CM_Sad01"
          },
          GUID = "C89F8650",
          LookAt = {
            [1] = "790027:n(790027)"
          },
          NextDialogue = 80140425,
          SpeakNpcId = 790026,
          Subtitle = "Oh, right. I shouldn't have mentioned him in front of you. Last time the director brought him up, you got so mad you nearly smashed the props.",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8650"
        },
        [80140425] = {
          Camera = "43.179199,176.508789,110.248047,0.000011,-3.59994,23.599939,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentEN = "Yeah... I was furious back then. If not for him and Ms Violetta deceiving the audience, Children From the Snowfield wouldn't have been cancelled. All those rehearsals wouldn't have gone to waste..",
          DialogueId = 80140425,
          FacialId = {
            [1] = "790026:CM_Shock01"
          },
          GUID = "C89F867A",
          LookAt = {
            [1] = "790026:n(790027)"
          },
          NextDialogue = 80140426,
          SpeakNpcId = 790027,
          Subtitle = "Yeah... I was furious back then. If not for him and Ms Violetta deceiving the audience, Children From the Snowfield wouldn't have been cancelled. All those rehearsals wouldn't have gone to waste..",
          TurnTo = {
            [1] = "790027:p(90)"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F867A"
        },
        [80140426] = {
          ContentEN = " But.. I've asked myself many times since then — was he really wrong for stepping on that stage? Was it his fault for breaking the rule that says \"Charons can't perform,\" or... was the rule itself at fault?",
          DialogueId = 80140426,
          GUID = "C89F86A4",
          LookAt = {
            [1] = "790027:n(790026)"
          },
          NextDialogue = 80140427,
          SpeakNpcId = 790027,
          Subtitle = " But.. I've asked myself many times since then — was he really wrong for stepping on that stage? Was it his fault for breaking the rule that says \"Charons can't perform,\" or... was the rule itself at fault?",
          TurnTo = {
            [1] = "790027:n(790026)"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F86A4"
        },
        [80140427] = {
          ContentEN = "Why do we stand on the stage? To <H>honour the unparalleled value of art</>.",
          DialogueId = 80140427,
          GUID = "C89F86CE",
          NextDialogue = 80140428,
          SpeakNpcId = 790027,
          Subtitle = "Why do we stand on the stage? To honour the unparalleled value of art.",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F86CE"
        },
        [80140428] = {
          ContentEN = "But why do people care more about whether a performer has horns than about the performance itself? If we all stood behind the curtain, how would Parsifal be any different from the rest of us?",
          DialogueId = 80140428,
          GUID = "C89F86F8",
          NextDialogue = 80140429,
          SpeakNpcId = 790027,
          Subtitle = "But why do people care more about whether a performer has horns than about the performance itself? If we all stood behind the curtain, how would Parsifal be any different from the rest of us?",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F86F8"
        },
        [80140429] = {
          Camera = "184.165039,231.606201,98.688477,0.00003,4.399932,43.401665,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentEN = "Oh, there is one difference — he sings better than I do.",
          DialogueId = 80140429,
          FacialId = {
            [1] = "790027:CM_Idle"
          },
          GUID = "C89F8722",
          NextDialogue = 80140430,
          SpeakNpcId = 790027,
          Subtitle = "Oh, there is one difference — he sings better than I do.",
          TalkActionId = {
            [1] = "790027:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8722"
        },
        [80140430] = {
          Camera = "201.510254,546.49585,122.383301,0.000004,-6.400051,-77.79879,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentEN = "Wow, it's rare to hear you say something like that. Looks like our reckless little Dennis is finally growing up!",
          DialogueId = 80140430,
          FacialId = {
            [1] = "790026:CM_Happy01"
          },
          GUID = "C89F874C",
          NextDialogue = 80140431,
          SpeakNpcId = 790026,
          Subtitle = "Wow, it's rare to hear you say something like that. Looks like our reckless little Dennis is finally growing up!",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F874C"
        },
        [80140431] = {
          Camera = "96.443359,130.570557,116.894043,0.000003,-3.99997,42.200706,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentEN = "Hey, don't start acting like the director and giving me lectures, alright?",
          DialogueId = 80140431,
          FacialId = {
            [1] = "790027:CM_Angry01"
          },
          GUID = "C89F8776",
          NextDialogue = 80140432,
          SpeakNpcId = 790027,
          Subtitle = "Hey, don't start acting like the director and giving me lectures, alright?",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8776"
        },
        [80140432] = {
          Camera = "201.510254,546.49585,122.383301,0.000004,-6.400051,-77.79879,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentEN = "That wasn't a lecture — it was a compliment! But if Parsifal ever comes back, I'll give him a real telling-off. Vanishing without so much as a note... What was he thinking? *sigh* I really miss him.",
          DialogueId = 80140432,
          FacialId = {
            [1] = "790026:CM_Smile01"
          },
          GUID = "C89F87A0",
          NextDialogue = 80140433,
          SpeakNpcId = 790026,
          Subtitle = "That wasn't a lecture — it was a compliment! But if Parsifal ever comes back, I'll give him a real telling-off. Vanishing without so much as a note... What was he thinking? *sigh* I really miss him.",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F87A0"
        },
        [80140433] = {
          Camera = "-1153.268066,1960.390137,235.713867,0.000035,-6.800218,-58.593773,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentEN = "(Susanna... Dennis...)",
          DialogueId = 80140433,
          GUID = "C89F87CA",
          NextDialogue = 80140434,
          SpeakNpcId = 790025,
          SpeakNpcName = "UI_Npc_Name_Paxi",
          Subtitle = "(Susanna... Dennis...)",
          TalkActionId = {
            [1] = "790025:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F87CA"
        },
        [80140434] = {
          Camera = "185.86377,442.624756,59.498047,0.000046,11.799335,-73.192505,47.811131,100000.0,false,DoNotOverride,2.8",
          ContentEN = "Do you remember what Ms Violetta used to say? \"Someday — not now, but in the future — our art will usher in a purer era, one free of prejudice or discrimination, with no divide between Solas and Charons.\"",
          DialogueId = 80140434,
          FacialId = {
            [1] = "790026:CM_Smile01"
          },
          FinalCamera = "199.419434,397.746582,69.291504,0.000046,11.799335,-73.192505,47.811131,100000.0,false,DoNotOverride,2.8",
          GUID = "C89F87F4",
          NextDialogue = 80140435,
          SpeakNpcId = 790026,
          Subtitle = "Do you remember what Ms Violetta used to say? \"Someday — not now, but in the future — our art will usher in a purer era, one free of prejudice or discrimination, with no divide between Solas and Charons.\"",
          TalkActionId = {
            [1] = "790025:Explain02_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F87F4"
        },
        [80140435] = {
          ContentEN = "I believe that even though Ms Violetta and Parsifal were scorned by so many, which brought shame upon the troupe... it's people like them who will bring about that brighter future.",
          DialogueId = 80140435,
          GUID = "C89F881E",
          NextDialogue = 80140436,
          SpeakNpcId = 790026,
          Subtitle = "I believe that even though Ms Violetta and Parsifal were scorned by so many, which brought shame upon the troupe... it's people like them who will bring about that brighter future.",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F881E"
        },
        [80140436] = {
          ContentEN = "When that day arrives, they won't be remembered as \"disgraces.\" They'll be seen as \"heroes\" — visionaries who woke up before the rest of us.",
          DialogueId = 80140436,
          FacialId = {
            [1] = "790026:CM_Happy01"
          },
          GUID = "C89F8848",
          NextDialogue = 80140437,
