        [80160103] = {
          ContentEN = "Up north in Icelake, there's a house with a piano, an anvil, and an hourglass. The lodger there entertains friends with homemade drinks — and is always happy to befriend strangers who mean no harm.",
          DialogueId = 80160103,
          Duration = 3,
          GUID = "C8AC22E6",
          NextDialogue = 80160104,
          SpeakNpcId = 790055,
          Subtitle = "Up north in Icelake, there's a house with a piano, an anvil, and an hourglass. The lodger there entertains friends with homemade drinks — and is always happy to befriend strangers who mean no harm.",
          TalkActionId = {
            [1] = "790055:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC22E6"
        },
        [80160104] = {
          ContentEN = "\"A place where you can drink in peace. Unbothered.\"",
          DialogueId = 80160104,
          Duration = 3,
          GUID = "C8AC2310",
          NextDialogue = 80160105,
          SpeakNpcId = 790055,
          Subtitle = "\"A place where you can drink in peace. Unbothered.\"",
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2310"
        },
        [80160105] = {
          ContentEN = "That's what Camilla Scarlet of the Asphodel told me. Was she lying?",
          DialogueId = 80160105,
          Duration = 3,
          GUID = "C8AC233A",
          NextOptions = {
            [1] = 801601071
          },
          SpeakNpcId = 790055,
          Subtitle = "That's what Camilla Scarlet of the Asphodel told me. Was she lying?",
          TalkActionId = {
            [1] = "790055:Talk01_Loop"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC233A"
        },
        [80160106] = {
          ContentEN = "The Asphodel, you mean. Camilla Scarlet's establishment. Actually, she's the one who sent me here.",
          DialogueId = 80160106,
          Duration = 3,
          GUID = "C8AC2364",
          NextDialogue = 80160107,
          SpeakNpcId = 790055,
          Subtitle = "The Asphodel, you mean. Camilla Scarlet's establishment. Actually, she's the one who sent me here.",
          TalkActionId = {
            [1] = "790055:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2364"
        },
        [80160107] = {
          ContentEN = "Her drinks could rival those of the finest taverns in the capital — it's no wonder the place is always packed. But today, I seek peace. A place where I can lower my guard.",
          DialogueId = 80160107,
          Duration = 3,
          GUID = "C8AC238E",
