          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC25DA"
        },
        [80160122] = {
          Camera = "-59.147827,-133.68457,134.808594,0.000211,8.401542,69.408882,35.0,451.476898,false,DoNotOverride,10.496961",
          ContentEN = "Heh... you flatter me, ma'am. I'm just a humble tavern keeper who'd never dare fall behind on her taxes. As for secrets — well, who doesn't have one or two?",
          DialogueId = 80160122,
          Duration = 5,
          FacialId = {
            [1] = "790052:Smile01"
          },
          FinalCamera = "-46.137329,-99.043945,142.054688,0.000211,8.401542,69.408882,35.0,451.476898,false,DoNotOverride,10.496961",
          GUID = "C8AC2604",
          NextDialogue = 80160123,
          SpeakNpcId = 790052,
          Subtitle = "Heh... you flatter me, ma'am. I'm just a humble tavern keeper who'd never dare fall behind on her taxes. As for secrets — well, who doesn't have one or two?",
          ToFinalCameraBlendTime = 25,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2604"
        },
        [80160123] = {
          ContentEN = "Besides, not every secret's dangerous. Sometimes, it's just something harmless — like an old family recipe for smoked ham. I haven't served it yet... only because I wasn't sure it would suit your palate.",
          DialogueId = 80160123,
          Duration = 5,
          GUID = "C8AC262E",
          NextDialogue = 80160124,
          SpeakNpcId = 790052,
          Subtitle = "Besides, not every secret's dangerous. Sometimes, it's just something harmless — like an old family recipe for smoked ham. I haven't served it yet... only because I wasn't sure it would suit your palate.",
          TalkActionId = {
            [1] = "790052:Talk02_Start"
