          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC262E"
        },
        [80160124] = {
          Camera = "-86.051514,-78.273438,146.841797,0.000205,-1.598749,-143.392212,35.0,451.476898,false,DoNotOverride,10.496961",
          ContentEN = "Amusing. One of my lieutenants — an expert in \"thorough searches\" — used to crack jokes like that.",
          DialogueId = 80160124,
          Duration = 3,
          GUID = "C8AC2658",
          NextDialogue = 80160125,
          SpeakNpcId = 790055,
          Subtitle = "Amusing. One of my lieutenants — an expert in \"thorough searches\" — used to crack jokes like that.",
