          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2658"
        },
        [80160125] = {
          ContentEN = "Relax, Ms Scarlet.",
          DialogueId = 80160125,
          Duration = 3,
          GUID = "C8AC2682",
          NextDialogue = 80160126,
          SpeakNpcId = 790055,
          Subtitle = "Relax, Ms Scarlet.",
          TalkActionId = {
