          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2682"
        },
        [80160126] = {
          Camera = "279.85791,105.764648,170.447266,0.000227,-3.998898,-152.592499,68.94529,451.476898,false,DoNotOverride,10.496961",
          ContentEN = "This is your ground, not a courtroom — and certainly not the Royal Military Prison. No one here's going to jab a truth serum into your neck and drag a confession out of you.",
          DialogueId = 80160126,
          Duration = 3,
          GUID = "C8AC26AC",
          NextDialogue = 80160127,
          SpeakNpcId = 790055,
          Subtitle = "This is your ground, not a courtroom — and certainly not the Royal Military Prison. No one here's going to jab a truth serum into your neck and drag a confession out of you.",
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC26AC"
        },
        [80160127] = {
          ContentEN = "I came to Icelake on my own business, and you have your way of keeping things running. Let's not waste time trading riddles about \"ham recipes.\"",
          DialogueId = 80160127,
          Duration = 3,
          GUID = "C8AC26D6",
          NextDialogue = 80160128,
          SpeakNpcId = 790055,
          Subtitle = "I came to Icelake on my own business, and you have your way of keeping things running. Let's not waste time trading riddles about \"ham recipes.\"",
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC26D6"
        },
        [80160128] = {
