        [80160129] = {
          Camera = "-105.736328,-382.012695,149.125,0.000248,-3.398559,147.008057,39.565411,252.247864,false,Manual,2.892425",
          ContentEN = "Perhaps you wonder why I bothered to remark upon your little secret.",
          DialogueId = 80160129,
          Duration = 3,
          GUID = "C8AC272A",
          NextDialogue = 80160130,
          SpeakNpcId = 790055,
          Subtitle = "Perhaps you wonder why I bothered to remark upon your little secret.",
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC272A"
        },
        [80160130] = {
          ContentEN = "It wasn't meant as a threat. Call it a professional reflex — I find it hard to ignore lies and secrets that sit under my nose.",
          DialogueId = 80160130,
          Duration = 5,
          GUID = "C8AC2754",
          LookAt = {
