          Subtitle = "It wasn't meant as a threat. Call it a professional reflex — I find it hard to ignore lies and secrets that sit under my nose.",
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2754"
        },
        [80160131] = {
          ContentEN = "Pity I won't be able to enjoy a drink at Icelake's finest tavern. Farewell.",
          DialogueId = 80160131,
          Duration = 3,
          GUID = "C8AC277E",
          LookAt = {
