        },
        [80160424] = {
          ContentEN = "I will not repeat the same mistake.",
          DialogueId = 80160424,
          GUID = "C8AC5790",
          NextDialogue = 80160425,
          SpeakNpcId = 93201,
          Subtitle = "I will not repeat the same mistake.",
          TalkActionId = {
            [1] = "93201:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC5790"
        },
        [80160425] = {
          ContentEN = "We were comrades once, then officer and subordinate — now judge and criminal. Perhaps we both changed. But I will keep the vow I swore at any cost.",
          DialogueId = 80160425,
          GUID = "C8AC57BA",
          NextDialogue = 80160426,
          SpeakNpcId = 93201,
          Subtitle = "We were comrades once, then officer and subordinate — now judge and criminal. Perhaps we both changed. But I will keep the vow I swore at any cost.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC57BA"
        },
        [80160426] = {
          ContentEN = "Even if it means I'll have to walk that path alone.",
          DialogueId = 80160426,
          GUID = "C8AC57E4",
          NextOptions = {
            [1] = 801604261
          },
          SpeakNpcId = 93201,
          Subtitle = "Even if it means I'll have to walk that path alone.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC57E4"
        },
        [80160427] = {
          ContentEN = "Nothing.",
          DialogueId = 80160427,
          GUID = "C8AC580E",
          NextDialogue = 80160428,
          SpeakNpcId = 93201,
          Subtitle = "Nothing.",
          TalkActionId = {
            [1] = "93201:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC580E"
        },
        [80160428] = {
          ContentEN = "The comrade I honoured was that unyielding young woman. I have nothing to say to a criminal.",
          DialogueId = 80160428,
          GUID = "C8AC5838",
          NextDialogue = 80160429,
          SpeakNpcId = 93201,
          Subtitle = "The comrade I honoured was that unyielding young woman. I have nothing to say to a criminal.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC5838"
        },
        [80160429] = {
          ContentEN = "Hellfire drains the last of the melted ice-water.",
          DialogueId = 80160429,
          GUID = "C8AC5862",
          IsBlack = 1,
          NextDialogue = 80160430,
          SpeakNpcId = 93201,
          Subtitle = "Hellfire drains the last of the melted ice-water.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC5862"
        },
        [80160430] = {
          ContentEN = "Whether from the Alchemy Academy or the Imperial Military College, whether once an ally or a lifelong enemy — I will judge them without distinction.",
          DialogueId = 80160430,
          GUID = "C8AC588C",
          NextDialogue = 80160431,
          SpeakNpcId = 93201,
          Subtitle = "Whether from the Alchemy Academy or the Imperial Military College, whether once an ally or a lifelong enemy — I will judge them without distinction.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC588C"
        },
        [80160431] = {
          ContentEN = "Such is the duty of a warden of the Royal Prison. It is the only path left to me.",
          DialogueId = 80160431,
          GUID = "C8AC58B6",
          SpeakNpcId = 93201,
          Subtitle = "Such is the duty of a warden of the Royal Prison. It is the only path left to me.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC58B6"
        },
        [80170001] = {
          ContentEN = "My child, if you're feeling tired, take a seat and rest for a moment.",
          DialogueId = 80170001,
          GUID = "C8B27ACA",
          SpeakNpcId = 91502,
          Subtitle = "My child, if you're feeling tired, take a seat and rest for a moment.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B27ACA"
        },
        [80170101] = {
          Camera = "135.91098,22.045166,124.542297,0.000012,1.800007,-136.994522,35.0,158.845352,false,Manual,3.0",
          ContentEN = "Thank you for having me, my child. It's been many years since I've had the pleasure of sitting down and conversing with a friend like this. I must admit, I do miss it.",
          DialogueId = 80170101,
          FacialId = {
            [1] = "91502:Smile01"
          },
          GUID = "C8B28B32",
          LookAt = {
            [1] = "91502:p(18000P1)"
          },
          NextDialogue = 80170102,
          SpeakNpcId = 91502,
          Subtitle = "Thank you for having me, my child. It's been many years since I've had the pleasure of sitting down and conversing with a friend like this. I must admit, I do miss it.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28B32"
        },
        [80170102] = {
          ContentEN = "\"Many years\"? How long are we talking about?",
          DialogueId = 80170102,
          GUID = "C8B28B5C",
          NextDialogue = 80170103,
          SpeakNpcId = 790008,
          Subtitle = "\"Many years\"? How long are we talking about?",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28B5C"
        },
        [80170103] = {
          ContentEN = "Hmm... It has probably been over a decade, I would say. And before that... perhaps a few centuries.",
          DialogueId = 80170103,
          GUID = "C8B28B86",
          NextDialogue = 80170104,
          SpeakNpcId = 91502,
          Subtitle = "Hmm... It has probably been over a decade, I would say. And before that... perhaps a few centuries.",
          TalkActionId = {
            [1] = "91502:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28B86"
        },
        [80170104] = {
          ContentEN = "Huh...?",
          DialogueId = 80170104,
          GUID = "C8B28BB0",
          NextDialogue = 80170105,
          SpeakNpcId = 790008,
          Subtitle = "Huh...?",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28BB0"
        },
        [80170105] = {
          ContentEN = "Hehe, I must have caught you by surprise. In truth, my age stretches far beyond the land beneath our feet — older than even the Hyperborean Empire itself.",
          DialogueId = 80170105,
          GUID = "C8B28BDA",
          NextOptions = {
            [1] = 801701051,
            [2] = 801701052
          },
          SpeakNpcId = 91502,
          Subtitle = "Hehe, I must have caught you by surprise. In truth, my age stretches far beyond the land beneath our feet — older than even the Hyperborean Empire itself.",
          TalkActionId = {
            [1] = "91502:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28BDA"
        },
        [80170106] = {
          ContentEN = "The magic powers of Daimons differ greatly — most are innate or passed down through bloodlines. I'm afraid it is not something that can be easily taught.",
          DialogueId = 80170106,
          GUID = "C8B28C04",
          NextDialogue = 80170107,
          SpeakNpcId = 91502,
          Subtitle = "The magic powers of Daimons differ greatly — most are innate or passed down through bloodlines. I'm afraid it is not something that can be easily taught.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28C04"
        },
        [80170107] = {
          ContentEN = "That's alright. I was just joking around. But seriously...",
          DialogueId = 80170107,
          GUID = "C8B28C2E",
          NextDialogue = 80170108,
          SpeakNpcId = 790008,
          Subtitle = "That's alright. I was just joking around. But seriously...",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28C2E"
        },
        [80170108] = {
          ContentEN = "I didn't realise you had so many years of wisdom, Lady Nifle... It's truly an honour to speak with you.",
          DialogueId = 80170108,
          GUID = "C8B28C58",
          NextDialogue = 80170109,
          SpeakNpcId = 790008,
          Subtitle = "I didn't realise you had so many years of wisdom, Lady Nifle... It's truly an honour to speak with you.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28C58"
        },
        [80170109] = {
          ContentEN = "There is no need for such formality. Think of me simply as a friend, someone with whom you may share your thoughts.",
          DialogueId = 80170109,
          GUID = "C8B28C82",
          NextDialogue = 80170110,
          SpeakNpcId = 91502,
          Subtitle = "There is no need for such formality. Think of me simply as a friend, someone with whom you may share your thoughts.",
          TalkActionId = {
            [1] = "91502:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28C82"
        },
        [80170110] = {
          ContentEN = "But tell me, what would you like to discuss? I have long distanced myself from the fleeting trends of the world. However, if you seek stories from distant lands or times long past, I would not mind sharing what I know.",
          DialogueId = 80170110,
          GUID = "C8B28CAC",
          NextOptions = {
            [1] = 801701101
          },
          SpeakNpcId = 91502,
          Subtitle = "But tell me, what would you like to discuss? I have long distanced myself from the fleeting trends of the world. However, if you seek stories from distant lands or times long past, I would not mind sharing what I know.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28CAC"
        },
        [80170111] = {
          ContentEN = "I recall you saying that you were a \"Ferrywoman of the Misty Sea.\" I must admit, I'm still not entirely clear on what that means.",
          DialogueId = 80170111,
          GUID = "C8B28CD6",
          NextDialogue = 80170112,
          SpeakNpcId = 790008,
          Subtitle = "I recall you saying that you were a \"Ferrywoman of the Misty Sea.\" I must admit, I'm still not entirely clear on what that means.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28CD6"
        },
        [80170112] = {
          ContentEN = "Hmm... Perhaps you've heard of the Charon lore.",
          DialogueId = 80170112,
          GUID = "C8B28D00",
          NextDialogue = 80170113,
          SpeakNpcId = 91502,
          Subtitle = "Hmm... Perhaps you've heard of the Charon lore.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28D00"
        },
        [80170113] = {
          ContentEN = "In the beginning, the world was a chaotic sea of mist. From this mist arose the sacred tree, its branches adorned with pure white flowers. These flowers gave birth to our primordial ancestor — the goddess of life, Mother Embla, from whom all living things came.",
          DialogueId = 80170113,
          GUID = "C8B28D2A",
          NextDialogue = 80170114,
          SpeakNpcId = 91502,
          Subtitle = "In the beginning, the world was a chaotic sea of mist. From this mist arose the sacred tree, its branches adorned with pure white flowers. These flowers gave birth to our primordial ancestor — the goddess of life, Mother Embla, from whom all living things came.",
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28D2A"
        },
        [80170114] = {
          ContentEN = "All life emerged from the Misty Sea. After drifting through the river of the \"Mortal Realm,\" all things eventually return to the Misty Sea.",
          DialogueId = 80170114,
          GUID = "C8B28D54",
          NextDialogue = 80170115,
          SpeakNpcId = 91502,
          Subtitle = "All life emerged from the Misty Sea. After drifting through the river of the \"Mortal Realm,\" all things eventually return to the Misty Sea.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28D54"
        },
        [80170115] = {
          ContentEN = "The role of the Ferrywoman is to guide wandering souls back to the Misty Sea. Thus, I spend most of my time listening to the murmurs of the departed, responding with whispers.",
          DialogueId = 80170115,
          GUID = "C8B28D7E",
          NextDialogue = 80170116,
          SpeakNpcId = 91502,
          Subtitle = "The role of the Ferrywoman is to guide wandering souls back to the Misty Sea. Thus, I spend most of my time listening to the murmurs of the departed, responding with whispers.",
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28D7E"
        },
        [80170116] = {
          ContentEN = "That sounds... rather unsettling.",
          DialogueId = 80170116,
          GUID = "C8B28DA8",
          NextDialogue = 80170117,
          SpeakNpcId = 790008,
          Subtitle = "That sounds... rather unsettling.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28DA8"
        },
        [80170117] = {
          ContentEN = "Hehe, yes. To most, death is indeed a terrifying notion.",
          DialogueId = 80170117,
          GUID = "C8B28DD2",
          NextOptions = {
            [1] = 801701171
          },
          SpeakNpcId = 91502,
          Subtitle = "Hehe, yes. To most, death is indeed a terrifying notion.",
          TalkActionId = {
            [1] = "91502:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28DD2"
        },
        [80170118] = {
          ContentEN = "Hmm... Since the topic has arisen, allow me to share with you a tale about \"death.\" It is the story of a girl and her ailing younger sister.",
          DialogueId = 80170118,
          FacialId = {
            [1] = "91502:Sad01"
          },
          GUID = "C8B28DFC",
          NextDialogue = 80170119,
          SpeakNpcId = 91502,
          Subtitle = "Hmm... Since the topic has arisen, allow me to share with you a tale about \"death.\" It is the story of a girl and her ailing younger sister.",
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28DFC"
        },
        [80170119] = {
          ContentEN = "The girl and her sister were born into poverty in Elysium. Orphaned at a tender age, they had no choice but to fend for themselves, enduring both hunger and cold. Alas, one harsh winter, the younger sister succumbed to a fatal illness.",
          DialogueId = 80170119,
          GUID = "C8B28E26",
          NextDialogue = 80170120,
          SpeakNpcId = 91502,
          Subtitle = "The girl and her sister were born into poverty in Elysium. Orphaned at a tender age, they had no choice but to fend for themselves, enduring both hunger and cold. Alas, one harsh winter, the younger sister succumbed to a fatal illness.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28E26"
        },
        [80170120] = {
          ContentEN = "Desperate to save her sister, the girl searched far and wide for any possible cure, yet none came. It was then she heard a tale from an old man — the legend of the \"golden blood.\"",
          DialogueId = 80170120,
          GUID = "C8B28E50",
          NextDialogue = 80170121,
          SpeakNpcId = 91502,
          Subtitle = "Desperate to save her sister, the girl searched far and wide for any possible cure, yet none came. It was then she heard a tale from an old man — the legend of the \"golden blood.\"",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28E50"
        },
        [80170121] = {
          ContentEN = "It is said that a woman, blessed by the gods, was once revered by the nobles of Elysium. Her blood, believed to cure ailments and preserve youth, was as precious as gold.",
          DialogueId = 80170121,
          GUID = "C8B28E7A",
          NextDialogue = 80170122,
          SpeakNpcId = 91502,
          Subtitle = "It is said that a woman, blessed by the gods, was once revered by the nobles of Elysium. Her blood, believed to cure ailments and preserve youth, was as precious as gold.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28E7A"
        },
        [80170122] = {
          ContentEN = "Countless nobles offered vast sums of gold for but a single phial of her blood. Yet, before long, war descended upon Elysium. During the Great Migration, she was taken by rebels, and her whereabouts were lost to history.",
          DialogueId = 80170122,
          GUID = "C8B28EA4",
          NextDialogue = 80170123,
          SpeakNpcId = 91502,
          Subtitle = "Countless nobles offered vast sums of gold for but a single phial of her blood. Yet, before long, war descended upon Elysium. During the Great Migration, she was taken by rebels, and her whereabouts were lost to history.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28EA4"
        },
        [80170123] = {
          ContentEN = "Driven by her resolve to save her sister, the girl set out on a long and arduous journey. Eventually, much to her astonishment, she discovered that the woman was still alive — over a century old — and living in Aethyrie, the Woodland Kingdom.",
          DialogueId = 80170123,
          GUID = "C8B28ECE",
          NextDialogue = 80170124,
          SpeakNpcId = 91502,
          Subtitle = "Driven by her resolve to save her sister, the girl set out on a long and arduous journey. Eventually, much to her astonishment, she discovered that the woman was still alive — over a century old — and living in Aethyrie, the Woodland Kingdom.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28ECE"
        },
        [80170124] = {
          ContentEN = "So, the girl carried her dying sister through mountains and rivers, and finally they found the so-called \"blessed woman.\" Cradling her nearly lifeless sister, the girl tearfully begged for just a drop of her miraculous blood.",
          DialogueId = 80170124,
          GUID = "C8B28EF8",
          NextDialogue = 80170125,
          SpeakNpcId = 91502,
          Subtitle = "So, the girl carried her dying sister through mountains and rivers, and finally they found the so-called \"blessed woman.\" Cradling her nearly lifeless sister, the girl tearfully begged for just a drop of her miraculous blood.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28EF8"
        },
        [80170125] = {
          ContentEN = "But the \"golden blood,\" once believed to be a divine gift, turned out to be nothing more than a myth — a tale spun by the greed of the nobles to conceal their own sins. In truth, the woman had been imprisoned for her healing powers, enduring great suffering before finally escaping Elysium.",
          DialogueId = 80170125,
          GUID = "C8B28F22",
          NextDialogue = 80170126,
          SpeakNpcId = 91502,
          Subtitle = "But the \"golden blood,\" once believed to be a divine gift, turned out to be nothing more than a myth — a tale spun by the greed of the nobles to conceal their own sins. In truth, the woman had been imprisoned for her healing powers, enduring great suffering before finally escaping Elysium.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28F22"
        },
        [80170126] = {
          ContentEN = "She had long since decided never to use her abilities again, lest they cause even more pain and suffering.",
          DialogueId = 80170126,
          GUID = "C8B28F4C",
          NextDialogue = 80170127,
          SpeakNpcId = 91502,
          Subtitle = "She had long since decided never to use her abilities again, lest they cause even more pain and suffering.",
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28F4C"
        },
        [80170127] = {
          ContentEN = "So the girl went through all that for nothing...?",
          DialogueId = 80170127,
          GUID = "C8B28F76",
          NextDialogue = 80170128,
          SpeakNpcId = 790008,
          Subtitle = "So the girl went through all that for nothing...?",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28F76"
        },
        [80170128] = {
          ContentEN = "No... wait. Since you've spent so much time telling the story, surely it's not over yet?",
          DialogueId = 80170128,
          GUID = "C8B28FA0",
          NextDialogue = 80170129,
          SpeakNpcId = 790008,
          Subtitle = "No... wait. Since you've spent so much time telling the story, surely it's not over yet?",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28FA0"
        },
        [80170129] = {
          ContentEN = "Hehe, you're perceptive. After much hesitation, the woman eventually agreed to help.",
          DialogueId = 80170129,
          FacialId = {
            [1] = "91502:Smile01"
          },
          GUID = "C8B28FCA",
          NextDialogue = 80170130,
          SpeakNpcId = 91502,
          Subtitle = "Hehe, you're perceptive. After much hesitation, the woman eventually agreed to help.",
          TalkActionId = {
            [1] = "91502:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28FCA"
        },
        [80170130] = {
          ContentEN = "Why would she do that?",
          DialogueId = 80170130,
          GUID = "C8B28FF4",
          NextDialogue = 80170131,
          SpeakNpcId = 790008,
          Subtitle = "Why would she do that?",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28FF4"
        },
        [80170131] = {
          ContentEN = "Because, you see, the woman had not fully closed her heart to the idea of healing others. Twice before, she had tried to use her blood to extend the life of others — once for her closest friend, and once for her daughter.",
          DialogueId = 80170131,
          GUID = "C8B2901E",
          NextDialogue = 80170132,
          SpeakNpcId = 91502,
          Subtitle = "Because, you see, the woman had not fully closed her heart to the idea of healing others. Twice before, she had tried to use her blood to extend the life of others — once for her closest friend, and once for her daughter.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B2901E"
        },
        [80170132] = {
          ContentEN = "Her friend was a valiant warrior, fatally wounded on the battlefield. Her daughter, a respected scholar, was peacefully nearing the end of her days.",
          DialogueId = 80170132,
          GUID = "C8B29048",
          NextDialogue = 80170133,
          SpeakNpcId = 91502,
          Subtitle = "Her friend was a valiant warrior, fatally wounded on the battlefield. Her daughter, a respected scholar, was peacefully nearing the end of her days.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B29048"
        },
        [80170133] = {
          ContentEN = "Although their circumstances were vastly different, their decisions were the same: both refused to accept the woman's blood, choosing death over a life prolonged by such a means.",
          DialogueId = 80170133,
          GUID = "C8B29072",
          NextDialogue = 80170134,
          SpeakNpcId = 91502,
          Subtitle = "Although their circumstances were vastly different, their decisions were the same: both refused to accept the woman's blood, choosing death over a life prolonged by such a means.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B29072"
        },
        [80170134] = {
          ContentEN = "The sorrow in the girl's eyes reminded the woman of her own past, and her thoughts turned to a question that had long lingered:",
          DialogueId = 80170134,
          GUID = "C8B2909C",
          NextDialogue = 80170135,
          SpeakNpcId = 91502,
          Subtitle = "The sorrow in the girl's eyes reminded the woman of her own past, and her thoughts turned to a question that had long lingered:",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B2909C"
        },
        [80170135] = {
          ContentEN = "What could have been, had she been able to save her friend and daughter? What might the path she did not take have offered?",
          DialogueId = 80170135,
          GUID = "C8B290C6",
          NextDialogue = 80170136,
          SpeakNpcId = 91502,
          Subtitle = "What could have been, had she been able to save her friend and daughter? What might the path she did not take have offered?",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B290C6"
        },
        [80170136] = {
          ContentEN = "She needed to know the answer. So, she cut her own arm and gave her blood to the girl.",
          DialogueId = 80170136,
          GUID = "C8B290F0",
          NextDialogue = 80170137,
          SpeakNpcId = 91502,
          Subtitle = "She needed to know the answer. So, she cut her own arm and gave her blood to the girl.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B290F0"
        },
        [80170137] = {
          ContentEN = "The ailing little sister drank the \"golden blood\" and soon regained consciousness.",
          DialogueId = 80170137,
          GUID = "C8B2911A",
          NextOptions = {
