          DialogueId = 80170142,
          GUID = "C8B291EC",
          NextDialogue = 80170143,
          SpeakNpcId = 91502,
          Subtitle = "So, after drinking the blood, her little sister did not die, but her body was still in an irreversible decline.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B291EC"
        },
        [80170143] = {
          ContentEN = "She could do nothing but lie in bed, struggling even to swallow water. She could not taste her food, nor understand the words on the pages, nor hear clearly her sister's voice.",
          DialogueId = 80170143,
          GUID = "C8B29216",
          NextDialogue = 80170144,
          SpeakNpcId = 91502,
          Subtitle = "She could do nothing but lie in bed, struggling even to swallow water. She could not taste her food, nor understand the words on the pages, nor hear clearly her sister's voice.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B29216"
        },
        [80170144] = {
          ContentEN = "The girl took on various odd jobs, hoping to have enough time to stay by her sister's side and take care of her. To make ends meet, she had no choice but to take on the most gruelling work — the kind that others would avoid.",
          DialogueId = 80170144,
          GUID = "C8B29240",
          NextDialogue = 80170145,
          SpeakNpcId = 91502,
          Subtitle = "The girl took on various odd jobs, hoping to have enough time to stay by her sister's side and take care of her. To make ends meet, she had no choice but to take on the most gruelling work — the kind that others would avoid.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B29240"
        },
        [80170145] = {
          ContentEN = "Her will was indeed unwavering, desperately clinging to the hard-won \"miracle.\" Yet her frail body couldn't withstand the constant strain, and each day she came closer to collapse.",
          DialogueId = 80170145,
          GUID = "C8B2926A",
          NextOptions = {
