          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B2926A"
        },
        [80170146] = {
          ContentEN = "Eventually, the younger sister chose to end her own life. With the last of her strength, she pushed the small phial of \"miracle\" — the one her elder sister had so desperately begged for — to the ground and shattered it.",
          DialogueId = 80170146,
          GUID = "C8B29294",
          NextDialogue = 80170147,
          SpeakNpcId = 91502,
          Subtitle = "Eventually, the younger sister chose to end her own life. With the last of her strength, she pushed the small phial of \"miracle\" — the one her elder sister had so desperately begged for — to the ground and shattered it.",
          TalkActionId = {
