          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B293E4"
        },
        [80170155] = {
          ContentEN = "In the grand design of life, death is not always an unwelcome guest. At times, it arrives with quiet grace — like petals drifting from a flower as fruit begins to ripen, marking not just an end, but the birth of something new.",
          DialogueId = 80170155,
          GUID = "C8B2940E",
          NextDialogue = 80170156,
