        },
        [80170201] = {
          Camera = "135.91098,22.045166,124.542297,0.000012,1.800007,-136.994522,35.0,158.845352,false,Manual,3.0",
          ContentEN = "Greetings, my child. You seem weary. Has something been troubling you?",
          DialogueId = 80170201,
