          TalkActionId = {
            [1] = "91502:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29B9A"
        },
        [80170202] = {
          ContentEN = "Since leaving my homeland, I've been through so much and experienced many regrets. At times, I feel so powerless, as though all my efforts will be in vain.",
          DialogueId = 80170202,
          GUID = "C8B29BC4",
          NextDialogue = 80170203,
          SpeakNpcId = 790008,
          Subtitle = "Since leaving my homeland, I've been through so much and experienced many regrets. At times, I feel so powerless, as though all my efforts will be in vain.",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29BC4"
        },
        [80170203] = {
          ContentEN = "Lady Nifle, as someone with centuries of wisdom, do you have any advice for me?",
          DialogueId = 80170203,
          GUID = "C8B29BEE",
          NextDialogue = 80170204,
          SpeakNpcId = 790008,
          Subtitle = "Lady Nifle, as someone with centuries of wisdom, do you have any advice for me?",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29BEE"
        },
        [80170204] = {
          ContentEN = "I see... Well, let me share another story with you.",
          DialogueId = 80170204,
          GUID = "C8B29C18",
          NextDialogue = 80170205,
          SpeakNpcId = 91502,
          Subtitle = "I see... Well, let me share another story with you.",
          TalkActionId = {
            [1] = "91502:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29C18"
        },
        [80170205] = {
          ContentEN = "This is a story about a young man and a young woman — one filled with hope, courage, and dreams of the future.",
          DialogueId = 80170205,
          GUID = "C8B29C42",
          NextDialogue = 80170206,
          SpeakNpcId = 91502,
          Subtitle = "This is a story about a young man and a young woman — one filled with hope, courage, and dreams of the future.",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29C42"
        },
        [80170206] = {
          ContentEN = "The story takes place a millennium ago, when Elysium was the only nation on the continent. One was a commoner, the other a noble.",
          DialogueId = 80170206,
          GUID = "C8B29C6C",
          NextDialogue = 80170207,
          SpeakNpcId = 91502,
          Subtitle = "The story takes place a millennium ago, when Elysium was the only nation on the continent. One was a commoner, the other a noble.",
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29C6C"
        },
        [80170207] = {
          ContentEN = "The young man, born a commoner, developed a profound love for books from an early age, particularly history and mythology. Even as a youth, his vast knowledge became widely known, and many expected him to become a great scholar.",
          DialogueId = 80170207,
          GUID = "C8B29C96",
          NextDialogue = 80170208,
          SpeakNpcId = 91502,
          Subtitle = "The young man, born a commoner, developed a profound love for books from an early age, particularly history and mythology. Even as a youth, his vast knowledge became widely known, and many expected him to become a great scholar.",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29C96"
        },
        [80170208] = {
          ContentEN = "But the more he read, the more he learned, and the deeper he thought, the more he came to realise that this land was rife with injustices. What people had come to accept as normal was not always right.",
          DialogueId = 80170208,
          FacialId = {
            [1] = "91502:Sad01"
          },
          GUID = "C8B29CC0",
          NextDialogue = 80170209,
          SpeakNpcId = 91502,
          Subtitle = "But the more he read, the more he learned, and the deeper he thought, the more he came to realise that this land was rife with injustices. What people had come to accept as normal was not always right.",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29CC0"
        },
        [80170209] = {
          ContentEN = "The commoners toiled endlessly, barely scraping by, while the priests dined in excess. Beneath the loud chorus of hymns, the cries of the innocent could be heard — condemned as heretics and executed beneath the gallows.",
          DialogueId = 80170209,
          GUID = "C8B29CEA",
          NextDialogue = 80170210,
          SpeakNpcId = 91502,
          Subtitle = "The commoners toiled endlessly, barely scraping by, while the priests dined in excess. Beneath the loud chorus of hymns, the cries of the innocent could be heard — condemned as heretics and executed beneath the gallows.",
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29CEA"
        },
        [80170210] = {
          ContentEN = "—Of course, one of those cries belonged to a young girl, said to possess the \"golden blood.\"",
          DialogueId = 80170210,
          GUID = "C8B29D14",
          NextDialogue = 80170211,
          SpeakNpcId = 91502,
          Subtitle = "—Of course, one of those cries belonged to a young girl, said to possess the \"golden blood.\"",
          TalkActionId = {
            [1] = "91502:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29D14"
        },
        [80170211] = {
          ContentEN = "By day, she trembled as she slit her arm, offering her blood to those who came to worship her; by night, she curled in her cell, weeping in pain and praying for mercy from the gods.",
          DialogueId = 80170211,
          GUID = "C8B29D3E",
          NextDialogue = 80170212,
          SpeakNpcId = 91502,
          Subtitle = "By day, she trembled as she slit her arm, offering her blood to those who came to worship her; by night, she curled in her cell, weeping in pain and praying for mercy from the gods.",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29D3E"
        },
        [80170212] = {
          ContentEN = "One day, the young scholar ventured into the temple and delivered an impassioned speech to the gathered crowd, all of whom sought the so-called \"golden blood.\" In response, however, all he received was the sharp point of the guards' spears.",
          DialogueId = 80170212,
          GUID = "C8B29D68",
          NextDialogue = 80170213,
          SpeakNpcId = 91502,
          Subtitle = "One day, the young scholar ventured into the temple and delivered an impassioned speech to the gathered crowd, all of whom sought the so-called \"golden blood.\" In response, however, all he received was the sharp point of the guards' spears.",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29D68"
        },
        [80170213] = {
          ContentEN = "He was thrown into a cold, damp cell, where, by a twist of fate, he encountered another key figure in the story — the noble young woman, who had arrived with her father for an inspection.",
          DialogueId = 80170213,
          GUID = "C8B29D92",
          NextDialogue = 80170214,
          SpeakNpcId = 91502,
          Subtitle = "He was thrown into a cold, damp cell, where, by a twist of fate, he encountered another key figure in the story — the noble young woman, who had arrived with her father for an inspection.",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29D92"
        },
        [80170214] = {
          ContentEN = "The young woman had a deep passion for riding and martial arts, and beneath her spirited nature was a kind and compassionate heart. When she came across the \"misguided\" young scholar — one of her own age — she couldn't help but feel sympathy for him. In secret, she visited his cell, hoping to persuade him to confess and earn a lighter sentence.",
          DialogueId = 80170214,
          GUID = "C8B29DBC",
          NextDialogue = 80170215,
          SpeakNpcId = 91502,
          Subtitle = "The young woman had a deep passion for riding and martial arts, and beneath her spirited nature was a kind and compassionate heart. When she came across the \"misguided\" young scholar — one of her own age — she couldn't help but feel sympathy for him. In secret, she visited his cell, hoping to persuade him to confess and earn a lighter sentence.",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29DBC"
        },
        [80170215] = {
          ContentEN = "But the scholar insisted on his innocence. He even urged the young noblewoman to awaken from her own ignorance.",
          DialogueId = 80170215,
          GUID = "C8B29DE6",
          NextDialogue = 80170216,
          SpeakNpcId = 91502,
          Subtitle = "But the scholar insisted on his innocence. He even urged the young noblewoman to awaken from her own ignorance.",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29DE6"
        },
        [80170216] = {
          ContentEN = "He revealed to her that the girl, said to possess the \"golden blood\" whom people revered, was in fact a poor soul held captive by a powerful nobleman — the noble young woman's very own father — who sought to profit from her.",
          DialogueId = 80170216,
          GUID = "C8B29E10",
          NextDialogue = 80170217,
          SpeakNpcId = 91502,
          Subtitle = "He revealed to her that the girl, said to possess the \"golden blood\" whom people revered, was in fact a poor soul held captive by a powerful nobleman — the noble young woman's very own father — who sought to profit from her.",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29E10"
        },
        [80170217] = {
          ContentEN = "At first, the young woman dismissed his words as absurd. Yet, the fervour in his bright eyes lingered in her thoughts, refusing to fade.",
          DialogueId = 80170217,
          GUID = "C8B29E3A",
          NextDialogue = 80170218,
          SpeakNpcId = 91502,
          Subtitle = "At first, the young woman dismissed his words as absurd. Yet, the fervour in his bright eyes lingered in her thoughts, refusing to fade.",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29E3A"
        },
        [80170218] = {
          ContentEN = "She saw sincerity in those eyes. And so, with a heart moved by his words, she took the first step toward uncovering the truth. Stealing the key from her father, she ventured into the deepest chamber of the temple, where she found the pale, emaciated girl — shackled and imprisoned.",
          DialogueId = 80170218,
          GUID = "C8B29E64",
          NextDialogue = 80170219,
          SpeakNpcId = 91502,
          Subtitle = "She saw sincerity in those eyes. And so, with a heart moved by his words, she took the first step toward uncovering the truth. Stealing the key from her father, she ventured into the deepest chamber of the temple, where she found the pale, emaciated girl — shackled and imprisoned.",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29E64"
        },
        [80170219] = {
          ContentEN = "After learning the truth, the noblewoman returned to the scholar's cell and stood before him once more. Seeing her grave and sympathetic expression, the scholar understood that she was now ready. And so, he shared with her the dark truths of the nobleman.",
          DialogueId = 80170219,
          GUID = "C8B29E8E",
          NextDialogue = 80170220,
          SpeakNpcId = 91502,
          Subtitle = "After learning the truth, the noblewoman returned to the scholar's cell and stood before him once more. Seeing her grave and sympathetic expression, the scholar understood that she was now ready. And so, he shared with her the dark truths of the nobleman.",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29E8E"
        },
        [80170220] = {
          ContentEN = "The young man's words struck like a blade, tearing through the delicate fabric of the young woman's privileged life, exposing the grotesque reality beneath. In that moment, she began to see the dark corners of her world that had once remained hidden.",
          DialogueId = 80170220,
          GUID = "C8B29EB8",
          NextDialogue = 80170221,
          SpeakNpcId = 91502,
          Subtitle = "The young man's words struck like a blade, tearing through the delicate fabric of the young woman's privileged life, exposing the grotesque reality beneath. In that moment, she began to see the dark corners of her world that had once remained hidden.",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29EB8"
        },
        [80170221] = {
          ContentEN = "She confided in her father, hoping he would release the young man. Instead, she found herself placed under house arrest, constantly watched. It was then that she realised — her father had always been complicit in their suffering.",
          DialogueId = 80170221,
          GUID = "C8B29EE2",
          NextOptions = {
            [1] = 801702211,
            [2] = 801702212
          },
          SpeakNpcId = 91502,
          Subtitle = "She confided in her father, hoping he would release the young man. Instead, she found herself placed under house arrest, constantly watched. It was then that she realised — her father had always been complicit in their suffering.",
          TalkActionId = {
            [1] = "91502:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29EE2"
        },
        [80170222] = {
          ContentEN = "Yes. There were times when they, too, despaired. Exhausted, much like you are now, they questioned the very meaning of their struggle. Yet, despite it all, they chose to persevere.",
          DialogueId = 80170222,
          FacialId = {
            [1] = "91502:Smile01"
          },
          GUID = "C8B29F0C",
          NextDialogue = 80170223,
          SpeakNpcId = 91502,
          Subtitle = "Yes. There were times when they, too, despaired. Exhausted, much like you are now, they questioned the very meaning of their struggle. Yet, despite it all, they chose to persevere.",
          TalkActionId = {
            [1] = "91502:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29F0C"
        },
        [80170223] = {
          ContentEN = "Even in prison, the young man continued to develop his theories, tirelessly sketching a vision of a new world rooted in justice and freedom.",
          DialogueId = 80170223,
          GUID = "C8B29F36",
          NextDialogue = 80170224,
          SpeakNpcId = 91502,
          Subtitle = "Even in prison, the young man continued to develop his theories, tirelessly sketching a vision of a new world rooted in justice and freedom.",
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29F36"
        },
        [80170224] = {
          ContentEN = "Without the support of her family, the young woman rejected the temptations of wealth, dedicating herself to uplifting the downtrodden and seeking out those willing to contribute to the cause.",
          DialogueId = 80170224,
          GUID = "C8B29F60",
          NextDialogue = 80170225,
          SpeakNpcId = 91502,
          Subtitle = "Without the support of her family, the young woman rejected the temptations of wealth, dedicating herself to uplifting the downtrodden and seeking out those willing to contribute to the cause.",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29F60"
        },
        [80170225] = {
          ContentEN = "At first, their efforts were as subtle as the flutter of a butterfly's wings. Yet, over time, their actions stirred a storm, cracking the seemingly impenetrable structure of Elysium.",
          DialogueId = 80170225,
          GUID = "C8B29F8A",
          NextDialogue = 80170226,
          SpeakNpcId = 91502,
          Subtitle = "At first, their efforts were as subtle as the flutter of a butterfly's wings. Yet, over time, their actions stirred a storm, cracking the seemingly impenetrable structure of Elysium.",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29F8A"
        },
        [80170226] = {
          ContentEN = "Together, they became the leaders of the legendary Great Migration, leading a resistance that freed the oppressed from the grasp of Elysium.",
          DialogueId = 80170226,
          GUID = "C8B29FB4",
          NextDialogue = 80170227,
          SpeakNpcId = 91502,
          Subtitle = "Together, they became the leaders of the legendary Great Migration, leading a resistance that freed the oppressed from the grasp of Elysium.",
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29FB4"
        },
        [80170227] = {
          ContentEN = "The Elysium resistance... the Great Migration...",
          DialogueId = 80170227,
          GUID = "C8B29FDE",
          NextDialogue = 80170228,
          SpeakNpcId = 790008,
          Subtitle = "The Elysium resistance... the Great Migration...",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29FDE"
        },
        [80170228] = {
          ContentEN = "I've read about it in books. But they never truly achieved their vision of equality, did they?",
          DialogueId = 80170228,
          GUID = "C8B2A008",
          NextDialogue = 80170229,
          SpeakNpcId = 790008,
          Subtitle = "I've read about it in books. But they never truly achieved their vision of equality, did they?",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B2A008"
        },
        [80170229] = {
          ContentEN = "...Indeed, fate is a cruel force. It can stir a storm in the calmest of seas or extinguish flames with the power of a tidal wave. As you've said, often, our efforts yield nothing in the end.",
          DialogueId = 80170229,
          GUID = "C8B2A032",
          NextDialogue = 80170230,
          SpeakNpcId = 91502,
          Subtitle = "...Indeed, fate is a cruel force. It can stir a storm in the calmest of seas or extinguish flames with the power of a tidal wave. As you've said, often, our efforts yield nothing in the end.",
          TalkActionId = {
            [1] = "91502:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B2A032"
        },
        [80170230] = {
          ContentEN = "However, those glorious moments were real, and they will be eternally etched in memory.",
          DialogueId = 80170230,
          FacialId = {
            [1] = "91502:Confident01"
          },
          GUID = "C8B2A05C",
          NextDialogue = 80170231,
          SpeakNpcId = 91502,
          Subtitle = "However, those glorious moments were real, and they will be eternally etched in memory.",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B2A05C"
        },
        [80170231] = {
          ContentEN = "The Great Migration shed the light of courage and freedom across the Atlasia Continent, piercing through the veils of deceit woven by the gods. For the first time, people were allowed to confront their own desires and emotions.",
          DialogueId = 80170231,
          GUID = "C8B2A086",
          NextDialogue = 80170232,
          SpeakNpcId = 91502,
          Subtitle = "The Great Migration shed the light of courage and freedom across the Atlasia Continent, piercing through the veils of deceit woven by the gods. For the first time, people were allowed to confront their own desires and emotions.",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B2A086"
        },
        [80170232] = {
          ContentEN = "Even after centuries, that spark of light endures in the weighty tomes of history, continuing to inspire those who strive toward the world envisioned by the young man and woman.",
          DialogueId = 80170232,
          GUID = "C8B2A0B0",
          NextDialogue = 80170233,
          SpeakNpcId = 91502,
          Subtitle = "Even after centuries, that spark of light endures in the weighty tomes of history, continuing to inspire those who strive toward the world envisioned by the young man and woman.",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B2A0B0"
        },
        [80170233] = {
          ContentEN = "Mmm...",
          DialogueId = 80170233,
          GUID = "C8B2A0DA",
          NextDialogue = 80170234,
          SpeakNpcId = 790008,
          Subtitle = "Mmm...",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B2A0DA"
        },
        [80170234] = {
          ContentEN = "You asked for my advice earlier, but having lived in seclusion for so long, I find it difficult to offer concrete guidance.",
          DialogueId = 80170234,
          GUID = "C8B2A104",
          NextDialogue = 80170235,
          SpeakNpcId = 91502,
          Subtitle = "You asked for my advice earlier, but having lived in seclusion for so long, I find it difficult to offer concrete guidance.",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B2A104"
        },
        [80170235] = {
          ContentEN = "What I can share with you is: the longer I have lived, the more I've come to realise that what's truly precious in life lies in those fleeting moments. The moments you've fought for what you cherish will remain timeless, regardless of the outcome.",
          DialogueId = 80170235,
          GUID = "C8B2A12E",
          NextDialogue = 80170236,
          SpeakNpcId = 91502,
          Subtitle = "What I can share with you is: the longer I have lived, the more I've come to realise that what's truly precious in life lies in those fleeting moments. The moments you've fought for what you cherish will remain timeless, regardless of the outcome.",
          TalkActionId = {
            [1] = "91502:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B2A12E"
        },
        [80170236] = {
          ContentEN = "{nickname}, do not fear, nor hesitate — within you lies extraordinary strength, and I have no doubt that you will leave an indelible mark upon the course of time.",
          DialogueId = 80170236,
          GUID = "C8B2A158",
          NextOptions = {
            [1] = 801702361,
            [2] = 801702362
          },
          SpeakNpcId = 91502,
          Subtitle = ", do not fear, nor hesitate — within you lies extraordinary strength, and I have no doubt that you will leave an indelible mark upon the course of time.",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B2A158"
        },
        [80170237] = {
          ContentEN = "I have faith in you.",
          DialogueId = 80170237,
          FacialId = {
            [1] = "91502:Satisfy01"
          },
          GUID = "C8B2A182",
          NextDialogue = 80170238,
          SpeakNpcId = 91502,
          Subtitle = "I have faith in you.",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B2A182"
        },
        [80170238] = {
          ContentEN = "For now... let us set aside the weight of our thoughts and savour this rare moment of peace together, over a pot of tea.",
          DialogueId = 80170238,
          GUID = "C8B2A1AC",
          SpeakNpcId = 91502,
          Subtitle = "For now... let us set aside the weight of our thoughts and savour this rare moment of peace together, over a pot of tea.",
          TalkActionId = {
            [1] = "91502:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B2A1AC"
        },
        [80170301] = {
          Camera = "135.91098,22.045166,124.542297,0.000012,1.800007,-136.994522,35.0,158.845352,false,Manual,3.0",
          ContentEN = "Greetings, my child. You seem much improved since last time.",
          DialogueId = 80170301,
          FacialId = {
            [1] = "91502:Smile01"
          },
          GUID = "C8B2AC02",
          LookAt = {
            [1] = "91502:p(18000P1)"
          },
          NextOptions = {
            [1] = 801703011,
            [2] = 801703012
          },
          SpeakNpcId = 91502,
          Subtitle = "Greetings, my child. You seem much improved since last time.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AC02"
        },
        [80170302] = {
          ContentEN = "I am pleased that my story was of some help to you. Now, is there anything on your mind today that you'd like to discuss?",
          DialogueId = 80170302,
          FacialId = {
            [1] = "91502:Happy01"
          },
          GUID = "C8B2AC2C",
          NextDialogue = 80170303,
          SpeakNpcId = 91502,
          Subtitle = "I am pleased that my story was of some help to you. Now, is there anything on your mind today that you'd like to discuss?",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AC2C"
        },
        [80170303] = {
          ContentEN = "I've been wondering... What are your thoughts on \"mistakes,\" Lady Nifle?",
          DialogueId = 80170303,
          GUID = "C8B2AC56",
          NextDialogue = 80170304,
          SpeakNpcId = 790008,
          Subtitle = "I've been wondering... What are your thoughts on \"mistakes,\" Lady Nifle?",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AC56"
        },
        [80170304] = {
          ContentEN = "I... I've been through so much, and lost even more. At times, I wonder if I've made the wrong choices. If I had taken a different path, would things have turned out differently?",
          DialogueId = 80170304,
          GUID = "C8B2AC80",
          NextDialogue = 80170305,
          SpeakNpcId = 790008,
          Subtitle = "I... I've been through so much, and lost even more. At times, I wonder if I've made the wrong choices. If I had taken a different path, would things have turned out differently?",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AC80"
        },
        [80170305] = {
          ContentEN = "But I can't go back in time, and so, I'll never know the answer.",
          DialogueId = 80170305,
          GUID = "C8B2ACAA",
          NextDialogue = 80170306,
          SpeakNpcId = 790008,
          Subtitle = "But I can't go back in time, and so, I'll never know the answer.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2ACAA"
        },
        [80170306] = {
          ContentEN = "Mmm... I can see your confusion. Well then, allow me to share a tale about \"mistakes\" this time. It is the story of a couple.",
          DialogueId = 80170306,
          FacialId = {
            [1] = "91502:Smile01"
          },
          GUID = "C8B2ACD4",
          NextDialogue = 80170307,
          SpeakNpcId = 91502,
          Subtitle = "Mmm... I can see your confusion. Well then, allow me to share a tale about \"mistakes\" this time. It is the story of a couple.",
          TalkActionId = {
            [1] = "91502:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2ACD4"
        },
        [80170307] = {
          ContentEN = "They lived on the outskirts of Elysium. He was a hunter, and she, a maid in the city. For years, they yearned for a child, yet fate remained unyielding to their prayers.",
          DialogueId = 80170307,
          GUID = "C8B2ACFE",
          NextDialogue = 80170308,
          SpeakNpcId = 91502,
          Subtitle = "They lived on the outskirts of Elysium. He was a hunter, and she, a maid in the city. For years, they yearned for a child, yet fate remained unyielding to their prayers.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2ACFE"
        },
        [80170308] = {
          ContentEN = "Then, one day, while hunting in the forest, the man stumbled upon a wandering child — battered, bloodied, and trembling in the cold. A pitiful sight indeed. Without hesitation, he brought her home.",
          DialogueId = 80170308,
          GUID = "C8B2AD28",
          NextDialogue = 80170309,
          SpeakNpcId = 91502,
          Subtitle = "Then, one day, while hunting in the forest, the man stumbled upon a wandering child — battered, bloodied, and trembling in the cold. A pitiful sight indeed. Without hesitation, he brought her home.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AD28"
        },
        [80170309] = {
          ContentEN = "His wife bathed the child and found no visible wounds upon her frail form. Yet, the child seemed to have been deeply traumatized. No matter what they asked, she simply stared at them, unblinking and silent.",
          DialogueId = 80170309,
          GUID = "C8B2AD52",
          NextDialogue = 80170310,
          SpeakNpcId = 91502,
          Subtitle = "His wife bathed the child and found no visible wounds upon her frail form. Yet, the child seemed to have been deeply traumatized. No matter what they asked, she simply stared at them, unblinking and silent.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AD52"
        },
        [80170310] = {
          ContentEN = "Still, the couple took her in, tending to her with patience and care. In time, the girl, like a frost-laden bud beneath the warmth of spring, began to open herself to the world once more. And one day, at long last, she spoke.",
          DialogueId = 80170310,
          GUID = "C8B2AD7C",
          NextDialogue = 80170311,
          SpeakNpcId = 91502,
          Subtitle = "Still, the couple took her in, tending to her with patience and care. In time, the girl, like a frost-laden bud beneath the warmth of spring, began to open herself to the world once more. And one day, at long last, she spoke.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AD7C"
        },
        [80170311] = {
          ContentEN = "She told them she had lost her birth parents. After some deliberation, the couple chose to adopt her as their own. They showered her with kindness, and in return, she blossomed into a sweet and well-mannered daughter. Thus, beneath their humble roof, a family found its quiet harmony.",
          DialogueId = 80170311,
          GUID = "C8B2ADA6",
          NextOptions = {
            [1] = 801703111
          },
          SpeakNpcId = 91502,
          Subtitle = "She told them she had lost her birth parents. After some deliberation, the couple chose to adopt her as their own. They showered her with kindness, and in return, she blossomed into a sweet and well-mannered daughter. Thus, beneath their humble roof, a family found its quiet harmony.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2ADA6"
        },
        [80170312] = {
          ContentEN = "On the surface, yes. But beneath it all, the girl carried with her a terrible secret.",
          DialogueId = 80170312,
          FacialId = {
            [1] = "91502:Unhappy01"
          },
          GUID = "C8B2ADD0",
          NextDialogue = 80170313,
          SpeakNpcId = 91502,
          Subtitle = "On the surface, yes. But beneath it all, the girl carried with her a terrible secret.",
          TalkActionId = {
            [1] = "91502:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2ADD0"
        },
        [80170313] = {
          ContentEN = "She was born into a family of heretics, followers of the ancient Charon myths. As a result, her parents were executed, and yet she survived — saved by a mysterious healing gift that she possessed.",
          DialogueId = 80170313,
          GUID = "C8B2ADFA",
          NextDialogue = 80170314,
          SpeakNpcId = 91502,
          Subtitle = "She was born into a family of heretics, followers of the ancient Charon myths. As a result, her parents were executed, and yet she survived — saved by a mysterious healing gift that she possessed.",
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2ADFA"
        },
        [80170314] = {
          ContentEN = "With hands horribly mutilated, she dug herself free from their graves and fled into the wilderness, seeking refuge in the forests.",
          DialogueId = 80170314,
          GUID = "C8B2AE24",
          NextDialogue = 80170315,
          SpeakNpcId = 91502,
          Subtitle = "With hands horribly mutilated, she dug herself free from their graves and fled into the wilderness, seeking refuge in the forests.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AE24"
        },
        [80170315] = {
          ContentEN = "In Elysium, nothing was deemed more sinful than heresy. Had her secret been revealed, even if her adoptive parents did not have the heart to hand her over to the executioners, they would have undoubtedly abandoned her.",
          DialogueId = 80170315,
          GUID = "C8B2AE4E",
          NextDialogue = 80170316,
          SpeakNpcId = 91502,
          Subtitle = "In Elysium, nothing was deemed more sinful than heresy. Had her secret been revealed, even if her adoptive parents did not have the heart to hand her over to the executioners, they would have undoubtedly abandoned her.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AE4E"
        },
        [80170316] = {
          ContentEN = "Having at last found a place she could call \"home,\" the girl could not bear the thought of losing it. Thus, she chose to conceal her true identity, clinging to the fragile hope that the truth would remain undiscovered.",
          DialogueId = 80170316,
          GUID = "C8B2AE78",
          NextDialogue = 80170317,
          SpeakNpcId = 91502,
          Subtitle = "Having at last found a place she could call \"home,\" the girl could not bear the thought of losing it. Thus, she chose to conceal her true identity, clinging to the fragile hope that the truth would remain undiscovered.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AE78"
        },
        [80170317] = {
          ContentEN = "Time passed, and under the care of her adoptive parents, the girl grew. Her secret remained well-guarded, and as the years went by, she even forgot it herself. She began to believe that, with her new family, she could live a happy, peaceful life forever.",
          DialogueId = 80170317,
          GUID = "C8B2AEA2",
          NextDialogue = 80170318,
          SpeakNpcId = 91502,
          Subtitle = "Time passed, and under the care of her adoptive parents, the girl grew. Her secret remained well-guarded, and as the years went by, she even forgot it herself. She began to believe that, with her new family, she could live a happy, peaceful life forever.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AEA2"
        },
        [80170318] = {
          ContentEN = "When her adoptive mother suggested they travel to the city, to work and experience the world beyond, the girl did not hesitate. After all, they would merely be lowly maids in the houses of the nobility, unnoticed and insignificant.",
          DialogueId = 80170318,
          GUID = "C8B2AECC",
          NextDialogue = 80170319,
          SpeakNpcId = 91502,
          Subtitle = "When her adoptive mother suggested they travel to the city, to work and experience the world beyond, the girl did not hesitate. After all, they would merely be lowly maids in the houses of the nobility, unnoticed and insignificant.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AECC"
        },
        [80170319] = {
          ContentEN = "One day, while cleaning, her adoptive mother accidentally broke a valuable artefact. According to her employer's house rules, such a mistake would result in a flogging. Unable to bear the thought of her mother enduring such a punishment, the girl decided to take the blame herself.",
          DialogueId = 80170319,
          GUID = "C8B2AEF6",
          NextDialogue = 80170320,
          SpeakNpcId = 91502,
          Subtitle = "One day, while cleaning, her adoptive mother accidentally broke a valuable artefact. According to her employer's house rules, such a mistake would result in a flogging. Unable to bear the thought of her mother enduring such a punishment, the girl decided to take the blame herself.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AEF6"
        },
        [80170320] = {
          ContentEN = "As the flogging began, the whip tore into her skin, leaving a gaping wound. Yet, within moments, the wound healed, as though no harm had been done.",
          DialogueId = 80170320,
          GUID = "C8B2AF20",
          NextDialogue = 80170321,
          SpeakNpcId = 91502,
          Subtitle = "As the flogging began, the whip tore into her skin, leaving a gaping wound. Yet, within moments, the wound healed, as though no harm had been done.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AF20"
        },
        [80170321] = {
          ContentEN = "This \"miracle\" soon reached the ears of the house's master — Lord \"Generous.\" He rushed to the scene, and with a swift motion, plunged a knife into the girl's chest. She fought through the agony for minutes, only to rise again, alive.",
          DialogueId = 80170321,
          GUID = "C8B2AF4A",
          NextDialogue = 80170322,
          SpeakNpcId = 91502,
          Subtitle = "This \"miracle\" soon reached the ears of the house's master — Lord \"Generous.\" He rushed to the scene, and with a swift motion, plunged a knife into the girl's chest. She fought through the agony for minutes, only to rise again, alive.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AF4A"
        },
        [80170322] = {
          ContentEN = "Lord \"Generous\" took her away. Upon investigation, he discovered that she was the daughter of the two heretics from years past.",
          DialogueId = 80170322,
          FacialId = {
            [1] = "91502:Sad01"
          },
          GUID = "C8B2AF74",
          NextDialogue = 80170323,
          SpeakNpcId = 91502,
          Subtitle = "Lord \"Generous\" took her away. Upon investigation, he discovered that she was the daughter of the two heretics from years past.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AF74"
        },
        [80170323] = {
          ContentEN = "At first, he was enraged. But then, a \"brilliant\" idea crossed his mind: if he could exploit her power, which had never been seen in Elysium, masking it as a \"divine miracle,\" it would not only be profitable but would also thrust him into the spotlight.",
          DialogueId = 80170323,
          GUID = "C8B2AF9E",
          NextDialogue = 80170324,
          SpeakNpcId = 91502,
          Subtitle = "At first, he was enraged. But then, a \"brilliant\" idea crossed his mind: if he could exploit her power, which had never been seen in Elysium, masking it as a \"divine miracle,\" it would not only be profitable but would also thrust him into the spotlight.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AF9E"
        },
        [80170324] = {
          ContentEN = "To achieve this, however, he needed to conceal her true identity. So, he imprisoned her, created a new identity for her, and secretly had her adoptive mother executed.",
          DialogueId = 80170324,
          GUID = "C8B2AFC8",
          NextOptions = {
            [1] = 801703241
          },
          SpeakNpcId = 91502,
          Subtitle = "To achieve this, however, he needed to conceal her true identity. So, he imprisoned her, created a new identity for her, and secretly had her adoptive mother executed.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AFC8"
        },
        [80170325] = {
          ContentEN = "The girl was filled with deep regret. Had she not hidden her true identity in her desperate search for the warmth of a family, her kind, innocent adoptive parents would never have suffered such a fate.",
          DialogueId = 80170325,
          GUID = "C8B2AFF2",
          NextDialogue = 80170326,
          SpeakNpcId = 91502,
          Subtitle = "The girl was filled with deep regret. Had she not hidden her true identity in her desperate search for the warmth of a family, her kind, innocent adoptive parents would never have suffered such a fate.",
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AFF2"
        },
        [80170326] = {
          ContentEN = "Though the girl was rescued by the resistance during the Great Migration, she never sought out her adoptive father again. Their encounter had been a mistake from the beginning, and she did not want to bring any further misfortune upon him.",
          DialogueId = 80170326,
          GUID = "C8B2B01C",
          NextDialogue = 80170327,
          SpeakNpcId = 91502,
          Subtitle = "Though the girl was rescued by the resistance during the Great Migration, she never sought out her adoptive father again. Their encounter had been a mistake from the beginning, and she did not want to bring any further misfortune upon him.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B01C"
        },
        [80170327] = {
          ContentEN = "For decades, she could not rid herself of the burden of the past, constantly worrying about her adoptive father's well-being. In time, as my journey took me through Elysium, I visited him on her behalf.",
          DialogueId = 80170327,
          FacialId = {
            [1] = "91502:None"
          },
          GUID = "C8B2B046",
          NextDialogue = 80170328,
          SpeakNpcId = 91502,
          Subtitle = "For decades, she could not rid herself of the burden of the past, constantly worrying about her adoptive father's well-being. In time, as my journey took me through Elysium, I visited him on her behalf.",
          TalkActionId = {
            [1] = "91502:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B046"
        },
        [80170328] = {
          ContentEN = "By then, her adoptive father had grown old, his hair streaked with silver. He had spent much of his life in hiding, and when I showed up, he was astonished that anyone still remembered his name.",
          DialogueId = 80170328,
          GUID = "C8B2B070",
          NextDialogue = 80170329,
          SpeakNpcId = 91502,
          Subtitle = "By then, her adoptive father had grown old, his hair streaked with silver. He had spent much of his life in hiding, and when I showed up, he was astonished that anyone still remembered his name.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B070"
        },
        [80170329] = {
          ContentEN = "Honouring the girl's wishes, I did not reveal the true purpose of my visit. Instead, I simply sat with him as a Ferrywoman, reminiscing about days long past.",
          DialogueId = 80170329,
          GUID = "C8B2B09A",
          NextDialogue = 80170330,
          SpeakNpcId = 91502,
          Subtitle = "Honouring the girl's wishes, I did not reveal the true purpose of my visit. Instead, I simply sat with him as a Ferrywoman, reminiscing about days long past.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B09A"
        },
        [80170330] = {
          ContentEN = "He remembered everything vividly — the night he lost both his wife and daughter, the moment his life unravelled, casting him into a fugitive's existence, wandering from place to place in perpetual flight.",
          DialogueId = 80170330,
          GUID = "C8B2B0C4",
          NextDialogue = 80170331,
          SpeakNpcId = 91502,
          Subtitle = "He remembered everything vividly — the night he lost both his wife and daughter, the moment his life unravelled, casting him into a fugitive's existence, wandering from place to place in perpetual flight.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B0C4"
        },
        [80170331] = {
          ContentEN = "And yet, to my surprise, he told me he had no regrets in choosing to take the girl in.",
          DialogueId = 80170331,
          FacialId = {
            [1] = "91502:Shock01"
          },
          GUID = "C8B2B0EE",
          NextDialogue = 80170332,
          SpeakNpcId = 91502,
          Subtitle = "And yet, to my surprise, he told me he had no regrets in choosing to take the girl in.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B0EE"
        },
        [80170332] = {
          ContentEN = "He then handed me a small box — a keepsake containing his wife's ashes. He told me he had long been waiting for a Ferrywoman, so that her soul might finally find peace.",
          DialogueId = 80170332,
          GUID = "C8B2B118",
          NextDialogue = 80170333,
          SpeakNpcId = 91502,
          Subtitle = "He then handed me a small box — a keepsake containing his wife's ashes. He told me he had long been waiting for a Ferrywoman, so that her soul might finally find peace.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B118"
        },
        [80170333] = {
          ContentEN = "With quiet astonishment, I performed the long-overdue farewell ritual for his wife. To my surprise, even after all these years, I could still hear the whisper of her soul...",
          DialogueId = 80170333,
          GUID = "C8B2B142",
          NextDialogue = 80170334,
          SpeakNpcId = 91502,
          Subtitle = "With quiet astonishment, I performed the long-overdue farewell ritual for his wife. To my surprise, even after all these years, I could still hear the whisper of her soul...",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B142"
        },
        [80170334] = {
          ContentEN = "She spoke the same words as her husband: \"Thank you for becoming our daughter.\"",
          DialogueId = 80170334,
          FacialId = {
            [1] = "91502:Smile01"
          },
          GUID = "C8B2B16C",
          NextDialogue = 80170335,
          SpeakNpcId = 91502,
          Subtitle = "She spoke the same words as her husband: \"Thank you for becoming our daughter.\"",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B16C"
        },
        [80170335] = {
          ContentEN = "He then told me that, from the very beginning, they had known the girl's true identity. On the night her parents were executed, they watched as the executioners, torches in hand, marched into the forest.",
          DialogueId = 80170335,
          GUID = "C8B2B196",
          NextDialogue = 80170336,
          SpeakNpcId = 91502,
          Subtitle = "He then told me that, from the very beginning, they had known the girl's true identity. On the night her parents were executed, they watched as the executioners, torches in hand, marched into the forest.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B196"
        },
        [80170336] = {
          ContentEN = "And the next morning, when they saw the wandering girl, they recognized her at once. Fully aware of the consequences, they made their choice to take her in.",
          DialogueId = 80170336,
          GUID = "C8B2B1C0",
          NextDialogue = 80170337,
          SpeakNpcId = 91502,
          Subtitle = "And the next morning, when they saw the wandering girl, they recognized her at once. Fully aware of the consequences, they made their choice to take her in.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B1C0"
        },
        [80170337] = {
          ContentEN = "For them, meeting the girl, protecting her, and raising her brought great joy. Though it was a joy shadowed by danger, they embraced it without hesitation.",
          DialogueId = 80170337,
          GUID = "C8B2B1EA",
          NextDialogue = 80170338,
          SpeakNpcId = 91502,
          Subtitle = "For them, meeting the girl, protecting her, and raising her brought great joy. Though it was a joy shadowed by danger, they embraced it without hesitation.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B1EA"
        },
        [80170338] = {
          ContentEN = "The old man confided that his only regret was lacking the courage to leave sooner. Had he taken his wife and daughter away from Elysium earlier, perhaps they might still have been living a peaceful life together today.",
          DialogueId = 80170338,
          GUID = "C8B2B214",
          NextDialogue = 80170339,
          SpeakNpcId = 91502,
          Subtitle = "The old man confided that his only regret was lacking the courage to leave sooner. Had he taken his wife and daughter away from Elysium earlier, perhaps they might still have been living a peaceful life together today.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B214"
        },
        [80170339] = {
          ContentEN = "And so, in the years that followed, the once wronged hunter became a true \"heretic.\" For decades, he quietly aided Elysium's oppressed, guiding them across the border to freedom.",
          DialogueId = 80170339,
          GUID = "C8B2B23E",
          NextOptions = {
            [1] = 801703391
          },
          SpeakNpcId = 91502,
          Subtitle = "And so, in the years that followed, the once wronged hunter became a true \"heretic.\" For decades, he quietly aided Elysium's oppressed, guiding them across the border to freedom.",
          TalkActionId = {
            [1] = "91502:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B23E"
        },
        [80170340] = {
          ContentEN = "...I did not say it outright. Yet, from the quiet relief in his eyes, I believe he had already understood.",
          DialogueId = 80170340,
          GUID = "C8B2B268",
          NextDialogue = 80170341,
          SpeakNpcId = 91502,
          Subtitle = "...I did not say it outright. Yet, from the quiet relief in his eyes, I believe he had already understood.",
          TalkActionId = {
            [1] = "91502:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B268"
        },
        [80170341] = {
          ContentEN = "Though they may never meet again, knowing that their loved ones are safe is, perhaps, comfort enough.",
          DialogueId = 80170341,
          GUID = "C8B2B292",
          NextDialogue = 80170342,
          SpeakNpcId = 790008,
          Subtitle = "Though they may never meet again, knowing that their loved ones are safe is, perhaps, comfort enough.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B292"
        },
        [80170342] = {
          ContentEN = "This story's ending doesn't seem so tragic after all.",
          DialogueId = 80170342,
          GUID = "C8B2B2BC",
          NextDialogue = 80170343,
          SpeakNpcId = 790008,
          Subtitle = "This story's ending doesn't seem so tragic after all.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B2BC"
        },
        [80170343] = {
          ContentEN = "Indeed. Hearing his words, I found myself reflecting...",
          DialogueId = 80170343,
          GUID = "C8B2B2E6",
          NextDialogue = 80170344,
          SpeakNpcId = 91502,
          Subtitle = "Indeed. Hearing his words, I found myself reflecting...",
          TalkActionId = {
            [1] = "91502:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B2E6"
        },
        [80170344] = {
          ContentEN = "As long as we live, mistakes are inevitable. Some stem from a narrow vision, others from misplaced hope, and at times, even willful ignorance.",
          DialogueId = 80170344,
          FacialId = {
            [1] = "91502:Confident01"
          },
          GUID = "C8B2B310",
          NextDialogue = 80170345,
          SpeakNpcId = 91502,
          Subtitle = "As long as we live, mistakes are inevitable. Some stem from a narrow vision, others from misplaced hope, and at times, even willful ignorance.",
          TalkActionId = {
            [1] = "91502:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B310"
        },
        [80170345] = {
          ContentEN = "However, a misguided choice does not always yield a misguided outcome. The taste of its sweetness or bitterness is known only to those who have lived through it.",
          DialogueId = 80170345,
          GUID = "C8B2B33A",
          NextDialogue = 80170346,
          SpeakNpcId = 91502,
          Subtitle = "However, a misguided choice does not always yield a misguided outcome. The taste of its sweetness or bitterness is known only to those who have lived through it.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B33A"
        },
        [80170346] = {
          ContentEN = "What truly matters, more than the mistake itself, is the future that lies before us.",
          DialogueId = 80170346,
          GUID = "C8B2B364",
          NextDialogue = 80170347,
          SpeakNpcId = 91502,
          Subtitle = "What truly matters, more than the mistake itself, is the future that lies before us.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B364"
        },
        [80170347] = {
          ContentEN = "It grants us the opportunity to make amends, to bring about change, and to transform what we've endured into something more meaningful.",
          DialogueId = 80170347,
          GUID = "C8B2B38E",
          NextDialogue = 80170348,
          SpeakNpcId = 91502,
          Subtitle = "It grants us the opportunity to make amends, to bring about change, and to transform what we've endured into something more meaningful.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B38E"
        },
        [80170348] = {
          ContentEN = "Perhaps that is why, when the old man spoke to me of his past, there was neither regret nor sorrow in his eyes — only the quiet contentment of one who has made peace with his journey.",
          DialogueId = 80170348,
          GUID = "C8B2B3B8",
          NextOptions = {
            [1] = 801703481
          },
          SpeakNpcId = 91502,
          Subtitle = "Perhaps that is why, when the old man spoke to me of his past, there was neither regret nor sorrow in his eyes — only the quiet contentment of one who has made peace with his journey.",
          TalkActionId = {
            [1] = "91502:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B3B8"
        },
        [80170349] = {
          ContentEN = "Thank you for sharing this story with me. I've learned so much today, just like before.",
          DialogueId = 80170349,
          GUID = "C8B2B3E2",
          NextDialogue = 80170350,
          SpeakNpcId = 790008,
          Subtitle = "Thank you for sharing this story with me. I've learned so much today, just like before.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B3E2"
        },
        [80170350] = {
          ContentEN = "Hehe, it is I who should thank you.",
          DialogueId = 80170350,
          FacialId = {
            [1] = "91502:Smile01"
          },
          GUID = "C8B2B40C",
          NextDialogue = 80170351,
          SpeakNpcId = 91502,
          Subtitle = "Hehe, it is I who should thank you.",
          TalkActionId = {
            [1] = "91502:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B40C"
        },
        [80170351] = {
          ContentEN = "Perhaps it's my age, but I do tend to be long-winded. I appreciate your patience — for keeping this old lady company and listening to my endless ramblings about the past.",
          DialogueId = 80170351,
          GUID = "C8B2B436",
          SpeakNpcId = 91502,
          Subtitle = "Perhaps it's my age, but I do tend to be long-winded. I appreciate your patience — for keeping this old lady company and listening to my endless ramblings about the past.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B436"
        },
        [80170401] = {
          Camera = "135.91098,22.045166,124.542297,0.000012,1.800007,-136.994522,35.0,158.845352,false,Manual,3.0",
          ContentEN = "Ah, you've arrived, my child. Tell me, what is it you wish to speak of today?",
          DialogueId = 80170401,
          FacialId = {
            [1] = "91502:Smile01"
          },
          GUID = "C8B2BC6A",
          LookAt = {
            [1] = "91502:p(18000P1)"
          },
          NextOptions = {
            [1] = 801704011
          },
          SpeakNpcId = 91502,
          Subtitle = "Ah, you've arrived, my child. Tell me, what is it you wish to speak of today?",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BC6A"
        },
        [80170402] = {
          ContentEN = "Lady Nifle, today... I'd like to hear your story.",
          DialogueId = 80170402,
          GUID = "C8B2BC94",
          NextDialogue = 80170403,
          SpeakNpcId = 790008,
          Subtitle = "Lady Nifle, today... I'd like to hear your story.",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BC94"
        },
        [80170403] = {
          ContentEN = "My story, hmm... You are an insightful child. I suspect you have already caught glimpses of it, have you not?",
          DialogueId = 80170403,
          GUID = "C8B2BCBE",
          NextOptions = {
            [1] = 801704031,
            [2] = 801704032
          },
          SpeakNpcId = 91502,
          Subtitle = "My story, hmm... You are an insightful child. I suspect you have already caught glimpses of it, have you not?",
          TalkActionId = {
            [1] = "91502:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BCBE"
        },
        [80170404] = {
          ContentEN = "The stories you've told me... they are all your own experiences, aren't they?",
          DialogueId = 80170404,
          GUID = "C8B2BCE8",
          NextDialogue = 80170405,
          SpeakNpcId = 790008,
          Subtitle = "The stories you've told me... they are all your own experiences, aren't they?",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BCE8"
        },
        [80170405] = {
          ContentEN = "Indeed.",
          DialogueId = 80170405,
          GUID = "C8B2BD12",
          NextDialogue = 80170407,
          SpeakNpcId = 91502,
          Subtitle = "Indeed.",
          TalkActionId = {
            [1] = "91502:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BD12"
        },
        [80170406] = {
          ContentEN = "The truth is, my story is interwoven with the very tales I have shared with you.",
          DialogueId = 80170406,
          GUID = "C8B2BD3C",
          NextDialogue = 80170407,
          SpeakNpcId = 91502,
          Subtitle = "The truth is, my story is interwoven with the very tales I have shared with you.",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BD3C"
        },
        [80170407] = {
          ContentEN = "They are not merely events that happened; they are, in truth, fragments of my own past.",
          DialogueId = 80170407,
          GUID = "C8B2BD66",
          NextDialogue = 80170408,
          SpeakNpcId = 91502,
          Subtitle = "They are not merely events that happened; they are, in truth, fragments of my own past.",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BD66"
        },
        [80170408] = {
          ContentEN = "I am the woman who bore a gift yet failed to ease people's suffering. I am the helpless girl once imprisoned in the temple's cold embrace. I am the child whose very existence became the harbinger of misfortune for those who took her in.",
          DialogueId = 80170408,
          GUID = "C8B2BD90",
          NextDialogue = 80170409,
          SpeakNpcId = 91502,
          Subtitle = "I am the woman who bore a gift yet failed to ease people's suffering. I am the helpless girl once imprisoned in the temple's cold embrace. I am the child whose very existence became the harbinger of misfortune for those who took her in.",
          TalkActionId = {
            [1] = "91502:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BD90"
        },
        [80170409] = {
          ContentEN = "Right... but still, I wish to hear it from you directly — not as an observer, but as you, Nifle, the protagonist of your own story.",
          DialogueId = 80170409,
          GUID = "C8B2BDBA",
          NextDialogue = 80170410,
          SpeakNpcId = 790008,
          Subtitle = "Right... but still, I wish to hear it from you directly — not as an observer, but as you, Nifle, the protagonist of your own story.",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BDBA"
        },
        [80170410] = {
          ContentEN = "Ah... I see. Very well. Since you wish to hear it, I shall, albeit uncharacteristically, recount my past.",
          DialogueId = 80170410,
          GUID = "C8B2BDE4",
          NextDialogue = 80170411,
          SpeakNpcId = 91502,
          Subtitle = "Ah... I see. Very well. Since you wish to hear it, I shall, albeit uncharacteristically, recount my past.",
          TalkActionId = {
            [1] = "91502:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BDE4"
        },
        [80170411] = {
          ContentEN = "I was born in Elysium, into a family devoted to the ancient Charon myths.",
          DialogueId = 80170411,
          GUID = "C8B2BE0E",
          NextDialogue = 80170412,
          SpeakNpcId = 91502,
          Subtitle = "I was born in Elysium, into a family devoted to the ancient Charon myths.",
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BE0E"
        },
        [80170412] = {
          ContentEN = "When I was ten, my parents were executed for heresy. I was meant to perish alongside them. Yet, in that moment, I unexpectedly awakened as a Daimon, gaining the power of immortality. And so, I survived.",
          DialogueId = 80170412,
          FacialId = {
            [1] = "91502:Sad01"
          },
          GUID = "C8B2BE38",
          NextDialogue = 80170413,
          SpeakNpcId = 91502,
          Subtitle = "When I was ten, my parents were executed for heresy. I was meant to perish alongside them. Yet, in that moment, I unexpectedly awakened as a Daimon, gaining the power of immortality. And so, I survived.",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BE38"
        },
        [80170413] = {
          ContentEN = "Orphaned and adrift, I wandered the forests until a passing hunter found me. He took me in, offering the quiet warmth of a home I had lost.",
          DialogueId = 80170413,
          GUID = "C8B2BE62",
          NextDialogue = 80170414,
          SpeakNpcId = 91502,
          Subtitle = "Orphaned and adrift, I wandered the forests until a passing hunter found me. He took me in, offering the quiet warmth of a home I had lost.",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BE62"
        },
        [80170414] = {
          ContentEN = "At eighteen, my true nature was inadvertently exposed. Word soon reached Lord \"Generous,\" who bestowed upon me the title of \"the Blessed One\" — a crown woven of thorns.",
          DialogueId = 80170414,
          GUID = "C8B2BE8C",
          NextDialogue = 80170415,
          SpeakNpcId = 91502,
          Subtitle = "At eighteen, my true nature was inadvertently exposed. Word soon reached Lord \"Generous,\" who bestowed upon me the title of \"the Blessed One\" — a crown woven of thorns.",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BE8C"
        },
        [80170415] = {
          ContentEN = "For years, my world was confined within the walls of a small temple, while Lord \"Generous\" reaped immense wealth from selling my blood.",
          DialogueId = 80170415,
          GUID = "C8B2BEB6",
          NextDialogue = 80170416,
          SpeakNpcId = 91502,
          Subtitle = "For years, my world was confined within the walls of a small temple, while Lord \"Generous\" reaped immense wealth from selling my blood.",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BEB6"
        },
        [80170416] = {
          ContentEN = "It was not until two brave souls — the young scholar and noblewoman from my second tale — rescued me from that lasting nightmare. They were my saviours, my dearest friends, and the ones who first cast light upon my path ahead.",
          DialogueId = 80170416,
          FacialId = {
            [1] = "91502:Confident01"
          },
          GUID = "C8B2BEE0",
          NextDialogue = 80170417,
          SpeakNpcId = 91502,
          Subtitle = "It was not until two brave souls — the young scholar and noblewoman from my second tale — rescued me from that lasting nightmare. They were my saviours, my dearest friends, and the ones who first cast light upon my path ahead.",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BEE0"
        },
        [80170417] = {
          ContentEN = "Later, Erika fell in battle during our journey north. As for Lexis, though he escaped, he never found the answers he sought for his ideal world. In the end, he faded away amidst stacks of unfinished manuscripts, his vision left incomplete.",
          DialogueId = 80170417,
          GUID = "C8B2BF0A",
          NextDialogue = 80170418,
          SpeakNpcId = 91502,
          Subtitle = "Later, Erika fell in battle during our journey north. As for Lexis, though he escaped, he never found the answers he sought for his ideal world. In the end, he faded away amidst stacks of unfinished manuscripts, his vision left incomplete.",
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BF0A"
        },
        [80170418] = {
          ContentEN = "During my years in Aethyrie, I adopted a child. It was my first experience as a caretaker, witnessing a life unfold before my eyes.",
          DialogueId = 80170418,
          GUID = "C8B2BF34",
          NextDialogue = 80170419,
          SpeakNpcId = 91502,
          Subtitle = "During my years in Aethyrie, I adopted a child. It was my first experience as a caretaker, witnessing a life unfold before my eyes.",
          TalkActionId = {
            [1] = "91502:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BF34"
        },
        [80170419] = {
          ContentEN = "I watched her grow — from a tiny infant wrapped in swaddling clothes to a radiant young woman, and later into a figure of calm wisdom. I remember her first cries, her first words, the first time she recited the ancient verses...",
          DialogueId = 80170419,
          GUID = "C8B2BF5E",
          NextDialogue = 80170420,
          SpeakNpcId = 91502,
          Subtitle = "I watched her grow — from a tiny infant wrapped in swaddling clothes to a radiant young woman, and later into a figure of calm wisdom. I remember her first cries, her first words, the first time she recited the ancient verses...",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BF5E"
        },
        [80170420] = {
          ContentEN = "I recall her endless debates with Lexis, and the solemn moment when she accepted the key to his library as he lay upon his deathbed.",
          DialogueId = 80170420,
          GUID = "C8B2BF88",
          NextDialogue = 80170421,
          SpeakNpcId = 91502,
          Subtitle = "I recall her endless debates with Lexis, and the solemn moment when she accepted the key to his library as he lay upon his deathbed.",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BF88"
        },
        [80170421] = {
          ContentEN = "Each change in her filled me with joy and pride. Yet, I remained painfully aware that, like Erika and Lexis, she too was bound by the limits of mortality. She could not stay by my side forever.",
          DialogueId = 80170421,
          GUID = "C8B2BFB2",
          NextDialogue = 80170422,
          SpeakNpcId = 91502,
          Subtitle = "Each change in her filled me with joy and pride. Yet, I remained painfully aware that, like Erika and Lexis, she too was bound by the limits of mortality. She could not stay by my side forever.",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BFB2"
        },
        [80170422] = {
          ContentEN = "In the end, they all left me. Once, I mourned their passing. But after meeting the two sisters who sought my blood, and bearing witness to countless partings between life and death, I came to accept the impermanence of this world.",
          DialogueId = 80170422,
          FacialId = {
            [1] = "91502:None"
          },
          GUID = "C8B2BFDC",
          NextDialogue = 80170423,
          SpeakNpcId = 91502,
          Subtitle = "In the end, they all left me. Once, I mourned their passing. But after meeting the two sisters who sought my blood, and bearing witness to countless partings between life and death, I came to accept the impermanence of this world.",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BFDC"
        },
        [80170423] = {
          ContentEN = "I have let go of both joy and sorrow, renounced desire, and no longer grieve or rage at the suffering woven into the fabric of existence. For the past nine centuries, I have wandered across Atlasia, guiding the souls of the departed.",
          DialogueId = 80170423,
          GUID = "C8B2C006",
          NextDialogue = 80170424,
          SpeakNpcId = 91502,
          Subtitle = "I have let go of both joy and sorrow, renounced desire, and no longer grieve or rage at the suffering woven into the fabric of existence. For the past nine centuries, I have wandered across Atlasia, guiding the souls of the departed.",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C006"
        },
        [80170424] = {
          ContentEN = "Now, I remain in Hyperborea for a time, drawn here by a child whose face is strangely familiar. Yet, I do not seek to meddle in conflicts or alter the course of fate. I wish only to bear witness to her story.",
          DialogueId = 80170424,
          GUID = "C8B2C030",
          NextDialogue = 80170425,
          SpeakNpcId = 91502,
          Subtitle = "Now, I remain in Hyperborea for a time, drawn here by a child whose face is strangely familiar. Yet, I do not seek to meddle in conflicts or alter the course of fate. I wish only to bear witness to her story.",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C030"
        },
        [80170425] = {
          ContentEN = "Soon enough, I will resume my journey. Nothing in this world will ever truly bring my wandering to a halt — unless, at last, death itself chooses to embrace me.",
          DialogueId = 80170425,
          GUID = "C8B2C05A",
          NextDialogue = 80170426,
          SpeakNpcId = 91502,
          Subtitle = "Soon enough, I will resume my journey. Nothing in this world will ever truly bring my wandering to a halt — unless, at last, death itself chooses to embrace me.",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C05A"
        },
        [80170426] = {
          ContentEN = "—And that is my story. Tell me, my child, does it sate your curiosity?",
          DialogueId = 80170426,
          GUID = "C8B2C084",
          NextOptions = {
            [1] = 801704261
          },
          SpeakNpcId = 91502,
          Subtitle = "—And that is my story. Tell me, my child, does it sate your curiosity?",
          TalkActionId = {
            [1] = "91502:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C084"
        },
        [80170427] = {
          ContentEN = "I would still like to know... before you assumed all these roles, before you gained immortality — what was Nifle like, back then?",
          DialogueId = 80170427,
          GUID = "C8B2C0AE",
          NextDialogue = 80170428,
          SpeakNpcId = 790008,
          Subtitle = "I would still like to know... before you assumed all these roles, before you gained immortality — what was Nifle like, back then?",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C0AE"
        },
        [80170428] = {
          ContentEN = "...",
          DialogueId = 80170428,
          FacialId = {
            [1] = "91502:Shock01"
          },
          GUID = "C8B2C0D8",
          NextDialogue = 80170429,
          SpeakNpcId = 91502,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C0D8"
        },
        [80170429] = {
          ContentEN = "You are the first to ask of my childhood. Many have been curious about my past, but none have sought to know the life I led before fate wove me into grander tales. Compared to what followed, it was quite unremarkable.",
          DialogueId = 80170429,
          GUID = "C8B2C102",
          NextDialogue = 80170430,
          SpeakNpcId = 91502,
          Subtitle = "You are the first to ask of my childhood. Many have been curious about my past, but none have sought to know the life I led before fate wove me into grander tales. Compared to what followed, it was quite unremarkable.",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C102"
        },
        [80170430] = {
          ContentEN = "Let me think...",
          DialogueId = 80170430,
          FacialId = {
            [1] = "91502:Think01"
          },
          GUID = "C8B2C12C",
          NextDialogue = 80170431,
          SpeakNpcId = 91502,
          Subtitle = "Let me think...",
          TalkActionId = {
            [1] = "91502:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C12C"
        },
        [80170431] = {
          ContentEN = "My first home — the one of my birth — lay deep within the northern forests of Elysium. There were no churches, no nobility — only the soft rustle of hares darting through the underbrush, and the fragrance of wild berries.",
          DialogueId = 80170431,
          GUID = "C8B2C156",
          NextDialogue = 80170432,
          SpeakNpcId = 91502,
          Subtitle = "My first home — the one of my birth — lay deep within the northern forests of Elysium. There were no churches, no nobility — only the soft rustle of hares darting through the underbrush, and the fragrance of wild berries.",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C156"
        },
        [80170432] = {
          ContentEN = "My earliest memories are of dappled sunlight filtering through the leaves, and the gentle murmur of a stream winding its way through the quiet woods.",
          DialogueId = 80170432,
          GUID = "C8B2C180",
          NextDialogue = 80170433,
          SpeakNpcId = 91502,
          Subtitle = "My earliest memories are of dappled sunlight filtering through the leaves, and the gentle murmur of a stream winding its way through the quiet woods.",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C180"
        },
        [80170433] = {
          ContentEN = "In those days, I was no different from any other child. I would beg my father to take me into the forest to play, and I would ignore my mother's gentle warnings, splashing carelessly in the stream.",
          DialogueId = 80170433,
          GUID = "C8B2C1AA",
          NextDialogue = 80170434,
          SpeakNpcId = 91502,
          Subtitle = "In those days, I was no different from any other child. I would beg my father to take me into the forest to play, and I would ignore my mother's gentle warnings, splashing carelessly in the stream.",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C1AA"
        },
        [80170434] = {
          ContentEN = "My mother, too, was a Ferrywoman. Strangers would pass through the forest, entrusting her with small caskets. Under the moonlight, she would dance, letting them drift down the river's current.",
          DialogueId = 80170434,
          GUID = "C8B2C1D4",
          NextDialogue = 80170435,
          SpeakNpcId = 91502,
          Subtitle = "My mother, too, was a Ferrywoman. Strangers would pass through the forest, entrusting her with small caskets. Under the moonlight, she would dance, letting them drift down the river's current.",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C1D4"
        },
        [80170435] = {
          ContentEN = "Once, I asked her what lay within those caskets. She told me they carried what people cherished and missed dearly.",
          DialogueId = 80170435,
          GUID = "C8B2C1FE",
          NextDialogue = 80170436,
          SpeakNpcId = 91502,
          Subtitle = "Once, I asked her what lay within those caskets. She told me they carried what people cherished and missed dearly.",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C1FE"
        },
        [80170436] = {
          ContentEN = "So I asked, \"Why would people cast away what they held dear?\" She said, \"Because to move forward, one must learn to let go.\"",
          DialogueId = 80170436,
          GUID = "C8B2C228",
          NextDialogue = 80170437,
          SpeakNpcId = 91502,
          Subtitle = "So I asked, \"Why would people cast away what they held dear?\" She said, \"Because to move forward, one must learn to let go.\"",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C228"
        },
        [80170437] = {
          ContentEN = "I did not understand. Sensing my confusion, my father only smiled, ruffled my hair, and said, \"One day, when you are older, you will understand.\"",
          DialogueId = 80170437,
          GUID = "C8B2C252",
          NextDialogue = 80170438,
          SpeakNpcId = 91502,
          Subtitle = "I did not understand. Sensing my confusion, my father only smiled, ruffled my hair, and said, \"One day, when you are older, you will understand.\"",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C252"
        },
        [80170438] = {
          ContentEN = "But they never lived to see that day. The moment they were executed, the carefree days of the young Nifle came to an end.",
          DialogueId = 80170438,
          FacialId = {
            [1] = "91502:Sad01"
          },
          GUID = "C8B2C27C",
          NextOptions = {
            [1] = 801704381
          },
          SpeakNpcId = 91502,
          Subtitle = "But they never lived to see that day. The moment they were executed, the carefree days of the young Nifle came to an end.",
          TalkActionId = {
            [1] = "91502:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C27C"
        },
        [80170439] = {
          ContentEN = "At times, memories of that distant past resurface. But unlike most, I do not cling to them with longing or nostalgia. I simply let them drift through my thoughts, like fallen leaves carried by the wind.",
          DialogueId = 80170439,
          FacialId = {
            [1] = "91502:None"
          },
          GUID = "C8B2C2A6",
          NextDialogue = 80170440,
          SpeakNpcId = 91502,
          Subtitle = "At times, memories of that distant past resurface. But unlike most, I do not cling to them with longing or nostalgia. I simply let them drift through my thoughts, like fallen leaves carried by the wind.",
          TalkActionId = {
            [1] = "91502:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C2A6"
        },
        [80170440] = {
          ContentEN = "To me, the past — like all that has come and gone — is simply another thread woven into the fabric of my existence, neither weighted with sorrow nor imbued with special meaning.",
          DialogueId = 80170440,
          GUID = "C8B2C2D0",
          NextDialogue = 80170441,
          SpeakNpcId = 91502,
          Subtitle = "To me, the past — like all that has come and gone — is simply another thread woven into the fabric of my existence, neither weighted with sorrow nor imbued with special meaning.",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C2D0"
        },
        [80170441] = {
          ContentEN = "And yet, as I recount these tales to you, I sense the faintest of ripples stirring within me...",
          DialogueId = 80170441,
          GUID = "C8B2C2FA",
          NextDialogue = 80170442,
          SpeakNpcId = 91502,
          Subtitle = "And yet, as I recount these tales to you, I sense the faintest of ripples stirring within me...",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C2FA"
        },
        [80170442] = {
          ContentEN = "...I find myself weary. If you do not mind, I shall rest here for a moment.",
          DialogueId = 80170442,
          FacialId = {
            [1] = "91502:Close"
          },
          GUID = "C8B2C324",
          NextDialogue = 80170443,
          SpeakNpcId = 91502,
          Subtitle = "...I find myself weary. If you do not mind, I shall rest here for a moment.",
          TalkActionId = {
            [1] = "91502:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C324"
        },
        [80170443] = {
          ContentEN = "(As Lady Nifle speaks, she closes her eyes, her head gently coming to rest against your shoulder.)",
          DialogueId = 80170443,
          GUID = "C8B2C34E",
          IsBlack = 1,
          NextDialogue = 80170444,
          Subtitle = "(As Lady Nifle speaks, she closes her eyes, her head gently coming to rest against your shoulder.)",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C34E"
        },
        [80170444] = {
          ContentEN = "(Her breathing slows, steady and serene, and a faint smile graces her lips. It seems she has drifted into a peaceful dream.)",
          DialogueId = 80170444,
          GUID = "C8B2C378",
          IsBlack = 1,
          NextDialogue = 80170445,
          Subtitle = "(Her breathing slows, steady and serene, and a faint smile graces her lips. It seems she has drifted into a peaceful dream.)",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C378"
        },
        [80170445] = {
          ContentEN = "(A dream laced with the sweet scent of wild berries, bathed in the golden warmth of sunlight, where perhaps, a hare flits playfully through the underbrush in the distance...)",
          DialogueId = 80170445,
          GUID = "C8B2C3A2",
          IsBlack = 1,
          Subtitle = "(A dream laced with the sweet scent of wild berries, bathed in the golden warmth of sunlight, where perhaps, a hare flits playfully through the underbrush in the distance...)",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C3A2"
        },
