        },
        [80180110] = {
          ContentEN = "Every time Emilia talked about the Academy, she'd cry. She always regretted going there.",
          DialogueId = 80180110,
          GUID = "C8B8F54C",
          NextDialogue = 80180111,
          SpeakNpcId = 790059,
          Subtitle = "Every time Emilia talked about the Academy, she'd cry. She always regretted going there.",
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F54C"
        },
        [80180111] = {
          Camera = "114.473145,81.809021,158.171875,0.000098,-23.197474,-77.990166,30.000002,247.327988,false,DoNotOverride,3.162369",
          ContentEN = "You're not Emilia! ...Who are you?",
          DialogueId = 80180111,
          FinalCamera = "110.792969,99.114258,165.755859,0.000092,-22.997458,-77.989754,30.000002,247.327988,false,DoNotOverride,3.162369",
