        [80180114] = {
          ContentEN = "I've become so forgetful lately... I can barely tell dream from waking. And recently... I keep seeing Emilia. As if she were still alive.",
          DialogueId = 80180114,
          GUID = "C8B8F5F4",
          NextDialogue = 80180115,
          SpeakNpcId = 790059,
          Subtitle = "I've become so forgetful lately... I can barely tell dream from waking. And recently... I keep seeing Emilia. As if she were still alive.",
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F5F4"
        },
        [80180115] = {
