          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F648"
        },
        [80180117] = {
          ContentEN = "No, child. Don't be. I remember now. Emilia was buried a month ago. A kind nurse wheeled me to the service. I left her old rubber duck on the grave — the one she always played with.",
          DialogueId = 80180117,
          GUID = "C8B8F672",
          NextDialogue = 80180118,
