          Subtitle = "Ugh... aahhh...",
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F7EC"
        },
        [80180127] = {
          ContentEN = "(Mr Gaston's pain flared up again. His fists clenched the sheets, veins bulging. He wasn't clinging to life — he was clinging to dignity. The last thing a soldier has left.)",
          DialogueId = 80180127,
          GUID = "C8B8F816",
          IsBlack = 1,
          NextDialogue = 80180128,
          Subtitle = "(Mr Gaston's pain flared up again. His fists clenched the sheets, veins bulging. He wasn't clinging to life — he was clinging to dignity. The last thing a soldier has left.)",
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F816"
        },
        [80180128] = {
          Camera = "-196.821289,36.408081,111.78125,0.000072,-0.789276,-6.604747,40.000011,311.952545,false,Manual,2.256478",
          ContentEN = "Aaaghhh—!",
          DialogueId = 80180128,
          FinalCamera = "-228.835938,40.114746,112.220703,0.000072,-0.789276,-6.604747,40.000011,311.952545,false,Manual,2.256478",
          GUID = "C8B8F840",
          NextDialogue = 80180129,
          SpeakNpcId = 790059,
          Subtitle = "Aaaghhh—!",
          ToFinalCameraBlendTime = 0.5,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F840"
        },
        [80180129] = {
          Camera = "146.449707,-106.377991,109.685547,0.000106,5.210492,114.589401,40.000011,311.952545,false,Manual,2.256478",
          ContentEN = "Miss Theodore — please. Just shoot me. I'm worthless now... I can't even get out of this bed. And now even my only daughter's...",
          DialogueId = 80180129,
          FinalCamera = "141.276367,-109.157471,109.685547,0.000106,5.210492,112.589111,40.000011,311.952545,false,Manual,2.256478",
          GUID = "C8B8F86A",
          NextDialogue = 80180130,
          SpeakNpcId = 790059,
          Subtitle = "Miss Theodore — please. Just shoot me. I'm worthless now... I can't even get out of this bed. And now even my only daughter's...",
          TalkActionId = {
            [1] = "790045:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F86A"
        },
        [80180130] = {
          ContentEN = "I'll put it in my will — swear it was my choice. I've got no family left anyway. You can even take my old house!",
          DialogueId = 80180130,
          GUID = "C8B8F894",
          NextDialogue = 80180131,
          SpeakNpcId = 790059,
          Subtitle = "I'll put it in my will — swear it was my choice. I've got no family left anyway. You can even take my old house!",
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F894"
        },
        [80180131] = {
          Camera = "9.807129,54.86792,159.228516,-28.800745,-17.989195,-27.007662,40.000011,311.952545,false,DoNotOverride,2.256478",
          ContentEN = "Please, I'm begging you — put me out of my misery! Or at least... cut off the other leg!",
          DialogueId = 80180131,
          FinalCamera = "-10.913086,65.429382,166.779297,-18.000868,-17.989195,-27.007536,40.000011,311.952545,false,DoNotOverride,2.256478",
          GUID = "C8B8F8BE",
          NextDialogue = 80180132,
          SpeakNpcId = 790059,
          Subtitle = "Please, I'm begging you — put me out of my misery! Or at least... cut off the other leg!",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F8BE"
        },
        [80180132] = {
