        },
        [80180133] = {
          Camera = "-328.205566,88.299622,110.056641,-0.001007,2.210365,-3.410769,40.000011,466.053558,false,Manual,1.2",
          ContentEN = "Please hang in there! Just a little longer! One year... no — six months! I swear, by the Emerald Order, I'll find a cure!",
          DialogueId = 80180133,
          FinalCamera = "-329.355469,68.979004,110.056641,-0.001007,2.210365,-0.410614,40.000011,466.053558,false,Manual,1.2",
          GUID = "C8B8F912",
          NextDialogue = 80180134,
          SpeakNpcId = 790045,
          Subtitle = "Please hang in there! Just a little longer! One year... no — six months! I swear, by the Emerald Order, I'll find a cure!",
          TalkActionId = {
            [1] = "790045:Talk02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F912"
        },
        [80180134] = {
          ContentEN = "Please — don't give up. Emilia would never have wanted that.",
          DialogueId = 80180134,
          GUID = "C8B8F93C",
          NextDialogue = 80180135,
          SpeakNpcId = 790045,
          Subtitle = "Please — don't give up. Emilia would never have wanted that.",
