        [80180136] = {
          ContentEN = "(After the episode passed, the bed finally stilled. Mr Gaston drifted off, sobbing quietly. Whether it was the pain or Emilia's name, I couldn't tell — but something had soothed him.)",
          DialogueId = 80180136,
          GUID = "C8B8F990",
          IsBlack = 1,
          NextDialogue = 80180137,
          SpeakNpcId = 790045,
          Subtitle = "(After the episode passed, the bed finally stilled. Mr Gaston drifted off, sobbing quietly. Whether it was the pain or Emilia's name, I couldn't tell — but something had soothed him.)",
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F990"
        },
        [80180137] = {
          ContentEN = "(For some, pain is a fate much crueller — and more humiliating — than death. Like a river stone worn smooth over time, it grinds down even the toughest — stripping away their pride and fire.)",
          DialogueId = 80180137,
          GUID = "C8B8F9BA",
          IsBlack = 1,
          NextDialogue = 80180138,
          SpeakNpcId = 790045,
          Subtitle = "(For some, pain is a fate much crueller — and more humiliating — than death. Like a river stone worn smooth over time, it grinds down even the toughest — stripping away their pride and fire.)",
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F9BA"
        },
        [80180138] = {
          ContentEN = "(His comrades and daughter rest in the public cemetery. And this small white bed... is his grave.)",
          DialogueId = 80180138,
          GUID = "C8B8F9E4",
          IsBlack = 1,
          NextDialogue = 80180139,
          SpeakNpcId = 790045,
          Subtitle = "(His comrades and daughter rest in the public cemetery. And this small white bed... is his grave.)",
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F9E4"
        },
        [80180139] = {
          ContentEN = "(That day, by his bedside, I finally made that decision.)",
          DialogueId = 80180139,
          GUID = "C8B8FA0E",
          IsBlack = 1,
          SpeakNpcId = 790045,
          Subtitle = "(That day, by his bedside, I finally made that decision.)",
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8FA0E"
        },
        [80180201] = {
          Camera = "-21.269043,-387.99707,181.142334,0.000059,-9.599646,87.198402,30.000008,489.123169,false,Manual,1.2",
