        [80180353] = {
          Camera = "-9.892578,-94.234375,107.247437,0.000138,8.803205,60.757439,45.0,317.18219,false,Manual,6.360716",
          ContentEN = "I had bested my classmates, survived experiments, overcome pain... I once thought I was invincible.\nBut now I understand — there are far more things I cannot conquer... than those I can.",
          DialogueId = 80180353,
          GUID = "C8B91D2A",
          IsBlack = 1,
          NextDialogue = 80180354,
          SpeakNpcId = 790045,
          Subtitle = "I had bested my classmates, survived experiments, overcome pain... I once thought I was invincible.\nBut now I understand — there are far more things I cannot conquer... than those I can.",
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91D2A"
        },
        [80180354] = {
          Camera = "47.957031,-1250.3125,16.771729,0.000155,3.202962,92.956001,45.0,317.18219,false,Manual,6.360716",
          ContentEN = "Still, whatever lies ahead... When this battle ends... Whether I make it out alive, or only my soul returns —\nI hope I can carry these words to Sibylle Mason—",
          DialogueId = 80180354,
          FinalCamera = "76.232422,-1248.960938,16.771729,0.000158,3.202962,93.755997,45.0,317.18219,false,Manual,6.360716",
          GUID = "C8B91D54",
          IsBlack = 1,
          SpeakNpcId = 790045,
          Subtitle = "Still, whatever lies ahead... When this battle ends... Whether I make it out alive, or only my soul returns —\nI hope I can carry these words to Sibylle Mason—",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91D54"
        },
        [80180355] = {
