        },
        [80190001] = {
          ContentEN = "Free food and drink? Don't mind if I do — only a fool would turn down a freebie.",
          DialogueId = 80190001,
          GUID = "C8BF4C0A",
          Subtitle = "Free food and drink? Don't mind if I do — only a fool would turn down a freebie."
        },
        [80190101] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          DialogueId = 80190101,
          Duration = 3,
          GUID = "C8BF5C72",
          NextDialogue = 80190102,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190102] = {
          ContentEN = "You've got this big place all to yourself? Not bad — even set up a proper bar, I see.",
          DialogueId = 80190102,
          FacialId = {
            [1] = "95102:Shock01"
          },
          GUID = "C8BF5C9C",
          NextDialogue = 80190103,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          Subtitle = "You've got this big place all to yourself? Not bad — even set up a proper bar, I see.",
          TalkActionId = {
            [1] = "95102:Sit_Idle_Loop"
          }
        },
        [80190103] = {
          ContentEN = "Good for you. You ought to have friends over more often — never hurts to build a few ties in Icelake.",
          DialogueId = 80190103,
          FacialId = {
            [1] = "95102:Smile01"
          },
          GUID = "C8BF5CC6",
          NextDialogue = 80190104,
          SpeakNpcId = 95102,
          Subtitle = "Good for you. You ought to have friends over more often — never hurts to build a few ties in Icelake."
        },
        [80190104] = {
          ContentEN = "Alright then — what do you want this time? If it's anything too much of a bother, I'm out. Got a big job hanging over me lately.",
          DialogueId = 80190104,
          GUID = "C8BF5CF0",
          NextOptions = {
            [1] = 801901041,
            [2] = 801901042
          },
          SpeakNpcId = 95102,
          Subtitle = "Alright then — what do you want this time? If it's anything too much of a bother, I'm out. Got a big job hanging over me lately.",
          TalkActionId = {
            [1] = "95102:Sit_Talk03_Start"
          }
        },
        [80190105] = {
          ContentEN = "Oof... That's sweet enough to rot my teeth. I'll let it slide — but if you say that to everyone you drink with, someone's bound to choke on their pint.",
          DialogueId = 80190105,
          GUID = "C8BF5D1A",
          NextDialogue = 80190107,
          SpeakNpcId = 95102,
          Subtitle = "Oof... That's sweet enough to rot my teeth. I'll let it slide — but if you say that to everyone you drink with, someone's bound to choke on their pint.",
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190106] = {
          ContentEN = "Now that's more like it. Let's see if your mix is worth the pour.",
          DialogueId = 80190106,
          GUID = "C8BF5D44",
          NextDialogue = 80190107,
          SpeakNpcId = 95102,
          Subtitle = "Now that's more like it. Let's see if your mix is worth the pour.",
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190107] = {
          ContentEN = "{空格}",
          DialogueId = 80190107,
          Duration = 3,
          GUID = "C8BF5D6E",
          NextDialogue = 80190108,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          Subtitle = "{空格}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190108] = {
          ContentEN = "Hmm... Sweet, with a tangy edge. Served warm, too — not bad at all. I'd say it's on par with the stuff back at The Asphodel, though you've definitely added your own twist.",
          DialogueId = 80190108,
          FacialId = {
            [1] = "95102:Smile01"
          },
          GUID = "C8BF5D98",
          NextDialogue = 80190109,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          Subtitle = "Hmm... Sweet, with a tangy edge. Served warm, too — not bad at all. I'd say it's on par with the stuff back at The Asphodel, though you've definitely added your own twist.",
          TalkActionId = {
            [1] = "95102:Sit_Idle_Loop"
          }
        },
        [80190109] = {
          ContentEN = "Bet this one took a fair bit of effort, eh? Didn't expect a drink this good, to be honest. Even just a warm cup of water would've done the trick — I'm easy. No need to pull out all the stops.",
          DialogueId = 80190109,
          GUID = "C8BF5DC2",
          NextDialogue = 80190110,
          SpeakNpcId = 95102,
          Subtitle = "Bet this one took a fair bit of effort, eh? Didn't expect a drink this good, to be honest. Even just a warm cup of water would've done the trick — I'm easy. No need to pull out all the stops."
        },
        [80190110] = {
          ContentEN = "You're looking rather chipper though... ah, I get it. Got a bit of coin lying around, huh? Thought you'd splash out — parties, drinks, maybe a new trinket or two. That's what they call \"buying a good time\" these days, right?",
          DialogueId = 80190110,
          GUID = "C8BF5DEC",
          NextOptions = {
            [1] = 801901101,
            [2] = 801901102
          },
          SpeakNpcId = 95102,
          Subtitle = "You're looking rather chipper though... ah, I get it. Got a bit of coin lying around, huh? Thought you'd splash out — parties, drinks, maybe a new trinket or two. That's what they call \"buying a good time\" these days, right?"
        },
        [80190111] = {
          ContentEN = "Well, isn't that the whole point? You pour someone a drink, you get a proper chat. Just means I know how to read the room — and I've got the decency to play along.",
          DialogueId = 80190111,
          GUID = "C8BF5E16",
          NextDialogue = 80190113,
          SpeakNpcId = 95102,
          Subtitle = "Well, isn't that the whole point? You pour someone a drink, you get a proper chat. Just means I know how to read the room — and I've got the decency to play along.",
          TalkActionId = {
            [1] = "95102:Sit_Talk01_Start"
          }
        },
        [80190112] = {
          ContentEN = "Whoa now, my bad! Your place, your booze — that makes you the boss. Here — throw a punch if it'll help you blow off some steam.",
          DialogueId = 80190112,
          GUID = "C8BF5E40",
          NextDialogue = 80190113,
          SpeakNpcId = 95102,
          Subtitle = "Whoa now, my bad! Your place, your booze — that makes you the boss. Here — throw a punch if it'll help you blow off some steam.",
          TalkActionId = {
            [1] = "95102:Sit_Talk01_Start"
          }
        },
        [80190113] = {
          ContentEN = "Kidding, obviously. But if you're after a bit of advice from someone who's been around — not everyone's worth the drink or the word \"friend.\"",
          DialogueId = 80190113,
          GUID = "C8BF5E6A",
          NextDialogue = 80190114,
          SpeakNpcId = 95102,
          Subtitle = "Kidding, obviously. But if you're after a bit of advice from someone who's been around — not everyone's worth the drink or the word \"friend.\"",
          TalkActionId = {
            [1] = "95102:Sit_Talk01_End"
          }
        },
        [80190114] = {
          ContentEN = "Especially not in a place like Icelake. Always some grinning bastard eyeing your pockets, buttering you up just to find a way in.",
          DialogueId = 80190114,
          GUID = "C8BF5E94",
          NextDialogue = 80190115,
          SpeakNpcId = 95102,
          Subtitle = "Especially not in a place like Icelake. Always some grinning bastard eyeing your pockets, buttering you up just to find a way in."
        },
        [80190115] = {
          ContentEN = "They'll smile, flatter, make you feel like you're the sun — and the second you're in trouble? You'd have better luck counting on a stray dog.",
          DialogueId = 80190115,
          GUID = "C8BF5EBE",
          NextOptions = {
            [1] = 801901151
          },
          SpeakNpcId = 95102,
          Subtitle = "They'll smile, flatter, make you feel like you're the sun — and the second you're in trouble? You'd have better luck counting on a stray dog.",
          TalkActionId = {
            [1] = "95102:Sit_Talk03_Start"
          }
        },
        [80190116] = {
          ContentEN = "Ding ding ding — got me! I, Outsider, am the finest freeloader you'll ever meet. Disguised, of course, as a charming drinking buddy. If there's free booze or a hot meal, I'll sniff it out from a mile off.",
          DialogueId = 80190116,
          GUID = "C8BF5EE8",
          NextDialogue = 80190117,
          SpeakNpcId = 95102,
          Subtitle = "Ding ding ding — got me! I, Outsider, am the finest freeloader you'll ever meet. Disguised, of course, as a charming drinking buddy. If there's free booze or a hot meal, I'll sniff it out from a mile off.",
          TalkActionId = {
            [1] = "95102:Sit_AgreeHead"
          }
        },
        [80190117] = {
          ContentEN = "Anyone wants the title, they'll have to fight me for it. And those who're planning to eat off your plate, they can only wait until I've had my fill.",
          DialogueId = 80190117,
          GUID = "C8BF5F12",
          NextOptions = {
            [1] = 801901171,
            [2] = 801901172
          },
          SpeakNpcId = 95102,
          Subtitle = "Anyone wants the title, they'll have to fight me for it. And those who're planning to eat off your plate, they can only wait until I've had my fill."
        },
        [80190118] = {
          ContentEN = "Oi, oi — no need to be hasty. I've only just got comfy.",
          DialogueId = 80190118,
          GUID = "C8BF5F3C",
          NextDialogue = 80190120,
          SpeakNpcId = 95102,
          Subtitle = "Oi, oi — no need to be hasty. I've only just got comfy.",
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190119] = {
          ContentEN = "Hmm? What's that now? No idea what you're talking about.",
          DialogueId = 80190119,
          GUID = "C8BF5F66",
          NextDialogue = 80190120,
          SpeakNpcId = 95102,
          Subtitle = "Hmm? What's that now? No idea what you're talking about.",
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190120] = {
          ContentEN = "But hey — the drink's good. Pour me another before I drag myself back to the grind.",
          DialogueId = 80190120,
          GUID = "C8BF5F90",
          SpeakNpcId = 95102,
          Subtitle = "But hey — the drink's good. Pour me another before I drag myself back to the grind."
        },
        [80190201] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          ContentEN = "Ah — half an hour late, huh? My bad. To make it up to you, I swear — even if today's drink tastes like bad fish in a dirty sock, I'll down it in one go!",
          DialogueId = 80190201,
          FacialId = {
            [1] = "95102:Ahaha01"
          },
          GUID = "C8BF6CDA",
          NextOptions = {
            [1] = 801902011,
            [2] = 801902012
          },
          SpeakNpcId = 95102,
          Subtitle = "Ah — half an hour late, huh? My bad. To make it up to you, I swear — even if today's drink tastes like bad fish in a dirty sock, I'll down it in one go!"
        },
        [80190202] = {
          ContentEN = "Haha — sharp one. Saw right through me.",
          DialogueId = 80190202,
          FacialId = {
            [1] = "95102:Smile02"
          },
          GUID = "C8BF6D04",
