        [80190203] = {
          ContentEN = "Remember that big job I mentioned the other day? Just wrapped it up with Wells. Took a bit longer than we thought.",
          DialogueId = 80190203,
          FacialId = {
            [1] = "95102:None"
          },
          GUID = "C8BF6D2E",
          NextDialogue = 80190204,
          SpeakNpcId = 95102,
          Subtitle = "Remember that big job I mentioned the other day? Just wrapped it up with Wells. Took a bit longer than we thought."
        },
        [80190204] = {
          ContentEN = "The job wasn't the problem — it was the people involved that made it a pain.",
          DialogueId = 80190204,
          GUID = "C8BF6D58",
          NextOptions = {
            [1] = 801902041
          },
          SpeakNpcId = 95102,
          Subtitle = "The job wasn't the problem — it was the people involved that made it a pain."
        },
        [80190205] = {
          ContentEN = "Nah. The Legion's manageable — long as you know the rules, read the room, and steer clear of stepping on the Empire's toes, you can find ways around most of their messes.",
          DialogueId = 80190205,
          GUID = "C8BF6D82",
          NextDialogue = 80190206,
          SpeakNpcId = 95102,
          Subtitle = "Nah. The Legion's manageable — long as you know the rules, read the room, and steer clear of stepping on the Empire's toes, you can find ways around most of their messes.",
          TalkActionId = {
            [1] = "95102:Sit_DisagreeHead"
          }
        },
        [80190206] = {
          ContentEN = "They're like a drawn blade — sharp and deadly, sure, but at least you see it coming.",
          DialogueId = 80190206,
          GUID = "C8BF6DAC",
          NextDialogue = 80190207,
          SpeakNpcId = 95102,
          Subtitle = "They're like a drawn blade — sharp and deadly, sure, but at least you see it coming."
        },
        [80190207] = {
          ContentEN = "It's the other lot you need to watch out for. The ones with no rules, just chaos. Like a live bomb buried just out of sight—",
          DialogueId = 80190207,
          GUID = "C8BF6DD6",
          NextDialogue = 80190208,
          SpeakNpcId = 95102,
          Subtitle = "It's the other lot you need to watch out for. The ones with no rules, just chaos. Like a live bomb buried just out of sight—",
          TalkActionId = {
            [1] = "95102:Sit_Talk03_Start"
          }
        },
        [80190208] = {
          ContentEN = "The Forsakens. That mad bunch. Once they drag you in, everything gets ten times messier.",
          DialogueId = 80190208,
          GUID = "C8BF6E00",
          NextDialogue = 80190209,
          SpeakNpcId = 95102,
          Subtitle = "The Forsakens. That mad bunch. Once they drag you in, everything gets ten times messier."
        },
        [80190209] = {
          ContentEN = "Take this job, for example — just your standard delivery gig, right? But Wells thought something felt off with the weight, so he quietly chiselled a hole in the crate and had a peek. And what do you know? It was packed with contraband weapons, all marked for the Forsakens.",
          DialogueId = 80190209,
          GUID = "C8BF6E2A",
          NextDialogue = 80190210,
          SpeakNpcId = 95102,
          Subtitle = "Take this job, for example — just your standard delivery gig, right? But Wells thought something felt off with the weight, so he quietly chiselled a hole in the crate and had a peek. And what do you know? It was packed with contraband weapons, all marked for the Forsakens."
        },
        [80190210] = {
          ContentEN = "If we'd hauled that through the city gates, the guards would've gunned us down before we got a word in.",
          DialogueId = 80190210,
          GUID = "C8BF6E54",
          NextDialogue = 80190211,
          SpeakNpcId = 95102,
          Subtitle = "If we'd hauled that through the city gates, the guards would've gunned us down before we got a word in."
        },
        [80190211] = {
          ContentEN = "Which was probably the plan. Maybe they wanted a few Phoxhunters dead. Maybe a little public chaos to slip into Icelake.",
          DialogueId = 80190211,
          GUID = "C8BF6E7E",
          NextDialogue = 80190212,
          SpeakNpcId = 95102,
          Subtitle = "Which was probably the plan. Maybe they wanted a few Phoxhunters dead. Maybe a little public chaos to slip into Icelake."
        },
        [80190212] = {
          ContentEN = "Or maybe it was all for show — a nice live performance, so their followers could watch exactly how cruel Solas are to Charons.",
          DialogueId = 80190212,
          GUID = "C8BF6EA8",
          NextDialogue = 80190213,
          SpeakNpcId = 95102,
          Subtitle = "Or maybe it was all for show — a nice live performance, so their followers could watch exactly how cruel Solas are to Charons.",
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190213] = {
          ContentEN = "Point is, there's no guessing with them. Their motives don't make sense to normal folk — and their methods are even worse.",
          DialogueId = 80190213,
          FacialId = {
            [1] = "95102:Angry01"
          },
          GUID = "C8BF6ED2",
          NextDialogue = 80190214,
          SpeakNpcId = 95102,
          Subtitle = "Point is, there's no guessing with them. Their motives don't make sense to normal folk — and their methods are even worse.",
          TalkActionId = {
            [1] = "95102:Sit_Talk02_Start"
          }
        },
        [80190214] = {
          ContentEN = "In the end, we had to smuggle the weapons in through the sewers just to finish the so-called \"delivery.\"",
          DialogueId = 80190214,
          GUID = "C8BF6EFC",
          NextDialogue = 80190215,
          SpeakNpcId = 95102,
          Subtitle = "In the end, we had to smuggle the weapons in through the sewers just to finish the so-called \"delivery.\""
        },
        [80190215] = {
          ContentEN = "Sounds simple when I say it, right? But Wells and I haven't had a proper night's sleep in days.",
          DialogueId = 80190215,
          GUID = "C8BF6F26",
          NextOptions = {
            [1] = 801902151,
            [2] = 801902152
          },
          SpeakNpcId = 95102,
          Subtitle = "Sounds simple when I say it, right? But Wells and I haven't had a proper night's sleep in days."
        },
        [80190216] = {
          ContentEN = "Still — wrong's wrong. Doesn't matter how busy I was, I showed up late.",
          DialogueId = 80190216,
          GUID = "C8BF6F50",
          NextDialogue = 80190218,
          SpeakNpcId = 95102,
          Subtitle = "Still — wrong's wrong. Doesn't matter how busy I was, I showed up late.",
          TalkActionId = {
            [1] = "95102:Sit_Talk02_End"
          }
        },
        [80190217] = {
          ContentEN = "Nah. I'd never say no to a drinking buddy. Even if I were six feet under, I'd still claw my way up for a sip.",
          DialogueId = 80190217,
          GUID = "C8BF6F7A",
          NextDialogue = 80190218,
          SpeakNpcId = 95102,
          Subtitle = "Nah. I'd never say no to a drinking buddy. Even if I were six feet under, I'd still claw my way up for a sip.",
          TalkActionId = {
            [1] = "95102:Sit_Talk02_End"
          }
        },
        [80190218] = {
          ContentEN = "{空格}",
          DialogueId = 80190218,
          Duration = 3,
          GUID = "C8BF6FA4",
          NextDialogue = 80190219,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          Subtitle = "{空格}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190219] = {
          ContentEN = "But yeah, I do need sleep. Before I go — one last bit of advice. For your own safety, and for the sake of those who care about you... steer clear of the Forsakens.",
          DialogueId = 80190219,
          GUID = "C8BF6FCE",
          NextOptions = {
            [1] = 801902191
          },
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          Subtitle = "But yeah, I do need sleep. Before I go — one last bit of advice. For your own safety, and for the sake of those who care about you... steer clear of the Forsakens.",
          TalkActionId = {
            [1] = "95102:Sit_Idle_Loop"
          }
        },
        [80190220] = {
          ContentEN = "...Just survival instinct. Like most folk — I see danger, I walk the other way.",
          DialogueId = 80190220,
          FacialId = {
            [1] = "95102:Sad01"
          },
          GUID = "C8BF6FF8",
          NextDialogue = 80190221,
          SpeakNpcId = 95102,
          Subtitle = "...Just survival instinct. Like most folk — I see danger, I walk the other way."
        },
        [80190221] = {
          ContentEN = "I've spent years scraping by between the grinding gears of clashing war machines. And if there's one thing I've learned, it's this: stay the hell away from the Forsakens.",
          DialogueId = 80190221,
          GUID = "C8BF7022",
          NextDialogue = 80190222,
          SpeakNpcId = 95102,
          Subtitle = "I've spent years scraping by between the grinding gears of clashing war machines. And if there's one thing I've learned, it's this: stay the hell away from the Forsakens."
        },
        [80190222] = {
          ContentEN = "This isn't some drunken ramble. This is life-or-death advice.",
          DialogueId = 80190222,
          GUID = "C8BF704C",
          SpeakNpcId = 95102,
          Subtitle = "This isn't some drunken ramble. This is life-or-death advice."
        },
        [80190301] = {
