        [80190305] = {
          ContentEN = "...Ah... yeah. I'm fine. Good drink. Solid as ever.",
          DialogueId = 80190305,
          GUID = "C8BF7DEA",
          NextDialogue = 80190306,
          SpeakNpcId = 95102,
          Subtitle = "...Ah... yeah. I'm fine. Good drink. Solid as ever."
        },
        [80190306] = {
          ContentEN = "...",
          DialogueId = 80190306,
          GUID = "C8BF7E14",
          NextOptions = {
