          }
        },
        [80190434] = {
          ContentEN = "Yeah... you're right. What was I thinking? I've lived through worse. One little scare, and here I am — handing you my last words like it's the end of the world.",
          DialogueId = 80190434,
          FacialId = {
            [1] = "95102:None"
          },
          GUID = "C8BF9314",
          NextDialogue = 80190435,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          Subtitle = "Yeah... you're right. What was I thinking? I've lived through worse. One little scare, and here I am — handing you my last words like it's the end of the world.",
          TalkActionId = {
            [1] = "95102:Sit_Idle_Loop"
          }
        },
        [80190435] = {
          ContentEN = "Maybe I've been spending too much time with you. Or maybe now that you're my Captain, some part of me thought I could lean a little. Or maybe... I've just gone soft.",
          DialogueId = 80190435,
          GUID = "C8BF933E",
          NextDialogue = 80190436,
          SpeakNpcId = 95102,
          Subtitle = "Maybe I've been spending too much time with you. Or maybe now that you're my Captain, some part of me thought I could lean a little. Or maybe... I've just gone soft."
        },
        [80190436] = {
          ContentEN = "No, no, no — can't be. Must be this drink. You spiked it, didn't you? I didn't say anything soppy just now, right? Be honest — I didn't, yeah?",
          DialogueId = 80190436,
          GUID = "C8BF9368",
          NextOptions = {
            [1] = 801904361,
            [2] = 801904362
          },
          SpeakNpcId = 95102,
          Subtitle = "No, no, no — can't be. Must be this drink. You spiked it, didn't you? I didn't say anything soppy just now, right? Be honest — I didn't, yeah?",
          TalkActionId = {
            [1] = "95102:Sit_DisagreeHead"
          }
        },
        [80190437] = {
          ContentEN = "Anyway — rather than worry about what might happen, maybe we stay cool until it actually does. Who knows? By then, we might've already found a way through.",
          DialogueId = 80190437,
          GUID = "C8BF9392",
          NextDialogue = 80190438,
          SpeakNpcId = 790008,
          Subtitle = "Anyway — rather than worry about what might happen, maybe we stay cool until it actually does. Who knows? By then, we might've already found a way through."
        },
        [80190438] = {
          ContentEN = "Hmm... good point. Cheers to that — here's to future me. May he be wiser and more put-together than current me. And to you — for being a good friend.",
          DialogueId = 80190438,
          FacialId = {
            [1] = "95102:Smile01"
          },
          GUID = "C8BF93BC",
          NextDialogue = 80190439,
          SpeakNpcId = 95102,
          Subtitle = "Hmm... good point. Cheers to that — here's to future me. May he be wiser and more put-together than current me. And to you — for being a good friend."
        },
        [80190439] = {
          ContentEN = "{空格}",
          DialogueId = 80190439,
          GUID = "C8BF93E6",
          NextDialogue = 80190440,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          Subtitle = "{空格}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190440] = {
          ContentEN = "Still... I owe you an apology. I've made peace with whatever's ahead — but my past? I still can't tell you everything. Not yet.",
          DialogueId = 80190440,
          GUID = "C8BF9410",
          NextDialogue = 80190441,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          Subtitle = "Still... I owe you an apology. I've made peace with whatever's ahead — but my past? I still can't tell you everything. Not yet.",
          TalkActionId = {
            [1] = "95102:Sit_Idle_Loop"
          }
        },
        [80190441] = {
          ContentEN = "But I promise — someday, I'll show you the path that led me here. It won't be easy. And you might not like what you find.",
          DialogueId = 80190441,
          GUID = "C8BF943A",
          NextDialogue = 80190442,
          SpeakNpcId = 95102,
