          ContentEN = "What I truly long for is practice — to observe, to examine, to diagnose... To understand what illness means in the living body.",
          DialogueId = 80200023,
          Duration = 2,
          FinalCamera = "-1097.473145,835.017334,72.382812,0.00011,1.800718,-34.790791,35.0,1303.897095,false,Manual,1.460963",
