        },
        [80210215] = {
          ContentEN = "Certainly not you.",
          DialogueId = 80210215,
          GUID = "C8CC4066",
          NextDialogue = 80210216,
          SpeakNpcId = 790067,
          Subtitle = "Certainly not you.",
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC4066"
        },
        [80210216] = {
