          ContentEN = "Then you misjudge me. Those pups are fine. I just knocked a few out, dragged them into the lee of a dune, and used them as blankets. Their warmth got me through the night.",
          DialogueId = 80210216,
          FinalCamera = "134.451172,-164.355713,167.136719,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
          GUID = "C8CC4090",
          NextDialogue = 80210217,
          SpeakNpcId = 790068,
          Subtitle = "Then you misjudge me. Those pups are fine. I just knocked a few out, dragged them into the lee of a dune, and used them as blankets. Their warmth got me through the night.",
          TalkActionId = {
            [1] = "790068:Disagree"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC4090"
        },
        [80210217] = {
