        },
        [80210223] = {
          Camera = "371.589844,-637.212402,325.822266,0.000051,-17.998013,119.596794,33.0,1098.901978,false,Manual,3.0",
          ContentEN = "I'm surprised you've heard of Icelake, stuck here in Huaxu as you are.",
          DialogueId = 80210223,
          FinalCamera = "305.197266,-520.310547,282.146484,0.000051,-17.998013,119.596794,33.0,1098.901978,false,Manual,3.0",
          GUID = "C8CC41B6",
          NextDialogue = 80210224,
          SpeakNpcId = 790068,
          Subtitle = "I'm surprised you've heard of Icelake, stuck here in Huaxu as you are.",
          ToFinalCameraBlendTime = 30,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC41B6"
        },
        [80210224] = {
          ContentEN = "Made a friend lately who lives there. Picked up a thing or two.",
          DialogueId = 80210224,
          FacialId = {
            [1] = "790067:Smile01"
          },
          GUID = "C8CC41E0",
          NextDialogue = 80210225,
          SpeakNpcId = 790067,
          Subtitle = "Made a friend lately who lives there. Picked up a thing or two.",
          TalkActionId = {
            [1] = "790067:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC41E0"
        },
        [80210225] = {
          ContentEN = "I see, but wrong guess. I was in a hurry. Went straight to Luca.",
          DialogueId = 80210225,
          GUID = "C8CC420A",
          NextDialogue = 80210226,
          SpeakNpcId = 790068,
          Subtitle = "I see, but wrong guess. I was in a hurry. Went straight to Luca.",
          TalkActionId = {
            [1] = "790067:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC420A"
        },
        [80210226] = {
          ContentEN = "On the way, I met a legendary creature of the sea. A beast they call a Siren. Beautiful as the moon... but its song steals your mind.",
          DialogueId = 80210226,
          GUID = "C8CC4234",
          NextDialogue = 80210227,
          SpeakNpcId = 790068,
          Subtitle = "On the way, I met a legendary creature of the sea. A beast they call a Siren. Beautiful as the moon... but its song steals your mind.",
          TalkActionId = {
            [1] = "790068:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC4234"
        },
        [80210227] = {
          Camera = "-31.490234,-67.365234,193.577148,0.000082,-19.79907,13.007189,30.000008,125.0,false,Manual,2.8",
          ContentEN = "So it's like Master Mo Baoqin, a century ago? Using secret tone arts to shatter one's focus?",
          DialogueId = 80210227,
          GUID = "C8CC425E",
          NextDialogue = 80210228,
          SpeakNpcId = 790067,
          Subtitle = "So it's like Master Mo Baoqin, a century ago? Using secret tone arts to shatter one's focus?",
          TalkActionId = {
            [1] = "790068:Talk03_End"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC425E"
        },
        [80210228] = {
          Camera = "150.619141,-184.330078,170.381836,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
          ContentEN = "Just like that. But in the moment, I didn't think — just dove deep, held my breath, and grabbed onto a passing whale. Barely escaped with my life.",
          DialogueId = 80210228,
          FinalCamera = "134.451172,-164.355713,167.136719,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
          GUID = "C8CC4288",
          NextDialogue = 80210229,
          SpeakNpcId = 790068,
          Subtitle = "Just like that. But in the moment, I didn't think — just dove deep, held my breath, and grabbed onto a passing whale. Barely escaped with my life.",
          TalkActionId = {
            [1] = "790068:Agree"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC4288"
        },
        [80210229] = {
          ContentEN = "But because of that, my breath control improved. I hardly fear poison or petty tricks like that anymore. I call this method the Whaleheart Art.",
          DialogueId = 80210229,
          GUID = "C8CC42B2",
          NextDialogue = 80210230,
          SpeakNpcId = 790068,
          Subtitle = "But because of that, my breath control improved. I hardly fear poison or petty tricks like that anymore. I call this method the Whaleheart Art.",
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC42B2"
        },
        [80210230] = {
          ContentEN = "And then?",
          DialogueId = 80210230,
          GUID = "C8CC42DC",
          NextDialogue = 80210231,
          SpeakNpcId = 790067,
          Subtitle = "And then?",
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC42DC"
        },
        [80210231] = {
          ContentEN = "And I didn't stay long either. Then I went to Yashnia, home of the Elysian Church... there I—",
          DialogueId = 80210231,
          GUID = "C8CC4306",
          NextDialogue = 80210232,
          SpeakNpcId = 790068,
          Subtitle = "And I didn't stay long either. Then I went to Yashnia, home of the Elysian Church... there I—",
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC4306"
        },
