        [80210301] = {
          Camera = "-1168.496094,1264.441406,313.365234,0.000131,-4.398683,-49.787758,30.000002,1615.87854,false,Manual,2.8",
          ContentEN = "A true hero is, above all, a connoisseur of fine living. A noble steed, a peerless blade, and elegant robes are the rightful marks of the righteous.",
          DialogueId = 80210301,
          FacialId = {
            [1] = "790071:Smile01"
          },
          FinalCamera = "-1040.925781,1113.558594,298.16748,0.000131,-4.398683,-49.787758,30.000002,1361.954834,false,Manual,2.8",
          GUID = "C8CC4E82",
          LookAt = {
            [1] = "790071:n(790069)",
            [2] = "790069:n(790071)"
          },
          NextDialogue = 80210302,
          Scripts = "PlayAnimation{ActorId{790071},AnimationId{\"Sit_Idle_Loop\"},Sync{true}}",
          Subtitle = "A true hero is, above all, a connoisseur of fine living. A noble steed, a peerless blade, and elegant robes are the rightful marks of the righteous.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC4E82"
        },
        [80210302] = {
          ContentEN = "But none are pursued with more fastidious care than food and drink. So much so that the very image of a hero is steeped in vintage wine and generously roasted meats. Should a swordsman refuse wine, one feels the edge of his blade is blunted — lacking that seasoned cunning.",
          DialogueId = 80210302,
          GUID = "C8CC4EAC",
          NextDialogue = 80210303,
          Subtitle = "But none are pursued with more fastidious care than food and drink. So much so that the very image of a hero is steeped in vintage wine and generously roasted meats. Should a swordsman refuse wine, one feels the edge of his blade is blunted — lacking that seasoned cunning.",
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC4EAC"
        },
        [80210303] = {
