        [80210306] = {
          Camera = "-545.542969,-132.332031,36.390137,0.000018,6.600196,30.606834,20.0,466.554138,false,Manual,2.8",
          ContentEN = "Thanks. By the way, have you heard of a Drifter named Liu Weifu, the Iron Palm? He'd be in his sixties or seventies by now.",
          DialogueId = 80210306,
          FinalCamera = "-444.984375,-72.832031,49.90918,0.00003,6.600196,30.607128,20.0,400.820953,false,Manual,2.8",
          GUID = "C8CC4F54",
          NextDialogue = 80210307,
          SpeakNpcId = 790071,
          Subtitle = "Thanks. By the way, have you heard of a Drifter named Liu Weifu, the Iron Palm? He'd be in his sixties or seventies by now.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC4F54"
        },
        [80210307] = {
          ContentEN = "Can't say I have. Never met a Drifter in my life.",
          DialogueId = 80210307,
          GUID = "C8CC4F7E",
          NextDialogue = 80210308,
          SpeakNpcId = 790069,
          Subtitle = "Can't say I have. Never met a Drifter in my life.",
