        },
        [80210308] = {
          Camera = "-194.460938,93.691406,125.272461,0.000011,-19.99996,37.409882,20.0,81.55352,false,Manual,2.8",
          ContentEN = "Well, you're looking at one right now.",
          DialogueId = 80210308,
          FinalCamera = "-185.449219,100.574219,121.142578,0.000011,-19.99996,37.409882,20.0,81.55352,false,Manual,2.8",
          GUID = "C8CC4FA8",
          NextDialogue = 80210309,
          SpeakNpcId = 790071,
          Subtitle = "Well, you're looking at one right now.",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC4FA8"
        },
        [80210309] = {
          ContentEN = "You're a Drifter?",
          DialogueId = 80210309,
          GUID = "C8CC4FD2",
          NextDialogue = 80210310,
          SpeakNpcId = 790069,
          Subtitle = "You're a Drifter?",
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC4FD2"
        },
        [80210310] = {
          ContentEN = "Obviously. What, I don't look the part?",
          DialogueId = 80210310,
          GUID = "C8CC4FFC",
          NextDialogue = 80210311,
          SpeakNpcId = 790071,
          Subtitle = "Obviously. What, I don't look the part?",
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC4FFC"
        },
        [80210311] = {
          Camera = "-159.164062,204.953125,88.058105,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
          ContentEN = "Not really. I heard Drifters drink wine by the bowl and eat meat by the chunk. Never seen one order tofu puffs.",
          DialogueId = 80210311,
          FinalCamera = "-156.535156,189.371094,90.843262,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
          GUID = "C8CC5026",
          NextDialogue = 80210312,
          SpeakNpcId = 790069,
          Subtitle = "Not really. I heard Drifters drink wine by the bowl and eat meat by the chunk. Never seen one order tofu puffs.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC5026"
        },
        [80210312] = {
          Camera = "-235.25,3.191406,148.305176,0.000013,-19.999994,47.002541,20.0,187.784851,false,Manual,2.8",
          ContentEN = "What kind of nonsense is that? We're not wild dogs tearing into raw meat. When we eat with purpose, we have our own refinements.",
          DialogueId = 80210312,
          FinalCamera = "-220.636719,18.855469,140.509766,0.000013,-19.999994,47.002541,20.0,169.81192,false,Manual,2.8",
          GUID = "C8CC5050",
          NextDialogue = 80210313,
          SpeakNpcId = 790071,
          Subtitle = "What kind of nonsense is that? We're not wild dogs tearing into raw meat. When we eat with purpose, we have our own refinements.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC5050"
        },
        [80210313] = {
          Camera = "-545.542969,-132.332031,36.390137,0.000018,6.600196,30.606834,20.0,466.554138,false,Manual,2.8",
          ContentEN = "Well, dogs eat more than just meat, actually…",
          DialogueId = 80210313,
          FinalCamera = "-462.796875,-83.355469,47.517578,0.0,6.600196,30.608337,20.0,466.554138,false,Manual,2.8",
          GUID = "C8CC507A",
          NextDialogue = 80210314,
          SpeakNpcId = 790069,
          Subtitle = "Well, dogs eat more than just meat, actually…",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC507A"
        },
        [80210314] = {
          ContentEN = "That's enough. Are my tofu puffs ready? Hurry them up, will you?",
          DialogueId = 80210314,
          GUID = "C8CC50A4",
          NextDialogue = 80210315,
          SpeakNpcId = 790071,
          Subtitle = "That's enough. Are my tofu puffs ready? Hurry them up, will you?",
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC50A4"
        },
        [80210315] = {
          ContentEN = "You got it! Uncle Maojin, hurry with those tofu puffs!",
          DialogueId = 80210315,
          GUID = "C8CC50CE",
          NextDialogue = 80210316,
          SpeakNpcId = 790069,
          Subtitle = "You got it! Uncle Maojin, hurry with those tofu puffs!",
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC50CE"
        },
        [80210316] = {
          ContentEN = "No rush. Almost done.",
          DialogueId = 80210316,
          GUID = "C8CC50F8",
          NextDialogue = 80210317,
          SpeakNpcId = 790070,
          Subtitle = "No rush. Almost done.",
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC50F8"
        },
        [80210317] = {
          Camera = "-159.164062,204.953125,88.058105,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
          ContentEN = "Right. Sir, it'll just be a moment. But since you mentioned that Drifters \"eat with purpose,\" could you tell me more? The place is empty — I'd love to hear.",
          DialogueId = 80210317,
          FinalCamera = "-156.535156,189.371094,90.843262,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
          GUID = "C8CC5122",
          NextDialogue = 80210318,
          SpeakNpcId = 790069,
          Subtitle = "Right. Sir, it'll just be a moment. But since you mentioned that Drifters \"eat with purpose,\" could you tell me more? The place is empty — I'd love to hear.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC5122"
        },
        [80210318] = {
          Camera = "-235.25,3.191406,148.305176,0.000013,-19.999994,47.002541,20.0,187.784851,false,Manual,2.8",
          ContentEN = "Fine. The master I'm looking for today was also famous in his day for his cooking. They called him the \"Gourmet Knight.\"",
          DialogueId = 80210318,
          FinalCamera = "-208.675781,31.691406,134.121582,0.000012,-19.999954,47.00246,20.0,150.472961,false,Manual,2.8",
          GUID = "C8CC514C",
          NextDialogue = 80210319,
          SpeakNpcId = 790071,
          Subtitle = "Fine. The master I'm looking for today was also famous in his day for his cooking. They called him the \"Gourmet Knight.\"",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC514C"
        },
        [80210319] = {
          ContentEN = "His most legendary dish was called \"The Untamable Loong Beyond Reach.\" Rumor was, he slew the Argent Loong that guarded the Nine Chapters and served it at a feast.",
          DialogueId = 80210319,
          GUID = "C8CC5176",
          NextDialogue = 80210320,
          SpeakNpcId = 790071,
          Subtitle = "His most legendary dish was called \"The Untamable Loong Beyond Reach.\" Rumor was, he slew the Argent Loong that guarded the Nine Chapters and served it at a feast.",
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC5176"
        },
        [80210320] = {
          ContentEN = "In truth, he used his palm strength to tenderize meats from all kinds of birds and beasts, ground them fine, and reshaped them. One bite released manifold flavors — so he called it \"Loong Meat.\"",
          DialogueId = 80210320,
          GUID = "C8CC51A0",
          NextDialogue = 80210321,
          SpeakNpcId = 790071,
          Subtitle = "In truth, he used his palm strength to tenderize meats from all kinds of birds and beasts, ground them fine, and reshaped them. One bite released manifold flavors — so he called it \"Loong Meat.\"",
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC51A0"
        },
        [80210321] = {
          ContentEN = "Then he'd stir-fry incredibly silken tofu with marrow from various animals, letting their richness soak in. He called that \"Loong Marrow.\"",
          DialogueId = 80210321,
          GUID = "C8CC51CA",
          NextDialogue = 80210322,
          SpeakNpcId = 790071,
          Subtitle = "Then he'd stir-fry incredibly silken tofu with marrow from various animals, letting their richness soak in. He called that \"Loong Marrow.\"",
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC51CA"
        },
        [80210322] = {
          Camera = "-159.164062,204.953125,88.058105,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
          ContentEN = "You're having a laugh, sir. It's just tofu. How could anyone call it Loong Marrow? By that logic, our fried tofu puffs could be called \"Fried Loong Marrow.\"",
          DialogueId = 80210322,
          FinalCamera = "-156.535156,189.371094,90.843262,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
          GUID = "C8CC51F4",
          NextDialogue = 80210323,
          SpeakNpcId = 790069,
          Subtitle = "You're having a laugh, sir. It's just tofu. How could anyone call it Loong Marrow? By that logic, our fried tofu puffs could be called \"Fried Loong Marrow.\"",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC51F4"
        },
        [80210323] = {
          Camera = "-194.460938,93.691406,125.272461,0.000011,-19.99996,37.409882,20.0,81.55352,false,Manual,2.8",
          ContentEN = "Ah, I only know what my master told me. They say the Iron Palm retired long ago. No one knows where he is now.",
          DialogueId = 80210323,
          FinalCamera = "-185.449219,100.574219,121.142578,0.000011,-19.99996,37.409882,20.0,81.55352,false,Manual,2.8",
          GUID = "C8CC521E",
          NextDialogue = 80210324,
          SpeakNpcId = 790071,
          Subtitle = "Ah, I only know what my master told me. They say the Iron Palm retired long ago. No one knows where he is now.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC521E"
        },
        [80210324] = {
          Camera = "-1040.925781,1113.558594,298.16748,0.000131,-4.398683,-49.787758,30.000002,1361.954834,false,Manual,2.8",
          ContentEN = "All this talk is making my mouth water, and you've never even tasted it? Enough fantasy — try these. Our signature fried tofu puffs.",
          DialogueId = 80210324,
          FinalCamera = "-847.84375,934.597656,274.614746,0.000131,-6.0,-49.78775,30.000002,1361.954834,false,Manual,2.8",
          GUID = "C8CC5248",
          NextDialogue = 80210325,
          SpeakNpcId = 790069,
          Subtitle = "All this talk is making my mouth water, and you've never even tasted it? Enough fantasy — try these. Our signature fried tofu puffs.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC5248"
        },
        [80210325] = {
          ContentEN = "Let me taste it.",
          DialogueId = 80210325,
          GUID = "C8CC5272",
          SpeakNpcId = 790071,
          Subtitle = "Let me taste it.",
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC5272"
