        },
        [80220121] = {
          ContentEN = "Buxia.",
          DialogueId = 80220121,
          GUID = "C8D2999A",
          NextDialogue = 80220122,
          Subtitle = "Buxia.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D2999A"
        },
        [80220122] = {
          ContentEN = "Shixiong! You're back already?",
          DialogueId = 80220122,
          GUID = "C8D299C4",
          NextDialogue = 80220123,
          Subtitle = "Shixiong! You're back already?",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D299C4"
        },
        [80220123] = {
          ContentEN = "Your hearing...",
          DialogueId = 80220123,
          GUID = "C8D299EE",
          NextDialogue = 80220124,
          Subtitle = "Your hearing...",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D299EE"
        },
        [80220124] = {
          ContentEN = "I'm fine — one ear just doesn't behave sometimes. The other's fine! ...Guess that's my body telling me it's time to sleep~",
          DialogueId = 80220124,
          GUID = "C8D29A18",
          NextDialogue = 80220125,
          Subtitle = "I'm fine — one ear just doesn't behave sometimes. The other's fine! ...Guess that's my body telling me it's time to sleep~",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29A18"
        },
        [80220125] = {
          ContentEN = "...You shouldn't be wasting time. If you and Kezhou hadn't been caught slacking, Shifu wouldn't have you copying texts for three days. You're not like him. He can afford that pace. You can't. Keep messing about with him and you'll only fall behind.",
          DialogueId = 80220125,
          GUID = "C8D29A42",
          NextDialogue = 80220126,
          Subtitle = "...You shouldn't be wasting time. If you and Kezhou hadn't been caught slacking, Shifu wouldn't have you copying texts for three days. You're not like him. He can afford that pace. You can't. Keep messing about with him and you'll only fall behind.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29A42"
        },
        [80220126] = {
          ContentEN = "And about your hearing — we should go to Haojing. Let a physician have a look.",
          DialogueId = 80220126,
          GUID = "C8D29A6C",
          NextDialogue = 80220127,
          Subtitle = "And about your hearing — we should go to Haojing. Let a physician have a look.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29A6C"
        },
        [80220127] = {
          ContentEN = "All right, all right — honestly, Shixiong, you're starting to sound like Shifu, always nagging. Sometimes I forget you're still young.",
          DialogueId = 80220127,
          GUID = "C8D29A96",
          NextDialogue = 80220128,
          Subtitle = "All right, all right — honestly, Shixiong, you're starting to sound like Shifu, always nagging. Sometimes I forget you're still young.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29A96"
        },
        [80220128] = {
          ContentEN = "Oh— right! How's Little Tangerine? That storm last night was awful... I couldn't stop worrying.",
          DialogueId = 80220128,
          GUID = "C8D29AC0",
          NextDialogue = 80220129,
          Subtitle = "Oh— right! How's Little Tangerine? That storm last night was awful... I couldn't stop worrying.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29AC0"
        },
        [80220129] = {
          ContentEN = "I went to the rear hills today to check on it. The shelter I built was crushed by a falling rock. It was huddled under the broken boards, soaked through.",
          DialogueId = 80220129,
          GUID = "C8D29AEA",
          NextDialogue = 80220130,
          Subtitle = "I went to the rear hills today to check on it. The shelter I built was crushed by a falling rock. It was huddled under the broken boards, soaked through.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29AEA"
        },
        [80220130] = {
          ContentEN = "I fixed the shelter and laid down some dry grass. Still, it just huddled there, shaking.",
          DialogueId = 80220130,
          GUID = "C8D29B14",
          NextDialogue = 80220131,
          Subtitle = "I fixed the shelter and laid down some dry grass. Still, it just huddled there, shaking.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29B14"
        },
        [80220131] = {
          ContentEN = "Aw... how am I not supposed to worry?",
          DialogueId = 80220131,
          GUID = "C8D29B3E",
          NextDialogue = 80220132,
          Subtitle = "Aw... how am I not supposed to worry?",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29B3E"
        },
        [80220132] = {
          ContentEN = "What are you two doing? Buxia — have you finished copying out those texts?",
          DialogueId = 80220132,
          GUID = "C8D29B68",
          NextDialogue = 80220133,
          Subtitle = "What are you two doing? Buxia — have you finished copying out those texts?",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29B68"
        },
        [80220133] = {
          ContentEN = "Ah... Shifu! W—We were talking about training! This morning Shixiong showed me a spear technique. I'd never seen anything like it, so I asked him for a few pointers. That's all! Really! Hehe...",
          DialogueId = 80220133,
          GUID = "C8D29B92",
          NextDialogue = 80220134,
          Subtitle = "Ah... Shifu! W—We were talking about training! This morning Shixiong showed me a spear technique. I'd never seen anything like it, so I asked him for a few pointers. That's all! Really! Hehe...",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29B92"
        },
        [80220134] = {
          ContentEN = "...Yes.",
          DialogueId = 80220134,
          GUID = "C8D29BBC",
          NextDialogue = 80220135,
          Subtitle = "...Yes.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29BBC"
        },
        [80220135] = {
          ContentEN = "Hmph. One of you talks more when she lies; the other talks less. Do you really think I'm as clueless as that little fox you've been keeping?",
          DialogueId = 80220135,
          GUID = "C8D29BE6",
          NextDialogue = 80220136,
          Subtitle = "Hmph. One of you talks more when she lies; the other talks less. Do you really think I'm as clueless as that little fox you've been keeping?",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29BE6"
        },
        [80220136] = {
          ContentEN = "Ah... so you knew all along, Shifu.",
          DialogueId = 80220136,
          GUID = "C8D29C10",
          NextDialogue = 80220137,
          Subtitle = "Ah... so you knew all along, Shifu.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29C10"
        },
        [80220137] = {
          ContentEN = "I may be old, but I'm not blind. I knew the minute you brought it back a year ago. It's been darting about ever since.",
          DialogueId = 80220137,
          GUID = "C8D29C3A",
          NextDialogue = 80220138,
          Subtitle = "I may be old, but I'm not blind. I knew the minute you brought it back a year ago. It's been darting about ever since.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29C3A"
        },
        [80220138] = {
          ContentEN = "I hadn't seen it for days, so I came to have a look. Then I find the two of you here, looking all troubled. Thought I'd ask what was wrong. Didn't expect you to try and pull the wool over my eyes.",
          DialogueId = 80220138,
          GUID = "C8D29C64",
          NextDialogue = 80220139,
          Subtitle = "I hadn't seen it for days, so I came to have a look. Then I find the two of you here, looking all troubled. Thought I'd ask what was wrong. Didn't expect you to try and pull the wool over my eyes.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29C64"
        },
        [80220139] = {
          ContentEN = "Well, it's just... you always seem so serene, so otherworldly, Shifu! I figured a venerable elder like you would prefer cranes or deer, not a fox. So I didn't dare bring it up...",
          DialogueId = 80220139,
          GUID = "C8D29C8E",
          NextDialogue = 80220140,
          Subtitle = "Well, it's just... you always seem so serene, so otherworldly, Shifu! I figured a venerable elder like you would prefer cranes or deer, not a fox. So I didn't dare bring it up...",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29C8E"
        },
        [80220140] = {
          ContentEN = "Still running your mouth. You picked that up from Kezhou too, didn't you? Since when have I ever been so particular? Go on — what's the problem?",
          DialogueId = 80220140,
          GUID = "C8D29CB8",
          NextDialogue = 80220141,
          Subtitle = "Still running your mouth. You picked that up from Kezhou too, didn't you? Since when have I ever been so particular? Go on — what's the problem?",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29CB8"
        },
        [80220141] = {
          ContentEN = "(Buxia and Yuming explain what happened to Little Tangerine.)",
          DialogueId = 80220141,
          GUID = "C8D29CE2",
          NextDialogue = 80220142,
          Subtitle = "(Buxia and Yuming explain what happened to Little Tangerine.)",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29CE2"
        },
        [80220142] = {
          ContentEN = "Ha! I thought it was something serious. If it were me, I'd scoop it up and take it straight back to where it came from. The Outer Peaks isn't its home. It belongs out in the wild.",
          DialogueId = 80220142,
          GUID = "C8D29D0C",
          NextDialogue = 80220143,
          Subtitle = "Ha! I thought it was something serious. If it were me, I'd scoop it up and take it straight back to where it came from. The Outer Peaks isn't its home. It belongs out in the wild.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29D0C"
        },
        [80220143] = {
          ContentEN = "Th—That won't do! No one's going to feed it out there! And when it gets cold, who's going to add more bedding to its den?",
          DialogueId = 80220143,
          GUID = "C8D29D36",
          NextDialogue = 80220144,
          Subtitle = "Th—That won't do! No one's going to feed it out there! And when it gets cold, who's going to add more bedding to its den?",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29D36"
        },
        [80220144] = {
          ContentEN = "That's exactly the problem. You keep doing everything for it, so it never learns to fend for itself.",
          DialogueId = 80220144,
          GUID = "C8D29D60",
          NextDialogue = 80220145,
          Subtitle = "That's exactly the problem. You keep doing everything for it, so it never learns to fend for itself.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29D60"
        },
        [80220145] = {
          ContentEN = "You built it a shelter to keep the rain off, but you never taught it how to make it through winter. You fed it, but you never taught it how to hunt.",
          DialogueId = 80220145,
          GUID = "C8D29D8A",
          NextDialogue = 80220146,
          Subtitle = "You built it a shelter to keep the rain off, but you never taught it how to make it through winter. You fed it, but you never taught it how to hunt.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29D8A"
        },
        [80220146] = {
          ContentEN = "Now when it's hungry or cold, it just waits for you. How's it supposed to survive on its own? If one day my silly disciples slip up and fail to watch over it, one night of heavy rain would be enough to finish it.",
          DialogueId = 80220146,
          GUID = "C8D29DB4",
          NextDialogue = 80220147,
          Subtitle = "Now when it's hungry or cold, it just waits for you. How's it supposed to survive on its own? If one day my silly disciples slip up and fail to watch over it, one night of heavy rain would be enough to finish it.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29DB4"
        },
        [80220147] = {
          ContentEN = "S—So... you're saying...?",
          DialogueId = 80220147,
          GUID = "C8D29DDE",
          NextDialogue = 80220148,
          Subtitle = "S—So... you're saying...?",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29DDE"
        },
        [80220148] = {
          ContentEN = "No matter how reluctant you are, it has to go back to the wild. That's where it belongs. Coddle it, and you'll only rob it of the chance to learn how to live.",
          DialogueId = 80220148,
          GUID = "C8D29E08",
          NextDialogue = 80220149,
          Subtitle = "No matter how reluctant you are, it has to go back to the wild. That's where it belongs. Coddle it, and you'll only rob it of the chance to learn how to live.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29E08"
        },
        [80220149] = {
          ContentEN = "...I understand. Let me talk it over with my two Shixiong first...",
          DialogueId = 80220149,
          GUID = "C8D29E32",
          NextDialogue = 80220150,
          Subtitle = "...I understand. Let me talk it over with my two Shixiong first...",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29E32"
        },
        [80220150] = {
          ContentEN = "...",
          DialogueId = 80220150,
          GUID = "C8D29E5C",
          NextDialogue = 80220151,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29E5C"
        },
        [80220151] = {
          ContentEN = "Yuming. Something's on your mind.",
          DialogueId = 80220151,
          GUID = "C8D29E86",
          NextDialogue = 80220152,
          Subtitle = "Yuming. Something's on your mind.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29E86"
        },
        [80220152] = {
          ContentEN = "...No.",
          DialogueId = 80220152,
          GUID = "C8D29EB0",
          NextDialogue = 80220153,
          Subtitle = "...No.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29EB0"
        },
        [80220153] = {
          ContentEN = "Only one word this time? That means you're lying again.",
          DialogueId = 80220153,
          GUID = "C8D29EDA",
          NextDialogue = 80220154,
          Subtitle = "Only one word this time? That means you're lying again.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29EDA"
        },
        [80220154] = {
          ContentEN = "...Sorry, Shifu. I was foolish.",
          DialogueId = 80220154,
          GUID = "C8D29F04",
          NextDialogue = 80220155,
          Subtitle = "...Sorry, Shifu. I was foolish.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29F04"
        },
        [80220155] = {
          ContentEN = "Maybe we shouldn't have taken Little Tangerine in that day. But we did.",
          DialogueId = 80220155,
          GUID = "C8D29F2E",
          NextDialogue = 80220156,
          Subtitle = "Maybe we shouldn't have taken Little Tangerine in that day. But we did.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29F2E"
        },
        [80220156] = {
          ContentEN = "You're right — it's been with us too long. It wouldn't last on its own. If we release it back into the wild now... I'm afraid it will—",
          DialogueId = 80220156,
          GUID = "C8D29F58",
          NextDialogue = 80220157,
          Subtitle = "You're right — it's been with us too long. It wouldn't last on its own. If we release it back into the wild now... I'm afraid it will—",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29F58"
        },
        [80220157] = {
          ContentEN = "Freeze to death. Or starve to death. Of course I know that. But listen: if you choose to do it, don't flinch. If you can't bear it, don't even start.",
          DialogueId = 80220157,
          GUID = "C8D29F82",
          NextDialogue = 80220158,
          Subtitle = "Freeze to death. Or starve to death. Of course I know that. But listen: if you choose to do it, don't flinch. If you can't bear it, don't even start.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29F82"
        },
        [80220158] = {
          ContentEN = "With every choice, you gain something — and you lose something. Like us Drifters: we left the protection of the Nine Chapters and chose to rely on ourselves. It isn't about right or wrong. It's simply a choice.",
          DialogueId = 80220158,
          GUID = "C8D29FAC",
          NextDialogue = 80220159,
          Subtitle = "With every choice, you gain something — and you lose something. Like us Drifters: we left the protection of the Nine Chapters and chose to rely on ourselves. It isn't about right or wrong. It's simply a choice.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29FAC"
        },
        [80220159] = {
          ContentEN = "All I want is for you to think before you choose. Live without regret.",
          DialogueId = 80220159,
          GUID = "C8D29FD6",
          NextDialogue = 80220160,
          Subtitle = "All I want is for you to think before you choose. Live without regret.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29FD6"
        },
        [80220160] = {
          ContentEN = "Understood, Shifu.",
          DialogueId = 80220160,
          GUID = "C8D2A000",
          Subtitle = "Understood, Shifu.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D2A000"
        },
        [80220201] = {
          ContentEN = "...",
          DialogueId = 80220201,
          GUID = "C8D2A6BA",
          NextDialogue = 80220202,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2A6BA"
        },
        [80220202] = {
          ContentEN = "Wh—What is that!? That's... Buxia!? She's turned into a monster!",
          DialogueId = 80220202,
          GUID = "C8D2A6E4",
          NextDialogue = 80220203,
          Subtitle = "Wh—What is that!? That's... Buxia!? She's turned into a monster!",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2A6E4"
        },
        [80220203] = {
          ContentEN = "N—No... stay back! I don't want to die!",
          DialogueId = 80220203,
          GUID = "C8D2A70E",
          NextDialogue = 80220204,
          Subtitle = "N—No... stay back! I don't want to die!",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2A70E"
        },
        [80220204] = {
          ContentEN = "Could this be... Lord Argent's punishment? For betraying their grace?",
          DialogueId = 80220204,
          GUID = "C8D2A738",
          NextDialogue = 80220205,
          Subtitle = "Could this be... Lord Argent's punishment? For betraying their grace?",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2A738"
        },
        [80220205] = {
          ContentEN = "Dad... Dad! ...Please... wake up! Say something... Dad...",
          DialogueId = 80220205,
          GUID = "C8D2A762",
          NextDialogue = 80220206,
          Subtitle = "Dad... Dad! ...Please... wake up! Say something... Dad...",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2A762"
        },
        [80220206] = {
          ContentEN = "Shixiong... help... I don't want to...",
          DialogueId = 80220206,
          GUID = "C8D2A78C",
          NextDialogue = 80220207,
          Subtitle = "Shixiong... help... I don't want to...",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2A78C"
        },
        [80220207] = {
          ContentEN = "...",
          DialogueId = 80220207,
          GUID = "C8D2A7B6",
          NextDialogue = 80220208,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2A7B6"
        },
        [80220208] = {
          ContentEN = "Did you show me all this... Taihao?",
          DialogueId = 80220208,
          GUID = "C8D2A7E0",
          NextDialogue = 80220209,
          Subtitle = "Did you show me all this... Taihao?",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2A7E0"
        },
        [80220209] = {
          ContentEN = "Not I. I have no desire to pry into mortal minds.",
          DialogueId = 80220209,
          GUID = "C8D2A80A",
          NextDialogue = 80220210,
          Subtitle = "Not I. I have no desire to pry into mortal minds.",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2A80A"
        },
        [80220210] = {
          ContentEN = "Then why are you here? I'm only mortal. And I'm a Drifter — one who turned away from you.",
          DialogueId = 80220210,
          GUID = "C8D2A834",
          NextDialogue = 80220211,
          Subtitle = "Then why are you here? I'm only mortal. And I'm a Drifter — one who turned away from you.",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2A834"
        },
        [80220211] = {
          ContentEN = "Your heart called, and I answered. You are not one meant for confinement.",
          DialogueId = 80220211,
          GUID = "C8D2A85E",
          NextDialogue = 80220212,
          Subtitle = "Your heart called, and I answered. You are not one meant for confinement.",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2A85E"
        },
        [80220212] = {
          ContentEN = "...I didn't know my heart had reached for you.",
          DialogueId = 80220212,
          GUID = "C8D2A888",
          NextDialogue = 80220213,
          Subtitle = "...I didn't know my heart had reached for you.",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2A888"
        },
        [80220213] = {
          ContentEN = "What you beheld was an old nightmare. It yet binds you.",
          DialogueId = 80220213,
          GUID = "C8D2A8B2",
          NextDialogue = 80220214,
          Subtitle = "What you beheld was an old nightmare. It yet binds you.",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2A8B2"
        },
        [80220214] = {
          ContentEN = "...I know.",
          DialogueId = 80220214,
          GUID = "C8D2A8DC",
          NextDialogue = 80220215,
          Subtitle = "...I know.",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2A8DC"
        },
        [80220215] = {
          ContentEN = "Is this the place of her final rest?",
          DialogueId = 80220215,
          GUID = "C8D2A906",
          NextDialogue = 80220216,
          Subtitle = "Is this the place of her final rest?",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2A906"
        },
        [80220216] = {
          ContentEN = "She... changed into something else. I couldn't even recover her body. All I had left were a few of her old clothes.",
          DialogueId = 80220216,
          GUID = "C8D2A930",
          NextDialogue = 80220217,
          Subtitle = "She... changed into something else. I couldn't even recover her body. All I had left were a few of her old clothes.",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2A930"
        },
        [80220217] = {
          ContentEN = "And I buried them here, not at the Outer Peaks...",
          DialogueId = 80220217,
          GUID = "C8D2A95A",
          NextDialogue = 80220218,
          Subtitle = "And I buried them here, not at the Outer Peaks...",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2A95A"
        },
        [80220218] = {
          ContentEN = "...because of her last words: \"If I hadn't turned my back on the Nine Chapters of Dafeng... would it have ended differently?\"",
          DialogueId = 80220218,
          GUID = "C8D2A984",
          NextDialogue = 80220219,
          Subtitle = "...because of her last words: \"If I hadn't turned my back on the Nine Chapters of Dafeng... would it have ended differently?\"",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2A984"
        },
        [80220219] = {
          ContentEN = "Founding Master Fufeng taught us this: a physician makes no distinction among the sick — not even Drifters. So long as there's a shred of hope, how could I refuse to treat her?",
          DialogueId = 80220219,
          GUID = "C8D2A9AE",
          NextDialogue = 80220220,
          Subtitle = "Founding Master Fufeng taught us this: a physician makes no distinction among the sick — not even Drifters. So long as there's a shred of hope, how could I refuse to treat her?",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2A9AE"
        },
        [80220220] = {
          ContentEN = "But it was Deterioration... an incurable affliction! Once it takes hold, there's no turning it back. She's about to become something inhuman. Go — while you still can. Run for your lives!",
          DialogueId = 80220220,
          GUID = "C8D2A9D8",
          NextDialogue = 80220221,
          Subtitle = "But it was Deterioration... an incurable affliction! Once it takes hold, there's no turning it back. She's about to become something inhuman. Go — while you still can. Run for your lives!",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2A9D8"
        },
        [80220221] = {
          ContentEN = "... If you Drifters hadn't been so set on turning your backs on the Nine Chapters' protection, it wouldn't have come to this...",
          DialogueId = 80220221,
          GUID = "C8D2AA02",
          NextDialogue = 80220222,
          Subtitle = "... If you Drifters hadn't been so set on turning your backs on the Nine Chapters' protection, it wouldn't have come to this...",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2AA02"
        },
        [80220222] = {
          ContentEN = "All I want is for you to think before you choose. Live without regret.",
          DialogueId = 80220222,
          GUID = "C8D2AA2C",
          NextDialogue = 80220223,
          Subtitle = "All I want is for you to think before you choose. Live without regret.",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2AA2C"
        },
        [80220223] = {
          ContentEN = "...Choice.",
          DialogueId = 80220223,
          GUID = "C8D2AA56",
          NextDialogue = 80220224,
          Subtitle = "...Choice.",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2AA56"
        },
        [80220224] = {
          ContentEN = "Taihao... if we had chosen the Nine Chapters of Dafeng, would things have turned out differently?",
          DialogueId = 80220224,
          GUID = "C8D2AA80",
          NextDialogue = 80220225,
          Subtitle = "Taihao... if we had chosen the Nine Chapters of Dafeng, would things have turned out differently?",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2AA80"
        },
        [80220225] = {
          ContentEN = "You Drifters crave freedom, yet you forget this: a kite without its line will fall, and a river without its banks will flood.",
          DialogueId = 80220225,
          GUID = "C8D2AAAA",
          NextDialogue = 80220226,
          Subtitle = "You Drifters crave freedom, yet you forget this: a kite without its line will fall, and a river without its banks will flood.",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2AAAA"
        },
        [80220226] = {
          ContentEN = "What is past cannot be changed. What lies ahead is yet unwritten. To turn back from the wrong road is not too late.",
          DialogueId = 80220226,
          GUID = "C8D2AAD4",
          NextDialogue = 80220227,
          Subtitle = "What is past cannot be changed. What lies ahead is yet unwritten. To turn back from the wrong road is not too late.",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2AAD4"
        },
        [80220227] = {
          ContentEN = "I have spoken. Consider well.",
          DialogueId = 80220227,
          GUID = "C8D2AAFE",
          NextDialogue = 80220228,
          Subtitle = "I have spoken. Consider well.",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2AAFE"
        },
        [80220228] = {
          ContentEN = "Taihao's apparition fades into the heavens.",
          DialogueId = 80220228,
          GUID = "C8D2AB28",
          NextDialogue = 80220229,
          Subtitle = "Taihao's apparition fades into the heavens.",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2AB28"
        },
        [80220229] = {
          ContentEN = "Yip...",
          DialogueId = 80220229,
          GUID = "C8D2AB52",
          NextDialogue = 80220230,
          Subtitle = "Yip...",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2AB52"
        },
        [80220230] = {
          ContentEN = "...Tangerine? You're still alive. So you made it out of the Outer Peaks that day...",
          DialogueId = 80220230,
          GUID = "C8D2AB7C",
          NextDialogue = 80220231,
          Subtitle = "...Tangerine? You're still alive. So you made it out of the Outer Peaks that day...",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2AB7C"
        },
        [80220231] = {
          ContentEN = "Yip... yip...",
          DialogueId = 80220231,
          GUID = "C8D2ABA6",
          NextDialogue = 80220232,
          Subtitle = "Yip... yip...",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2ABA6"
        },
        [80220232] = {
          ContentEN = "Are you... crying?",
          DialogueId = 80220232,
          GUID = "C8D2ABD0",
          NextDialogue = 80220233,
          Subtitle = "Are you... crying?",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2ABD0"
        },
        [80220233] = {
          ContentEN = "Is it for Buxia? For our Shifu? For the innocents who died? Or is it for me... because I started to waver?",
          DialogueId = 80220233,
          GUID = "C8D2ABFA",
          NextDialogue = 80220234,
          Subtitle = "Is it for Buxia? For our Shifu? For the innocents who died? Or is it for me... because I started to waver?",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2ABFA"
        },
        [80220234] = {
          ContentEN = "Yip...",
          DialogueId = 80220234,
          GUID = "C8D2AC24",
          NextDialogue = 80220235,
          Subtitle = "Yip...",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2AC24"
        },
        [80220235] = {
          ContentEN = "Do you want me to take you back to the Outer Peaks?",
          DialogueId = 80220235,
          GUID = "C8D2AC4E",
          NextDialogue = 80220236,
          Subtitle = "Do you want me to take you back to the Outer Peaks?",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2AC4E"
        },
        [80220236] = {
          ContentEN = "Yip!",
          DialogueId = 80220236,
          GUID = "C8D2AC78",
          NextDialogue = 80220237,
          Subtitle = "Yip!",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2AC78"
        },
        [80220237] = {
          ContentEN = "I'm sorry. I can't go back.",
          DialogueId = 80220237,
          GUID = "C8D2ACA2",
          NextDialogue = 80220238,
          Subtitle = "I'm sorry. I can't go back.",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2ACA2"
        },
        [80220238] = {
          ContentEN = "(It's grown used to humans sheltering it. Away from the Outer Peaks... it wouldn't last long.)",
          DialogueId = 80220238,
          GUID = "C8D2ACCC",
          NextDialogue = 80220239,
          Subtitle = "(It's grown used to humans sheltering it. Away from the Outer Peaks... it wouldn't last long.)",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2ACCC"
        },
        [80220239] = {
          ContentEN = "The Outer Peaks are that way. Whether you go back or not... that's your choice.",
          DialogueId = 80220239,
          GUID = "C8D2ACF6",
          Subtitle = "The Outer Peaks are that way. Whether you go back or not... that's your choice.",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2ACF6"
        },
        [80220301] = {
          ContentEN = "...Huff... huff...",
          DialogueId = 80220301,
          GUID = "C8D2B722",
          NextDialogue = 80220302,
          Subtitle = "...Huff... huff...",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2B722"
        },
        [80220302] = {
          ContentEN = "You were quiet back at the Outer Peaks. Who knew you'd be so good at wagging your tail for them.",
          DialogueId = 80220302,
          GUID = "C8D2B74C",
          NextDialogue = 80220303,
          Subtitle = "You were quiet back at the Outer Peaks. Who knew you'd be so good at wagging your tail for them.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2B74C"
        },
        [80220303] = {
          ContentEN = "...Surrender.",
          DialogueId = 80220303,
          GUID = "C8D2B776",
          NextDialogue = 80220304,
          Subtitle = "...Surrender.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2B776"
        },
        [80220304] = {
          ContentEN = "\"Surrender\"? That's rich. If people didn't know better, they'd think I was the criminal here.",
          DialogueId = 80220304,
          GUID = "C8D2B7A0",
          NextDialogue = 80220305,
          Subtitle = "\"Surrender\"? That's rich. If people didn't know better, they'd think I was the criminal here.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2B7A0"
        },
        [80220305] = {
          ContentEN = "You've wounded people and taken lives. That makes you a criminal. Repent — it's the only way left.",
          DialogueId = 80220305,
          GUID = "C8D2B7CA",
          NextDialogue = 80220306,
          Subtitle = "You've wounded people and taken lives. That makes you a criminal. Repent — it's the only way left.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2B7CA"
        },
        [80220306] = {
          ContentEN = "Repent? Don't make me laugh. That old rotter twisted the loan agreement and bled innocent folk dry. I simply carried out justice in Heaven's name.",
          DialogueId = 80220306,
          GUID = "C8D2B7F4",
          NextDialogue = 80220307,
          Subtitle = "Repent? Don't make me laugh. That old rotter twisted the loan agreement and bled innocent folk dry. I simply carried out justice in Heaven's name.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2B7F4"
        },
        [80220307] = {
          ContentEN = "Abusing power is no justice. The Heavenly Way has no need of mortals acting in its name.",
          DialogueId = 80220307,
          GUID = "C8D2B81E",
          NextDialogue = 80220308,
          Subtitle = "Abusing power is no justice. The Heavenly Way has no need of mortals acting in its name.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2B81E"
        },
        [80220308] = {
          ContentEN = "Is that so? Then tell me — when that crafty rotter used a rigged loan agreement to swindle people out of everything they had, where was your \"Heavenly Way\"? Where were the Nine Chapters?",
          DialogueId = 80220308,
          GUID = "C8D2B848",
          NextDialogue = 80220309,
          Subtitle = "Is that so? Then tell me — when that crafty rotter used a rigged loan agreement to swindle people out of everything they had, where was your \"Heavenly Way\"? Where were the Nine Chapters?",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2B848"
        },
        [80220309] = {
          ContentEN = "The Nine Chapters weren't forged overnight, and they aren't beyond change. How such evil is dealt with is for Lord Argent to decide — not you, not me. We have no right to overstep.",
          DialogueId = 80220309,
          GUID = "C8D2B872",
          NextDialogue = 80220310,
          Subtitle = "The Nine Chapters weren't forged overnight, and they aren't beyond change. How such evil is dealt with is for Lord Argent to decide — not you, not me. We have no right to overstep.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2B872"
        },
        [80220310] = {
          ContentEN = "...Heh. Pretty words. Come on, then. Let me see what a Magistrate of Yingtian is really worth.",
          DialogueId = 80220310,
          GUID = "C8D2B89C",
          NextDialogue = 80220311,
          Subtitle = "...Heh. Pretty words. Come on, then. Let me see what a Magistrate of Yingtian is really worth.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2B89C"
        },
        [80220311] = {
          ContentEN = "Yuming clashes steel with the Drifter. The Drifter goes down in a few exchanges.\nA spear drives for his chest — but doesn't pierce.\nA jade belt clasp, snapped clean in two, falls free.",
          DialogueId = 80220311,
          GUID = "C8D2B8C6",
          NextDialogue = 80220312,
          Subtitle = "Yuming clashes steel with the Drifter. The Drifter goes down in a few exchanges.\nA spear drives for his chest — but doesn't pierce.\nA jade belt clasp, snapped clean in two, falls free.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2B8C6"
        },
        [80220312] = {
          ContentEN = "That's... Shifu's...",
          DialogueId = 80220312,
          GUID = "C8D2B8F0",
          NextDialogue = 80220313,
          Subtitle = "That's... Shifu's...",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2B8F0"
        },
        [80220313] = {
          ContentEN = "When Deterioration took Buxia, he stayed behind so the rest of us could get out. I found that clasp lying in his blood.",
          DialogueId = 80220313,
          GUID = "C8D2B91A",
          NextDialogue = 80220314,
          Subtitle = "When Deterioration took Buxia, he stayed behind so the rest of us could get out. I found that clasp lying in his blood.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2B91A"
        },
        [80220314] = {
          ContentEN = "I pieced it back together as carefully as I could, just to keep a piece of him. But... I guess what's broken can never truly be mended.",
          DialogueId = 80220314,
          GUID = "C8D2B944",
          NextDialogue = 80220315,
          Subtitle = "I pieced it back together as carefully as I could, just to keep a piece of him. But... I guess what's broken can never truly be mended.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2B944"
        },
        [80220315] = {
          ContentEN = "Among us Drifters, everyone looked up to Yan Shanting. He lived free. He stayed true to himself, no matter how many stood against him. A man of his word.",
          DialogueId = 80220315,
          GUID = "C8D2B96E",
          NextDialogue = 80220316,
          Subtitle = "Among us Drifters, everyone looked up to Yan Shanting. He lived free. He stayed true to himself, no matter how many stood against him. A man of his word.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2B96E"
        },
        [80220316] = {
          ContentEN = "But look at you now... Mr Magistrate of Yingtian. His prized disciple — turned back on the Drifters, just to go wagging your tail for that dumb loong!",
          DialogueId = 80220316,
          GUID = "C8D2B998",
          NextDialogue = 80220317,
          Subtitle = "But look at you now... Mr Magistrate of Yingtian. His prized disciple — turned back on the Drifters, just to go wagging your tail for that dumb loong!",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2B998"
        },
        [80220317] = {
          ContentEN = "...",
          DialogueId = 80220317,
          GUID = "C8D2B9C2",
          NextDialogue = 80220318,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2B9C2"
        },
        [80220318] = {
          ContentEN = "...Go. If you survived that strike, then Heaven has not decreed your end.",
          DialogueId = 80220318,
          GUID = "C8D2B9EC",
          NextDialogue = 80220319,
          Subtitle = "...Go. If you survived that strike, then Heaven has not decreed your end.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2B9EC"
        },
        [80220319] = {
          ContentEN = "...Hmph.",
          DialogueId = 80220319,
          GUID = "C8D2BA16",
          NextDialogue = 80220320,
          Subtitle = "...Hmph.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BA16"
        },
        [80220320] = {
          ContentEN = "The Drifter glares at Yuming, then turns and runs, vanishing into the rain...",
          DialogueId = 80220320,
          GUID = "C8D2BA40",
          NextDialogue = 80220321,
          Subtitle = "The Drifter glares at Yuming, then turns and runs, vanishing into the rain...",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BA40"
        },
        [80220321] = {
          ContentEN = "That should have been the end.",
          DialogueId = 80220321,
          GUID = "C8D2BA6A",
          NextDialogue = 80220322,
          Subtitle = "That should have been the end.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BA6A"
        },
        [80220322] = {
          ContentEN = "But a violent wind surges from behind. Before Yuming can react, the Drifter goes slack and collapses.",
          DialogueId = 80220322,
          GUID = "C8D2BA94",
          NextDialogue = 80220323,
          Subtitle = "But a violent wind surges from behind. Before Yuming can react, the Drifter goes slack and collapses.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BA94"
        },
        [80220323] = {
          ContentEN = "A Bi'an is already on him. Its claws drive straight through his chest.",
          DialogueId = 80220323,
          GUID = "C8D2BABE",
          NextDialogue = 80220324,
          Subtitle = "A Bi'an is already on him. Its claws drive straight through his chest.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BABE"
        },
        [80220324] = {
          ContentEN = "ROAR—!",
          DialogueId = 80220324,
          GUID = "C8D2BAE8",
          NextDialogue = 80220325,
          Subtitle = "ROAR—!",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BAE8"
        },
        [80220325] = {
          ContentEN = "...",
          DialogueId = 80220325,
          GUID = "C8D2BB12",
          NextDialogue = 80220326,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BB12"
        },
        [80220326] = {
          ContentEN = "Yuming.",
          DialogueId = 80220326,
          GUID = "C8D2BB3C",
          NextDialogue = 80220327,
          Subtitle = "Yuming.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BB3C"
        },
        [80220327] = {
          ContentEN = "...",
          DialogueId = 80220327,
          GUID = "C8D2BB66",
          NextDialogue = 80220328,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BB66"
        },
        [80220328] = {
          ContentEN = "Shifu...",
          DialogueId = 80220328,
          GUID = "C8D2BB90",
          NextDialogue = 80220329,
          Subtitle = "Shifu...",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BB90"
        },
        [80220329] = {
          ContentEN = "Yuming. Look at you — taller, broader in the shoulders.",
          DialogueId = 80220329,
          GUID = "C8D2BBBA",
          NextDialogue = 80220330,
          Subtitle = "Yuming. Look at you — taller, broader in the shoulders.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BBBA"
        },
        [80220330] = {
          ContentEN = "But Shifu, I stopped growing years ago.",
          DialogueId = 80220330,
          GUID = "C8D2BBE4",
          NextDialogue = 80220331,
          Subtitle = "But Shifu, I stopped growing years ago.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BBE4"
        },
        [80220331] = {
          ContentEN = "You brat! I was ready for a mushy reunion, and you just had to spoil it.",
          DialogueId = 80220331,
          GUID = "C8D2BC0E",
          NextDialogue = 80220332,
          Subtitle = "You brat! I was ready for a mushy reunion, and you just had to spoil it.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BC0E"
        },
        [80220332] = {
          ContentEN = "What's wrong? That miserable look again. What's on your mind?",
          DialogueId = 80220332,
          GUID = "C8D2BC38",
          NextDialogue = 80220333,
          Subtitle = "What's wrong? That miserable look again. What's on your mind?",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BC38"
        },
        [80220333] = {
          ContentEN = "...Nothing.",
          DialogueId = 80220333,
          GUID = "C8D2BC62",
          NextDialogue = 80220334,
          Subtitle = "...Nothing.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BC62"
        },
        [80220334] = {
          ContentEN = "You're lying again. Every time you lie, you can barely string two words together. You can't fool me.",
          DialogueId = 80220334,
          GUID = "C8D2BC8C",
          NextDialogue = 80220335,
          Subtitle = "You're lying again. Every time you lie, you can barely string two words together. You can't fool me.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BC8C"
        },
        [80220335] = {
          ContentEN = "Shifu... Have you come to scold me?",
          DialogueId = 80220335,
          GUID = "C8D2BCB6",
          NextDialogue = 80220336,
          Subtitle = "Shifu... Have you come to scold me?",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BCB6"
        },
        [80220336] = {
          ContentEN = "I failed you. I crossed blades with old allies.",
          DialogueId = 80220336,
          GUID = "C8D2BCE0",
          NextDialogue = 80220337,
          Subtitle = "I failed you. I crossed blades with old allies.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BCE0"
        },
        [80220337] = {
          ContentEN = "I turned my back on you. On the Drifters. I chose the Nine Chapters of Dafeng. I don't know how I can face you now.",
          DialogueId = 80220337,
          GUID = "C8D2BD0A",
          NextDialogue = 80220338,
          Subtitle = "I turned my back on you. On the Drifters. I chose the Nine Chapters of Dafeng. I don't know how I can face you now.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BD0A"
        },
        [80220338] = {
          ContentEN = "Still stubborn as a mule, I see. I've prided myself on my wits all my life — how did I end up with a disciple as thick as you?",
          DialogueId = 80220338,
          GUID = "C8D2BD34",
          NextDialogue = 80220339,
          Subtitle = "Still stubborn as a mule, I see. I've prided myself on my wits all my life — how did I end up with a disciple as thick as you?",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BD34"
        },
        [80220339] = {
          ContentEN = "...I'm sorry, Shifu.",
          DialogueId = 80220339,
          GUID = "C8D2BD5E",
          NextDialogue = 80220340,
          Subtitle = "...I'm sorry, Shifu.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BD5E"
        },
        [80220340] = {
          ContentEN = "Answer me one thing. Have you ever regretted it?",
          DialogueId = 80220340,
          GUID = "C8D2BD88",
          NextDialogue = 80220341,
          Subtitle = "Answer me one thing. Have you ever regretted it?",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BD88"
        },
        [80220341] = {
          ContentEN = "I... I don't know.",
          DialogueId = 80220341,
          GUID = "C8D2BDB2",
          NextDialogue = 80220342,
          Subtitle = "I... I don't know.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BDB2"
        },
        [80220342] = {
          ContentEN = "Then I'll ask it another way. If you could turn back time, would you still choose to become a Magistrate of Yingtian?",
          DialogueId = 80220342,
          GUID = "C8D2BDDC",
          NextDialogue = 80220343,
          Subtitle = "Then I'll ask it another way. If you could turn back time, would you still choose to become a Magistrate of Yingtian?",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BDDC"
        },
        [80220343] = {
          ContentEN = "...Yes.",
          DialogueId = 80220343,
          GUID = "C8D2BE06",
          NextDialogue = 80220344,
          Subtitle = "...Yes.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BE06"
        },
        [80220344] = {
          ContentEN = "Why?",
          DialogueId = 80220344,
          GUID = "C8D2BE30",
          NextDialogue = 80220345,
          Subtitle = "Why?",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BE30"
        },
        [80220345] = {
          ContentEN = "Under the Nine Chapters of Dafeng, we gave up some freedom, and the right to act on right and wrong as we saw fit. But... <H>flawed rules are still better than none</>.",
          DialogueId = 80220345,
          GUID = "C8D2BE5A",
          NextDialogue = 80220346,
          Subtitle = "Under the Nine Chapters of Dafeng, we gave up some freedom, and the right to act on right and wrong as we saw fit. But... flawed rules are still better than none.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BE5A"
        },
        [80220346] = {
          ContentEN = "Without the Nine Chapters, the world would fall apart. Even the Drifters, punishing evil and righting wrongs, can only do so much.",
          DialogueId = 80220346,
          GUID = "C8D2BE84",
          NextDialogue = 80220347,
          Subtitle = "Without the Nine Chapters, the world would fall apart. Even the Drifters, punishing evil and righting wrongs, can only do so much.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BE84"
        },
        [80220347] = {
          ContentEN = "And I... I don't want what happened to Buxia to happen to anyone again.",
          DialogueId = 80220347,
          GUID = "C8D2BEAE",
          NextDialogue = 80220348,
          Subtitle = "And I... I don't want what happened to Buxia to happen to anyone again.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BEAE"
        },
        [80220348] = {
          ContentEN = "...I don't want to watch another man like you die, even as a hero.",
          DialogueId = 80220348,
          GUID = "C8D2BED8",
          NextDialogue = 80220349,
          Subtitle = "...I don't want to watch another man like you die, even as a hero.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BED8"
        },
        [80220349] = {
          ContentEN = "Ha... haha! If you've followed your own heart, what more is there to say? Choice or no choice back then, give you another chance and you'd still decide the same. So who has the right to judge?",
          DialogueId = 80220349,
          GUID = "C8D2BF02",
          NextDialogue = 80220350,
          Subtitle = "Ha... haha! If you've followed your own heart, what more is there to say? Choice or no choice back then, give you another chance and you'd still decide the same. So who has the right to judge?",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BF02"
        },
        [80220350] = {
          ContentEN = "Even if the man I am now stands against you... against the Shifu I once looked up to?",
          DialogueId = 80220350,
          GUID = "C8D2BF2C",
          NextDialogue = 80220351,
          Subtitle = "Even if the man I am now stands against you... against the Shifu I once looked up to?",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BF2C"
        },
        [80220351] = {
          ContentEN = "When we're young, we follow our parents. When we come of age, our teachers. Later, those in power. Later still, our children. But if a man spends his whole life walking a road laid out by others — never once choosing for himself — then he's never truly lived.",
          DialogueId = 80220351,
          GUID = "C8D2BF56",
          NextDialogue = 80220352,
          Subtitle = "When we're young, we follow our parents. When we come of age, our teachers. Later, those in power. Later still, our children. But if a man spends his whole life walking a road laid out by others — never once choosing for himself — then he's never truly lived.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BF56"
        },
        [80220352] = {
          ContentEN = "I taught you only one thing: <H>live without regret</>. I never taught you to follow me blindly and nod along to everything I say.",
          DialogueId = 80220352,
          GUID = "C8D2BF80",
          NextDialogue = 80220353,
          Subtitle = "I taught you only one thing: live without regret. I never taught you to follow me blindly and nod along to everything I say.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BF80"
        },
        [80220353] = {
          ContentEN = "Yuming, do you remember why I rebelled against the Nine Chapters?",
          DialogueId = 80220353,
          GUID = "C8D2BFAA",
          NextDialogue = 80220354,
          Subtitle = "Yuming, do you remember why I rebelled against the Nine Chapters?",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BFAA"
        },
        [80220354] = {
          ContentEN = "So people wouldn't be trapped in a cage, never learning to stand on their own?",
          DialogueId = 80220354,
          GUID = "C8D2BFD4",
          NextDialogue = 80220355,
          Subtitle = "So people wouldn't be trapped in a cage, never learning to stand on their own?",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BFD4"
        },
        [80220355] = {
          ContentEN = "No. It was to seize, beyond the Heavenly Way, <H>the right to choose another path</>.",
          DialogueId = 80220355,
          GUID = "C8D2BFFE",
          NextDialogue = 80220356,
          Subtitle = "No. It was to seize, beyond the Heavenly Way, the right to choose another path.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BFFE"
        },
        [80220356] = {
          ContentEN = "The Outer Peaks stands against the Nine Chapters, yet it has always let people come and go freely. A Drifter should be a choice you make — not just another cage.",
          DialogueId = 80220356,
          GUID = "C8D2C028",
          NextDialogue = 80220357,
          Subtitle = "The Outer Peaks stands against the Nine Chapters, yet it has always let people come and go freely. A Drifter should be a choice you make — not just another cage.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2C028"
        },
        [80220357] = {
          ContentEN = "Stop punishing yourself, Yuming.",
          DialogueId = 80220357,
          GUID = "C8D2C052",
          NextDialogue = 80220358,
          Subtitle = "Stop punishing yourself, Yuming.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2C052"
        },
        [80220358] = {
          ContentEN = "I'm proud of you.",
          DialogueId = 80220358,
          GUID = "C8D2C07C",
          NextDialogue = 80220359,
          Subtitle = "I'm proud of you.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2C07C"
        },
        [80220359] = {
          ContentEN = "Shifu...",
          DialogueId = 80220359,
          GUID = "C8D2C0A6",
          NextDialogue = 80220360,
          Subtitle = "Shifu...",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2C0A6"
        },
        [80220360] = {
          ContentEN = "I won't forget what you taught me...!",
          DialogueId = 80220360,
          GUID = "C8D2C0D0",
          Subtitle = "I won't forget what you taught me...!",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2C0D0"
        },
        [80220401] = {
          ContentEN = "Yuming? Was that you?",
          DialogueId = 80220401,
          GUID = "C8D2C78A",
          NextDialogue = 80220402,
          Subtitle = "Yuming? Was that you?",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2C78A"
        },
        [80220402] = {
          ContentEN = "{nickname}... It's been a while.",
          DialogueId = 80220402,
          GUID = "C8D2C7B4",
          NextDialogue = 80220403,
          Subtitle = "... It's been a while.",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2C7B4"
        },
        [80220403] = {
          ContentEN = "I didn't know you could play the flute. I've never seen you do that before.",
          DialogueId = 80220403,
          GUID = "C8D2C7DE",
          NextDialogue = 80220404,
          Subtitle = "I didn't know you could play the flute. I've never seen you do that before.",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2C7DE"
        },
        [80220404] = {
          ContentEN = "I can't say I've done all I should for the people of Huaxu... but I've kept busy. There was always something that needed seeing to.",
          DialogueId = 80220404,
          GUID = "C8D2C808",
          NextDialogue = 80220405,
          Subtitle = "I can't say I've done all I should for the people of Huaxu... but I've kept busy. There was always something that needed seeing to.",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2C808"
        },
        [80220405] = {
          ContentEN = "Now things have settled. Zhuyin has returned to their place, and the Trial by Disputation has resumed. With mortals and gods governing together again, those of us acting in Taihao's stead have, at last, found ourselves with time to spare.",
          DialogueId = 80220405,
          GUID = "C8D2C832",
          NextDialogue = 80220406,
          Subtitle = "Now things have settled. Zhuyin has returned to their place, and the Trial by Disputation has resumed. With mortals and gods governing together again, those of us acting in Taihao's stead have, at last, found ourselves with time to spare.",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2C832"
        },
        [80220406] = {
          ContentEN = "You sound... a little lonely.",
          DialogueId = 80220406,
          GUID = "C8D2C85C",
          NextDialogue = 80220407,
          Subtitle = "You sound... a little lonely.",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2C85C"
        },
        [80220407] = {
          ContentEN = "Forgive me. I'm being sentimental.",
          DialogueId = 80220407,
          GUID = "C8D2C886",
          NextDialogue = 80220408,
          Subtitle = "Forgive me. I'm being sentimental.",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2C886"
        },
        [80220408] = {
          ContentEN = "The Outer Peaks... that was your home, right?",
          DialogueId = 80220408,
          GUID = "C8D2C8B0",
          NextDialogue = 80220409,
          Subtitle = "The Outer Peaks... that was your home, right?",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2C8B0"
        },
        [80220409] = {
          ContentEN = "Were you thinking of going back to see everyone?",
          DialogueId = 80220409,
          GUID = "C8D2C8DA",
          NextDialogue = 80220410,
          Subtitle = "Were you thinking of going back to see everyone?",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2C8DA"
        },
        [80220410] = {
          ContentEN = "...No.",
          DialogueId = 80220410,
          GUID = "C8D2C904",
          NextDialogue = 80220411,
          Subtitle = "...No.",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2C904"
        },
        [80220411] = {
          ContentEN = "I... was only passing through. I've been a Magistrate of Yingtian for too long now. We're not on the same road anymore.",
          DialogueId = 80220411,
          GUID = "C8D2C92E",
          NextDialogue = 80220412,
          Subtitle = "I... was only passing through. I've been a Magistrate of Yingtian for too long now. We're not on the same road anymore.",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2C92E"
        },
        [80220412] = {
          ContentEN = "I've done what Zhiliu asked of me. After that, we won't have any reason to cross paths again.",
          DialogueId = 80220412,
          GUID = "C8D2C958",
          NextDialogue = 80220413,
          Subtitle = "I've done what Zhiliu asked of me. After that, we won't have any reason to cross paths again.",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2C958"
        },
        [80220413] = {
          ContentEN = "That's a shame. I came looking for you because Kezhou asked me to pass on a message—",
          DialogueId = 80220413,
          GUID = "C8D2C982",
          NextDialogue = 80220414,
          Subtitle = "That's a shame. I came looking for you because Kezhou asked me to pass on a message—",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2C982"
        },
        [80220414] = {
          ContentEN = "What was it?",
          DialogueId = 80220414,
          GUID = "C8D2C9AC",
          NextDialogue = 80220415,
          Subtitle = "What was it?",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2C9AC"
        },
        [80220415] = {
          ContentEN = "See? You do still care about them.",
          DialogueId = 80220415,
          GUID = "C8D2C9D6",
          NextDialogue = 80220416,
          Subtitle = "See? You do still care about them.",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2C9D6"
        },
        [80220416] = {
          ContentEN = "...!",
          DialogueId = 80220416,
          GUID = "C8D2CA00",
          NextDialogue = 80220417,
          Subtitle = "...!",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CA00"
        },
        [80220417] = {
          ContentEN = "Heh.",
          DialogueId = 80220417,
          GUID = "C8D2CA2A",
          NextDialogue = 80220418,
          Subtitle = "Heh.",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CA2A"
        },
        [80220418] = {
          ContentEN = "You smiled. That's a rare sight. Like the local saying goes — \"Even ironwood blooms.\" Did I get that right?",
          DialogueId = 80220418,
          GUID = "C8D2CA54",
          NextDialogue = 80220419,
          Subtitle = "You smiled. That's a rare sight. Like the local saying goes — \"Even ironwood blooms.\" Did I get that right?",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CA54"
        },
        [80220419] = {
          ContentEN = "It's just... your jokes remind me of my Shifu.",
          DialogueId = 80220419,
          GUID = "C8D2CA7E",
          NextDialogue = 80220420,
          Subtitle = "It's just... your jokes remind me of my Shifu.",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CA7E"
        },
        [80220420] = {
          ContentEN = "Kezhou says he was a grumpy old man. Honestly... is that meant as a compliment, or are you taking a jab at me?",
          DialogueId = 80220420,
          GUID = "C8D2CAA8",
          NextDialogue = 80220421,
          Subtitle = "Kezhou says he was a grumpy old man. Honestly... is that meant as a compliment, or are you taking a jab at me?",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CAA8"
        },
        [80220421] = {
          ContentEN = "...{nickname}.",
          DialogueId = 80220421,
          GUID = "C8D2CAD2",
          NextDialogue = 80220422,
          Subtitle = "....",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CAD2"
        },
        [80220422] = {
          ContentEN = "What is it?",
          DialogueId = 80220422,
          GUID = "C8D2CAFC",
          NextDialogue = 80220423,
          Subtitle = "What is it?",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CAFC"
        },
        [80220423] = {
          ContentEN = "Do you think... the path I chose was right?",
          DialogueId = 80220423,
          GUID = "C8D2CB26",
          NextDialogue = 80220424,
          Subtitle = "Do you think... the path I chose was right?",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CB26"
        },
        [80220424] = {
          ContentEN = "You're asking me?",
          DialogueId = 80220424,
          GUID = "C8D2CB50",
          NextDialogue = 80220425,
          Subtitle = "You're asking me?",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CB50"
        },
        [80220425] = {
          ContentEN = "I am.",
          DialogueId = 80220425,
          GUID = "C8D2CB7A",
          NextDialogue = 80220426,
          Subtitle = "I am.",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CB7A"
        },
        [80220426] = {
          ContentEN = "Isn't that something you already figured out?",
          DialogueId = 80220426,
          GUID = "C8D2CBA4",
          NextDialogue = 80220427,
          Subtitle = "Isn't that something you already figured out?",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CBA4"
        },
        [80220427] = {
          ContentEN = "My Shifu once said, \"The road ahead may be desolate, but to press on is to walk where none have trodden.\"",
          DialogueId = 80220427,
          GUID = "C8D2CBCE",
          NextDialogue = 80220428,
          Subtitle = "My Shifu once said, \"The road ahead may be desolate, but to press on is to walk where none have trodden.\"",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CBCE"
        },
        [80220428] = {
          ContentEN = "He also said we should reflect three times a day — before Heaven, before others, and before our own hearts. If we can face all three with a clear conscience, then the path ahead is worth walking.",
          DialogueId = 80220428,
          GUID = "C8D2CBF8",
          NextDialogue = 80220429,
          Subtitle = "He also said we should reflect three times a day — before Heaven, before others, and before our own hearts. If we can face all three with a clear conscience, then the path ahead is worth walking.",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CBF8"
        },
        [80220429] = {
          ContentEN = "I thought that once everything had settled, I'd have to face it all again — the same slow, painful reckoning. That I'd see Buxia, Kezhou, my Shifu... even Taihao, keeping me awake in the dark.",
          DialogueId = 80220429,
          GUID = "C8D2CC22",
          NextDialogue = 80220430,
          Subtitle = "I thought that once everything had settled, I'd have to face it all again — the same slow, painful reckoning. That I'd see Buxia, Kezhou, my Shifu... even Taihao, keeping me awake in the dark.",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CC22"
        },
        [80220430] = {
          ContentEN = "But when I finally took that step forward... I found I wasn't as lost anymore.",
          DialogueId = 80220430,
          GUID = "C8D2CC4C",
          NextDialogue = 80220431,
          Subtitle = "But when I finally took that step forward... I found I wasn't as lost anymore.",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CC4C"
        },
        [80220431] = {
          ContentEN = "So you just haven't shaken the old habit of looking to others for answers yet?",
          DialogueId = 80220431,
          GUID = "C8D2CC76",
          NextDialogue = 80220432,
          Subtitle = "So you just haven't shaken the old habit of looking to others for answers yet?",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CC76"
        },
        [80220432] = {
          ContentEN = "It's been with me a long time... I'll try.",
          DialogueId = 80220432,
          GUID = "C8D2CCA0",
          NextDialogue = 80220433,
          Subtitle = "It's been with me a long time... I'll try.",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CCA0"
        },
        [80220433] = {
          ContentEN = "Take it easy. Even Lord Argent says they should embrace change. So what's wrong with a mortal doing the same?",
          DialogueId = 80220433,
          GUID = "C8D2CCCA",
          NextDialogue = 80220434,
          Subtitle = "Take it easy. Even Lord Argent says they should embrace change. So what's wrong with a mortal doing the same?",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CCCA"
        },
        [80220434] = {
          ContentEN = "...You're right. The way you talk really does remind me of my Shifu. You've cleared my head.",
          DialogueId = 80220434,
          GUID = "C8D2CCF4",
          NextDialogue = 80220435,
          Subtitle = "...You're right. The way you talk really does remind me of my Shifu. You've cleared my head.",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CCF4"
        },
        [80220435] = {
          ContentEN = "Come on. I told you — don't go making me out to be an old man.",
          DialogueId = 80220435,
          GUID = "C8D2CD1E",
          NextDialogue = 80220436,
          Subtitle = "Come on. I told you — don't go making me out to be an old man.",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CD1E"
        },
        [80220436] = {
          ContentEN = "Awooo!",
          DialogueId = 80220436,
          GUID = "C8D2CD48",
          NextDialogue = 80220437,
          Subtitle = "Awooo!",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CD48"
        }
      }
    end
  },
  {
