        },
        [80220440] = {
          ContentEN = "You didn't go back to the Outer Peaks... You're still alive.",
          DialogueId = 80220440,
          GUID = "C8D2CDF0",
          NextDialogue = 80220441,
          Subtitle = "You didn't go back to the Outer Peaks... You're still alive.",
