          SpeakNpcId = 100001,
          Subtitle = "Then why do you call yourself \"Demon Tabethe the Red Hand\"?",
          TalkActionId = {
            [1] = "82301:Talk03_End"
          }
        },
        [90050404] = {
          ContentEN = "That's because I want to make the word \"demon\" cool. Now, the mere mention of my title \"Demon Tabethe the Red Hand\" sends shivers down the spine of those thieves.",
          DialogueId = 90050404,
          GUID = "E16E85EB",
          NextDialogue = 90050405,
          SpeakNpcId = 82301,
          Subtitle = "That's because I want to make the word \"demon\" cool. Now, the mere mention of my title \"Demon Tabethe the Red Hand\" sends shivers down the spine of those thieves.",
