        [90060101] = {
          ContentEN = "If you learned about history, you'd know that the first warden of the Royal Military Prison had skin like molten lava. Even the most ruthless criminals feared her interrogations.",
          DialogueId = 90060101,
          GUID = "E174BD52",
          LookAt = {
            [1] = "83201:n(0)",
            [2] = "0:n(83201)"
          },
          NextDialogue = 90060102,
          SpeakNpcId = 83201,
          Subtitle = "If you learned about history, you'd know that the first warden of the Royal Military Prison had skin like molten lava. Even the most ruthless criminals feared her interrogations.",
          TalkActionId = {
            [1] = "83201:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_01_1"
        },
        [90060102] = {
          ContentEN = "As her descendant, I proudly bear her name, ready to incinerate all sins with my fire.",
          DialogueId = 90060102,
          GUID = "E174BD53",
          NextDialogue = 90060103,
          SpeakNpcId = 83201,
          Subtitle = "As her descendant, I proudly bear her name, ready to incinerate all sins with my fire.",
          TalkActionId = {
            [1] = "83201:Talk03_End"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_01_2"
        },
        [90060103] = {
          ContentEN = "Then... does your scorching skin make everyday life difficult?",
          DialogueId = 90060103,
          GUID = "E174BD54",
          NextDialogue = 90060104,
          SpeakNpcId = 100001,
          Subtitle = "Then... does your scorching skin make everyday life difficult?"
        },
        [90060104] = {
          ContentEN = "It does pose some challenges — I can only sleep on iron beds and can't linger in wooden structures for long. However, it allows me to pull criminals from burning buildings and administer justice. And the cold never bothers me.",
          DialogueId = 90060104,
          GUID = "E174BD55",
          NextDialogue = 90060105,
          SpeakNpcId = 83201,
          Subtitle = "It does pose some challenges — I can only sleep on iron beds and can't linger in wooden structures for long. However, it allows me to pull criminals from burning buildings and administer justice. And the cold never bothers me.",
          TalkActionId = {
            [1] = "83201:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_01_3"
        },
        [90060105] = {
          ContentEN = "My unusual appearance is more of a gift. If there's any downside... I've always wanted to try ice cream, but it melts in my hand before I can taste it...",
          DialogueId = 90060105,
          GUID = "E174BD56",
          NextOptions = {
            [1] = 90060002,
            [2] = 90060003
          },
          SpeakNpcId = 83201,
          Subtitle = "My unusual appearance is more of a gift. If there's any downside... I've always wanted to try ice cream, but it melts in my hand before I can taste it...",
          TalkActionId = {
            [1] = "83201:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_01_4",
          bForbidSkipOptions = true
        },
        [90060201] = {
          ContentEN = "Since the Empire's inception, my family has managed the prison that holds the most heinous criminals, correcting wrongs and neutralising threats.",
          DialogueId = 90060201,
          GUID = "E174CDBA",
          LookAt = {
            [1] = "83201:n(0)",
            [2] = "0:n(83201)"
          },
          NextDialogue = 90060202,
          SpeakNpcId = 83201,
          Subtitle = "Since the Empire's inception, my family has managed the prison that holds the most heinous criminals, correcting wrongs and neutralising threats.",
          TalkActionId = {
            [1] = "83201:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_02_1"
        },
        [90060202] = {
          ContentEN = "My fiery red skin, a legacy from the first warden, predestined me to continue enforcing the iron-clad code she established. So it wasn't me who chose to become a warden; it was the mantle of warden that chose me.",
          DialogueId = 90060202,
          GUID = "E174CDBB",
          NextDialogue = 90060203,
          SpeakNpcId = 83201,
          Subtitle = "My fiery red skin, a legacy from the first warden, predestined me to continue enforcing the iron-clad code she established. So it wasn't me who chose to become a warden; it was the mantle of warden that chose me.",
          TalkActionId = {
            [1] = "83201:Angry01_End"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_02_2"
        },
        [90060203] = {
          ContentEN = "Does that mean you've already achieved your aspirations?",
          DialogueId = 90060203,
          GUID = "E174CDBC",
          NextDialogue = 90060204,
          SpeakNpcId = 100001,
          Subtitle = "Does that mean you've already achieved your aspirations?"
        },
        [90060204] = {
          ContentEN = "Becoming a warden is merely the beginning. It compels me to remain vigilant, eradicating any injustice within the Empire until my final breath.",
          DialogueId = 90060204,
          GUID = "E174CDBD",
          NextOptions = {
            [1] = 90060002,
            [2] = 90060003
          },
          SpeakNpcId = 83201,
          Subtitle = "Becoming a warden is merely the beginning. It compels me to remain vigilant, eradicating any injustice within the Empire until my final breath.",
          TalkActionId = {
            [1] = "83201:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_02_3",
          bForbidSkipOptions = true
        },
        [90060301] = {
          ContentEN = "Certainly. The Imperial Prison is teeming with devious criminals. My duties include conducting interrogations, reviewing case files, and thwarting escape attempts.",
          DialogueId = 90060301,
          GUID = "E174DE22",
          LookAt = {
            [1] = "83201:n(0)",
            [2] = "0:n(83201)"
          },
          NextDialogue = 90060302,
          SpeakNpcId = 83201,
          Subtitle = "Certainly. The Imperial Prison is teeming with devious criminals. My duties include conducting interrogations, reviewing case files, and thwarting escape attempts.",
          TalkActionId = {
            [1] = "83201:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_03_1"
        },
        [90060302] = {
          ContentEN = "Every minute of rest delays justice a bit, and when justice is delayed, chaos and the law of the jungle take over.",
          DialogueId = 90060302,
          GUID = "E174DE23",
          NextDialogue = 90060303,
          SpeakNpcId = 83201,
          Subtitle = "Every minute of rest delays justice a bit, and when justice is delayed, chaos and the law of the jungle take over.",
          TalkActionId = {
            [1] = "83201:Confident_End"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_03_2"
        },
        [90060303] = {
          ContentEN = "Would your job be easier if there were fewer prisoners?",
          DialogueId = 90060303,
          GUID = "E174DE24",
          NextDialogue = 90060304,
          SpeakNpcId = 100001,
          Subtitle = "Would your job be easier if there were fewer prisoners?"
        },
        [90060304] = {
          ContentEN = "Some scholars have envisioned a crime-free world. Should such a day come, my purpose would vanish, for evil necessitates a warden's existence. Until then, I am committed to upholding order.",
          DialogueId = 90060304,
          GUID = "E174DE25",
          NextOptions = {
            [1] = 90060002,
            [2] = 90060003
          },
          SpeakNpcId = 83201,
          Subtitle = "Some scholars have envisioned a crime-free world. Should such a day come, my purpose would vanish, for evil necessitates a warden's existence. Until then, I am committed to upholding order.",
          TalkActionId = {
            [1] = "83201:Agree"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_03_3",
          bForbidSkipOptions = true
        },
        [90060401] = {
          ContentEN = "Justice? It is the restraint of desire through power, the suppression of evil through strength, and the punishment of the wicked by the mighty.",
          DialogueId = 90060401,
          GUID = "E174EE8A",
          LookAt = {
            [1] = "83201:n(0)",
            [2] = "0:n(83201)"
          },
          NextDialogue = 90060402,
          SpeakNpcId = 83201,
          Subtitle = "Justice? It is the restraint of desire through power, the suppression of evil through strength, and the punishment of the wicked by the mighty.",
          TalkActionId = {
            [1] = "83201:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_04_1"
        },
        [90060402] = {
          ContentEN = "Isn't that a bit \"painting with a broad brush\"?",
          DialogueId = 90060402,
          GUID = "E174EE8B",
          NextDialogue = 90060403,
          SpeakNpcId = 100001,
          Subtitle = "Isn't that a bit \"painting with a broad brush\"?",
          TalkActionId = {
            [1] = "83201:Explain01_End"
          }
        },
        [90060403] = {
          ContentEN = "Hmph, broad? I wouldn't expect a naive child to understand. We don't live in a utopia where people simply hold hands and love each other. Only through absolute power and order can true justice be secured!",
          DialogueId = 90060403,
          GUID = "E174EE8C",
          NextOptions = {
            [1] = 90060002,
            [2] = 90060003
          },
          SpeakNpcId = 83201,
          Subtitle = "Hmph, broad? I wouldn't expect a naive child to understand. We don't live in a utopia where people simply hold hands and love each other. Only through absolute power and order can true justice be secured!",
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_04_2",
          bForbidSkipOptions = true
        },
        [90060501] = {
          ContentEN = "With criminals still roaming the streets of the Empire, spare time is a luxury for a warden. The only respite I get is when I sneak in a few strong drinks amidst a busy schedule.",
          DialogueId = 90060501,
          GUID = "E174FEF2",
          LookAt = {
            [1] = "83201:n(0)",
            [2] = "0:n(83201)"
          },
          NextDialogue = 90060502,
          SpeakNpcId = 83201,
          Subtitle = "With criminals still roaming the streets of the Empire, spare time is a luxury for a warden. The only respite I get is when I sneak in a few strong drinks amidst a busy schedule.",
          TalkActionId = {
            [1] = "83201:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_05_1"
        },
        [90060502] = {
          ContentEN = "What!? You drink!?",
          DialogueId = 90060502,
          GUID = "E174FF1C",
          LookAt = {
            [1] = "83201:n(0)",
            [2] = "0:n(83201)"
          },
          NextDialogue = 90060503,
          SpeakNpcId = 100001,
          Subtitle = "What!? You drink!?",
          TalkActionId = {
            [1] = "83201:Talk01_End"
          }
        },
        [90060503] = {
          ContentEN = "Why so surprised? It's merely a diversion. During interrogations, I always hear about various kinds of alcohol, which made me curious about this so-called wicked potion that seems to be associated with crime. So I drink once in a while.",
          DialogueId = 90060503,
          GUID = "E174FF1D",
          NextDialogue = 90060504,
          SpeakNpcId = 83201,
          Subtitle = "Why so surprised? It's merely a diversion. During interrogations, I always hear about various kinds of alcohol, which made me curious about this so-called wicked potion that seems to be associated with crime. So I drink once in a while.",
          TalkActionId = {
            [1] = "83201:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_05_2"
        },
        [90060504] = {
          ContentEN = "And the more I drink, the more I'm convinced that it's not the drink that is wicked.",
          DialogueId = 90060504,
          GUID = "E174FF1E",
          NextOptions = {
            [1] = 90060002,
            [2] = 90060003
          },
          SpeakNpcId = 83201,
          Subtitle = "And the more I drink, the more I'm convinced that it's not the drink that is wicked.",
          TalkActionId = {
            [1] = "83201:Talk03_End"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_05_3",
          bForbidSkipOptions = true
        },
        [90060601] = {
          ContentEN = "I'm the warden and you're the Legion's chief. Together, we're the merciless keepers of the dark order that is the Empire. Their hatred of us means nothing, as long as we serve Hyperborea!",
          DialogueId = 90060601,
          GUID = "E1750F5A",
          SpeakNpcId = 83201,
          Subtitle = "I'm the warden and you're the Legion's chief. Together, we're the merciless keepers of the dark order that is the Empire. Their hatred of us means nothing, as long as we serve Hyperborea!",
          VoiceName = "voice/$Locale$/char/Haier/vo_companio_01"
        },
