          DialogueId = 90090105,
          GUID = "E187F7DA",
          NextDialogue = 90090106,
          SpeakNpcId = 100001,
          Subtitle = "Should I report you for treason based on that statement?",
          TalkActionId = {
            [1] = "84301:Confident_Start"
          }
        },
        [90090106] = {
          ContentEN = "Feel free to try. Treason is a grave offence, and any accusation would work its way up through the ranks and end up right on my desk.",
