            [2] = 901200012,
            [3] = 901200013,
            [4] = 901200014,
            [5] = 901200015
          },
          RandomOptionNum = 3,
          SpeakNpcId = 85101,
          Subtitle = "The sun is shining bright, and the little birdies are chirping with joy after a hearty meal. Are you hungry too? Wanna grab something to eat as well?",
          TalkActionId = {
            [1] = "85101:Agree"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_welcome",
          bForbidSkipOptions = true
        },
        [90120002] = {
          ContentEN = "Let's talk about something else",
          DialogueId = 90120002,
          GUID = "90120002.0",
          NextDialogue = 90120001,
          Subtitle = "Let's talk about something else"
        },
        [90120003] = {
          ContentEN = "Goodbye",
          DialogueId = 90120003,
          GUID = "90120003.0",
          Subtitle = "Goodbye"
        },
        [90120101] = {
          ContentEN = "Huh? You don't know? A commissary's job is to make sure everyone's well-fed, dealing with all sorts of food every day.",
          DialogueId = 90120101,
          GUID = "E19B3112",
          LookAt = {
            [1] = "85101:n(0)",
            [2] = "0:n(85101)"
          },
          NextDialogue = 90120103,
          SpeakNpcId = 85101,
          Subtitle = "Huh? You don't know? A commissary's job is to make sure everyone's well-fed, dealing with all sorts of food every day.",
          TalkActionId = {
            [1] = "85101:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_01_1"
        },
        [90120103] = {
          ContentEN = "For example, I go out to gather all kinds of ingredients from the wild, have Filbert haul them back, and then get Mr Beard at the bakery to turn them into yummy food for everyone.",
          DialogueId = 90120103,
          GUID = "E19B3166",
          NextDialogue = 90120104,
          SpeakNpcId = 85101,
          Subtitle = "For example, I go out to gather all kinds of ingredients from the wild, have Filbert haul them back, and then get Mr Beard at the bakery to turn them into yummy food for everyone.",
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_01_2"
        },
        [90120104] = {
          ContentEN = "And just so you know, haggling with Mr Beard is part of my job too! Hehe.",
          DialogueId = 90120104,
          GUID = "E19B3190",
          NextDialogue = 90120105,
          SpeakNpcId = 85101,
          Subtitle = "And just so you know, haggling with Mr Beard is part of my job too! Hehe.",
          TalkActionId = {
            [1] = "85101:Confident_End"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_01_3"
        },
        [90120105] = {
          ContentEN = "Wow! That sounds impressive. Is it the same for all commissaries?",
          DialogueId = 90120105,
          GUID = "E19B31BA",
          NextDialogue = 90120106,
          SpeakNpcId = 100001,
          Subtitle = "Wow! That sounds impressive. Is it the same for all commissaries?"
        },
        [90120106] = {
          ContentEN = "Oh, not at all! The others seem to be brainy types; they're all about the paperwork — filling out application forms, then waiting for trains loaded with food to roll in.",
          DialogueId = 90120106,
          GUID = "E19B31E4",
          NextDialogue = 90120107,
          SpeakNpcId = 85101,
          Subtitle = "Oh, not at all! The others seem to be brainy types; they're all about the paperwork — filling out application forms, then waiting for trains loaded with food to roll in.",
          TalkActionId = {
            [1] = "85101:Agree"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_01_4"
        },
        [90120107] = {
          ContentEN = "But for a small town like ours, just Filbert and I can feed everyone! Otherwise, I might have to start filling out those forms too — ugh, it's all gibberish to me.",
          DialogueId = 90120107,
          GUID = "E19B320E",
          NextOptions = {
            [1] = 90120002,
            [2] = 90120003
          },
          SpeakNpcId = 85101,
          Subtitle = "But for a small town like ours, just Filbert and I can feed everyone! Otherwise, I might have to start filling out those forms too — ugh, it's all gibberish to me.",
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_01_5",
          bForbidSkipOptions = true
        },
        [90120201] = {
          ContentEN = "Hmm... maybe it does? I've never really thought about it, but Filbert only knocks down those no-good, shouty, fighty troublemakers! They totally deserve it!",
          DialogueId = 90120201,
          GUID = "E19B417A",
          LookAt = {
            [1] = "85101:n(0)",
            [2] = "0:n(85101)"
          },
          NextDialogue = 90120203,
          SpeakNpcId = 85101,
          Subtitle = "Hmm... maybe it does? I've never really thought about it, but Filbert only knocks down those no-good, shouty, fighty troublemakers! They totally deserve it!",
          TalkActionId = {
            [1] = "85101:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_02_1"
        },
        [90120203] = {
          ContentEN = "Those guys always end up hungry after their brawls. They'd do more good ploughing fields than swinging weapons — that way, less people would go to bed hungry.",
          DialogueId = 90120203,
          GUID = "E19B41CE",
          NextDialogue = 90120204,
          SpeakNpcId = 85101,
          Subtitle = "Those guys always end up hungry after their brawls. They'd do more good ploughing fields than swinging weapons — that way, less people would go to bed hungry.",
          TalkActionId = {
            [1] = "85101:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_02_2"
        },
        [90120204] = {
          ContentEN = "You must really hate wars, then.",
          DialogueId = 90120204,
          GUID = "E19B41F8",
          NextDialogue = 90120205,
          SpeakNpcId = 100001,
          Subtitle = "You must really hate wars, then."
        },
        [90120205] = {
          ContentEN = "Absolutely! Fighting just leads to hunger — that's really awful! I've heard that in times of war, everyone ends up starving, which is just the worst! I hope I never have to see that.",
          DialogueId = 90120205,
          GUID = "E19B4222",
          NextDialogue = 90120206,
          SpeakNpcId = 85101,
          Subtitle = "Absolutely! Fighting just leads to hunger — that's really awful! I've heard that in times of war, everyone ends up starving, which is just the worst! I hope I never have to see that.",
          TalkActionId = {
            [1] = "85101:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_02_3"
        },
        [90120206] = {
          ContentEN = "If war does break out, you could mount Filbert and ram those troublemakers.",
          DialogueId = 90120206,
          GUID = "E19B424C",
          NextDialogue = 90120207,
          SpeakNpcId = 100001,
          Subtitle = "If war does break out, you could mount Filbert and ram those troublemakers.",
          TalkActionId = {
            [1] = "85101:Confident_End"
          }
        },
        [90120207] = {
          ContentEN = "Right! Anyone who makes people go hungry will sooner or later get knocked over by Filbert!",
          DialogueId = 90120207,
          GUID = "E19B4276",
          NextOptions = {
            [1] = 90120002,
            [2] = 90120003
          },
          SpeakNpcId = 85101,
          Subtitle = "Right! Anyone who makes people go hungry will sooner or later get knocked over by Filbert!",
          TalkActionId = {
            [1] = "85101:Agree"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_02_4",
          bForbidSkipOptions = true
        },
        [90120301] = {
          ContentEN = "Yeah, she is! And you know what, even across several creeks, Filbert can sniff out ripe berries and then off we go charging! Pretty awesome, isn't she?",
          DialogueId = 90120301,
          GUID = "E19B51E2",
          LookAt = {
            [1] = "85101:n(0)",
            [2] = "0:n(85101)"
          },
          NextDialogue = 90120303,
          SpeakNpcId = 85101,
          Subtitle = "Yeah, she is! And you know what, even across several creeks, Filbert can sniff out ripe berries and then off we go charging! Pretty awesome, isn't she?",
          TalkActionId = {
            [1] = "85101:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_03_1"
        },
        [90120303] = {
          ContentEN = "Awesome. No risk of food shortage then.",
          DialogueId = 90120303,
          GUID = "E19B5236",
          NextDialogue = 90120304,
          SpeakNpcId = 100001,
          Subtitle = "Awesome. No risk of food shortage then.",
          TalkActionId = {
            [1] = "85101:Talk02_End"
          }
        },
        [90120304] = {
          ContentEN = "No worries at all! Filbert always brings more food. So never ever make fun of her — it would hurt her feelings, and mine too.",
          DialogueId = 90120304,
          GUID = "E19B5260",
          NextOptions = {
            [1] = 90120002,
            [2] = 90120003
          },
          SpeakNpcId = 85101,
          Subtitle = "No worries at all! Filbert always brings more food. So never ever make fun of her — it would hurt her feelings, and mine too.",
          TalkActionId = {
            [1] = "85101:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_03_2",
          bForbidSkipOptions = true
        },
        [90120401] = {
          ContentEN = "Thank you! Actually, these are shorts, not a dress. They did start as a pretty, long, white dress; then the lady at the tailor's shop turned them into shorts for me.",
          DialogueId = 90120401,
          GUID = "E19B624A",
          LookAt = {
            [1] = "85101:n(0)",
            [2] = "0:n(85101)"
          },
          NextDialogue = 90120403,
          SpeakNpcId = 85101,
          Subtitle = "Thank you! Actually, these are shorts, not a dress. They did start as a pretty, long, white dress; then the lady at the tailor's shop turned them into shorts for me.",
          TalkActionId = {
            [1] = "85101:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_04_1"
        },
        [90120403] = {
          ContentEN = "Why is that?",
          DialogueId = 90120403,
          GUID = "E19B629E",
          NextDialogue = 90120404,
          SpeakNpcId = 100001,
          Subtitle = "Why is that?",
          TalkActionId = {
            [1] = "85101:Explain01_End"
          }
        },
        [90120404] = {
          ContentEN = "Because dresses aren't the best for all the running around I do. One time, I tripped over the hem and all the bread in my arms went flying.",
          DialogueId = 90120404,
          GUID = "E19B62C8",
          NextDialogue = 90120405,
          SpeakNpcId = 85101,
          Subtitle = "Because dresses aren't the best for all the running around I do. One time, I tripped over the hem and all the bread in my arms went flying.",
          TalkActionId = {
            [1] = "85101:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_04_2"
        },
        [90120405] = {
          ContentEN = "But if the day comes, when no one's starving anymore, I'll have them changed back into a dress!",
          DialogueId = 90120405,
          GUID = "E19B62F2",
          NextOptions = {
            [1] = 90120002,
            [2] = 90120003
          },
          SpeakNpcId = 85101,
          Subtitle = "But if the day comes, when no one's starving anymore, I'll have them changed back into a dress!",
          TalkActionId = {
            [1] = "85101:Talk01_End"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_04_3",
          bForbidSkipOptions = true
        },
        [90120501] = {
          ContentEN = "Oh, I was meditating, not zoning out. I'm a member of the Elysian Church after all, so I do try to give some deep thought occasionally.",
          DialogueId = 90120501,
          GUID = "E19B72B2",
          LookAt = {
            [1] = "85101:n(0)",
            [2] = "0:n(85101)"
          },
          NextDialogue = 90120503,
          SpeakNpcId = 85101,
          Subtitle = "Oh, I was meditating, not zoning out. I'm a member of the Elysian Church after all, so I do try to give some deep thought occasionally.",
          TalkActionId = {
            [1] = "85101:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_05_1"
        },
        [90120503] = {
          ContentEN = "What were you thinking, then? Why isn't there a god of full bellies, perhaps?",
          DialogueId = 90120503,
          GUID = "E19B7306",
          NextDialogue = 90120504,
          SpeakNpcId = 100001,
          Subtitle = "What were you thinking, then? Why isn't there a god of full bellies, perhaps?"
        },
        [90120504] = {
          ContentEN = "I used to wonder about that, but the clergy said it was... blastphomy or something. So I stopped thinking about that.",
          DialogueId = 90120504,
          GUID = "E19B7330",
          NextDialogue = 90120505,
          SpeakNpcId = 85101,
          Subtitle = "I used to wonder about that, but the clergy said it was... blastphomy or something. So I stopped thinking about that.",
          TalkActionId = {
            [1] = "85101:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_05_2"
        },
        [90120505] = {
          ContentEN = "I never quite get what they say, like how gluttony is a terrible sin... but it seems like the higher someone's status, the more they eat.",
          DialogueId = 90120505,
          GUID = "E19B735A",
          NextOptions = {
            [1] = 90120002,
            [2] = 90120003
          },
          SpeakNpcId = 85101,
          Subtitle = "I never quite get what they say, like how gluttony is a terrible sin... but it seems like the higher someone's status, the more they eat.",
          TalkActionId = {
