          NextDialogue = 90130203,
          SpeakNpcId = 83101,
          Subtitle = "Tips? The only tip I have is there's no problem a good punch can't fix. If that doesn't work, throw another.",
          TalkActionId = {
            [1] = "83101:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Linen/vo_topic_02_1"
        },
        [90130203] = {
          ContentEN = "What if two punches don't sort it out either?",
          DialogueId = 90130203,
          GUID = "E1A1AA6E",
          NextDialogue = 90130204,
          SpeakNpcId = 100001,
          Subtitle = "What if two punches don't sort it out either?"
        },
        [90130204] = {
          ContentEN = "Then a bullet usually does the trick.",
          DialogueId = 90130204,
          GUID = "E1A1AA98",
          NextDialogue = 90130205,
          SpeakNpcId = 83101,
          Subtitle = "Then a bullet usually does the trick.",
          TalkActionId = {
            [1] = "83101:Confident_End"
          },
          VoiceName = "voice/$Locale$/char/Linen/vo_topic_02_2"
        },
        [90130205] = {
          ContentEN = "But I heard some people can take a bullet and still stand.",
          DialogueId = 90130205,
          GUID = "E1A1AAC2",
          NextDialogue = 90130206,
          SpeakNpcId = 100001,
          Subtitle = "But I heard some people can take a bullet and still stand."
        },
        [90130206] = {
          ContentEN = "It's just a figure of speech. My point is: be as tough and strong as you can be, and that's all you need. Keep nitpicking, and your face will be getting those punches next.",
          DialogueId = 90130206,
          GUID = "E1A1AAEC",
          NextOptions = {
            [1] = 90130002,
            [2] = 90130003
          },
          SpeakNpcId = 83101,
          Subtitle = "It's just a figure of speech. My point is: be as tough and strong as you can be, and that's all you need. Keep nitpicking, and your face will be getting those punches next.",
          VoiceName = "voice/$Locale$/char/Linen/vo_topic_02_3",
          bForbidSkipOptions = true
        },
        [90130301] = {
          ContentEN = "Saw a really nice gun the other day... Forget it, can't skimp on food just to buy it. The old one feels better in my hands anyway.",
