          GUID = "E1AE7BD8",
          NextDialogue = 90150205,
          SpeakNpcId = 100001,
          Subtitle = "Wow... it must be heavenly to nestle inside."
        },
        [90150205] = {
          ContentEN = "Well... if you nibble one of those candies that shrinks you down tiny, you could get in for a visit. But everything's white in there, so be careful not to wander off and lose your way.",
