          SpeakNpcId = 100001,
          Subtitle = "And how's that done?"
        },
        [90170104] = {
          ContentEN = "For instance, turning an aristocrat's cast-off velvet curtains into warm winter coats for the elderly, or bringing discarded dolls to children whose only playthings are pebbles — they'll be overjoyed for a long time.",
          DialogueId = 90170104,
          GUID = "E1BB3CB0",
          NextDialogue = 90170105,
          SpeakNpcId = 83301,
          Subtitle = "For instance, turning an aristocrat's cast-off velvet curtains into warm winter coats for the elderly, or bringing discarded dolls to children whose only playthings are pebbles — they'll be overjoyed for a long time.",
          TalkActionId = {
            [1] = "83301:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_01_2"
        },
        [90170105] = {
          ContentEN = "There was one time, I dragged back a broken bookshelf someone had thrown out. Though I was half-dead from the effort, it quickly turned into a non-stop playground for a litter of kittens — totally worth it!",
          DialogueId = 90170105,
          GUID = "E1BB3CDA",
          NextDialogue = 90170106,
          SpeakNpcId = 83301,
          Subtitle = "There was one time, I dragged back a broken bookshelf someone had thrown out. Though I was half-dead from the effort, it quickly turned into a non-stop playground for a litter of kittens — totally worth it!",
          TalkActionId = {
            [1] = "83301:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_01_3"
        },
        [90170106] = {
          ContentEN = "That's scavenging for you! It's mostly small fry stuff, but never a dull moment. So, what do you say, wanna join us?",
          DialogueId = 90170106,
          GUID = "E1BB3D04",
          NextOptions = {
            [1] = 90170002,
