          VoiceName = "voice/$Locale$/char/Maer/vo_topic_02_1"
        },
        [90170203] = {
          ContentEN = "This map charts every rubbish bin in Icelake, and I've marked the few where the best stuff tends to gather — I've upgraded those bins to larger sizes and timed my visits to perfection!",
          DialogueId = 90170203,
          GUID = "E1BB4CEE",
          NextDialogue = 90170204,
          SpeakNpcId = 83301,
          Subtitle = "This map charts every rubbish bin in Icelake, and I've marked the few where the best stuff tends to gather — I've upgraded those bins to larger sizes and timed my visits to perfection!",
          TalkActionId = {
