            [2] = 90170003
          },
          SpeakNpcId = 83301,
          Subtitle = "Ha, I knew you'd understand!",
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_02_4",
          bForbidSkipOptions = true
        },
        [90170301] = {
          ContentEN = "Oh, you've got it backwards! I love Icelake through and through. It's just that I often reminisce about the days I spent wandering the snowfields with my dad; that's how I grew up.",
          DialogueId = 90170301,
          GUID = "E1BB5D02",
          LookAt = {
            [1] = "83301:n(0)",
            [2] = "0:n(83301)"
          },
          NextDialogue = 90170303,
          SpeakNpcId = 83301,
          Subtitle = "Oh, you've got it backwards! I love Icelake through and through. It's just that I often reminisce about the days I spent wandering the snowfields with my dad; that's how I grew up.",
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_03_1"
        },
        [90170303] = {
          ContentEN = "How do you feel about those days?",
          DialogueId = 90170303,
          GUID = "E1BB5D56",
          NextDialogue = 90170304,
          SpeakNpcId = 100001,
          Subtitle = "How do you feel about those days?",
          TalkActionId = {
            [1] = "83301:Agree"
          }
        },
        [90170304] = {
          ContentEN = "From here, the snowfields look like something out of a fairy tale. But once you step into it, you'd feel so very small. Even after trudging through knee-high snow for hours, that feeling would never leave.",
          DialogueId = 90170304,
          GUID = "E1BB5D80",
          NextDialogue = 90170305,
          SpeakNpcId = 83301,
          Subtitle = "From here, the snowfields look like something out of a fairy tale. But once you step into it, you'd feel so very small. Even after trudging through knee-high snow for hours, that feeling would never leave.",
          TalkActionId = {
            [1] = "83301:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_03_2"
        },
        [90170305] = {
          ContentEN = "I don't hate those days. But the bustling, lively Icelake is my absolute favourite!",
