          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_01_2"
        },
        [90200104] = {
          ContentEN = "The wall between our cells was so thin, every sound passed through. There he was, barely a metre away — rambling about his family, spinning dreams of the future, or singing some hopelessly off-key tune.",
          DialogueId = 90200104,
          GUID = "E1CE7690",
          NextDialogue = 90200105,
          SpeakNpcId = 81103,
          Subtitle = "The wall between our cells was so thin, every sound passed through. There he was, barely a metre away — rambling about his family, spinning dreams of the future, or singing some hopelessly off-key tune.",
          TalkActionId = {
            [1] = "81103:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_01_3"
        },
        [90200105] = {
          ContentEN = "For a moment, I'd forget I was a caged beast. Instead, I'd feel like an ordinary child in school, waking from a nightmare during an afternoon nap to the racket of a noisy classmate beside me.",
          DialogueId = 90200105,
          GUID = "E1CE76BA",
