          TalkActionId = {
            [1] = "81103:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_02_1"
        },
        [90200202] = {
          ContentEN = "But to me, you're real.",
          DialogueId = 90200202,
          GUID = "E1CE86A4",
          NextDialogue = 90200203,
          SpeakNpcId = 100001,
          Subtitle = "But to me, you're real."
