            [1] = "81103:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_02_3"
        },
        [90200205] = {
          ContentEN = "Thank you, for granting me a stage to rest my weary soul.",
          DialogueId = 90200205,
          GUID = "E1CE8722",
          NextOptions = {
            [1] = 90200002,
            [2] = 90200003
          },
          SpeakNpcId = 81103,
          Subtitle = "Thank you, for granting me a stage to rest my weary soul.",
          TalkActionId = {
            [1] = "81103:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_02_4",
          bForbidSkipOptions = true
        },
        [90200301] = {
          ContentEN = "You're so kind. Thank you. Yet, all my vows have been fulfilled. There's little left that stirs my heart.",
          DialogueId = 90200301,
          GUID = "E1CE96E2",
          LookAt = {
            [1] = "81103:n(0)",
            [2] = "0:n(81103)"
          },
          NextDialogue = 90200302,
          SpeakNpcId = 81103,
          Subtitle = "You're so kind. Thank you. Yet, all my vows have been fulfilled. There's little left that stirs my heart.",
          TalkActionId = {
            [1] = "81103:Agree"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_03_1"
        },
        [90200302] = {
          ContentEN = "...",
          DialogueId = 90200302,
          GUID = "E1CE970C",
          NextDialogue = 90200303,
          SpeakNpcId = 81103,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_03_2"
        },
        [90200303] = {
          ContentEN = "Should you ever find yourself at the Galea Theatre, please convey to Ms Violetta that I've settled down in Aethyrie. Assure her not to worry, as I am doing very well now.",
          DialogueId = 90200303,
          GUID = "E1CE9736",
          NextDialogue = 90200304,
          SpeakNpcId = 81103,
          Subtitle = "Should you ever find yourself at the Galea Theatre, please convey to Ms Violetta that I've settled down in Aethyrie. Assure her not to worry, as I am doing very well now.",
          TalkActionId = {
            [1] = "81103:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_03_3"
        },
        [90200304] = {
          ContentEN = "\"A land of music and poetry, where every pebble taps out a rhythm, and every brook sings a melody.\"",
          DialogueId = 90200304,
          GUID = "E1CE9760",
          NextDialogue = 90200305,
          SpeakNpcId = 81103,
          Subtitle = "\"A land of music and poetry, where every pebble taps out a rhythm, and every brook sings a melody.\"",
          TalkActionId = {
            [1] = "81103:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_03_4"
        },
        [90200305] = {
          ContentEN = "Hopefully, that'll keep her from enquiring after me. Once her favoured pupil... I'd rather not tarnish her memories.",
          DialogueId = 90200305,
          GUID = "E1CE978A",
          NextDialogue = 90200306,
          SpeakNpcId = 81103,
          Subtitle = "Hopefully, that'll keep her from enquiring after me. Once her favoured pupil... I'd rather not tarnish her memories.",
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_03_5"
        },
        [90200306] = {
          ContentEN = "A little white lie, I see.",
          DialogueId = 90200306,
          GUID = "E1CE97B4",
          NextDialogue = 90200307,
          SpeakNpcId = 100001,
          Subtitle = "A little white lie, I see."
        },
        [90200307] = {
          ContentEN = "Indeed. Ignorance is always bliss.",
          DialogueId = 90200307,
          GUID = "E1CE97DE",
          NextOptions = {
            [1] = 90200002,
            [2] = 90200003
          },
          SpeakNpcId = 81103,
          Subtitle = "Indeed. Ignorance is always bliss.",
          TalkActionId = {
            [1] = "81103:Agree"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_03_6",
          bForbidSkipOptions = true
        },
        [90200401] = {
          ContentEN = "Why seek to learn acting? You have no need to become someone else.",
          DialogueId = 90200401,
          GUID = "E1CEA74A",
          LookAt = {
            [1] = "81103:n(0)",
            [2] = "0:n(81103)"
          },
          NextDialogue = 90200402,
          SpeakNpcId = 81103,
          Subtitle = "Why seek to learn acting? You have no need to become someone else.",
          TalkActionId = {
            [1] = "81103:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_04_1"
        },
        [90200402] = {
          ContentEN = "Become someone else?",
          DialogueId = 90200402,
          GUID = "E1CEA774",
          NextDialogue = 90200403,
          SpeakNpcId = 100001,
          Subtitle = "Become someone else?"
        },
        [90200403] = {
          ContentEN = "When you're on stage, every part of you — from your very bones to the breaths you take — is surrendered to the character. In that moment, you can shed all your sorrows and pain, stepping into a world unblemished by reality.",
          DialogueId = 90200403,
          GUID = "E1CEA79E",
          NextDialogue = 90200404,
          SpeakNpcId = 81103,
          Subtitle = "When you're on stage, every part of you — from your very bones to the breaths you take — is surrendered to the character. In that moment, you can shed all your sorrows and pain, stepping into a world unblemished by reality.",
          TalkActionId = {
            [1] = "81103:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_04_2"
        },
        [90200404] = {
          ContentEN = "But you... you were born the {性别：hero|heroine} of your own story, already carrying the admiration and trust of those around you. You shine effortlessly, needing no spotlight to dazzle.",
          DialogueId = 90200404,
          GUID = "E1CEA7C8",
          NextOptions = {
            [1] = 90200002,
            [2] = 90200003
          },
          SpeakNpcId = 81103,
          Subtitle = "But you... you were born the {性别：hero|heroine} of your own story, already carrying the admiration and trust of those around you. You shine effortlessly, needing no spotlight to dazzle.",
          TalkActionId = {
            [1] = "81103:Angry01_End"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_04_3",
          bForbidSkipOptions = true
        },
        [90200501] = {
          ContentEN = "It stands, enduring time far beyond my years. On one side of its towering walls lies the imposing inner city — majestic as storm clouds, yet colder.",
          DialogueId = 90200501,
          GUID = "E1CEB7B2",
          LookAt = {
            [1] = "81103:n(0)",
            [2] = "0:n(81103)"
          },
          NextDialogue = 90200502,
          SpeakNpcId = 81103,
          Subtitle = "It stands, enduring time far beyond my years. On one side of its towering walls lies the imposing inner city — majestic as storm clouds, yet colder.",
          TalkActionId = {
            [1] = "81103:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_05_1"
        },
        [90200502] = {
          ContentEN = "Elegantly clad figures alight from silk-lined carriages, discussing art, poetry, and the perpetual gloom of the skies. They gossip about balls and betrothals, lamenting how the mire of melting snow from the outer city soils their fine leather boots.",
          DialogueId = 90200502,
          GUID = "E1CEB7DC",
          NextDialogue = 90200503,
          SpeakNpcId = 81103,
          Subtitle = "Elegantly clad figures alight from silk-lined carriages, discussing art, poetry, and the perpetual gloom of the skies. They gossip about balls and betrothals, lamenting how the mire of melting snow from the outer city soils their fine leather boots.",
          TalkActionId = {
            [1] = "81103:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_05_2"
        },
        [90200503] = {
          ContentEN = "On the other side of the walls, the rowdy fog district buzzes with chaos. Vendors hawk loudly, mothers clutch their children, begging for a scrap of rye bread. Mischievous hands sketch defiant graffiti, always a step ahead of the patrols.",
          DialogueId = 90200503,
          GUID = "E1CEB806",
          NextDialogue = 90200504,
          SpeakNpcId = 81103,
          Subtitle = "On the other side of the walls, the rowdy fog district buzzes with chaos. Vendors hawk loudly, mothers clutch their children, begging for a scrap of rye bread. Mischievous hands sketch defiant graffiti, always a step ahead of the patrols.",
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_05_3"
        },
        [90200504] = {
          ContentEN = "And so stands our Galea Theatre, caught between these two worlds, hearing all yet understanding none.",
          DialogueId = 90200504,
          GUID = "E1CEB830",
          NextDialogue = 90200505,
          SpeakNpcId = 81103,
          Subtitle = "And so stands our Galea Theatre, caught between these two worlds, hearing all yet understanding none.",
          TalkActionId = {
            [1] = "81103:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_05_4"
        },
        [90200505] = {
          ContentEN = "Any personal memories there?",
          DialogueId = 90200505,
          GUID = "E1CEB85A",
          NextDialogue = 90200506,
          SpeakNpcId = 100001,
          Subtitle = "Any personal memories there?",
          TalkActionId = {
            [1] = "81103:Confident_End"
          }
        },
        [90200506] = {
          ContentEN = "Oddly, it's not the scripts or the lavish costumes that first come to mind, nor the cluttered prop room I swept daily.",
          DialogueId = 90200506,
          GUID = "E1CEB884",
          NextDialogue = 90200507,
          SpeakNpcId = 81103,
          Subtitle = "Oddly, it's not the scripts or the lavish costumes that first come to mind, nor the cluttered prop room I swept daily.",
          TalkActionId = {
            [1] = "81103:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_05_5"
        },
        [90200507] = {
          ContentEN = "It's the velvet carpet that blanketed the stage after the curtain fell. As a child, after the earliest performance I can remember, my mother and I lingered on the stage after everyone left, reciting lines and dancing through the night.",
          DialogueId = 90200507,
          GUID = "E1CEB8AE",
          NextDialogue = 90200508,
          SpeakNpcId = 81103,
          Subtitle = "It's the velvet carpet that blanketed the stage after the curtain fell. As a child, after the earliest performance I can remember, my mother and I lingered on the stage after everyone left, reciting lines and dancing through the night.",
          TalkActionId = {
            [1] = "81103:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_05_6"
        },
        [90200508] = {
          ContentEN = "When dawn broke, exhaustion finally overtook me. I lay down on that carpet, resting my head on Mother's lap, and drifted into a long, sweet dream.",
          DialogueId = 90200508,
          GUID = "E1CEB8D8",
          NextOptions = {
            [1] = 90200002,
            [2] = 90200003
          },
          SpeakNpcId = 81103,
          Subtitle = "When dawn broke, exhaustion finally overtook me. I lay down on that carpet, resting my head on Mother's lap, and drifted into a long, sweet dream.",
          TalkActionId = {
            [1] = "81103:Sigh_End"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_05_7",
          bForbidSkipOptions = true
        },
        [90200601] = {
          ContentEN = [[
How have you been lately?
...Apologies for the abruptness. We don't actually know each other. I was... merely enquiring for a friend.]],
          DialogueId = 90200601,
          GUID = "E1CEC81A",
          SpeakNpcId = 81103,
          Subtitle = [[
How have you been lately?
...Apologies for the abruptness. We don't actually know each other. I was... merely enquiring for a friend.]],
          VoiceName = "voice/$Locale$/char/Tuosi/vo_companio_01"
        },
        [90200701] = {
          ContentEN = "Is that so? You've found a new home and a family who cares for you... That's wonderful. You've broken free of your cage — what a brave soul you are.",
          DialogueId = 90200701,
          GUID = "E1CED882",
          SpeakNpcId = 81103,
          Subtitle = "Is that so? You've found a new home and a family who cares for you... That's wonderful. You've broken free of your cage — what a brave soul you are.",
          VoiceName = "voice/$Locale$/char/Tuosi/vo_companio_02"
        },
        [90200901] = {
          ContentEN = "Your mimicry is extraordinary. Even the finest stage prop artists couldn't craft something so exquisitely detailed.",
          DialogueId = 90200901,
          GUID = "E1CEF952",
          SpeakNpcId = 81103,
          Subtitle = "Your mimicry is extraordinary. Even the finest stage prop artists couldn't craft something so exquisitely detailed.",
          VoiceName = "voice/$Locale$/char/Tuosi/vo_companio_04"
        },
        [90210000] = {
          ContentEN = "Is there anything I can help with? It's not that I'm a workaholic — it's just... a habit, I guess. When I'm not busy, I feel unsettled.",
          DialogueId = 90210000,
          GUID = "E1D4CE49",
          SpeakNpcId = 84101,
          Subtitle = "Is there anything I can help with? It's not that I'm a workaholic — it's just... a habit, I guess. When I'm not busy, I feel unsettled.",
          VoiceName = "voice/$Locale$/char/Lise/vo_idle"
        },
        [90210001] = {
          ContentEN = "Patrol complete. No signs of dangerous creatures, structural damage, or suspicious markings. Routine operations may proceed without interruption. Report concluded.",
          DialogueId = 90210001,
          GUID = "E1D4CE4A",
          LookAt = {
            [1] = "84101:n(0)",
            [2] = "0:n(84101)"
          },
          NextOptions = {
            [1] = 902100011,
            [2] = 902100012,
            [3] = 902100013,
            [4] = 902100014,
            [5] = 902100015,
            [6] = 902100016,
            [7] = 902100017
          },
          RandomOptionNum = 3,
          SpeakNpcId = 84101,
          Subtitle = "Patrol complete. No signs of dangerous creatures, structural damage, or suspicious markings. Routine operations may proceed without interruption. Report concluded.",
          TalkActionId = {
            [1] = "84101:Agree"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_welcome",
          bForbidSkipOptions = true
        },
        [90210002] = {
          ContentEN = "Let's talk about something else",
          DialogueId = 90210002,
          GUID = "90210002.0",
          NextDialogue = 90210001,
          Subtitle = "Let's talk about something else"
        },
        [90210003] = {
          ContentEN = "Goodbye",
          DialogueId = 90210003,
          GUID = "90210003.0",
          Subtitle = "Goodbye"
        },
        [90210101] = {
          ContentEN = "Oh... You've noticed. Yes, I have one — it was given to me by someone very dear. I keep it locked away safely, but... I can't help checking on it now and then, worried it might just vanish somehow.",
          DialogueId = 90210101,
          GUID = "E1D4DEB2",
          LookAt = {
            [1] = "84101:n(0)",
            [2] = "0:n(84101)"
          },
          NextDialogue = 90210102,
          SpeakNpcId = 84101,
          Subtitle = "Oh... You've noticed. Yes, I have one — it was given to me by someone very dear. I keep it locked away safely, but... I can't help checking on it now and then, worried it might just vanish somehow.",
          TalkActionId = {
            [1] = "84101:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_01_1"
        },
        [90210102] = {
          ContentEN = "Then you must know how to play lots of tunes on it.",
          DialogueId = 90210102,
          GUID = "E1D4DEDC",
          NextDialogue = 90210103,
          SpeakNpcId = 100001,
          Subtitle = "Then you must know how to play lots of tunes on it.",
          TalkActionId = {
            [1] = "84101:Explain02_End"
          }
        },
        [90210103] = {
          ContentEN = "Actually, I only know one. The person who gave it to me taught me. I wasn't quick to pick it up back then... maybe because I've never been good at things that require emotional expression...",
          DialogueId = 90210103,
          GUID = "E1D4DF06",
          NextDialogue = 90210104,
          SpeakNpcId = 84101,
          Subtitle = "Actually, I only know one. The person who gave it to me taught me. I wasn't quick to pick it up back then... maybe because I've never been good at things that require emotional expression...",
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_01_2"
        },
        [90210104] = {
          ContentEN = "But whenever I'm too tense or carried away, I find myself reaching for it. It's like an anchor — a reminder of the things that matter, the things I can trust. It always helps me find my calm again.",
          DialogueId = 90210104,
          GUID = "E1D4DF30",
          NextDialogue = 90210105,
          SpeakNpcId = 84101,
          Subtitle = "But whenever I'm too tense or carried away, I find myself reaching for it. It's like an anchor — a reminder of the things that matter, the things I can trust. It always helps me find my calm again.",
          TalkActionId = {
            [1] = "84101:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_01_3"
        },
        [90210105] = {
          ContentEN = "Many of my peers rely on doctors for stress relief — sedatives, stimulants, that kind of stuff. I've never needed that. Whether my heart races or slows, the harmonica always steadies me.",
          DialogueId = 90210105,
          GUID = "E1D4DF5A",
          NextOptions = {
            [1] = 90210002,
            [2] = 90210003
          },
          SpeakNpcId = 84101,
          Subtitle = "Many of my peers rely on doctors for stress relief — sedatives, stimulants, that kind of stuff. I've never needed that. Whether my heart races or slows, the harmonica always steadies me.",
          TalkActionId = {
            [1] = "84101:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_01_4",
          bForbidSkipOptions = true
        },
        [90210201] = {
          ContentEN = "Not bad. The Legion is one of the few places where hard work truly gets rewarded. I've earned my position here, and now I even have a few subordinates. I make sure they treat Charons and Solas with the same respect.",
          DialogueId = 90210201,
          GUID = "E1D4EF1A",
          LookAt = {
            [1] = "84101:n(0)",
            [2] = "0:n(84101)"
          },
          NextDialogue = 90210202,
          SpeakNpcId = 84101,
          Subtitle = "Not bad. The Legion is one of the few places where hard work truly gets rewarded. I've earned my position here, and now I even have a few subordinates. I make sure they treat Charons and Solas with the same respect.",
          TalkActionId = {
            [1] = "84101:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_02_1"
        },
        [90210202] = {
          ContentEN = "I've heard plenty of complaints — and bitter accusations — about how harshly the Legion treats the Charon community. I do everything I can to change that... Maybe someday, people will start to see the Legion in a better light.",
          DialogueId = 90210202,
          GUID = "E1D4EF44",
          NextDialogue = 90210203,
          SpeakNpcId = 84101,
          Subtitle = "I've heard plenty of complaints — and bitter accusations — about how harshly the Legion treats the Charon community. I do everything I can to change that... Maybe someday, people will start to see the Legion in a better light.",
          TalkActionId = {
            [1] = "84101:Talk01_End"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_02_2"
        },
        [90210203] = {
          ContentEN = "But are there enough people like you to really make a difference?",
          DialogueId = 90210203,
          GUID = "E1D4EF6E",
          NextDialogue = 90210204,
          SpeakNpcId = 100001,
          Subtitle = "But are there enough people like you to really make a difference?"
        },
        [90210204] = {
          ContentEN = "Not yet. But there will be. There was a time when you wouldn't find even a single Charon in the Legion. I know I can't make a big difference just yet, but if I guide my subordinates down the right path, I believe the conflicts between Charons and Solas will ease, bit by bit.",
          DialogueId = 90210204,
          GUID = "E1D4EF98",
          NextDialogue = 90210205,
          SpeakNpcId = 84101,
          Subtitle = "Not yet. But there will be. There was a time when you wouldn't find even a single Charon in the Legion. I know I can't make a big difference just yet, but if I guide my subordinates down the right path, I believe the conflicts between Charons and Solas will ease, bit by bit.",
          TalkActionId = {
            [1] = "84101:Agree"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_02_3"
        },
        [90210205] = {
          ContentEN = "Treating everyone fairly and keeping them safe from Filthoids and Deterioration... I believe these efforts can improve life for the Charon community. Maybe, it will quiet the weary sighs echoing through Icelake a little bit.",
          DialogueId = 90210205,
          GUID = "E1D4EFC2",
          NextOptions = {
            [1] = 90210002,
            [2] = 90210003
          },
          SpeakNpcId = 84101,
          Subtitle = "Treating everyone fairly and keeping them safe from Filthoids and Deterioration... I believe these efforts can improve life for the Charon community. Maybe, it will quiet the weary sighs echoing through Icelake a little bit.",
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_02_4",
          bForbidSkipOptions = true
        },
        [90210301] = {
          ContentEN = "I wouldn't call it responsibility. I'm simply following the Escort's regulations to the letter.",
          DialogueId = 90210301,
          GUID = "E1D4FF82",
          LookAt = {
            [1] = "84101:n(0)",
            [2] = "0:n(84101)"
          },
          NextDialogue = 90210302,
          SpeakNpcId = 84101,
          Subtitle = "I wouldn't call it responsibility. I'm simply following the Escort's regulations to the letter.",
          TalkActionId = {
            [1] = "84101:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_03_1"
        },
        [90210302] = {
          ContentEN = "But the other soldiers don't seem to do the same — they're always so reckless and rude.",
          DialogueId = 90210302,
          GUID = "E1D4FFAC",
          NextDialogue = 90210303,
          SpeakNpcId = 100001,
          Subtitle = "But the other soldiers don't seem to do the same — they're always so reckless and rude."
        },
        [90210303] = {
          ContentEN = "The Escort's regulations forbid any legionary from commenting on the conduct of their fellow legionaries.",
          DialogueId = 90210303,
          GUID = "E1D4FFD6",
          NextDialogue = 90210304,
          SpeakNpcId = 84101,
          Subtitle = "The Escort's regulations forbid any legionary from commenting on the conduct of their fellow legionaries.",
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_03_2"
        },
        [90210304] = {
          ContentEN = "That said, I really don't understand them. Maybe, to them, it's just a job. As long as their superiors don't notice, they think it's fine to slack off or mess around.",
          DialogueId = 90210304,
          GUID = "E1D50000",
          NextDialogue = 90210305,
          SpeakNpcId = 84101,
          Subtitle = "That said, I really don't understand them. Maybe, to them, it's just a job. As long as their superiors don't notice, they think it's fine to slack off or mess around.",
          TalkActionId = {
            [1] = "84101:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_03_3"
        },
        [90210305] = {
          ContentEN = "I think that kind of attitude is wrong. People need something to keep themselves in check. Without it, they'll just drift through life, letting their standards erode little by little — until they're no better than rats in the sewers.",
          DialogueId = 90210305,
          GUID = "E1D5002A",
          NextOptions = {
            [1] = 90210002,
            [2] = 90210003
          },
          SpeakNpcId = 84101,
          Subtitle = "I think that kind of attitude is wrong. People need something to keep themselves in check. Without it, they'll just drift through life, letting their standards erode little by little — until they're no better than rats in the sewers.",
          TalkActionId = {
            [1] = "84101:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_03_4",
          bForbidSkipOptions = true
        },
        [90210401] = {
          ContentEN = "No... Thank you. I don't really enjoy looking at myself in the mirror. Seeing my horns always makes me feel... uncomfortable.",
          DialogueId = 90210401,
          GUID = "E1D50FEA",
          LookAt = {
            [1] = "84101:n(0)",
            [2] = "0:n(84101)"
          },
          NextDialogue = 90210402,
          SpeakNpcId = 84101,
          Subtitle = "No... Thank you. I don't really enjoy looking at myself in the mirror. Seeing my horns always makes me feel... uncomfortable.",
          TalkActionId = {
            [1] = "84101:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_04_1"
        },
        [90210402] = {
          ContentEN = "So, you're not comfortable with how Charons look?",
          DialogueId = 90210402,
          GUID = "E1D51014",
          NextDialogue = 90210403,
          SpeakNpcId = 100001,
          Subtitle = "So, you're not comfortable with how Charons look?"
        },
        [90210403] = {
          ContentEN = "No, that's not it at all. I'm not ashamed of my Charon heritage. It's just... I think my horns would look much better if they were more regular, more symmetrical. Ah, don't get me wrong! I'm not saying there's anything wrong with your horn...",
          DialogueId = 90210403,
          GUID = "E1D5103E",
          NextOptions = {
            [1] = 90210002,
            [2] = 90210003
          },
          SpeakNpcId = 84101,
          Subtitle = "No, that's not it at all. I'm not ashamed of my Charon heritage. It's just... I think my horns would look much better if they were more regular, more symmetrical. Ah, don't get me wrong! I'm not saying there's anything wrong with your horn...",
          TalkActionId = {
            [1] = "84101:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_04_2",
          bForbidSkipOptions = true
        },
        [90210501] = {
          ContentEN = "I do... but it feels so heavy now, almost unbearably so. I'm not sure I have the strength to pick it up and play anymore.",
          DialogueId = 90210501,
          GUID = "E1D52052",
          LookAt = {
            [1] = "84101:n(0)",
            [2] = "0:n(84101)"
          },
          NextDialogue = 90210502,
          SpeakNpcId = 84101,
          Subtitle = "I do... but it feels so heavy now, almost unbearably so. I'm not sure I have the strength to pick it up and play anymore.",
          TalkActionId = {
            [1] = "84101:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_05_1"
        },
        [90210502] = {
          ContentEN = "After all, it once carried all my hopes and dreams. Now, it just reminds me of everything I've lost.",
          DialogueId = 90210502,
          GUID = "E1D5207C",
          NextDialogue = 90210503,
          SpeakNpcId = 84101,
          Subtitle = "After all, it once carried all my hopes and dreams. Now, it just reminds me of everything I've lost.",
          TalkActionId = {
            [1] = "84101:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_05_2"
        },
        [90210503] = {
          ContentEN = "If you ever feel ready to play it again, I'd be honoured to be your first listener.",
          DialogueId = 90210503,
          GUID = "E1D520A6",
          NextDialogue = 90210504,
          SpeakNpcId = 100001,
          Subtitle = "If you ever feel ready to play it again, I'd be honoured to be your first listener."
        },
        [90210504] = {
          ContentEN = "...Thank you. I promise, when the day comes that I can pick it up again — when I'm ready to learn a new tune — I'll make sure you're the first to hear it.",
          DialogueId = 90210504,
          GUID = "E1D520D0",
          NextOptions = {
            [1] = 90210002,
            [2] = 90210003
          },
          SpeakNpcId = 84101,
          Subtitle = "...Thank you. I promise, when the day comes that I can pick it up again — when I'm ready to learn a new tune — I'll make sure you're the first to hear it.",
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_05_3",
          bForbidSkipOptions = true
        },
        [90210601] = {
          ContentEN = "I've been taking on odd jobs here and there. It's enough to cover my expenses. But honestly, earning a living isn't the point anymore. These days, work is more about keeping myself busy.",
          DialogueId = 90210601,
          GUID = "E1D530BA",
          LookAt = {
            [1] = "84101:n(0)",
            [2] = "0:n(84101)"
          },
          NextDialogue = 90210602,
          SpeakNpcId = 84101,
          Subtitle = "I've been taking on odd jobs here and there. It's enough to cover my expenses. But honestly, earning a living isn't the point anymore. These days, work is more about keeping myself busy.",
          TalkActionId = {
            [1] = "84101:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_06_1"
        },
        [90210602] = {
          ContentEN = "Keeping busy?",
          DialogueId = 90210602,
          GUID = "E1D530E4",
          NextDialogue = 90210603,
          SpeakNpcId = 100001,
          Subtitle = "Keeping busy?",
          TalkActionId = {
            [1] = "84101:Talk02_End"
          }
        },
        [90210603] = {
          ContentEN = "Yes... Work gives me purpose. It makes me happy. When I'm busy, even the sunlight feels a little warmer.",
          DialogueId = 90210603,
          GUID = "E1D5310E",
          NextOptions = {
            [1] = 90210002,
            [2] = 90210003
          },
          SpeakNpcId = 84101,
          Subtitle = "Yes... Work gives me purpose. It makes me happy. When I'm busy, even the sunlight feels a little warmer.",
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_06_2",
          bForbidSkipOptions = true
        },
        [90210701] = {
          ContentEN = "Better than if I'd stayed, I suppose. The Legion was once my refuge, the place where I thought my dreams could take flight. But those dreams... they turned out to be illusions, and that so-called refuge was a hell that dragged my loved one into an unending abyss of despair...",
          DialogueId = 90210701,
          GUID = "E1D54122",
          LookAt = {
            [1] = "84101:n(0)",
            [2] = "0:n(84101)"
          },
          NextDialogue = 90210702,
          SpeakNpcId = 84101,
          Subtitle = "Better than if I'd stayed, I suppose. The Legion was once my refuge, the place where I thought my dreams could take flight. But those dreams... they turned out to be illusions, and that so-called refuge was a hell that dragged my loved one into an unending abyss of despair...",
          TalkActionId = {
            [1] = "84101:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_07_1"
        },
        [90210702] = {
          ContentEN = "Now, my heart burns with the desire for vengeance, yet I can't bring myself to aim my weapon at those I once called comrades. I feel lost... Tell me, what should I do?",
          DialogueId = 90210702,
          GUID = "E1D5414C",
          NextDialogue = 90210703,
          SpeakNpcId = 84101,
          Subtitle = "Now, my heart burns with the desire for vengeance, yet I can't bring myself to aim my weapon at those I once called comrades. I feel lost... Tell me, what should I do?",
          TalkActionId = {
            [1] = "84101:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_07_2"
        },
        [90210703] = {
          ContentEN = "I think that's a question only you can answer.",
          DialogueId = 90210703,
          GUID = "E1D54176",
          NextDialogue = 90210704,
          SpeakNpcId = 100001,
          Subtitle = "I think that's a question only you can answer."
        },
        [90210704] = {
          ContentEN = "...Sorry, I lost my cool. You're right — I need to figure it out on my own, instead of placing that weight on you. Though... it might take me some time.",
          DialogueId = 90210704,
          GUID = "E1D541A0",
          NextOptions = {
            [1] = 90210002,
            [2] = 90210003
          },
          SpeakNpcId = 84101,
          Subtitle = "...Sorry, I lost my cool. You're right — I need to figure it out on my own, instead of placing that weight on you. Though... it might take me some time.",
          TalkActionId = {
            [1] = "84101:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_07_3",
          bForbidSkipOptions = true
        },
        [90210901] = {
          ContentEN = "This proposal is remarkably detailed, down to every second accounted for. Following it through must be immensely satisfying. It's just... hard to believe something like this was put together by Lieutenant Colonel Randy.",
          DialogueId = 90210901,
          GUID = "E1D561F2",
          SpeakNpcId = 84101,
          Subtitle = "This proposal is remarkably detailed, down to every second accounted for. Following it through must be immensely satisfying. It's just... hard to believe something like this was put together by Lieutenant Colonel Randy.",
          VoiceName = "voice/$Locale$/char/Lise/vo_companio_02"
        },
        [90220000] = {
          ContentEN = "In a land so fraught with turmoil, having such a tranquil place for even a brief moment of peace is a rare comfort.",
          DialogueId = 90220000,
          GUID = "E1DB36E9",
          SpeakNpcId = 81502,
          Subtitle = "In a land so fraught with turmoil, having such a tranquil place for even a brief moment of peace is a rare comfort.",
          VoiceName = "voice/$Locale$/char/Nifu/vo_idle"
        },
        [90220001] = {
          ContentEN = "Ah, it's you, my dear child. Good day. Is there something on your mind you'd like to share with me?",
          DialogueId = 90220001,
          GUID = "E1DB36EA",
          LookAt = {
            [1] = "81502:n(0)",
            [2] = "0:n(81502)"
          },
          NextOptions = {
            [1] = 902200011,
            [2] = 902200012,
            [3] = 902200013,
            [4] = 902200014
          },
          RandomOptionNum = 3,
          SpeakNpcId = 81502,
          Subtitle = "Ah, it's you, my dear child. Good day. Is there something on your mind you'd like to share with me?",
          TalkActionId = {
            [1] = "81502:Agree"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_welcome",
          bForbidSkipOptions = true
        },
        [90220002] = {
          ContentEN = "Let's talk about something else",
          DialogueId = 90220002,
          GUID = "90220002.0",
          NextDialogue = 90220001,
          Subtitle = "Let's talk about something else"
        },
        [90220003] = {
          ContentEN = "Goodbye",
          DialogueId = 90220003,
          GUID = "90220003.0",
          Subtitle = "Goodbye"
        },
        [90220101] = {
          ContentEN = "Indeed. Over the course of endless time, I've travelled — or perhaps wandered — through every corner of Atlasia, treading upon every inch of its soil and tracing every grain of sand with my fingertips.",
          DialogueId = 90220101,
          GUID = "E1DB4752",
          LookAt = {
            [1] = "81502:n(0)",
            [2] = "0:n(81502)"
          },
          NextDialogue = 90220102,
          SpeakNpcId = 81502,
          Subtitle = "Indeed. Over the course of endless time, I've travelled — or perhaps wandered — through every corner of Atlasia, treading upon every inch of its soil and tracing every grain of sand with my fingertips.",
          TalkActionId = {
            [1] = "81502:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_01_1"
        },
        [90220102] = {
          ContentEN = "So, which place is your favourite?",
          DialogueId = 90220102,
          GUID = "E1DB477C",
          NextDialogue = 90220103,
          SpeakNpcId = 100001,
          Subtitle = "So, which place is your favourite?",
          TalkActionId = {
            [1] = "81502:Explain01_End"
          }
        },
        [90220103] = {
          ContentEN = "Once you've seen enough, you'll find that the scenery of all places is not so different after all. Whether it's the snows of the North, the sands of Khemet, or the smoke curling from the chimneys of Huaxu, they are all but different shades of mist drifting through the forest.",
          DialogueId = 90220103,
          GUID = "E1DB47A6",
          NextDialogue = 90220104,
          SpeakNpcId = 81502,
          Subtitle = "Once you've seen enough, you'll find that the scenery of all places is not so different after all. Whether it's the snows of the North, the sands of Khemet, or the smoke curling from the chimneys of Huaxu, they are all but different shades of mist drifting through the forest.",
          TalkActionId = {
            [1] = "81502:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_01_2"
        },
        [90220104] = {
          ContentEN = "If I had to choose, though... it would be the mountains and forests of Aethyrie. The air there brings me the most peace.",
          DialogueId = 90220104,
          GUID = "E1DB47D0",
          NextDialogue = 90220105,
          SpeakNpcId = 81502,
          Subtitle = "If I had to choose, though... it would be the mountains and forests of Aethyrie. The air there brings me the most peace.",
          TalkActionId = {
            [1] = "81502:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_01_3"
        },
        [90220105] = {
          ContentEN = "I'll have to visit someday.",
          DialogueId = 90220105,
          GUID = "E1DB47FA",
          NextDialogue = 90220106,
          SpeakNpcId = 100001,
          Subtitle = "I'll have to visit someday."
        },
        [90220106] = {
          ContentEN = "Perhaps you will.",
          DialogueId = 90220106,
          GUID = "E1DB4824",
          NextDialogue = 90220107,
          SpeakNpcId = 81502,
          Subtitle = "Perhaps you will.",
          TalkActionId = {
            [1] = "81502:Agree"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_01_4"
        },
        [90220107] = {
          ContentEN = "Should you wander into the Emerald Forest, would you mind bringing a bouquet of white asters for me? Beneath its earth rest my friends, my child, and a version of myself from long ago.",
          DialogueId = 90220107,
          GUID = "E1DB484E",
          NextOptions = {
            [1] = 90220002,
            [2] = 90220003
          },
          SpeakNpcId = 81502,
          Subtitle = "Should you wander into the Emerald Forest, would you mind bringing a bouquet of white asters for me? Beneath its earth rest my friends, my child, and a version of myself from long ago.",
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_01_5",
          bForbidSkipOptions = true
        },
        [90220201] = {
          ContentEN = "The Misty Sea is the birthplace and final rest of all living beings. To the Misty Sea, the deceased return, and from there, life begins anew... just as dying clouds dissolve into the earth as rain, only for flowers to bloom again from that very soil.",
          DialogueId = 90220201,
          GUID = "E1DB57BA",
          LookAt = {
            [1] = "81502:n(0)",
            [2] = "0:n(81502)"
          },
          NextDialogue = 90220202,
          SpeakNpcId = 81502,
          Subtitle = "The Misty Sea is the birthplace and final rest of all living beings. To the Misty Sea, the deceased return, and from there, life begins anew... just as dying clouds dissolve into the earth as rain, only for flowers to bloom again from that very soil.",
          TalkActionId = {
            [1] = "81502:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_02_1"
        },
        [90220202] = {
          ContentEN = "Will I go there someday, too?",
          DialogueId = 90220202,
          GUID = "E1DB57E4",
          NextDialogue = 90220203,
          SpeakNpcId = 100001,
          Subtitle = "Will I go there someday, too?",
          TalkActionId = {
            [1] = "81502:Confident_End"
          }
        },
        [90220203] = {
          ContentEN = "I believe so, my child. One day, you will journey to the Misty Sea, into the embrace of Mother Embla.",
          DialogueId = 90220203,
          GUID = "E1DB580E",
          NextDialogue = 90220204,
          SpeakNpcId = 81502,
          Subtitle = "I believe so, my child. One day, you will journey to the Misty Sea, into the embrace of Mother Embla.",
          TalkActionId = {
            [1] = "81502:Agree"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_02_2"
        },
        [90220204] = {
          ContentEN = "That sounds... a bit scary.",
          DialogueId = 90220204,
          GUID = "E1DB5838",
          NextDialogue = 90220205,
          SpeakNpcId = 100001,
          Subtitle = "That sounds... a bit scary."
        },
        [90220205] = {
          ContentEN = "My dear child, cherish all that life offers, yet do not shrink from its passing. Demise is not suffering, but the inevitable conclusion of life's journey.",
          DialogueId = 90220205,
          GUID = "E1DB5862",
          NextDialogue = 90220206,
          SpeakNpcId = 81502,
          Subtitle = "My dear child, cherish all that life offers, yet do not shrink from its passing. Demise is not suffering, but the inevitable conclusion of life's journey.",
          TalkActionId = {
            [1] = "81502:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_02_3"
        },
        [90220206] = {
          ContentEN = "Should you ever grow weary, rest in my arms for a while... There is no need to fear — this will not be your eternal sleep. There is still much for you to fulfil in this world.",
          DialogueId = 90220206,
          GUID = "E1DB588C",
          NextOptions = {
            [1] = 90220002,
            [2] = 90220003
          },
          SpeakNpcId = 81502,
          Subtitle = "Should you ever grow weary, rest in my arms for a while... There is no need to fear — this will not be your eternal sleep. There is still much for you to fulfil in this world.",
          TalkActionId = {
            [1] = "81502:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_02_4",
          bForbidSkipOptions = true
        },
        [90220301] = {
          ContentEN = "Did that surprise you? Long ago, during the Great Migration, I stood on the front lines as a soldier well-versed in close combat.",
          DialogueId = 90220301,
          GUID = "E1DB6822",
          LookAt = {
            [1] = "81502:n(0)",
            [2] = "0:n(81502)"
          },
          NextDialogue = 90220302,
          SpeakNpcId = 81502,
          Subtitle = "Did that surprise you? Long ago, during the Great Migration, I stood on the front lines as a soldier well-versed in close combat.",
          TalkActionId = {
            [1] = "81502:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_03_1"
        },
        [90220302] = {
          ContentEN = "Though those days are far behind me, I still remember the essentials of fighting.",
          DialogueId = 90220302,
          GUID = "E1DB684C",
          NextDialogue = 90220303,
          SpeakNpcId = 81502,
          Subtitle = "Though those days are far behind me, I still remember the essentials of fighting.",
          TalkActionId = {
            [1] = "81502:Talk01_End"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_03_2"
        },
        [90220303] = {
          ContentEN = "During my wanderings, I've often faced roaming beasts. Their claws and fangs have left me with scars, bruises, and even deaths I should have rightfully endured.",
          DialogueId = 90220303,
          GUID = "E1DB6876",
          NextDialogue = 90220304,
          SpeakNpcId = 81502,
          Subtitle = "During my wanderings, I've often faced roaming beasts. Their claws and fangs have left me with scars, bruises, and even deaths I should have rightfully endured.",
          TalkActionId = {
            [1] = "81502:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_03_3"
        },
        [90220304] = {
          ContentEN = "It's hard to picture you grappling hand-to-hand...",
          DialogueId = 90220304,
          GUID = "E1DB68A0",
          NextDialogue = 90220305,
          SpeakNpcId = 100001,
          Subtitle = "It's hard to picture you grappling hand-to-hand...",
          TalkActionId = {
            [1] = "81502:Talk02_End"
          }
        },
        [90220305] = {
          ContentEN = "Even the eternal moon wanes and waxes, ever changing. Humans, naturally, are far more complex — especially one who's lived countless lifetimes beyond a mortal span.",
          DialogueId = 90220305,
          GUID = "E1DB68CA",
          NextDialogue = 90220306,
          SpeakNpcId = 81502,
          Subtitle = "Even the eternal moon wanes and waxes, ever changing. Humans, naturally, are far more complex — especially one who's lived countless lifetimes beyond a mortal span.",
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_03_4"
        },
        [90220306] = {
          ContentEN = "If you're curious about those days, I'll recount them in detail for you another time.",
          DialogueId = 90220306,
          GUID = "E1DB68F4",
          NextOptions = {
            [1] = 90220002,
            [2] = 90220003
          },
          SpeakNpcId = 81502,
          Subtitle = "If you're curious about those days, I'll recount them in detail for you another time.",
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_03_5",
          bForbidSkipOptions = true
        },
        [90220401] = {
          ContentEN = "\"Friends\"... By the common definition of the word, I've had many over my long years.",
          DialogueId = 90220401,
          GUID = "E1DB788A",
          LookAt = {
            [1] = "81502:n(0)",
            [2] = "0:n(81502)"
          },
          NextDialogue = 90220402,
          SpeakNpcId = 81502,
          Subtitle = "\"Friends\"... By the common definition of the word, I've had many over my long years.",
          TalkActionId = {
            [1] = "81502:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_04_1"
        },
        [90220402] = {
          ContentEN = "Yet when I hear that word, the first who come to mind are Lexis and Erika, the two who once led me away from Elysium.",
          DialogueId = 90220402,
          GUID = "E1DB78B4",
          NextDialogue = 90220403,
          SpeakNpcId = 81502,
          Subtitle = "Yet when I hear that word, the first who come to mind are Lexis and Erika, the two who once led me away from Elysium.",
          TalkActionId = {
            [1] = "81502:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_04_2"
        },
        [90220403] = {
          ContentEN = "What were they like?",
          DialogueId = 90220403,
          GUID = "E1DB78DE",
          NextDialogue = 90220404,
          SpeakNpcId = 100001,
          Subtitle = "What were they like?"
        },
        [90220404] = {
          ContentEN = "In the annals of history and the tales of heroes, they're often portrayed as the Sage who tore away the gods' veil of ignorance, and the Heroine who gave her life for the Sage's cause...",
          DialogueId = 90220404,
          GUID = "E1DB7908",
          NextDialogue = 90220405,
          SpeakNpcId = 81502,
          Subtitle = "In the annals of history and the tales of heroes, they're often portrayed as the Sage who tore away the gods' veil of ignorance, and the Heroine who gave her life for the Sage's cause...",
          TalkActionId = {
            [1] = "81502:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_04_3"
        },
        [90220405] = {
          ContentEN = "But in my memories, they are simply Lexis and Erika.",
          DialogueId = 90220405,
          GUID = "E1DB7932",
          NextDialogue = 90220406,
          SpeakNpcId = 81502,
          Subtitle = "But in my memories, they are simply Lexis and Erika.",
          TalkActionId = {
            [1] = "81502:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_04_4"
        },
        [90220406] = {
          ContentEN = "Erika was a brave and lively young woman, with a spirit that drew everyone to her. Lexis, though brilliant, often overthought things. He'd suddenly lapse into deep musings, which, ironically, made him seem a bit slow.",
          DialogueId = 90220406,
          GUID = "E1DB795C",
          NextDialogue = 90220407,
          SpeakNpcId = 81502,
          Subtitle = "Erika was a brave and lively young woman, with a spirit that drew everyone to her. Lexis, though brilliant, often overthought things. He'd suddenly lapse into deep musings, which, ironically, made him seem a bit slow.",
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_04_5"
        },
        [90220407] = {
          ContentEN = "Any fun stories?",
          DialogueId = 90220407,
          GUID = "E1DB7986",
          NextDialogue = 90220408,
          SpeakNpcId = 100001,
          Subtitle = "Any fun stories?"
        },
        [90220408] = {
          ContentEN = "Mm... There was one time Lexis tried to apologize to Erika for something he'd done. On a whim, she pointed to one of the soldiers' archery training dummies, saying she'd forgive him if he could hit the bullseye...",
          DialogueId = 90220408,
          GUID = "E1DB79B0",
          NextDialogue = 90220409,
          SpeakNpcId = 81502,
          Subtitle = "Mm... There was one time Lexis tried to apologize to Erika for something he'd done. On a whim, she pointed to one of the soldiers' archery training dummies, saying she'd forgive him if he could hit the bullseye...",
          TalkActionId = {
            [1] = "81502:Agree"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_04_6"
        },
        [90220409] = {
          ContentEN = "Of course, she didn't mean it seriously. Not even all the soldiers could manage it, let alone Lexis, whose hands were meant for quills and scrolls, not bows or blades.",
          DialogueId = 90220409,
          GUID = "E1DB79DA",
          NextDialogue = 90220410,
          SpeakNpcId = 81502,
          Subtitle = "Of course, she didn't mean it seriously. Not even all the soldiers could manage it, let alone Lexis, whose hands were meant for quills and scrolls, not bows or blades.",
          TalkActionId = {
            [1] = "81502:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_04_7"
        },
        [90220410] = {
          ContentEN = "But he took her words to heart. After the soldiers left, he stayed behind and practised alone, long into the night.",
          DialogueId = 90220410,
          GUID = "E1DB7A04",
          NextDialogue = 90220411,
          SpeakNpcId = 81502,
          Subtitle = "But he took her words to heart. After the soldiers left, he stayed behind and practised alone, long into the night.",
          TalkActionId = {
            [1] = "81502:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_04_8"
        },
        [90220411] = {
          ContentEN = "As you might guess, true history is not a tale of omnipotent heroes. Even someone as brilliant as Lexis had his limits — he practised until his palms bled. Erika ended up wrapping them in linen, but he never did strike the mark.",
          DialogueId = 90220411,
          GUID = "E1DB7A2E",
          NextDialogue = 90220412,
          SpeakNpcId = 81502,
          Subtitle = "As you might guess, true history is not a tale of omnipotent heroes. Even someone as brilliant as Lexis had his limits — he practised until his palms bled. Erika ended up wrapping them in linen, but he never did strike the mark.",
          TalkActionId = {
            [1] = "81502:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_04_9"
        },
        [90220412] = {
          ContentEN = "The funny thing is, I can't even recall why they argued in the first place. Strange, isn't it? When I think of them now, it's always these small, insignificant details that come to mind first.",
          DialogueId = 90220412,
          GUID = "E1DB7A58",
          NextDialogue = 90220413,
          SpeakNpcId = 81502,
          Subtitle = "The funny thing is, I can't even recall why they argued in the first place. Strange, isn't it? When I think of them now, it's always these small, insignificant details that come to mind first.",
          TalkActionId = {
            [1] = "81502:Talk03_End"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_04_10"
        },
        [90220413] = {
          ContentEN = "Sounds like some golden memories.",
          DialogueId = 90220413,
          GUID = "E1DB7A82",
          NextDialogue = 90220414,
          SpeakNpcId = 100001,
          Subtitle = "Sounds like some golden memories."
        },
        [90220414] = {
          ContentEN = "Indeed. Those were such precious, joyful days... But they are far behind me now.",
          DialogueId = 90220414,
          GUID = "E1DB7AAC",
          NextOptions = {
            [1] = 90220002,
            [2] = 90220003
          },
          SpeakNpcId = 81502,
          Subtitle = "Indeed. Those were such precious, joyful days... But they are far behind me now.",
          TalkActionId = {
            [1] = "81502:Agree"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_04_11",
          bForbidSkipOptions = true
        },
        [90220501] = {
          ContentEN = "No soul can outrun its past forever. In time, you will have to confront yours. May you have the strength to face it when that moment arrives.",
          DialogueId = 90220501,
          GUID = "E1DB88F2",
          SpeakNpcId = 81502,
          Subtitle = "No soul can outrun its past forever. In time, you will have to confront yours. May you have the strength to face it when that moment arrives.",
          VoiceName = "voice/$Locale$/char/Nifu/vo_companio_01"
        },
        [90220601] = {
          ContentEN = "My dear, you carry an aura I find quite familiar. Could it be that you, like me, hail from bygone days?",
          DialogueId = 90220601,
          GUID = "E1DB995A",
          SpeakNpcId = 81502,
          Subtitle = "My dear, you carry an aura I find quite familiar. Could it be that you, like me, hail from bygone days?",
          VoiceName = "voice/$Locale$/char/Nifu/vo_companio_02"
        },
        [90230000] = {
          ContentEN = "I had my secretary clear my schedule for the next few days. For now, I wish only to savour this tranquillity with you, untouched by the clamour of the outside world. Is this out of sincerity, or another calculated move? Why don't you take a guess?",
          DialogueId = 90230000,
          GUID = "E1E19F60",
          SpeakNpcId = 84102,
          Subtitle = "I had my secretary clear my schedule for the next few days. For now, I wish only to savour this tranquillity with you, untouched by the clamour of the outside world. Is this out of sincerity, or another calculated move? Why don't you take a guess?",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_idle"
        },
        [90230001] = {
          ContentEN = "Ah, so you've come to see me... Are you still resentful? Conflicted, perhaps? Or have you become indifferent toward me? It makes no difference. We have all the time in the world to figure it out.",
          DialogueId = 90230001,
          GUID = "E1E19F8A",
          LookAt = {
            [1] = "84102:n(0)",
            [2] = "0:n(84102)"
          },
          NextOptions = {
            [1] = 902300011,
            [2] = 902300012,
            [3] = 902300013,
            [4] = 902300014
          },
          RandomOptionNum = 3,
          SpeakNpcId = 84102,
          Subtitle = "Ah, so you've come to see me... Are you still resentful? Conflicted, perhaps? Or have you become indifferent toward me? It makes no difference. We have all the time in the world to figure it out.",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_welcome",
          bForbidSkipOptions = true
        },
        [90230002] = {
          ContentEN = "Let's talk about something else",
          DialogueId = 90230002,
          GUID = "E1E19FB4",
          NextDialogue = 90230001,
          Subtitle = "Let's talk about something else"
        },
        [90230003] = {
          ContentEN = "Goodbye",
          DialogueId = 90230003,
          GUID = "E1E19FDE",
          Subtitle = "Goodbye"
        },
        [90230101] = {
          ContentEN = "There is nothing that cannot be leveraged in a negotiation. The only question is — what price will move the scales in your favour?",
          DialogueId = 90230101,
          GUID = "E1E1AFF2",
          LookAt = {
            [1] = "84102:n(0)",
            [2] = "0:n(84102)"
          },
          NextDialogue = 90230102,
          SpeakNpcId = 84102,
          Subtitle = "There is nothing that cannot be leveraged in a negotiation. The only question is — what price will move the scales in your favour?",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_01_1"
        },
        [90230102] = {
          ContentEN = "Even when the price is your life?",
          DialogueId = 90230102,
          GUID = "E1E1B01C",
          NextDialogue = 90230103,
          SpeakNpcId = 100001,
          Subtitle = "Even when the price is your life?"
        },
        [90230103] = {
          ContentEN = "Indeed. Your life, mine, and the lives of countless others — each is but a piece on a grander board, their worth determined only by the stakes at play.",
          DialogueId = 90230103,
          GUID = "E1E1B046",
          NextDialogue = 90230104,
          SpeakNpcId = 84102,
          Subtitle = "Indeed. Your life, mine, and the lives of countless others — each is but a piece on a grander board, their worth determined only by the stakes at play.",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_01_2"
        },
        [90230104] = {
          ContentEN = "For those as insignificant as we, to exchange what little we have for what we desire... is that not, in itself, a stroke of fortune?",
          DialogueId = 90230104,
          GUID = "E1E1B070",
          NextDialogue = 90230105,
          SpeakNpcId = 84102,
          Subtitle = "For those as insignificant as we, to exchange what little we have for what we desire... is that not, in itself, a stroke of fortune?",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_01_3"
        },
        [90230105] = {
          ContentEN = "Does my answer unsettle you? Then, by all means, prove me wrong.",
          DialogueId = 90230105,
          GUID = "E1E1B09A",
          NextOptions = {
            [1] = 90230002,
            [2] = 90230003
          },
          SpeakNpcId = 84102,
          Subtitle = "Does my answer unsettle you? Then, by all means, prove me wrong.",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_01_4",
          bForbidSkipOptions = true
        },
        [90230201] = {
          ContentEN = "Mmm... Never lose yourself in fleeting profits and losses. Play the long game. Be generous when needed. Learn to read people, to use them, and to grant them favours, so that they respect you, admire you, and also fear you. True power lies in that delicate balance.",
          DialogueId = 90230201,
          GUID = "E1E1C05A",
          LookAt = {
            [1] = "84102:n(0)",
            [2] = "0:n(84102)"
          },
          NextDialogue = 90230202,
          SpeakNpcId = 84102,
          Subtitle = "Mmm... Never lose yourself in fleeting profits and losses. Play the long game. Be generous when needed. Learn to read people, to use them, and to grant them favours, so that they respect you, admire you, and also fear you. True power lies in that delicate balance.",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_02_1"
        },
        [90230202] = {
          ContentEN = "That's not quite what I had in mind.",
          DialogueId = 90230202,
          GUID = "E1E1C084",
          NextDialogue = 90230203,
          SpeakNpcId = 100001,
          Subtitle = "That's not quite what I had in mind."
        },
        [90230203] = {
          ContentEN = "Heh. Goods have fixed prices, but human connections are a different currency altogether. Those who haggle over every coin will remain forever bound to their little corner of the market. Only by mastering the art of influence can one rise above mere trade and ascend to true greatness.",
          DialogueId = 90230203,
          GUID = "E1E1C0AE",
          NextOptions = {
            [1] = 90230002,
            [2] = 90230003
          },
          SpeakNpcId = 84102,
          Subtitle = "Heh. Goods have fixed prices, but human connections are a different currency altogether. Those who haggle over every coin will remain forever bound to their little corner of the market. Only by mastering the art of influence can one rise above mere trade and ascend to true greatness.",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_02_2",
          bForbidSkipOptions = true
        },
        [90230301] = {
          ContentEN = "I am often entangled in the minutiae of business and rarely afforded the luxury of leisure.",
          DialogueId = 90230301,
          GUID = "E1E1D0C2",
          LookAt = {
            [1] = "84102:n(0)",
            [2] = "0:n(84102)"
          },
          NextDialogue = 90230302,
          SpeakNpcId = 84102,
          Subtitle = "I am often entangled in the minutiae of business and rarely afforded the luxury of leisure.",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_03_1"
        },
        [90230302] = {
          ContentEN = "Yet, if fate were to grant me a fleeting moment of respite... I would likely seek solace in the theatre. Be it the age-old storytelling traditions of Huaxu, the refined operas of the Empire, or the avant-garde films gaining traction overseas — each offers its own intrigue.",
          DialogueId = 90230302,
          GUID = "E1E1D0EC",
          NextDialogue = 90230303,
          SpeakNpcId = 84102,
          Subtitle = "Yet, if fate were to grant me a fleeting moment of respite... I would likely seek solace in the theatre. Be it the age-old storytelling traditions of Huaxu, the refined operas of the Empire, or the avant-garde films gaining traction overseas — each offers its own intrigue.",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_03_2"
        },
        [90230303] = {
          ContentEN = "It seems our meeting at the theatre wasn't just a coincidence, then.",
          DialogueId = 90230303,
          GUID = "E1E1D116",
          NextDialogue = 90230304,
          SpeakNpcId = 100001,
          Subtitle = "It seems our meeting at the theatre wasn't just a coincidence, then."
        },
        [90230304] = {
          ContentEN = "Heh... No, I suppose not. Theatre distils fleeting moments of life, yet within those fragments, it unveils profound truths about the human soul — one that defies reason, thrives in contradiction, and remains endlessly captivating in its unpredictability.",
          DialogueId = 90230304,
          GUID = "E1E1D140",
          NextDialogue = 90230305,
          SpeakNpcId = 84102,
          Subtitle = "Heh... No, I suppose not. Theatre distils fleeting moments of life, yet within those fragments, it unveils profound truths about the human soul — one that defies reason, thrives in contradiction, and remains endlessly captivating in its unpredictability.",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_03_3"
        },
        [90230305] = {
          ContentEN = "So, what unexpected turns will you bring to my story? I shall be watching with keen interest.",
          DialogueId = 90230305,
          GUID = "E1E1D16A",
          NextOptions = {
            [1] = 90230002,
            [2] = 90230003
          },
          SpeakNpcId = 84102,
          Subtitle = "So, what unexpected turns will you bring to my story? I shall be watching with keen interest.",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_03_4",
          bForbidSkipOptions = true
        },
        [90230401] = {
          ContentEN = "Hmm? So, you've noticed. An old habit, nothing more.",
          DialogueId = 90230401,
          GUID = "E1E1E12A",
          LookAt = {
            [1] = "84102:n(0)",
            [2] = "0:n(84102)"
          },
          NextDialogue = 90230402,
          SpeakNpcId = 84102,
          Subtitle = "Hmm? So, you've noticed. An old habit, nothing more.",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_04_1"
        },
        [90230402] = {
          ContentEN = "When I was little, an accident left me stranded in a pitch-black ravine for three days and nights. It was then this... tendency took root.",
          DialogueId = 90230402,
          GUID = "E1E1E154",
          NextDialogue = 90230403,
          SpeakNpcId = 84102,
          Subtitle = "When I was little, an accident left me stranded in a pitch-black ravine for three days and nights. It was then this... tendency took root.",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_04_2"
        },
        [90230403] = {
          ContentEN = "In this world, everyone harbours their own fears. I am no exception... You seem surprised. May I ask why?",
          DialogueId = 90230403,
          GUID = "E1E1E17E",
          NextDialogue = 90230404,
          SpeakNpcId = 84102,
          Subtitle = "In this world, everyone harbours their own fears. I am no exception... You seem surprised. May I ask why?",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_04_3"
        },
        [90230404] = {
          ContentEN = "I just thought... you don't seem like someone who has fears or weaknesses.",
          DialogueId = 90230404,
          GUID = "E1E1E1A8",
          NextDialogue = 90230405,
          SpeakNpcId = 100001,
          Subtitle = "I just thought... you don't seem like someone who has fears or weaknesses."
        },
        [90230405] = {
          ContentEN = "Heh... Correct. Weakness can be a merchant's undoing.",
          DialogueId = 90230405,
          GUID = "E1E1E1D2",
          NextDialogue = 90230406,
          SpeakNpcId = 84102,
          Subtitle = "Heh... Correct. Weakness can be a merchant's undoing.",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_04_4"
        },
        [90230406] = {
          ContentEN = "I underwent rigorous trainings to suppress this fear. At the negotiating table, I can cast it aside with ease. But in your presence, there's no need for such pretences.",
          DialogueId = 90230406,
          GUID = "E1E1E1FC",
          NextOptions = {
            [1] = 90230002,
            [2] = 90230003
          },
          SpeakNpcId = 84102,
          Subtitle = "I underwent rigorous trainings to suppress this fear. At the negotiating table, I can cast it aside with ease. But in your presence, there's no need for such pretences.",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_04_5",
          bForbidSkipOptions = true
        },
        [90230501] = {
          ContentEN = "Your perfume carries a bold, intoxicating sweetness — unrestrained, unapologetic. A striking contrast to the subtle fragrances of Huaxu. I'm intrigued.",
          DialogueId = 90230501,
          GUID = "E1E1F192",
          SpeakNpcId = 84102,
          Subtitle = "Your perfume carries a bold, intoxicating sweetness — unrestrained, unapologetic. A striking contrast to the subtle fragrances of Huaxu. I'm intrigued.",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_companio_01"
        },
        [90230601] = {
          ContentEN = "I saw a trace of someone I once knew in you... No, I must be mistaken. Pay me no mind.",
          DialogueId = 90230601,
          GUID = "E1E201FA",
          SpeakNpcId = 84102,
          Subtitle = "I saw a trace of someone I once knew in you... No, I must be mistaken. Pay me no mind.",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_companio_03"
        },
        [90240000] = {
          ContentEN = "Bright and roomy — would be a perfect spot for sparring if there weren't so many tables and chairs in the way.",
          DialogueId = 90240000,
          GUID = "E1E80800",
          SpeakNpcId = 81503,
          Subtitle = "Bright and roomy — would be a perfect spot for sparring if there weren't so many tables and chairs in the way.",
          VoiceName = "voice/$Locale$/char/Kezhou/vo_idle"
        },
        [90240001] = {
          ContentEN = "Today's perfect for drinking and singing! Come on, let me finish this glass, and then we'll chase down the sinners who deserve my sword. What? I said the same thing yesterday? Well, every day's a fine day to live like this, don't you think?",
          DialogueId = 90240001,
          GUID = "E1E8082A",
          LookAt = {
            [1] = "81503:n(0)",
            [2] = "0:n(81503)"
          },
          NextOptions = {
            [1] = 902400011,
            [2] = 902400012,
            [3] = 902400013,
            [4] = 902400014
          },
          RandomOptionNum = 3,
          SpeakNpcId = 81503,
          Subtitle = "Today's perfect for drinking and singing! Come on, let me finish this glass, and then we'll chase down the sinners who deserve my sword. What? I said the same thing yesterday? Well, every day's a fine day to live like this, don't you think?",
          VoiceName = "voice/$Locale$/char/Kezhou/vo_welcome",
          bForbidSkipOptions = true
        },
        [90240002] = {
          ContentEN = "Let's talk about something else",
          DialogueId = 90240002,
          GUID = "E1E80854",
          NextDialogue = 90240001,
          Subtitle = "Let's talk about something else"
        },
        [90240003] = {
          ContentEN = "Goodbye",
          DialogueId = 90240003,
          GUID = "E1E8087E",
          Subtitle = "Goodbye"
        },
        [90240101] = {
          ContentEN = "You're into swordplay too? Figured as much — you've got a fine blade there. You must be pretty good with it. Let's have a friendly spar and see what you've got!",
          DialogueId = 90240101,
          GUID = "E1E81892",
          LookAt = {
            [1] = "81503:n(0)",
            [2] = "0:n(81503)"
          },
          NextDialogue = 90240102,
          SpeakNpcId = 81503,
          Subtitle = "You're into swordplay too? Figured as much — you've got a fine blade there. You must be pretty good with it. Let's have a friendly spar and see what you've got!",
          TalkActionId = {
            [1] = "81503:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_01_1"
        },
        [90240102] = {
          ContentEN = "Honestly, it's been ages since I've met anyone truly on par with me. Though, my shifu always said I need more honing because I'm too blunt — and that I should work on my acting.",
          DialogueId = 90240102,
          GUID = "E1E818BC",
          NextDialogue = 90240103,
          SpeakNpcId = 81503,
          Subtitle = "Honestly, it's been ages since I've met anyone truly on par with me. Though, my shifu always said I need more honing because I'm too blunt — and that I should work on my acting.",
          TalkActionId = {
            [1] = "81503:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_01_2"
        },
        [90240103] = {
          ContentEN = "Is acting part of swordsmanship?",
          DialogueId = 90240103,
          GUID = "E1E818E6",
          NextDialogue = 90240104,
          SpeakNpcId = 100001,
          Subtitle = "Is acting part of swordsmanship?"
        },
        [90240104] = {
          ContentEN = "Not exactly how I see it, but he always said that swordsmanship isn't just about skill; it's about strategy. Stuff like \"conceal your strength by feigning weakness,\" \"subdue the enemy without fighting,\" and \"overwhelm the few with the many.\" Said that's what separates the good from the great.",
          DialogueId = 90240104,
          GUID = "E1E81910",
          NextDialogue = 90240105,
          SpeakNpcId = 81503,
          Subtitle = "Not exactly how I see it, but he always said that swordsmanship isn't just about skill; it's about strategy. Stuff like \"conceal your strength by feigning weakness,\" \"subdue the enemy without fighting,\" and \"overwhelm the few with the many.\" Said that's what separates the good from the great.",
          TalkActionId = {
            [1] = "81503:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_01_3"
        },
        [90240105] = {
          ContentEN = "Back when I was a kid, he used to pull that same trick on me. He'd claim his skills were mediocre and tell me if I could knock him down, I wouldn't have to train anymore. Took me a whole year to realize I couldn't even touch his sleeve.",
          DialogueId = 90240105,
          GUID = "E1E8193A",
          NextDialogue = 90240106,
          SpeakNpcId = 81503,
          Subtitle = "Back when I was a kid, he used to pull that same trick on me. He'd claim his skills were mediocre and tell me if I could knock him down, I wouldn't have to train anymore. Took me a whole year to realize I couldn't even touch his sleeve.",
          TalkActionId = {
            [1] = "81503:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_01_4"
        },
        [90240106] = {
          ContentEN = "One day, I was so wiped out I just collapsed. That's when I noticed — not a single drop of sweat beneath his feet. That doddering, clumsy look of his? All an act.",
          DialogueId = 90240106,
          GUID = "E1E81964",
          NextOptions = {
            [1] = 90240002,
            [2] = 90240003
          },
          SpeakNpcId = 81503,
          Subtitle = "One day, I was so wiped out I just collapsed. That's when I noticed — not a single drop of sweat beneath his feet. That doddering, clumsy look of his? All an act.",
          TalkActionId = {
            [1] = "81503:Talk03_End"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_01_5",
          bForbidSkipOptions = true
        },
        [90240201] = {
          ContentEN = "Plenty of reasons, really, but if I had to sum it up: I hate being bound by them.",
          DialogueId = 90240201,
          GUID = "E1E828FA",
          LookAt = {
            [1] = "81503:n(0)",
            [2] = "0:n(81503)"
          },
          NextDialogue = 90240202,
          SpeakNpcId = 81503,
          Subtitle = "Plenty of reasons, really, but if I had to sum it up: I hate being bound by them.",
          TalkActionId = {
            [1] = "81503:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_02_1"
        },
        [90240202] = {
          ContentEN = "I've been free-spirited all my life, doing everything my way, drawing my sword wherever I saw injustice. I only ever listened to what I wanted to hear from my Shifu or Yuming. The rest? In one ear and out the other, like the wind passing by. So tell me, why would I let myself be chained by some laws?",
          DialogueId = 90240202,
          GUID = "E1E82924",
          NextDialogue = 90240203,
          SpeakNpcId = 81503,
          Subtitle = "I've been free-spirited all my life, doing everything my way, drawing my sword wherever I saw injustice. I only ever listened to what I wanted to hear from my Shifu or Yuming. The rest? In one ear and out the other, like the wind passing by. So tell me, why would I let myself be chained by some laws?",
          TalkActionId = {
            [1] = "81503:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_02_2"
        },
        [90240203] = {
          ContentEN = "Tell me the biggest reason then.",
          DialogueId = 90240203,
          GUID = "E1E8294E",
          NextDialogue = 90240204,
          SpeakNpcId = 100001,
          Subtitle = "Tell me the biggest reason then."
        },
        [90240204] = {
          ContentEN = "I'd say it's the concern of a swordsman. Think of it this way — when you first learn swordsmanship, you follow the swordplay scroll move by move, right? Against regular foes, that's enough. Your sword moves instinctively.",
          DialogueId = 90240204,
          GUID = "E1E82978",
          NextDialogue = 90240205,
          SpeakNpcId = 81503,
          Subtitle = "I'd say it's the concern of a swordsman. Think of it this way — when you first learn swordsmanship, you follow the swordplay scroll move by move, right? Against regular foes, that's enough. Your sword moves instinctively.",
          TalkActionId = {
            [1] = "81503:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_02_3"
        },
        [90240205] = {
          ContentEN = "But if you stick too closely to the scroll and can't think on your feet, your sword's no better than a lump of scrap — dull, clumsy, useless. Face something unexpected, and you'll flail around like a headless chicken.",
          DialogueId = 90240205,
          GUID = "E1E829A2",
          NextDialogue = 90240206,
          SpeakNpcId = 81503,
          Subtitle = "But if you stick too closely to the scroll and can't think on your feet, your sword's no better than a lump of scrap — dull, clumsy, useless. Face something unexpected, and you'll flail around like a headless chicken.",
          TalkActionId = {
            [1] = "81503:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_02_4"
        },
        [90240206] = {
          ContentEN = "To me, Huaxu is like a clumsy swordsman glued to their Nine Chapters of Dafeng. They can't even deal with a Drifter like me — what chance do they have against a true threat? It's only a matter of time before they fall.",
          DialogueId = 90240206,
          GUID = "E1E829CC",
          NextOptions = {
            [1] = 90240002,
            [2] = 90240003
          },
          SpeakNpcId = 81503,
          Subtitle = "To me, Huaxu is like a clumsy swordsman glued to their Nine Chapters of Dafeng. They can't even deal with a Drifter like me — what chance do they have against a true threat? It's only a matter of time before they fall.",
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_02_5",
          bForbidSkipOptions = true
        },
        [90240301] = {
          ContentEN = "Of course! Being good with a sword doesn't mean you're stuck using only it. In Huaxu, there are people who can use pens and chopsticks as weapons — does that mean swordsmen are supposed to starve or never write?",
          DialogueId = 90240301,
          GUID = "E1E83962",
          LookAt = {
            [1] = "81503:n(0)",
            [2] = "0:n(81503)"
          },
          NextDialogue = 90240302,
          SpeakNpcId = 81503,
          Subtitle = "Of course! Being good with a sword doesn't mean you're stuck using only it. In Huaxu, there are people who can use pens and chopsticks as weapons — does that mean swordsmen are supposed to starve or never write?",
          TalkActionId = {
            [1] = "81503:Agree"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_03_1"
        },
        [90240302] = {
          ContentEN = "That's disappointing. I was hoping you could do stuff like slicing a bullet in half with your sword.",
          DialogueId = 90240302,
          GUID = "E1E8398C",
          NextDialogue = 90240303,
          SpeakNpcId = 100001,
          Subtitle = "That's disappointing. I was hoping you could do stuff like slicing a bullet in half with your sword."
        },
        [90240303] = {
          ContentEN = "Oh, I can do that. But why bother? Dodging is way easier, after all. Even boars in the woods know to go for radishes over tree bark when they can.",
          DialogueId = 90240303,
          GUID = "E1E839B6",
          NextDialogue = 90240304,
          SpeakNpcId = 81503,
          Subtitle = "Oh, I can do that. But why bother? Dodging is way easier, after all. Even boars in the woods know to go for radishes over tree bark when they can.",
          TalkActionId = {
            [1] = "81503:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_03_2"
        },
        [90240304] = {
          ContentEN = "That said, if I ever meet a worthy opponent, you can bet I'll draw my sword and go all out.",
          DialogueId = 90240304,
          GUID = "E1E839E0",
          NextOptions = {
            [1] = 90240002,
            [2] = 90240003
          },
          SpeakNpcId = 81503,
          Subtitle = "That said, if I ever meet a worthy opponent, you can bet I'll draw my sword and go all out.",
          TalkActionId = {
            [1] = "81503:Talk02_End"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_03_3",
          bForbidSkipOptions = true
        },
        [90240401] = {
          ContentEN = "They sure do. Now that you mention it, I can think of quite a few. Stuff like \"King So-and-So,\" \"Lord Something,\" or \"Immortal This-and-That.\" Animals are the go-to — dragons, tigers, lions, cranes, you name it. It's like a whole zoo out there.",
          DialogueId = 90240401,
          GUID = "E1E849CA",
          LookAt = {
            [1] = "81503:n(0)",
            [2] = "0:n(81503)"
          },
          NextDialogue = 90240402,
          SpeakNpcId = 81503,
          Subtitle = "They sure do. Now that you mention it, I can think of quite a few. Stuff like \"King So-and-So,\" \"Lord Something,\" or \"Immortal This-and-That.\" Animals are the go-to — dragons, tigers, lions, cranes, you name it. It's like a whole zoo out there.",
          TalkActionId = {
            [1] = "81503:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_04_1"
        },
        [90240402] = {
          ContentEN = "Here's how it works: the longer the title, the lousier the skills. Four words? A newbie. Three? Not bad. Two — that's someone you don't want to mess with. And those with no nickname at all? They're the true grandmasters.",
          DialogueId = 90240402,
          GUID = "E1E849F4",
          NextDialogue = 90240403,
          SpeakNpcId = 81503,
          Subtitle = "Here's how it works: the longer the title, the lousier the skills. Four words? A newbie. Three? Not bad. Two — that's someone you don't want to mess with. And those with no nickname at all? They're the true grandmasters.",
          TalkActionId = {
            [1] = "81503:Angry01_End"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_04_2"
        },
        [90240403] = {
          ContentEN = "So is Kezhou your real name or a nickname?",
          DialogueId = 90240403,
          GUID = "E1E84A1E",
          NextDialogue = 90240404,
          SpeakNpcId = 100001,
          Subtitle = "So is Kezhou your real name or a nickname?"
        },
        [90240404] = {
          ContentEN = "I walk this world with my real name, of course. I know, it sounds made-up, doesn't it? Even my shifu used to say so — warned me that a name like this would have people mistaking me for some prodigy, and that'd only bring me trouble.",
          DialogueId = 90240404,
          GUID = "E1E84A48",
          NextDialogue = 90240405,
          SpeakNpcId = 81503,
          Subtitle = "I walk this world with my real name, of course. I know, it sounds made-up, doesn't it? Even my shifu used to say so — warned me that a name like this would have people mistaking me for some prodigy, and that'd only bring me trouble.",
          TalkActionId = {
            [1] = "81503:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_04_3"
        },
        [90240405] = {
          ContentEN = "But it's the name my old man gave me. Maybe he hoped I'd grow up to be some kind of hero. He didn't leave much behind, but carrying this name feels like his sword still leaves its mark on the world.",
          DialogueId = 90240405,
          GUID = "E1E84A72",
          NextOptions = {
            [1] = 90240002,
            [2] = 90240003
          },
          SpeakNpcId = 81503,
          Subtitle = "But it's the name my old man gave me. Maybe he hoped I'd grow up to be some kind of hero. He didn't leave much behind, but carrying this name feels like his sword still leaves its mark on the world.",
          TalkActionId = {
            [1] = "81503:Talk01_End"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_04_4",
          bForbidSkipOptions = true
        },
        [90240601] = {
          ContentEN = "I'm holding onto your old sword for now. When you stop moping around with that gloomy face, I'll give it back — but only if you beat me in a duel. Lose, and it's mine for good.",
          DialogueId = 90240601,
          GUID = "E1E86A9A",
          SpeakNpcId = 81503,
          Subtitle = "I'm holding onto your old sword for now. When you stop moping around with that gloomy face, I'll give it back — but only if you beat me in a duel. Lose, and it's mine for good.",
          VoiceName = "voice/$Locale$/char/Kezhou/vo_companio_02"
        },
        [90240701] = {
          ContentEN = "A sword can be a friend, a toy, or even a tool for all sorts of things — cutting, prying, shaving. But it should never be your master. Don't let that blade hold you back.",
          DialogueId = 90240701,
          GUID = "E1E87B02",
          SpeakNpcId = 81503,
