          NextDialogue = 90250103,
          SpeakNpcId = 100001,
          Subtitle = "Why would you call a sword your friend?"
        },
        [90250103] = {
          ContentEN = "In the Church, only those chosen by one of the Seven Relics can become one of the \"Seven Virtues.\" There were loads of strong warriors that day, but I was the only one who could pull Samael free. It chose me, so of course I've got to treat it right!",
          DialogueId = 90250103,
          GUID = "E1EE8186",
          NextDialogue = 90250104,
          SpeakNpcId = 81501,
          Subtitle = "In the Church, only those chosen by one of the Seven Relics can become one of the \"Seven Virtues.\" There were loads of strong warriors that day, but I was the only one who could pull Samael free. It chose me, so of course I've got to treat it right!",
          VoiceName = "voice/$Locale$/char/Baonu/vo_topic_01_2"
        },
        [90250104] = {
          ContentEN = "...Only thing is, ever since then, it hasn't responded to me. Not once... W—Wait — that's top secret! You can't tell anyone, got it!?",
